// Title: libraries_loaded_by_svchost_with_low_occurrence_frequency.toml
// Source: detection-rules::hunting/windows/queries/libraries_loaded_by_svchost_with_low_occurrence_frequency.toml
// Section: EQL Hunt
// Rule Name: Libraries Loaded by svchost with Low Occurrence Frequency
// Author: Elastic
// Description:
// This hunt returns the SHA256 hash and the `dll.path` of unsigned libraries loaded by svchost where the presence of unique path/hash is limited to a unique host. Adversaries may use Windows service DLLs to maintain persistence or run with System privileges.
// Integration: endpoint, windows
// Language: ES|QL
// MITRE ATT&CK: T1543, T1543.003
// UUID: c00f1afe-4f25-4542-8cc9-277b23581121
// Type: hunt

from logs-endpoint.events.library-*
| where @timestamp > NOW() - 7 day
| where host.os.family == "windows" and event.category == "library" and event.action == "load" and
  process.name == "svchost.exe" and (dll.code_signature.trusted == false or dll.code_signature.exists == false) and dll.hash.sha256 like "?*" and
  (dll.Ext.relative_file_creation_time <= 900 or dll.Ext.relative_file_name_modify_time <= 900)
| keep dll.name, dll.path, dll.hash.sha256, host.id
| eval dll_folder = substring(dll.path, 1, length(dll.path) - (length(dll.name) + 1))
 /* paths normalization by removing random patterns */
| eval dll_path = replace(dll_folder, """([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}|ns[a-z][A-Z0-9]{3,4}\.tmp|DX[A-Z0-9]{3,4}\.tmp|7z[A-Z0-9]{3,5}\.tmp|[0-9\.\-\_]{3,})""", "replaced")
| eval dll_path = replace(dll_path, """[cC]:\\[uU][sS][eE][rR][sS]\\[a-zA-Z0-9\.\-\_\$~]+\\""", "C:\\\\users\\\\user\\\\")
| eval dll_path = replace(dll_path, """SoftwareDistribution\\Download\\[a-z0-9]+""", """SoftwareDistribution\\Download\\""")
| stats hosts = count_distinct(host.id), count_dlls_per_folder = count(dll_path) by dll_path, dll.name, dll.hash.sha256
| where hosts == 1 and count_dlls_per_folder == 1

from logs-windows.sysmon_operational-*
| where @timestamp > NOW() - 7 day
| where host.os.family == "windows" and event.category == "process" and event.action == "Image loaded" and
  process.name == "svchost.exe" and file.code_signature.status != "Valid" and file.hash.sha256 like "?*"
| keep file.name, file.path, file.hash.sha256, host.id
| eval dll_folder = substring(file.path, 1, length(file.path) - (length(file.name) + 1))
/* paths normalization by removing random patterns */
| eval dll_path = replace(dll_folder, """([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}|ns[a-z][A-Z0-9]{3,4}\.tmp|DX[A-Z0-9]{3,4}\.tmp|7z[A-Z0-9]{3,5}\.tmp|[0-9\.\-\_]{3,})""", "replaced")
| eval dll_path = replace(dll_path, """[cC]:\\[uU][sS][eE][rR][sS]\\[a-zA-Z0-9\.\-\_\$~]+\\""", "C:\\\\users\\\\user\\\\")
| eval dll_path = replace(dll_path, """SoftwareDistribution\\Download\\[a-z0-9]+""", """SoftwareDistribution\\Download\\""")
| stats hosts = count_distinct(host.id), count_dlls_per_folder = count(dll_path) by dll_path, file.name, file.hash.sha256
| where hosts == 1 and count_dlls_per_folder == 1

// Title: microsoft_office_child_processes_with_low_occurrence_frequency.toml
// Source: detection-rules::hunting/windows/queries/microsoft_office_child_processes_with_low_occurrence_frequency.toml
// Section: EQL Hunt
// Rule Name: Microsoft Office Child Processes with Low Occurrence Frequency by Unique Agent
// Author: Elastic
// Description:
// This hunt looks for Microsoft Office child processes with low occurrence frequency. This could be a normal rare behavior as well as potential execution via a malicious document. Adversaries may use Microsoft Office applications to execute malicious code, such as macros, scripts, or other payloads.
// Integration: endpoint, windows, system
// Language: ES|QL
// MITRE ATT&CK: T1566, T1566.001
// UUID: f1b8519a-4dae-475f-965a-f53559233eab
// Type: hunt

from logs-endpoint.events.process-*, logs-windows.sysmon_operational-*, logs-system.security-*
| where host.os.family == "windows" and @timestamp > NOW() - 15 day and
  event.category == "process" and event.action in ("start", "Process creation", "created-process") and
  to_lower(process.parent.name) in ("winword.exe", "excel.exe", "powerpnt.exe") and not starts_with(process.executable, "C:\\Program Files")
// normalize user home profile paths
| eval process_path = replace(to_lower(process.executable), """[c]:\\[u][s][e][r][s]\\[a-zA-Z0-9\.\-\_\$]+\\""", "c:\\\\users\\\\user\\\\")
| stats occurrences = count(*), agents = count_distinct(agent.id) by process_path, process.parent.name
| where occurrences == 1 and agents == 1

// Title: network_discovery_via_sensitive_ports_by_unusual_process.toml
// Source: detection-rules::hunting/windows/queries/network_discovery_via_sensitive_ports_by_unusual_process.toml
// Section: EQL Hunt
// Rule Name: Network Discovery via Sensitive Ports by Unusual Process
// Author: Elastic
// Description:
// This hunt looks for either processes connecting to multiple sensitive TCP ports (SMB, RDP, LDAP, Kerberos and ADWS), a high number of SMB/RDP connections to unique destinations or the same process connecting to both RDP and SMB (should be rare).
// Integration: endpoint, windows
// Language: ES|QL
// MITRE ATT&CK: T1021, T1021.002, T1021.001
// UUID: 386f9cec-bb44-4dd2-8368-45e6fa0a425b
// Type: hunt

from logs-endpoint.events.network-*, logs-windows.sysmon_operational-*
| where @timestamp > now() - 7 day
| where host.os.family == "windows" and event.category == "network" and network.direction == "egress" and
  network.transport == "tcp"and destination.port in (3389, 445, 389, 9389, 88, 5985, 5986, 22) and source.port >= 49152 and
  process.pid != 4
| keep process.executable, destination.port, destination.ip, process.entity_id
 /* network events with SMB or RDP as a target */
| eval smb_dip = case(destination.port == 445, destination.ip, null), rdp_dip = case(destination.port == 389, destination.ip, null)
 /* unique count by destination.port, number of distinct SMB and RDP destinations */
| stats count_unique_ports = count_distinct(destination.port), count_smb_dst =  count_distinct(smb_dip), count_rdp_dst =  count_distinct(rdp_dip) by process.entity_id, process.executable
| where count_unique_ports >= 3 or count_rdp_dst >= 10 or count_smb_dst >= 10 or (count_rdp_dst >= 1 and count_rdp_dst >= 1)

// Title: pe_file_transfer_via_smb_admin_shares_by_agent.toml
// Source: detection-rules::hunting/windows/queries/pe_file_transfer_via_smb_admin_shares_by_agent.toml
// Section: EQL Hunt
// Rule Name: PE File Transfer via SMB_Admin Shares by Agent or User
// Author: Elastic
// Description:
// This hunt looks for a high number of executable file transfers via the SMB protocol by the same user or agent to more than a defined maxium threshold of targets. This could be a sign of lateral movement via the Windows Admin Shares.
// Integration: endpoint
// Language: ES|QL
// MITRE ATT&CK: T1021, T1021.002
// UUID: 814894a4-c951-4f33-ab0b-09354e1cb957
// Type: hunt

from logs-endpoint.events.file-*
| where  @timestamp > now() - 7 day
| where host.os.family == "windows" and event.category == "file" and event.action != "deletion" and process.pid == 4 and
  starts_with(file.Ext.header_bytes, "4d5a*") and (starts_with(user.id, "S-1-5-21-") or starts_with(user.id, "S-1-12-1-"))
| stats agents = count_distinct(host.id), total = count(*) by user.name
| where agents == 1 and total <= 3

from logs-endpoint.events.file-*
| where  @timestamp > now() - 7 day
| where host.os.family == "windows" and event.category == "file" and event.action != "deletion" and process.pid == 4 and
  starts_with(file.Ext.header_bytes, "4d5a*") and (starts_with(user.id, "S-1-5-21-") or starts_with(user.id, "S-1-12-1-"))
| stats agents = count_distinct(host.id), total = count(*) by user.name
 /* threshold set to 10 but can be adjusted to reduce normal baseline in your env */
| where agents >= 10

// Title: persistence_via_run_key_with_low_occurrence_frequency.toml
// Source: detection-rules::hunting/windows/queries/persistence_via_run_key_with_low_occurrence_frequency.toml
// Section: EQL Hunt
// Rule Name: Persistence via Run Key with Low Occurrence Frequency
// Author: Elastic
// Description:
// Leveraging frequency based analysis and random values normalization, this hunt identifies instances where a program adds a persistence entry with rare values or are imited to unique hosts. Run registry key cause programs to run each time that a user logs on and are often abused by adversaries to maintain persistence on an endpoint.
// Integration: endpoint, windows
// Language: ES|QL
// MITRE ATT&CK: T1547, T1547.001
// UUID: df4ee961-254d-4ad1-af15-c65c3b65abcd
// Type: hunt

from logs-endpoint.events.registry-*
| where  @timestamp > NOW() - 7 day
| where host.os.family == "windows" and event.category == "registry" and event.action == "modification" and
  (process.code_signature.exists == false or starts_with(process.code_signature.subject_name, "Microsoft")) and
  ends_with(registry.key,"\\Microsoft\\Windows\\CurrentVersion\\Run") and
  not registry.data.strings rlike """(.{1,2}[c-fC-F]:\\Program Files.+)|([c-fC-F]:\\Program Files.+)|(.{1,2}[c-fC-F]:\\WINDOWS\\System32\\DriverStore\\FileRepository\\.+)"""
| keep registry.key, registry.data.strings, process.name, host.id
 /* Paths normalization in registry.data.strings to ease aggregation */
| eval registry_data = replace(registry.data.strings, """([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}|ns[a-z][A-Z0-9]{3,4}\.tmp|DX[A-Z0-9]{3,4}\.tmp|7z[A-Z0-9]{3,5}\.tmp|[0-9\.\-\_]{3,})""", "")
| eval registry_data = replace(registry_data, """[cC]:\\[uU][sS][eE][rR][sS]\\[a-zA-Z0-9ñ\.\-\_\$~ ]+\\""", "C:\\\\users\\\\user\\\\")
| stats cc = count(*), hosts = count_distinct(host.id) by process.name, registry_data
| where hosts == 1 and cc == 1

from logs-windows.sysmon_operational-*
| where  @timestamp > NOW() - 7 day
| where host.os.family == "windows" and event.category == "registry" and event.action == "RegistryEvent (Value Set)" and
  ends_with(registry.key,"\\Microsoft\\Windows\\CurrentVersion\\Run") and
  not registry.data.strings rlike """(.{1,2}[c-fC-F]:\\Program Files.+)|([c-fC-F]:\\Program Files.+)|(.{1,2}[c-fC-F]:\\WINDOWS\\System32\\DriverStore\\FileRepository\\.+)"""
| keep registry.key, registry.data.strings, process.name, host.id
 /* Paths normalization in registry.data.strings to ease aggregation */
| eval registry_data = replace(registry.data.strings, """([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}|ns[a-z][A-Z0-9]{3,4}\.tmp|DX[A-Z0-9]{3,4}\.tmp|7z[A-Z0-9]{3,5}\.tmp|[0-9\.\-\_]{3,})""", "")
| eval registry_data = replace(registry_data, """[cC]:\\[uU][sS][eE][rR][sS]\\[a-zA-Z0-9ñ\.\-\_\$~ ]+\\""", "C:\\\\users\\\\user\\\\")
| stats cc = count(*), hosts = count_distinct(host.id) by process.name, registry_data
| where hosts == 1 and cc == 1

// Title: persistence_via_startup_with_low_occurrence_frequency.toml
// Source: detection-rules::hunting/windows/queries/persistence_via_startup_with_low_occurrence_frequency.toml
// Section: EQL Hunt
// Rule Name: Persistence via Startup with Low Occurrence Frequency by Unique Host
// Author: Elastic
// Description:
// Leveraging frequency based analysis and path normalization, this hunt identifies rare instances where a program adds a Startup persistence via file creation. Startup entries cause programs to run each time that a user logs on and are often abused by adversaries to maintain persistence on an endpoint.
// Integration: endpoint, windows
// Language: ES|QL
// MITRE ATT&CK: T1547, T1547.001
// UUID: ea950361-33e4-4045-96a5-d36ca28fbc91
// Type: hunt

from logs-endpoint.events.file-*, logs-windows.sysmon_operational-*
| where  @timestamp > now() - 7 day
| where host.os.family == "windows" and event.category == "file" and event.action in ("creation", "FileCreate") and
  file.path rlike """(C:\\Users\\.+\\AppData\\Roaming\\Microsoft\\Windows\\Start Menu\\Programs\\Startup\\.+*|C:\\ProgramData\\Microsoft\\Windows\\Start Menu\\Programs\\StartUp\\.+)"""
| keep process.executable, host.id, file.name
 /* Paths normalization in registry.data.strings to ease aggregation */
| eval process_path = replace(process.executable, """([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}|ns[a-z][A-Z0-9]{3,4}\.tmp|DX[A-Z0-9]{3,4}\.tmp|7z[A-Z0-9]{3,5}\.tmp|[0-9\.\-\_]{3,})""", "")
| eval process_path = replace(process_path, """[cC]:\\[uU][sS][eE][rR][sS]\\[a-zA-Z0-9\.\-\_\$~ ]+\\""", "C:\\\\users\\\\user\\\\")
| stats number_hosts = count_distinct(host.id) by process_path, file.name
| where number_hosts == 1

// Title: potential_exfiltration_by_process_total_egress_bytes.toml
// Source: detection-rules::hunting/windows/queries/potential_exfiltration_by_process_total_egress_bytes.toml
// Section: EQL Hunt
// Rule Name: Egress Network Connections with Total Bytes Greater than Threshold
// Author: Elastic
// Description:
// Using aggregation and the ES|QL `SUM` function, this hunt identifies processes that performed egress connections with total bytes greater or equal to a defined maximum threshold. This may indicate exfiltration or long term command and control activity.
// Integration: endpoint
// Language: ES|QL
// MITRE ATT&CK: T1071
// UUID: 24925575-defd-4581-bfda-a8753dcfb46e
// Type: hunt

from logs-endpoint.events.network-*
| where  @timestamp > now() - 8 hour
| where host.os.family == "windows" and event.category == "network" and
  event.action == "disconnect_received" and
  not CIDR_MATCH(destination.ip, "10.0.0.0/8", "127.0.0.0/8", "169.254.0.0/16", "172.16.0.0/12", "192.0.0.0/24", "192.0.0.0/29", "192.0.0.8/32", "192.0.0.9/32", "192.0.0.10/32", "192.0.0.170/32", "192.0.0.171/32", "192.0.2.0/24", "192.31.196.0/24", "192.52.193.0/24", "192.168.0.0/16", "192.88.99.0/24", "224.0.0.0/4", "100.64.0.0/10", "192.175.48.0/24","198.18.0.0/15", "198.51.100.0/24", "203.0.113.0/24", "240.0.0.0/4", "::1","FE80::/10", "FF00::/8")
| keep source.bytes, destination.address, process.executable, process.entity_id
| stats total_bytes_out = sum(source.bytes) by process.entity_id, destination.address, process.executable
 /* more than 1GB out by same process.pid in 8 hours */
| where total_bytes_out >= 1073741824

// Title: rundll32_execution_aggregated_by_cmdline.toml
// Source: detection-rules::hunting/windows/queries/rundll32_execution_aggregated_by_cmdline.toml
// Section: EQL Hunt
// Rule Name: Rundll32 Execution Aggregated by Command Line
// Author: Elastic
// Description:
// This hunt aggregate Rundll32 execution by normalized `process.command_line` and returns instances that are unique by frequency. Rundll32 is one of the most abused binaries to proxy execution of malicious commands and modules.
// Integration: endpoint, windows, system
// Language: ES|QL
// MITRE ATT&CK: T1127, T1218, T1218.011
// UUID: 44e6adc6-e183-4bfa-b06d-db41669641fa
// Type: hunt

from logs-endpoint.events.process-*, logs-windows.sysmon_operational-*, logs-system.security-*
| where  @timestamp > now() - 7 day
| where host.os.family == "windows" and event.category == "process" and event.action in ("start", "Process creation", "created-process") and
  to_lower(process.name) == "rundll32.exe" and
  not process.command_line rlike """.*(zzzzInvokeManagedCustomActionOutOfProc|GeneralTel.dll,RunInUserCxt|ShOpenVerbApplication|davclnt.dll,DavSetCookie|FileProtocolHandler|EDGEHTML.dll|FirewallControlPanel.dll,ShowNotificationDialog|printui.dll,PrintUIEntryDPIAware|Program Files|SHCreateLocalServerRunDll|ImageView_Fullscreen|StatusMonitorEntryPoint|Control_RunDLL|HotPlugSafeRemovalDriveNotification|AppxDeploymentClient.dll|acproxy.dll,PerformAutochkOperations|CapabilityAccessManagerDoStoreMaintenance|dfshim.dll|display.dll,ShowAdapterSettings|ForceProxyDetectionOnNextRun|PfSvWsSwapAssessmentTask|acmigration.dll,ApplyMigrationShims|LenovoBatteryGaugePackage.dll|-localserver|DriverStore|CnmDxPEntryPoint|DeferredDelete|DeviceProperties_RunDLL|AppxDeploymentClient.dll|spool\\DRIVERS|printui.dll,PrintUIEntry|DfdGetDefaultPolicyAndSMART|cryptext.dll,CryptExt|WininetPlugin.dll|ClearMyTracksByProcess|SusRunTask|OpenURL|CleanupTemporaryState).*"""
| keep process.parent.name, process.command_line, host.id
| eval cmdline = replace(process.command_line, """[cC]:\\[uU][sS][eE][rR][sS]\\[a-zA-Z0-9\.\-\_\$~ ]+\\""", "C:\\\\users\\\\user\\\\")
| eval cmdline = replace(cmdline, """([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}|ns[a-z][A-Z0-9]{3,4}\.tmp|DX[A-Z0-9]{3,4}\.tmp|7z[A-Z0-9]{3,5}\.tmp|[0-9\.\-\_]{3,})""", "")
| stats hosts =count_distinct(host.id), total = count() by cmdline, process.parent.name
| where hosts == 1

// Title: scheduled_task_creation_by_action_via_registry.toml
// Source: detection-rules::hunting/windows/queries/scheduled_task_creation_by_action_via_registry.toml
// Section: EQL Hunt
// Rule Name: Scheduled tasks Creation by Action via Registry
// Author: Elastic
// Description:
// This hunt looks for scheduled tasks creation by action using registry events. Scheduled tasks actions are saved under the TaskCache registry key in base64 encoded blob. Malware often abuse LOLBins to proxy execution or run executables from unusual paths, you can add more patterns to the query.
// Integration: endpoint
// Language: ES|QL
// MITRE ATT&CK: T1053, T1053.005
// UUID: df50f65e-e820-47f4-a039-671611582f51
// Type: hunt

from logs-endpoint.events.registry-*
| where  @timestamp > now() - 7 day
| where host.os.type == "windows" and event.category == "registry" and event.action == "modification" and
  registry.path like """HKLM\\SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\Schedule\\TaskCache\\Tasks\\*Actions*"""
 /* scheduled task actions are saved under the TaskCache registry key in base64 encoded blob */
| eval scheduled_task_action = replace(TO_LOWER(FROM_BASE64(registry.data.bytes)), """\u0000""", "")
 /* commonly abused lolbin set to run as a scheduled task */
| where scheduled_task_action rlike """.*(users\\public\\|\\appdata\\roaming|programdata|powershell.exe|rundll32.exe|regsvr32.exe|mshta.exe|cscript.exe|wscript.exe|cmd.exe|forfiles|msiexec.exe|wmic.exe|msbuild.exe|http|cmstp.exe|msxsl.exe|ie4uinit.exe).*""" and not scheduled_task_action like "localsystem*"
| keep scheduled_task_action, registry.path, agent.id
| stats count_agents = count_distinct(agent.id) by scheduled_task_action
 /* helps reduce result to instances limited to one agent */
| where count_agents == 1

// Title: scheduled_tasks_creation_for_unique_hosts_by_task_command.toml
// Source: detection-rules::hunting/windows/queries/scheduled_tasks_creation_for_unique_hosts_by_task_command.toml
// Section: EQL Hunt
// Rule Name: Scheduled Tasks Creation for Unique Hosts by Task Command
// Author: Elastic
// Description:
// Using aggregation and strings extraction, this hunt identifies instances where a scheduled task is created and set to run a command unique to a specific host. This could be the result of persistence as a Windows Scheduled Task.
// Integration: system
// Language: ES|QL
// MITRE ATT&CK: T1053, T1053.005
// UUID: 44223fd6-8241-4c21-9d54-21201fa15b12
// Type: hunt

from logs-system.security-*
| where  @timestamp > now() - 7 day
| where host.os.family == "windows" and event.code == "4698" and event.action == "scheduled-task-created"
 /* parsing unstructured data from winlog message to extract a scheduled task Exec command */
| grok message "(?<Command><Command>.+</Command>)" | eval Command = replace(Command, "(<Command>|</Command>)", "")
| where Command is not null
 /* normalise task name by removing usersid and uuid string patterns */
| eval TaskName = replace(winlog.event_data.TaskName, """((-S-1-5-.*)|\{[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\})""", "")
 /* normalise task name by removing random patterns in a file path */
| eval Task_Command = replace(Command, """(ns[a-z][A-Z0-9]{3,4}\.tmp|DX[A-Z0-9]{3,4}\.tmp|7z[A-Z0-9]{3,5}\.tmp|[0-9\.\-\_]{3,})""", "")
 /* normalize user home profile path */
| eval Task_Command = replace(Task_Command, """[cC]:\\[uU][sS][eE][rR][sS]\\[a-zA-Z0-9\.\-\_\$~]+\\""", "C:\\\\users\\\\user\\\\")
| where Task_Command like "?*" and not starts_with(Task_Command, "C:\\Program Files") and not starts_with(Task_Command, "\"C:\\Program Files")
| stats tasks_count = count(*), hosts_count = count_distinct(host.id) by Task_Command, TaskName
| where hosts_count == 1

// Title: suspicious_base64_encoded_powershell_commands.toml
// Source: detection-rules::hunting/windows/queries/suspicious_base64_encoded_powershell_commands.toml
// Section: EQL Hunt
// Rule Name: Suspicious Base64 Encoded Powershell Command
// Author: Elastic
// Description:
// This hunt identifies base64 encoded powershell commands in process start events and filters ones with suspicious keywords like downloaders and evasion related commands.
// Integration: endpoint, windows, system
// Language: ES|QL
// MITRE ATT&CK: T1059, T1059.001, T1027, T1027.010
// UUID: 2e583d3c-7ad6-4544-a0db-c685b2066493
// Type: hunt

from logs-endpoint.events.process-*, logs-windows.sysmon_operational-*, logs-system.security-*
| where host.os.type == "windows" and event.category == "process" and event.type == "start" and TO_LOWER(process.name) == "powershell.exe" and process.command_line rlike ".+ -(e|E).*"
| keep agent.id, process.command_line
 /* simplified regex to extract base64 encoded blob */
| grok process.command_line """(?<base64_data>([A-Za-z0-9+/]+={1,2}$|[A-Za-z0-9+/]{100,}))"""
| where base64_data is not null
 /* base64 decode added in 8.14 */
| eval decoded_base64_cmdline = replace(TO_LOWER(FROM_BASE64(base64_data)), """\u0000""", "")
 /* most common suspicious keywords, you can add more patterns here */
| where decoded_base64_cmdline rlike """.*(http|webclient|download|mppreference|sockets|bxor|.replace|reflection|assembly|load|bits|start-proc|iwr|frombase64).*"""
| keep agent.id, process.command_line, decoded_base64_cmdline

// Title: suspicious_dns_txt_record_lookups_by_process.toml
// Source: detection-rules::hunting/windows/queries/suspicious_dns_txt_record_lookups_by_process.toml
// Section: EQL Hunt
// Rule Name: Suspicious DNS TXT Record Lookups by Process
// Author: Elastic
// Description:
// Leveraging aggregation by process executable entities, this hunt identifies identifies a high number of DNS TXT record queries from same process.
// Adversaries may leverage DNS TXT queries to stage malicious content or exfiltrate data.
// Integration: endpoint, windows
// Language: ES|QL
// MITRE ATT&CK: T1071, T1071.004
// UUID: 7a2c8397-d219-47ad-a8e2-93562e568d08
// Type: hunt

from logs-endpoint.events.network-*, logs-windows.sysmon_operational-*
| where host.os.family == "windows" and event.category == "network" and
  event.action in ("lookup_requested", "DNSEvent (DNS query)") and
  (dns.question.type == "TXT" or dns.answers.type == "TXT") and process.executable != "C:\\Windows\\system32\\svchost.exe"
| keep process.executable,  process.entity_id
| stats occurrences = count(*) by process.entity_id, process.executable
 /* threshold can be adjusted to your env */
| where occurrences >= 50

// Title: windows_command_and_scripting_interpreter_from_unusual_parent.toml
// Source: detection-rules::hunting/windows/queries/windows_command_and_scripting_interpreter_from_unusual_parent.toml
// Section: EQL Hunt
// Rule Name: Windows Command and Scripting Interpreter from Unusual Parent Process
// Author: Elastic
// Description:
// This hunt looks for unusual Microsoft native processes spawning `cmd.exe`, `powershell.exe` or `conhost.exe` and limited to a unique host. This could be normal rare behavior as well as an interactive shell activity from an injected parent process to execute system commands.
// Integration: endpoint, windows, system
// Language: ES|QL
// MITRE ATT&CK: T1059, T1059.001, T1059.003
// UUID: aca4877f-d284-4bdb-8e18-b1414d3a7c20
// Type: hunt

from logs-endpoint.events.process-*, logs-windows.sysmon_operational-*, logs-system.security-*
| where  @timestamp > now() - 7 day
| where host.os.family == "windows" and event.category == "process" and event.action in ("start", "Process creation", "created-process") and
  to_lower(process.name) in ("cmd.exe", "powershell.exe", "conhost.exe") and
  (starts_with(to_lower(process.parent.executable), "c:\\windows\\system32") or starts_with(to_lower(process.parent.executable), "c:\\windows\\syswow64"))
| keep process.name, process.parent.name, host.id
| stats hosts = count_distinct(host.id), cc = count(*) by process.parent.name
| where cc <= 10 and hosts == 1

// Title: windows_logon_activity_by_source_ip.toml
// Source: detection-rules::hunting/windows/queries/windows_logon_activity_by_source_ip.toml
// Section: EQL Hunt
// Rule Name: Windows Logon Activity by Source IP
// Author: Elastic
// Description:
// This hunt returns a summary of network logon activity by `source.ip` using Windows event IDs 4624 and 4625. The higher the number of failures, low success and multiple accounts the more suspicious the behavior is.
// Integration: system
// Language: ES|QL
// MITRE ATT&CK: T1110, T1110.001, T1110.003
// UUID: 441fba85-47a9-4f1f-aab4-569bbfdc548b
// Type: hunt

from logs-system.security-*
| where  @timestamp > now() - 7 day
| where host.os.family == "windows" and
  event.category == "authentication" and event.action in ("logon-failed", "logged-in") and winlog.logon.type == "Network" and
  source.ip is not null and
  /* noisy failure status codes often associated to authentication misconfiguration */
  not (event.action == "logon-failed" and winlog.event_data.Status in ("0xC000015B", "0XC000005E", "0XC0000133", "0XC0000192"))
| eval failed = case(event.action == "logon-failed", source.ip, null), success = case(event.action == "logged-in", source.ip, null)
| stats count_failed = count(failed), count_success = count(success), count_user = count_distinct(winlog.event_data.TargetUserName) by source.ip
 /* below threshold should be adjusted to your env logon patterns */
| where count_failed >= 100 and count_success <= 10 and count_user >= 20

// Title: command_and_control_connection_attempt_by_non_ssh_root_session.toml
// Source: detection-rules::rules/_deprecated/command_and_control_connection_attempt_by_non_ssh_root_session.toml
// Section: EQL Rule
// Rule Name: Suspicious Network Connection Attempt by Root
// Author: Elastic
// Description:
// Identifies an outbound network connection attempt followed by a session id change as the root user by the same process
// entity. This particular instantiation of a network connection is abnormal and should be investigated as it may indicate
// a potential reverse shell activity via a privileged process.
// Integration: endpoint
// Language: eql
// UUID: eb6a3790-d52d-11ec-8ce9-f661ea17fbce
// Type: eql

sequence by process.entity_id with maxspan=1m
[network where host.os.type == "linux" and event.type == "start" and event.action == "connection_attempted" and user.id == "0" and
    not process.executable : ("/bin/ssh", "/sbin/ssh", "/usr/lib/systemd/systemd", "/usr/sbin/sshd","/usr/bin/ssh","/usr/bin/sshpass")]
[process where host.os.type == "linux" and event.action == "session_id_change" and user.id == "0" and
    not process.executable : ("/bin/ssh", "/sbin/ssh", "/usr/lib/systemd/systemd", "/usr/sbin/sshd","/usr/bin/ssh","/usr/bin/sshpass")]

// Title: command_and_control_linux_chisel_server_activity.toml
// Source: detection-rules::rules/_deprecated/command_and_control_linux_chisel_server_activity.toml
// Section: EQL Rule
// Rule Name: Deprecated - Potential Protocol Tunneling via Chisel Server
// Author: Elastic
// Description:
// This rule monitors for common command line flags leveraged by the Chisel server utility followed by a received
// connection within a timespan of 1 minute. Chisel is a command-line utility used for creating and managing TCP and UDP
// tunnels, enabling port forwarding and secure communication between machines. Attackers can abuse the Chisel utility to
// establish covert communication channels, bypass network restrictions, and carry out malicious activities by creating
// tunnels that allow unauthorized access to internal systems.
// Integration: endpoint
// Language: eql
// UUID: ac8805f6-1e08-406c-962e-3937057fa86f
// Type: eql

sequence by host.id, process.entity_id with maxspan=1m
  [process where host.os.type == "linux" and event.type == "start" and event.action == "exec" and 
   process.args == "server" and process.args in ("--port", "-p", "--reverse", "--backend", "--socks5") and 
   process.args_count >= 3 and process.parent.name in ("bash", "dash", "ash", "sh", "tcsh", "csh", "zsh", "ksh", "fish")]
  [network where host.os.type == "linux" and event.type == "start" and event.action == "connection_accepted" and 
   destination.ip != null and destination.ip != "127.0.0.1" and destination.ip != "::1" and 
   not process.name : (
     "python*", "php*", "perl", "ruby", "lua*", "openssl", "nc", "netcat", "ncat", "telnet", "awk", "java", "telnet",
     "ftp", "socat", "curl", "wget", "dpkg", "docker", "dockerd", "yum", "apt", "rpm", "dnf", "ssh", "sshd", "hugo")]

// Title: command_and_control_non_standard_http_port.toml
// Source: detection-rules::rules/_deprecated/command_and_control_non_standard_http_port.toml
// Section: EQL Rule
// Rule Name: Deprecated - Potential Non-Standard Port HTTP/HTTPS connection
// Author: Elastic
// Description:
// Identifies potentially malicious processes communicating via a port paring typically not associated with HTTP/HTTPS. For
// example, HTTP over port 8443 or port 440 as opposed to the traditional port 80 , 443. Adversaries may make changes to
// the standard port a protocol uses to bypass filtering or muddle analysis/parsing of network data.
// Integration: endpoint
// Language: eql
// UUID: 62b68eb2-1e47-4da7-85b6-8f478db5b272
// Type: eql

network where process.name : ("http", "https") and destination.port not in (80, 443) and event.action in (
  "connection_attempted", "ipv4_connection_attempt_event", "connection_accepted", "ipv4_connection_accept_event"
) and destination.ip != "127.0.0.1"

// Title: command_and_control_non_standard_ssh_port.toml
// Source: detection-rules::rules/_deprecated/command_and_control_non_standard_ssh_port.toml
// Section: EQL Rule
// Rule Name: Deprecated - Potential Non-Standard Port SSH connection
// Author: Elastic
// Description:
// Identifies potentially malicious processes communicating via a port paring typically not associated with SSH. For
// example, SSH over port 2200 or port 2222 as opposed to the traditional port 22. Adversaries may make changes to the
// standard port a protocol uses to bypass filtering or muddle analysis/parsing of network data.
// Integration: endpoint
// Language: eql
// UUID: bc8ca7e0-92fd-4b7c-b11e-ee0266b8d9c9
// Type: eql

sequence by process.entity_id with maxspan=1m
  [process where event.action == "exec" and process.name in ("ssh", "sshd") and not process.parent.name in (
   "rsync", "pyznap", "git", "ansible-playbook", "scp", "pgbackrest", "git-lfs", "expect", "Sourcetree", "ssh-copy-id",
   "run"
   )
  ]
  [network where process.name:"ssh" and event.action in ("connection_attempted", "connection_accepted") and
   destination.port != 22 and network.transport == "tcp" and not (
     destination.ip == null or destination.ip == "0.0.0.0" or cidrmatch(
       destination.ip, "10.0.0.0/8", "127.0.0.0/8", "169.254.0.0/16", "172.16.0.0/12", "192.0.0.0/24", "192.0.0.0/29",
       "192.0.0.8/32", "192.0.0.9/32", "192.0.0.10/32", "192.0.0.170/32", "192.0.0.171/32", "192.0.2.0/24",
       "192.31.196.0/24", "192.52.193.0/24", "192.168.0.0/16", "192.88.99.0/24", "224.0.0.0/4", "100.64.0.0/10",
       "192.175.48.0/24","198.18.0.0/15", "198.51.100.0/24", "203.0.113.0/24", "240.0.0.0/4", "::1", "FE80::/10",
       "FF00::/8"
     )
   )
  ]

// Title: command_and_control_sunburst_c2_activity_detected.toml
// Source: detection-rules::rules/_deprecated/command_and_control_sunburst_c2_activity_detected.toml
// Section: EQL Rule
// Rule Name: Deprecated - SUNBURST Command and Control Activity
// Author: Elastic
// Description:
// The malware known as SUNBURST targets the SolarWind's Orion business software for command and control. This rule detects
// post-exploitation command and control activity of the SUNBURST backdoor.
// Integration: endpoint
// Language: eql
// UUID: 22599847-5d13-48cb-8872-5796fee8692b
// Type: eql

network where host.os.type == "windows" and event.type == "protocol" and network.protocol == "http" and
  process.name : ("ConfigurationWizard.exe",
                  "NetFlowService.exe",
                  "NetflowDatabaseMaintenance.exe",
                  "SolarWinds.Administration.exe",
                  "SolarWinds.BusinessLayerHost.exe",
                  "SolarWinds.BusinessLayerHostx64.exe",
                  "SolarWinds.Collector.Service.exe",
                  "SolarwindsDiagnostics.exe") and
  (
    (
      (http.request.body.content : "*/swip/Upload.ashx*" and http.request.body.content : ("POST*", "PUT*")) or
      (http.request.body.content : ("*/swip/SystemDescription*", "*/swip/Events*") and http.request.body.content : ("GET*", "HEAD*"))
    ) and
    not http.request.body.content : "*solarwinds.com*"
  )

// Title: credential_access_entra_signin_brute_force_microsoft_365_repeat_source.toml
// Source: detection-rules::rules/_deprecated/credential_access_entra_signin_brute_force_microsoft_365_repeat_source.toml
// Section: EQL Rule
// Rule Name: Deprecated - Azure Entra Sign-in Brute Force Microsoft 365 Accounts by Repeat Source
// Author: Elastic
// Description:
// Identifies potential brute-force attempts against Microsoft 365 user accounts by detecting a high number of failed
// interactive or non-interactive login attempts within a 30-minute window from a single source. Attackers may attempt to
// brute force user accounts to gain unauthorized access to Microsoft 365 services via different services such as Exchange,
// SharePoint, or Teams.
// Integration: azure
// Language: esql
// UUID: c6655282-6c79-11ef-bbb5-f661ea17fbcc
// Type: esql

from logs-azure.signinlogs*
| WHERE
  event.dataset == "azure.signinlogs"
  and event.category == "authentication"
  and to_lower(azure.signinlogs.properties.resource_display_name) rlike "(.*)365(.*)"
  and azure.signinlogs.category in ("NonInteractiveUserSignInLogs", "SignInLogs")
  and event.outcome != "success"

  // For tuning, review azure.signinlogs.properties.status.error_code
  // https://learn.microsoft.com/en-us/entra/identity-platform/reference-error-codes

// keep only relevant fields
| keep event.dataset, event.category, azure.signinlogs.properties.resource_display_name, azure.signinlogs.category, event.outcome, azure.signinlogs.properties.user_principal_name, source.ip

// Count the number of unique targets per source IP
| stats
  target_count = count_distinct(azure.signinlogs.properties.user_principal_name) by source.ip

// Filter for at least 10 distinct failed login attempts from a single source
| where target_count >= 10

// Title: credential_access_potential_linux_ssh_bruteforce_root.toml
// Source: detection-rules::rules/_deprecated/credential_access_potential_linux_ssh_bruteforce_root.toml
// Section: EQL Rule
// Rule Name: Potential SSH Brute Force Detected on Privileged Account
// Author: Elastic
// Description:
// Identifies multiple consecutive login failures targeting a root user account from the same source address and within a
// short time interval. Adversaries will often brute force login attempts on privileged accounts with a common or known
// password, in an attempt to gain privileged access to systems.
// Integration: system
// Language: eql
// UUID: a5f0d057-d540-44f5-924d-c6a2ae92f045
// Type: eql

sequence by host.id, source.ip with maxspan=10s
  [authentication where host.os.type == "linux" and event.action  in ("ssh_login", "user_login") and
   event.outcome == "failure" and source.ip != null and source.ip != "0.0.0.0" and
   source.ip != "::" and  user.name : ("*root*" , "*admin*")] with runs=3

// Title: credential_access_potential_successful_linux_ftp_bruteforce.toml
// Source: detection-rules::rules/_deprecated/credential_access_potential_successful_linux_ftp_bruteforce.toml
// Section: EQL Rule
// Rule Name: Deprecated - Potential Successful Linux FTP Brute Force Attack Detected
// Author: Elastic
// Description:
// An FTP (file transfer protocol) brute force attack is a method where an attacker systematically tries different
// combinations of usernames and passwords to gain unauthorized access to an FTP server, and if successful, the impact can
// include unauthorized data access, manipulation, or theft, compromising the security and integrity of the server and
// potentially exposing sensitive information. This rule identifies multiple consecutive authentication failures targeting
// a specific user account from the same source address and within a short time interval, followed by a successful
// authentication.
// Integration: auditd_manager
// Language: eql
// UUID: 66712812-e7f2-4a1d-bbda-dd0b5cf20c5d
// Type: eql

sequence by host.id, auditd.data.addr, related.user with maxspan=5s
  [authentication where host.os.type == "linux" and event.action == "authenticated" and
   auditd.data.terminal == "ftp" and event.outcome == "failure" and auditd.data.addr != null and
   auditd.data.addr != "0.0.0.0" and auditd.data.addr != "::"] with runs=10
  [authentication where host.os.type == "linux" and event.action  == "authenticated" and
   auditd.data.terminal == "ftp" and event.outcome == "success" and auditd.data.addr != null and
   auditd.data.addr != "0.0.0.0" and auditd.data.addr != "::"] | tail 1

// Title: credential_access_potential_successful_linux_rdp_bruteforce.toml
// Source: detection-rules::rules/_deprecated/credential_access_potential_successful_linux_rdp_bruteforce.toml
// Section: EQL Rule
// Rule Name: Deprecated - Potential Successful Linux RDP Brute Force Attack Detected
// Author: Elastic
// Description:
// An RDP (Remote Desktop Protocol) brute force attack involves an attacker repeatedly attempting various username and
// password combinations to gain unauthorized access to a remote computer via RDP, and if successful, the potential impact
// can include unauthorized control over the compromised system, data theft, or the ability to launch further attacks
// within the network, jeopardizing the security and confidentiality of the targeted system and potentially compromising
// the entire network infrastructure. This rule identifies multiple consecutive authentication failures targeting a
// specific user account within a short time interval, followed by a successful authentication.
// Integration: auditd_manager
// Language: eql
// UUID: 521fbe5c-a78d-4b6b-a323-f978b0e4c4c0
// Type: eql

sequence by host.id, related.user with maxspan=5s
  [authentication where host.os.type == "linux" and event.action == "authenticated" and
   auditd.data.terminal : "*rdp*" and event.outcome == "failure"] with runs=10
  [authentication where host.os.type == "linux" and event.action  == "authenticated" and
   auditd.data.terminal : "*rdp*" and event.outcome == "success"] | tail 1

// Title: defense_evasion_code_injection_conhost.toml
// Source: detection-rules::rules/_deprecated/defense_evasion_code_injection_conhost.toml
// Section: EQL Rule
// Rule Name: Suspicious Process from Conhost
// Author: Elastic
// Description:
// Identifies a suspicious Conhost child process which may be an indication of code injection activity.
// Language: eql
// UUID: 28896382-7d4f-4d50-9b72-67091901fd26
// Type: eql

process where event.type in ("start", "process_started") and
  process.parent.name : "conhost.exe" and
  not process.executable : ("?:\\Windows\\splwow64.exe", "?:\\Windows\\System32\\WerFault.exe", "?:\\Windows\\System32\\conhost.exe")

// Title: defense_evasion_hide_encoded_executable_registry.toml
// Source: detection-rules::rules/_deprecated/defense_evasion_hide_encoded_executable_registry.toml
// Section: EQL Rule
// Rule Name: Deprecated - Encoded Executable Stored in the Registry
// Author: Elastic
// Description:
// Identifies registry write modifications to hide an encoded portable executable. This could be indicative of adversary
// defense evasion by avoiding the storing of malicious content directly on disk.
// Integration: endpoint, windows, sentinel_one_cloud_funnel, m365_defender, crowdstrike
// Language: eql
// UUID: 93c1ce76-494c-4f01-8167-35edfb52f7b1
// Type: eql

registry where host.os.type == "windows" and
/* update here with encoding combinations */
 registry.data.strings : "TVqQAAMAAAAEAAAA*"

// Title: defense_evasion_ld_preload_env_variable_process_injection.toml
// Source: detection-rules::rules/_deprecated/defense_evasion_ld_preload_env_variable_process_injection.toml
// Section: EQL Rule
// Rule Name: Deprecated - Potential Process Injection via LD_PRELOAD Environment Variable
// Author: Elastic
// Description:
// This rule detects the execution of a process where the LD_PRELOAD environment variable is set. LD_PRELOAD can be used to
// inject a shared library into a binary at or prior to execution. A threat actor may do this in order to load a malicious
// shared library for the purposes of persistence, privilege escalation, and defense evasion. This activity is not common
// and will potentially indicate malicious or suspicious behavior.
// Integration: endpoint
// Language: eql
// UUID: 4973e46b-a663-41b8-a875-ced16dda2bb0
// Type: eql

process where host.os.type == "linux" and event.action == "exec" and process.env_vars : ("LD_PRELOAD=?*", "LD_LIBRARY_PATH=?*")

// Title: defense_evasion_mshta_making_network_connections.toml
// Source: detection-rules::rules/_deprecated/defense_evasion_mshta_making_network_connections.toml
// Section: EQL Rule
// Rule Name: Network Connection via Mshta
// Author: Elastic
// Description:
// Identifies mshta.exe making a network connection. This may indicate adversarial activity, as mshta.exe is often
// leveraged by adversaries to execute malicious scripts and evade detection.
// Language: eql
// UUID: a4ec1382-4557-452b-89ba-e413b22ed4b8
// Type: eql

/* duplicate of Mshta Making Network Connections - c2d90150-0133-451c-a783-533e736c12d7 */

sequence by process.entity_id
  [process where process.name : "mshta.exe" and event.type == "start"]
  [network where process.name : "mshta.exe"]

// Title: defense_evasion_potential_processherpaderping.toml
// Source: detection-rules::rules/_deprecated/defense_evasion_potential_processherpaderping.toml
// Section: EQL Rule
// Rule Name: Potential Process Herpaderping Attempt
// Author: Elastic
// Description:
// Identifies process execution followed by a file overwrite of an executable by the same parent process. This may indicate
// an evasion attempt to execute malicious code in a stealthy way.
// Integration: endpoint, windows
// Language: eql
// UUID: ccc55af4-9882-4c67-87b4-449a7ae8079c
// Type: eql

sequence with maxspan=5s
   [process where host.os.type == "windows" and event.type == "start" and not process.parent.executable :
      (
         "?:\\Windows\\SoftwareDistribution\\*.exe",
         "?:\\Program Files\\Elastic\\Agent\\data\\*.exe",
         "?:\\Program Files (x86)\\Trend Micro\\*.exe"
      )
   ] by host.id, process.executable, process.parent.entity_id
   [file where host.os.type == "windows" and event.type == "change" and event.action == "overwrite" and file.extension == "exe"] by host.id, file.path, process.entity_id

// Title: defense_evasion_process_termination_followed_by_deletion.toml
// Source: detection-rules::rules/_deprecated/defense_evasion_process_termination_followed_by_deletion.toml
// Section: EQL Rule
// Rule Name: Deprecated - Process Termination followed by Deletion
// Author: Elastic
// Description:
// Identifies a process termination event quickly followed by the deletion of its executable file. Malware tools and other
// non-native files dropped or created on a system by an adversary may leave traces to indicate to what occurred. Removal
// of these files can occur during an intrusion, or as part of a post-intrusion process to minimize the adversary's
// footprint.
// Integration: endpoint
// Language: eql
// UUID: 09443c92-46b3-45a4-8f25-383b028b258d
// Type: eql

sequence by host.id with maxspan=5s
   [process where host.os.type == "windows" and event.type == "end" and
    process.code_signature.trusted != true and
    not process.executable like
             ("C:\\Windows\\SoftwareDistribution\\*.exe",
              "C:\\Windows\\WinSxS\\*.exe",
              "?:\\Windows\\Postillion\\Office\\*.exe") and
    not (
      process.name : "infinst.exe" and process.parent.name: "dxsetup.exe" and
      process.parent.code_signature.subject_name == "NVIDIA Corporation" and
      process.parent.code_signature.status == "trusted"
    )
   ] by process.executable
   [file where host.os.type == "windows" and event.type == "deletion" and file.extension in~ ("exe", "scr", "com") and
    not process.executable like
             ("?:\\Program Files\\*.exe",
              "?:\\Program Files (x86)\\*.exe",
              "?:\\Windows\\System32\\svchost.exe",
              "?:\\Windows\\System32\\drvinst.exe",
              "?:\\Windows\\Postillion\\Office\\*.exe") and
    not file.path like (
          "?:\\Program Files\\*.exe",
          "?:\\Program Files (x86)\\*.exe",
          "?:\\Windows\\Temp\\*\\DismHost.exe",
          "?:\\$WINDOWS.~BT\\Work\\*\\DismHost.exe",
          "?:\\$WinREAgent\\Scratch\\*\\DismHost.exe",
          "?:\\Windows\\tenable_mw_scan_*.exe",
          "?:\\Users\\*\\AppData\\Local\\Temp\\LogiUI\\Pak\\uninstall.exe",
          "?:\\ProgramData\\chocolatey\\*.exe"
    ) and
    not (process.name : "OktaVerifySetup-*.exe" and process.code_signature.subject_name == "Okta, Inc.") and
    not (
      process.executable : "?:\\Windows\\SysWOW64\\config\\systemprofile\\Citrix\\UpdaterBinaries\\CitrixReceiver\\*" and
      process.code_signature.subject_name == "Citrix Systems, Inc." and
      file.path : "?:\\Windows\\SysWOW64\\config\\systemprofile\\Citrix\\UpdaterBinaries\\CitrixReceiver\\*\\bootstrapperhelper.exe"
    )
   ] by file.path

// Title: defense_evasion_rename_esxi_index_file.toml
// Source: detection-rules::rules/_deprecated/defense_evasion_rename_esxi_index_file.toml
// Section: EQL Rule
// Rule Name: Deprecated - Suspicious Renaming of ESXI index.html File
// Author: Elastic
// Description:
// Identifies instances where the "index.html" file within the "/usr/lib/vmware/*" directory is renamed on a Linux system.
// The rule monitors for the "rename" event action associated with this specific file and path, which could indicate
// malicious activity.
// Integration: endpoint
// Language: eql
// UUID: c125e48f-6783-41f0-b100-c3bf1b114d16
// Type: eql

file where host.os.type == "linux" and event.action == "rename" and file.name : "index.html" and
file.Ext.original.path : "/usr/lib/vmware/*"

// Title: defense_evasion_whitespace_padding_in_command_line.toml
// Source: detection-rules::rules/_deprecated/defense_evasion_whitespace_padding_in_command_line.toml
// Section: EQL Rule
// Rule Name: Whitespace Padding in Process Command Line
// Author: Elastic
// Description:
// Identifies process execution events where the command line value contains a long sequence of whitespace characters or
// multiple occurrences of contiguous whitespace. Attackers may attempt to evade signature-based detections by padding
// their malicious command with unnecessary whitespace characters. These observations should be investigated for malicious
// behavior.
// Language: eql
// UUID: e0dacebe-4311-4d50-9387-b17e89c2e7fd
// Type: eql

process where event.type in ("start", "process_started") and
  process.command_line regex ".*[ ]{20,}.*" or

  /* this will match on 3 or more separate occurrences of 3+ contiguous whitespace characters */
  process.command_line regex "([^ ]+[ ]{3,}[^ ]*){3,}.*"

// Title: discovery_file_dir_discovery.toml
// Source: detection-rules::rules/_deprecated/discovery_file_dir_discovery.toml
// Section: EQL Rule
// Rule Name: File and Directory Discovery
// Author: Elastic
// Description:
// Enumeration of files and directories using built-in tools. Adversaries may use the information discovered to plan
// follow-on activity.
// Language: eql
// UUID: 7b08314d-47a0-4b71-ae4e-16544176924f
// Type: eql

sequence by agent.id, user.name with maxspan=1m
[process where event.type in ("start", "process_started") and
  ((process.name : "cmd.exe" or process.pe.original_file_name == "Cmd.Exe") and process.args : "dir") or
    process.name : "tree.com"]
[process where event.type in ("start", "process_started") and
  ((process.name : "cmd.exe" or process.pe.original_file_name == "Cmd.Exe") and process.args : "dir") or
    process.name : "tree.com"]
[process where event.type in ("start", "process_started") and
  ((process.name : "cmd.exe" or process.pe.original_file_name == "Cmd.Exe") and process.args : "dir") or
    process.name : "tree.com"]

// Title: discovery_pspy_process_monitoring_detected.toml
// Source: detection-rules::rules/_deprecated/discovery_pspy_process_monitoring_detected.toml
// Section: EQL Rule
// Rule Name: Deprecated - Potential Pspy Process Monitoring Detected
// Author: Elastic
// Description:
// This rule leverages auditd to monitor for processes scanning different processes within the /proc directory using the
// openat syscall. This is a strong indication for the usage of the pspy utility. Attackers may leverage the pspy process
// monitoring utility to monitor system processes without requiring root permissions, in order to find potential privilege
// escalation vectors.
// Integration: auditd_manager
// Language: eql
// UUID: bdb04043-f0e3-4efa-bdee-7d9d13fa9edc
// Type: eql

sequence by process.pid, host.id with maxspan=5s
  [file where host.os.type == "linux" and auditd.data.syscall == "openat" and file.path == "/proc" and
   auditd.data.a0 : ("ffffffffffffff9c", "ffffff9c") and auditd.data.a2 : ("80000", "88000") and
   not process.name in ("agentbeat", "packetbeat")
  ] with runs=10

// Title: discovery_query_registry_via_reg.toml
// Source: detection-rules::rules/_deprecated/discovery_query_registry_via_reg.toml
// Section: EQL Rule
// Rule Name: Query Registry via reg.exe
// Author: Elastic
// Description:
// Enumeration or discovery of the Windows registry using reg.exe. This information can be used to perform follow-on
// activities.
// Language: eql
// UUID: 68113fdc-3105-4cdd-85bb-e643c416ef0b
// Type: eql

process where event.type in ("start", "process_started") and
  (process.name : "reg.exe" or process.pe.original_file_name == "reg.exe") and
  process.args == "query"

// Title: execution_apt_binary.toml
// Source: detection-rules::rules/_deprecated/execution_apt_binary.toml
// Section: EQL Rule
// Rule Name: Linux Restricted Shell Breakout via  apt/apt-get Changelog Escape
// Author: Elastic
// Description:
// Identifies Linux binary apt/apt-get abuse to breakout out of restricted shells or environments by spawning an
// interactive system shell. The apt utility allows us to manage installation and removal of softwares on Debian based
// Linux distributions and the activity of spawning shell is not a standard use of this binary for a user or system
// administrator. It indicates a potentially malicious actor attempting to improve the capabilities or stability of their
// access.
// Language: eql
// UUID: 8fed8450-847e-43bd-874c-3bbf0cd425f3
// Type: eql

process where event.type == "start" and process.name == "sensible-pager" and
  process.args in ("/bin/sh", "/bin/bash", "/bin/dash", "sh", "bash", "dash") and
  process.parent.name in ("apt", "apt-get") and process.parent.args == "changelog"

// Title: execution_awk_binary_shell.toml
// Source: detection-rules::rules/_deprecated/execution_awk_binary_shell.toml
// Section: EQL Rule
// Rule Name: Linux Restricted Shell Breakout via awk Commands
// Author: Elastic
// Description:
// Identifies Linux binary awk abuse to breakout out of restricted shells or environments by spawning an interactive system
// shell. The awk utility is a text processing language used for data extraction and reporting tools and the activity of
// spawning shell is not a standard use of this binary for a user or system administrator. It indicates a potentially
// malicious actor attempting to improve the capabilities or stability of their access.
// Language: eql
// UUID: 10754992-28c7-4472-be5b-f3770fd04f2d
// Type: eql

process where event.type == "start" and process.name in ("sh", "bash", "dash") and
  process.parent.name in ("nawk", "mawk", "awk", "gawk") and process.parent.args : "BEGIN {system(*)}"

// Title: execution_busybox_binary.toml
// Source: detection-rules::rules/_deprecated/execution_busybox_binary.toml
// Section: EQL Rule
// Rule Name: Linux Restricted Shell Breakout via busybox Shell Evasion
// Author: Elastic
// Description:
// Identifies Linux binary busybox abuse to break out from restricted environments by spawning an interactive system
// shell.The busybox is software utility suite that provides several Unix utilities in a single executable file and the
// activity of spawing a shell is not a standard use of this binary by a user or system administrator. It indicates a
// potentially malicious actor attempting to improve the capabilities or stability of their access.
// Language: eql
// UUID: e9b4a3c7-24fc-49fd-a00f-9c938031eef1
// Type: eql

process where event.type == "start" and process.name == "busybox" and process.args_count == 2 and process.args in ("/bin/sh", "/bin/ash", "sh", "ash")

// Title: execution_c89_c99_binary.toml
// Source: detection-rules::rules/_deprecated/execution_c89_c99_binary.toml
// Section: EQL Rule
// Rule Name: Linux Restricted Shell Breakout via c89/c99 Shell evasion
// Author: Elastic
// Description:
// Identifies Linux binary c89/c99 abuse to break out from restricted environments by spawning an interactive system
// shell.The c89/c99 utility is an interface to the standard C compilation system and the activity of spawing a shell is
// not a standard use of this binary by a user or system administrator. It indicates a potentially malicious actor
// attempting to improve the capabilities or stability of their access.
// Language: eql
// UUID: 1859ce38-6a50-422b-a5e8-636e231ea0cd
// Type: eql

process where event.type == "start" and process.name in ("sh", "dash", "bash") and
  process.parent.name in ("c89","c99") and process.parent.args == "-wrapper" and
  process.parent.args in ("sh,-s", "bash,-s", "dash,-s", "/bin/sh,-s", "/bin/bash,-s", "/bin/dash,-s")

// Title: execution_cpulimit_binary.toml
// Source: detection-rules::rules/_deprecated/execution_cpulimit_binary.toml
// Section: EQL Rule
// Rule Name: Linux Restricted Shell Breakout via cpulimit Shell Evasion
// Author: Elastic
// Description:
// Identifies Linux binary cpulimit abuse to break out from restricted environments by spawning an interactive system
// shell. The cpulimit utility is used to restrict the CPU usage of a process in cases of CPU or system load exceeding the
// defined threshold and the activity of spawning a shell is not a standard use of this binary by a user or system
// administrator. This can potentially indicate a malicious actor attempting to improve the capabilities or stability of
// their access.
// Language: eql
// UUID: 0968cfbd-40f0-4b1c-b7b1-a60736c7b241
// Type: eql

process where event.type == "start" and process.name in ("bash", "sh", "dash") and
  process.parent.name == "cpulimit" and process.parent.args == "-f" and
  process.parent.args in ("/bin/sh", "/bin/bash", "/bin/dash", "sh", "bash", "dash")

// Title: execution_crash_binary.toml
// Source: detection-rules::rules/_deprecated/execution_crash_binary.toml
// Section: EQL Rule
// Rule Name: Linux Restricted Shell Breakout via crash Shell evasion
// Author: Elastic
// Description:
// Identifies Linux binary crash abuse to break out from restricted environments by spawning an interactive system shell.
// The crash utility helps analyze Linux crash dump data or a live system and the activity of spawning a shell is not a
// standard use of this binary by a user or system administrator. It indicates a potentially malicious actor attempting to
// improve the capabilities or stability of their access.
// Language: eql
// UUID: ee619805-54d7-4c56-ba6f-7717282ddd73
// Type: eql

process where event.type == "start" and process.parent.name == "crash" and process.parent.args == "-h" and process.name == "sh"

// Title: execution_curl_cve_2023_38545_heap_overflow.toml
// Source: detection-rules::rules/_deprecated/execution_curl_cve_2023_38545_heap_overflow.toml
// Section: EQL Rule
// Rule Name: Deprecated - Potential curl CVE-2023-38545 Exploitation
// Author: Elastic
// Description:
// Detects potential exploitation of curl CVE-2023-38545 by monitoring for vulnerable command line arguments in conjunction
// with an unusual command line length. A flaw in curl version <= 8.3 makes curl vulnerable to a heap based buffer overflow
// during the SOCKS5 proxy handshake. Upgrade to curl version >= 8.4 to patch this vulnerability. This exploit can be
// executed with and without the use of environment variables. For increased visibility, enable the collection of
// http_proxy, HTTPS_PROXY and ALL_PROXY environment variables based on the instructions provided in the setup guide of
// this rule.
// Integration: endpoint
// Language: eql
// UUID: f41296b4-9975-44d6-9486-514c6f635b2d
// Type: eql

process where host.os.type == "linux" and event.type == "start" and event.action == "exec" and process.name == "curl"
and (
  process.args like ("--socks5-hostname", "--proxy", "--preproxy", "socks5*") or
  process.env_vars like ("http_proxy=socks5h://*", "HTTPS_PROXY=socks5h://*", "ALL_PROXY=socks5h://*")
) and length(process.command_line) > 255 and not (
  process.parent.name in ("cf-agent", "agent-run", "agent-check", "rudder", "agent-inventory", "cf-execd") or
  process.args like "/opt/rudder/*" or
  process.parent.executable like ("/vz/root/*", "/var/rudder/*")
)

// Title: execution_env_binary.toml
// Source: detection-rules::rules/_deprecated/execution_env_binary.toml
// Section: EQL Rule
// Rule Name: Linux Restricted Shell Breakout via env Shell Evasion
// Author: Elastic
// Description:
// Identifies Linux binary env abuse to break out from restricted environments by spawning an interactive system shell. The
// env utility is a shell command for Unix-like operating systems and is used to print a list of environment variables. The
// activity of spawning a shell is not a standard use of this binary for a user or system administrator. It indicates a
// potentially malicious actor attempting to improve the capabilities or stability of their access.
// Language: eql
// UUID: 72d33577-f155-457d-aad3-379f9b750c97
// Type: eql

process where event.type == "start" and process.name : "env" and process.args_count == 2 and process.args : ("/bin/sh", "/bin/bash", "sh", "bash")

// Title: execution_expect_binary.toml
// Source: detection-rules::rules/_deprecated/execution_expect_binary.toml
// Section: EQL Rule
// Rule Name: Linux Restricted Shell Breakout via the expect command
// Author: Elastic
// Description:
// Identifies Linux binary expect command abuse to break out from restricted environments by spawning an interactive system
// shell. The expect utility allows us to automate control of interactive applications such as Telnet, FTP, SSH and others.
// The activity of spawning shell is not a standard use of this binary for a user or system administrator and could
// potentially indicate malicious actor attempting to improve the capabilities or stability of their access.
// Language: eql
// UUID: fd3fc25e-7c7c-4613-8209-97942ac609f6
// Type: eql

process where event.type == "start" and process.name in ("bash", "sh", "dash") and
  process.parent.name == "expect" and process.parent.args == "-c" and
  process.parent.args in ("spawn /bin/sh;interact", "spawn /bin/bash;interact", "spawn /bin/dash;interact", "spawn sh;interact", "spawn bash;interact", "spawn dash;interact")

// Title: execution_find_binary.toml
// Source: detection-rules::rules/_deprecated/execution_find_binary.toml
// Section: EQL Rule
// Rule Name: Linux Restricted Shell Breakout via the find command
// Author: Elastic
// Description:
// Identifies Linux binary find abuse to break out from restricted environments by spawning an interactive system shell.
// The find command in Unix is a command line utility for walking a file hierarchy. The activity of spawning shell is not a
// standard use of this binary for a user or system administrator. It indicates a potentially malicious actor attempting to
// improve the capabilities or stability of their access.
// Language: eql
// UUID: 6f683345-bb10-47a7-86a7-71e9c24fb358
// Type: eql

process where event.type == "start" and process.name in ("bash", "sh") and
  process.parent.name == "find" and process.parent.args == "-exec" and
  process.parent.args == ";" and process.parent.args in ("/bin/bash", "/bin/sh", "bash", "sh")

// Title: execution_flock_binary.toml
// Source: detection-rules::rules/_deprecated/execution_flock_binary.toml
// Section: EQL Rule
// Rule Name: Linux Restricted Shell Breakout via flock Shell evasion
// Author: Elastic
// Description:
// Identifies Linux binary flock abuse to break out from restricted environments by spawning an interactive system shell.
// The flock utility allows users to manage advisory file locks in shell scripts or on the command line. The activity of
// spawning a shell is not a standard use of this binary by a user or system administrator. It indicates a potentially
// malicious actor attempting to improve the capabilities or stability of their access.
// Language: eql
// UUID: f52362cd-baf1-4b6d-84be-064efc826461
// Type: eql

process where event.type == "start" and process.parent.name == "flock" and process.parent.args == "-u" and process.parent.args == "/" and process.parent.args in ("/bin/sh", "/bin/bash", "/bin/dash", "sh", "bash", "dash") and process.name in ("bash", "dash", "sh")

// Title: execution_gcc_binary.toml
// Source: detection-rules::rules/_deprecated/execution_gcc_binary.toml
// Section: EQL Rule
// Rule Name: Linux Restricted Shell Breakout via the gcc command
// Author: Elastic
// Description:
// Identifies Linux binary gcc abuse to break out from restricted environments by spawning an interactive system shell. The
// gcc utility is a complier system for various languages and mainly used to compile C and C++ programs. The activity of
// spawning shell is not a standard use of this binary for a user or system administrator. It indicates a potentially
// malicious actor attempting to improve the capabilities or stability of their access.
// Language: eql
// UUID: da986d2c-ffbf-4fd6-af96-a88dbf68f386
// Type: eql

process where event.type == "start" and process.name in ("sh", "dash", "bash")  and
  process.parent.name == "gcc" and process.parent.args == "-wrapper" and
  process.parent.args in ("sh,-s", "bash,-s", "dash,-s", "/bin/sh,-s", "/bin/bash,-s", "/bin/dash,-s")

// Title: execution_mysql_binary.toml
// Source: detection-rules::rules/_deprecated/execution_mysql_binary.toml
// Section: EQL Rule
// Rule Name: Linux Restricted Shell Breakout via the mysql command
// Author: Elastic
// Description:
// Identifies MySQL server abuse to break out from restricted environments by spawning an interactive system shell. The
// MySQL server is an open source relational database management system. The activity of spawning shell is not a standard
// use of this binary for a user or system administrator. It indicates a potentially malicious actor attempting to improve
// the capabilities or stability of their access.
// Language: eql
// UUID: 83b2c6e5-e0b2-42d7-8542-8f3af86a1acb
// Type: eql

process where event.type == "start" and process.name in ("bash", "sh", "dash") and
  process.parent.name == "mysql" and process.parent.args == "-e" and
  process.parent.args : ("\\!*sh", "\\!*bash", "\\!*dash", "\\!*/bin/sh", "\\!*/bin/bash", "\\!*/bin/dash")

// Title: execution_pdf_written_file.toml
// Source: detection-rules::rules/_deprecated/execution_pdf_written_file.toml
// Section: EQL Rule
// Rule Name: Deprecated - Execution of File Written or Modified by PDF Reader
// Author: Elastic
// Description:
// Identifies a suspicious file that was written by a PDF reader application and subsequently executed. These processes are
// often launched via exploitation of PDF applications.
// Integration: endpoint, windows
// Language: eql
// UUID: 1defdd62-cd8d-426e-a246-81a37751bb2b
// Type: eql

sequence with maxspan=2h
  [file where host.os.type == "windows" and event.type != "deletion" and file.extension : "exe" and
     (process.name : "AcroRd32.exe" or
      process.name : "rdrcef.exe" or
      process.name : "FoxitPhantomPDF.exe" or
      process.name : "FoxitReader.exe") and
     not (file.name : "FoxitPhantomPDF.exe" or
          file.name : "FoxitPhantomPDFUpdater.exe" or
          file.name : "FoxitReader.exe" or
          file.name : "FoxitReaderUpdater.exe" or
          file.name : "AcroRd32.exe" or
          file.name : "rdrcef.exe")
  ] by host.id, file.path
  [process where host.os.type == "windows" and event.type == "start"] by host.id, process.executable

// Title: execution_reverse_shell_via_named_pipe.toml
// Source: detection-rules::rules/_deprecated/execution_reverse_shell_via_named_pipe.toml
// Section: EQL Rule
// Rule Name: Reverse Shell Created via Named Pipe
// Author: Elastic
// Description:
// Identifies a reverse shell via the abuse of named pipes on Linux with the help of OpenSSL or Netcat. First in, first out
// (FIFO) files are special files for reading and writing to by Linux processes. For this to work, a named pipe is created
// and passed to a Linux shell where the use of a network connection tool such as Netcat or OpenSSL has been established.
// The stdout and stderr are captured in the named pipe from the network connection and passed back to the shell for
// execution.
// Integration: endpoint
// Language: eql
// UUID: dd7f1524-643e-11ed-9e35-f661ea17fbcd
// Type: eql

sequence by host.id with maxspan = 5s
    [process where host.os.type == "linux" and event.type == "start" and process.executable : ("/usr/bin/mkfifo","/usr/bin/mknod") and process.args:("/tmp/*","$*")]
    [process where host.os.type == "linux" and process.executable : ("/bin/sh","/bin/bash") and process.args:("-i") or
        (process.executable: ("/usr/bin/openssl") and process.args: ("-connect"))]
    [process where host.os.type == "linux" and (process.name:("nc","ncat","netcat","netcat.openbsd","netcat.traditional") or
                    (process.name: "openssl" and process.executable: "/usr/bin/openssl"))]

// Title: execution_shell_evasion_linux_binary.toml
// Source: detection-rules::rules/_deprecated/execution_shell_evasion_linux_binary.toml
// Section: EQL Rule
// Rule Name: Deprecated - Linux Restricted Shell Breakout via Linux Binary(s)
// Author: Elastic
// Description:
// Identifies the abuse of a Linux binary to break out of a restricted shell or environment by spawning an interactive
// system shell. The activity of spawning a shell from a binary is not common behavior for a user or system administrator,
// and may indicate an attempt to evade detection, increase capabilities or enhance the stability of an adversary.
// Integration: endpoint
// Language: eql
// UUID: 52376a86-ee86-4967-97ae-1a05f55816f0
// Type: eql

process where host.os.type == "linux" and event.type == "start" and process.executable != null and
(
  /* launching shell from capsh */
  (process.name == "capsh" and process.args == "--" and not process.parent.executable == "/usr/bin/log4j-cve-2021-44228-hotpatch") or

  /* launching shells from unusual parents or parent+arg combos */
  (process.name in ("bash", "dash", "ash", "sh", "tcsh", "csh", "zsh", "ksh", "fish") and (
    (process.parent.name : "*awk" and process.parent.args : "BEGIN {system(*)}") or
    (process.parent.name == "git" and process.parent.args : ("!*sh", "exec *sh") and not process.name == "ssh" ) or
    (process.parent.name : ("byebug", "ftp", "strace", "zip", "tar") and
    (
      process.parent.args : "BEGIN {system(*)}" or
      (
        (process.parent.args : "exec=*sh" or (process.parent.args : "-I" and process.parent.args : "*sh")) or
        (process.args : "exec=*sh" or (process.args : "-I" and process.args : "*sh"))
        )
      )
    ) or

    /* shells specified in parent args */
    /* nice rule is broken in 8.2 */
    (process.parent.args : "*sh" and
      (
        (process.parent.name == "nice") or
        (process.parent.name == "cpulimit" and process.parent.args == "-f") or
        (process.parent.name == "find" and process.parent.args == "." and process.parent.args == "-exec" and
         process.parent.args == ";" and process.parent.args : "/bin/*sh") or
        (process.parent.name == "flock" and process.parent.args == "-u" and process.parent.args == "/")
      )
    )
  )) or

  /* shells specified in args */
  (process.args : "*sh" and (
    (process.parent.name == "crash" and process.parent.args == "-h") or
    (process.name == "sensible-pager" and process.parent.name in ("apt", "apt-get") and process.parent.args == "changelog")
    /* scope to include more sensible-pager invoked shells with different parent process to reduce noise and remove false positives */

  )) or
  (process.name == "busybox" and event.action == "exec" and process.args_count == 2 and process.args : "*sh" and not
   process.executable : "/var/lib/docker/overlay2/*/merged/bin/busybox" and not (process.parent.args == "init" and
   process.parent.args == "runc") and not process.parent.args in ("ls-remote", "push", "fetch") and not process.parent.name == "mkinitramfs" and
   not process.parent.executable == "/bin/busybox") or
  (process.name == "env" and process.args_count == 2 and process.args : "*sh") or
  (process.parent.name in ("vi", "vim") and process.parent.args == "-c" and process.parent.args : ":!*sh") or
  (process.parent.name in ("c89", "c99", "gcc") and process.parent.args : "*sh,-s" and process.parent.args == "-wrapper") or
  (process.parent.name == "expect" and process.parent.args == "-c" and process.parent.args : "spawn *sh;interact") or
  (process.parent.name == "mysql" and process.parent.args == "-e" and process.parent.args : "\\!*sh") or
  (process.parent.name == "ssh" and process.parent.args == "-o" and process.parent.args : "ProxyCommand=;*sh 0<&2 1>&2")
)

// Title: execution_shell_suspicious_parent_child_revshell_linux.toml
// Source: detection-rules::rules/_deprecated/execution_shell_suspicious_parent_child_revshell_linux.toml
// Section: EQL Rule
// Rule Name: Deprecated - Potential Reverse Shell via Suspicious Parent Process
// Author: Elastic
// Description:
// This detection rule detects the creation of a shell through a suspicious parent child relationship. Any reverse shells
// spawned by the specified utilities that use a forked process to initialize the connection attempt will be captured
// through this rule. Attackers may spawn reverse shells to establish persistence onto a target system.
// Integration: endpoint
// Language: eql
// UUID: 4b1a807a-4e7b-414e-8cea-24bf580f6fc5
// Type: eql

sequence by host.id, process.parent.entity_id with maxspan=1s
[ process where host.os.type == "linux" and event.type == "start" and event.action == "fork" and (
  (process.name : "python*" and process.args == "-c" and not process.args == "/usr/bin/supervisord") or
  (process.name : "php*" and process.args == "-r") or
  (process.name : "perl" and process.args == "-e") or
  (process.name : "ruby" and process.args in ("-e", "-rsocket")) or
  (process.name : "lua*" and process.args == "-e") or
  (process.name : "openssl" and process.args : "-connect") or
  (process.name : ("nc", "ncat", "netcat") and process.args_count >= 3 and not process.args == "-z") or
  (process.name : "telnet" and process.args_count >= 3) or
  (process.name : "awk")) and 
  process.parent.name : ("python*", "php*", "perl", "ruby", "lua*", "openssl", "nc", "netcat", "ncat", "telnet", "awk") ]
[ network where host.os.type == "linux" and event.type == "start" and event.action in ("connection_attempted", "connection_accepted") and 
  process.name : ("python*", "php*", "perl", "ruby", "lua*", "openssl", "nc", "netcat", "ncat", "telnet", "awk") and
  destination.ip != null and destination.ip != "127.0.0.1" and destination.ip != "::1" ]

// Title: execution_ssh_binary.toml
// Source: detection-rules::rules/_deprecated/execution_ssh_binary.toml
// Section: EQL Rule
// Rule Name: Linux Restricted Shell Breakout via the SSH command
// Author: Elastic
// Description:
// Identifies Linux binary SSH abuse to break out from restricted environments by spawning an interactive system shell. The
// SSH protocol is a network protocol that gives users, particularly system administrators, a secure way to access a
// computer over a network. The activity of spawning shell is not a standard use of this binary for a user or system
// administrator. It indicates a potentially malicious actor attempting to improve the capabilities or stability of their
// access.
// Language: eql
// UUID: 97da359b-2b61-4a40-b2e4-8fc48cf7a294
// Type: eql

process where event.type == "start" and process.name : ("bash", "sh", "dash") and
  process.parent.name == "ssh" and process.parent.args == "-o" and
  process.parent.args in ("ProxyCommand=;sh 0<&2 1>&2", "ProxyCommand=;bash 0<&2 1>&2", "ProxyCommand=;dash 0<&2 1>&2", "ProxyCommand=;/bin/sh 0<&2 1>&2", "ProxyCommand=;/bin/bash 0<&2 1>&2", "ProxyCommand=;/bin/dash 0<&2 1>&2")

// Title: execution_vi_binary.toml
// Source: detection-rules::rules/_deprecated/execution_vi_binary.toml
// Section: EQL Rule
// Rule Name: Linux Restricted Shell Breakout via the vi command
// Author: Elastic
// Description:
// Identifies Linux binary find abuse to break out from restricted environments by spawning an interactive system shell.
// The vi/vim editor is the standard text editor in Linux distributions, and the activity of spawning a shell is not a
// standard use of this binary by a user or system administrator. This could potentially indicate a malicious actor
// attempting to improve the capabilities or stability of their access.
// Language: eql
// UUID: 89583d1b-3c2e-4606-8b74-0a9fd2248e88
// Type: eql

process where event.type == "start" and process.parent.name in ("vi", "vim") and process.parent.args == "-c" and process.parent.args in (":!/bin/bash", ":!/bin/sh", ":!bash", ":!sh") and process.name in ("bash", "sh")

// Title: impact_potential_linux_ransomware_file_encryption.toml
// Source: detection-rules::rules/_deprecated/impact_potential_linux_ransomware_file_encryption.toml
// Section: EQL Rule
// Rule Name: Suspicious File Changes Activity Detected
// Author: Elastic
// Description:
// This rule identifies a sequence of 100 file extension rename events within a set of common file paths by the same
// process in a timespan of 1 second. Ransomware is a type of malware that encrypts a victim's files or systems and demands
// payment (usually in cryptocurrency) in exchange for the decryption key. One important indicator of a ransomware attack
// is the mass encryption of the file system, after which a new file extension is added to the file.
// Integration: endpoint
// Language: eql
// UUID: 28738f9f-7427-4d23-bc69-756708b5f624
// Type: eql

sequence by process.entity_id, host.id with maxspan=1s
  [file where host.os.type == "linux" and event.type == "change" and event.action == "rename" and file.extension : "?*" 
   and process.executable : ("./*", "/tmp/*", "/var/tmp/*", "/dev/shm/*", "/var/run/*", "/boot/*", "/srv/*", "/run/*") and
   file.path : (
     "/home/*/Downloads/*", "/home/*/Documents/*", "/root/*", "/bin/*", "/usr/bin/*", "/var/log/*", "/var/lib/log/*",
     "/var/backup/*", "/var/www/*"
   ) and
   not process.name : (
     "dpkg", "yum", "dnf", "rpm", "dockerd", "go", "java", "pip*", "python*", "node", "containerd", "php", "p4d",
     "conda", "chrome", "imap", "cmake", "firefox", "semanage", "semodule", "ansible-galaxy", "fc-cache", "jammy", "git",
     "systemsettings", "vmis-launcher", "bundle", "kudu-tserver", "suldownloader"
    )
   ] with runs=25

// Title: initial_access_cross_site_scripting.toml
// Source: detection-rules::rules/_deprecated/initial_access_cross_site_scripting.toml
// Section: EQL Rule
// Rule Name: Potential Cross Site Scripting (XSS)
// Author: Elastic
// Description:
// Cross-Site Scripting (XSS) is a type of attack in which malicious scripts are injected into trusted websites. In XSS
// attacks, an attacker uses a benign web application to send malicious code, generally in the form of a browser-side
// script. This detection rule identifies the potential malicious executions of such browser-side scripts.
// Integration: apm
// Language: eql
// UUID: 4aa58ac6-4dc0-4d18-b713-f58bf8bd015c
// Type: eql

any where processor.name == "transaction" and
url.fragment : ("<iframe*", "*prompt(*)*", "<script*>", "<svg*>", "*onerror=*", "*javascript*alert*", "*eval*(*)*", "*onclick=*",
"*alert(document.cookie)*", "*alert(document.domain)*","*onresize=*","*onload=*","*onmouseover=*")

// Title: initial_access_ssh_connection_established_inside_a_container.toml
// Source: detection-rules::rules/_deprecated/initial_access_ssh_connection_established_inside_a_container.toml
// Section: EQL Rule
// Rule Name: Deprecated - SSH Connection Established Inside A Running Container
// Author: Elastic
// Description:
// This rule detects an incoming SSH connection established inside a running container. Running an ssh daemon inside a
// container should be avoided and monitored closely if necessary. If an attacker gains valid credentials they can use it
// to gain initial access or establish persistence within a compromised environment.
// Integration: cloud_defend
// Language: eql
// UUID: f5488ac1-099e-4008-a6cb-fb638a0f0828
// Type: eql

process where container.id: "*" and event.type == "start" and

/* use of sshd to enter a container*/
process.entry_leader.entry_meta.type: "sshd"  and

/* process is the initial process run in a container or start of a new session*/
(process.entry_leader.same_as_process== true or process.session_leader.same_as_process== true) and

/* interactive process*/
process.interactive== true

// Title: lateral_movement_malicious_remote_file_creation.toml
// Source: detection-rules::rules/_deprecated/lateral_movement_malicious_remote_file_creation.toml
// Section: EQL Rule
// Rule Name: Malicious Remote File Creation
// Author: Elastic
// Description:
// Malicious remote file creation, which can be an indicator of lateral movement activity.
// Integration: endpoint
// Language: eql
// UUID: 301571f3-b316-4969-8dd0-7917410030d3
// Type: eql

sequence by host.name
[file where event.action == "creation" and process.name : ("System", "scp", "sshd", "smbd", "vsftpd", "sftp-server")]
[file where event.category == "malware" or event.category == "intrusion_detection"
and process.name:("System", "scp", "sshd", "smbd", "vsftpd", "sftp-server")]

// Title: lateral_movement_remote_file_creation_in_sensitive_directory.toml
// Source: detection-rules::rules/_deprecated/lateral_movement_remote_file_creation_in_sensitive_directory.toml
// Section: EQL Rule
// Rule Name: Deprecated - Remote File Creation on a Sensitive Directory
// Author: Elastic
// Description:
// Discovery of files created by a remote host on sensitive directories and folders. Remote file creation in these
// directories could indicate a malicious binary or script trying to compromise the system.
// Integration: endpoint
// Language: eql
// UUID: 2377946d-0f01-4957-8812-6878985f515d
// Type: eql

file where event.action in ("creation", "modification") and
  not user.name:("SYSTEM", "root") and
  process.name in ("System", "scp", "sshd", "smbd", "vsftpd", "sftp-server") and
  (
    file.path : (
        "?:\\Users\\*\\AppData\\Roaming*", "?:\\Program Files*",
        "?:\\Windows\\*", "?:\\Windows\\System\\*",
        "?:\\Windows\\System32\\*", "/etc/*", "/tmp*",
        "/var/tmp*", "/home/*/.*", "/home/.*", "/usr/bin/*",
        "/sbin/*", "/bin/*", "/usr/lib/*", "/usr/sbin/*",
        "/usr/share/*", "/usr/local/*", "/var/lib/dpkg/*",
        "/lib/systemd/*"
    )
)

// Title: lateral_movement_ssh_process_launched_inside_a_container.toml
// Source: detection-rules::rules/_deprecated/lateral_movement_ssh_process_launched_inside_a_container.toml
// Section: EQL Rule
// Rule Name: Deprecated - SSH Process Launched From Inside A Container
// Author: Elastic
// Description:
// This rule detects an SSH or SSHD process executed from inside a container. This includes both the client ssh binary and
// server ssh daemon process. SSH usage inside a container should be avoided and monitored closely when necessary. With
// valid credentials an attacker may move laterally to other containers or to the underlying host through container
// breakout. They may also use valid SSH credentials as a persistence mechanism.
// Integration: cloud_defend
// Language: eql
// UUID: 03a514d9-500e-443e-b6a9-72718c548f6c
// Type: eql

process where container.id: "*" and event.type== "start" and
event.action in ("fork", "exec") and
process.name: ("sshd", "ssh", "autossh")

// Title: lateral_movement_ssh_process_launched_inside_container.toml
// Source: detection-rules::rules/_deprecated/lateral_movement_ssh_process_launched_inside_container.toml
// Section: EQL Rule
// Rule Name: Deprecated - SSH Process Launched From Inside A Container via Elastic Defend
// Author: Elastic
// Description:
// This rule detects an SSH or SSHD process executed from inside a container. This includes both the client ssh binary and
// server ssh daemon process. SSH usage inside a container should be avoided and monitored closely when necessary. With
// valid credentials an attacker may move laterally to other containers or to the underlying host through container
// breakout. They may also use valid SSH credentials as a persistence mechanism.
// Integration: endpoint
// Language: eql
// UUID: 5c50ffa6-07f4-4cce-a1b7-c16928a2ed52
// Type: eql

process where host.os.type == "linux" and event.type == "start" and event.action == "exec" and
process.entry_leader.entry_meta.type == "container" and process.name in ("sshd", "ssh", "autossh")

// Title: persistence_adobe_hijack_persistence.toml
// Source: detection-rules::rules/_deprecated/persistence_adobe_hijack_persistence.toml
// Section: EQL Rule
// Rule Name: Deprecated - Adobe Hijack Persistence
// Author: Elastic
// Description:
// Detects writing executable files that will be automatically launched by Adobe on launch.
// Integration: endpoint, windows, sentinel_one_cloud_funnel, m365_defender, crowdstrike
// Language: eql
// UUID: 2bf78aa2-9c56-48de-b139-f169bf99cf86
// Type: eql

file where host.os.type == "windows" and event.type == "creation" and
  file.path : (
    "?:\\Program Files (x86)\\Adobe\\Acrobat Reader DC\\Reader\\AcroCEF\\RdrCEF.exe",
    "?:\\Program Files\\Adobe\\Acrobat Reader DC\\Reader\\AcroCEF\\RdrCEF.exe",

    /* Crowdstrike specific condition as it uses NT Object paths */
    "\\Device\\HarddiskVolume*\\Program Files (x86)\\Adobe\\Acrobat Reader DC\\Reader\\AcroCEF\\RdrCEF.exe",
    "\\Device\\HarddiskVolume*\\Program Files\\Adobe\\Acrobat Reader DC\\Reader\\AcroCEF\\RdrCEF.exe"
  ) and
  not process.name : ("msiexec.exe", "AdobeARM.exe")

// Title: persistence_creation_modif_launch_deamon_sequence.toml
// Source: detection-rules::rules/_deprecated/persistence_creation_modif_launch_deamon_sequence.toml
// Section: EQL Rule
// Rule Name: Deprecated - LaunchDaemon Creation or Modification and Immediate Loading
// Author: Elastic
// Description:
// Indicates the creation or modification of a launch daemon, which adversaries may use to repeatedly execute malicious
// payloads as part of persistence.
// Integration: endpoint
// Language: eql
// UUID: 9d19ece6-c20e-481a-90c5-ccca596537de
// Type: eql

sequence by host.id with maxspan=1m
 [file where host.os.type == "macos" and event.type != "deletion" and file.path : ("/System/Library/LaunchDaemons/*", "/Library/LaunchDaemons/*")]
 [process where host.os.type == "macos" and event.type in ("start", "process_started") and process.name == "launchctl" and process.args == "load"]

// Title: persistence_creation_of_kernel_module.toml
// Source: detection-rules::rules/_deprecated/persistence_creation_of_kernel_module.toml
// Section: EQL Rule
// Rule Name: Deprecated - Creation of Kernel Module
// Author: Elastic
// Description:
// Identifies activity related to loading kernel modules on Linux via creation of new ko files in the LKM directory.
// Integration: endpoint
// Language: eql
// UUID: 947827c6-9ed6-4dec-903e-c856c86e72f3
// Type: eql

file where host.os.type == "linux" and event.type in ("change", "creation") and file.path : "/lib/modules/*" and
file.extension == "ko" and not process.name : (
  "dpkg", "systemd", "falcon-sensor*", "dnf", "yum", "rpm", "cp"
)

// Title: persistence_etc_file_creation.toml
// Source: detection-rules::rules/_deprecated/persistence_etc_file_creation.toml
// Section: EQL Rule
// Rule Name: Deprecated - Suspicious File Creation in /etc for Persistence
// Author: Elastic
// Description:
// Detects the manual creation of files in specific etc directories, via user root, used by Linux malware to persist and
// elevate privileges on compromised systems. File creation in these directories should not be entirely common and could
// indicate a malicious binary or script installing persistence mechanisms for long term access.
// Integration: endpoint
// Language: eql
// UUID: 1c84dd64-7e6c-4bad-ac73-a5014ee37042
// Type: eql

file where host.os.type == "linux" and event.type in ("creation", "file_create_event") and user.id == "0" and
file.path : ("/etc/ld.so.conf.d/*", "/etc/cron.d/*", "/etc/sudoers.d/*", "/etc/init.d/*", "/etc/systemd/system/*",
"/usr/lib/systemd/system/*") and not (
  (process.name : (
    "chef-client", "ruby", "pacman", "packagekitd", "python*", "platform-python", "dpkg", "yum", "apt", "dnf", "rpm",
    "systemd", "snapd", "dnf-automatic", "yum-cron", "elastic-agent", "dnfdaemon-system", "dockerd", "executor",
    "rhn_check"
    )
  ) or 
  (file.extension in ("swp", "swpx", "tmp"))
)

// Title: persistence_web_server_sus_destination_port.toml
// Source: detection-rules::rules/_deprecated/persistence_web_server_sus_destination_port.toml
// Section: EQL Rule
// Rule Name: Deprecated - Uncommon Destination Port Connection by Web Server
// Author: Elastic
// Description:
// This rule identifies unusual destination port network activity originating from a web server process. The rule is
// designed to detect potential web shell activity or unauthorized communication from a web server process to external
// systems.
// Integration: endpoint
// Language: eql
// UUID: 00546494-5bb0-49d6-9220-5f3b4c12f26a
// Type: eql

network where host.os.type == "linux" and event.type == "start" and event.action == "connection_attempted" and (
  process.name like (
    "apache", "nginx", "apache2", "httpd", "lighttpd", "caddy", "mongrel_rails", "gunicorn",
    "uwsgi", "openresty", "cherokee", "h2o", "resin", "puma", "unicorn", "traefik", "tornado", "hypercorn",
    "daphne", "twistd", "yaws", "webfsd", "httpd.worker", "flask", "rails", "mongrel", "php-fpm*", "php-cgi",
    "php-fcgi", "php-cgi.cagefs", "catalina.sh", "hiawatha", "lswsctrl"
  ) or
  user.name in ("apache", "www-data", "httpd", "nginx", "lighttpd", "tomcat", "tomcat8", "tomcat9") or
  user.id in ("33", "498", "48")
) and
network.direction == "egress" and destination.ip != null and
not destination.port in (80, 443, 8080, 8443, 8000, 8888, 3128, 3306, 5432, 8220, 8082) and
not cidrmatch(destination.ip, "127.0.0.0/8", "::1","FE80::/10", "FF00::/8", "10.0.0.0/8", "169.254.0.0/16", "172.16.0.0/12", "192.0.0.0/24", "192.0.0.0/29", "192.0.0.8/32", "192.0.0.9/32",
"192.0.0.10/32", "192.0.0.170/32", "192.0.0.171/32", "192.0.2.0/24", "192.31.196.0/24", "192.52.193.0/24", "192.168.0.0/16", "192.88.99.0/24",
"224.0.0.0/4", "100.64.0.0/10", "192.175.48.0/24","198.18.0.0/15", "198.51.100.0/24", "203.0.113.0/24", "224.0.0.0/4", "240.0.0.0/4")

// Title: privilege_escalation_cve_2025_41244_vmtoolsd_lpe.toml
// Source: detection-rules::rules/_deprecated/privilege_escalation_cve_2025_41244_vmtoolsd_lpe.toml
// Section: EQL Rule
// Rule Name: Potential CVE-2025-41244 vmtoolsd LPE Exploitation Attempt
// Author: Elastic
// Description:
// This rule looks for processes that behave like an attacker trying to exploit a known vulnerability in VMware tools
// (CVE-2025-41244). The vulnerable behavior involves the VMware tools service or its discovery scripts executing other
// programs to probe their version strings. An attacker can place a malicious program in a writable location (for example
// /tmp) and have the tools execute it with elevated privileges, resulting in local privilege escalation. The rule flags
// launches where vmtoolsd or the service discovery scripts start other child processes.
// Integration: endpoint, auditd_manager, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: c5da2519-160c-4cc9-bf69-b0223e99d0db
// Type: eql

process where host.os.type == "linux" and event.type == "start" and
event.action in ("exec", "exec_event", "start", "executed", "process_started", "ProcessRollup2") and
(
  (
    process.parent.name == "vmtoolsd"
  ) or
  (
    process.parent.name in ("bash", "dash", "sh", "tcsh", "csh", "zsh", "ksh", "fish") and
    ?process.parent.args like ("/*/open-vm-tools/serviceDiscovery/scripts/get-versions.sh")
  )
) and not (
  process.executable == null or
  ?process.parent.args == "--version" or
  process.args like (
    "/etc/vmware-tools/resume-vm-default",
    "/etc/vmware-tools/suspend-vm-default",
    "/sbin/shutdown",
    "/sbin/shutdown*",
    "/etc/vmware-tools/poweroff-vm-default",
    "/etc/vmware-tools/poweroff-vm-default",
    "/bin/touch",
    "/tmp/vmware-administrator_*",
    "/tmp/vmware-root_*",
    "/etc/vmware-tools/scripts/vmware/network",
    "/etc/vmware-tools/poweron-vm-default"
  ) or
  process.executable == "/usr/sbin/unix_chkpwd" or
  ?process.working_directory like ("/var/opt/ds_agent", "/tmp/vmware-root_*/tmpvmware*") or
  process.command_line like ("*/usr/bin/lsb_release*", "*/bin/touch*", "*/tmp/vmware-root_*")
)

// Title: privilege_escalation_krbrelayup_suspicious_logon.toml
// Source: detection-rules::rules/_deprecated/privilege_escalation_krbrelayup_suspicious_logon.toml
// Section: EQL Rule
// Rule Name: Potential Privilege Escalation via Local Kerberos Relay over LDAP
// Author: Elastic
// Description:
// Identifies a suspicious local successful logon event where the Logon Package is Kerberos, the remote address is set to
// localhost, and the target user SID is the built-in local Administrator account. This may indicate an attempt to leverage
// a Kerberos relay attack variant that can be used to elevate privilege locally from a domain joined limited user to local
// System privileges.
// Language: eql
// UUID: 3605a013-6f0c-4f7d-88a5-326f5be262ec
// Type: eql

authentication where

 /* event 4624 need to be logged */
 event.action == "logged-in" and event.outcome == "success" and

 /* authenticate locally via relayed kerberos ticket */
 winlog.event_data.AuthenticationPackageName : "Kerberos" and winlog.logon.type == "Network" and
 source.ip == "127.0.0.1" and source.port > 0 and

 /* Impersonate Administrator user via S4U2Self service ticket */
 winlog.event_data.TargetUserSid : "S-1-5-21-*-500"

// Title: privilege_escalation_linux_uid_int_max_bug.toml
// Source: detection-rules::rules/_deprecated/privilege_escalation_linux_uid_int_max_bug.toml
// Section: EQL Rule
// Rule Name: Deprecated - Potential Privilege Escalation via UID INT_MAX Bug Detected
// Author: Elastic
// Description:
// This rule monitors for the execution of the systemd-run command by a user with a UID that is larger than the maximum
// allowed UID size (INT_MAX). Some older Linux versions were affected by a bug which allows user accounts with a UID
// greater than INT_MAX to escalate privileges by spawning a shell through systemd-run.
// Integration: endpoint, crowdstrike
// Language: eql
// UUID: d55436a8-719c-445f-92c4-c113ff2f9ba5
// Type: eql

process where host.os.type == "linux" and event.type == "start" and
  event.action in ("exec", "exec_event", "ProcessRollup2") and
  process.name == "systemd-run" and process.args == "-t" and process.args_count >= 3 and user.id >= "1000000000"

// Title: privilege_escalation_netcon_via_sudo_binary.toml
// Source: detection-rules::rules/_deprecated/privilege_escalation_netcon_via_sudo_binary.toml
// Section: EQL Rule
// Rule Name: Deprecated - Network Connection via Sudo Binary
// Author: Elastic
// Description:
// Detects network connections initiated by the "sudo" binary. This behavior is uncommon and may occur in instances where
// reverse shell shellcode is injected into a process run with elevated permissions via "sudo". Attackers may attempt to
// inject shellcode into processes running as root, to escalate privileges.
// Integration: endpoint
// Language: eql
// UUID: 30e1e9f2-eb9c-439f-aff6-1e3068e99384
// Type: eql

sequence by host.id, process.entity_id with maxspan=5s
  [process where host.os.type == "linux" and event.type == "start" and event.action == "exec" and process.name == "sudo" and not (
    process.args == "su" or
    process.command_line like ("sudo su*", "sudo ./opt/Limpar_ram.sh", "*BECOME-SUCCESS*")
  )]
  [network where host.os.type == "linux" and event.type == "start" and
  event.action in ("connection_attempted", "ipv4_connection_attempt_event") and process.name == "sudo" and not (
    destination.ip == null or destination.ip == "0.0.0.0" or cidrmatch(
      destination.ip, "10.0.0.0/8", "127.0.0.0/8", "169.254.0.0/16", "172.16.0.0/12", "192.0.0.0/24", "192.0.0.0/29",
      "192.0.0.8/32", "192.0.0.9/32", "192.0.0.10/32", "192.0.0.170/32", "192.0.0.171/32", "192.0.2.0/24",
      "192.31.196.0/24", "192.52.193.0/24", "192.168.0.0/16", "192.88.99.0/24", "224.0.0.0/4", "100.64.0.0/10",
      "192.175.48.0/24","198.18.0.0/15", "198.51.100.0/24", "203.0.113.0/24", "240.0.0.0/4", "::1", "FE80::/10",
      "FF00::/8", "172.31.0.0/16"
    )
  )]

// Title: privilege_escalation_printspooler_malicious_driver_file_changes.toml
// Source: detection-rules::rules/_deprecated/privilege_escalation_printspooler_malicious_driver_file_changes.toml
// Section: EQL Rule
// Rule Name: Potential PrintNightmare File Modification
// Author: Elastic
// Description:
// Detects the creation or modification of a print driver with an unusual file name. This may indicate attempts to exploit
// privilege escalation vulnerabilities related to the Print Spooler service. For more information refer to CVE-2021-34527
// and verify that the impacted system is investigated.
// Language: eql
// UUID: 5e87f165-45c2-4b80-bfa5-52822552c997
// Type: eql

/* This rule is compatible with both Sysmon and Elastic Endpoint */

file where process.name : "spoolsv.exe" and 
 file.name : ("kernelbase.dll", "ntdll.dll", "kernel32.dll", "winhttp.dll", "user32.dll") and
 file.path : "?:\\Windows\\System32\\spool\\drivers\\x64\\3\\*"

// Title: privilege_escalation_printspooler_malicious_registry_modification.toml
// Source: detection-rules::rules/_deprecated/privilege_escalation_printspooler_malicious_registry_modification.toml
// Section: EQL Rule
// Rule Name: Potential PrintNightmare Exploit Registry Modification
// Author: Elastic
// Description:
// Detects attempts to exploit privilege escalation vulnerabilities related to the Print Spooler service. For more
// information refer to CVE-2021-34527 and verify that the impacted system is investigated.
// Language: eql
// UUID: 6506c9fd-229e-4722-8f0f-69be759afd2a
// Type: eql

/* This rule is not compatible with Sysmon due to schema issues */

registry where process.name : "spoolsv.exe" and
  (registry.path : "HKLM\\SYSTEM\\ControlSet*\\Control\\Print\\Environments\\Windows*\\Drivers\\Version-3\\mimikatz*\\Data File" or
  (registry.path : "HKLM\\SYSTEM\\ControlSet*\\Control\\Print\\Environments\\Windows*\\Drivers\\Version-3\\*\\Configuration File" and
   registry.data.strings : ("kernelbase.dll", "ntdll.dll", "kernel32.dll", "winhttp.dll", "user32.dll")))

// Title: command_and_control_curl_wget_spawn_via_nodejs_parent.toml
// Source: detection-rules::rules/cross-platform/command_and_control_curl_wget_spawn_via_nodejs_parent.toml
// Section: EQL Rule
// Rule Name: Curl or Wget Spawned via Node.js
// Author: Elastic
// Description:
// This rule detects when Node.js, directly or via a shell, spawns the curl or wget command. This may indicate
// command and control behavior. Adversaries may use Node.js to download additional tools or payloads onto
// the system.
// Integration: endpoint, windows, system, sentinel_one_cloud_funnel, crowdstrike, auditd_manager
// Language: eql
// UUID: d9af2479-ad13-4471-a312-f586517f1243
// Type: eql

process where event.type == "start" and
event.action in ("exec", "exec_event", "start", "ProcessRollup2", "executed", "process_started") and
process.parent.name in ("node", "bun", "node.exe", "bun.exe") and (
(
  process.name in ("bash", "dash", "sh", "tcsh", "csh", "zsh", "ksh", "fish", "cmd.exe", "bash.exe", "powershell.exe") and
  process.command_line like~ ("*curl*http*", "*wget*http*")
) or 
(
  process.name in ("curl", "wget", "curl.exe", "wget.exe")
)
) and not (
  process.command_line like ("*127.0.0.1*", "*localhost*", "*/home/*/.claude/shell-snapshots/*", "*/root/.claude/shell-snapshots/snapshot*", "*/Users/*/.claude/shell-snapshots/*") or
  process.parent.executable like ("/*/.cursor-server/*node", "/home/*/cursor-agent/*/node") 
)

// Title: command_and_control_genai_process_suspicious_tld_connection.toml
// Source: detection-rules::rules/cross-platform/command_and_control_genai_process_suspicious_tld_connection.toml
// Section: EQL Rule
// Rule Name: GenAI Process Connection to Suspicious Top Level Domain
// Author: Elastic
// Description:
// Detects when GenAI tools connect to domains using suspicious TLDs commonly abused for malware C2 infrastructure. TLDs
// like .top, .xyz, .ml, .cf, .onion are frequently used in phishing and malware campaigns. Legitimate GenAI services use
// well-established domains (.com, .ai, .io), so connections to suspicious TLDs may indicate compromised tools, malicious
// plugins, or AI-generated code connecting to attacker infrastructure.
// Integration: endpoint, windows
// Language: eql
// UUID: a1b2c3d4-e5f6-7890-abcd-ef1234567890
// Type: eql

network where host.os.type in ("macos", "windows") and

  // GenAI processes
  process.name in (
    "ollama.exe", "ollama", "Ollama",
    "textgen.exe", "textgen", "text-generation-webui.exe", "oobabooga.exe",
    "lmstudio.exe", "lmstudio", "LM Studio",
    "claude.exe", "claude", "Claude",
    "cursor.exe", "cursor", "Cursor",
    "copilot.exe", "copilot", "Copilot",
    "codex.exe", "codex",
    "Jan", "jan.exe", "jan",
    "gpt4all.exe", "gpt4all", "GPT4All",
    "gemini-cli.exe", "gemini-cli",
    "genaiscript.exe", "genaiscript",
    "grok.exe", "grok",
    "qwen.exe", "qwen",
    "koboldcpp.exe", "koboldcpp", "KoboldCpp",
    "llama-server", "llama-cli",
    "deno.exe", "deno",
    "npx", "pnpm", "yarn", "bunx"
  ) and

  // Suspicious TLDs 
  (
    // Windows DNS events
    (host.os.type == "windows" and dns.question.name != null and
     dns.question.name regex """.*\.(top|buzz|xyz|rest|ml|cf|gq|ga|onion|monster|cyou|quest|cc|bar|cfd|click|cam|surf|tk|shop|club|icu|pw|ws|online|fun|life|boats|store|hair|skin|motorcycles|christmas|lol|makeup|mom|bond|beauty|biz|live|work|zip|country|accountant|date|party|science|loan|win|men|faith|review|racing|download|host)""") or

    // macOS network events
    (host.os.type == "macos" and destination.domain != null and
     destination.domain regex """.*\.(top|buzz|xyz|rest|ml|cf|gq|ga|onion|monster|cyou|quest|cc|bar|cfd|click|cam|surf|tk|shop|club|icu|pw|ws|online|fun|life|boats|store|hair|skin|motorcycles|christmas|lol|makeup|mom|bond|beauty|biz|live|work|zip|country|accountant|date|party|science|loan|win|men|faith|review|racing|download|host)""")

    // Linux DNS events
    // Revist when available
  )

// Title: command_and_control_google_drive_malicious_file_download.toml
// Source: detection-rules::rules/cross-platform/command_and_control_google_drive_malicious_file_download.toml
// Section: EQL Rule
// Rule Name: Suspicious File Downloaded from Google Drive
// Author: Elastic
// Description:
// Identifies suspicious file download activity from a Google Drive URL. This could indicate an attempt to deliver phishing
// payloads via a trusted webservice.
// Integration: endpoint, system
// Language: eql
// UUID: a8afdce2-0ec1-11ee-b843-f661ea17fbcd
// Type: eql

process where

    /* common browser processes  */
    event.action in ("exec", "fork", "start") and

    process.name : ("Microsoft Edge", "chrome.exe", "Google Chrome", "google-chrome-stable",
                    "google-chrome-beta", "google-chrome", "msedge.exe", "firefox.exe", "brave.exe",
                    "whale.exe", "browser.exe", "dragon.exe", "vivaldi.exe", "opera.exe", "firefox",
                    "powershell.exe", "curl", "curl.exe", "wget", "wget.exe") and

    /* Look for Google Drive download URL with AV flag skipping */
    (process.command_line : "*drive.google.com*" and process.command_line : "*export=download*" and process.command_line : "*confirm=no_antivirus*")

// Title: command_and_control_kubectl_networking_modification.toml
// Source: detection-rules::rules/cross-platform/command_and_control_kubectl_networking_modification.toml
// Section: EQL Rule
// Rule Name: Kubectl Network Configuration Modification
// Author: Elastic
// Description:
// This rule detects potential kubectl network configuration modification activity by monitoring for process events
// where the kubectl command is executed with arguments that suggest an attempt to modify network configurations in
// Kubernetes. This could indicate an adversary trying to manipulate network settings for malicious purposes, such as
// establishing unauthorized access or exfiltrating data.
// Integration: endpoint, crowdstrike, sentinel_one_cloud_funnel, cloud_defend
// Language: eql
// UUID: 877cc04a-3320-411d-bbe9-53266fa5e107
// Type: eql

process where host.os.type in ("linux", "macos") and event.type == "start" and
event.action in ("exec", "exec_event", "start", "ProcessRollup2") and
process.name == "kubectl" and (
  process.args == "port-forward" and process.args like "*:*" or
  process.args in ("proxy", "expose")
) and (
  process.parent.name in ("bash", "dash", "sh", "tcsh", "csh", "zsh", "ksh", "fish") or
  (
    process.parent.executable like (
      "/tmp/*", "/private/tmp/*", "/var/tmp/*", "/private/var/tmp/*", "/dev/shm/*", "/root/*", "/home/*", "/Users/*"
    ) or
    process.parent.name like (".*", "*.sh", "python*")
  )
)

// Title: command_and_control_pan_elastic_defend_c2.toml
// Source: detection-rules::rules/cross-platform/command_and_control_pan_elastic_defend_c2.toml
// Section: EQL Rule
// Rule Name: PANW and Elastic Defend - Command and Control Correlation
// Author: Elastic
// Description:
// This detection correlates Palo Alto Networks (PANW) command and control events with Elastic Defend network events to identify
// the source process performing the network activity.
// Integration: endpoint, panw
// Language: eql
// UUID: da4f56b8-9bc5-4003-a46c-d23616fbc691
// Type: eql

sequence by source.port, source.ip, destination.ip with maxspan=1m
 [network where event.module == "panw" and event.action == "c2_communication"]
 [network where event.module == "endpoint" and event.action in ("disconnect_received", "connection_attempted")]

// Title: command_and_control_socks_fortigate_endpoint.toml
// Source: detection-rules::rules/cross-platform/command_and_control_socks_fortigate_endpoint.toml
// Section: EQL Rule
// Rule Name: FortiGate SOCKS Traffic from an Unusual Process
// Author: Elastic
// Description:
// This detection correlates FortiGate's application control SOCKS events with Elastic Defend network event to identify the
// source process performing SOCKS traffic. Adversaries may use a connection proxy to direct network traffic between systems
// or act as an intermediary for network communications to a command and control server to avoid direct connections to their
// infrastructure.
// Integration: endpoint, fortinet_fortigate
// Language: eql
// UUID: 6926b708-7964-425f-bed8-6e006379df08
// Type: eql

sequence by source.port, source.ip, destination.ip with maxspan=1m
 [network where data_stream.dataset == "fortinet_fortigate.log" and event.action == "signature" and network.application in ("SOCKS4", "SOCKS5")]
 [network where event.module == "endpoint" and event.action in ("disconnect_received", "connection_attempted")]

// Title: command_and_control_suricata_elastic_defend_c2.toml
// Source: detection-rules::rules/cross-platform/command_and_control_suricata_elastic_defend_c2.toml
// Section: EQL Rule
// Rule Name: Suricata and Elastic Defend Network Correlation
// Author: Elastic
// Description:
// This detection correlates Suricata alerts with Elastic Defend network events to identify the source process performing
// the network activity.
// Integration: endpoint, suricata
// Language: eql
// UUID: 9edd000e-cbd1-4d6a-be72-2197b5625a05
// Type: eql

sequence by source.port, source.ip, destination.ip with maxspan=5s
 [network where data_stream.dataset == "suricata.eve" and event.kind == "alert" and
  event.severity != 3 and source.ip != null and destination.ip != null and
  not source.domain : ("*nessusscan*", "SCCMPS*") and
  not rule.name in ("ET INFO SMB2 NT Create AndX Request For a Powershell .ps1 File", "ET SCAN MS Terminal Server Traffic on Non-standard Port")]
 [network where event.module == "endpoint" and event.action in ("disconnect_received", "connection_attempted") and
  not process.executable in ("System", "C:\\Program Files (x86)\\Admin Arsenal\\PDQ Inventory\\PDQInventoryService.exe") and 
  not process.executable : "C:\\Windows\\AdminArsenal\\PDQInventory-Scanner\\service-*\\exec\\PDQInventoryScanner.exe"]

// Title: command_and_control_tunnel_qemu.toml
// Source: detection-rules::rules/cross-platform/command_and_control_tunnel_qemu.toml
// Section: EQL Rule
// Rule Name: Potential Traffic Tunneling using QEMU
// Author: Elastic
// Description:
// Identifies the use of the QEMU hardware emulator to potentially tunnel network traffic between Virtual machines. This
// can be used by attackers to enable routing of network packets that would otherwise not reach their intended destination.
// Integration: endpoint, windows, sentinel_one_cloud_funnel, m365_defender, system, crowdstrike
// Language: eql
// UUID: b29b7652-219f-468b-aa1f-5da7bcc24b03
// Type: eql

process where event.type == "start" and
 process.args : "-netdev" and
 (
  (process.args : "-nographic" and process.command_line : "*connect=*" and process.command_line : "*restrict=off*") or
   process.command_line : "*hostfwd=*"
 )

// Title: command_and_control_tunneling_via_tailscaled.toml
// Source: detection-rules::rules/cross-platform/command_and_control_tunneling_via_tailscaled.toml
// Section: EQL Rule
// Rule Name: Potential Tunneling via Tailscaled
// Author: Elastic
// Description:
// Identifies the use of Tailscaled to potentially tunnel network traffic. This can be used by attackers to enable
// routing of network packets that would otherwise not reach their intended destination, or to bypass network restrictions
// and/or hide traffic from network monitoring.
// Integration: endpoint, windows, sentinel_one_cloud_funnel, m365_defender, system, crowdstrike
// Language: eql
// UUID: 482a5584-4ce4-4838-b806-0839a39b004f
// Type: eql

process where event.type == "start" and
process.name like~ ("tailscaled", "tailscaled.exe") and
process.args like~ ("*--socks5-server*", "*--outbound-http-proxy-listen*")

// Title: credential_access_cookies_chromium_browsers_debugging.toml
// Source: detection-rules::rules/cross-platform/credential_access_cookies_chromium_browsers_debugging.toml
// Section: EQL Rule
// Rule Name: Potential Cookies Theft via Browser Debugging
// Author: Elastic
// Description:
// Identifies the execution of a Chromium based browser with the debugging process argument, which may indicate an attempt
// to steal authentication cookies. An adversary may steal web application or service session cookies and use them to gain
// access web applications or Internet services as an authenticated user without needing credentials.
// Integration: endpoint, windows, system
// Language: eql
// UUID: 027ff9ea-85e7-42e3-99d2-bbb7069e02eb
// Type: eql

process where event.type in ("start", "process_started", "info") and
  process.name in (
             "Microsoft Edge",
             "chrome.exe",
             "Google Chrome",
             "google-chrome-stable",
             "google-chrome-beta",
             "google-chrome",
             "msedge.exe") and
   process.args : ("--remote-debugging-port=*",
                   "--remote-debugging-targets=*",
                   "--remote-debugging-pipe=*") and
   process.args : "--user-data-dir=*" and not process.args:"--remote-debugging-port=0"

// Title: credential_access_forced_authentication_pipes.toml
// Source: detection-rules::rules/cross-platform/credential_access_forced_authentication_pipes.toml
// Section: EQL Rule
// Rule Name: Active Directory Forced Authentication from Linux Host - SMB Named Pipes
// Author: Elastic
// Description:
// Identifies a potential forced authentication using related SMB named pipes. Attackers may attempt to force targets to
// authenticate to a host controlled by them to capture hashes or enable relay attacks.
// Integration: endpoint, system
// Language: eql
// UUID: c24e9a43-f67e-431d-991b-09cdb83b3c0c
// Type: eql

sequence with maxspan=15s
[network where host.os.type == "linux" and event.action == "connection_attempted" and destination.port == 445 and not startswith~(string(destination.ip), string(host.ip))] by host.ip, data_stream.namespace
[file where host.os.type == "windows" and event.code == "5145" and file.name : ("Spoolss", "netdfs", "lsarpc", "lsass", "netlogon", "samr", "efsrpc", "FssagentRpc")] by source.ip, data_stream.namespace

// Title: credential_access_genai_process_sensitive_file_access.toml
// Source: detection-rules::rules/cross-platform/credential_access_genai_process_sensitive_file_access.toml
// Section: EQL Rule
// Rule Name: GenAI Process Accessing Sensitive Files
// Author: Elastic
// Description:
// Detects when GenAI tools access sensitive files such as cloud credentials, SSH keys, browser password databases, or
// shell configurations. Attackers leverage GenAI agents to systematically locate and exfiltrate credentials, API keys, and
// tokens. Access to credential stores (.aws/credentials, .ssh/id_*) suggests harvesting, while writes to shell configs
// (.bashrc, .zshrc) indicate persistence attempts. Note: On linux only creation events are available. Access events are
// not yet implemented.
// Integration: endpoint
// Language: eql
// UUID: c0136397-f82a-45e5-9b9f-a3651d77e21a
// Type: eql

file where event.action in ("open", "creation", "modification") and event.outcome == "success" and

  // GenAI process 
    (
      process.name in~ (
        "ollama.exe", "ollama",
        "textgen.exe", "textgen", "text-generation-webui.exe", "oobabooga.exe",
        "lmstudio.exe", "lmstudio", "LM Studio",
        "claude.exe", "claude",
        "cursor.exe", "cursor",
        "copilot.exe", "copilot",
        "codex.exe", "codex",
        "jan.exe", "jan",
        "gpt4all.exe", "gpt4all",
        "gemini-cli.exe", "gemini-cli", "gemini.exe",
        "genaiscript.exe", "genaiscript",
        "grok.exe", "grok",
        "qwen.exe", "qwen",
        "koboldcpp.exe", "koboldcpp",
        "llama-server", "llama-cli",
        "windsurf.exe", "windsurf",
        "zed.exe", "zed",
        "opencode.exe", "opencode",
        "goose.exe", "goose"
      )
    ) and

  // Sensitive file paths
  (
    // Persistence via Shell configs
    file.name in (".bashrc", ".bash_profile", ".zshrc", ".zshenv", ".zprofile", ".profile", ".bash_logout") or

    // Credentials In Files 
    file.name like~ 
                 ("key?.db", 
                  "logins.json", 
                  "Login Data", 
                  "Local State",
                  "signons.sqlite",
                  "Cookies", 
                  "cookies.sqlite",
                  "Cookies.binarycookies", 
                  "login.keychain-db", 
                  "System.keychain", 
                  "credentials.db", 
                  "credentials", 
                  "access_tokens.db", 
                  "accessTokens.json", 
                  "azureProfile.json",
                  "RDCMan.settings", 
                  "known_hosts", 
                  "KeePass.config.xml", 
                  "Unattended.xml")
  ) and not (
    host.os.type == "windows" and
    file.name like~ "Local State" and
    file.path : (
      "?:\\Users\\*\\AppData\\Roaming\\*\\Local State",
      "?:\\Users\\*\\AppData\\Local\\Packages\\*\\LocalCache\\Roaming\\*\\Local State"
    )
  )

// Title: credential_access_gitleaks_execution.toml
// Source: detection-rules::rules/cross-platform/credential_access_gitleaks_execution.toml
// Section: EQL Rule
// Rule Name: Potential Secret Scanning via Gitleaks
// Author: Elastic
// Description:
// This rule detects the execution of Gitleaks, a tool used to search for high-entropy strings and secrets in code
// repositories, which may indicate an attempt to access credentials.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike, auditd_manager
// Language: eql
// UUID: f92171ed-a4d3-4baa-98f9-4df1652cb11b
// Type: eql

process where event.type == "start" and event.action like ("exec", "exec_event", "start", "ProcessRollup2", "executed", "process_started", "Process Create*") and
process.name : ("gitleaks.exe", "gitleaks")

// Title: credential_access_multi_cloud_cli_token_harvesting.toml
// Source: detection-rules::rules/cross-platform/credential_access_multi_cloud_cli_token_harvesting.toml
// Section: EQL Rule
// Rule Name: Multi-Cloud CLI Token and Credential Access Commands
// Author: Elastic
// Description:
// Correlates process telemetry for shells and major cloud/Kubernetes CLIs when command lines match token or credential
// material access patterns (GCP, Azure, AWS, GitHub, kubectl, DigitalOcean, OCI). Flags hosts where multiple cloud
// targets appear within a five-minute window.
// Integration: endpoint, windows, system
// Language: esql
// UUID: 2b9a3b7a-0891-4a89-abbe-dca753c403cd
// Type: esql

FROM logs-endpoint.events.process-*, logs-system.security-*, logs-windows.sysmon_operational-* METADATA _id, _index, _version
| WHERE event.category == "process" AND KQL(""" event.type : "start" and not event.action : "fork" """)
  AND process.command_line IS NOT NULL 
  AND (
    TO_LOWER(process.name) IN (
      "cmd.exe", "powershell.exe", "pwsh.exe", 
      "sh", "bash", "zsh", "dash", "fish", "ksh",
      "gcloud", "gcloud.cmd", "az", "az.cmd", "azd", "azd.exe",
      "gh", "gh.exe", "aws", "aws.exe",
      "kubectl", "kubectl.exe",
      "doctl", "doctl.exe",
      "oci", "oci.exe"
    ) OR
    TO_LOWER(process.parent.name) IN (
      "cmd.exe", "powershell.exe", "pwsh.exe",
      "sh", "bash", "zsh", "dash", "fish", "ksh", "bun", "bun.exe", 
      "node", "node.exe", "java", "java.exe"
    )
  )
  AND process.command_line RLIKE """.*(config-helper\s.*--format|auth\s+print-access-token|auth\s+print-identity-token|auth\s+application-default\s+print|get-access-token\s.*--output|Get-AzAccessToken|azd\s+auth\s+token|az\s+account\s+get-access-token|gh\s+auth\s+(token|status)|aws\s+sts\s+(get-session-token|get-caller-identity|assume-role)|aws\s+configure\s+(export-credentials|list)|kubectl\s+config\s+view\s.*--raw|kubectl\s+get\s+secret|doctl\s+auth\s+(list|init)|oci\s+session\s+authenticate|oci\s+iam\s.*token).*"""
| EVAL cloud_target = CASE(
    process.command_line RLIKE ".*(gcloud|config-helper|print-access-token|print-identity-token).*", "GCP",
    process.command_line RLIKE ".*(azd auth|az account|Get-AzAccessToken).*", "AZURE",
    process.command_line RLIKE ".*(aws sts|aws configure).*", "AWS",
    process.command_line RLIKE ".*(gh auth).*", "GITHUB",
    process.command_line RLIKE ".*(kubectl config|kubectl get secret).*", "KUBERNETES",
    process.command_line RLIKE ".*(doctl).*", "DIGITALOCEAN",
    process.command_line RLIKE ".*(oci session|oci iam).*", "ORACLE"
  )
| WHERE cloud_target IS NOT NULL // drop unclassified events before aggregation
| STATS
    Esql.cloud_targets = VALUES(cloud_target),
    Esql.unique_clouds = COUNT_DISTINCT(cloud_target),
    Esql.process_command_line_values = VALUES(process.command_line),
    Esql.process_parent_executable_values = VALUES(process.parent.executable),
    Esql.first_seen = MIN(@timestamp),
    Esql.last_seen = MAX(@timestamp),
    Esql.event_count = COUNT(*)
  BY host.name, host.id, user.name
| WHERE Esql.unique_clouds >= 2
| KEEP Esql.*, user.name, host.name, host.id

// Title: credential_access_multi_could_secrets_via_api.toml
// Source: detection-rules::rules/cross-platform/credential_access_multi_could_secrets_via_api.toml
// Section: EQL Rule
// Rule Name: Multiple Cloud Secrets Accessed by Source Address
// Author: Elastic
// Description:
// This rule detects authenticated sessions accessing secret stores across multiple environments from the same source
// address within a short period of time, including cloud providers (AWS, GCP, Azure) and Kubernetes clusters.
// Adversaries with access to compromised credentials or session tokens may attempt to retrieve secrets from services such
// as AWS Secrets Manager, Google Secret Manager, Azure Key Vault, or Kubernetes Secrets in rapid succession to expand
// their access or exfiltrate sensitive information.
// Integration: aws, gcp, azure, kubernetes
// Language: esql
// UUID: 472b4944-d810-43cf-83dc-7d080ae1b8dd
// Type: esql

FROM logs-azure.platformlogs-*, logs-aws.cloudtrail-*, logs-gcp.audit-*, logs-kubernetes.audit_logs-* METADATA _id, _version, _index 
| WHERE 
  ( 
    /* AWS Secrets Manager */ 
    (data_stream.dataset == "aws.cloudtrail" AND event.action == "GetSecretValue") OR 

    // Azure Key Vault (platform logs)
    (data_stream.dataset == "azure.platformlogs" AND event.action IN ("SecretGet", "KeyGet")) or 

    /* Google Secret Manager */ 
    (data_stream.dataset IN ("googlecloud.audit", "gcp.audit") AND 
     event.action IN ("google.cloud.secretmanager.v1.SecretManagerService.AccessSecretVersion", "google.cloud.secretmanager.v1.SecretManagerService.GetSecretRequest")) OR 

    /* Kubernetes Secrets */
    (data_stream.dataset == "kubernetes.audit_logs" AND kubernetes.audit.objectRef.resource == "secrets" AND kubernetes.audit.verb IN ("get", "list"))

   ) AND source.ip IS NOT NULL

// Cloud vendor label based on dataset
| EVAL Esql.cloud_vendor = CASE(
    data_stream.dataset == "aws.cloudtrail", "aws",
    data_stream.dataset == "azure.platformlogs", "azure",
    data_stream.dataset IN ("googlecloud.audit","gcp.audit"), "gcp",
    data_stream.dataset == "kubernetes.audit_logs", "k8s",
    "unknown"
  )
// Vendor+tenant label, e.g. aws:123456789012, azure:tenant, gcp:project
| EVAL Esql.tenant_label = CASE(
    Esql.cloud_vendor == "aws", CONCAT("aws:", cloud.account.id),
    Esql.cloud_vendor == "azure", CONCAT("azure:", cloud.account.id),
    Esql.cloud_vendor == "gcp", CONCAT("gcp:", cloud.account.id),
    Esql.cloud_vendor == "k8s", CONCAT("k8s:", orchestrator.cluster.name),
    "unknown"
  )
| WHERE Esql.cloud_vendor != "unknown"
| STATS
    // Core counts
    Esql.events_count = COUNT(*),
    Esql.vendor_count_distinct = COUNT_DISTINCT(Esql.cloud_vendor),
    // Action & data source context
    Esql.event_action_values = VALUES(event.action),
    Esql.data_source_values = VALUES(data_stream.dataset),
    // Cloud vendor + tenant context
    Esql.cloud_vendor_values = VALUES(Esql.cloud_vendor),
    Esql.tenant_label_values = VALUES(Esql.tenant_label),
    // Hyperscaler-specific IDs
    Esql.aws_account_id_values = VALUES(CASE(Esql.cloud_vendor == "aws", cloud.account.id, "unknown")),
    Esql.azure_tenant_id_values = VALUES(CASE(Esql.cloud_vendor == "azure", cloud.account.id, "unknown")),
    Esql.gcp_project_id_values = VALUES(CASE(Esql.cloud_vendor == "gcp", cloud.account.id, "unknown")),
    // Generic cloud metadata
    Esql.cloud_region_values = VALUES(cloud.region),
    Esql.k8s_namespace_values = VALUES(kubernetes.audit.objectRef.namespace),
    // Namespace values
    Esql.data_stream_namespace_values = VALUES(data_stream.namespace), 
    Esql_priv.user_name_values = VALUES(user.name)
  BY source.ip
// Require multi-vendor cred-access from same source IP
| WHERE Esql.vendor_count_distinct >= 2
| SORT Esql.events_count DESC
| KEEP Esql.*, Esql_priv.*, source.ip

// Title: credential_access_suspicious_instance_metadata_service_api_cli.toml
// Source: detection-rules::rules/cross-platform/credential_access_suspicious_instance_metadata_service_api_cli.toml
// Section: EQL Rule
// Rule Name: Suspicious Instance Metadata Service (IMDS) API Command Line Execution
// Author: Elastic
// Description:
// This rule identifies various tools/scripts performing command line execution attempting to access the cloud service
// provider's instance metadata service (IMDS) API endpoint, which can be used to retrieve sensitive instance-specific
// information such as instance ID, public IP address, and even temporary security credentials if roles are assumed by
// that instance.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike, auditd_manager
// Language: eql
// UUID: ecc0cd54-608e-11ef-ab6d-f661ea17fbce
// Type: eql

process where host.os.type in ("linux", "macos", "windows") and event.type == "start" and
event.action like ("exec", "exec_event", "start", "ProcessRollup2", "executed", "process_started", "Process Create*") and
(
  process.name in~ (
    "curl", "curl.exe", "wget", "wget.exe", "bash", "dash", "sh", "tcsh", "tclsh", "wish",
    "csh", "zsh", "ksh", "fish", "mksh", "busybox", "powershell.exe", "cmd.exe", "pwsh.exe", "pwsh"
  ) or
  process.name like~ (".*", "python*", "perl*", "ruby*", "php*", "lua*", "java*") or
  ?process.executable like~ (
    "/tmp/*", "/var/tmp/*", "/dev/shm/*", "/home/*/*", "/var/run/*", "/run/*", "/boot/*", "/.*", "C:\\Users\\*",
    "?:\\ProgramData\\*", "/var/www/*", "./*"
  )
) and
process.args like~ (
  "*/latest/meta-data/iam/security-credentials/?*",
  "*computeMetadata/v1/instance/service-accounts/*/oauth2/access_token*",
  "*/metadata/identity/oauth2/token*resource=*"
)

// Title: credential_access_trufflehog_execution.toml
// Source: detection-rules::rules/cross-platform/credential_access_trufflehog_execution.toml
// Section: EQL Rule
// Rule Name: Credential Access via TruffleHog Execution
// Author: Elastic
// Description:
// This rule detects the execution of TruffleHog, a tool used to search for high-entropy strings and secrets
// in code repositories, which may indicate an attempt to access credentials. This tool was abused by the Shai-Hulud
// worm to search for credentials in code repositories.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike, auditd_manager
// Language: eql
// UUID: 47595dea-452b-4d37-b82d-6dd691325139
// Type: eql

process where event.type == "start" and process.name : ("trufflehog.exe", "trufflehog") and
process.args == "--json" and process.args == "filesystem"

// Title: credential_access_web_server_cloud_imds_ssrf_request.toml
// Source: detection-rules::rules/cross-platform/credential_access_web_server_cloud_imds_ssrf_request.toml
// Section: EQL Rule
// Rule Name: Web Server Cloud Metadata SSRF Request
// Author: Elastic
// Description:
// Detects HTTP requests to web servers whose URL or query string references cloud instance metadata endpoints or
// equivalent encoded variants. Attackers exploit server-side request forgery (SSRF) vulnerabilities in web applications
// to reach link-local metadata services on AWS, GCP, Azure, and similar cloud providers and harvest temporary
// credentials, tokens, or instance details.
// Integration: nginx, apache, apache_tomcat, iis, traefik, zeek
// Language: eql
// UUID: 8670bf41-cb64-4d65-a0d6-78af17cf8f30
// Type: eql

web where (
  url.original : (
    "*169.254.169.254*", "*169%2e254%2e169%2e254*", "*0xa9fea9fe*", "*0xa9.0xfe.0xa9.0xfe*", 
    "*2852039166*", "*0251.0376.0251.0376*", "*::ffff:169.254.169.254*", "*::ffff:a9fe:a9fe*", "*fd00:ec2::254*",
    "*100.100.100.200*", "*169.254.170.2*", "*metadata.google.internal*", "*metadata.goog*", "*computeMetadata/v1*",
    "*meta-data/iam/security-credentials*", "*meta-data%2Fiam%2Fsecurity-credentials*",
    "*latest/meta-data*", "*latest/api/token*"
  )
  or
  url.query : (
    "*169.254.169.254*", "*169%2e254%2e169%2e254*", "*0xa9fea9fe*", "*0xa9.0xfe.0xa9.0xfe*", 
    "*2852039166*", "*0251.0376.0251.0376*", "*::ffff:169.254.169.254*", "*::ffff:a9fe:a9fe*", "*fd00:ec2::254*",
    "*100.100.100.200*", "*169.254.170.2*", "*metadata.google.internal*", "*metadata.goog*", "*computeMetadata/v1*",
    "*meta-data/iam/security-credentials*", "*meta-data%2Fiam%2Fsecurity-credentials*",
    "*latest/meta-data*", "*latest/api/token*"
  )
)

// Title: defense_evasion_agent_spoofing_multiple_hosts.toml
// Source: detection-rules::rules/cross-platform/defense_evasion_agent_spoofing_multiple_hosts.toml
// Section: EQL Rule
// Rule Name: Agent Spoofing - Multiple Hosts Using Same Agent
// Author: Elastic
// Description:
// Detects when multiple hosts are using the same agent ID. This could occur in the event of an agent being taken over and
// used to inject illegitimate documents into an instance as an attempt to spoof events in order to masquerade actual
// activity to evade detection.
// Integration: endpoint
// Language: esql
// UUID: 493834ca-f861-414c-8602-150d5505b777
// Type: esql

from logs-endpoint.*  metadata _id
| where event.agent_id_status is not null and agent.id is not null
| stats Esql.count_distinct_host_ids = count_distinct(host.id), Esql.host_id_values = values(host.id), Esql.user_id_values_user_id = values(user.id) by agent.id
| where Esql.count_distinct_host_ids >= 2
| keep Esql.count_distinct_host_ids, Esql.host_id_values, Esql.user_id_values_user_id, agent.id

// Title: defense_evasion_claude_cowork_vm_boot_image_tamper.toml
// Source: detection-rules::rules/cross-platform/defense_evasion_claude_cowork_vm_boot_image_tamper.toml
// Section: EQL Rule
// Rule Name: Claude Cowork VM Boot Image Tamper
// Author: Elastic
// Description:
// Detects unexpected modification of Claude Desktop Cowork VM boot images (kernel, initrd, root filesystem). Adversaries
// with user-context access can rewrite these stored images so later Cowork sessions boot attacker-controlled code inside a
// virtual instance that host EDR cannot inspect by default.
// Integration: endpoint
// Language: eql
// UUID: a0939500-a817-4ce9-85a9-191133352a9e
// Type: eql

file where host.os.type in ("windows", "macos") and
  event.action in ("creation", "modification", "overwrite", "rename") and
  event.outcome == "success" and
  file.path : (
    "/Users/*/Library/Application Support/Claude/vm_bundles/claudevm.bundle/initrd",
    "/Users/*/Library/Application Support/Claude/vm_bundles/claudevm.bundle/initrd.zst",
    "/Users/*/Library/Application Support/Claude/vm_bundles/claudevm.bundle/vmlinuz",
    "/Users/*/Library/Application Support/Claude/vm_bundles/claudevm.bundle/vmlinuz.zst",
    "/Users/*/Library/Application Support/Claude/vm_bundles/claudevm.bundle/rootfs.img",
    "?:\\Users\\*\\AppData\\Local\\Packages\\Claude_*\\LocalCache\\Roaming\\Claude\\vm_bundles\\claudevm.bundle\\initrd",
    "?:\\Users\\*\\AppData\\Local\\Packages\\Claude_*\\LocalCache\\Roaming\\Claude\\vm_bundles\\claudevm.bundle\\initrd.zst",
    "?:\\Users\\*\\AppData\\Local\\Packages\\Claude_*\\LocalCache\\Roaming\\Claude\\vm_bundles\\claudevm.bundle\\vmlinuz",
    "?:\\Users\\*\\AppData\\Local\\Packages\\Claude_*\\LocalCache\\Roaming\\Claude\\vm_bundles\\claudevm.bundle\\rootfs.vhdx",
    "?:\\Users\\*\\AppData\\Local\\Packages\\Claude_*\\LocalCache\\Roaming\\Claude\\vm_bundles\\claudevm.bundle\\smol-bin.vhdx"
  ) and
  not (
    (process.name : "claude.exe" and
     process.executable : "?:\\Program Files\\WindowsApps\\Claude_*\\app\\claude.exe") or
    (process.name : ("Claude", "Claude Helper") and
     process.executable like "/Applications/Claude.app/*")
  )

// Title: defense_evasion_data_encrypted_via_openssl.toml
// Source: detection-rules::rules/cross-platform/defense_evasion_data_encrypted_via_openssl.toml
// Section: EQL Rule
// Rule Name: Data Encrypted via OpenSSL Utility
// Author: Elastic
// Description:
// Identifies the execution of the OpenSSL utility to encrypt data. Adversaries may use OpenSSL to encrypt data to
// disrupt the availability of their target's data and may attempt to hold the organization's data to ransom for the
// purposes of extortion.
// Integration: endpoint, sentinel_one_cloud_funnel, crowdstrike, auditd_manager, windows, system
// Language: eql
// UUID: feba48f6-40ca-4d04-b41f-5dfa327de865
// Type: eql

process where event.type == "start" and event.action in ("start", "exec", "executed", "exec_event", "ProcessRollup2") and
process.name : "openssl*" and process.args : "enc" and process.args : "-in" and process.args : "-out"

// Title: defense_evasion_deleting_websvr_access_logs.toml
// Source: detection-rules::rules/cross-platform/defense_evasion_deleting_websvr_access_logs.toml
// Section: EQL Rule
// Rule Name: WebServer Access Logs Deleted
// Author: Elastic
// Description:
// Identifies the deletion of WebServer access logs. This may indicate an attempt to evade detection or destroy forensic
// evidence on a system.
// Integration: endpoint, windows
// Language: eql
// UUID: 665e7a4f-c58e-4fc6-bc83-87a7572670ac
// Type: eql

file where event.type == "deletion" and
  file.path : ("C:\\inetpub\\logs\\LogFiles\\*.log",
               "/var/log/apache*/access.log",
               "/etc/httpd/logs/access_log",
               "/var/log/httpd/access_log",
               "/var/www/*/logs/access.log")

// Title: defense_evasion_deletion_of_bash_command_line_history.toml
// Source: detection-rules::rules/cross-platform/defense_evasion_deletion_of_bash_command_line_history.toml
// Section: EQL Rule
// Rule Name: Tampering of Shell Command-Line History
// Author: Elastic
// Description:
// Adversaries may attempt to clear or disable the Bash command-line history in an attempt to evade detection or forensic
// investigations.
// Integration: endpoint, auditd_manager
// Language: eql
// UUID: 7bcbb3ac-e533-41ad-a612-d6c3bf666aba
// Type: eql

process where event.action in ("exec", "exec_event", "executed", "process_started") and event.type == "start" and
(
  (
    (process.args : ("rm", "echo") or
    (process.args : "ln" and process.args : "-sf" and process.args : "/dev/null") or
    (process.args : "truncate" and process.args : "-s0")
  )
    and process.args : (
      ".bash_history", "/root/.bash_history", "/home/*/.bash_history","/Users/.bash_history", "/Users/*/.bash_history",
      ".zsh_history", "/root/.zsh_history", "/home/*/.zsh_history", "/Users/.zsh_history", "/Users/*/.zsh_history"
    )
  ) or
  (process.args : "history" and process.args : "-c") or
  (process.args : "export" and process.args : ("HISTFILE=/dev/null", "HISTFILESIZE=0")) or
  (process.args : "unset" and process.args : "HISTFILE") or
  (process.args : "set" and process.args : "history" and process.args : "+o")
) and not (
  process.executable like (
    "/usr/bin/timeout", "/usr/bin/kubectl", "/usr/bin/psql", "/usr/lib/postgresql/*/bin/psql", "/usr/bin/bazel", "/usr/bin/git",  "/usr/bin/jq", "/bin/grep"
  ) or
  process.command_line == "stat -c %s history"
)

// Title: defense_evasion_elastic_agent_service_terminated.toml
// Source: detection-rules::rules/cross-platform/defense_evasion_elastic_agent_service_terminated.toml
// Section: EQL Rule
// Rule Name: Elastic Agent Service Terminated
// Author: Elastic
// Description:
// Identifies the Elastic endpoint agent has stopped and is no longer running on the host. Adversaries may attempt to
// disable security monitoring tools in an attempt to evade detection or prevention capabilities during an intrusion. This
// may also indicate an issue with the agent itself and should be addressed to ensure defensive measures are back in a
// stable state.
// Integration: endpoint
// Language: eql
// UUID: b627cd12-dac4-11ec-9582-f661ea17fbcd
// Type: eql

process where event.type == "start" and
(
  /* net, sc or wmic stopping or deleting Elastic Agent on Windows */
  (
    process.name : ("net.exe", "sc.exe", "wmic.exe", "powershell.exe", "taskkill.exe", "PsKill.exe", "ProcessHacker.exe") and
    process.args : ("stopservice", "uninstall", "stop", "disabled", "Stop-Process", "terminate", "suspend") and
    process.args : ("elasticendpoint", "Elastic Agent", "elastic-agent", "elastic-endpoint")
  ) or

  /* direct uninstallation of Elastic Agent or Elastic Endpoint on Windows */
  (
    host.os.type == "windows" and
    process.name : ("elastic-agent.exe", "endpoint-security.exe", "elastic-endpoint.exe") and
    process.args : "uninstall" and
    /* exclude legitimate Elastic-managed reinstall, upgrade, and uninstall subprocesses */
    not (
      process.parent.code_signature.trusted == true and
      process.parent.code_signature.subject_name == "Elasticsearch, Inc." and
      (
        (
          process.name : "elastic-agent.exe" and process.args : "--force" and
          process.parent.name : "elastic-agent.exe" and process.parent.args : "install" and
          process.parent.args : ("--force", "-f")
        ) or
        (
          process.parent.name : "endpoint-security.exe" and
          process.executable : "*\\components\\previous\\elastic-endpoint.exe" and
          process.args : "--keepstate" and process.parent.args : "--upgrade"
        ) or
        (
          process.name : "endpoint-security.exe" and process.parent.name : "elastic-agent.exe" and
          process.parent.args : "uninstall"
        )
      )
    )
  ) or

  /* service or systemctl used to stop Elastic Agent on Linux */
  (
    process.name in ("systemctl", "service", "chkconfig", "update-rc.d") and
    process.args : ("elastic-agent", "elastic-agent.service", "ElasticEndpoint") and
    process.args : ("stop", "disable", "remove", "off", "kill", "mask") and
    not (
      process.parent.executable : "/opt/Elastic/Agent/data/elastic-agent-*/components/previous/elastic-endpoint" and
      process.parent.args : "uninstall" and
      process.parent.args : "--keepstate"
    )
  ) or

  /* pkill, killall used to stop Elastic Agent or Endpoint on Linux */
  (process.name in ("pkill", "killall", "kill") and process.args : ("elastic-agent", "elastic-endpoint")) or

  /* Unload Elastic Defend extension on MacOS */
  (process.name : "kextunload" and process.args : "com.apple.iokit.EndpointSecurity")
)

// Title: defense_evasion_encoding_rot13_python_script.toml
// Source: detection-rules::rules/cross-platform/defense_evasion_encoding_rot13_python_script.toml
// Section: EQL Rule
// Rule Name: ROT Encoded Python Script Execution
// Author: Elastic
// Description:
// Identifies the execution of a Python script that uses the ROT cipher for letters substitution. Adversaries may
// use this method to encode and obfuscate part of their malicious code in legit python packages.
// Integration: endpoint
// Language: eql
// UUID: 5ab49127-b1b3-46e6-8a38-9e8512a2a363
// Type: eql

sequence by process.entity_id with maxspan=1m
 [process where host.os.type in ("windows", "macos") and event.type == "start" and process.name : "python*" and
  not (
    process.args : ("*gcloud.py", "*conda-script.py", "*compileall.py", "*.lmstudio*") or
    process.parent.args : ("*gcloud.py", "*conda-script.py", "*compileall.py", "*.lmstudio*")
  )]
 [file where host.os.type in ("windows", "macos") and
  event.action != "deletion" and process.name : "python*" and file.name : "rot_??.cpython-*.pyc*"]

// Title: defense_evasion_genai_cli_unsafe_permission_bypass.toml
// Source: detection-rules::rules/cross-platform/defense_evasion_genai_cli_unsafe_permission_bypass.toml
// Section: EQL Rule
// Rule Name: GenAI CLI Started with Unsafe Permission Bypass
// Author: Elastic
// Description:
// Identifies GenAI agent CLIs started with permission-bypass or auto-approval flags that disable human-in-the-loop
// guardrails. These modes are intended for isolated sandboxes but are frequently misused on internet-connected developer
// workstations, allowing prompt injection, compromised dependencies, or malicious skills to execute commands, modify
// files, or reach sensitive paths without confirmation.
// Integration: endpoint
// Language: eql
// UUID: c1326e45-6d3c-4a2d-9882-606a0c310299
// Type: eql

process where event.type == "start" and event.action in ("exec", "start") and
(
  (
    process.args in (
      "--dangerously-skip-permissions",
      "--allow-dangerously-skip-permissions",
      "--permission-mode=bypassPermissions"
    ) or
    (process.args == "--permission-mode" and process.args == "bypassPermissions")
  ) and
  (
    process.name in ("claude", "claude.exe") or
    process.executable : (
      "*/.local/share/claude/versions/*",
      "*/.claude/downloads/*",
      "*Caskroom/claude-code/*",
      "*\\Claude\\versions\\*"
    ) or
    (process.name in ("node", "node.exe") and process.args : "*@anthropic-ai/claude-code*")
  )
) or
(
  (
    process.args in ("--dangerously-bypass-approvals-and-sandbox", "--full-auto", "--yolo") or
    process.command_line : (
      "* -s danger-full-access*",
      "*--sandbox danger-full-access*",
      "*--sandbox=danger-full-access*",
      "*--ask-for-approval never*",
      "*--ask-for-approval=never*"
    )
  ) and
  (
    process.name in (
      "codex", "codex.exe", "codex-exec",
      "codex-aarch64-apple-darwin", "codex-x86_64-apple-darwin",
      "codex-linux-arm64", "codex-linux-x64"
    ) or
    (process.name in ("node", "node.exe") and process.args : ("*@openai/codex*", "*/codex", "*\\codex*"))
  )
) or
(
  (
    process.args in ("--yolo", "-y") or
    (process.args == "--approval-mode" and process.args == "yolo") or
    process.args == "--approval-mode=yolo"
  ) and
  (
    process.name in ("gemini", "gemini-cli", "gemini.exe", "gemini-cli.exe") or
    (process.name in ("node", "node.exe") and process.args : ("*@google/gemini-cli*", "*/gemini", "*\\gemini*"))
  )
) or
(
  (
    process.args in (
      "--yolo",
      "--autopilot",
      "--allow-all",
      "--allow-all-tools",
      "--allow-all-paths",
      "--allow-all-urls"
    )
  ) and
  (
    process.name in ("copilot", "copilot.exe") or
    (process.name in ("node", "node.exe") and process.args : ("*@github/copilot*", "*/copilot", "*\\copilot*"))
  )
) or
(
  process.args == "--dangerously-skip-permissions" and
  (
    process.name in ("opencode", "opencode.exe", ".opencode") or
    process.executable : ("*opencode-ai*", "*\\.opencode*") or
    (process.name in ("node", "node.exe") and process.args : ("*opencode-ai*", "*/opencode", "*\\opencode*"))
  )
)

// Title: defense_evasion_genai_process_compiling_executables.toml
// Source: detection-rules::rules/cross-platform/defense_evasion_genai_process_compiling_executables.toml
// Section: EQL Rule
// Rule Name: GenAI Process Compiling or Generating Executables
// Author: Elastic
// Description:
// Detects when GenAI tools spawn compilers or packaging tools to generate executables. Attackers leverage local LLMs to
// autonomously generate and compile malware, droppers, or implants. Python packaging tools (pyinstaller, nuitka, pyarmor)
// are particularly high-risk as they create standalone executables that can be deployed without dependencies. This rule
// focuses on compilation activity that produces output binaries, filtering out inspection-only operations.
// Integration: endpoint, windows, sentinel_one_cloud_funnel, m365_defender, auditd_manager
// Language: eql
// UUID: b2c3d4e5-f6a7-8901-bcde-f123456789ab
// Type: eql

process where event.type == "start" and

  // GenAI parent process
  (
    process.parent.name in (
      "ollama.exe", "ollama", "Ollama",
      "textgen.exe", "textgen", "text-generation-webui.exe", "oobabooga.exe",
      "lmstudio.exe", "lmstudio", "LM Studio",
      "claude.exe", "claude", "Claude",
      "cursor.exe", "cursor", "Cursor", "Cursor Helper", "Cursor Helper (Plugin)",
      "copilot.exe", "copilot", "Copilot",
      "codex.exe", "codex",
      "Jan", "jan.exe", "jan", "Jan Helper",
      "gpt4all.exe", "gpt4all", "GPT4All",
      "gemini-cli.exe", "gemini-cli",
      "genaiscript.exe", "genaiscript",
      "grok.exe", "grok",
      "qwen.exe", "qwen",
      "koboldcpp.exe", "koboldcpp", "KoboldCpp",
      "llama-server", "llama-cli"
    ) or

    // Node/Deno with GenAI frameworks
    (process.parent.name in ("node.exe", "node", "deno.exe", "deno") and
     process.parent.command_line like~ ("*mcp-server*", "*@modelcontextprotocol*", "*langchain*", "*autogpt*", "*babyagi*", "*agentgpt*", "*crewai*", "*semantic-kernel*", "*llama-index*", "*haystack*")) or

    // Python with GenAI frameworks
    (process.parent.name like~ "python*" and
     process.parent.command_line like~ ("*langchain*", "*autogpt*", "*babyagi*", "*agentgpt*", "*crewai*", "*semantic-kernel*", "*llama-index*", "*haystack*"))
  ) and

  // Compilation tools
  (
    // Python packaging
    process.name in ("pyinstaller", "py2exe", "cx_Freeze", "nuitka", "pyarmor", "pkg") or

    // C/C++ compilation with output
    (process.name in ("gcc", "g++", "clang", "clang++", "cl.exe") and
     process.command_line like~ "*-o *" and
     process.command_line like~ ("*.c *", "*.c", "*.cpp *", "*.cpp", "*.cc *", "*.cc", "*.m *", "*.m") and
     not process.command_line like~ "*git*") or

    // Go compilation
    (process.name == "go" and process.args == "build") or

    // Rust compilation
    (process.name == "cargo" and process.args == "build") or
    (process.name == "rustc" and process.command_line like~ "*-o *") or

    // .NET compilation
    process.name in ("csc.exe", "vbc.exe", "msbuild.exe") or
    (process.name == "dotnet" and process.args == "build") or

    // Java compilation
    process.name == "javac"
  )

// Title: defense_evasion_genai_process_encoding_prior_to_network_activity.toml
// Source: detection-rules::rules/cross-platform/defense_evasion_genai_process_encoding_prior_to_network_activity.toml
// Section: EQL Rule
// Rule Name: GenAI Process Performing Encoding/Chunking Prior to Network Activity
// Author: Elastic
// Description:
// Detects when GenAI processes perform encoding or chunking (base64, gzip, tar, zip) followed by outbound network
// activity. This sequence indicates data preparation for exfiltration. Attackers encode or compress sensitive data before
// transmission to obfuscate contents and evade detection. Legitimate GenAI workflows rarely encode data before network
// communications.
// Integration: endpoint, windows, sentinel_one_cloud_funnel, m365_defender
// Language: eql
// UUID: c3d4e5f6-a7b8-9012-cdef-123456789abc
// Type: eql

sequence by process.entity_id with maxspan=30s

  // Encoding/compression followed by network activity
  [process where event.type == "start"
     and event.type == "start"

     // Encoding/chunking tools
     and (
       // Native encoding tools
       process.name in ("base64", "gzip", "tar", "zip", "split", "7z", "7za", "7zr") or

       // PowerShell encoding
       (process.name in ("powershell.exe", "pwsh.exe") and
        process.command_line like~ ("*Compress-Archive*", "*[Convert]::ToBase64String*")) or

       // Python encoding
       (process.name like~ "python*" and
        process.command_line like~ ("*base64*", "*gzip*", "*zlib*", "*tarfile*", "*zipfile*")) or

       // Node.js encoding
       (process.name in ("node.exe", "node") and
        process.command_line like~ ("*Buffer.from*", "*zlib*", "*gzip*") and
        not process.command_line like~ ("*mcp*start*", "*mcp-server*", "*npm exec*mcp*"))
     )

     // GenAI parent process
     and (
       process.parent.name in (
         "ollama.exe", "ollama", "Ollama",
         "textgen.exe", "textgen", "text-generation-webui.exe", "oobabooga.exe",
         "lmstudio.exe", "lmstudio", "LM Studio",
         "claude.exe", "claude", "Claude",
         "cursor.exe", "cursor", "Cursor", "Cursor Helper", "Cursor Helper (Plugin)",
         "copilot.exe", "copilot", "Copilot",
         "codex.exe", "codex",
         "Jan", "jan.exe", "jan", "Jan Helper",
         "gpt4all.exe", "gpt4all", "GPT4All",
         "gemini-cli.exe", "gemini-cli",
         "genaiscript.exe", "genaiscript",
         "grok.exe", "grok",
         "qwen.exe", "qwen",
         "koboldcpp.exe", "koboldcpp", "KoboldCpp",
         "llama-server", "llama-cli"
       ) or

       // Node/Deno with GenAI frameworks
       (process.parent.name in ("node.exe", "node", "deno.exe", "deno") and
        process.parent.command_line like~ (
          "*ollama*", "*mcp-server*", "*@modelcontextprotocol*", "*langchain*", "*autogpt*",
          "*babyagi*", "*agentgpt*", "*crewai*", "*semantic-kernel*", "*llama-index*",
          "*haystack*", "*openai*", "*anthropic*", "*cohere*", "*mistral*"
        )) or

       // Python with GenAI frameworks
       (process.parent.name like~ "python*" and
        process.parent.command_line like~ (
          "*ollama*", "*mcp-server*", "*langchain*", "*autogpt*", "*babyagi*",
          "*agentgpt*", "*crewai*", "*semantic-kernel*", "*llama-index*", "*haystack*",
          "*openai*", "*anthropic*", "*cohere*", "*mistral*"
        ))
     )
  ] by process.entity_id

  // Outbound network connection (non-local)
  [network where event.type == "start"
     and event.action == "connection_attempted"
     and destination.ip != null
     and not cidrmatch(destination.ip, "10.0.0.0/8", "127.0.0.0/8", "169.254.0.0/16", "172.16.0.0/12", "192.0.0.0/24", "192.0.0.0/29",
                       "192.0.0.8/32", "192.0.0.9/32", "192.0.0.10/32", "192.0.0.170/32", "192.0.0.171/32", "192.0.2.0/24",
                       "192.31.196.0/24", "192.52.193.0/24", "192.168.0.0/16", "192.88.99.0/24", "224.0.0.0/4", "100.64.0.0/10",
                       "192.175.48.0/24","198.18.0.0/15", "198.51.100.0/24", "203.0.113.0/24", "240.0.0.0/4", "::1", "FE80::/10",
                       "FF00::/8")

  ] by process.entity_id

// Title: defense_evasion_long_base64_encoded_interpreter_command_line.toml
// Source: detection-rules::rules/cross-platform/defense_evasion_long_base64_encoded_interpreter_command_line.toml
// Section: EQL Rule
// Rule Name: Long Base64 Encoded Command via Scripting Interpreter
// Author: Elastic
// Description:
// Identifies oversized command lines used by Python, PowerShell, Node.js, or Deno that contain base64 decoding or
// encoded-command patterns. Adversaries may embed long inline encoded payloads in scripting interpreters to evade
// inspection and execute malicious content across Windows, macOS, and Linux systems.
// Integration: endpoint
// Language: esql
// UUID: 74d31cb7-4a2c-44fe-9d1d-f375b9f3cb61
// Type: esql

FROM logs-endpoint.events.process-* METADATA _id, _index, _version, _ignored
| MV_EXPAND _ignored
| WHERE _ignored == "process.command_line"
| WHERE event.category == "process" and event.type == "start"
| EVAL command_line = TO_LOWER(process.command_line.text), pname = TO_LOWER(process.name)
| WHERE 
(
    (
        /* Python: inline exec with base64 decode or -c flag with encoded payload */
        pname like "python*" and
        (
            command_line like "*b64decode*" or
            (command_line like "*-c*" and command_line like "*base64*")
        )
    ) or
    (
        /* PowerShell: encoded command flag — require trailing space to avoid matching
           -Encoding, -EncryptionType, -EncryptionProvider, etc. */
        (pname like "powershell*" or pname like "pwsh*") and
        (
            command_line rlike ".* -(e|en|enc|enco|encod|encode|encoded|encodedcommand) .+" or
            command_line like "*-encodedcommand*" or
            command_line like "*frombase64string*"
        )
    ) or
    (
        /* Node.js: buffer.from must be paired with base64 to avoid matching
           general Buffer usage; atob is always base64 */
        pname like "node*" and
        (
            (command_line like "*buffer.from*" and command_line like "*base64*") or
            command_line like "*atob(*"
        )
    ) or
    (
        /* Deno: eval( (not eval/evaluate/evaluation), atob, or buffer+base64 */
        pname like "deno*" and
        (
            command_line like "*atob(*" or
            (command_line like "*buffer.from*" and command_line like "*base64*") or
            command_line like "*eval(*"
        )
    )
)
| EVAL Esql.length_cmdline = LENGTH(command_line)
| WHERE Esql.length_cmdline >= 4000
| KEEP *

// Title: defense_evasion_masquerading_space_after_filename.toml
// Source: detection-rules::rules/cross-platform/defense_evasion_masquerading_space_after_filename.toml
// Section: EQL Rule
// Rule Name: Masquerading Space After Filename
// Author: Elastic
// Description:
// This rules identifies a process created from an executable with a space appended to the end of the filename. This may
// indicate an attempt to masquerade a malicious file as benign to gain user execution. When a space is added to the end of
// certain files, the OS will execute the file according to it's true filetype instead of it's extension. Adversaries can
// hide a program's true filetype by changing the extension of the file. They can then add a space to the end of the name
// so that the OS automatically executes the file when it's double-clicked.
// Integration: endpoint
// Language: eql
// UUID: f5fb4598-4f10-11ed-bdc3-0242ac120002
// Type: eql

process where host.os.type:("linux","macos") and event.type == "start" and
process.executable regex~ """/[a-z0-9\s_\-\\./]+\s""" and not (
  process.name in ("ls", "find", "grep", "xkbcomp") or
  process.executable like ("/opt/nessus_agent/*", "/opt/gitlab/sv/gitlab-exporter/*", "/tmp/ansible-admin/*") or
  process.parent.args in (
    "./check_rubrik", "/usr/bin/check_mk_agent", "/etc/rubrik/start_stop_bootstrap.sh", "/etc/rubrik/start_stop_agent.sh"
  ) or
  process.args == "runc"
)

// Title: defense_evasion_missing_events_after_alert.toml
// Source: detection-rules::rules/cross-platform/defense_evasion_missing_events_after_alert.toml
// Section: EQL Rule
// Rule Name: Elastic Defend Alert Followed by Telemetry Loss
// Author: Elastic
// Description:
// Detects when an Elastic Defend endpoint alert is generated on a host and is not followed by any subsequent endpoint
// telemetry (process, network, registry, library, or DNS events) within a short time window. This behavior may indicate
// endpoint security evasion, agent tampering, sensor disablement, service termination, system crash, or malicious
// interference with telemetry collection following detection.
// Integration: endpoint
// Language: eql
// UUID: fc552f49-8f1c-409b-90f8-6f5b9869b6c4
// Type: eql

sequence by host.id with maxspan=10m
 [any where data_stream.dataset == "endpoint.alerts"]
 ![any where event.category in ("process", "library", "registry", "network", "dns", "file")]

// Title: defense_evasion_potential_kubectl_impersonation.toml
// Source: detection-rules::rules/cross-platform/defense_evasion_potential_kubectl_impersonation.toml
// Section: EQL Rule
// Rule Name: Potential Impersonation Attempt via Kubectl
// Author: Elastic
// Description:
// This rule detects potential impersonation attempts via the "kubectl" command in Linux and macOS environments. It identifies
// process events where "kubectl" is executed with arguments that suggest an attempt to impersonate another user or
// group, such as using "--kubeconfig", "--token", "--as", or "--as-group". This could indicate an adversary trying
// to gain unauthorized access or escalate privileges within a Kubernetes cluster. If this rule is triggered, in
// conjunction with rules related to secret access or kubeconfig file discovery, it may indicate a potential
// impersonation attempt.
// Integration: endpoint, auditd_manager, sentinel_one_cloud_funnel, cloud_defend
// Language: eql
// UUID: 3c6685eb-9eaa-43a4-be1b-a7f9f1f5e63d
// Type: eql

process where host.os.type in ("linux", "macos") and event.type == "start" and
event.action in ("exec", "exec_event", "start", "executed", "process_started") and
process.name == "kubectl" and (
  process.parent.name in ("bash", "dash", "sh", "tcsh", "csh", "zsh", "ksh", "fish") or
  (
    process.parent.executable like (
      "/tmp/*", "/private/tmp/*", "/var/tmp/*", "/private/var/tmp/*", "/dev/shm/*", "/root/*", "/home/*", "/Users/*"
    ) or
    process.parent.name like (".*", "*.sh", "python*")
  )
) and process.args like~ ("--kubeconfig*", "--token*", "--as*", "--as-group*", "--as-uid*") and
not process.parent.args like ("/snap/microk8s/*/apiservice-kicker", "/snap/microk8s/*/microk8s-start.wrapper")

// Title: defense_evasion_potential_kubectl_masquerading.toml
// Source: detection-rules::rules/cross-platform/defense_evasion_potential_kubectl_masquerading.toml
// Section: EQL Rule
// Rule Name: Potential Kubectl Masquerading via Unexpected Process
// Author: Elastic
// Description:
// This rule detects potential kubectl masquerading activity by monitoring for process events where the process name
// is not "kubectl" but the command line arguments include kubectl-related commands. This could indicate an adversary
// attempting to masquerade as legitimate kubectl activity to evade detection. This rule covers evasion gaps
// introduced by renaming the kubectl binary, or placing it in an unusual directory.
// Integration: endpoint, crowdstrike, sentinel_one_cloud_funnel, cloud_defend
// Language: eql
// UUID: 2388c687-cb2c-4b7b-be8f-6864a2385048
// Type: eql

process where host.os.type in ("linux", "macos") and event.type == "start" and
event.action in ("exec", "exec_event", "start", "executed", "process_started") and
(
  process.executable like~ (
    "/tmp/*", "/private/tmp/*", "/var/tmp/*", "/private/var/tmp/*", "/dev/shm/*", "/root/*", "/var/www/*", "/home/*", "/Users/*", "./kubectl"
  ) or
  process.name like ".*"
) and
process.args like~ (

  // get and describe commands
  "*get po*", "*get deploy*", "*get node*", "*get svc*", "*get service*", "*get secret*", "*get clusterrole*", "*get ingress*",
  "*get configmap*", "*describe po*", "*describe deploy*", "*describe node*", "*describe svc*", "*describe service*",
  "*describe secret*", "*describe configmap*", "*describe clusterrole*", "*describe ingress*",

  // exec commands
  "*exec -it*", "*exec --stdin*", "*exec --tty*",

  // networking commands
  "*port-forward* ", "*proxy --port*", "*run --image=*", "*expose*",

  // authentication/impersonation commands
  "*auth can-i*", "*--kubeconfig*", "*--as *", "*--as=*", "*--as-group*", "*--as-uid*"
) and not (
  process.executable like "/tmp/newroot/*" or
  process.name == ".flatpak-wrapped"
)

// Title: defense_evasion_processes_with_trailing_spaces.toml
// Source: detection-rules::rules/cross-platform/defense_evasion_processes_with_trailing_spaces.toml
// Section: EQL Rule
// Rule Name: Processes with Trailing Spaces
// Author: Elastic
// Description:
// Identify instances where adversaries include trailing space characters to mimic regular files, disguising their activity
// to evade default file handling mechanisms.
// Integration: endpoint, auditd_manager
// Language: eql
// UUID: 0c093569-dff9-42b6-87b1-0242d9f7d9b4
// Type: eql

process where event.type == "start" and event.action in ("exec", "exec_event", "executed", "process_started") and
process.name : "* "

// Title: defense_evasion_timestomp_touch.toml
// Source: detection-rules::rules/cross-platform/defense_evasion_timestomp_touch.toml
// Section: EQL Rule
// Rule Name: Timestomping using Touch Command
// Author: Elastic
// Description:
// Timestomping is an anti-forensics technique which is used to modify the timestamps of a file, often to mimic files that
// are in the same folder.
// Integration: endpoint
// Language: eql
// UUID: b0046934-486e-462f-9487-0d4cf9e429c6
// Type: eql

process where event.type == "start" and event.action == "exec" and process.name == "touch" and
process.parent.executable != null and process.args like (
  "-t*", "-d*", "-a*", "-m*", "-r*", "--date=*", "--reference=*", "--time=*"
) and not (
  process.parent.executable in (
    "/usr/local/bin/manage_omnimesh_logs", "/pro/bin/sys/install/packageUtils.sh", "/bin/dracut",
    "/usr/libexec/postfix/aliasesdb", "pwsh-preview", "/usr/bin/dracut", "/usr/share/initramfs-tools/hooks/amd64_microcode",
    "/usr/local/bin/start-mailserver.sh", "/usr/bin/ssm-agent-worker", "/bin/ssm-agent-worker", "/usr/local/cpanel/scripts/restartsrv_bind"
  ) or
  process.parent.executable like ("/opt/sw/tomcat/rc_scripts/*", "/tmp/newroot/var/lib/docker/overlay2/*", "/snap/*", "/opt/zeek/*") or
  process.parent.name in (
    "xargs", "find", "sudo", "make", "pmlogger_check", "pmlogger_daily", "pmlogger_janitor", "autoupdate", "pmlogctl",
    "spyglass", "desktop-launch", "pmiectl", "systemd"
  ) or
  process.parent.args like (
    "/home/*/scripts/auto_download_process.py", "/home/*/scripts/perl_python_eagu1p.py", "/var/lib/dpkg/info/*",
    "bazel-out/k8-dbg/bin/dependencies/thirdparty/libjansson_foreign_cc/build_script.sh", "/usr/lib/portage/python*/ebuild.sh",
    "/var/tmp/rpm-tmp.*", "/usr/lib/pcp/bin/pmlogger_janitor", "/usr/libexec/pcp/bin/pmlogger_janitor",
    "/usr/libexec/pcp/bin/pmlogger_daily", "/usr/lib/pcp/bin/pmlogger_daily", "/opt/oracle.ExaWatcher/GetExaWatcherResults.sh"
  ) or
  process.args in (
    "/usr/bin/coreutils", "--no-create", "/etc/opt/lumu/lumud.conf", "/opt/vuso*", "/opt/diff", "/etc/aliases.db", "/opt/cursor/cursor"
  ) or
  process.args like (
    "--checkpoint=*", "/root/.config/envman/*", "/var/tmp/dracut*", "/var/tmp/portage*", "/snap/*", "/var/tmp/pmlogger_*/stamp", "/opt/ubki/*.jar",
    "/usr/lib/go-*/bin/go", "/usr/lib/dracut/dracut-functions.sh", "/tmp/KSInstallAction.*/m/.patch/*"
  ) or
  process.command_line in ("/bin/touch -a /tmp/au_status", "touch -d 2 seconds ago /etc/postfix/main.cf") or
  process.parent.command_line == "runc init" or
  process.working_directory in ("/opt/libexec", "/opt/local/src/connectxx/build/src/mdp")
)

// Title: defense_evasion_whitespace_padding_command_line.toml
// Source: detection-rules::rules/cross-platform/defense_evasion_whitespace_padding_command_line.toml
// Section: EQL Rule
// Rule Name: Command Line Obfuscation via Whitespace Padding
// Author: Elastic
// Description:
// Identifies process execution events where the command line value contains a long sequence of whitespace characters or
// multiple occurrences of contiguous whitespace. Attackers may attempt to evade signature-based detections by padding
// their malicious command with unnecessary whitespace characters. These observations should be investigated for malicious
// behavior.
// Integration: endpoint, system, windows, auditd_manager, m365_defender, crowdstrike, sentinel_one_cloud_funnel
// Language: esql
// UUID: 5a876e0d-d39a-49b9-8ad8-19c9b622203b
// Type: esql

FROM logs-* metadata _id, _version, _index 
| where event.category == "process" and event.type == "start" and event.action != "fork"
// more than 100 spaces in process.command_line
| eval multi_spaces = LOCATE(process.command_line, space(100)) 
| where multi_spaces > 0 
| keep user.name, host.id, host.name, process.command_line, process.executable, process.parent.executable, _id, _version, _index

// Title: discovery_kubectl_permission_discovery.toml
// Source: detection-rules::rules/cross-platform/discovery_kubectl_permission_discovery.toml
// Section: EQL Rule
// Rule Name: Kubectl Permission Discovery
// Author: Elastic
// Description:
// This rule detects the use of the "kubectl auth --can-i" command, which is used to check permissions in Kubernetes clusters.
// Attackers may use this command to enumerate permissions and discover potential misconfigurations in the cluster, allowing
// them to gain unauthorized access or escalate privileges.
// Integration: endpoint, auditd_manager, crowdstrike, sentinel_one_cloud_funnel, cloud_defend
// Language: eql
// UUID: 1600f9e2-5be6-4742-8593-1ba50cd94069
// Type: eql

process where host.os.type in ("linux", "macos") and event.type == "start" and
event.action in ("exec", "exec_event", "start", "ProcessRollup2", "executed", "process_started") and
process.name == "kubectl" and process.args == "auth" and process.args == "can-i"

// Title: discovery_kubectl_secrets_all_namespaces.toml
// Source: detection-rules::rules/cross-platform/discovery_kubectl_secrets_all_namespaces.toml
// Section: EQL Rule
