// Title: credential_access_google_workspace_drive_encryption_key_accessed_by_anonymous_user.toml
// Source: detection-rules::rules/integrations/google_workspace/credential_access_google_workspace_drive_encryption_key_accessed_by_anonymous_user.toml
// Section: EQL Rule
// Rule Name: Google Workspace Drive Encryption Key(s) Accessed from Anonymous User
// Author: Elastic
// Description:
// Detects when an anonymous user views, copies, or downloads a private key or credential file from Google Drive via an
// anyone-with-the-link share. Adversaries who obtain or create open Drive links can harvest encryption keys and secrets
// stored in user drives, then use those materials to decrypt data, authenticate to services, or expand access beyond the
// initial compromise.
// Integration: google_workspace
// Language: eql
// UUID: 980b70a0-c820-11ed-8799-f661ea17fbcc
// Type: eql

file where data_stream.dataset == "google_workspace.drive" and event.action : ("copy", "view", "download") and
    google_workspace.drive.visibility: "people_with_link" and source.user.email == "" and
    file.extension: (
        "token","assig", "pssc", "keystore", "pub", "pgp.asc", "ps1xml", "pem", "gpg.sig", "der", "key",
        "p7r", "p12", "asc", "jks", "p7b", "signature", "gpg", "pgp.sig", "sst", "pgp", "gpgz", "pfx", "crt",
        "p8", "sig", "pkcs7", "jceks", "pkcs8", "psc1", "p7c", "csr", "cer", "spc", "ps2xml")

// Title: initial_access_external_user_added_to_google_workspace_group.toml
// Source: detection-rules::rules/integrations/google_workspace/initial_access_external_user_added_to_google_workspace_group.toml
// Section: EQL Rule
// Rule Name: External User Added to Google Workspace Group
// Author: Elastic
// Description:
// Detects an external Google Workspace user account being added to an existing group. Adversaries may add external user
// accounts as a means to intercept shared files or emails with that specific group.
// Integration: google_workspace
// Language: eql
// UUID: 38f384e0-aef8-11ed-9a38-f661ea17fbcc
// Type: eql

iam where data_stream.dataset == "google_workspace.admin" and event.action == "ADD_GROUP_MEMBER" and
  not endsWith(user.target.domain, user.target.group.domain)

// Title: initial_access_object_copied_to_external_drive_with_app_consent.toml
// Source: detection-rules::rules/integrations/google_workspace/initial_access_object_copied_to_external_drive_with_app_consent.toml
// Section: EQL Rule
// Rule Name: Google Workspace Object Copied from External Drive with App Consent
// Author: Elastic
// Description:
// Detects when a user copies a Google document, spreadsheet, form, or script from an external Drive into their Workspace
// Drive and shortly after authorizes a custom Google OAuth application. Adversaries may send spearphishing links with a
// /copy URI parameter so the victim replicates a malicious object locally. Container-bound Apps Script can then execute on
// open and prompt the user for OAuth consent, granting the attacker's application access to Workspace data.
// Integration: google_workspace
// Language: eql
// UUID: f33e68a4-bd19-11ed-b02f-f661ea17fbcc
// Type: eql

sequence by source.user.email with maxspan=3m
[file where data_stream.dataset == "google_workspace.drive" and event.action == "copy" and

    /* Should only match if the object lives in a Drive that is external to the user's GWS organization */
    google_workspace.drive.owner_is_team_drive == false and google_workspace.drive.copy_type == "external" and

    /* Google Script, Forms, Sheets and Document can have container-bound scripts */
    google_workspace.drive.file.type: ("script", "form", "spreadsheet", "document")]

[any where data_stream.dataset == "google_workspace.token" and event.action == "authorize" and

    /* Ensures application ID references custom app in Google Workspace and not GCP */
    google_workspace.token.client.id : "*apps.googleusercontent.com"]

// Title: persistence_google_workspace_device_registered_after_oauth_from_suspicious_asn.toml
// Source: detection-rules::rules/integrations/google_workspace/persistence_google_workspace_device_registered_after_oauth_from_suspicious_asn.toml
// Section: EQL Rule
// Rule Name: Google Workspace Device Registration After OAuth from Suspicious ASN
// Author: Elastic
// Description:
// Detects when a Google Workspace account completes OAuth authorization for a specific Google OAuth client from a
// high-risk autonomous system number (ASN), followed within 30 seconds by a device registration event with account state
// REGISTERED. This sequence can indicate device enrollment or join flows initiated from attacker-controlled or
// residential-proxy infrastructure after a user authorizes a sensitive client.
// Integration: google_workspace
// Language: eql
// UUID: 012bfca7-45cb-4507-a3ba-3777167f8b81
// Type: eql

sequence by user.name with maxspan=30s
  [iam where data_stream.dataset == "google_workspace.token" and event.action == "authorize" and
      google_workspace.token.client.id == "77185425430.apps.googleusercontent.com" and
      source.as.number in (9009, 45102, 215540, 29802, 62240, 204957, 395092)]
  [any where data_stream.dataset == "google_workspace.device" and google_workspace.device.account_state == "REGISTERED"]

// Title: credential_access_azure_arc_proxy_secret_configmap_access.toml
// Source: detection-rules::rules/integrations/kubernetes/credential_access_azure_arc_proxy_secret_configmap_access.toml
// Section: EQL Rule
// Rule Name: Kubernetes Secret or ConfigMap Access via Azure Arc Proxy
// Author: Elastic
// Description:
// Detects when secrets or configmaps are accessed, created, modified, or deleted in a Kubernetes cluster by the Azure Arc
// AAD proxy service account. When operations are routed through the Azure Arc Cluster Connect proxy, the Kubernetes audit
// log records the acting user as system:serviceaccount:azure-arc:azure-arc-kube-aad-proxy-sa with the actual caller
// identity in the impersonatedUser field. This pattern indicates that someone is accessing the cluster through the Azure
// ARM API rather than directly via kubectl against the API server. While legitimate for Arc-managed workflows, adversaries
// with stolen service principal credentials can abuse Arc Cluster Connect to read, exfiltrate, or modify secrets and
// configmaps while appearing as the Arc proxy service account in K8s audit logs. This rule uses a 5-day new-terms history
// window keyed on the impersonated identity and alerts the first time that Azure AD principal performs this activity.
// Integration: kubernetes
// Language: esql
// UUID: 220d92c6-479d-4a49-9cc0-3a29756dad0c
// Type: esql

FROM logs-kubernetes.audit_logs-* metadata _id, _version, _index
| WHERE STARTS_WITH(kubernetes.audit.user.username, "system:serviceaccount:azure-arc:")
    AND kubernetes.audit.objectRef.resource IN ("secrets", "configmaps")
    AND kubernetes.audit.verb IN ("get", "list", "create", "update", "patch", "delete")
    AND kubernetes.audit.objectRef.namespace NOT IN ("azure-arc", "azure-arc-release", "kube-system")
    AND NOT STARTS_WITH(kubernetes.audit.objectRef.name, "sh.helm.release.v1")

| STATS
    Esql.verb_values = VALUES(kubernetes.audit.verb),
    Esql.resource_type_values = VALUES(kubernetes.audit.objectRef.resource),
    Esql.resource_name_values = VALUES(kubernetes.audit.objectRef.name),
    Esql.namespace_values = VALUES(kubernetes.audit.objectRef.namespace),
    Esql.data_stream_namespace_values = VALUES(data_stream.namespace),
    Esql.acting_user_values = VALUES(kubernetes.audit.user.username),
    Esql.user_agent_values = VALUES(kubernetes.audit.userAgent),
    Esql.source_ips_values = VALUES(kubernetes.audit.sourceIPs),
    Esql.response_code_values = VALUES(kubernetes.audit.responseStatus.code),
    Esql.timestamp_first_seen = MIN(@timestamp),
    Esql.timestamp_last_seen = MAX(@timestamp),
    Esql.event_count = COUNT(*)
    BY kubernetes.audit.impersonatedUser.username

| WHERE Esql.timestamp_first_seen >= NOW() - 9 minutes
| KEEP kubernetes.audit.impersonatedUser.username, Esql.*

// Title: credential_access_kubernetes_multiple_secret_retrieval_burst.toml
// Source: detection-rules::rules/integrations/kubernetes/credential_access_kubernetes_multiple_secret_retrieval_burst.toml
// Section: EQL Rule
// Rule Name: Kubernetes Rapid Secret GET Activity Against Multiple Objects
// Author: Elastic
// Description:
// This rule detects an unusual volume of Kubernetes API get requests against multiple distinct Secret objects from the same client 
// fingerprint (user, source IP, and user agent) within a defined lookback window. This can indicate credential access or in-cluster
// reconnaissance, where a user or token is used to enumerate and retrieve sensitive data such as service account tokens, registry 
// credentials, TLS material, or application configuration. Failed get requests are also included, as they may reveal RBAC boundaries, 
// confirm the existence of targeted secrets, or reflect automated probing activity.
// Integration: kubernetes
// Language: esql
// UUID: b4c8e2a1-9f3d-4e7c-a2b1-0d5e6f7a8b9c
// Type: esql

from logs-kubernetes.audit_logs-* metadata _id, _index, _version
| where event.dataset == "kubernetes.audit_logs"
    and event.action == "get"
    and kubernetes.audit.objectRef.resource == "secrets"
    and source.ip is not null and user.name is not null 
    and not to_string(source.ip) in ("127.0.0.1", "::1") and 
    not user.name in ("system:kube-controller-manager", "system:kube-scheduler") and 
    not kubernetes.audit.objectRef.name like "sh.helm.release.*" and 
    not kubernetes.audit.user.username in ("system:serviceaccount:flux-system:kustomize-controller", "system:serviceaccount:flux-system:helm-controller", "system:serviceaccount:flux-system:source-controller", "system:serviceaccount:security:trivy-operator")
| stats
    Esql.unique_credentials = count_distinct(kubernetes.audit.objectRef.name),
    Esql.secrets_names = values(kubernetes.audit.objectRef.name),
    Esql.namespaces = values(kubernetes.audit.objectRef.namespace),
    Esql.outcome = values(`kubernetes.audit.annotations.authorization_k8s_io/decision`)
  by user.name, kubernetes.audit.user.username, source.ip, user_agent.original
| where Esql.unique_credentials >= 3
| KEEP user.name, kubernetes.audit.user.username, source.ip, user_agent.original, Esql.*

// Title: credential_access_kubernetes_pod_exec_cloud_instance_metadata.toml
// Source: detection-rules::rules/integrations/kubernetes/credential_access_kubernetes_pod_exec_cloud_instance_metadata.toml
// Section: EQL Rule
// Rule Name: Kubernetes Pod Exec Cloud Instance Metadata Access
// Author: Elastic
// Description:
// Detects Kubernetes pod exec sessions whose decoded command line references cloud instance metadata endpoints or
// equivalent hostnames and paths. Workloads that reach the link-local metadata IP, AWS IMDS paths, GCP computeMetadata,
// Azure IMDS token routes, or encoded variants are often attempting to harvest role credentials, tokens, or instance
// attributes from the underlying node or hypervisor boundary. That behavior is high risk in multi-tenant and regulated
// environments because it can expose short-lived cloud credentials to code running inside a container. The rule
// classifies a coarse cloud target label and whether the string looks like credential retrieval versus lighter
// reconnaissance.
// Integration: kubernetes
// Language: esql
// UUID: a8e7d6c5-b4a3-2918-0f9e-8d7c6b5a4032
// Type: esql

FROM logs-kubernetes.audit_logs-* metadata _id, _index, _version
| WHERE kubernetes.audit.objectRef.subresource == "exec"
  AND kubernetes.audit.requestURI LIKE "*command=*"
| EVAL Esql.decoded_uri = URL_DECODE(kubernetes.audit.requestURI)
| GROK Esql.decoded_uri "%{DATA}/exec\\?%{DATA:raw_commands}&(?:container|stdin|stdout|stderr)=%{GREEDYDATA}"
| EVAL command = REPLACE(raw_commands, "command=", "")
| EVAL command = REPLACE(command, "&", " ")
| EVAL Esql.executed_command = REPLACE(command, "\\+", " ")
| WHERE Esql.executed_command IS NOT NULL 
  AND Esql.executed_command RLIKE """.*(169\.254\.169\.254|2852039166|0xa9fea9fe|/latest/api/token|/latest/meta-data|/latest/user-data|/latest/dynamic/instance-identity|computeMetadata/v1|metadata\.google\.internal|metadata/identity/oauth2/token|metadata/instance).*"""
| EVAL Esql.cloud_target = CASE(
    Esql.executed_command RLIKE """.*(169\.254\.169\.254|2852039166|0xa9fea9fe|/latest/meta-data|/latest/api/token|/latest/user-data|/latest/dynamic).*""", "AWS_IMDS",
    Esql.executed_command RLIKE """.*(computeMetadata/v1|metadata\.google\.internal).*""", "GCP_METADATA",
    Esql.executed_command RLIKE """.*metadata/identity/oauth2/token.*""", "AZURE_IMDS",
    "UNKNOWN"
  )
| EVAL Esql.is_credential_theft = CASE(
    Esql.executed_command RLIKE """.*(security-credentials|/api/token|oauth2/token|service-accounts/.*/token).*""", "yes",
    "recon"
  )
| KEEP Esql.*, user.name, user_agent.original, event.*, source.ip, kubernetes.audit.*, _id, _version, _index, data_stream.namespace

// Title: credential_access_kubernetes_pod_exec_sensitive_file_access.toml
// Source: detection-rules::rules/integrations/kubernetes/credential_access_kubernetes_pod_exec_sensitive_file_access.toml
// Section: EQL Rule
// Rule Name: Kubernetes Pod Exec Sensitive File or Credential Path Access
// Author: Elastic
// Description:
// Detects Kubernetes pod exec sessions whose decoded command line references high-value host or in-cluster paths and
// material types: mounted service account or platform tokens, kubelet and control-plane configuration areas, host
// identity stores, root dot-directories for cloud and kubeconfig material, common private-key and keystore extensions,
// process environment dumps, and configuration filenames suggestive of embedded secrets. The intent is to catch
// interactive or scripted access that often precedes lateral movement, privilege escalation, or credential theft from
// the node or workload boundary. A narrow exclusion ignores benign reads of resolv.conf. The query also labels an
// access_type bucket to speed triage without altering the detection predicates you validated.
// Integration: kubernetes
// Language: esql
// UUID: b2c3d4e5-f6a7-4890-b1c2-d3e4f5a60789
// Type: esql

from logs-kubernetes.audit_logs-* metadata _id, _index, _version
| WHERE kubernetes.audit.objectRef.subresource == "exec"
  AND kubernetes.audit.requestURI LIKE "*command=*"
| EVAL Esql.decoded_uri = URL_DECODE(kubernetes.audit.requestURI)
| GROK Esql.decoded_uri "%{DATA}/exec\\?%{DATA:raw_commands}&(?:container|stdin|stdout|stderr)=%{GREEDYDATA}"
| EVAL command = REPLACE(raw_commands, "command=", "")
| EVAL command = REPLACE(command, "&", " ")
| EVAL Esql.executed_command = REPLACE(command, "\\+", " ")
| WHERE Esql.executed_command IS NOT NULL 
  AND Esql.executed_command RLIKE """.*(/var/run/secrets/|/etc/kubernetes/|/var/lib/kubelet/|/etc/shadow|/etc/passwd|/etc/sudoers|(/root|/home/[^/]+)/\.(ssh|aws|azure|kube|config/gcloud)|\.p12|\.pem|\.key|\.jks|\.keystore|/etc/.*\.conf.*(password|secret|key|token|credential)|/proc/.*/environ).*"""
  AND NOT Esql.executed_command RLIKE """.*/etc/resolv\.conf.*"""
| EVAL Esql.access_type = CASE(
    Esql.executed_command RLIKE """.*/var/run/secrets/eks\.amazonaws\.com.*""", "AWS_IRSA_TOKEN",
    Esql.executed_command RLIKE """.*/var/run/secrets/azure/tokens/.*""", "AZURE_WORKLOAD_IDENTITY_TOKEN",
    Esql.executed_command RLIKE """.*/var/run/secrets/tokens/gcp-ksa/.*""", "GCP_WORKLOAD_IDENTITY_TOKEN",
    Esql.executed_command RLIKE """.*/var/run/secrets/kubernetes\.io/serviceaccount/token.*""", "K8S_SA_TOKEN",
    Esql.executed_command RLIKE """.*/var/run/secrets/.*""", "MOUNTED_SECRET",
    Esql.executed_command RLIKE """.*\.(p12|pem|key|jks|keystore).*""", "CERTIFICATE_OR_KEY",
    Esql.executed_command RLIKE """.*/etc/kubernetes/.*""", "K8S_CONFIG",
    Esql.executed_command RLIKE """.*/var/lib/kubelet/.*""", "KUBELET_CONFIG",
    Esql.executed_command RLIKE """.*/etc/shadow.*""", "HOST_CREDENTIALS",
    Esql.executed_command RLIKE """.*/etc/passwd.*""", "USER_ENUMERATION",
    Esql.executed_command RLIKE """.*/etc/sudoers.*""", "SUDOERS_ACCESS",
    Esql.executed_command RLIKE """.*(/root|/home/[^/]+)/\.(ssh|aws|azure|kube|config/gcloud).*""", "USER_CREDENTIALS",
    Esql.executed_command RLIKE """.*/proc/.*/environ.*""", "PROCESS_ENV_SECRETS",
    Esql.executed_command RLIKE """.*/etc/.*\.conf.*(password|secret|key|token|credential).*""", "EMBEDDED_CONFIG_SECRET",
    "OTHER_SENSITIVE"
  )
| KEEP Esql.*, user.name, user_agent.original, event.*, source.ip, kubernetes.audit.*, _id, _version, _index, data_stream.namespace

// Title: defense_evasion_events_deleted.toml
// Source: detection-rules::rules/integrations/kubernetes/defense_evasion_events_deleted.toml
// Section: EQL Rule
// Rule Name: Kubernetes Events Deleted
// Author: Elastic
// Description:
// This rule detects the deletion of Kubernetes events, which can indicate an attempt to cover up malicious
// activity or misconfigurations. Adversaries may delete events to remove traces of their actions, making it
// harder for defenders to investigate and respond to incidents.
// Integration: kubernetes
// Language: eql
// UUID: 33c27b4e-8ec6-406f-b8e5-345dc024aa97
// Type: eql

any where data_stream.dataset == "kubernetes.audit_logs" and kubernetes.audit.verb == "delete" and
kubernetes.audit.objectRef.resource == "events" and kubernetes.audit.stage == "ResponseComplete"

// Title: discovery_endpoint_permission_enumeration_by_user_and_srcip.toml
// Source: detection-rules::rules/integrations/kubernetes/discovery_endpoint_permission_enumeration_by_user_and_srcip.toml
// Section: EQL Rule
// Rule Name: Kubernetes Potential Endpoint Permission Enumeration Attempt Detected
// Author: Elastic
// Description:
// This rule detects potential endpoint enumeration attempts by a single user and source IP address. By looking for a
// combination of failed/successful API requests across multiple endpoints and a limited number of documents, this rule
// can detect automated permission enumeration attempts. This behavior is uncommon for regular Kubernetes clusters.
// Integration: kubernetes
// Language: esql
// UUID: a337c3f8-e264-4eb4-9998-22669ca52791
// Type: esql

from logs-kubernetes.audit_logs-* metadata _id, _index, _version
| where kubernetes.audit.stage == "ResponseComplete" and kubernetes.audit.verb in ("get", "list", "watch", "create", "update", "patch")
| stats
  Esql.document_count = count(),
  Esql.kubernetes_audit_annotations_authorization_k8s_io_decision_count_distinct = count_distinct(`kubernetes.audit.annotations.authorization_k8s_io/decision`),
  Esql.kubernetes_audit_verb_count_distinct = count_distinct(kubernetes.audit.verb),
  Esql.kubernetes_audit_requestURI_count_distinct = count_distinct(kubernetes.audit.requestURI),
  Esql.kubernetes_audit_objectRef_resource_count_distinct = count_distinct(kubernetes.audit.objectRef.resource),

  Esql.kubernetes_audit_responseStatus_message_values = values(kubernetes.audit.responseStatus.message),
  Esql.kubernetes_audit_verb_values = values(kubernetes.audit.verb),
  Esql.kubernetes_audit_responseStatus_code_values = values(kubernetes.audit.responseStatus.code),
  Esql.kubernetes_audit_objectRef_resource_values = values(kubernetes.audit.objectRef.resource),
  Esql.kubernetes_audit_objectRef_namespace_values = values(kubernetes.audit.objectRef.namespace),
  Esql.kubernetes_audit_user_username_values = values(kubernetes.audit.user.username),
  Esql.kubernetes_audit_user_groups_values = values(kubernetes.audit.user.groups),
  Esql.kubernetes_audit_requestURI_values = values(kubernetes.audit.requestURI),
  Esql.user_agent_original_values = values(user_agent.original),
  Esql.data_stream_namespace_values = values(data_stream.namespace)

  by kubernetes.audit.user.username, kubernetes.audit.sourceIPs
| where
  Esql.kubernetes_audit_annotations_authorization_k8s_io_decision_count_distinct == 2 and
  Esql.kubernetes_audit_requestURI_count_distinct > 5 and
  Esql.kubernetes_audit_objectRef_resource_count_distinct > 3 and
  Esql.document_count < 75
| keep Esql.*, kubernetes.audit.user.username, kubernetes.audit.sourceIPs

// Title: discovery_kubernetes_multi_resource_setup_recon.toml
// Source: detection-rules::rules/integrations/kubernetes/discovery_kubernetes_multi_resource_setup_recon.toml
// Section: EQL Rule
// Rule Name: Kubernetes Multi-Resource Discovery
// Author: Elastic
// Description:
// Adversaries who land credentials in a cluster—or abuse an over-privileged token—often map the environment before
// exfiltration or privilege escalation. A practical first pass is to learn where workloads run, how the cluster is
// partitioned, and what RBAC exists at namespace vs cluster scope. Rapid `get`/`list` traffic across distinct
// API resource kinds that answer those questions (namespaces, workloads, roles, cluster-wide roles) is a common
// setup and orientation pattern for both interactive attackers and automated recon scripts. It is less typical for
// steady-state controllers, which usually touch a narrow set of resources repeatedly. This rule highlights that
// cross-resource burst from a single client fingerprint within a one-minute bucket so analysts can separate routine
// automation from potential discovery and permission reconnaissance ahead of follow-on actions.
// Integration: kubernetes
// Language: esql
// UUID: c2a91e88-4f4b-4e1d-9c7b-8fde112a9403
// Type: esql

from logs-kubernetes.audit_logs-* metadata _id, _index, _version
| eval Esql.time_interval = date_trunc(1 minute, @timestamp)
| where event.dataset == "kubernetes.audit_logs"
    and event.action in ("get", "list")
    and kubernetes.audit.objectRef.resource in ("namespaces", "nodes", "pods", "roles", "configmaps", "serviceaccounts", "clusterroles", "clusterrolebindings", "rolebindings")
    and source.ip is not null and user.name IS NOT NULL
    and not to_string(source.ip) in ("127.0.0.1", "::1")
    and not user.name rlike """(system:serviceaccount:kube-system:|eks:|system:kube-|arn:aws:sts::.*:assumed-role/AWSServiceRoleForAmazonEKS/|system:serviceaccount:kube-system:azure|system:node:aks-default|aksService).*""" 
    and not kubernetes.audit.user.username in ("system:serviceaccount:flux-system:kustomize-controller", "system:serviceaccount:flux-system:helm-controller", "system:serviceaccount:flux-system:source-controller", "system:serviceaccount:security:trivy-operator")
| stats
    Esql.unique_resources = count_distinct(kubernetes.audit.objectRef.resource),
    Esql.enumerated_resources = values(kubernetes.audit.objectRef.resource),
    Esql.enumerated_namespaces = values(kubernetes.audit.objectRef.namespace),
    Esql.decisions = values(`kubernetes.audit.annotations.authorization_k8s_io/decision`)
  by user.name, kubernetes.audit.user.username, source.ip, user_agent.original, Esql.time_interval
| where Esql.unique_resources >= 3
| keep Esql.*, kubernetes.audit.user.username, user.name, source.ip, user_agent.original

// Title: execution_anonymous_create_update_patch_pod_request.toml
// Source: detection-rules::rules/integrations/kubernetes/execution_anonymous_create_update_patch_pod_request.toml
// Section: EQL Rule
// Rule Name: Kubernetes Anonymous User Create/Update/Patch Pods Request
// Author: Elastic
// Description:
// This rule detects attempts to create, update, or patch pods by an anonymous user. An anonymous user is a user that
// is not authenticated or authorized to access the Kubernetes API server. Creating, updating, or patching pods is a common
// activity for attackers to gain access to the cluster and execute commands.
// Integration: kubernetes
// Language: eql
// UUID: 3a01e5c6-ce01-46d7-ac9f-52dc349695fb
// Type: eql

any where data_stream.dataset == "kubernetes.audit_logs" and (
    kubernetes.audit.user.username in ("system:anonymous", "system:unauthenticated") or
    kubernetes.audit.user.username == null or
    kubernetes.audit.user.username == ""
  ) and kubernetes.audit.level in ("RequestResponse", "ResponseComplete", "Request") and kubernetes.audit.verb in ("create", "update", "patch") and
kubernetes.audit.objectRef.resource == "pods"

// Title: execution_forbidden_creation_request.toml
// Source: detection-rules::rules/integrations/kubernetes/execution_forbidden_creation_request.toml
// Section: EQL Rule
// Rule Name: Kubernetes Forbidden Creation Request
// Author: Elastic
// Description:
// This rule detects attempts to create resources in Kubernetes clusters that are forbidden by the authorization policy. It
// specifically looks for creation requests that are denied with a "forbid" decision, indicating that the user or service
// account does not have the necessary permissions to perform the action. This activity is commonly associated with
// adversaries attempting to create resources in a Kubernetes environment without proper authorization, which can lead to
// unauthorized access, manipulation of cluster resources, lateral movement and/or privilege escalation.
// Integration: kubernetes
// Language: eql
// UUID: ec81962e-4bc8-48e6-bfb0-545fc97d8f6a
// Type: eql

any where data_stream.dataset == "kubernetes.audit_logs" and kubernetes.audit.verb == "create" and
kubernetes.audit.stage == "ResponseComplete" and `kubernetes.audit.annotations.authorization_k8s_io/decision` == "forbid"

// Title: execution_kubernetes_pod_exec_curl_wget_https.toml
// Source: detection-rules::rules/integrations/kubernetes/execution_kubernetes_pod_exec_curl_wget_https.toml
// Section: EQL Rule
// Rule Name: Kubernetes Pod Exec with Curl or Wget to HTTPS
// Author: Elastic
// Description:
// Detects pod or attach exec API calls where the decoded request query implies curl or wget fetching an
// https URL. Attackers with permission to exec into workloads often run one-liners to stage tooling, pull
// scripts or binaries, or exfiltrate data over HTTPS—activity that should be rare compared to shells, debuggers, or
// expected health checks. The rule decodes the audit requestURI, reconstructs a readable command string from
// repeated command parameters, and applies noise filters for common cluster health and OIDC/JWKS endpoints so
// benign automation is less likely to alert.
// Integration: kubernetes
// Language: esql
// UUID: c9d4e8f1-2a3b-4c5d-8e9f-0a1b2c3d4e5f
// Type: esql

FROM logs-kubernetes.audit_logs-* metadata _id, _index, _version
| WHERE kubernetes.audit.objectRef.subresource == "exec"
  AND kubernetes.audit.requestURI LIKE "*command=*"
| EVAL Esql.decoded_uri = URL_DECODE(kubernetes.audit.requestURI)
| GROK Esql.decoded_uri "%{DATA}/exec\\?%{DATA:raw_commands}&(?:container|stdin|stdout|stderr)=%{GREEDYDATA}"
| EVAL command = REPLACE(raw_commands, "command=", "")
| EVAL command = REPLACE(command, "&", " ")
| EVAL Esql.executed_command = REPLACE(command, "\\+", " ")
| WHERE Esql.executed_command IS NOT NULL 
  AND Esql.executed_command RLIKE """.*(curl.*https|wget.*https).*"""
  AND NOT Esql.executed_command RLIKE """.*(/api/v1/health|/healthz|/readyz|/livez|127\.0\.0\.1|localhost|/openid/v1/jwks|/openid-connect/certs|/.well-known/openid-configuration|/.well-known/jwks\.json|kubernetes\.default\.svc).*"""
| KEEP Esql.*, user.name, user_agent.original, event.*, source.ip, kubernetes.audit.*, _id, _version, _index, data_stream.namespace

// Title: execution_kubernetes_pod_exec_potential_reverse_shell.toml
// Source: detection-rules::rules/integrations/kubernetes/execution_kubernetes_pod_exec_potential_reverse_shell.toml
// Section: EQL Rule
// Rule Name: Kubernetes Pod Exec Potential Reverse Shell
// Author: Elastic
// Description:
// Flags exec into a pod when the URL-decoded command payload resembles reverse-shell or bind-shell
// one-liners invocation patterns. Legitimate debug sessions sometimes use similar building blocks, but together 
// these patterns align with post-exploitation interactive access and command-and-control.
// Integration: kubernetes
// Language: esql
// UUID: f1a2b3c4-d5e6-4789-a012-3456789abc01
// Type: esql

FROM logs-kubernetes.audit_logs-* metadata _id, _index, _version
| WHERE kubernetes.audit.objectRef.subresource == "exec"
  AND kubernetes.audit.requestURI LIKE "*command=*"
| EVAL Esql.decoded_uri = URL_DECODE(kubernetes.audit.requestURI)
| GROK Esql.decoded_uri "%{DATA}/exec\\?%{DATA:raw_commands}&(?:container|stdin|stdout|stderr)=%{GREEDYDATA}"
| EVAL command = REPLACE(raw_commands, "command=", "")
| EVAL command = REPLACE(command, "&", " ")
| EVAL Esql.executed_command = REPLACE(command, "\\+", " ")
| WHERE Esql.executed_command IS NOT NULL AND command RLIKE """.*(/dev/tcp/|/dev/udp/|zsh/net/tcp|zsh/net/udp|nc\s+-e|ncat\s+-e|netcat\s+-e|nc\s.*\s-c\s|mkfifo|socat\s.*exec|socat\s.*pty|bash\s+-i\s+>&|0>&1|>&\s*/dev/tcp|import\s+socket.*connect|import\s+pty.*spawn|socket\.socket.*connect|IO::Socket::INET|fsockopen|TCPSocket\.new|/inet/tcp/).*""" AND 
  // local service health check patterns
  NOT command RLIKE """.*/dev/tcp/(localhost|127\.0\.0\.1)/(8080|8443|9090|3000|5000|8888|80|443).*"""
| KEEP Esql.*, user.name, user_agent.original, event.*, source.ip, kubernetes.audit.*, _id, _version, _index, data_stream.namespace

// Title: execution_user_exec_to_pod.toml
// Source: detection-rules::rules/integrations/kubernetes/execution_user_exec_to_pod.toml
// Section: EQL Rule
// Rule Name: Kubernetes User Exec into Pod
// Author: Elastic
// Description:
// This rule detects a user attempt to establish a shell session into a pod using the 'exec' command. Using the 'exec'
// command in a pod allows a user to establish a temporary shell session and execute any process/commands in the pod. An
// adversary may call bash to gain a persistent interactive shell which will allow access to any data the pod has
// permissions to, including secrets.
// Integration: kubernetes
// Language: eql
// UUID: 14de811c-d60f-11ec-9fd7-f661ea17fbce
// Type: eql

any where data_stream.dataset == "kubernetes.audit_logs" and kubernetes.audit.verb in ("get", "create") and
kubernetes.audit.objectRef.subresource == "exec" and kubernetes.audit.stage in ("ResponseComplete", "ResponseStarted") and
kubernetes.audit.level == "Request" and `kubernetes.audit.annotations.authorization_k8s_io/decision` == "allow" and
not (
  (kubernetes.audit.objectRef.namespace == "trident" and kubernetes.audit.objectRef.name like "trident-controller-*") or
  (kubernetes.audit.objectRef.namespace == "vuls" and kubernetes.audit.requestURI like "/api/v1/namespaces/vuls/pods/vuls-*/exec?command=sh&command=-c&command=*+%2Fvuls%2Fresults*") or
  (kubernetes.audit.objectRef.namespace == "git-runners" and kubernetes.audit.requestURI like (
     "/api/v1/namespaces/git-runners/pods/runner-*/exec?command=sh&command=-c&command=if+%5B+-x+%2Fusr%2Flocal%2Fbin%2Fbash+%5D%3B+then%0A%09exec+%2Fusr%2Flocal%2Fbin%2Fbash+%0Aelif+%5B+-x+%2Fusr%2Fbin%2Fbash+%5D%3B+then%0A%09exec+%2Fusr%2Fbin%2Fbash+%0Aelif+%5B+-x+%2Fbin%2Fbash+%5D%3B+then%0A%09exec+%2Fbin%2Fbash+%0Aelif+%5B+-x+%2Fusr%2Flocal%2Fbin%2Fsh+%5D%3B+then%0A%09exec+%2Fusr%2Flocal%2Fbin%2Fsh+%0Aelif+%5B+-x+%2Fusr%2Fbin%2Fsh+%5D%3B+then%0A%09exec+%2Fusr%2Fbin%2Fsh+%0Aelif+%5B+-x+%2Fbin%2Fsh+%5D%3B+then%0A%09exec+%2Fbin%2Fsh+%0Aelif+%5B+-x+%2Fbusybox%2Fsh+%5D%3B+then%0A%09exec+%2Fbusybox%2Fsh+%0Aelse%0A%09echo+shell+not+found%0A%09exit+1%0Afi%0A%0A&container=*&container=*&stderr=true&stdin=true&stdout=true",
     "/api/v1/namespaces/git-runners/pods/runner-*/exec?command=gitlab-runner-helper&command=read-logs&command=--path&command=%2Flogs-*%2Foutput.log&command=--offset&command=0&command=--wait-file-timeout&command=1m0s&container=*&container=*&stderr=true&stdout=true"
  )) or
  (kubernetes.audit.objectRef.namespace == "elasticsearch-cluster" and kubernetes.audit.requestURI like (
    "/api/v1/namespaces/elasticsearch-cluster/pods/*/exec?command=df&command=-h&container=elasticsearch&stdin=true&stdout=true&tty=true",
    "/api/v1/namespaces/elasticsearch-cluster/pods/*/exec?command=df&command=-h&container=elasticsearch&stderr=true&stdout=true",
    "/api/v1/namespaces/elasticsearch-cluster/pods/*/exec?command=df&command=-h&container=kibana&stderr=true&stdout=true"
  )) or
  (kubernetes.audit.objectRef.namespace == "kube-system" and kubernetes.audit.requestURI like (
    "/api/v1/namespaces/kube-system/pods/*/exec?command=%2Fproxy-agent&command=--help&container=konnectivity-agent&stderr=true&stdout=true",
    "api/v1/namespaces/kube-system/pods/*/exec?command=cilium&command=endpoint&command=list&command=-o&command=json&container=cilium-agent&stderr=true&stdout=true",
    "/api/v1/namespaces/kube-system/pods/*/exec?command=cilium&command=status&command=-o&command=json&container=cilium-agent&stderr=true&stdout=true",
    "/api/v1/namespaces/kube-system/pods/*/exec?command=sh&command=-c&command=clear%3B+%28bash+%7C%7C+ash+%7C%7C+sh%29&container=*&stdin=true&stdout=true&tty=true"
  ))
)

// Title: persistence_sensitive_role_creation_or_modification.toml
// Source: detection-rules::rules/integrations/kubernetes/persistence_sensitive_role_creation_or_modification.toml
// Section: EQL Rule
// Rule Name: Kubernetes Creation or Modification of Sensitive Role
// Author: Elastic
// Description:
// Detects the creation or modification of Kubernetes Roles or ClusterRoles that grant high-risk permissions,
// such as wildcard access or RBAC escalation verbs (e.g., bind, escalate, impersonate), which may enable
// privilege escalation or unauthorized access within the cluster.
// Integration: kubernetes
// Language: esql
// UUID: 0fb25791-d8d4-42ab-8fc7-4954642de85f
// Type: esql

FROM logs-kubernetes.audit_logs-* metadata _id, _index, _version
| WHERE
  kubernetes.audit.objectRef.resource in ("roles", "clusterroles") and
  kubernetes.audit.verb in ("create", "update", "patch") and
  `kubernetes.audit.annotations.authorization_k8s_io/decision` == "allow" and
  kubernetes.audit.level == "RequestResponse" and kubernetes.audit.stage == "ResponseComplete" and
  not kubernetes.audit.sourceIPs in ("::1", "127.0.0.1") and 
  not (user.name like "eks:*" and kubernetes.audit.objectRef.name like "eks:*") and 
  not (user.name == "aksService" and event.action == "create" and kubernetes.audit.objectRef.name like "aks:*") and 
  not (user.name == "system:serviceaccount:kube-system:clusterrole-aggregation-controller" and  kubernetes.audit.objectRef.name in ("admin", "edit") and event.action == "patch") and 
  (
    // using requestObject
    KQL(""" kubernetes.audit.requestObject.rules.verbs:("*" or "escalate" or "bind" or "impersonate") """) or 
    KQL(""" kubernetes.audit.requestObject.rules.verbs: ("*" or "create" or "patch" or "update") and kubernetes.audit.requestObject.rules.resources:("*" or "clusterroles" or "clusterrolebindings" or "roles" or "rolebindings" or "pods/exec" or "serviceaccounts/token" or "nodes/proxy" or "daemonsets") """) or 
    KQL(""" kubernetes.audit.requestObject.rules.verbs: ("*" or "get" or "list") and kubernetes.audit.requestObject.rules.resources:("*" or "secrets") """) or

    // using responseObject
    KQL(""" kubernetes.audit.responseObject.rules.verbs:("*" or "escalate" or "bind" or "impersonate") """) or 
    KQL(""" kubernetes.audit.responseObject.rules.verbs: ("*" or "create" or "patch" or "update") and kubernetes.audit.responseObject.rules.resources:("*" or "clusterroles" or "clusterrolebindings" or "roles" or "rolebindings" or "pods/exec" or "serviceaccounts/token" or "nodes/proxy" or "daemonsets") """) or 
    KQL(""" kubernetes.audit.responseObject.rules.verbs: ("*" or "get" or "list") and kubernetes.audit.responseObject.rules.resources:("*" or "secrets") """)
  )
| keep user.name, user_agent.original, event.action, source.ip, kubernetes.audit.verb, kubernetes.audit.objectRef.resource, kubernetes.audit.objectRef.name, kubernetes.audit.requestURI, kubernetes.audit.user.username, kubernetes.audit.user.groups, `kubernetes.audit.annotations.authorization_k8s_io/decision`, event.original, _id, _version, _index, data_stream.namespace

// Title: privilege_escalation_role_patch_wildcard_verbs_resources_response.toml
// Source: detection-rules::rules/integrations/kubernetes/privilege_escalation_role_patch_wildcard_verbs_resources_response.toml
// Section: EQL Rule
// Rule Name: Kubernetes RBAC Wildcard Elevation on Existing Role
// Author: Elastic
// Description:
// Flags an existing Role or ClusterRole being changed (patch or update) so the effective rules become cluster-admin-like:
// wildcard on every API resource and wildcard on every verb. That is usually a deliberate privilege expansion, not a typo.
// RequestResponse audit and the response body are required so the detection reads the merged role after apply; loopback
// source IPs are ignored.
// Integration: kubernetes
// Language: esql
// UUID: c8f4a2e1-9b3d-4c7e-8f2a-1d0e5b6c7a89
// Type: esql

from logs-kubernetes.audit_logs-* metadata _id, _index, _version
| where
  kubernetes.audit.objectRef.resource in ("roles", "clusterroles") and
  kubernetes.audit.verb in ("update", "patch") and
  `kubernetes.audit.annotations.authorization_k8s_io/decision` == "allow" and
  kubernetes.audit.level == "RequestResponse" and
  kubernetes.audit.stage == "ResponseComplete" and
  kubernetes.audit.sourceIPs is not null and
  not kubernetes.audit.sourceIPs in ("::1", "127.0.0.1") and
  KQL(""" kubernetes.audit.responseObject.rules.verbs:"*" and kubernetes.audit.responseObject.rules.resources:"*" """)
| keep user.name, user_agent.original, event.action, source.ip, kubernetes.audit.verb, kubernetes.audit.objectRef.resource, kubernetes.audit.objectRef.name, kubernetes.audit.requestURI, kubernetes.audit.user.username, kubernetes.audit.user.groups, `kubernetes.audit.annotations.authorization_k8s_io/decision`, event.original, _id, _version, _index, data_stream.namespace

// Title: privilege_escalation_sensitive_rbac_change_followed_by_workload_modification.toml
// Source: detection-rules::rules/integrations/kubernetes/privilege_escalation_sensitive_rbac_change_followed_by_workload_modification.toml
// Section: EQL Rule
// Rule Name: Kubernetes Sensitive RBAC Change Followed by Workload Modification
// Author: Elastic
// Description:
// Detects a sequence where a principal creates or modifies a Role/ClusterRole to include high-risk permissions
// (e.g., wildcard access or escalation verbs) and then creates or patches a workload resource (DaemonSet,
// Deployment, or CronJob) shortly after, which may indicate RBAC-based privilege escalation followed by payload
// deployment. This pattern is often used by adversaries to gain unauthorized access to sensitive resources and
// deploy malicious payloads.
// Integration: kubernetes
// Language: eql
// UUID: 3c82bf84-5941-495b-ac41-0302f28e1a90
// Type: eql

sequence by user.name with maxspan=5m
  [any where data_stream.dataset == "kubernetes.audit_logs" and
   `kubernetes.audit.annotations.authorization_k8s_io/decision` == "allow" and
    kubernetes.audit.objectRef.resource in ("roles", "clusterroles") and
    kubernetes.audit.verb in ("create", "update", "patch")]
  [any where data_stream.dataset == "kubernetes.audit_logs" and
   `kubernetes.audit.annotations.authorization_k8s_io/decision` == "allow" and
    kubernetes.audit.objectRef.resource in ("daemonsets", "deployments", "cronjobs") and
    kubernetes.audit.verb in ("create", "patch") and
    /* reduce control-plane / bootstrap noise */
    not kubernetes.audit.user.groups == "system:masters"
  ]

// Title: initial_access_azure_monitor_callback_phishing_email.toml
// Source: detection-rules::rules/integrations/microsoft_exchange_online_message_trace/initial_access_azure_monitor_callback_phishing_email.toml
// Section: EQL Rule
// Rule Name: M365 Azure Monitor Alert Email with Financial or Billing Theme
// Author: Elastic
// Description:
// Detects Azure Monitor alert notification emails with financial or billing themed subject lines delivered to organization
// users. Adversaries abuse Azure Monitor alert rules to deliver callback phishing emails from Microsoft's legitimate
// azure-noreply@microsoft.com address. Because the emails originate from Microsoft's own infrastructure, they pass SPF,
// DKIM, and DMARC checks, bypassing email security filters and increasing victim trust. The attacker embeds a fraudulent
// billing or security lure in the alert rule description, which is rendered in the notification email body. Observed
// subject patterns include invoice numbers, payment references, and order confirmations.
// Integration: microsoft_exchange_online_message_trace
// Language: esql
// UUID: a6129187-c47b-48ab-a412-67a44836d918
// Type: esql

from logs-microsoft_exchange_online_message_trace.* metadata _id, _version, _index

// Filter for Azure Monitor notification emails with financial/billing themed subjects
| where data_stream.dataset == "microsoft_exchange_online_message_trace.log"
    and email.from.address == "azure-noreply@microsoft.com"
    and event.outcome in ("success", "unknown")
    and email.subject like "*Azure Monitor alert*"
    and (
        email.subject like "*INV-*"
        or email.subject like "*invoice*"
        or email.subject like "*payment*"
        or email.subject like "*order-*"
        or email.subject like "*purchase*"
        or email.subject like "*funds*"
        or email.subject like "*receipt*"
        or email.subject like "*billing*"
        or email.subject like "*transaction*"
        or email.subject like "*refund*"
        or email.subject like "*charge*"
        or email.subject like "*subscription*"
        or email.subject like "*renewal*"
        or email.subject like "*overdue*"
        or email.subject like "*past due*"
        or email.subject like "*amount due*"
        or email.subject like "*wire transfer*"
        or email.subject like "*bank account*"
        or email.subject like "*credit card*"
        or email.subject like "*financial*"
        or email.subject like "*remittance*"
    )

| keep *

// Title: collection_exchange_new_inbox_rule.toml
// Source: detection-rules::rules/integrations/o365/collection_exchange_new_inbox_rule.toml
// Section: EQL Rule
// Rule Name: M365 Exchange Inbox Forwarding Rule Created
// Author: Elastic, Gary Blackwell, Austin Songer, Marco Pedrinazzi
// Description:
// Identifies when a new Inbox forwarding rule is created in Microsoft 365. Inbox rules process messages in the Inbox based
// on conditions and take actions. In this case, the rules will forward the emails to a defined address. Attackers can
// abuse Inbox Rules to intercept and exfiltrate email data without making organization-wide configuration changes or
// having the corresponding privileges.
// Integration: o365
// Language: eql
// UUID: ec8efb0c-604d-42fa-ac46-ed1cfbc38f78
// Type: eql

web where
    event.provider == "Exchange" and
    event.action in (
        "New-InboxRule",
        "Set-InboxRule",
        "Set-Mailbox",
        "Set-TransportRule",
        "New-TransportRule"
    ) and event.outcome == "success" and
    (
        (?o365.audit.Parameters.ForwardTo != null and not endsWith~(?o365.audit.Parameters.ForwardTo, user.domain)) or
        (?o365.audit.Parameters.ForwardAsAttachmentTo != null and not endsWith~(?o365.audit.Parameters.ForwardAsAttachmentTo, user.domain)) or
        (?o365.audit.Parameters.ForwardingAddress != null and not endsWith~(?o365.audit.Parameters.ForwardingAddress, user.domain)) or
        (?o365.audit.Parameters.ForwardingSmtpAddress != null and not endsWith~(?o365.audit.Parameters.ForwardingSmtpAddress, user.domain)) or
        (?o365.audit.Parameters.RedirectTo != null and not endsWith~(?o365.audit.Parameters.RedirectTo, user.domain)) or
        (?o365.audit.Parameters.RedirectToRecipients != null and not endsWith~(?o365.audit.Parameters.RedirectToRecipients, user.domain)) or
        (?o365.audit.Parameters.RedirectMessageTo != null and not endsWith~(?o365.audit.Parameters.RedirectMessageTo, user.domain)) or
        (?o365.audit.Parameters.BlindCopyTo != null and not endsWith~(?o365.audit.Parameters.BlindCopyTo, user.domain))
    )

// Title: credential_access_entra_id_device_reg_via_oauth_redirection.toml
// Source: detection-rules::rules/integrations/o365/credential_access_entra_id_device_reg_via_oauth_redirection.toml
// Section: EQL Rule
// Rule Name: M365 Identity OAuth Flow by User Sign-in to Device Registration
// Author: Elastic
// Description:
// Identifies attempts to register a new device in Microsoft Entra ID after OAuth authentication with authorization code
// grant. Adversaries may use OAuth phishing techniques to obtain an OAuth authorization code, which can then be exchanged
// for access and refresh tokens. This rule detects a sequence of events where a user principal authenticates via OAuth,
// followed by a device registration event, indicating potential misuse of the OAuth flow to establish persistence or
// access resources.
// Integration: o365
// Language: eql
// UUID: fcd2e4be-6ec4-482f-9222-6245367cd738
// Type: eql

sequence by related.user with maxspan=30m
[authentication where event.action == "UserLoggedIn" and
 o365.audit.ExtendedProperties.RequestType == "OAuth2:Authorize" and o365.audit.ExtendedProperties.ResultStatusDetail == "Redirect" and
 o365.audit.UserType: ("0", "2", "3", "10")] // victim source.ip
[authentication where event.action == "UserLoggedIn" and
 o365.audit.ExtendedProperties.RequestType == "OAuth2:Token" and o365.audit.ExtendedProperties.ResultStatusDetail == "Success"] // attacker source.ip to convert oauth code to token
[web where data_stream.dataset == "o365.audit" and event.action == "Add registered users to device."] // user.name is captured in related.user

// Title: defense_evasion_exchange_inbox_rule_obfuscated_name.toml
// Source: detection-rules::rules/integrations/o365/defense_evasion_exchange_inbox_rule_obfuscated_name.toml
// Section: EQL Rule
// Rule Name: M365 Exchange Inbox Rule with Obfuscated Name
// Author: Elastic
// Description:
// Identifies when a Microsoft Exchange inbox rule is created or modified with a name composed only of special characters.
// Adversaries may use obfuscated inbox rule names to evade detection, hide malicious forwarding or deletion rules, or blend
// in with benign audit noise. The rule name is parsed from "o365.audit.ObjectId", which encodes the mailbox identity and
// rule name separated by a backslash.
// Integration: o365
// Language: esql
// UUID: 1c3d9346-4591-4894-935c-dad2824850f2
// Type: esql

from logs-o365.audit-* metadata _id, _version, _index
| where
    data_stream.dataset == "o365.audit" and
    event.provider == "Exchange" and
    event.action in ("New-InboxRule", "Set-InboxRule") and
    event.outcome == "success" and
    o365.audit.ObjectId is not null
| grok o365.audit.ObjectId """.*\\\\(?<Esql.inbox_rule_name>.*)$"""
// only special chars in inbox rule name
| where Esql.inbox_rule_name rlike """[!@#$%^&*()_+={[\]|\\:;"'<,>.?/~` \-]+"""
| keep
    @timestamp,
    _id,
    _version,
    _index,
    Esql.inbox_rule_name,
    o365.audit.ObjectId,
    o365.audit.UserId,
    o365.audit.ApplicationId,
    user.name,
    user.domain,
    event.action,
    source.ip,
    source.as.number,
    source.as.organization.name,
    o365.audit.Parameters.ForwardTo,
    o365.audit.Parameters.ForwardAsAttachmentTo,
    o365.audit.Parameters.RedirectTo

// Title: defense_evasion_mfa_notification_email_deleted.toml
// Source: detection-rules::rules/integrations/o365/defense_evasion_mfa_notification_email_deleted.toml
// Section: EQL Rule
// Rule Name: M365 Exchange MFA Notification Email Deleted or Moved
// Author: Elastic
// Description:
// Identifies when an MFA enrollment, registration, or security notification email is deleted or moved to deleted items in
// Microsoft 365 Exchange. Adversaries who compromise accounts and register their own MFA device often delete the
// notification emails to cover their tracks and prevent the legitimate user from noticing the unauthorized change. This
// technique is commonly observed in business email compromise (BEC) and account takeover attacks.
// Integration: o365
// Language: eql
// UUID: c9636a6e-125e-11f1-9cd3-f661ea17fbce
// Type: eql

web where data_stream.dataset == "o365.audit" and
    event.provider == "Exchange" and
    event.action in ("SoftDelete", "HardDelete", "MoveToDeletedItems") and
    event.outcome == "success" and
    (
        o365.audit.AffectedItems.Subject like~ (
            /* new + (mfa|multi-|factor|method|device|security) */
            "*new mfa*", "*new multi*", "*new factor*", "*new method*", "*new device*", "*new security*",
            /* 2fa and 2-step */
            "*2fa*", "*2-step*",
            /* mfa + action verbs */
            "*mfa enroll*", "*mfa register*", "*mfa added*", "*mfa change*",
            "*mfa verify*", "*mfa update*", "*mfa activate*", "*mfa configure*", "*mfa setup*",
            /* factor + action verbs */
            "*factor enroll*", "*factor register*", "*factor added*", "*factor change*",
            "*factor verify*", "*factor update*", "*factor activate*", "*factor configure*", "*factor setup*",
            /* method + action verbs */
            "*method enroll*", "*method register*", "*method added*", "*method change*",
            "*method verify*", "*method update*", "*method activate*", "*method configure*", "*method setup*",
            /* device + action verbs */
            "*device enroll*", "*device register*", "*device added*", "*device change*",
            "*device verify*", "*device update*", "*device activate*", "*device configure*", "*device setup*",
            /* security + action verbs */
            "*security enroll*", "*security register*", "*security added*", "*security change*",
            "*security verify*", "*security update*", "*security activate*", "*security configure*", "*security setup*",
            /* Additional security notifications */
            "*authenticator*", "*verification code*", "*security info*", "*security alert*"
        ) and not
        o365.audit.AffectedItems.Subject like~ ("*sign-in*", "*sign in*", "*log-in*", "*log in*", "*logon*")
    )

// Title: discovery_sharepoint_sensitive_term_search.toml
// Source: detection-rules::rules/integrations/o365/discovery_sharepoint_sensitive_term_search.toml
// Section: EQL Rule
// Rule Name: M365 SharePoint Search for Sensitive Content
// Author: Elastic
// Description:
// Identifies search queries in SharePoint containing sensitive terms related to credentials, financial data,
// PII, legal matters, or infrastructure information. Adversaries who compromise user accounts often search for high-value
// files before exfiltration. This rule detects searches containing terms across multiple sensitivity categories,
// regardless of the access method (browser, PowerShell, or API). The actual search query text is analyzed against a
// curated list of sensitive terms to identify potential reconnaissance activity.
// Integration: o365
// Language: eql
// UUID: 4f2654e4-125b-11f1-af7d-f661ea17fbce
// Type: eql

web where data_stream.dataset == "o365.audit" and
    event.provider == "SharePoint" and
    event.action == "SearchQueryPerformed" and
    event.outcome == "success" and
    o365.audit.SearchQueryText != null and
    o365.audit.SearchQueryText != "" and
    o365.audit.SearchQueryText like~ (
        /* Credentials and Secrets */
        "*password*", "*credential*", "*secret*", "*api key*", "*apikey*",
        "*token*", "*private key*", "*certificate*", "*ssh*", "*aws*",
        "*azure*", "*gcp*", "*oauth*", "*bearer*", "*connection string*",
        "*access key*", "*secret key*",
        /* Financial */
        "*salary*", "*payroll*", "*compensation*", "*budget*", "*revenue*",
        "*financial*", "*banking*", "*invoice*", "*wire transfer*", "*account number*",
        "*credit card*", "*routing number*", "*profit*", "*expense*", "*1099*",
        /* Legal and Compliance */
        "*confidential*", "*privileged*", "*attorney*", "*legal hold*", "*settlement*",
        "*contract*", "*nda*", "*merger*", "*acquisition*", "*litigation*",
        "*subpoena*", "*trade secret*", "*intellectual property*", "*proprietary*",
        "*internal*", "*proposal*", "*poc*",
        /* HR and PII */
        "*ssn*", "*social security*", "*employee*", "*personnel*", "*performance review*",
        "*termination*", "*tax*", "*w2*", "*benefits*", "*background check*",
        "*medical*", "*hipaa*", "*passport*", "*driver license*", "*dob*",
        /* Infrastructure and IT */
        "*admin*", "*root*", "*vpn*", "*firewall*", "*network diagram*",
        "*architecture*", "*topology*", "*production*", "*database*", "*config*",
        "*backup*", "*disaster recovery*", "*vulnerability*", "*pentest*", "*security audit*",
        "*salesforce*"
    )

// Title: credential_access_okta_aitm_session_cookie_replay.toml
// Source: detection-rules::rules/integrations/okta/credential_access_okta_aitm_session_cookie_replay.toml
// Section: EQL Rule
// Rule Name: Okta AiTM Session Cookie Replay
// Author: Elastic
// Description:
// Detects potential Adversary-in-the-Middle (AiTM) session cookie replay attacks against Okta. This rule identifies when
// an Okta session is used from multiple IP addresses or with suspicious non-browser user agents after initial
// authentication. AiTM attacks capture session cookies via phishing proxies (e.g., Evilginx, Modlishka) and replay them
// from attacker infrastructure, bypassing MFA. The detection correlates session start events with subsequent policy
// evaluations or SSO attempts that occur from different IPs or programmatic user agents.
// Integration: okta
// Language: esql
// UUID: 9ed5d08f-aad6-4c03-838c-d686da887c2c
// Type: esql

FROM logs-okta.system-*

// Filter to relevant event types for AiTM detection
| WHERE
    okta.event_type IN ("user.session.start", "policy.evaluate_sign_on", "user.authentication.sso") AND
    okta.authentication_context.root_session_id IS NOT NULL AND
    okta.actor.alternate_id != "system@okta.com"

// Create event type flags
| EVAL Esql.is_session_start = okta.event_type == "user.session.start"
| EVAL Esql.is_policy_eval = okta.event_type == "policy.evaluate_sign_on"
| EVAL Esql.is_sso = okta.event_type == "user.authentication.sso"
| EVAL Esql.is_replay_event = Esql.is_policy_eval OR Esql.is_sso

// Flag suspicious non-browser user agents
| EVAL Esql.is_suspicious_ua =
    user_agent.original LIKE "python-requests*" OR
    user_agent.original LIKE "curl/*" OR
    user_agent.original LIKE "httpx*" OR
    user_agent.original LIKE "aiohttp*" OR
    user_agent.original LIKE "Go-http-client*" OR
    user_agent.original LIKE "*Headless*" OR
    user_agent.original LIKE "Java/*" OR
    user_agent.original LIKE "okhttp*"

// Aggregate by session
| STATS
    Esql.session_start_count = SUM(CASE(Esql.is_session_start, 1, 0)),
    Esql.replay_event_count = SUM(CASE(Esql.is_replay_event, 1, 0)),
    Esql.session_start_time = MIN(CASE(Esql.is_session_start, @timestamp, null)),
    Esql.first_replay_time = MIN(CASE(Esql.is_replay_event, @timestamp, null)),
    Esql.last_replay_time = MAX(CASE(Esql.is_replay_event, @timestamp, null)),
    Esql.session_start_ip = MAX(CASE(Esql.is_session_start, okta.client.ip, null)),
    Esql.session_start_ua = MAX(CASE(Esql.is_session_start, user_agent.original, null)),
    Esql.suspicious_ua_count = SUM(CASE(Esql.is_suspicious_ua, 1, 0)),
    Esql.okta_client_ip_count_distinct = COUNT_DISTINCT(okta.client.ip),
    Esql.user_agent_count_distinct = COUNT_DISTINCT(user_agent.original),
    Esql.okta_client_ip_values = VALUES(okta.client.ip),
    Esql.user_agent_values = VALUES(user_agent.original),
    Esql.okta_event_type_values = VALUES(okta.event_type),
    Esql.okta_outcome_result_values = VALUES(okta.outcome.result),
    Esql.source_geo_country_name_values = VALUES(source.geo.country_name),
    Esql.source_geo_city_name_values = VALUES(source.geo.city_name),
    Esql.okta_debug_context_debug_data_risk_level_values = VALUES(okta.debug_context.debug_data.risk_level),
    Esql.okta_debug_context_debug_data_risk_reasons_values = VALUES(okta.debug_context.debug_data.risk_reasons)
  BY okta.authentication_context.root_session_id, okta.actor.alternate_id

// Detection conditions
| WHERE
    Esql.session_start_count >= 1
    AND Esql.replay_event_count >= 1
    AND Esql.first_replay_time > Esql.session_start_time
    AND (
            (
                Esql.okta_client_ip_count_distinct > 1 OR Esql.user_agent_count_distinct > 1
            ) AND Esql.suspicious_ua_count > 0
        )

| SORT Esql.session_start_time DESC
| KEEP Esql.*, okta.authentication_context.root_session_id, okta.actor.alternate_id

// Title: credential_access_okta_authentication_for_multiple_users_with_the_same_device_token_hash.toml
// Source: detection-rules::rules/integrations/okta/credential_access_okta_authentication_for_multiple_users_with_the_same_device_token_hash.toml
// Section: EQL Rule
// Rule Name: Multiple Okta User Authentication Events with Same Device Token Hash
// Author: Elastic
// Description:
// Detects when a high number of Okta user authentication events are reported for multiple users in a short time frame.
// Adversaries may attempt to launch a credential stuffing or password spraying attack from the same device by using a list
// of known usernames and passwords to gain unauthorized access to user accounts.
// Integration: okta
// Language: esql
// UUID: 95b99adc-2cda-11ef-84e1-f661ea17fbce
// Type: esql

from logs-okta*
| where
    data_stream.dataset == "okta.system" and
    (event.action like "user.authentication.*" or event.action == "user.session.start") and
    okta.debug_context.debug_data.dt_hash != "-" and
    okta.outcome.reason == "INVALID_CREDENTIALS"
| keep
    event.action,
    okta.debug_context.debug_data.dt_hash,
    okta.actor.id,
    okta.actor.alternate_id,
    okta.outcome.reason
| stats
    Esql.okta_actor_id_count_distinct = count_distinct(okta.actor.id)
  by
    okta.debug_context.debug_data.dt_hash,
    okta.actor.alternate_id
| where
    Esql.okta_actor_id_count_distinct > 20
| sort
    Esql.okta_actor_id_count_distinct desc

// Title: credential_access_okta_brute_force_device_token_rotation.toml
// Source: detection-rules::rules/integrations/okta/credential_access_okta_brute_force_device_token_rotation.toml
// Section: EQL Rule
// Rule Name: Potential Okta Brute Force (Device Token Rotation)
// Author: Elastic
// Description:
// Detects potential brute force attacks against a single Okta user account where excessive unique device token hashes
// are generated, indicating automated tooling that fails to persist browser cookies between attempts.
// Integration: okta
// Language: esql
// UUID: 23f18264-2d6d-11ef-9413-f661ea17fbce
// Type: esql

FROM logs-okta.system-* METADATA _id, _version, _index
| WHERE
    data_stream.dataset == "okta.system"
    AND (event.action LIKE "user.authentication.*" OR event.action == "user.session.start")
    AND okta.outcome.reason IN ("INVALID_CREDENTIALS", "LOCKED_OUT")
    AND okta.actor.alternate_id IS NOT NULL
    // Primary authn endpoint; sessions API provides additional coverage
    AND (
        okta.debug_context.debug_data.request_uri == "/api/v1/authn"
        OR okta.debug_context.debug_data.request_uri LIKE "/api/v1/sessions*"
    )
// Track whether each event has a device token
| EVAL has_dt_hash = CASE(okta.debug_context.debug_data.dt_hash IS NOT NULL, 1, 0)
// Aggregate by IP + user to detect single-user brute force
| STATS
    Esql.unique_dt_hashes = COUNT_DISTINCT(okta.debug_context.debug_data.dt_hash),
    Esql.total_attempts = COUNT(*),
    Esql.attempts_with_dt = SUM(has_dt_hash),
    Esql.unique_user_agents = COUNT_DISTINCT(okta.client.user_agent.raw_user_agent),
    Esql.first_seen = MIN(@timestamp),
    Esql.last_seen = MAX(@timestamp),
    Esql.dt_hash_values = VALUES(okta.debug_context.debug_data.dt_hash),
    Esql.event_action_values = VALUES(event.action),
    Esql.user_agent_values = VALUES(okta.client.user_agent.raw_user_agent),
    Esql.device_values = VALUES(okta.client.device),
    Esql.is_proxy_values = VALUES(okta.security_context.is_proxy),
    Esql.geo_country_values = VALUES(client.geo.country_name),
    Esql.geo_city_values = VALUES(client.geo.city_name),
    Esql.source_asn_values = VALUES(source.as.number),
    Esql.source_asn_org_values = VALUES(source.as.organization.name),
    Esql.threat_suspected_values = VALUES(okta.debug_context.debug_data.threat_suspected),
    Esql.risk_level_values = VALUES(okta.debug_context.debug_data.risk_level),
    Esql.risk_reasons_values = VALUES(okta.debug_context.debug_data.risk_reasons)
  BY okta.client.ip, okta.actor.alternate_id
// Calculate automation detection metrics (float-safe division)
| EVAL Esql.dt_coverage = Esql.attempts_with_dt * 1.0 / Esql.total_attempts,
       Esql.dt_per_attempt = Esql.unique_dt_hashes * 1.0 / Esql.total_attempts
// Detection branches:
//   A) Many unique DT hashes relative to attempts = tooling generating new tokens per attempt
//   B) High attempts + very low DT coverage = cookie-less automation (no DT sent at all)
//   C) Multiple user agents for same user = evasion or automation
| WHERE
    (Esql.unique_dt_hashes >= 7 AND Esql.total_attempts >= 10 AND Esql.dt_per_attempt >= 0.5)
    OR (Esql.total_attempts >= 12 AND Esql.dt_coverage < 0.15)
    OR (Esql.total_attempts >= 10 AND Esql.unique_user_agents >= 5)
| SORT Esql.total_attempts DESC
| KEEP Esql.*, okta.client.ip, okta.actor.alternate_id

// Title: credential_access_okta_mfa_bombing_via_push_notifications.toml
// Source: detection-rules::rules/integrations/okta/credential_access_okta_mfa_bombing_via_push_notifications.toml
// Section: EQL Rule
// Rule Name: Potential Okta MFA Bombing via Push Notifications
// Author: Elastic
// Description:
// Detects when an attacker abuses the Multi-Factor authentication mechanism by repeatedly issuing login requests until the
// user eventually accepts the Okta push notification. An adversary may attempt to bypass the Okta MFA policies configured
// for an organization to obtain unauthorized access.
// Integration: okta
// Language: eql
// UUID: 8a0fbd26-867f-11ee-947c-f661ea17fbcd
// Type: eql

sequence by okta.actor.id with maxspan=10m
  [ any
    where data_stream.dataset == "okta.system"
      and (
        okta.event_type == "user.mfa.okta_verify.deny_push"
        or (
          okta.event_type == "user.authentication.auth_via_mfa"
          and okta.debug_context.debug_data.factor == "OKTA_VERIFY_PUSH"
          and okta.outcome.reason == "INVALID_CREDENTIALS"
        )
      )
  ] with runs=5
  until
  [ any
    where data_stream.dataset == "okta.system"
      and okta.event_type in (
        "user.authentication.sso",
        "user.authentication.auth_via_mfa",
        "user.authentication.verify",
        "user.session.start"
      )
      and okta.outcome.result == "SUCCESS"
  ]

// Title: credential_access_okta_password_spray_single_source.toml
// Source: detection-rules::rules/integrations/okta/credential_access_okta_password_spray_single_source.toml
// Section: EQL Rule
// Rule Name: Potential Okta Password Spray (Single Source)
// Author: Elastic
// Description:
// Detects potential password spray attacks where a single source IP attempts authentication against multiple Okta
// user accounts with repeated attempts per user, indicating common password guessing paced to avoid lockouts.
// Integration: okta
// Language: esql
// UUID: 42bf698b-4738-445b-8231-c834ddefd8a0
// Type: esql

FROM logs-okta.system-* METADATA _id, _version, _index
| WHERE
    data_stream.dataset == "okta.system"
    AND (event.action LIKE "user.authentication.*" OR event.action == "user.session.start")
    AND okta.outcome.reason IN ("INVALID_CREDENTIALS", "LOCKED_OUT")
    AND okta.actor.alternate_id IS NOT NULL
// Build user-source context as JSON for enrichment
| EVAL Esql.user_source_info = CONCAT(
    "{\"user\":\"", okta.actor.alternate_id,
    "\",\"ip\":\"", COALESCE(okta.client.ip::STRING, "unknown"),
    "\",\"user_agent\":\"", COALESCE(okta.client.user_agent.raw_user_agent, "unknown"), "\"}"
  )
// FIRST STATS: Aggregate by (IP, user) to get per-user attempt counts
// This prevents skew from outlier users with many attempts
| STATS
    Esql.user_attempts = COUNT(*),
    Esql.user_source_info = VALUES(Esql.user_source_info),
    Esql.user_agents_per_user = VALUES(okta.client.user_agent.raw_user_agent),
    Esql.devices_per_user = VALUES(okta.client.device),
    Esql.is_proxy = VALUES(okta.security_context.is_proxy),
    Esql.geo_country = VALUES(client.geo.country_name),
    Esql.geo_city = VALUES(client.geo.city_name),
    Esql.asn_number = VALUES(source.as.number),
    Esql.asn_org = VALUES(source.as.organization.name),
    Esql.threat_suspected = VALUES(okta.debug_context.debug_data.threat_suspected),
    Esql.risk_level = VALUES(okta.debug_context.debug_data.risk_level),
    Esql.event_actions = VALUES(event.action),
    Esql.first_seen_user = MIN(@timestamp),
    Esql.last_seen_user = MAX(@timestamp)
  BY okta.client.ip, okta.actor.alternate_id
// SECOND STATS: Aggregate by IP to detect password spray pattern
// Now we can accurately measure the distribution of attempts across users
| STATS
    Esql.unique_users = COUNT(*),
    Esql.total_attempts = SUM(Esql.user_attempts),
    Esql.max_attempts_per_user = MAX(Esql.user_attempts),
    Esql.min_attempts_per_user = MIN(Esql.user_attempts),
    Esql.avg_attempts_per_user = AVG(Esql.user_attempts),
    // Spray band: 2-6 attempts per user (deliberate slow spray below lockout)
    Esql.users_in_spray_band = SUM(CASE(Esql.user_attempts >= 2 AND Esql.user_attempts <= 6, 1, 0)),
    // Also track users with only 1 attempt (stuffing-like) for differentiation
    Esql.users_with_single_attempt = SUM(CASE(Esql.user_attempts == 1, 1, 0)),
    Esql.first_seen = MIN(Esql.first_seen_user),
    Esql.last_seen = MAX(Esql.last_seen_user),
    Esql.target_users = VALUES(okta.actor.alternate_id),
    Esql.user_source_mapping = VALUES(Esql.user_source_info),
    Esql.event_action_values = VALUES(Esql.event_actions),
    Esql.user_agent_values = VALUES(Esql.user_agents_per_user),
    Esql.device_values = VALUES(Esql.devices_per_user),
    Esql.is_proxy_values = VALUES(Esql.is_proxy),
    Esql.geo_country_values = VALUES(Esql.geo_country),
    Esql.geo_city_values = VALUES(Esql.geo_city),
    Esql.source_asn_values = VALUES(Esql.asn_number),
    Esql.source_asn_org_values = VALUES(Esql.asn_org),
    Esql.threat_suspected_values = VALUES(Esql.threat_suspected),
    Esql.risk_level_values = VALUES(Esql.risk_level)
  BY okta.client.ip
// Calculate spray signature metrics
| EVAL
    // Percentage of users in the spray band (2-6 attempts)
    Esql.pct_users_in_spray_band = Esql.users_in_spray_band * 100.0 / Esql.unique_users,
    // Attack duration in minutes (spray is paced, not bursty)
    Esql.attack_duration_minutes = DATE_DIFF("minute", Esql.first_seen, Esql.last_seen)
// Password spraying detection logic:
// - Many users targeted (>= 5)
// - Hard cap below Okta lockout threshold (max <= 8 attempts per user)
// - Majority of users in spray band (2-6 attempts) (at least 60%)
// - Attack is paced over time (>= 5 minutes) (not a 10-second burst like stuffing)
// - Minimum total attempts to reduce noise
// Note: For IP rotation attacks, see "Distributed Password Spray Attack in Okta" rule
| WHERE
    Esql.unique_users >= 5
    AND Esql.total_attempts >= 15
    AND Esql.max_attempts_per_user <= 8
    AND Esql.max_attempts_per_user >= 2
    AND Esql.pct_users_in_spray_band >= 60.0
    AND Esql.attack_duration_minutes >= 5
| SORT Esql.total_attempts DESC
| KEEP Esql.*, okta.client.ip

// Title: credential_access_okta_potentially_successful_okta_bombing_via_push_notifications.toml
// Source: detection-rules::rules/integrations/okta/credential_access_okta_potentially_successful_okta_bombing_via_push_notifications.toml
// Section: EQL Rule
// Rule Name: Potentially Successful Okta MFA Bombing via Push Notifications
// Author: Elastic
// Description:
// Detects when an attacker abuses the Multi-Factor authentication mechanism by repeatedly issuing login requests until the
// user eventually accepts the Okta push notification. An adversary may attempt to bypass the Okta MFA policies configured
// for an organization to obtain unauthorized access.
// Integration: okta
// Language: eql
// UUID: 97a8e584-fd3b-421f-9b9d-9c9d9e57e9d7
// Type: eql

sequence by okta.actor.id with maxspan=10m
  [ any
    where data_stream.dataset == "okta.system"
      and (
        okta.event_type == "user.mfa.okta_verify.deny_push"
        or (
          okta.event_type == "user.authentication.auth_via_mfa"
          and okta.debug_context.debug_data.factor == "OKTA_VERIFY_PUSH"
          and okta.outcome.reason == "INVALID_CREDENTIALS"
        )
      )
  ] with runs=5
  [ any
    where data_stream.dataset == "okta.system"
      and okta.event_type in (
        "user.authentication.sso",
        "user.authentication.auth_via_mfa",
        "user.authentication.verify",
        "user.session.start"
      )
      and okta.outcome.result == "SUCCESS"
  ]

// Title: initial_access_okta_suspicious_activity_after_proxy_authentication.toml
// Source: detection-rules::rules/integrations/okta/initial_access_okta_suspicious_activity_after_proxy_authentication.toml
// Section: EQL Rule
// Rule Name: Okta Alerts Following Unusual Proxy Authentication
// Author: Elastic
// Description:
// Correlates the first occurrence of an Okta user session started via a proxy with subsequent Okta security alerts for the
// same user. Attackers frequently use proxy infrastructure (VPNs, Tor, residential proxies) to mask their origin when
// using stolen credentials, and their post-authentication activity often triggers additional detection rules.
// Integration: okta
// Language: eql
// UUID: af2d8e4c-3b7c-4e91-8f5a-6c9d0e1f2a3b
// Type: eql

sequence by user.name with maxspan=30m
    [any where event.dataset == "okta.system" and
        kibana.alert.rule.rule_id == "6f1bb4b2-7dc8-11ee-92b2-f661ea17fbcd"]
    [any where event.dataset == "okta.system" and
        kibana.alert.rule.rule_id != null and
        kibana.alert.severity != "low" and
        kibana.alert.rule.rule_id not in  (
            "6f1bb4b2-7dc8-11ee-92b2-f661ea17fbcd",
            "af2d8e4c-3b7c-4e91-8f5a-6c9d0e1f2a3b"
        )
    ]

// Title: initial_access_okta_user_sessions_started_from_different_geolocations.toml
// Source: detection-rules::rules/integrations/okta/initial_access_okta_user_sessions_started_from_different_geolocations.toml
// Section: EQL Rule
// Rule Name: Okta User Sessions Started from Different Geolocations
// Author: Elastic
// Description:
// Detects when a specific Okta actor has multiple sessions started from different geolocations. Adversaries may attempt to
// launch an attack by using a list of known usernames and passwords to gain unauthorized access to user accounts from
// different locations.
// Integration: okta
// Language: esql
// UUID: 2e56e1bc-867a-11ee-b13e-f661ea17fbcd
// Type: esql

from logs-okta*
| where
    data_stream.dataset == "okta.system" and
    (event.action like "user.authentication.*" or event.action == "user.session.start") and
    okta.security_context.is_proxy != true and
    okta.actor.id != "unknown" and
    event.outcome == "success"
| keep
    event.action,
    okta.security_context.is_proxy,
    okta.actor.id,
    okta.actor.alternate_id,
    event.outcome,
    client.geo.country_name
| stats
    Esql.client_geo_country_name_count_distinct = count_distinct(client.geo.country_name)
    by okta.actor.id, okta.actor.alternate_id
| where
    Esql.client_geo_country_name_count_distinct >= 2
| sort
    Esql.client_geo_country_name_count_distinct desc

// Title: persistence_mfa_deactivation_with_no_reactivation.toml
// Source: detection-rules::rules/integrations/okta/persistence_mfa_deactivation_with_no_reactivation.toml
// Section: EQL Rule
// Rule Name: MFA Deactivation with no Re-Activation for Okta User Account
// Author: Elastic
// Description:
// Detects multi-factor authentication (MFA) deactivation with no subsequent re-activation for an Okta user account. An
// adversary may deactivate MFA for an Okta user account in order to weaken the authentication requirements for the
// account.
// Integration: okta
// Language: eql
// UUID: cd89602e-9db0-48e3-9391-ae3bf241acd8
// Type: eql

sequence by okta.target.id with maxspan=12h
    [any where data_stream.dataset == "okta.system" and okta.event_type in ("user.mfa.factor.deactivate", "user.mfa.factor.reset_all")
        and okta.outcome.reason != "User reset SECURITY_QUESTION factor" and okta.outcome.result == "SUCCESS"]
    ![any where data_stream.dataset == "okta.system" and okta.event_type == "user.mfa.factor.activate"]

// Title: persistence_stolen_credentials_used_to_login_to_okta_account_after_mfa_reset.toml
// Source: detection-rules::rules/integrations/okta/persistence_stolen_credentials_used_to_login_to_okta_account_after_mfa_reset.toml
// Section: EQL Rule
// Rule Name: Stolen Credentials Used to Login to Okta Account After MFA Reset
// Author: Elastic
// Description:
// Detects a sequence of suspicious activities on Windows hosts indicative of credential compromise, followed by efforts to
// undermine multi-factor authentication (MFA) and single sign-on (SSO) mechanisms for an Okta user account.
// Integration: endpoint, okta
// Language: eql
// UUID: 5610b192-7f18-11ee-825b-f661ea17fbcd
// Type: eql

sequence by user.name with maxspan=12h
    [any where host.os.type == "windows" and signal.rule.threat.tactic.name == "Credential Access"]
    [any where data_stream.dataset == "okta.system" and okta.event_type == "user.mfa.factor.update"]
    [any where data_stream.dataset == "okta.system" and okta.event_type: ("user.session.start", "user.authentication*")]

// Title: defense_evasion_ml_suspicious_windows_event_high_probability.toml
// Source: detection-rules::rules/integrations/problemchild/defense_evasion_ml_suspicious_windows_event_high_probability.toml
// Section: EQL Rule
// Rule Name: Machine Learning Detected a Suspicious Windows Event with a High Malicious Probability Score
// Author: Elastic
// Description:
// A supervised machine learning model (ProblemChild) has identified a suspicious Windows process event with high
// probability of it being malicious activity. Alternatively, the model's blocklist identified the event as being
// malicious.
// Integration: problemchild, endpoint
// Language: eql
// UUID: 994e40aa-8c85-43de-825e-15f665375ee8
// Type: eql

process where ((problemchild.prediction == 1 and problemchild.prediction_probability > 0.98) or
blocklist_label == 1) and not process.args : ("*C:\\WINDOWS\\temp\\nessus_*.txt*", "*C:\\WINDOWS\\temp\\nessus_*.tmp*") and
process.parent.executable != null and not user.id in ("S-1-5-18", "S-1-5-19", "S-1-5-20") and
not process.parent.name : ("cmd.exe", "powershell.exe", "Perplexity.exe", "vmtoolsd.exe", "Code.exe", "explorer.exe", "git.exe") and
not (process.name : "msedgewebview2.exe" and process.parent.name : "msedgewebview2.exe") and
not (process.name : "opera.exe" and process.parent.name : "opera.exe") and
not (process.parent.executable : "C:\\Windows\\System32\\svchost.exe" and
     process.name : ("UCPDMgr.exe", "sdbinst.exe", "gpupdate.exe", "rundll32.exe", "taskhostw.exe", "taskeng.exe", "rdpclip.exe", "firefox.exe", "w3wp.exe")) and
not process.executable : ("C:\\Program Files\\*.exe", "C:\\Program Files (x86)\\*.exe") and
not (process.name : "MpCmdRun.exe" and process.parent.name : ("MsMpEng.exe", "MpCmdRun.exe", "svchost.exe")) and
not (process.name : "slack.exe" and process.parent.name : "slack.exe") and
not (process.name : "reg.exe" and process.parent.name : "pycharm64.exe") and
not (process.name : "reg.exe" and process.parent.name : "rider64.exe") and
not (process.name : "LogiLuUpdater.exe" and process.parent.name : "LogiOptionsMgr.exe") and
not (process.name : "chrome.exe" and process.parent.name : "node.exe" and process.command_line  : "*playwright*") and
not (process.name : "powershell.exe" and process.command_line : "*\\Zabbix_Scripts\\*.ps1*") and
not (process.parent.name : "opera.exe" and process.command_line: "*--type=renderer*")

// Title: defense_evasion_ml_suspicious_windows_event_low_probability.toml
// Source: detection-rules::rules/integrations/problemchild/defense_evasion_ml_suspicious_windows_event_low_probability.toml
// Section: EQL Rule
// Rule Name: Machine Learning Detected a Suspicious Windows Event with a Low Malicious Probability Score
// Author: Elastic
// Description:
// A supervised machine learning model (ProblemChild) has identified a suspicious Windows process event with low
// probability of it being malicious activity. Alternatively, the model's blocklist identified the event as being
// malicious.
// Integration: problemchild, endpoint
// Language: eql
// UUID: 13e908b9-7bf0-4235-abc9-b5deb500d0ad
// Type: eql

process where ((problemchild.prediction == 1 and problemchild.prediction_probability <= 0.98) or
blocklist_label == 1) and not process.args : ("*C:\\WINDOWS\\temp\\nessus_*.txt*", "*C:\\WINDOWS\\temp\\nessus_*.tmp*") and
process.parent.executable != null and not user.id in ("S-1-5-18", "S-1-5-19", "S-1-5-20") and
not process.parent.name : ("cmd.exe", "powershell.exe") and
not (process.name == "net1.exe" and process.parent.name == "net.exe") and
not (process.parent.executable : "C:\\Windows\\System32\\svchost.exe" and
     process.name : ("UCPDMgr.exe", "sdbinst.exe", "gpupdate.exe", "rundll32.exe", "taskhostw.exe", "taskeng.exe")) and
not (process.name: ("powershell.exe", "cmd.exe", "cscript.exe") and
     process.parent.executable : ("C:\\Program Files\\*.exe",
                                  "C:\\Program Files (x86)\\*.exe",
                                  "C:\\Users\\*\\Documents\\scripts\\nssm-2.24\\win64\\nssm.exe",
                                  "C:\\Windows\\System32\\cmd.exe",
                                  "C:\\Windows\\SysWOW64\\cmd.exe",
                                  "C:\\Windows\\CCM\\CcmExec.exe",
                                  "C:\\Windows\\System32\\svchost.exe",
                                  "C:\\Windows\\System32\\gpscript.exe",
                                  "C:\\Windows\\System32\\wbem\\WmiPrvSE.exe",
                                  "C:\\appian\\java\\bin\\java.exe")) and
not (process.executable : "C:\\Windows\\System32\\cscript.exe" and process.parent.name : ("node.exe", "MicroStrategy Services.exe")) and
not (process.name : "MpCmdRun.exe" and process.parent.name : ("MsMpEng.exe", "MpCmdRun.exe", "svchost.exe")) and
not process.executable : ("C:\\Program Files\\*.exe", "C:\\Program Files (x86)\\*.exe")

// Title: command_and_control_cat_network_activity.toml
// Source: detection-rules::rules/linux/command_and_control_cat_network_activity.toml
// Section: EQL Rule
// Rule Name: Network Activity Detected via cat
// Author: Elastic
// Description:
// This rule monitors for the execution of the cat command, followed by a connection attempt by the same process. Cat is
// capable of transfering data via tcp/udp channels by redirecting its read output to a /dev/tcp or /dev/udp channel. This
// activity is highly suspicious, and should be investigated. Attackers may leverage this capability to transfer tools or
// files to another host in the network or exfiltrate data while attempting to evade detection in the process.
// Integration: endpoint
// Language: eql
// UUID: afd04601-12fc-4149-9b78-9c3f8fe45d39
// Type: eql

sequence by host.id, process.entity_id with maxspan=3s
  [process where host.os.type == "linux" and event.type == "start" and event.action == "exec" and
   process.name == "cat" and process.parent.name in ("bash", "dash", "sh", "tcsh", "csh", "zsh", "ksh", "fish")]
  [network where host.os.type == "linux" and event.action in ("connection_attempted", "disconnect_received") and
   process.name == "cat" and not (
     destination.ip == null or destination.ip == "0.0.0.0" or cidrmatch(
       destination.ip, "10.0.0.0/8", "127.0.0.0/8", "169.254.0.0/16", "172.16.0.0/12", "192.0.0.0/24", "192.0.0.0/29",
       "192.0.0.8/32", "192.0.0.9/32", "192.0.0.10/32", "192.0.0.170/32", "192.0.0.171/32", "192.0.2.0/24",
       "192.31.196.0/24", "192.52.193.0/24", "192.168.0.0/16", "192.88.99.0/24", "224.0.0.0/4", "100.64.0.0/10",
       "192.175.48.0/24","198.18.0.0/15", "198.51.100.0/24", "203.0.113.0/24", "240.0.0.0/4", "::1", "FE80::/10",
       "FF00::/8"
     )
   )]

// Title: command_and_control_cupsd_foomatic_rip_netcon.toml
// Source: detection-rules::rules/linux/command_and_control_cupsd_foomatic_rip_netcon.toml
// Section: EQL Rule
// Rule Name: Network Connection by Cups or Foomatic-rip Child
// Author: Elastic
// Description:
// This detection rule addresses multiple vulnerabilities in the CUPS printing system, including CVE-2024-47176,
// CVE-2024-47076, CVE-2024-47175, and CVE-2024-47177. Specifically, this rule detects network connections initiated by a
// child processes of foomatic-rip. These flaws impact components like cups-browsed, libcupsfilters, libppd, and
// foomatic-rip, allowing remote unauthenticated attackers to manipulate IPP URLs or inject malicious data through crafted
// UDP packets or network spoofing. This can result in arbitrary command execution when a print job is initiated.
// Integration: endpoint
// Language: eql
// UUID: e80ee207-9505-49ab-8ca8-bc57d80e2cab
// Type: eql

sequence by host.id with maxspan=10s
  [process where host.os.type == "linux" and event.type == "start" and event.action == "exec" and
   process.parent.name == "foomatic-rip" and
   process.name in ("bash", "dash", "sh", "tcsh", "csh", "zsh", "ksh", "fish")] by process.entity_id
  [network where host.os.type == "linux" and event.type == "start" and
   event.action == "connection_attempted"] by process.parent.entity_id

// Title: command_and_control_curl_socks_proxy_detected.toml
// Source: detection-rules::rules/linux/command_and_control_curl_socks_proxy_detected.toml
// Section: EQL Rule
// Rule Name: Curl SOCKS Proxy Activity from Unusual Parent
// Author: Elastic
// Description:
// This rule detects the use of the "curl" command-line tool with SOCKS proxy options, launched from an unusual parent
// process. Attackers may use "curl" to establish a SOCKS proxy connection to bypass network restrictions and exfiltrate
// data or communicate with C2 servers.
// Integration: endpoint
// Language: eql
// UUID: 734239fe-eda8-48c0-bca8-9e3dafd81a88
// Type: eql

process where host.os.type == "linux" and event.type == "start" and event.action == "exec" and
process.name == "curl" and (
  process.parent.executable like (
    "/dev/shm/*", "/tmp/*", "/var/tmp/*", "/var/run/*", "/root/*", "/boot/*", "/var/www/*", "/opt/.*",
    "/home/*"
  ) or
  process.parent.name in ("bash", "dash", "sh", "tcsh", "csh", "zsh", "ksh", "fish") or
  process.parent.name like ".*"
) and (
  process.args like ("--socks5-hostname", "--proxy", "--preproxy", "socks5*") or
  process.args == "-x" or
  process.env_vars like~ ("http_proxy=socks5h://*", "HTTPS_PROXY=socks5h://*", "ALL_PROXY=socks5h://*")
) and not (
  process.parent.args == "/opt/rudder/share/commands/agent-run" or
  process.args == "http://localhost:8080/rudder/api/status"
)

// Title: command_and_control_dns_query_to_sus_top_level_domain.toml
// Source: detection-rules::rules/linux/command_and_control_dns_query_to_sus_top_level_domain.toml
// Section: EQL Rule
// Rule Name: DNS Request to Suspicious Top Level Domain
// Author: Elastic
// Description:
// This rule detects DNS queries to commonly abused top level domains. Malware authors may use these
// domains to host command and control infrastructure, exfiltrate data, or to download payloads
// for later execution.
// Integration: endpoint
// Language: eql
// UUID: 44a2de72-fe41-4558-b7ec-3e42de5f0432
// Type: eql

network where host.os.type == "linux" and dns.question.name != null and process.name != null and
dns.question.name like~ (
  "*.forum", "*.pro", "*.team", "*.lol", "*.kr", "*.ke", "*.nu", "*.space", "*.capital", "*.in", "*.cfd", "*.online",
  "*.ru", "*.info", "*.top", "*.buzz", "*.xyz", "*.rest", "*.ml", "*.cf", "*.gq", "*.ga", "*.onion", "*.network",
  "*.monster", "*.marketing", "*.cyou", "*.quest", "*.cc", "*.bar", "*.click", "*.cam", "*.surf", "*.tk", "*.shop",
  "*.club", "*.icu", "*.pw", "*.ws", "*.fun", "*.life", "*.boats", "*.store", "*.hair", "*.mom",
  "*.beauty", "*.bond", "*.biz", "*.live", "*.zone"
)

// Title: command_and_control_elastic_endpoint_shell_execution.toml
// Source: detection-rules::rules/linux/command_and_control_elastic_endpoint_shell_execution.toml
// Section: EQL Rule
// Rule Name: Shell Execution via Elastic Endpoint
// Author: Elastic
// Description:
// This rule detects shell executions via Elastic Endpoint. Elastic Endpoint has a built-in response action
// console that can be used to execute shell commands on compromised systems.
// Integration: endpoint, sentinel_one_cloud_funnel
// Language: eql
// UUID: ef35b103-7fca-4af4-879d-a7e73c918659
// Type: eql

process where host.os.type == "linux" and event.type == "start" and event.action in ("exec", "start") and
process.parent.executable == "/opt/Elastic/Endpoint/elastic-endpoint" and
process.name in ("bash", "dash", "sh", "tcsh", "csh", "zsh", "ksh", "fish") and
process.args in ("-c", "-cl", "-lc", "--command")

// Title: command_and_control_git_repo_or_file_download_to_sus_dir.toml
// Source: detection-rules::rules/linux/command_and_control_git_repo_or_file_download_to_sus_dir.toml
// Section: EQL Rule
// Rule Name: Git Repository or File Download to Suspicious Directory
// Author: Elastic
// Description:
// This rule detects the use of git to clone a repository or download files from GitHub using wget or curl, followed by
// the creation of files in suspicious directories such as /tmp, /var/tmp, or /dev/shm. This behavior may indicate an
// attempt to download a payload, exploit or tool.
// Integration: endpoint
// Language: eql
// UUID: 70089609-c41a-438e-b132-5b3b43c5fc07
// Type: eql

sequence by process.entity_id, host.id with maxspan=10s
  [process where host.os.type == "linux" and event.type == "start" and event.action == "exec" and (
     (process.name == "git" and process.args == "clone") or
     (process.name in ("wget", "curl") and process.command_line like~ "*github*")
  ) and not (
    process.parent.name in ("git", "cmake") or
     process.parent.args like "/root/.ansible/tmp/ansible*"
  )]
  [file where host.os.type == "linux" and event.type == "creation" and file.path like ("/tmp/*", "/var/tmp/*", "/dev/shm/*")]

// Title: command_and_control_ip_forwarding_activity.toml
// Source: detection-rules::rules/linux/command_and_control_ip_forwarding_activity.toml
// Section: EQL Rule
// Rule Name: IPv4/IPv6 Forwarding Activity
// Author: Elastic
// Description:
// This rule monitors for the execution of commands that enable IPv4 and IPv6 forwarding on Linux systems. Enabling IP
// forwarding can be used to route network traffic between different network interfaces, potentially allowing attackers to
// pivot between networks, exfiltrate data, or establish command and control channels.
// Integration: endpoint, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 5a138e2e-aec3-4240-9843-56825d0bc569
// Type: eql

process where host.os.type == "linux" and event.type == "start" and event.action in ("exec", "start", "exec_event", "ProcessRollup2") and
?process.parent.executable != null and process.command_line like (
  "*net.ipv4.ip_forward*", "*/proc/sys/net/ipv4/ip_forward*", "*net.ipv6.conf.all.forwarding*",
  "*/proc/sys/net/ipv6/conf/all/forwarding*"
) and (
  (process.name == "sysctl" and process.args like ("*-w*", "*--write*", "*=*")) or
  (
    process.name in ("bash", "dash", "sh", "tcsh", "csh", "zsh", "ksh", "fish") and process.args == "-c" and
    process.command_line like "*echo *"
  )
) and
not (
  process.parent.name like~ ("privsep-helper", "platform-python*", "init.ipv6-global", "wsl-bootstrap") or
  ?process.parent.executable == "/usr/sbin/sshd" or
  ?process.parent.args in (
    "/usr/lib/pritunl/usr/bin/pritunl", "/usr/bin/dockerd-rootless.sh", "/etc/rc.d/init.d/network", "/etc/rc0.d/K90network"
  )  or
  ?process.parent.args like "/etc/untangle/post-network-hook.d/*"
)

// Title: command_and_control_linux_chisel_client_activity.toml
// Source: detection-rules::rules/linux/command_and_control_linux_chisel_client_activity.toml
// Section: EQL Rule
// Rule Name: Potential Protocol Tunneling via Chisel Client
// Author: Elastic
// Description:
// This rule monitors for common command line flags leveraged by the Chisel client utility followed by a connection
// attempt. Chisel is a command-line utility used for creating and managing TCP and UDP tunnels, enabling port forwarding
// and secure communication between machines. Attackers can abuse the Chisel utility to establish covert communication
// channels, bypass network restrictions, and carry out malicious activities by creating tunnels that allow unauthorized
// access to internal systems.
// Integration: endpoint
// Language: eql
// UUID: 3f12325a-4cc6-410b-8d4c-9fbbeb744cfd
// Type: eql

sequence by host.id, process.entity_id with maxspan=3s
  [process where host.os.type == "linux" and event.type == "start" and event.action == "exec" and 
   process.args == "client" and process.args : ("R*", "*:*", "*socks*") and process.args_count >= 4 and 
   process.parent.name in ("bash", "dash", "ash", "sh", "tcsh", "csh", "zsh", "ksh", "fish") and
   not process.name in ("velociraptor", "nbemmcmd", "redis-cli", "ipa")]
  [network where host.os.type == "linux" and event.action == "connection_attempted" and event.type == "start" and 
   destination.ip != null and destination.ip != "127.0.0.1" and destination.ip != "::1" and 
   not process.name : (
     "python*", "php*", "perl", "ruby", "lua*", "openssl", "nc", "netcat", "ncat", "telnet", "awk", "java", "telnet",
     "ftp", "socat", "curl", "wget", "dpkg", "docker", "dockerd", "yum", "apt", "rpm", "dnf", "ssh", "sshd", "kubectl*",
     "clickhouse"
   )]

// Title: command_and_control_linux_proxychains_activity.toml
// Source: detection-rules::rules/linux/command_and_control_linux_proxychains_activity.toml
// Section: EQL Rule
// Rule Name: ProxyChains Activity
// Author: Elastic
// Description:
// This rule monitors for the execution of the ProxyChains utility. ProxyChains is a command-line tool that enables the
// routing of network connections through intermediary proxies, enhancing anonymity and enabling access to restricted
// resources. Attackers can exploit the ProxyChains utility to hide their true source IP address, evade detection, and
// perform malicious activities through a chain of proxy servers, potentially masking their identity and intentions.
// Integration: endpoint, auditd_manager, crowdstrike, sentinel_one_cloud_funnel
// Language: eql
// UUID: 4b868f1f-15ff-4ba3-8c11-d5a7a6356d37
// Type: eql

process where host.os.type == "linux" and event.type == "start" and
event.action in ("exec", "exec_event", "start", "ProcessRollup2", "executed", "process_started") and
process.name == "proxychains"

// Title: command_and_control_linux_ssh_x11_forwarding.toml
// Source: detection-rules::rules/linux/command_and_control_linux_ssh_x11_forwarding.toml
// Section: EQL Rule
// Rule Name: Linux SSH X11 Forwarding
// Author: Elastic
// Description:
// This rule monitors for X11 forwarding via SSH. X11 forwarding is a feature that allows users to run graphical
// applications on a remote server and display the application's graphical user interface on their local machine. Attackers
// can abuse X11 forwarding for tunneling their GUI-based tools, pivot through compromised systems, and create covert
// communication channels, enabling lateral movement and facilitating remote control of systems within a network.
// Integration: endpoint, crowdstrike, sentinel_one_cloud_funnel
// Language: eql
// UUID: 29f0cf93-d17c-4b12-b4f3-a433800539fa
// Type: eql

process where host.os.type == "linux" and event.type == "start" and event.action in ("exec", "exec_event", "start", "ProcessRollup2") and
process.name in ("ssh", "sshd") and process.args in ("-X", "-Y") and process.args_count >= 3 and
process.parent.name in ("bash", "dash", "ash", "sh", "tcsh", "csh", "zsh", "ksh", "fish")

// Title: command_and_control_linux_suspicious_proxychains_activity.toml
// Source: detection-rules::rules/linux/command_and_control_linux_suspicious_proxychains_activity.toml
// Section: EQL Rule
// Rule Name: Suspicious Utility Launched via ProxyChains
// Author: Elastic
// Description:
// This rule monitors for the execution of suspicious linux tools through ProxyChains. ProxyChains is a command-line tool
// that enables the routing of network connections through intermediary proxies, enhancing anonymity and enabling access to
// restricted resources. Attackers can exploit the ProxyChains utility to hide their true source IP address, evade
// detection, and perform malicious activities through a chain of proxy servers, potentially masking their identity and
// intentions.
// Integration: endpoint, auditd_manager, crowdstrike, sentinel_one_cloud_funnel
// Language: eql
// UUID: 6ace94ba-f02c-4d55-9f53-87d99b6f9af4
// Type: eql

process where host.os.type == "linux" and event.type == "start" and
event.action in ("exec", "exec_event", "start", "ProcessRollup2", "executed", "process_started") and
process.name == "proxychains" and process.args : (
  "ssh", "sshd", "sshuttle", "socat", "iodine", "iodined", "dnscat", "hans", "hans-ubuntu", "ptunnel-ng",
  "ssf", "3proxy", "ngrok", "gost", "pivotnacci", "chisel*", "nmap", "ping", "python*", "php*", "perl", "ruby",
  "lua*", "openssl", "nc", "netcat", "ncat", "telnet", "awk", "java", "telnet", "ftp", "curl", "wget"
)

// Title: command_and_control_linux_tunneling_and_port_forwarding.toml
// Source: detection-rules::rules/linux/command_and_control_linux_tunneling_and_port_forwarding.toml
// Section: EQL Rule
// Rule Name: Potential Linux Tunneling and/or Port Forwarding
// Author: Elastic
// Description:
// This rule monitors for a set of Linux utilities that can be used for tunneling and port forwarding. Attackers can
// leverage tunneling and port forwarding techniques to bypass network defenses, establish hidden communication channels,
// and gain unauthorized access to internal resources, facilitating data exfiltration, lateral movement, and remote
// control.
// Integration: endpoint, crowdstrike, sentinel_one_cloud_funnel, auditd_manager
// Language: eql
// UUID: 6ee947e9-de7e-4281-a55d-09289bdf947e
// Type: eql

process where host.os.type == "linux" and event.type == "start" and event.action in ("exec", "exec_event", "start", "ProcessRollup2", "executed", "process_started") and (
  (
    // gost & pivotnacci - spawned without process.parent.name
    (process.name == "gost" and process.args : ("-L*", "-C*", "-R*")) or (process.name == "pivotnacci")) or (
    // ssh
    (process.name == "ssh" and (
      (
        /* exact tunnel argument matching */
        process.args in ("-R", "-L", "-D", "-w") or
        /* single-dash token, first letter is NOT o/O, contains one of R/L/D/w/W somewhere later */
        process.args regex "-[A-NP-Za-np-z][A-Za-z]*[RLDwW][A-Za-z]*"
      ) and
      process.args_count >= 4 and 
      not (
        process.args == "chmod" or process.command_line like "*rungencmd*"
      )
    )) or
    (process.name == "ssh" and process.args == "-J") or
    // sshuttle
    (process.name == "sshuttle" and process.args in ("-r", "--remote", "-l", "--listen") and process.args_count >= 4) or
    // socat
    (process.name == "socat" and process.args : ("TCP4-LISTEN:*", "SOCKS*") and process.args_count >= 3) or
    // chisel
    (process.name : "chisel*" and process.args in ("client", "server")) or
    // iodine(d), dnscat, hans, ptunnel-ng, ssf, 3proxy & ngrok 
    (process.name in ("iodine", "iodined", "dnscat", "hans", "hans-ubuntu", "ptunnel-ng", "ssf", "3proxy", "ngrok", "wstunnel"))
  ) and process.parent.name in ("bash", "dash", "ash", "sh", "tcsh", "csh", "zsh", "ksh", "fish")
)

// Title: command_and_control_linux_tunneling_via_ssh_option.toml
// Source: detection-rules::rules/linux/command_and_control_linux_tunneling_via_ssh_option.toml
// Section: EQL Rule
// Rule Name: Potential Linux Tunneling and/or Port Forwarding via SSH Option
// Author: Elastic
// Description:
// This rule detects the use of SSH options that may indicate tunneling or port forwarding on Linux systems. This behavior
// is commonly associated with malicious activity, such as establishing a port forward, proxy or an encrypted tunnel to
// exfiltrate data.
// Integration: endpoint, crowdstrike, sentinel_one_cloud_funnel
// Language: eql
// UUID: ef395dff-be12-4a6e-8919-d87d627c2174
// Type: eql

process where host.os.type == "linux" and event.type == "start" and event.action in ("exec", "exec_event", "start", "ProcessRollup2") and
process.name in ("ssh", "sshd") and process.args like "-o*" and
process.command_line like~ (
  "*ProxyCommand*", "*LocalForward*", "*RemoteForward*", "*DynamicForward*", "*Tunnel*", "*GatewayPorts*",
  "*ExitOnForwardFailure*", "*ProxyCommand*", "*ProxyJump*"
) and 
not (
  ?process.parent.args == "/usr/bin/pvedaemon" or
  ?process.parent.command_line in ("pvedaemon", "pve-ha-lrm") or
  ?process.working_directory like "*ansible*" or
  process.command_line like "*ansible*"
)

// Title: command_and_control_netcon_file_creation.toml
// Source: detection-rules::rules/linux/command_and_control_netcon_file_creation.toml
// Section: EQL Rule
// Rule Name: Network Connection Followed by File Creation
// Author: Elastic
// Description:
// Detects network connections originating from a binary located in a potentially suspicious location, followed by a file
// creation event. This behavior is consistent with C2 agents such as Poseidon and Athena, connecting to a C2 framework
// such as Mythic. The agent polls the C2 for commands through a web request, after which the command gets executed.
// Integration: endpoint
// Language: eql
// UUID: 01c1e353-9d86-4344-abdf-523ab80c6f08
// Type: eql

sequence by host.id, process.entity_id with maxspan=5s
  [network where host.os.type == "linux" and event.type == "start" and event.action == "connection_attempted" and
  process.executable like (
    "/boot/*", "/dev/shm/*", "/tmp/*", "/var/tmp/*", "/var/log/*", "/var/run/user/*", "/run/user/*"
  ) and
  not (
    destination.ip == null or
    destination.ip == "0.0.0.0" or 
    cidrmatch(
      destination.ip, "10.0.0.0/8", "127.0.0.0/8", "169.254.0.0/16", "172.16.0.0/12",
      "192.0.0.0/24", "192.0.0.0/29","192.0.0.8/32", "192.0.0.9/32", "192.0.0.10/32",
      "192.0.0.170/32", "192.0.0.171/32", "192.0.2.0/24", "192.31.196.0/24", "192.52.193.0/24",
      "192.168.0.0/16", "192.88.99.0/24", "224.0.0.0/4", "100.64.0.0/10", "192.175.48.0/24",
      "198.18.0.0/15", "198.51.100.0/24", "203.0.113.0/24", "240.0.0.0/4", "::1", "FE80::/10",
      "FF00::/8", "FC00::/7"
    )
  )]
  [file where host.os.type == "linux" and event.type == "creation" and process.executable like (
    "/boot/*", "/dev/shm/*", "/tmp/*", "/var/tmp/*", "/var/log/*", "/boot/*", "/var/run/user/*", "/run/user/*"
  ) and
  not (
    file.name like "tmp*" or file.extension in ("sqlite-journal", "db-journal", "lockfile", "tmp") or
    file.path like (
      "/loki/wal/*", "/dev/shm/.org.chromium.Chromium.*", "/opt/rapid7/nexpose/*",
      "/usr/local/ltechagent*", "/var/lib/cloudendure/agent_keystore_temp", "/var/cache/yum/*",
      "/run/aws-node/ipam.json.tmp*", "/run/systemd/journal/streams/.*"
    ) or
    (process.executable == "/tmp/terraform" and file.path like "/tmp/terraform-provider*") or 
    process.name in ("podman", "minikube", "logrotate", "java", "aws-k8s-agent", "grafana", "postman") or
    process.executable : (
      "/etc/cron.daily/logrotate", "/etc/update-motd.d/50-motd-news", "/etc/cron.hourly/0yum-hourly.cron",
      "/etc/cron.hourly/BitdefenderRedline", "/tmp/token_handler", "/tmp/.sentry-cli*.exe", 
      "/etc/cron.daily/0yum-daily.cron", "/etc/init.d/fortiedr"
    )
  )]

// Title: command_and_control_potential_tunneling_command_line.toml
// Source: detection-rules::rules/linux/command_and_control_potential_tunneling_command_line.toml
// Section: EQL Rule
// Rule Name: Potential Linux Tunneling and/or Port Forwarding via Command Line
// Author: Elastic
// Description:
// This rule monitors for potential tunneling and/or port forwarding activity on Linux systems via command line utilities. Attackers may use
// various tools to create covert communication channels, allowing them to bypass network security measures and maintain persistent access
// to compromised systems. By leveraging these utilities, attackers can tunnel traffic through legitimate protocols, making detection more
// challenging.
// Integration: endpoint, crowdstrike, sentinel_one_cloud_funnel, auditd_manager
// Language: eql
// UUID: 8c8df61f-ed2a-4832-87b8-ee30812606e0
// Type: eql

process where host.os.type == "linux" and event.type == "start" and event.action in ("exec", "exec_event", "start", "ProcessRollup2", "executed", "process_started") and 
process.command_line regex """.*[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}:[0-9]{1,5}:[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}:[0-9]{1,5}.*"""

// Title: command_and_control_telegram_api_request.toml
// Source: detection-rules::rules/linux/command_and_control_telegram_api_request.toml
// Section: EQL Rule
// Rule Name: Linux Telegram API Request
// Author: Elastic
// Description:
// This rule detects when a process executes the curl or wget command with an argument that includes the
// api.telegram.org domain. This may indicate command and control behavior.
// Integration: endpoint, crowdstrike, sentinel_one_cloud_funnel, auditd_manager
// Language: eql
// UUID: af1e36fe-0abd-4463-b5ec-4e276dec0b26
// Type: eql

process where host.os.type == "linux" and event.type == "start" and
event.action in ("exec", "start", "exec_event", "ProcessRollup2", "executed", "exec_event", "process_started") and
process.name in ("curl", "wget") and process.command_line like "*api.telegram.org*"

// Title: command_and_control_tunneling_via_earthworm.toml
// Source: detection-rules::rules/linux/command_and_control_tunneling_via_earthworm.toml
// Section: EQL Rule
// Rule Name: Potential Protocol Tunneling via EarthWorm
// Author: Elastic
// Description:
// Identifies the execution of the EarthWorm tunneler. Adversaries may tunnel network communications to and from a victim
// system within a separate protocol to avoid detection and network filtering, or to enable access to otherwise unreachable
// systems.
// Integration: endpoint, crowdstrike, sentinel_one_cloud_funnel, auditd_manager
// Language: eql
// UUID: 9f1c4ca3-44b5-481d-ba42-32dc215a2769
// Type: eql

process where host.os.type == "linux" and event.type == "start" and
event.action in ("exec", "start", "exec_event", "ProcessRollup2", "executed", "exec_event", "process_started") and
process.args : "-s" and process.args : "-d" and process.args : "rssocks"

// Title: credential_access_aws_creds_search_inside_container.toml
// Source: detection-rules::rules/linux/credential_access_aws_creds_search_inside_container.toml
// Section: EQL Rule
// Rule Name: AWS Credentials Searched For Inside A Container
// Author: Elastic
// Description:
// This rule detects the use of system search utilities like grep and find to search for AWS credentials inside a
// container. Unauthorized access to these sensitive files could lead to further compromise of the container environment or
// facilitate a container breakout to the underlying cloud environment.
// Integration: endpoint
// Language: eql
// UUID: 5749282b-7524-4c9d-af9a-e2b3e814e5d4
// Type: eql

process where host.os.type == "linux" and event.type == "start" and event.action == "exec" and
process.entry_leader.entry_meta.type == "container" and
process.name in ("grep", "egrep", "fgrep", "find", "locate", "mlocate", "cat", "sed", "awk") and
process.command_line like~ (
  "*aws_access_key_id*", "*aws_secret_access_key*", "*aws_session_token*", "*accesskeyid*", "*secretaccesskey*",
  "*access_key*", "*.aws/credentials*"
)

// Title: credential_access_collection_sensitive_files_compression_inside_container.toml
// Source: detection-rules::rules/linux/credential_access_collection_sensitive_files_compression_inside_container.toml
// Section: EQL Rule
// Rule Name: Sensitive Files Compression Inside A Container
// Author: Elastic
// Description:
// Identifies the use of a compression utility to collect known files containing sensitive information, such as credentials
// and system configurations inside a container.
// Integration: endpoint
// Language: eql
// UUID: d9faf1ba-a216-4c29-b8e0-a05a9d14b027
// Type: eql

process where host.os.type == "linux" and event.type == "start" and event.action == "exec" and
process.entry_leader.entry_meta.type == "container" and process.name in ("zip", "tar", "gzip", "hdiutil", "7z") and
process.command_line like~ (
  "*/root/.ssh/*", "*/home/*/.ssh/*", "*/root/.bash_history*", "*/etc/hosts*", "*/root/.aws/*", "*/home/*/.aws/*",
  "*/root/.docker/*", "*/home/*/.docker/*", "*/etc/group*", "*/etc/passwd*", "*/etc/shadow*", "*/etc/gshadow*"
)

// Title: credential_access_credential_dumping.toml
// Source: detection-rules::rules/linux/credential_access_credential_dumping.toml
// Section: EQL Rule
// Rule Name: Potential Linux Credential Dumping via Unshadow
// Author: Elastic
// Description:
// Identifies the execution of the unshadow utility which is part of John the Ripper, a password-cracking tool on the host
// machine. Malicious actors can use the utility to retrieve the combined contents of the '/etc/shadow' and '/etc/password'
// files. Using the combined file generated from the utility, the malicious threat actors can use them as input for
// password-cracking utilities or prepare themselves for future operations by gathering credential information of the
// victim.
// Integration: endpoint, crowdstrike, sentinel_one_cloud_funnel
// Language: eql
// UUID: e7cb3cfd-aaa3-4d7b-af18-23b89955062c
// Type: eql

process where host.os.type == "linux" and event.type == "start" and event.action in ("exec", "exec_event", "start", "ProcessRollup2") and
process.name == "unshadow" and process.args_count >= 3

// Title: credential_access_gdb_init_process_hooking.toml
// Source: detection-rules::rules/linux/credential_access_gdb_init_process_hooking.toml
// Section: EQL Rule
// Rule Name: Linux init (PID 1) Secret Dump via GDB
// Author: Elastic
// Description:
// This rule monitors for the potential memory dump of the init process (PID 1) through gdb. Attackers may leverage memory
// dumping techniques to attempt secret extraction from privileged processes. Tools that display this behavior include
// "truffleproc" and "bash-memory-dump". This behavior should not happen by default, and should be investigated thoroughly.
// Integration: endpoint, crowdstrike, sentinel_one_cloud_funnel, auditd_manager
// Language: eql
// UUID: d4ff2f53-c802-4d2e-9fb9-9ecc08356c3f
// Type: eql

process where host.os.type == "linux" and event.type == "start" and event.action in ("exec", "exec_event", "start", "ProcessRollup2", "executed", "process_started") and
process.name == "gdb" and process.args in ("--pid", "-p") and process.args == "1"

// Title: credential_access_gdb_process_hooking.toml
// Source: detection-rules::rules/linux/credential_access_gdb_process_hooking.toml
// Section: EQL Rule
// Rule Name: Linux Process Hooking via GDB
// Author: Elastic
// Description:
// This rule monitors for potential memory dumping through gdb. Attackers may leverage memory dumping techniques to attempt
// secret extraction from privileged processes. Tools that display this behavior include "truffleproc" and
// "bash-memory-dump". This behavior should not happen by default, and should be investigated thoroughly.
// Integration: endpoint, auditd_manager, crowdstrike, sentinel_one_cloud_funnel
// Language: eql
// UUID: 66c058f3-99f4-4d18-952b-43348f2577a0
// Type: eql

process where host.os.type == "linux" and event.type == "start" and event.action in ("exec", "exec_event", "start", "ProcessRollup2", "executed", "process_started")
 and process.name == "gdb" and process.args in ("--pid", "-p") and
/* Covered by d4ff2f53-c802-4d2e-9fb9-9ecc08356c3f */
process.args != "1"

// Title: credential_access_gh_auth_via_nodejs.toml
// Source: detection-rules::rules/linux/credential_access_gh_auth_via_nodejs.toml
// Section: EQL Rule
// Rule Name: GitHub Authentication Token Access via Node.js
// Author: Elastic
// Description:
// This rule detects when the Node.js runtime spawns a shell to execute the GitHub CLI (gh) command to retrieve
// a GitHub authentication token. The GitHub CLI is a command-line tool that allows users to interact with
// GitHub from the terminal. The "gh auth token" command is used to retrieve an authentication token for
// GitHub, which can be used to authenticate API requests and perform actions on behalf of the user. Adversaries
// may use this technique to access GitHub repositories and potentially exfiltrate sensitive information or
// perform malicious actions. This activity was observed in the wild as part of the Shai-Hulud worm.
// Integration: endpoint, crowdstrike
// Language: eql
// UUID: e5d69377-f8cf-4e8f-8328-690822cd012a
// Type: eql

process where host.os.type == "linux" and event.type == "start" and event.action in ("exec", "ProcessRollup2", "exec_event") and process.parent.name == "node" and
process.name in ("bash", "dash", "sh", "tcsh", "csh", "zsh", "ksh", "fish") and process.args == "gh auth token"

// Title: credential_access_kubernetes_service_account_secret_access.toml
// Source: detection-rules::rules/linux/credential_access_kubernetes_service_account_secret_access.toml
// Section: EQL Rule
// Rule Name: Kubernetes Service Account Secret Access
// Author: Elastic
// Description:
// This rule detects when a process accesses Kubernetes service account secrets. Kubernetes service
// account secrets are files that contain sensitive information used by applications running in Kubernetes
// clusters to authenticate and authorize access to the cluster. These secrets are typically mounted into
// pods at runtime, allowing applications to access them securely. Unauthorized access to these secrets
// can lead to privilege escalation, lateral movement and unauthorized actions within the cluster.
// Integration: endpoint
// Language: eql
// UUID: ce73954b-a0a4-4f05-b67b-294c500dac77
// Type: eql

process where host.os.type == "linux" and event.type == "start" and event.action == "exec" and (
  process.command_line like (
    "*/run/secrets/kubernetes.io/serviceaccount*",
    "*/var/run/secrets/kubernetes.io/serviceaccount*",
    "*/secrets/kubernetes.io/serviceaccount*"
  ) or (
    process.working_directory like (
      "/run/secrets/kubernetes.io/serviceaccount",
      "/var/run/secrets/kubernetes.io/serviceaccount",
      "/secrets/kubernetes.io/serviceaccount"
    ) and
    process.args in ("ca.crt", "token")
  )
) and
not (
  process.command_line like "*/bin/test*" or
  process.args in (
    "/var/run/secrets/kubernetes.io/serviceaccount/namespace",
    "/run/secrets/kubernetes.io/serviceaccount/namespace",
    "/secrets/kubernetes.io/serviceaccount/namespace"
  ) or
  process.command_line == "/usr/bin/coreutils --coreutils-prog-shebang=cat /usr/bin/cat /var/run/secrets/kubernetes.io/serviceaccount/token" or
  process.parent.command_line == "runc init" or
  (process.parent.name == "px-oci-mon" and process.name == "rsync") or
  (
    process.parent.command_line == "sh /install-cni.sh" and
    process.working_directory like (
      "/opt/cni/bin", "/run/containerd/io.containerd.runtime.v2.task/k8s.io/*/opt/cni/bin"
    )
  ) or
  (process.working_directory like "/home/runner/_work/*" and process.parent.args like "/home/runner/_work/_temp/*.sh") or
  process.working_directory == "/opt/cni/bin"
)

// Title: credential_access_manual_memory_dumping.toml
// Source: detection-rules::rules/linux/credential_access_manual_memory_dumping.toml
// Section: EQL Rule
// Rule Name: Manual Memory Dumping via Proc Filesystem
// Author: Elastic
// Description:
// This rule monitors for manual memory dumping via the proc filesystem. The proc filesystem in Linux provides a virtual filesystem
// that contains information about system processes and their memory mappings. Attackers may use this technique to dump the memory
// of a process, potentially extracting sensitive information such as credentials or encryption keys.
// Integration: endpoint, crowdstrike, sentinel_one_cloud_funnel, auditd_manager
// Language: eql
// UUID: 6505e02e-28dd-41cd-b18f-64e649caa4e2
// Type: eql

process where host.os.type == "linux" and event.type == "start" and event.action in ("exec", "exec_event", "start", "ProcessRollup2", "executed", "process_started") and
process.name in ("cat", "grep", "tail", "less", "more", "egrep", "fgrep") and process.command_line like "/proc/*/mem"

// Title: credential_access_potential_linux_local_account_bruteforce.toml
// Source: detection-rules::rules/linux/credential_access_potential_linux_local_account_bruteforce.toml
// Section: EQL Rule
// Rule Name: Potential Linux Local Account Brute Force Detected
// Author: Elastic
// Description:
// Identifies multiple consecutive login attempts executed by one process targeting a local linux user account within a
// short time interval. Adversaries might brute force login attempts across different users with a default wordlist or a
// set of customly crafted passwords in an attempt to gain access to these accounts.
// Integration: endpoint
// Language: esql
// UUID: 835c0622-114e-40b5-a346-f843ea5d01f1
// Type: esql

from logs-endpoint.events.process* metadata _id, _index, _version

// Create 1-minute time buckets
| eval Esql.time_window_date_trunc = date_trunc(1 minute, @timestamp)

// Ensure event.action values in a list are expanded
| mv_expand event.action 

| where
  event.category == "process" and event.type == "start" and event.action == "exec" and process.name == "su" and 
  process.parent.name not in (
    "bash", "dash", "ash", "sh", "tcsh", "csh", "zsh", "ksh", "fish", "clickhouse-server", "ma", "gitlab-runner",
    "updatedb.findutils", "cron", "perl", "sudo", "java", "cloud-app-identify", "ambari-sudo.sh", "runc",
    "cau9sat.exe", "git-pull.sh", "distributor-pulltabs-devel-live", "p_ctmag", "backup_agent_main", "sshd",
    "nxpgsql", "cau9cli.exe", "autopostgresqlbackup"
  ) and
  not process.parent.command_line == "runc init"

// Keep relevant fields
| keep
   @timestamp,
   event.action,
   event.category,
   event.type,
   process.name,
   process.parent.name,
   process.parent.command_line,
   process.command_line,
   user.name,
   data_stream.dataset,
   data_stream.namespace,
   process.parent.executable,
   agent.id,
   user.id,
   Esql.time_window_date_trunc

| stats
  Esql.event_count = count(*),
  Esql.process_command_line_values = values(process.command_line),
  Esql.process_parent_command_line_values = values(process.parent.command_line),
  Esql.user_name_values = values(user.name),
  Esql.data_stream_dataset_values = values(data_stream.dataset),
  Esql.data_stream_namespace_values = values(data_stream.namespace)

  by process.parent.executable, agent.id, user.id, Esql.time_window_date_trunc

| where Esql.event_count >= 10

// Title: credential_access_potential_linux_ssh_bruteforce_external.toml
// Source: detection-rules::rules/linux/credential_access_potential_linux_ssh_bruteforce_external.toml
// Section: EQL Rule
// Rule Name: Potential External Linux SSH Brute Force Detected
// Author: Elastic
// Description:
// Identifies multiple external consecutive login failures targeting a user account from the same source address within a
// short time interval. Adversaries will often brute force login attempts across multiple users with a common or known
// password, in an attempt to gain access to these accounts.
// Integration: system
// Language: eql
// UUID: fa210b61-b627-4e5e-86f4-17e8270656ab
// Type: eql

sequence by host.id, source.ip, user.name with maxspan=30s
  [ authentication where host.os.type == "linux" and 
   event.action in ("ssh_login", "user_login") and event.outcome == "failure" and
   not cidrmatch(source.ip, "10.0.0.0/8", "127.0.0.0/8", "169.254.0.0/16", "172.16.0.0/12", "192.0.0.0/24",
       "192.0.0.0/29", "192.0.0.8/32", "192.0.0.9/32", "192.0.0.10/32", "192.0.0.170/32", "192.0.0.171/32",
       "192.0.2.0/24", "192.31.196.0/24", "192.52.193.0/24", "192.168.0.0/16", "192.88.99.0/24", "224.0.0.0/4",
       "100.64.0.0/10", "192.175.48.0/24","198.18.0.0/15", "198.51.100.0/24", "203.0.113.0/24", "240.0.0.0/4", 
       "::1", "FE80::/10", "FF00::/8") ] with runs = 60

// Title: credential_access_potential_linux_ssh_bruteforce_internal.toml
// Source: detection-rules::rules/linux/credential_access_potential_linux_ssh_bruteforce_internal.toml
// Section: EQL Rule
// Rule Name: Potential Internal Linux SSH Brute Force Detected
// Author: Elastic
// Description:
// Identifies multiple internal consecutive login failures targeting a user account from the same source address within a
// short time interval. Adversaries will often brute force login attempts across multiple users with a common or known
// password, in an attempt to gain access to these accounts.
// Integration: system
// Language: eql
// UUID: 1c27fa22-7727-4dd3-81c0-de6da5555feb
// Type: eql

sequence by host.id, source.ip, user.name with maxspan=30s
