file where host.os.type == "linux" and event.action in ("rename", "creation") and
file.path like ("/usr/lib/python*/site-packages/dnf-plugins/*", "/etc/dnf/plugins/*") and not (
  process.executable in (
    "/bin/dockerd", "/usr/bin/dockerd", "/usr/sbin/dockerd", "/bin/microdnf", "/usr/bin/microdnf", "/bin/rpm",
    "/usr/bin/rpm", "/bin/snapd", "/usr/bin/snapd", "/bin/yum", "/usr/bin/yum", "/bin/dnf", "/usr/bin/dnf",
    "/bin/podman", "/usr/bin/podman", "/bin/dnf-automatic", "/usr/bin/dnf-automatic", "/sbin/apk", "/usr/sbin/apk",
    "/usr/local/sbin/apk", "/bin/podman", "/usr/bin/podman", "/usr/bin/puppet", "/bin/puppet",
    "/opt/puppetlabs/puppet/bin/puppet", "/usr/bin/chef-client", "/bin/chef-client", "/bin/autossl_check",
    "/usr/bin/autossl_check", "/proc/self/exe", "/usr/lib/snapd/snapd", "/usr/local/bin/dockerd",
    "/usr/libexec/netplan/generate", "./usr/bin/podman", "/usr/bin/dnf5", "/bin/needs-restarting",
    "/usr/bin/crio", "/usr/bin/insights-client", "/kaniko/executor"
  ) or
  file.extension in ("swp", "swpx", "swx") or
  process.executable : (
    "/nix/store/*", "/var/lib/dpkg/*", "/tmp/vmis.*", "/snap/*", "/dev/fd/*", "/usr/lib/*", "/usr/libexec/*",
    "/etc/kernel/*"
  ) or
  process.executable == null or
  (process.name == "sed" and file.name : "sed*") or
  (process.name == "perl" and file.name : "e2scrub_all.tmp*") or
  file.path like~ "/etc/dnf/plugins/.ansible_tmp*" or
  process.name like~ ("ssm-agent-worker, NinjaOrbit", "python*")
)

// Title: persistence_dpkg_unusual_execution.toml
// Source: detection-rules::rules/linux/persistence_dpkg_unusual_execution.toml
// Section: EQL Rule
// Rule Name: Unusual DPKG Execution
// Author: Elastic
// Description:
// This rule detects the execution of the DPKG command by processes not associated with the DPKG package manager. The DPKG
// command is used to install, remove, and manage Debian packages on a Linux system. Attackers can abuse the DPKG command
// to install malicious packages on a system.
// Integration: endpoint
// Language: eql
// UUID: d6241c90-99f2-44db-b50f-299b6ebd7ee9
// Type: eql

process where host.os.type == "linux" and event.type == "start" and event.action == "exec" and
process.executable : "/var/lib/dpkg/info/*" and process.session_leader.name != null and
process.group_leader.name != null and not (
  process.parent.name in ("dpkg", "dpkg-reconfigure", "frontend") or
  process.session_leader.name == "dpkg" or
  process.group_leader.name == "dpkg" or
  process.parent.executable in ("/usr/share/debconf/frontend", "/usr/bin/unattended-upgrade")
)

// Title: persistence_dracut_module_creation.toml
// Source: detection-rules::rules/linux/persistence_dracut_module_creation.toml
// Section: EQL Rule
// Rule Name: Dracut Module Creation
// Author: Elastic
// Description:
// This rule detects the creation of Dracut module files on Linux systems. Dracut is a tool used to generate an initramfs
// image that is used to boot the system. Dracut modules are scripts that are executed during the initramfs image
// generation process. Attackers may create malicious Dracut modules to execute arbitrary code at boot time, which can be
// leveraged to maintain persistence on a Linux system.
// Integration: endpoint, sentinel_one_cloud_funnel
// Language: eql
// UUID: dc765fb2-0c99-4e57-8c11-dafdf1992b66
// Type: eql

file where host.os.type == "linux" and event.type == "creation" and process.executable != null and
file.path like~ ("/lib/dracut/modules.d/*", "/usr/lib/dracut/modules.d/*") and not (
  // Too many FPs from Python automation
  process.name like ("python*", "platform-python*") or
  process.executable in (
    "/bin/dpkg", "/usr/bin/dpkg", "/bin/dockerd", "/usr/bin/dockerd", "/usr/sbin/dockerd", "/bin/microdnf",
    "/usr/bin/microdnf", "/bin/rpm", "/usr/bin/rpm", "/bin/snapd", "/usr/bin/snapd", "/bin/yum", "/usr/bin/yum",
    "/bin/dnf", "/usr/bin/dnf", "/bin/podman", "/usr/bin/podman", "/bin/dnf-automatic", "/usr/bin/dnf-automatic",
    "/bin/pacman", "/usr/bin/pacman", "/usr/bin/dpkg-divert", "/bin/dpkg-divert", "/sbin/apk", "/usr/sbin/apk",
    "/usr/local/sbin/apk", "/usr/bin/apt", "/usr/sbin/pacman", "/bin/podman", "/usr/bin/podman", "/usr/bin/puppet",
    "/bin/puppet", "/opt/puppetlabs/puppet/bin/puppet", "/usr/bin/chef-client", "/bin/chef-client",
    "/bin/autossl_check", "/usr/bin/autossl_check", "/proc/self/exe", "/usr/bin/pamac-daemon",
    "/bin/pamac-daemon", "/usr/lib/snapd/snapd", "/usr/local/bin/dockerd", "/usr/bin/crio", "/usr/sbin/crond",
    "/opt/puppetlabs/puppet/bin/ruby", "/usr/libexec/platform-python", "/kaniko/kaniko-executor",
    "/usr/local/bin/dockerd", "/usr/bin/podman", "/bin/install", "/proc/self/exe", "/usr/lib/systemd/systemd",
    "/usr/sbin/sshd", "/usr/bin/gitlab-runner", "/opt/gitlab/embedded/bin/ruby", "/usr/sbin/gdm", "/usr/bin/install",
    "/usr/local/manageengine/uems_agent/bin/dcregister", "/usr/local/bin/pacman", "/usr/libexec/packagekitd",
    "./usr/bin/podman", "/usr/lib/dracut/dracut-install", "/usr/bin/dnf5", "/kaniko/executor", "/usr/bin/buildah",
    "/usr/sbin/yum-cron"
  ) or
  process.executable like~ (
    "/nix/store/*", "/var/lib/dpkg/*", "/tmp/vmis.*", "/snap/*", "/dev/fd/*", "/usr/lib/virtualbox/*",
    "/var/lib/docker/overlay2/*/dockerd"
  ) or
  file.extension in ("swp", "swpx", "swx", "dpkg-remove") or
  (process.name == "sed" and file.name : "sed*")
)

// Title: persistence_dynamic_linker_backup.toml
// Source: detection-rules::rules/linux/persistence_dynamic_linker_backup.toml
// Section: EQL Rule
// Rule Name: Dynamic Linker Copy
// Author: Elastic
// Description:
// Detects the copying of the Linux dynamic loader binary and subsequent file creation for the purpose of creating a backup
// copy. This technique was seen recently being utilized by Linux malware prior to patching the dynamic loader in order to
// inject and preload a malicious shared object file. This activity should never occur and if it does then it should be
// considered highly suspicious or malicious.
// Integration: endpoint, sentinel_one_cloud_funnel
// Language: eql
// UUID: df6f62d9-caab-4b88-affa-044f4395a1e0
// Type: eql

sequence by process.entity_id with maxspan=1m
  [process where host.os.type == "linux" and event.type == "start" and process.name in ("cp", "rsync", "mv") and
  process.args in (
   "/lib/x86_64-linux-gnu/ld-linux-x86-64.so.2", "/etc/ld.so.preload", "/lib64/ld-linux-x86-64.so.2",
   "/usr/lib/x86_64-linux-gnu/ld-linux-x86-64.so.2", "/usr/lib64/ld-linux-x86-64.so.2"
  ) and
  not process.args like ("/var/tmp/mkinitramfs*", "/var/tmp/dracut*", "/tmp/mkinitcpio*")]
[file where host.os.type == "linux" and event.action == "creation" and (file.extension == "so" or file.name like "*.so.*")]

// Title: persistence_extract_initramfs_via_cpio.toml
// Source: detection-rules::rules/linux/persistence_extract_initramfs_via_cpio.toml
// Section: EQL Rule
// Rule Name: Initramfs Extraction via CPIO
// Author: Elastic
// Description:
// This rule detects the extraction of an initramfs image using the "cpio" command on Linux systems. The "cpio" command is
// used to create or extract cpio archives. Attackers may extract the initramfs image to modify the contents or add
// malicious files, which can be leveraged to maintain persistence on the system.
// Integration: endpoint, auditd_manager, crowdstrike, sentinel_one_cloud_funnel
// Language: eql
// UUID: 17b3fcd1-90fb-4f5d-858c-dc1d998fa368
// Type: eql

process where host.os.type == "linux" and event.type == "start" and
event.action in ("exec", "exec_event", "start", "ProcessRollup2", "executed") and
process.name == "cpio" and process.args in ("-H", "--format") and process.args == "newc" and
not (
  process.parent.name in ("mkinitramfs", "dracut") or
  ?process.parent.executable like~ ("/usr/share/initramfs-tools/*", "/nix/store/*") or
  ?process.parent.args in (
    "/bin/dracut", "/usr/share/initramfs-tools/hooks/amd64_microcode", "/usr/bin/dracut", "/usr/sbin/mkinitramfs",
    "/usr/sbin/dracut", "/usr/bin/update-microcode-initrd"
  ) or
  process.args like ("/var/tmp/mkinitramfs_*", "/tmp/tmp.*/mkinitramfs_*") or
  ?process.working_directory like (
    "/var/tmp/mkinitramfs-*", "/tmp/microcode-initrd_*", "/var/tmp/mkinitramfs-*", "/var/tmp/dracut.*",
    "/var/tmp/mkinitramfs_*", "/var/tmp/supermin*/init.d"
  )
)

// Title: persistence_git_hook_execution.toml
// Source: detection-rules::rules/linux/persistence_git_hook_execution.toml
// Section: EQL Rule
// Rule Name: Git Hook Command Execution
// Author: Elastic
// Description:
// This rule detects the execution of a potentially malicious process from a Git hook. Git hooks are scripts that Git
// executes before or after events such as: commit, push, and receive. An attacker can abuse Git hooks to execute arbitrary
// commands on the system and establish persistence.
// Integration: endpoint, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: dc61f382-dc0c-4cc0-a845-069f2a071704
// Type: eql

sequence by host.id with maxspan=3s
  [process where host.os.type == "linux" and event.type == "start" and event.action in ("exec", "start", "ProcessRollup2") and
   process.parent.name == "git" and process.args like ".git/hooks/*" and
   process.name in ("bash", "dash", "sh", "tcsh", "csh", "zsh", "ksh", "fish")
  ] by process.entity_id
  [process where host.os.type == "linux" and event.type == "start" and event.action in ("exec", "start", "ProcessRollup2") and
   process.parent.name in ("bash", "dash", "sh", "tcsh", "csh", "zsh", "ksh", "fish")] by process.parent.entity_id

// Title: persistence_git_hook_file_creation.toml
// Source: detection-rules::rules/linux/persistence_git_hook_file_creation.toml
// Section: EQL Rule
// Rule Name: Git Hook Created or Modified
// Author: Elastic
// Description:
// This rule detects the creation or modification of a Git hook file on a Linux system. Git hooks are scripts that Git
// executes before or after events such as commit, push, and receive. They are used to automate tasks, enforce policies,
// and customize Git's behavior. Attackers can abuse Git hooks to maintain persistence on a system by executing malicious
// code whenever a specific Git event occurs.
// Integration: endpoint, sentinel_one_cloud_funnel
// Language: eql
// UUID: ac531fcc-1d3b-476d-bbb5-1357728c9a37
// Type: eql

file where host.os.type == "linux" and event.type == "creation" and file.path like "*.git/hooks/*" and
file.extension == null and process.executable != null and not (
  process.executable in (
    "/bin/dpkg", "/usr/bin/dpkg", "/bin/dockerd", "/usr/bin/dockerd", "/usr/sbin/dockerd", "/bin/microdnf",
    "/usr/bin/microdnf", "/bin/rpm", "/usr/bin/rpm", "/bin/snapd", "/usr/bin/snapd", "/bin/yum", "/usr/bin/yum",
    "/bin/dnf", "/usr/bin/dnf", "/bin/podman", "/usr/bin/podman", "/bin/dnf-automatic", "/usr/bin/dnf-automatic",
    "/bin/pacman", "/usr/bin/pacman", "/usr/bin/dpkg-divert", "/bin/dpkg-divert", "/sbin/apk", "/usr/sbin/apk",
    "/usr/local/sbin/apk", "/usr/bin/apt", "/usr/sbin/pacman", "/bin/podman", "/usr/bin/podman", "/usr/bin/puppet",
    "/bin/puppet", "/opt/puppetlabs/puppet/bin/puppet", "/usr/bin/chef-client", "/bin/chef-client",
    "/bin/autossl_check", "/usr/bin/autossl_check", "/proc/self/exe", "/usr/bin/pamac-daemon", "/bin/pamac-daemon",
    "/usr/local/bin/dockerd", "/sbin/dockerd", "/usr/bin/fuse-overlayfs", "/usr/local/bin/gitlab-runner",
    "/usr/bin/coreutils", "/usr/bin/nautilus"
  ) or
  process.executable like (
    "/nix/store/*", "/var/lib/dpkg/*", "/snap/*", "/dev/fd/*", "/run/k3s/containerd/io.containerd.runtime.v2.task/k8s.io/*/r10k"
  ) or
  process.name in ("git", "dirname", "tar", "gitea", "git-lfs") or
  (process.name == "sed" and file.name : "sed*") or
  (process.name == "perl" and file.name : "e2scrub_all.tmp*")
)

// Title: persistence_git_hook_netcon.toml
// Source: detection-rules::rules/linux/persistence_git_hook_netcon.toml
// Section: EQL Rule
// Rule Name: Git Hook Egress Network Connection
// Author: Elastic
// Description:
// This rule detects a suspicious egress network connection attempt from a Git hook script. Git hooks are scripts that Git
// executes before or after events such as: commit, push, and receive. An attacker can abuse these features to execute
// arbitrary commands on the system, establish persistence or to initialize a network connection to a remote server and
// exfiltrate data or download additional payloads.
// Integration: endpoint
// Language: eql
// UUID: 9822c5a1-1494-42de-b197-487197bb540c
// Type: eql

sequence by host.id with maxspan=3s
  [process where host.os.type == "linux" and event.type == "start" and event.action == "exec" and
   process.parent.name == "git" and process.args like ".git/hooks/*" and
   process.name in ("bash", "dash", "sh", "tcsh", "csh", "zsh", "ksh", "fish") and
   not (process.name like "python*" and process.command_line like "*pip*")
  ] by process.entity_id
  [network where host.os.type == "linux" and event.type == "start" and event.action == "connection_attempted" and not (
     destination.ip == null or destination.ip == "0.0.0.0" or cidrmatch(
       destination.ip, "10.0.0.0/8", "127.0.0.0/8", "169.254.0.0/16", "172.16.0.0/12", "192.0.0.0/24", "192.0.0.0/29",
       "192.0.0.8/32", "192.0.0.9/32", "192.0.0.10/32", "192.0.0.170/32", "192.0.0.171/32", "192.0.2.0/24",
       "192.31.196.0/24", "192.52.193.0/24", "192.168.0.0/16", "192.88.99.0/24", "224.0.0.0/4", "100.64.0.0/10",
       "192.175.48.0/24","198.18.0.0/15", "198.51.100.0/24", "203.0.113.0/24", "240.0.0.0/4", "::1", "FE80::/10",
       "FF00::/8", "172.31.0.0/16"
     )
   )
  ] by process.parent.entity_id

// Title: persistence_git_hook_process_execution.toml
// Source: detection-rules::rules/linux/persistence_git_hook_process_execution.toml
// Section: EQL Rule
// Rule Name: Git Hook Child Process
// Author: Elastic
// Description:
// This rule detects child processes spawned by Git hooks. Git hooks are scripts that Git executes before or after events
// such as commit, push, and receive. The rule identifies child processes spawned by Git hooks that are not typically
// spawned by the Git process itself. This behavior may indicate an attacker attempting to hide malicious activity by
// leveraging the legitimate Git process to execute unauthorized commands.
// Integration: endpoint, crowdstrike, sentinel_one_cloud_funnel
// Language: eql
// UUID: 7ce5e1c7-6a49-45e6-a101-0720d185667f
// Type: eql

process where host.os.type == "linux" and event.type == "start" and
event.action in ("exec", "exec_event", "start", "ProcessRollup2") and
process.parent.name in (
  "applypatch-msg", "commit-msg", "fsmonitor-watchman", "post-update", "post-checkout", "post-commit",
  "pre-applypatch", "pre-commit", "pre-merge-commit", "prepare-commit-msg", "pre-push", "pre-rebase", "pre-receive",
  "push-to-checkout", "update", "post-receive", "pre-auto-gc", "post-rewrite", "sendemail-validate", "p4-pre-submit",
  "post-index-change", "post-merge", "post-applypatch"
) and
(
  process.name in ("nohup", "setsid", "disown", "bash", "dash", "sh", "tcsh", "csh", "zsh", "ksh", "fish") or
  process.name like ("php*", "perl*", "ruby*", "lua*") or
  process.executable like (
    "/boot/*", "/dev/shm/*", "/etc/cron.*/*", "/etc/init.d/*", "/etc/update-motd.d/*",
    "/run/*", "/srv/*", "/tmp/*", "/var/tmp/*", "/var/log/*"
  )
) and
not process.name in ("git", "dirname")

// Title: persistence_grub_configuration_creation.toml
// Source: detection-rules::rules/linux/persistence_grub_configuration_creation.toml
// Section: EQL Rule
// Rule Name: GRUB Configuration File Creation
// Author: Elastic
// Description:
// This rule detects the creation of GRUB configuration files on Linux systems. The GRUB configuration file is used to
// configure the boot loader, which is responsible for loading the operating system. Attackers may create malicious GRUB
// configuration files to execute arbitrary code or escalate privileges during the boot process, which can be leveraged to
// maintain persistence on the system.
// Integration: endpoint, sentinel_one_cloud_funnel
// Language: eql
// UUID: ce4a32e5-32aa-47e6-80da-ced6d234387d
// Type: eql

file where host.os.type == "linux" and event.type == "creation" and process.executable != null and file.path like~ (
  "/etc/default/grub.d/*", "/etc/default/grub", "/etc/grub.d/*",
  "/boot/grub2/grub.cfg", "/boot/grub/grub.cfg", "/boot/efi/EFI/*/grub.cfg",
  "/etc/sysconfig/grub"
) and not (
  /* Too many FPs from Python automation */
  process.name like ("python*", "platform-python*") or
  process.executable in (
    "/bin/dpkg", "/usr/bin/dpkg", "/bin/dockerd", "/usr/bin/dockerd", "/usr/sbin/dockerd", "/bin/microdnf",
    "/usr/bin/microdnf", "/bin/rpm", "/usr/bin/rpm", "/bin/snapd", "/usr/bin/snapd", "/bin/yum", "/usr/bin/yum",
    "/bin/dnf", "/usr/bin/dnf", "/bin/podman", "/usr/bin/podman", "/bin/dnf-automatic", "/usr/bin/dnf-automatic",
    "/bin/pacman", "/usr/bin/pacman", "/usr/bin/dpkg-divert", "/bin/dpkg-divert", "/sbin/apk", "/usr/sbin/apk",
    "/usr/local/sbin/apk", "/usr/bin/apt", "/usr/sbin/pacman", "/bin/podman", "/usr/bin/podman", "/usr/bin/puppet",
    "/bin/puppet", "/opt/puppetlabs/puppet/bin/puppet", "/usr/bin/chef-client", "/bin/chef-client",
    "/bin/autossl_check", "/usr/bin/autossl_check", "/proc/self/exe", "/usr/bin/pamac-daemon",
    "/bin/pamac-daemon", "/usr/lib/snapd/snapd", "/usr/local/bin/dockerd", "/usr/bin/crio", "/usr/sbin/crond",
    "/opt/puppetlabs/puppet/bin/ruby", "/usr/libexec/platform-python", "/kaniko/kaniko-executor",
    "/usr/local/bin/dockerd", "/usr/bin/podman", "/bin/install", "/proc/self/exe", "/usr/lib/systemd/systemd",
    "/usr/sbin/sshd", "/usr/bin/gitlab-runner", "/opt/gitlab/embedded/bin/ruby", "/usr/sbin/gdm", "/usr/bin/install",
    "/usr/local/manageengine/uems_agent/bin/dcregister", "/usr/local/bin/pacman", "./usr/bin/podman", "/usr/bin/dnf5",
    "/usr/sbin/yum-cron"
  ) or
  process.executable like~ (
    "/nix/store/*", "/var/lib/dpkg/*", "/tmp/vmis.*", "/snap/*", "/dev/fd/*", "/usr/lib/virtualbox/*"
  ) or
  file.extension in ("swp", "swpx", "swx", "dpkg-remove") or
  (process.name == "sed" and file.name : "sed*")
)

// Title: persistence_grub_makeconfig.toml
// Source: detection-rules::rules/linux/persistence_grub_makeconfig.toml
// Section: EQL Rule
// Rule Name: GRUB Configuration Generation through Built-in Utilities
// Author: Elastic
// Description:
// This rule detects the generation of a new GRUB configuration file using built-in Linux commands. The GRUB configuration
// file is used to configure the GRUB bootloader, which is responsible for loading the Linux kernel and initramfs image
// during the boot process. Attackers may use these built-in utilities to generate a new GRUB configuration file that
// includes malicious kernel parameters or boot options, which can be leveraged to maintain persistence on the system.
// Integration: endpoint, crowdstrike, sentinel_one_cloud_funnel
// Language: eql
// UUID: aabdad51-51fb-4a66-9d82-3873e42accb8
// Type: eql

process where host.os.type == "linux" and event.type == "start" and
event.action in ("exec", "exec_event", "start", "ProcessRollup2") and
process.parent.executable != null and process.name in ("grub-mkconfig", "grub2-mkconfig", "update-grub") and not (
  process.parent.name in ("run-parts", "sudo", "update-grub", "pacman", "dockerd", "dnf", "rpm", "yum") or
  process.parent.executable like (
    "/var/lib/dpkg/info/*", "/usr/lib/bootloader/grub2-efi/config", "/tmp/newroot/*", "/usr/lib/kernel/install.d/*",
    "/run/user/*/.bubblewrap/*/timeout"
  ) or
  process.parent.executable in (
    "/usr/bin/timeout", "/usr/sbin/nvidia-boot-update", "/usr/lib/oci-linux-config/misc_updates.sh",
    "/opt/puppetlabs/puppet/bin/puppet", "/usr/sbin/selinux-activate", "/usr/lib/skylight/stop-workspace",
    "/var/lib/aws-replication-agent/install_agent", "/usr/local/CTS/bin/apply_personality",
    "/opt/puppetlabs/puppet/bin/ruby"
  ) or
  (process.parent.name like ("python*", "platform-python*") and process.parent.command_line like "*ansible*")
)

// Title: persistence_init_d_file_creation.toml
// Source: detection-rules::rules/linux/persistence_init_d_file_creation.toml
// Section: EQL Rule
// Rule Name: System V Init Script Created
// Author: Elastic
// Description:
// Files that are placed in the "/etc/init.d/" directory in Unix can be used to start custom applications, services, scripts
// or commands during start-up. Init.d has been mostly replaced in favor of Systemd. However, the "systemd-sysv-generator"
// can convert init.d files to service unit files that run at boot. Adversaries may add or alter files located in the
// "/etc/init.d/" directory to execute malicious code upon boot in order to gain persistence on the system.
// Integration: endpoint, sentinel_one_cloud_funnel
// Language: eql
// UUID: 474fd20e-14cc-49c5-8160-d9ab4ba16c8b
// Type: eql

file where host.os.type == "linux" and event.action in ("creation", "file_create_event", "rename", "file_rename_event")
and file.path like "/etc/init.d/*" and not (
  process.executable in (
    "/bin/dpkg", "/usr/bin/dpkg", "/bin/dockerd", "/usr/bin/dockerd", "/usr/sbin/dockerd", "/bin/microdnf",
    "/usr/bin/microdnf", "/bin/rpm", "/usr/bin/rpm", "/bin/snapd", "/usr/bin/snapd", "/bin/yum", "/usr/bin/yum",
    "/bin/dnf", "/usr/bin/dnf", "/bin/podman", "/usr/bin/podman", "/bin/dnf-automatic", "/usr/bin/dnf-automatic",
    "/bin/pacman", "/usr/bin/pacman", "/usr/bin/dpkg-divert", "/bin/dpkg-divert", "/sbin/apk", "/usr/sbin/apk",
    "/usr/local/sbin/apk", "/usr/bin/apt", "/usr/sbin/pacman", "/bin/podman", "/usr/bin/podman", "/usr/bin/puppet",
    "/bin/puppet", "/opt/puppetlabs/puppet/bin/puppet", "/usr/bin/chef-client", "/bin/chef-client", "./envbuilder/bin/envbuilder",
    "/bin/autossl_check", "/usr/bin/autossl_check", "/proc/self/exe", "/usr/bin/pamac-daemon", "/opt/puppetlabs/puppet/bin/ruby",
    "/bin/pamac-daemon", "/usr/lib/snapd/snapd", "/usr/local/bin/dockerd", "./usr/bin/podman", "/usr/lib/systemd/systemd",
    "/usr/bin/buildah", "/dev/.buildkit_qemu_emulator", "/usr/lib/nvidia/post-install", "/usr/bin/dnf5", "/usr/sbin/yum-cron"
  ) or
  file.extension in ("swp", "swpx", "swx", "dpkg-remove", "dpkg-new") or
  ?file.Ext.original.name like "*.dpkg-new" or
  file.path like ("/etc/init.d/*beat*", "/etc/init.d/elastic-agent*") or
  process.executable like (
    "/nix/store/*", "/var/lib/dpkg/*", "/snap/*", "/dev/fd/*", "/usr/lib/virtualbox/*", "/var/lib/docker/overlay2/*/dockerd ",
    "/var/lib/containers/storage/overlay/*/dockerd"
  ) or
  process.name in ("docker-init", "jumpcloud-agent", "crio") or
  process.executable == null or
  process.name in ("executor", "univention-config-registry", "install", "dockerd-entrypoint.sh", "platform-python*", "ssm-agent-worker") or
  (process.name == "ln" and file.path : "/etc/init.d/rc*.d/*") or
  (process.name == "sed" and file.name : "sed*") or
  (process.name == "perl" and file.name : "e2scrub_all.tmp*") or
  (process.name == "cp" and file.path == "/etc/init.d/unified-monitoring-agent") or
  (process.name == "./vmware-install.pl" and file.path == "/etc/init.d/vmware-tools")
)

// Title: persistence_insmod_kernel_module_load.toml
// Source: detection-rules::rules/linux/persistence_insmod_kernel_module_load.toml
// Section: EQL Rule
// Rule Name: Kernel Module Load via Built-in Utility
// Author: Elastic
// Description:
// Detects the use of the insmod binary to load a Linux kernel object file. Threat actors can use this binary, given they
// have root privileges, to load a rootkit on a system providing them with complete control and the ability to hide from
// security products. Manually loading a kernel module in this manner should not be at all common and can indicate
// suspicious or malicious behavior.
// Integration: endpoint
// Language: eql
// UUID: 2339f03c-f53f-40fa-834b-40c5983fc41f
// Type: eql

process where host.os.type == "linux" and event.type == "start" and event.action == "load_module" and
(
  (process.name == "kmod" and process.args == "insmod" and process.args like~ "*.ko*") or
  (process.name == "kmod" and process.args == "modprobe" and not process.args in ("-r", "--remove")) or
  (process.name == "insmod" and process.args like~ "*.ko*") or
  (process.name == "modprobe" and not process.args in ("-r", "--remove"))
) and
not (
  process.parent.executable like ("/opt/ds_agent/*", "/opt/TrendMicro/vls_agent/*", "/opt/intel/oneapi/*") or
  process.working_directory in ("/opt/vinchin/agent", "/var/opt/ds_agent/am", "/opt/ds_agent", "/var/opt/TrendMicro/vls_agent/am") or
  process.parent.executable in (
    "/usr/lib/uptrack/ksplice-apply", "/opt/commvault/commvault/Base/linux_drv", "/opt/cisco/amp/bin/cisco-amp-helper",
    "/usr/bin/kcarectl", "/usr/share/ksplice/ksplice-apply", "/opt/commvault/Base/linux_drv", "/usr/sbin/veeamsnap-loader",
    "/bin/falcoctl", "/usr/sbin/veeamworker"
  ) or
  process.parent.executable like (
    "/sbin/iptables-multi*", "/var/ossec/bin/wazuh-modulesd", "/usr/sbin/mkinitramfs",
    "/usr/share/initramfs-tools/hooks/lvm2", "/usr/lpp/mmfs/bin/*", "/opt/forticlient/*",
    "/opt/traps/bin/*", "/snap/lxd/*/sbin/lxd", "/usr/sbin/xtables*"
  ) or
  (process.parent.name like ("python*", "platform-python*") and process.parent.args in ("--smart-update", "--auto-update")) or
  process.args in ("--showconfig", "--dump-modversions") or
  (
    process.name == "modprobe" and process.args == "-q" and process.args == "--" and
    (process.args in ("net-pf-10", "binfmt-464c") or process.args like ("netdev-*", "block-major-*"))
  ) or
  (
    process.name == "modprobe" and process.args == "-n" and process.args == "-v" and
    process.args in ("usb-storage", "dccp", "squashfs", "udf", "sctp", "cramfs", "hfsplus", "rds", "hfs", "jffs2", "freevxfs", "vfat", "overlay")
  ) or
  process.parent.args like "/usr/share/initramfs-tools/hooks/*"
)

// Title: persistence_kde_autostart_modification.toml
// Source: detection-rules::rules/linux/persistence_kde_autostart_modification.toml
// Section: EQL Rule
// Rule Name: KDE AutoStart Script or Desktop File Creation
// Author: Elastic
// Description:
// Identifies the creation or modification of a K Desktop Environment (KDE) AutoStart script or desktop file that will
// execute upon each user logon. Adversaries may abuse this method for persistence.
// Integration: endpoint, sentinel_one_cloud_funnel
// Language: eql
// UUID: e3e904b3-0a8e-4e68-86a8-977a163e21d3
// Type: eql

file where host.os.type == "linux" and event.type == "creation" and process.executable != null and
file.extension in ("sh", "desktop") and
file.path like (
  "/home/*/.config/autostart/*", "/root/.config/autostart/*",
  "/home/*/.kde/Autostart/*", "/root/.kde/Autostart/*",
  "/home/*/.kde4/Autostart/*", "/root/.kde4/Autostart/*",
  "/home/*/.kde/share/autostart/*", "/root/.kde/share/autostart/*",
  "/home/*/.kde4/share/autostart/*", "/root/.kde4/share/autostart/*",
  "/home/*/.local/share/autostart/*", "/root/.local/share/autostart/*",
  "/home/*/.config/autostart-scripts/*", "/root/.config/autostart-scripts/*",
  "/etc/xdg/autostart/*", "/usr/share/autostart/*"
) and
not (
  process.name in (
    "yum", "dpkg", "install", "dnf", "teams", "yum-cron", "dnf-automatic", "docker", "dockerd", "rpm", "pacman",
    "podman", "nautilus", "remmina", "cinnamon-settings.py", "executor", "xfce4-clipman", "jetbrains-toolbox",
    "ansible-admin", "apk"
  ) or
  process.executable in (
    "/usr/bin/dnf5", "/usr/libexec/xdg-desktop-portal", "/usr/sbin/mkhomedir_helper", "/sbin/mkhomedir_helper",
    "/usr/bin/crio", "/usr/sbin/useradd", "/usr/bin/nextcloud", "/usr/bin/sealert", "/opt/google/chrome/chrome",
    "/usr/bin/pamac-daemon", "/usr/sbin/sshd", "/usr/sbin/gdm", "/usr/libexec/platform-python"
  ) or
  process.executable like "/home/*/.MathWorks/*/glnxa64/mlcpostinstall"
)

// Title: persistence_kernel_driver_load.toml
// Source: detection-rules::rules/linux/persistence_kernel_driver_load.toml
// Section: EQL Rule
// Rule Name: Kernel Driver Load
// Author: Elastic
// Description:
// Detects the loading of a Linux kernel module through system calls. Threat actors may leverage Linux kernel modules to
// load a rootkit on a system providing them with complete control and the ability to hide from security products. As other
// rules monitor for the addition of Linux kernel modules through system utilities or .ko files, this rule covers the gap
// that evasive rootkits leverage by monitoring for kernel module additions on the lowest level through auditd_manager.
// Integration: auditd_manager
// Language: eql
// UUID: 3e12a439-d002-4944-bc42-171c0dcb9b96
// Type: eql

driver where host.os.type == "linux" and event.action == "loaded-kernel-module" and
auditd.data.syscall in ("init_module", "finit_module")

// Title: persistence_kernel_driver_load_by_non_root.toml
// Source: detection-rules::rules/linux/persistence_kernel_driver_load_by_non_root.toml
// Section: EQL Rule
// Rule Name: Kernel Driver Load by non-root User
// Author: Elastic
// Description:
// Detects the loading of a Linux kernel module by a non-root user through system calls. Threat actors may leverage Linux
// kernel modules to load a rootkit on a system providing them with complete control and the ability to hide from security
// products. As other rules monitor for the addition of Linux kernel modules through system utilities or .ko files, this
// rule covers the gap that evasive rootkits leverage by monitoring for kernel module additions on the lowest level through
// auditd_manager.
// Integration: auditd_manager
// Language: eql
// UUID: ba81c182-4287-489d-af4d-8ae834b06040
// Type: eql

driver where host.os.type == "linux" and event.action == "loaded-kernel-module" and
auditd.data.syscall in ("init_module", "finit_module") and user.id != "0"

// Title: persistence_kernel_module_load_from_unusual_location.toml
// Source: detection-rules::rules/linux/persistence_kernel_module_load_from_unusual_location.toml
// Section: EQL Rule
// Rule Name: Kernel Module Load from Unusual Location
// Author: Elastic
// Description:
// This rule detects the loading of a kernel module from an unusual location. Threat actors may use
// this technique to maintain persistence on a system by loading a kernel module into the kernel namespace.
// This behavior is strongly related to the presence of a rootkit on the system.
// Integration: endpoint
// Language: eql
// UUID: d54b649d-46d0-4b4c-a9a7-1bc9fc458d3c
// Type: eql

process where host.os.type == "linux" and event.type == "start" and event.action == "exec" and (
  (process.name == "kmod" and process.args == "insmod" and process.args like~ "*.ko*") or
  (process.name == "kmod" and process.args == "modprobe" and not process.args in ("-r", "--remove")) or
  (process.name == "insmod" and process.args like~ "*.ko*") or
  (process.name == "modprobe" and not process.args in ("-r", "--remove"))
) and (
  process.working_directory like (
    "/tmp*", "/var/tmp*", "/dev/shm*", "/run*", "/var/run*", "/home*/*", "/root*",
    "/var/www*", "/boot*", "/srv*", "/mnt*", "/media*"
  ) or
  process.parent.working_directory like (
    "/tmp*", "/var/tmp*", "/dev/shm*", "/run*", "/var/run*", "/home*/*", "/root*",
    "/var/www*", "/boot*", "/srv*", "/mnt*", "/media*"
  ) or
  process.args like (
    "/tmp/*", "/var/tmp/*", "/dev/shm/*", "/run/*", "/var/run/*", "/home/*/*", "/root/*",
    "/var/www/*", "/boot/*", "/srv/*", "/mnt/*", "/media/*", "./*"
  )
) and
not (
  process.parent.executable == "/usr/bin/podman" or
  process.working_directory like "/tmp/newroot"
)

// Title: persistence_kubernetes_sensitive_file_activity.toml
// Source: detection-rules::rules/linux/persistence_kubernetes_sensitive_file_activity.toml
// Section: EQL Rule
// Rule Name: Kubernetes Sensitive Configuration File Activity
// Author: Elastic
// Description:
// This rule detects the creation or modification of sensitive Kubernetes configuration files on Linux systems. These files
// include Kubernetes manifests, PKI files, and configuration files that are critical for the operation of Kubernetes clusters.
// Monitoring these files helps identify potential unauthorized changes or misconfigurations that could lead to security
// vulnerabilities in Kubernetes environments. Attackers may attempt to modify these files to gain persistence or to
// deploy malicious containers within the Kubernetes cluster.
// Integration: endpoint, cloud_defend
// Language: eql
// UUID: 0fe2290a-2664-4c9c-8263-b88904f12f0d
// Type: eql

file where host.os.type == "linux" and event.type != "deletion" and file.path like (
  "/etc/kubernetes/manifests/*",
  "/etc/kubernetes/pki/*",
  "/etc/kubernetes/*.conf"
) and not (
  process.name in ("kubeadm", "kubelet", "dpkg", "sed") or
  (process.name in ("vi", "vim", "vim.basic") and file.extension in ("swx", "swp"))
)

// Title: persistence_kworker_file_creation.toml
// Source: detection-rules::rules/linux/persistence_kworker_file_creation.toml
// Section: EQL Rule
// Rule Name: Suspicious File Creation via Kworker
// Author: Elastic
// Description:
// This rule monitors for a file creation event originating from a kworker parent process. kworker, or kernel worker,
// processes are part of the kernel's workqueue mechanism. They are responsible for executing work that has been scheduled
// to be done in kernel space, which might include tasks like handling interrupts, background activities, and other
// kernel-related tasks. Attackers may attempt to evade detection by masquerading as a kernel worker process.
// Integration: endpoint, sentinel_one_cloud_funnel
// Language: eql
// UUID: ae343298-97bc-47bc-9ea2-5f2ad831c16e
// Type: eql

file where host.os.type == "linux" and event.action in ("creation", "file_create_event") and
process.name : "kworker*" and not (
  process.name : "kworker*kcryptd*" or
  file.path like (
    "/var/log/*", "/var/crash/*", "/var/run/*", "/var/lib/systemd/coredump/*", "/var/spool/*",
    "/var/lib/nfs/nfsdcltrack/main.sqlite-journal", "/proc/*/cwd/core.*", "/var/run/apport.lock",
    "/var/spool/abrt/ccpp-*", "/var/lib/dynatrace/oneagent/*", "/var/lib/nfs*", "/run/user/*/.bubblewrap/*",
    "/etc/localtime/*", "/proc/*/cwd/core.*", "/tmp/sh-thd.*", "/var/lib/apport/coredump/*", "/var/tmp/abrt/ccpp*"
  )
)

// Title: persistence_linux_backdoor_user_creation.toml
// Source: detection-rules::rules/linux/persistence_linux_backdoor_user_creation.toml
// Section: EQL Rule
// Rule Name: Potential Linux Backdoor User Account Creation
// Author: Elastic
// Description:
