// Title: persistence_linux_user_added_to_privileged_group.toml
// Source: detection-rules::rules/linux/persistence_linux_user_added_to_privileged_group.toml
// Section: EQL Rule
// Rule Name: Linux User Added to Privileged Group
// Author: Elastic
// Description:
// Identifies attempts to add a user to a privileged group. Attackers may add users to a privileged group in order to
// establish persistence on a system.
// Integration: endpoint, auditd_manager, crowdstrike, sentinel_one_cloud_funnel
// Language: eql
// UUID: 43d6ec12-2b1c-47b5-8f35-e9de65551d3b
// Type: eql

process where host.os.type == "linux" and event.type == "start" and
event.action in ("exec", "exec_event", "start", "ProcessRollup2", "executed", "process_started") and
process.executable != null and process.args in (
  "root", "admin", "wheel", "staff", "sudo","disk", "video", "shadow", "lxc", "lxd"
) and
(
  process.name in ("usermod", "adduser") or
  (process.name == "gpasswd" and process.args in ("-a", "--add", "-M", "--members"))
