not (
  ?process.parent.executable like (
    "/usr/lib/google/guest_agent/core_plugin", "/usr/libexec/platform-python*", "/usr/lib/google/guest_agent/GuestAgentCorePlugin/core_plugin",
    "/usr/bin/google_guest_agent"
  ) or
  (
    ?process.entry_leader.executable == "/usr/lib/venv-salt-minion/bin/python.original" and
    ?process.entry_leader.args == "/usr/lib/venv-salt-minion/bin/salt-minion"
  )
)

// Title: persistence_lkm_configuration_file_creation.toml
// Source: detection-rules::rules/linux/persistence_lkm_configuration_file_creation.toml
// Section: EQL Rule
// Rule Name: Loadable Kernel Module Configuration File Creation
// Author: Elastic
// Description:
// This rule detects the creation of Loadable Kernel Module (LKM) configuration files. Attackers may create or modify these
// files to allow their LKMs to be loaded upon reboot, ensuring persistence on a compromised system.
// Integration: endpoint
// Language: eql
// UUID: 6e2355cc-c60a-4d92-a80c-e54a45ad2400
// Type: eql

file where host.os.type == "linux" and event.action == "creation" and process.executable != null and
file.path like (
  "/etc/modules", "/etc/modprobe.d/*", "/run/modprobe.d/*", "/usr/local/lib/modprobe.d/*", "/usr/lib/modprobe.d/*",
  "/lib/modprobe.d/*", "/etc/modules-load.d/*", "/run/modules-load.d/*", "/usr/local/lib/modules-load.d/*",
  "/usr/lib/modules-load.d/*"
) and not (
  process.executable in (
    "/bin/dpkg", "/usr/bin/dpkg", "/bin/dockerd", "/usr/bin/dockerd", "/usr/sbin/dockerd", "/bin/microdnf",
    "/usr/bin/microdnf", "/bin/rpm", "/usr/bin/rpm", "/bin/snapd", "/usr/bin/snapd", "/bin/yum", "/usr/bin/yum",
    "/bin/dnf", "/usr/bin/dnf", "/bin/podman", "/usr/bin/podman", "/bin/dnf-automatic", "/usr/bin/dnf-automatic",
    "/bin/pacman", "/usr/bin/pacman", "/usr/bin/dpkg-divert", "/bin/dpkg-divert", "/sbin/apk", "/usr/sbin/apk",
    "/usr/local/sbin/apk", "/usr/bin/apt", "/usr/sbin/pacman", "/bin/podman", "/usr/bin/podman", "/usr/bin/puppet",
    "/bin/puppet", "/opt/puppetlabs/puppet/bin/puppet", "/usr/bin/chef-client", "/bin/chef-client",
    "/bin/autossl_check", "/usr/bin/autossl_check", "/proc/self/exe", "/dev/fd/*",  "/usr/bin/pamac-daemon",
    "/bin/pamac-daemon", "/usr/local/bin/dockerd", "/opt/elasticbeanstalk/bin/platform-engine",
    "/opt/puppetlabs/puppet/bin/ruby", "/usr/libexec/platform-python", "/opt/imunify360/venv/bin/python3",
    "/opt/eset/efs/lib/utild", "/usr/sbin/anacron", "/usr/bin/podman", "/kaniko/kaniko-executor", "/usr/bin/prime-select",
    "/usr/lib/dracut/dracut-install", "/usr/bin/dnf5", "./usr/bin/podman", "/usr/libexec/packagekitd", "/usr/bin/buildah",
    "./usr/lib/snapd/snap-update-ns", "/usr/lib/snapd/snapd", "/usr/local/bin/podman", "/usr/sbin/yum-cron",
    "./usr/bin/qemu-aarch64-static", "/.envbuilder/bin/envbuilder"
  ) or
  file.extension in ("swp", "swpx", "swx", "dpkg-remove") or
  file.Ext.original.extension == "dpkg-new" or
  process.executable like (
    "/nix/store/*", "/var/lib/dpkg/info/kmod.postinst", "/tmp/vmis.*", "/snap/*", "/dev/fd/*",
    "/usr/libexec/platform-python*", "./snap/snapd/*/snap-update-ns"
  ) or
  process.executable == null or
  process.name in (
    "crond", "executor", "puppet", "droplet-agent.postinst", "cf-agent", "schedd", "imunify-notifier", "perl",
    "jumpcloud-agent", "crio", "dnf_install", "utild", "dockerd"
  ) or
  process.name like "python*" or
  (process.name == "sed" and file.name : "sed*") or
  (process.name == "perl" and file.name : "e2scrub_all.tmp*")
)

// Title: persistence_manual_dracut_execution.toml
// Source: detection-rules::rules/linux/persistence_manual_dracut_execution.toml
// Section: EQL Rule
// Rule Name: Manual Dracut Execution
// Author: Elastic
// Description:
// This rule detects manual execution of the "dracut" command on Linux systems. Dracut is a tool used to generate an
// initramfs image that is used to boot the system. Attackers may use "dracut" to create a custom initramfs image that
// includes malicious code or backdoors, allowing them to maintain persistence on the system.
// Integration: endpoint, crowdstrike, sentinel_one_cloud_funnel
// Language: eql
// UUID: 834ee026-f9f9-4ec7-b5e0-7fbfe84765f4
// Type: eql

process where host.os.type == "linux" and event.type == "start" and
event.action in ("exec", "exec_event", "start", "ProcessRollup2") and
process.name == "dracut" and process.parent.executable != null and not (
  process.parent.executable like (
    "/usr/lib/kernel/*", "/etc/kernel/install.d/*", "/var/lib/dpkg/info/dracut.postinst",
    "/tmp/newroot/*", "/usr/lib/module-init-tools/*", "/usr/bin/xargs", "/sbin/dkms",
    "/sbin/mkinitrd", "/usr/bin/timeout", "/usr/sbin/dkms", "/usr/bin/systemd-inhibit"
  ) or
  process.parent.name in (
    "dracut-install", "dracut", "run-parts", "weak-modules", "mkdumprd", "new-kernel-pkg", "sudo"
  ) or
  process.parent.args like~ ("/usr/bin/dracut-rebuild", "/var/tmp/rpm-tmp.*") or
  process.parent.command_line like~ "/bin/sh -c if command -v mkinitcpio*"
)

// Title: persistence_message_of_the_day_creation.toml
// Source: detection-rules::rules/linux/persistence_message_of_the_day_creation.toml
// Section: EQL Rule
// Rule Name: Message-of-the-Day (MOTD) File Creation
// Author: Elastic
// Description:
// This rule detects the creation of potentially malicious files within the default MOTD file directories. Message of the
// day (MOTD) is the message that is presented to the user when a user connects to a Linux server via SSH or a serial
// connection. Linux systems contain several default MOTD files located in the "/etc/update-motd.d/" directory. These
// scripts run as the root user every time a user connects over SSH or a serial connection. Adversaries may create
// malicious MOTD files that grant them persistence onto the target every time a user connects to the system by executing a
// backdoor script or command.
// Integration: endpoint
// Language: eql
// UUID: 96d11d31-9a79-480f-8401-da28b194608f
// Type: eql

file where host.os.type == "linux" and event.action == "creation" and file.path like "/etc/update-motd.d/*" and
not (
  process.executable in (
    "/bin/dpkg", "/usr/bin/dpkg", "/bin/dockerd", "/usr/bin/dockerd", "/usr/sbin/dockerd", "/bin/microdnf",
    "/usr/bin/microdnf", "/bin/rpm", "/usr/bin/rpm", "/bin/snapd", "/usr/bin/snapd", "/bin/yum", "/usr/bin/yum",
    "/bin/dnf", "/usr/bin/dnf", "/bin/podman", "/usr/bin/podman", "/bin/dnf-automatic", "/usr/bin/dnf-automatic",
    "/bin/pacman", "/usr/bin/pacman", "/usr/bin/dpkg-divert", "/bin/dpkg-divert", "/sbin/apk", "/usr/sbin/apk",
    "/usr/local/sbin/apk", "/usr/bin/apt", "/usr/sbin/pacman", "/bin/podman", "/usr/bin/podman", "/usr/bin/puppet",
    "/bin/puppet", "/opt/puppetlabs/puppet/bin/puppet", "/usr/bin/chef-client", "/bin/chef-client", "/usr/bin/buildah",
    "/bin/autossl_check", "/usr/bin/autossl_check", "/proc/self/exe", "/usr/bin/pamac-daemon", "/.envbuilder/bin/envbuilder",
    "/bin/pamac-daemon", "/usr/lib/snapd/snapd", "/usr/local/bin/dockerd", "./usr/bin/podman", "/opt/saltstack/salt/bin/python3.10",
    "/opt/puppetlabs/puppet/bin/ruby", "/usr/bin/crio"
  ) or
  file.extension in ("swp", "swpx", "swx", "dpkg-remove") or
  file.Ext.original.extension == "dpkg-new" or
  process.executable : (
    "/nix/store/*", "/var/lib/dpkg/*", "/tmp/vmis.*", "/snap/*", "/dev/fd/*", "/usr/lib/virtualbox/*"
  ) or
  process.executable == null or
  process.name in ("executor", "dockerd", "crio") or
  (process.name == "sed" and file.name : "sed*") or
  (process.name == "perl" and file.name : "e2scrub_all.tmp*")
)

// Title: persistence_message_of_the_day_execution.toml
// Source: detection-rules::rules/linux/persistence_message_of_the_day_execution.toml
// Section: EQL Rule
// Rule Name: Process Spawned from Message-of-the-Day (MOTD)
// Author: Elastic
// Description:
// Message of the day (MOTD) is the message that is presented to the user when a user connects to a Linux server via SSH or
// a serial connection. Linux systems contain several default MOTD files located in the "/etc/update-motd.d/" directory.
// These scripts run as the root user every time a user connects over SSH or a serial connection. Adversaries may create
// malicious MOTD files that grant them persistence onto the target every time a user connects to the system by executing a
// backdoor script or command. This rule detects the execution of potentially malicious processes through the MOTD utility.
// Integration: endpoint, sentinel_one_cloud_funnel
// Language: eql
// UUID: 4ec47004-b34a-42e6-8003-376a123ea447
// Type: eql

process where event.type == "start" and host.os.type == "linux" and event.action in ("exec", "exec_event", "start") and
process.parent.executable like "/etc/update-motd.d/*" and
(
  (
    process.name in ("bash", "dash", "sh", "tcsh", "csh", "zsh", "ksh", "fish") and
    (
      process.args : ("-i", "-l") or
      (process.parent.name == "socat" and process.parent.args : "*exec*")
    )
  ) or
  (
    process.name : ("nc", "ncat", "netcat", "nc.openbsd") and process.args_count >= 3 and 
    not process.args : ("-*z*", "-*l*")
  ) or
  (
    process.name : "python*" and process.args : "-c" and process.args : (
      "*import*pty*spawn*", "*import*subprocess*call*"
    )
  ) or
  (
    process.name : "perl*" and process.args : "-e" and process.args : "*socket*" and process.args : (
      "*exec*", "*system*"
    )
  ) or
  (
    process.name : "ruby*" and process.args : ("-e", "-rsocket") and process.args : (
      "*TCPSocket.new*", "*TCPSocket.open*"
    )
  ) or
  (
    process.name : "lua*" and process.args : "-e" and process.args : "*socket.tcp*" and process.args : (
      "*io.popen*", "*os.execute*"
    )
  ) or
  (process.name : "php*" and process.args : "-r" and process.args : "*fsockopen*" and process.args : "*/bin/*sh*") or 
  (process.name : ("awk", "gawk", "mawk", "nawk") and process.args : "*/inet/tcp/*") or 
  (process.name in ("openssl", "telnet")) or
  (
    process.args : (
      "./*", "/boot/*", "/dev/shm/*", "/etc/cron.*/*", "/etc/init.d/*", "/etc/update-motd.d/*", "/run/*", "/srv/*",
      "/tmp/*", "/var/tmp/*", "/var/log/*", "/opt/*"
    ) and process.args_count == 1
  )
) and 
not (
  process.parent.args == "--force" or
  process.args in ("/usr/games/lolcat", "/usr/bin/screenfetch") or
  process.parent.name == "system-crash-notification"
)

// Title: persistence_network_manager_dispatcher_persistence.toml
// Source: detection-rules::rules/linux/persistence_network_manager_dispatcher_persistence.toml
// Section: EQL Rule
// Rule Name: NetworkManager Dispatcher Script Creation
// Author: Elastic
// Description:
// This rule detects the creation of a NetworkManager dispatcher script on a Linux system. NetworkManager dispatcher
// scripts are shell scripts that NetworkManager executes when network interfaces change state. Attackers can abuse
// NetworkManager dispatcher scripts to maintain persistence on a system by executing malicious code whenever a network
// event occurs.
// Integration: endpoint, sentinel_one_cloud_funnel
// Language: eql
// UUID: 86aa8579-1526-4dff-97cd-3635eb0e0545
// Type: eql

file where host.os.type == "linux" and event.type == "creation" and file.path like "/etc/NetworkManager/dispatcher.d/*" and
not (
  process.executable in (
    "/bin/dpkg", "/usr/bin/dpkg", "/bin/dockerd", "/usr/bin/dockerd", "/usr/sbin/dockerd", "/bin/microdnf",
    "/usr/bin/microdnf", "/bin/rpm", "/usr/bin/rpm", "/bin/snapd", "/usr/bin/snapd", "/bin/yum", "/usr/bin/yum",
    "/bin/dnf", "/usr/bin/dnf", "/bin/podman", "/usr/bin/podman", "/bin/dnf-automatic", "/usr/bin/dnf-automatic",
    "/bin/pacman", "/usr/bin/pacman", "/usr/bin/dpkg-divert", "/bin/dpkg-divert", "/sbin/apk", "/usr/sbin/apk",
    "/usr/local/sbin/apk", "/usr/bin/apt", "/usr/sbin/pacman", "/bin/podman", "/usr/bin/podman", "/usr/bin/puppet",
    "/bin/puppet", "/opt/puppetlabs/puppet/bin/puppet", "/usr/bin/chef-client", "/bin/chef-client",
    "/bin/autossl_check", "/usr/bin/autossl_check", "/proc/self/exe",  "/usr/bin/pamac-daemon", "./usr/bin/podman",
    "/bin/pamac-daemon", "/usr/lib/snapd/snapd", "/usr/local/bin/dockerd", "/usr/bin/crio", "/usr/sbin/crond",
    "/opt/puppetlabs/puppet/bin/ruby", "/usr/libexec/platform-python", "/kaniko/kaniko-executor",
    "/usr/local/bin/dockerd", "/usr/bin/podman", "/bin/install", "/proc/self/exe", "/usr/lib/systemd/systemd",
    "/usr/sbin/sshd", "/usr/bin/gitlab-runner", "/opt/gitlab/embedded/bin/ruby", "/usr/sbin/gdm", "/usr/bin/install",
    "/usr/local/manageengine/uems_agent/bin/dcregister", "/usr/local/bin/pacman", "./usr/bin/qemu-aarch64-static"
  ) or
  process.executable like~ (
    "/nix/store/*", "/var/lib/dpkg/*", "/tmp/vmis.*", "/snap/*", "/dev/fd/*", "/usr/lib/virtualbox/*"
  ) or
  file.extension in ("swp", "swpx", "swx", "dpkg-remove") or
  (process.name == "sed" and file.name : "sed*") or
  (
    process.executable like ("/kaniko/executor", "/usr/libexec/platform-python*") and
    file.path like "/etc/NetworkManager/dispatcher.d/11-dhclient*"
  )
)

// Title: persistence_openssl_passwd_hash_generation.toml
// Source: detection-rules::rules/linux/persistence_openssl_passwd_hash_generation.toml
// Section: EQL Rule
// Rule Name: OpenSSL Password Hash Generation
// Author: Elastic
// Description:
// This rule detects the usage of the "openssl" binary to generate password hashes on Linux systems. The "openssl" command
// is a cryptographic utility that can be used to generate password hashes. Attackers may use "openssl" to generate
// password hashes for new user accounts or to change the password of existing accounts, which can be leveraged to maintain
// persistence on a Linux system.
// Integration: endpoint, auditd_manager, crowdstrike, sentinel_one_cloud_funnel
// Language: eql
// UUID: f4b857b3-faef-430d-b420-90be48647f00
// Type: eql

process where host.os.type == "linux" and event.type == "start" and
event.action in ("exec", "exec_event", "start", "ProcessRollup2", "executed") and process.name == "openssl"
and process.args == "passwd" and ?process.args_count >= 4 and
not process.args in ("-help", "--help", "-h")

// Title: persistence_pluggable_authentication_module_creation.toml
// Source: detection-rules::rules/linux/persistence_pluggable_authentication_module_creation.toml
// Section: EQL Rule
// Rule Name: Pluggable Authentication Module or Configuration Creation
// Author: Elastic
// Description:
// This rule monitors for the creation of Pluggable Authentication Module (PAM) shared object files or configuration
// files. Attackers may create these files to maintain persistence on a compromised system, or harvest account credentials.
// Integration: endpoint
// Language: eql
// UUID: f48ecc44-7d02-437d-9562-b838d2c41987
// Type: eql

file where host.os.type == "linux" and event.action == "creation" and process.executable != null and (
  (file.path like (
    "/lib/security/*", "/lib64/security/*", "/usr/lib/security/*", "/usr/lib64/security/*",
    "/lib/x86_64-linux-gnu/security/*", "/usr/lib/x86_64-linux-gnu/security/*"
  ) and file.extension == "so") or
  (file.path like "/etc/pam.d/*" and file.extension == null) or
  (file.path like "/etc/security/pam_*" or file.path == "/etc/pam.conf")
) and not (
  process.executable in (
    "/bin/dpkg", "/usr/bin/dpkg", "/bin/dockerd", "/usr/bin/dockerd", "/usr/sbin/dockerd", "/bin/microdnf",
    "/usr/bin/microdnf", "/bin/rpm", "/usr/bin/rpm", "/bin/snapd", "/usr/bin/snapd", "/bin/yum", "/usr/bin/yum",
    "/bin/dnf", "/usr/bin/dnf", "/bin/podman", "/usr/bin/podman", "/bin/dnf-automatic", "/usr/bin/dnf-automatic",
    "/bin/pacman", "/usr/bin/pacman", "/usr/bin/dpkg-divert", "/bin/dpkg-divert", "/sbin/apk", "/usr/sbin/apk",
    "/usr/local/sbin/apk", "/usr/bin/apt", "/usr/sbin/pacman", "/bin/podman", "/usr/bin/podman", "/usr/bin/puppet",
    "/bin/puppet", "/opt/puppetlabs/puppet/bin/puppet", "/usr/bin/chef-client", "/bin/chef-client",
    "/bin/autossl_check", "/usr/bin/autossl_check", "/proc/self/exe", "/usr/bin/pamac-daemon",
    "/bin/pamac-daemon", "/usr/lib/snapd/snapd", "/usr/local/bin/dockerd", "/usr/sbin/pam-auth-update",
    "/usr/lib/systemd/systemd", "/usr/libexec/packagekitd", "/usr/bin/bsdtar", "/sbin/pam-auth-update", "./user/bin/podman",
    "/usr/bin/dnf5", "/opt/puppetlabs/puppet/bin/ruby", "/usr/bin/crio", "/sbin/authconfig", "/usr/sbin/yum-cron",
    "/sbin/yum-cron", "/usr/local/psa/bin/dnf_install", "/opt/jc/bin/jumpcloud-agent", "./usr/bin/podman",
    "/kaniko/executor", "/opt/kaniko/executor", "/usr/bin/buildah", "/usr/sbin/pam-config",
    "./usr/lib/snapd/snap-update-ns", "/usr/bin/install", "/usr/bin/env"
  ) or
  file.path like (
    "/tmp/snap.rootfs_*/pam_*.so", "/tmp/newroot/lib/*/pam_*.so", "/tmp/newroot/usr/lib64/security/pam_*.so"
  ) or
  file.extension in ("swp", "swpx", "swx", "dpkg-remove") or
  file.Ext.original.extension == "dpkg-new" or
  file.Ext.original.name like "*.pam-new" or
  process.executable like (
    "/nix/store/*", "/var/lib/dpkg/*", "/snap/*", "/dev/fd/*", "/usr/lib/virtualbox/*", "/usr/bin/python*",
    "/opt/alt/python*/bin/python*", "/usr/libexec/platform-python*", "./snap/snapd/*/usr/lib/snapd/snap-update-ns"
  ) or
  (process.name == "sed" and file.name like~ "sed*") or
  (process.name == "perl" and file.name like~ "e2scrub_all.tmp*") or
  (process.name == "perl" and event.action == "rename" and file.Ext.original.name like "*.pam-new") or
  process.name like ("python*", "platform-python*", "dockerd") or
  (process.name == "vim.basic" and file.name like "*~")
)

// Title: persistence_pluggable_authentication_module_creation_in_unusual_dir.toml
// Source: detection-rules::rules/linux/persistence_pluggable_authentication_module_creation_in_unusual_dir.toml
// Section: EQL Rule
// Rule Name: Pluggable Authentication Module (PAM) Creation in Unusual Directory
// Author: Elastic
// Description:
// This rule detects the creation of Pluggable Authentication Module (PAM) shared object files in unusual directories.
// Attackers may compile PAM shared object files in temporary directories, to move them to system directories later,
// potentially allowing them to maintain persistence on a compromised system, or harvest account credentials.
// Integration: endpoint, sentinel_one_cloud_funnel
// Language: eql
// UUID: 5c832156-5785-4c9c-a2e7-0d80d2ba3daa
// Type: eql

file where host.os.type == "linux" and event.type == "creation" and file.name like "pam_*.so" and not file.path like (
  "/lib/security/*",
  "/lib64/security/*",
  "/lib/x86_64-linux-gnu/security/*",
  "/usr/lib/security/*",
  "/usr/lib64/security/*",
  "/usr/lib/x86_64-linux-gnu/security/*"
) and not (
  process.name in ("dockerd", "containerd", "steam", "buildkitd", "unsquashfs", "pacman", "executor") or
  file.path like (
    "/build/rootImage/nix/store/*", "/home/*/.local/share/containers/*", "/nix/store/*", "/var/lib/containerd/*",
    "/var/snap/*", "/usr/share/nix/nix/store/*", "/tmp/cura/squashfs-root/*", "/home/*/docker/*", "/tmp/containerd*",
    "/var/lib/rancher/*/agent/containerd/*", "/var/lib/lxc/*", "/var/lib/containers/storage/*", "/var/lib/checkpoint*",
    "/var/lib/docker/overlay2/*", "/srv/docker/*", "/podman/storage/*", "/opt/jail/driver-jail*", "/build/tmp/work/iot*",
    "/tmp/containers-root/*", "/cce-14/*", "/cce-usr/*", "/var/tmp/portage/*", "/media/*", "/data/var/lib/docker/overlay2/*",
    "/home/*/.cache/bazel/*", "/home/*/.cache/umu/*/SteamLinuxRuntime*"
  )
)

// Title: persistence_pluggable_authentication_module_pam_exec_backdoor_exec.toml
// Source: detection-rules::rules/linux/persistence_pluggable_authentication_module_pam_exec_backdoor_exec.toml
// Section: EQL Rule
// Rule Name: Potential Backdoor Execution Through PAM_EXEC
// Author: Elastic
// Description:
// This rule detects SSH session ID change followed by a suspicious SSHD child process, this may
// indicate the successful execution of a potentially malicious process through the Pluggable
// Authentication Module (PAM) utility. PAM is a framework used by Linux systems to authenticate
// users. Adversaries may create malicious PAM modules that grant them persistence onto the
// target every time a user logs in by executing a backdoor script or command.
// Integration: endpoint
// Language: eql
// UUID: 96f29282-ffcc-4ce7-834b-b17aee905568
// Type: eql

sequence by process.entity_id with maxspan=3s
  [process where host.os.type == "linux" and event.type == "change" and event.action == "session_id_change" and process.name in ("ssh", "sshd")]
  [process where host.os.type == "linux" and event.type == "start" and event.action == "exec" and process.parent.name in ("ssh", "sshd") and
   process.args_count == 2 and process.args like (
     "sh", "dash", "bash", "zsh",
     "perl*", "python*", "php*", "ruby*", "lua*",

     "/bin/sh", "/bin/dash", "/bin/bash", "/bin/zsh",
     "/bin/perl*", "/bin/python*", "/bin/php*", "/bin/ruby*", "/bin/lua*",

     "/usr/bin/sh", "/usr/bin/dash", "/usr/bin/bash", "/usr/bin/zsh",
     "/usr/bin/perl*", "/usr/bin/python*", "/usr/bin/php*", "/usr/bin/ruby*", "/usr/bin/lua*",

     "/usr/local/bin/sh", "/usr/local/bin/dash", "/usr/local/bin/bash", "/usr/local/bin/zsh",
     "/usr/local/bin/perl*", "/usr/local/bin/python*", "/usr/local/bin/php*", "/usr/local/bin/ruby*", "/usr/local/bin/lua*"
   ) and (
     process.name like ".*" or
     process.executable like (
       "/tmp/*", "/var/tmp/*", "/dev/shm/*", "./*", "/boot/*", "/sys/*", "/lost+found/*", "/media/*", "/proc/*", "/bin/*", "/usr/bin/*",
       "/sbin/*", "/usr/sbin/*", "/lib/*", "/lib64/*", "/usr/lib/*", "/usr/lib64/*", "/opt/*", "/var/lib/*", "/run/*", "/var/backups/*",
       "/var/log/*", "/var/mail/*", "/var/spool/*"
     )
   )
  ]

// Title: persistence_pluggable_authentication_module_source_download.toml
// Source: detection-rules::rules/linux/persistence_pluggable_authentication_module_source_download.toml
// Section: EQL Rule
// Rule Name: Pluggable Authentication Module (PAM) Source Download
// Author: Elastic
// Description:
// This rule detects the usage of "curl" or "wget" to download the source code of a Pluggable Authentication Module (PAM)
// shared object file. Attackers may download the source code of a PAM shared object file to create a backdoor in the
// authentication process.
// Integration: endpoint, crowdstrike
// Language: eql
// UUID: 53ef31ea-1f8a-493b-9614-df23d8277232
// Type: eql

process where host.os.type == "linux" and event.type == "start" and event.action in ("exec", "exec_event", "ProcessRollup2") and
process.name in ("curl", "wget") and
