// Title: persistence_polkit_policy_creation.toml
// Source: detection-rules::rules/linux/persistence_polkit_policy_creation.toml
// Section: EQL Rule
// Rule Name: Polkit Policy Creation
// Author: Elastic
// Description:
// This rule monitors for the creation of Polkit policy files on Linux systems. Polkit policy files are used to define the
// permissions for system-wide services and applications. The creation of new Polkit policy files may indicate an attempt
// to modify the authentication process, which could be used for persistence by an adversary.
// Integration: endpoint, sentinel_one_cloud_funnel
// Language: eql
// UUID: 0f54e947-9ab3-4dff-9e8d-fb42493eaa2f
// Type: eql

file where host.os.type == "linux" and event.type == "creation" and process.executable != null and
file.extension in ("rules", "pkla", "policy") and file.path like~ (

  // Rule files
  "/etc/polkit-1/rules.d/*", "/usr/share/polkit-1/rules.d/*",

  // pkla files
  "/etc/polkit-1/localauthority/*", "/var/lib/polkit-1/localauthority/*",

  // Action files
  "/usr/share/polkit-1/actions/*",

  // Misc. legacy paths
  "/lib/polkit-1/rules.d/*", "/lib64/polkit-1/rules.d/*", "/var/lib/polkit-1/rules.d/*"
) and not (
  process.executable in (
    "/bin/dpkg", "/usr/bin/dpkg", "/bin/dockerd", "/usr/bin/dockerd", "/usr/sbin/dockerd", "/bin/microdnf",
    "/usr/bin/microdnf", "/bin/rpm", "/usr/bin/rpm", "/bin/snapd", "/usr/bin/snapd", "/bin/yum", "/usr/bin/yum",
    "/bin/dnf", "/usr/bin/dnf", "/bin/podman", "/usr/bin/podman", "/bin/dnf-automatic", "/usr/bin/dnf-automatic",
    "/bin/pacman", "/usr/bin/pacman", "/usr/bin/dpkg-divert", "/bin/dpkg-divert", "/sbin/apk", "/usr/sbin/apk",
    "/usr/local/sbin/apk", "/usr/bin/apt", "/usr/sbin/pacman", "/bin/podman", "/usr/bin/podman", "/usr/bin/puppet",
    "/bin/puppet", "/opt/puppetlabs/puppet/bin/puppet", "/usr/bin/chef-client", "/bin/chef-client",
    "/bin/autossl_check", "/usr/bin/autossl_check", "/proc/self/exe", "/usr/bin/pamac-daemon",
    "/bin/pamac-daemon", "/usr/lib/snapd/snapd", "/usr/local/bin/dockerd", "/usr/bin/crio", "/usr/sbin/crond",
    "/opt/puppetlabs/puppet/bin/ruby", "/usr/libexec/platform-python", "/kaniko/kaniko-executor",
    "/usr/local/bin/dockerd", "/usr/bin/podman", "/bin/install", "/proc/self/exe", "/usr/lib/systemd/systemd",
    "/usr/sbin/sshd", "/usr/bin/gitlab-runner", "/opt/gitlab/embedded/bin/ruby", "/usr/sbin/gdm", "/usr/bin/install",
    "/usr/local/manageengine/uems_agent/bin/dcregister", "/usr/local/bin/pacman", "./usr/bin/podman",
    "/kaniko/executor", "/opt/kaniko/executor", "/usr/bin/buildah", "/usr/lib/cargo/bin/coreutils/install"
  ) or
  process.executable like (
    "/nix/store/*", "/var/lib/dpkg/*", "/tmp/vmis.*", "/snap/*", "/dev/fd/*", "/usr/lib/virtualbox/*",
    "/var/lib/containers/storage/overlay/*/dockerd", "/var/lib/docker/overlay2/*/dockerd"
  ) or
  (process.name like "python*" and file.name like ".ansible_tmp*.rules")
)

// Title: persistence_potential_persistence_script_executable_bit_set.toml
// Source: detection-rules::rules/linux/persistence_potential_persistence_script_executable_bit_set.toml
// Section: EQL Rule
// Rule Name: Executable Bit Set for Potential Persistence Script
// Author: Elastic
// Description:
// This rule monitors for the addition of an executable bit for scripts that are located in directories which are commonly
// abused for persistence. An alert of this rule is an indicator that a persistence mechanism is being set up within your
// environment. Adversaries may create these scripts to execute malicious code at start-up, or at a set interval to gain
// persistence onto the system.
// Integration: endpoint, sentinel_one_cloud_funnel
// Language: eql
// UUID: 94418745-529f-4259-8d25-a713a6feb6ae
// Type: eql

process where host.os.type == "linux" and event.type == "start" and event.action in ("exec", "exec_event", "start") and
process.args : (
  // Misc.
  "/etc/rc.local", "/etc/rc.common", "/etc/rc.d/rc.local", "/etc/init.d/*", "/etc/update-motd.d/*",
  "/etc/apt/apt.conf.d/*", "/etc/cron*", "/etc/init/*", "/etc/NetworkManager/dispatcher.d/*",
  "/lib/dracut/modules.d/*", "/usr/lib/dracut/modules.d/*",

  // XDG
  "/etc/xdg/autostart/*", "/home/*/.config/autostart/*", "/root/.config/autostart/*",
  "/home/*/.local/share/autostart/*", "/root/.local/share/autostart/*", "/home/*/.config/autostart-scripts/*",
  "/root/.config/autostart-scripts/*", "/etc/xdg/autostart/*", "/usr/share/autostart/*",

  // udev
  "/lib/udev/*", "/etc/udev/rules.d/*", "/usr/lib/udev/rules.d/*", "/run/udev/rules.d/*"

) and (
  (process.name == "chmod" and process.args : ("+x*", "1*", "3*", "5*", "7*")) or
  (process.name == "install" and process.args : "-m*" and process.args : ("7*", "5*", "3*", "1*"))
) and not (
  process.parent.executable : "/var/lib/dpkg/*" or
  process.command_line in ("chmod 777 /etc/update-motd.d/", "chmod 755 /etc/update-motd.d/")
)

// Title: persistence_process_capability_set_via_setcap.toml
// Source: detection-rules::rules/linux/persistence_process_capability_set_via_setcap.toml
// Section: EQL Rule
// Rule Name: Process Capability Set via setcap Utility
// Author: Elastic
// Description:
// This rule detects the use of the setcap utility to set capabilities on a process. The setcap utility is used to set the
// capabilities of a binary to allow it to perform privileged operations without needing to run as root. This can be used
// by attackers to establish persistence by creating a backdoor, or escalate privileges by abusing a misconfiguration on a
// system.
// Integration: endpoint, sentinel_one_cloud_funnel
// Language: eql
// UUID: f18a474c-3632-427f-bcf5-363c994309ee
// Type: eql

process where host.os.type == "linux" and event.type == "start" and event.action in ("exec", "exec_event", "start") and
process.name == "setcap" and not (
  process.parent.executable == null or
  process.parent.executable like (
    "/var/lib/dpkg/*", "/var/lib/docker/*", "/tmp/newroot/*", "/var/tmp/newroot/*", "/usr/bin/cmake",
    "/opt/zscaler/bin/zpa-connector"
  ) or
  process.parent.name in ("jem", "vzctl") or
  process.parent.args like "/var/lib/dpkg/info/*" or
  ?process.working_directory in ("/opt/dynatrace/oneagent", "/opt/sophos-spl/plugins/av/sbin") or
  process.parent.command_line in ("/bin/bash /entrypoint.sh telegraf", "/bin/sh /usr/local/bin/docker-entrypoint.sh server")
)

// Title: persistence_pth_file_creation.toml
// Source: detection-rules::rules/linux/persistence_pth_file_creation.toml
// Section: EQL Rule
// Rule Name: Python Path File (pth) Creation
// Author: Elastic
// Description:
// This rule detects the creation of .pth files in system-wide and user-specific Python package
// directories, which can be abused for persistent code execution. .pth files automatically
// execute Python code when the interpreter starts, making them a stealthy persistence mechanism.
// Monitoring these paths helps identify unauthorized modifications that could indicate
// persistence by an attacker or malicious package injection.
// Integration: endpoint
// Language: eql
// UUID: 7f65f984-5642-4291-a0a0-2bbefce4c617
// Type: eql

file where host.os.type == "linux" and event.action == "creation" and file.extension == "pth" and
file.path like (
  "/usr/local/lib/python*/dist-packages/*", 
  "/usr/lib/python*/dist-packages/*",
  "/usr/local/lib/python*/site-packages/*",
  "/usr/lib/python*/site-packages/*",
  "/home/*/.local/lib/python*/site-packages/*",
  "/opt/*/lib/python*/site-packages/*"
) and process.executable != null and not (
  process.executable in (
    "/usr/bin/restic", "/usr/bin/pacman", "/usr/bin/dockerd",  "/usr/bin/podman", "/usr/bin/pamac-daemon",
    "/usr/bin/dnf", "/usr/bin/dnf5", "/bin/dnf5", "/bin/podman", "./usr/bin/podman", "/kaniko/executor",
    "/dev/fd/3", "/opt/SolarWinds/Agent/bin/Plugins/Discovery/SolarWinds.Agent.Discovery.Plugin", "/usr/bin/crio",
    "/opt/splunk/bin/splunkd", "/opt/Tanium/TaniumClient/TaniumCX"
  ) or
  process.executable like (
    "/nix/store/*libexec/docker/dockerd", "/snap/docker/*dockerd"
  ) or
  (
    process.name like ("platform-python*", "cp", "uv") and
    file.name in ("distutils-precedence.pth", "_virtualenv.pth")
  )
)

// Title: persistence_rc_local_service_already_running.toml
// Source: detection-rules::rules/linux/persistence_rc_local_service_already_running.toml
// Section: EQL Rule
// Rule Name: Potential Execution of rc.local Script
// Author: Elastic
// Description:
// This rule detects the potential execution of the "/etc/rc.local" script through the "already_running" event action
// created by the "rc-local.service" systemd service. The "/etc/rc.local" script is a legacy initialization script that is
// executed at the end of the boot process. The "/etc/rc.local" script is not enabled by default on most Linux
// distributions. The "/etc/rc.local" script can be used by attackers to persistently execute malicious commands or scripts
// on a compromised system at reboot. As the rc.local file is executed prior to the initialization of Elastic Defend, the
// execution event is not ingested, and therefore the "already_running" event is leveraged to provide insight into the
// potential execution of "rc.local".
// Integration: endpoint
// Language: eql
// UUID: 7318affb-bfe8-4d50-a425-f617833be160
// Type: eql

process where host.os.type == "linux" and event.type == "info" and event.action == "already_running" and
process.parent.args == "/etc/rc.local" and process.parent.args == "start"

// Title: persistence_rc_script_creation.toml
// Source: detection-rules::rules/linux/persistence_rc_script_creation.toml
// Section: EQL Rule
// Rule Name: rc.local/rc.common File Creation
// Author: Elastic
// Description:
// This rule monitors the creation of the rc.local/rc.common files. The "/etc/rc.local" file is used to start
// custom applications, services, scripts or commands during start-up. The rc.local file has mostly been replaced by
// Systemd. However, through the "systemd-rc-local-generator", rc.local files can be converted to services that run at
// boot. Adversaries may alter rc.local/rc.common to execute malicious code at start-up, and gain persistence onto the
// system.
// Integration: endpoint
// Language: eql
// UUID: 0f4d35e4-925e-4959-ab24-911be207ee6f
// Type: eql

file where host.os.type == "linux" and event.action == "creation" and
file.path in ("/etc/rc.local", "/etc/rc.common") and not (
  process.executable in (
    "/bin/dpkg", "/usr/bin/dpkg", "/bin/dockerd", "/usr/bin/dockerd", "/usr/sbin/dockerd", "/bin/microdnf",
    "/usr/bin/microdnf", "/bin/rpm", "/usr/bin/rpm", "/bin/snapd", "/usr/bin/snapd", "/bin/yum", "/usr/bin/yum",
    "/bin/dnf", "/usr/bin/dnf", "/bin/podman", "/usr/bin/podman", "/bin/dnf-automatic", "/usr/bin/dnf-automatic",
    "/bin/pacman", "/usr/bin/pacman", "/usr/bin/dpkg-divert", "/bin/dpkg-divert", "/sbin/apk", "/usr/sbin/apk",
    "/usr/local/sbin/apk", "/usr/bin/apt", "/usr/sbin/pacman", "/bin/podman", "/usr/bin/podman", "/usr/bin/puppet",
    "/bin/puppet", "/opt/puppetlabs/puppet/bin/puppet", "/usr/bin/chef-client", "/bin/chef-client",
    "/bin/autossl_check", "/usr/bin/autossl_check", "/proc/self/exe", "/dev/fd/*",  "/usr/bin/pamac-daemon",
    "/bin/pamac-daemon", "/usr/lib/snapd/snapd", "/usr/local/bin/dockerd", "/usr/libexec/platform-python"
  ) or
  file.extension in ("swp", "swpx", "swx", "dpkg-remove") or
  file.Ext.original.extension == "dpkg-new" or
  process.executable : (
    "/nix/store/*", "/var/lib/dpkg/*", "/snap/*", "/dev/fd/*", "/usr/lib/virtualbox/*"
  ) or
  process.executable == null or
  process.name in ("ssm-agent-worker", "convert2rhel", "platform-python*") or
  (process.name == "sed" and file.name : "sed*") or
  (process.name == "perl" and file.name : "e2scrub_all.tmp*") 
)

// Title: persistence_setuid_setgid_capability_set.toml
// Source: detection-rules::rules/linux/persistence_setuid_setgid_capability_set.toml
// Section: EQL Rule
// Rule Name: Setcap setuid/setgid Capability Set
// Author: Elastic
// Description:
// This rule monitors for the addition of the cap_setuid+ep or cap_setgid+ep capabilities via setcap. Setuid (Set User ID)
// and setgid (Set Group ID) are Unix-like OS features that enable processes to run with elevated privileges, based on the
// file owner or group. Threat actors can exploit these attributes to achieve persistence by creating malicious binaries,
// allowing them to maintain control over a compromised system with elevated permissions.
// Integration: endpoint, crowdstrike, sentinel_one_cloud_funnel
// Language: eql
// UUID: f5c005d3-4e17-48b0-9cd7-444d48857f97
// Type: eql

process where host.os.type == "linux" and event.type == "start" and
event.action in ("exec", "exec_event", "start", "ProcessRollup2") and 
process.name == "setcap" and process.args : "cap_set?id+ep" and not (
  process.parent.name in ("jem", "vzctl") or
  process.args like "/usr/bin/new?idmap"
)

// Title: persistence_shadow_file_modification.toml
// Source: detection-rules::rules/linux/persistence_shadow_file_modification.toml
// Section: EQL Rule
// Rule Name: Shadow File Modification by Unusual Process
// Author: Elastic
// Description:
// This rule monitors for Linux Shadow file modifications. These modifications are indicative of a potential password
// change or user addition event. Threat actors may attempt to create new users or change the password of a user account to
// maintain access to a system.
// Integration: endpoint
// Language: eql
// UUID: cdf1a39b-1ca5-4e2a-9739-17fc4d026029
// Type: eql

file where host.os.type == "linux" and event.type == "change" and event.action == "rename" and
file.path == "/etc/shadow" and file.Ext.original.path != null and 
not (
  file.Ext.original.name in ("shadow+", "nshadow") or
  process.name in (
    "usermod", "useradd", "passwd", "chage", "systemd-sysusers", "chpasswd", "userdel", "adduser", "update-passwd", "perl"
  ) or
  process.executable like "/usr/libexec/platform-python*" or
  process.executable in (
    "/usr/bin/containerd", "/usr/bin/dnf", "/usr/bin/yum", "/bin/dnf", "./usr/bin/qemu-aarch64-static",
    "/usr/local/cpanel/whostmgr/bin/xml-api", "/usr/local/cpanel/whostmgr/bin/whostmgr5",
    "/usr/local/cpanel/bin/admin/Cpanel/security"
  )
)

// Title: persistence_shell_configuration_modification.toml
// Source: detection-rules::rules/linux/persistence_shell_configuration_modification.toml
// Section: EQL Rule
// Rule Name: Shell Configuration Creation
// Author: Elastic
// Description:
// This rule monitors the creation of a shell configuration file. Unix systems use shell configuration files to
// set environment variables, create aliases, and customize the user's environment. Adversaries may modify or add a shell
// configuration file to execute malicious code and gain persistence in the system.
// Integration: endpoint
// Language: eql
// UUID: 28f6f34b-8e16-487a-b5fd-9d22eb903db8
// Type: eql

file where host.os.type == "linux" and event.action == "creation" and file.path : (
  // system-wide configurations
  "/etc/profile", "/etc/profile.d/*", "/etc/bash.bashrc", "/etc/bash.bash_logout", "/etc/zsh/*",
  "/etc/csh.cshrc", "/etc/csh.login", "/etc/fish/config.fish", "/etc/ksh.kshrc",
  // root and user configurations
  "/home/*/.profile", "/home/*/.bashrc", "/home/*/.bash_login", "/home/*/.bash_logout", "/home/*/.bash_profile",
  "/root/.profile", "/root/.bashrc", "/root/.bash_login", "/root/.bash_logout", "/root/.bash_profile",
  "/root/.bash_aliases", "/home/*/.bash_aliases", "/home/*/.zprofile", "/home/*/.zshrc", "/root/.zprofile",
  "/root/.zshrc", "/home/*/.cshrc", "/home/*/.login", "/home/*/.logout", "/root/.cshrc", "/root/.login",
  "/root/.logout", "/home/*/.config/fish/config.fish", "/root/.config/fish/config.fish", "/home/*/.kshrc",
  "/root/.kshrc"
) and not (
  process.executable in (
    "/bin/dpkg", "/usr/bin/dpkg", "/bin/dockerd", "/usr/bin/dockerd", "/usr/sbin/dockerd", "/bin/microdnf",
    "/usr/bin/microdnf", "/bin/rpm", "/usr/bin/rpm", "/bin/snapd", "/usr/bin/snapd", "/bin/yum", "/usr/bin/yum",
    "/bin/dnf", "/usr/bin/dnf", "/bin/podman", "/usr/bin/podman", "/bin/dnf-automatic", "/usr/bin/dnf-automatic",
    "/bin/pacman", "/usr/bin/pacman", "/usr/bin/dpkg-divert", "/bin/dpkg-divert", "/sbin/apk", "/usr/sbin/apk",
    "/usr/local/sbin/apk", "/usr/bin/apt", "/usr/sbin/pacman", "/bin/podman", "/usr/bin/podman", "/usr/bin/puppet",
    "/bin/puppet", "/opt/puppetlabs/puppet/bin/puppet", "/usr/bin/chef-client", "/bin/chef-client",
    "/bin/autossl_check", "/usr/bin/autossl_check", "/proc/self/exe",  "/usr/bin/pamac-daemon",
    "/bin/pamac-daemon", "/usr/lib/snapd/snapd", "/usr/sbin/adduser", "/usr/sbin/useradd", "/usr/local/bin/dockerd",
    "/usr/sbin/gdm", "/usr/bin/unzip", "/usr/bin/gnome-shell", "/sbin/mkhomedir_helper", "/usr/sbin/sshd",
    "/opt/puppetlabs/puppet/bin/ruby", "/usr/bin/xfce4-session", "/usr/libexec/oddjob/mkhomedir", "/sbin/useradd",
    "/usr/lib/systemd/systemd", "/usr/sbin/crond", "/usr/bin/pamac-daemon", "/usr/sbin/mkhomedir_helper",
    "/opt/pbis/sbin/lwsmd", "/usr/sbin/oddjobd", "./usr/bin/podman", "/usr/bin/dnf5", "/bin/dnf5",
    "/usr/libexec/gnome-terminal-server", "/usr/bin/buildah", "/usr/lib/venv-salt-minion/bin/python.original"
  ) or
  file.extension in ("swp", "swpx", "swx", "dpkg-remove") or
  file.Ext.original.extension == "dpkg-new" or
  process.executable like (
    "/nix/store/*", "/var/lib/dpkg/*", "/tmp/vmis.*", "/snap/*", "/dev/fd/*", "/usr/lib/virtualbox/*",
    "/usr/libexec/platform-python*", "./snap/snapd/*/usr/lib/snapd/snap-update-ns", "/opt/alt/python*/bin/python*"
  ) or
  process.executable == null or
  process.name in ("adclient", "mkhomedir_helper", "teleport", "mkhomedir", "adduser", "desktopDaemon", "executor", "crio") or
  (process.name == "sed" and file.name like "sed*") or
  (process.name == "perl" and file.name like "e2scrub_all.tmp*")
)

// Title: persistence_simple_web_server_connection_accepted.toml
// Source: detection-rules::rules/linux/persistence_simple_web_server_connection_accepted.toml
// Section: EQL Rule
// Rule Name: Simple HTTP Web Server Connection
// Author: Elastic
// Description:
// This rule detects connections accepted by a simple HTTP web server in Python and PHP built-in modules. Adversaries may
// create simple HTTP web servers to establish persistence on a compromised system by uploading a reverse or command shell
// payload to the server web root, allowing them to regain remote access to the system if lost. This event may occur when
// an attacker requests the server to execute a command or script via a potential backdoor.
// Integration: endpoint
// Language: eql
// UUID: 183f3cd2-4cc6-44c0-917c-c5d29ecdcf74
// Type: eql

sequence by process.entity_id with maxspan=1m
[process where host.os.type == "linux" and event.type == "start" and 
 (
  (process.name regex~ """php?[0-9]?\.?[0-9]{0,2}""" and process.command_line like "*-S*") or
  (process.name like "python*" and process.command_line like ("*--cgi*", "*CGIHTTPServer*"))
 ) and not process.parent.command_line == "runc init"
]
[network where host.os.type == "linux" and event.type == "start" and event.action == "connection_accepted"]

// Title: persistence_simple_web_server_creation.toml
// Source: detection-rules::rules/linux/persistence_simple_web_server_creation.toml
// Section: EQL Rule
// Rule Name: Simple HTTP Web Server Creation
// Author: Elastic
// Description:
// This rule detects the creation of a simple HTTP web server using PHP or Python built-in modules. Adversaries may create
// simple HTTP web servers to establish persistence on a compromised system by uploading a reverse or command shell payload
// to the server web root, allowing them to regain remote access to the system if lost.
// Integration: endpoint, crowdstrike, sentinel_one_cloud_funnel
// Language: eql
// UUID: 907a26f5-3eb6-4338-a70e-6c375c1cde8a
// Type: eql

process where host.os.type == "linux" and event.type == "start" and
event.action in ("exec", "exec_event", "start", "ProcessRollup2") and
(
  (process.name regex~ """php?[0-9]?\.?[0-9]{0,2}""" and process.args == "-S") or
  (process.name like "python*" and process.args in ("--cgi", "CGIHTTPServer"))
) and
not process.parent.name in ("check_kmp_wrapper", "naemon", "runc")

// Title: persistence_site_and_user_customize_file_creation.toml
// Source: detection-rules::rules/linux/persistence_site_and_user_customize_file_creation.toml
// Section: EQL Rule
// Rule Name: Python Site or User Customize File Creation
// Author: Elastic
// Description:
// This rule detects the creation and modification of sitecustomize.py and usercustomize.py, which
// Python automatically executes on startup. Attackers can exploit these files for persistence by
// injecting malicious code. The rule monitors system-wide, user-specific, and virtual environment
// locations to catch unauthorized changes that could indicate persistence or backdooring attempts.
// Integration: endpoint
// Language: eql
// UUID: d788313c-9e0b-4c5a-8c4b-c3f05a47d5a8
// Type: eql

file where host.os.type == "linux" and event.type == "creation" and process.executable != null and
file.path like (
  "/usr/lib/python*/sitecustomize.py",
  "/usr/local/lib/python*/sitecustomize.py",
  "/usr/lib/python*/dist-packages/sitecustomize.py",
  "/usr/local/lib/python*/dist-packages/sitecustomize.py",
  "/opt/*/lib/python*/sitecustomize.py",
  "/home/*/.local/lib/python*/site-packages/usercustomize.py",
  "/home/*/.config/python/usercustomize.py"
) and not (
  process.executable in (
    "/usr/bin/restic", "/usr/bin/pacman", "/usr/bin/dockerd", "/usr/bin/podman", "/usr/bin/pamac-daemon",
    "./usr/bin/podman", "/opt/miniforge3/bin/mamba", "/usr/sbin/dockerd", "/opt/conda/_conda", "/kaniko/executor",
    "/usr/bin/crio", "/usr/lib/systemd/systemd-executor"
  ) or
  process.executable like~ ("/nix/store/*libexec/docker/dockerd", "/snap/docker/*dockerd")
)

// Title: persistence_ssh_key_generation.toml
// Source: detection-rules::rules/linux/persistence_ssh_key_generation.toml
// Section: EQL Rule
// Rule Name: SSH Key Generated via ssh-keygen
// Author: Elastic
// Description:
// This rule identifies the creation of SSH keys using the ssh-keygen tool, which is the standard utility for generating
// SSH keys. Users often create SSH keys for authentication with remote services. However, threat actors can exploit this
// tool to move laterally across a network or maintain persistence by generating unauthorized SSH keys, granting them SSH
// access to systems.
// Integration: endpoint, sentinel_one_cloud_funnel
// Language: eql
// UUID: 7df3cb8b-5c0c-4228-b772-bb6cd619053c
// Type: eql

file where host.os.type == "linux" and event.action in ("creation", "file_create_event") and
process.executable == "/usr/bin/ssh-keygen" and file.path : ("/home/*/.ssh/*", "/root/.ssh/*", "/etc/ssh/*") and
not file.name : "known_hosts.*"

// Title: persistence_ssh_netcon.toml
// Source: detection-rules::rules/linux/persistence_ssh_netcon.toml
// Section: EQL Rule
// Rule Name: Network Connection Initiated by Suspicious SSHD Child Process
// Author: Elastic
// Description:
// This rule identifies an egress internet connection initiated by an SSH Daemon child process. This behavior is
// indicative of the alteration of a shell configuration file or other mechanism that launches a process when a
// new SSH login occurs. Attackers can also backdoor the SSH daemon to allow for persistence, call out to a C2
// or to steal credentials.
// Integration: endpoint
// Language: eql
// UUID: 63431796-f813-43af-820b-492ee2efec8e
// Type: eql

sequence by host.id with maxspan=1s
  [process where host.os.type == "linux" and event.type == "start" and event.action == "exec" and
   process.parent.executable == "/usr/sbin/sshd" and not process.command_line like ("*ansible*", "*BECOME-SUCCESS*")] by process.entity_id
  [network where host.os.type == "linux" and event.type == "start" and event.action == "connection_attempted" and (
     process.executable like (
       "/tmp/*", "/var/tmp/*", "/dev/shm/*", "./*", "/run/*", "/var/run/*", "/boot/*", "/sys/*", "/lost+found/*",
       "/proc/*", "/var/mail/*", "/var/www/*", "/home/*", "/root/*" 
     ) or
     process.name like~ (
       // Hidden processes
       ".*",
       // Suspicious file formats
       "*.elf", "*.sh", "*.py", "*.rb", "*.pl", "*.lua*", "*.php*", ".js",
       // Scheduled tasks
       "systemd", "cron", "crond",
       // Network utilities often used for reverse shells
       "nc", "netcat", "ncat", "telnet", "socat", "openssl", "nc.openbsd", "ngrok", "nc.traditional"
     )
   ) and  
   not (
     destination.ip == null or destination.ip == "0.0.0.0" or cidrmatch(
       destination.ip, "10.0.0.0/8", "127.0.0.0/8", "169.254.0.0/16", "172.16.0.0/12", "192.0.0.0/24", "192.0.0.0/29",
       "192.0.0.8/32", "192.0.0.9/32", "192.0.0.10/32", "192.0.0.170/32", "192.0.0.171/32", "192.0.2.0/24",
       "192.31.196.0/24", "192.52.193.0/24", "192.168.0.0/16", "192.88.99.0/24", "224.0.0.0/4", "100.64.0.0/10",
       "192.175.48.0/24","198.18.0.0/15", "198.51.100.0/24", "203.0.113.0/24", "240.0.0.0/4", "::1", "FE80::/10",
       "FF00::/8", "172.31.0.0/16"
     ) or
     process.executable in ("/bin/yum", "/usr/bin/yum") or
     process.name in ("login_duo", "ssh", "sshd", "sshd-session", "sqlplus")
   )
  ] by process.parent.entity_id

// Title: persistence_suspicious_file_opened_through_editor.toml
// Source: detection-rules::rules/linux/persistence_suspicious_file_opened_through_editor.toml
// Section: EQL Rule
// Rule Name: Potential Suspicious File Edit
// Author: Elastic
// Description:
// This rule monitors for the potential edit of a suspicious file. In Linux, when editing a file through an editor, a
// temporary .swp file is created. By monitoring for the creation of this .swp file, we can detect potential file edits of
// suspicious files. The execution of this rule is not a clear sign of the file being edited, as just opening the file
// through an editor will trigger this event. Attackers may alter any of the files added in this rule to establish
// persistence, escalate privileges or perform reconnaisance on the system.
// Integration: endpoint, sentinel_one_cloud_funnel
// Language: eql
// UUID: 3728c08d-9b70-456b-b6b8-007c7d246128
// Type: eql

file where host.os.type == "linux" and event.action in ("creation", "file_create_event") and file.extension == "swp" and
file.path : (
  /* common interesting files and locations */
  "/etc/.shadow.swp", "/etc/.shadow-.swp", "/etc/.shadow~.swp", "/etc/.gshadow.swp", "/etc/.gshadow-.swp",
  "/etc/.passwd.swp", "/etc/.pwd.db.swp", "/etc/.master.passwd.swp", "/etc/.spwd.db.swp", "/etc/security/.opasswd.swp",
  "/etc/.environment.swp", "/etc/.profile.swp", "/etc/sudoers.d/.*.swp", "/etc/ld.so.conf.d/.*.swp",
  "/etc/init.d/.*.swp", "/etc/.rc.local.swp", "/etc/rc*.d/.*.swp", "/dev/shm/.*.swp", "/etc/update-motd.d/.*.swp",
  "/usr/lib/update-notifier/.*.swp",

  /* service, timer, want, socket and lock files */
  "/etc/systemd/system/.*.swp", "/usr/local/lib/systemd/system/.*.swp", "/lib/systemd/system/.*.swp",
  "/usr/lib/systemd/system/.*.swp","/home/*/.config/systemd/user/.*.swp", "/run/.*.swp", "/var/run/.*.swp/",

  /* profile and shell configuration files */
  "/home/*.profile.swp", "/home/*.bash_profile.swp", "/home/*.bash_login.swp", "/home/*.bashrc.swp", "/home/*.bash_logout.swp",
  "/home/*.zshrc.swp", "/home/*.zlogin.swp", "/home/*.tcshrc.swp", "/home/*.kshrc.swp", "/home/*.config.fish.swp",
  "/root/*.profile.swp", "/root/*.bash_profile.swp", "/root/*.bash_login.swp", "/root/*.bashrc.swp", "/root/*.bash_logout.swp",
  "/root/*.zshrc.swp", "/root/*.zlogin.swp", "/root/*.tcshrc.swp", "/root/*.kshrc.swp", "/root/*.config.fish.swp"
)

// Title: persistence_suspicious_ssh_execution_xzbackdoor.toml
// Source: detection-rules::rules/linux/persistence_suspicious_ssh_execution_xzbackdoor.toml
// Section: EQL Rule
// Rule Name: Potential Execution via SSH Backdoor
// Author: Elastic
// Description:
// It identifies potential malicious shell executions through remote SSH and detects cases where the sshd service suddenly
// terminates soon after successful execution, suggesting suspicious behavior similar to the XZ backdoor.
// Integration: endpoint
// Language: eql
// UUID: 7afc6cc9-8800-4c7f-be6b-b688d2dea248
// Type: eql

sequence by host.id with maxspan=1m
  [process where host.os.type == "linux" and event.action == "end" and process.name == "sshd" and process.exit_code != 0 and
   process.command_line == "/usr/sbin/sshd -D -R" and process.parent.command_line == "sshd: /usr/sbin/sshd -D [listener] 0 of 10-100 startups"] by process.entity_id
  [process where host.os.type == "linux" and event.type == "start" and event.action == "exec" and
   process.parent.name == "sshd" and process.parent.command_line == "/usr/sbin/sshd -D -R" and
   process.name in ("bash", "dash", "sh", "tcsh", "csh", "zsh", "ksh", "fish") and process.args == "-c" and not (
     process.args like (
       "rsync*", "systemctl*", "/usr/sbin/unix_chkpwd", "/usr/bin/google_authorized_keys", "/usr/sbin/aad_certhandler*",
        "bash -c bash -s", "/usr/lib/ssh/sftp-server", "stat /etc/is_upgrade_install > /dev/null 2>&1",
        "stat /opt/qradar/ha/.*", "/usr/bin/env -i PATH=*", "/opt/gitlab/*", "clamdscan*", "wc*", "export*",
        "test*", "md5sum*", "check_mk_agent", "/usr/bin/env*", "/usr/bin/check_mk_agent", "timeout*", "/usr/sbin/haproxy*",
        "/usr/libexec/openssh/sftp-server", "command*", "find*", "cd *", "scp*", "while*", "pvesh*", "/bin/true",
        "/usr/sbin/qm mtunnel", "multipath*", "/usr/lib/openssh/sftp-server"
     ) or
     process.command_line like ("sh -c /usr/bin/env -i PATH=*", "sh -c -- /usr/bin/env -i PATH=*", "*ansible*", "*BECOME-SUCCESS*")
   )
  ] by process.parent.entity_id

// Title: persistence_systemd_generator_creation.toml
// Source: detection-rules::rules/linux/persistence_systemd_generator_creation.toml
// Section: EQL Rule
// Rule Name: Systemd Generator Created
// Author: Elastic
// Description:
// This rule detects the creation of a systemd generator file. Generators are small executables executed by systemd at
// bootup and during configuration reloads. Their main role is to convert non-native configuration and execution parameters
// into dynamically generated unit files, symlinks, or drop-ins, extending the unit file hierarchy for the service manager.
// Systemd generators can be used to execute arbitrary code at boot time, which can be leveraged by attackers to maintain
// persistence on a Linux system.
// Integration: endpoint
// Language: eql
// UUID: 39c06367-b700-4380-848a-cab06e7afede
// Type: eql

file where host.os.type == "linux" and event.action in ("rename", "creation") and file.path : (
"/run/systemd/system-generators/*", "/etc/systemd/system-generators/*",
"/usr/local/lib/systemd/system-generators/*", "/lib/systemd/system-generators/*",
"/usr/lib/systemd/system-generators/*", "/etc/systemd/user-generators/*",
"/usr/local/lib/systemd/user-generators/*", "/usr/lib/systemd/user-generators/*",
"/lib/systemd/user-generators/*"
) and not (
  process.executable in (
    "/bin/dpkg", "/usr/bin/dpkg", "/bin/dockerd", "/usr/bin/dockerd", "/usr/sbin/dockerd", "/bin/microdnf",
    "/usr/bin/microdnf", "/bin/rpm", "/usr/bin/rpm", "/bin/snapd", "/usr/bin/snapd", "/bin/yum", "/usr/bin/yum",
    "/bin/dnf", "/usr/bin/dnf", "/bin/podman", "/usr/bin/podman", "/bin/dnf-automatic", "/usr/bin/dnf-automatic",
