// Title: persistence_systemd_netcon.toml
// Source: detection-rules::rules/linux/persistence_systemd_netcon.toml
// Section: EQL Rule
// Rule Name: Suspicious Network Connection via systemd
// Author: Elastic
// Description:
// Detects suspicious network events executed by systemd, potentially indicating persistence through a systemd backdoor.
// Systemd is a system and service manager for Linux operating systems, used to initialize and manage system processes.
// Attackers can backdoor systemd for persistence by creating or modifying systemd unit files to execute malicious scripts
// or commands, or by replacing legitimate systemd binaries with compromised ones, ensuring that their malicious code is
// automatically executed at system startup or during certain system events.
// Integration: endpoint
// Language: eql
// UUID: f3818c85-2207-4b51-8a28-d70fb156ee87
// Type: eql

sequence by host.id with maxspan=5s
  [process where host.os.type == "linux" and event.type == "start" and event.action == "exec" and
   process.parent.name == "systemd" and (
     process.name in (
       "openssl", "nc", "ncat", "netcat", "nc.openbsd", "nc.traditional", "socat", "busybox", "mkfifo",
       "nohup", "setsid", "xterm", "telnet"
     ) or
    (process.name : "python*" and process.args : "-c" and process.args : (
     "*import*pty*spawn*", "*import*subprocess*call*"
    )) or
    (process.name : "perl*" and process.args : "-e" and process.args : "*socket*" and process.args : (
     "*exec*", "*system*"
    )) or
    (process.name : "ruby*" and process.args : ("-e", "-rsocket") and process.args : (
     "*TCPSocket.new*", "*TCPSocket.open*"
     )) or
    (process.name : "lua*" and process.args : "-e" and process.args : "*socket.tcp*" and process.args : (
     "*io.popen*", "*os.execute*"
    )) or
    (process.name : "php*" and process.args : "-r" and process.args : "*fsockopen*" and process.args : "*/bin/*sh*") or 
    (process.name == "node" and process.args == "-e" and process.args : "*spawn*sh*" and process.args : "*connect*") or
    (process.name : ("awk", "gawk", "mawk", "nawk") and process.args : "*/inet/tcp/*") or
    (process.name in ("rvim", "vim", "vimdiff", "rview", "view") and process.args == "-c" and process.args : "*socket*")
  ) and
   not (
     process.args in ("/usr/bin/pg_ctlcluster", "/usr/bin/pveproxy", "/usr/sbin/pveum", "/usr/bin/pveupdate") or
     process.executable like (
       "/usr/local/cpanel/*/bin/perl", "/opt/puppetlabs/puppet/bin/ruby", "/opt/unified-monitoring-agent/embedded/bin/ruby"
     ) or
     process.command_line in (
       "/usr/bin/perl /usr/sbin/pveum realm sync planet",
       "/usr/bin/perl -T /usr/bin/pveproxy start", "/usr/bin/perl /usr/bin/pveupdate"
     )
   )
  ] by process.entity_id
  [network where host.os.type == "linux" and event.action == "connection_attempted" and event.type == "start" and
   not process.executable == "/tmp/newroot/bin/curl"] by process.parent.entity_id

// Title: persistence_systemd_override_conf_creation.toml
// Source: detection-rules::rules/linux/persistence_systemd_override_conf_creation.toml
// Section: EQL Rule
// Rule Name: Systemd Service Override Configuration File Created
// Author: Elastic
// Description:
// This rule detects the creation or renaming of a new Systemd override configuration file in any
// of the Systemd service locations for both root and regular users. Systemd override configuration
// files are configuration files in Linux systems used to override the default Systemd service
// configuration for a specific service. Malicious actors can leverage systemd override configuration
// files to achieve persistence by creating or modifying services to execute malicious commands or
// payloads during system startup or at a predefined interval by adding a systemd timer. This allows
// them to maintain unauthorized access, execute additional malicious activities, or evade detection.
// Integration: endpoint
// Language: eql
// UUID: 9e8c185c-8237-4b13-a4da-4a8d4e9bb6ef
// Type: eql

file where host.os.type == "linux" and event.action in ("rename", "creation") and
file.extension == "conf" and file.path like (
  "/etc/systemd/system/*.d/*.conf", "/etc/systemd/user/*.d/*.conf", "/usr/local/lib/systemd/system/*.d/*.conf",
  "/lib/systemd/system/*.d/*.conf", "/usr/lib/systemd/system/*.d/*.conf", "/usr/lib/systemd/user/*.d/*.conf",
  "/home/*/.config/systemd/user/*.d/*.conf", "/home/*/.local/share/systemd/user/*.d/*.conf",
  "/root/.config/systemd/user/*.d/*.conf", "/root/.local/share/systemd/user/*.d/*.conf",
  "/run/systemd/system/*.d/*.conf", "/var/run/systemd/system/*.d/*.conf"
) and
not process.executable in (
  "/bin/dpkg", "/usr/bin/dpkg", "/bin/dockerd", "/usr/bin/dockerd", "/usr/sbin/dockerd", "/bin/microdnf",
  "/usr/bin/microdnf", "/bin/rpm", "/usr/bin/rpm", "/bin/snapd", "/usr/bin/snapd", "/bin/yum", "/usr/bin/yum",
  "/bin/dnf", "/usr/bin/dnf", "/bin/podman", "/usr/bin/podman", "/bin/dnf-automatic", "/usr/bin/dnf-automatic",
  "/usr/bin/dpkg-divert", "/bin/dpkg-divert", "/sbin/apk", "/usr/sbin/apk", "/usr/local/sbin/apk", "/usr/bin/dnf5",
  "/usr/bin/apt", "/usr/bin/puppet", "/bin/puppet", "/opt/puppetlabs/puppet/bin/puppet", "/usr/bin/pacman",
  "/usr/bin/chef-client", "/bin/chef-client", "/usr/bin/pamac-daemon", "/bin/pamac-daemon", "/usr/local/bin/dockerd",
  "/usr/bin/crio", "/usr/bin/podman", "/usr/bin/tdnf", "/usr/bin/apk"
)

// Title: persistence_systemd_scheduled_timer_created.toml
