// Title: persistence_systemd_shell_execution.toml
// Source: detection-rules::rules/linux/persistence_systemd_shell_execution.toml
// Section: EQL Rule
// Rule Name: Systemd Shell Execution During Boot
// Author: Elastic
// Description:
// This rule detects the execution of shell commands by systemd during the boot process on Linux systems. Systemd
// is a system and service manager for Linux operating systems. Attackers may execute shell commands during the
// boot process to maintain persistence on the system. This may be a sign of malicious systemd services, initramfs
// or GRUB bootloader manipulation, or other persistence mechanisms.
// Integration: endpoint
// Language: eql
// UUID: 0b76ad27-c3f3-4769-9e7e-3237137fdf06
// Type: eql

process where host.os.type == "linux" and event.type == "info" and event.action == "already_running" and
process.parent.name == "systemd" and process.name in ("bash", "sh", "tcsh", "csh", "zsh", "ksh", "fish") and
process.parent.command_line == "/sbin/init" and process.args_count >= 2

// Title: persistence_tainted_kernel_module_loaded.toml
// Source: detection-rules::rules/linux/persistence_tainted_kernel_module_loaded.toml
// Section: EQL Rule
// Rule Name: Kernel Module Loaded with Tainting Flags
// Author: Elastic
// Description:
// This rule detects the loading of tainted kernel modules on Linux systems. A tainted kernel module indicates that
// the module is not officially supported or may have been modified. Attackers may load tainted kernel modules to
// maintain persistence or evade detection on the system. This may be a sign of malicious activity involving kernel
// modules.
// Integration: endpoint
// Language: eql
// UUID: cc3dab79-3706-4775-9404-a722e2b00fed
// Type: eql

process where host.os.type == "linux" and event.type == "start" and event.action == "load_module" and
process.Ext.load_module.taint_flags != null

// Title: persistence_udev_rule_creation.toml
// Source: detection-rules::rules/linux/persistence_udev_rule_creation.toml
// Section: EQL Rule
// Rule Name: Systemd-udevd Rule File Creation
// Author: Elastic
// Description:
// Monitors for the creation of rule files that are used by systemd-udevd to manage device nodes and handle kernel device
// events in the Linux operating system. Systemd-udevd can be exploited for persistence by adversaries by creating
// malicious udev rules that trigger on specific events, executing arbitrary commands or payloads whenever a certain device
// is plugged in or recognized by the system.
// Integration: endpoint
// Language: eql
// UUID: 054db96b-fd34-43b3-9af2-587b3bd33964
// Type: eql

file where host.os.type == "linux" and event.action == "creation" and
process.executable != null and file.extension == "rules" and
file.path like (
  "/lib/udev/*", "/etc/udev/rules.d/*", "/usr/lib/udev/rules.d/*", "/run/udev/rules.d/*", "/usr/local/lib/udev/rules.d/*"
) and not (
  process.executable in (
    "/bin/dpkg", "/usr/bin/dpkg", "/bin/dockerd", "/usr/bin/dockerd", "/usr/sbin/dockerd", "/bin/microdnf",
    "/usr/bin/microdnf", "/bin/rpm", "/usr/bin/rpm", "/bin/snapd", "/usr/bin/snapd", "/bin/yum", "/usr/bin/yum",
    "/bin/dnf", "/usr/bin/dnf", "/bin/podman", "/usr/bin/podman", "/bin/dnf-automatic", "/usr/bin/dnf-automatic",
    "/bin/pacman", "/usr/bin/pacman", "/usr/bin/dpkg-divert", "/bin/dpkg-divert", "/sbin/apk", "/usr/sbin/apk",
    "/usr/local/sbin/apk", "/usr/bin/apt", "/usr/sbin/pacman", "/bin/podman", "/usr/bin/podman", "/usr/bin/puppet",
    "/bin/puppet", "/opt/puppetlabs/puppet/bin/puppet", "/usr/bin/chef-client", "/bin/chef-client",
    "/bin/autossl_check", "/usr/bin/autossl_check", "/proc/self/exe",  "/usr/bin/pamac-daemon", "./usr/bin/podman",
    "/bin/pamac-daemon", "/usr/lib/snapd/snapd", "/usr/local/bin/dockerd", "/usr/libexec/netplan/generate",
    "/lib/systemd/system-generators/netplan", "/lib/systemd/systemd", "/usr/bin/containerd", "/usr/sbin/sshd",
    "/kaniko/executor", "/usr/local/bin/defender", "/usr/bin/dnf5", "/opt/kaniko/executor", "/lib/netplan/generate"
  ) or
  file.Ext.original.extension == "dpkg-new" or
  process.executable like (
    "/nix/store/*", "/var/lib/dpkg/*", "/snap/*", "/dev/fd/*", "/usr/lib/*", "/usr/libexec/*",
     "/var/lib/docker/overlay2/*/dockerd", "/var/lib/containers/storage/overlay*/dockerd"
  ) or
  process.name in (
    "systemd", "netplan", "apt-get", "vmware-config-tools.pl", "systemd-hwdb", "ssm-agent-worker", "crio", "cloud-init", "convert2rhel" 
  ) or
  process.name like ("python*", "perl*") or
  (process.name == "sed" and file.name : "sed*")
)

// Title: persistence_unpack_initramfs_via_unmkinitramfs.toml
// Source: detection-rules::rules/linux/persistence_unpack_initramfs_via_unmkinitramfs.toml
// Section: EQL Rule
// Rule Name: Initramfs Unpacking via unmkinitramfs
// Author: Elastic
// Description:
// This rule detects the unpacking of an initramfs image using the "unmkinitramfs" command on Linux systems. The
// "unmkinitramfs" command is used to extract the contents of an initramfs image, which is used to boot the system.
// Attackers may use "unmkinitramfs" to unpack an initramfs image and modify its contents to include malicious code or
// backdoors, allowing them to maintain persistence on the system.
// Integration: endpoint, auditd_manager, crowdstrike, sentinel_one_cloud_funnel
// Language: eql
// UUID: c5fc788c-7576-4a02-b3d6-d2c016eb85a6
// Type: eql

process where host.os.type == "linux" and event.type == "start" and
event.action in ("exec", "exec_event", "start", "ProcessRollup2", "executed") and
process.name == "unmkinitramfs" and not (
  ?process.parent.executable == "/usr/bin/lsinitramfs" or
  ?process.working_directory == "/usr/local/nutanix/ngt/python/bin"
)

// Title: persistence_user_credential_modification_via_echo.toml
// Source: detection-rules::rules/linux/persistence_user_credential_modification_via_echo.toml
// Section: EQL Rule
// Rule Name: Linux User Account Credential Modification
// Author: Elastic
// Description:
// This rule detects Linux user account credential modification events where the echo command is
// used to directly echo a password into the passwd or shadow utilities. This technique is used by
// malware to automate the process of user account credential modification on Linux systems post-infection.
// Integration: endpoint
// Language: eql
// UUID: 79e7291f-9e3b-4a4b-9823-800daa89c8f9
// Type: eql

process where host.os.type == "linux" and event.type == "start" and event.action == "exec" and
process.name in ("bash", "dash", "sh", "tcsh", "csh", "zsh", "ksh", "fish") and
process.command_line like (
  "*echo*> /etc/passwd*", "*echo*>/etc/passwd*",
  "*echo*> /etc/shadow*", "*echo*>/etc/shadow*"
) and
not (
  process.parent.command_line == "runc init" or
  process.parent.executable in ("/usr/bin/make", "/bin/make")
)

// Title: persistence_user_or_group_creation_or_modification.toml
// Source: detection-rules::rules/linux/persistence_user_or_group_creation_or_modification.toml
// Section: EQL Rule
// Rule Name: User or Group Creation/Modification
// Author: Elastic
// Description:
// This rule leverages the "auditd_manager" integration to detect user or group creation or modification events on Linux
// systems. Threat actors may attempt to create or modify users or groups to establish persistence on the system.
// Integration: auditd_manager
// Language: eql
// UUID: fcf733d5-7801-4eb0-92ac-8ffacf3658f2
// Type: eql

iam where host.os.type == "linux" and event.type in ("creation", "change") and auditd.result == "success" and
event.action in ("changed-password", "added-user-account", "added-group-account-to") and process.name != null

// Title: persistence_webserver_php_file_creation_in_wordpress_plugin_dir.toml
// Source: detection-rules::rules/linux/persistence_webserver_php_file_creation_in_wordpress_plugin_dir.toml
// Section: EQL Rule
// Rule Name: PHP File Creation in WordPress Plugin Directory
// Author: Elastic
// Description:
// Detects the creation of a PHP file in the WordPress plugin directory, which is a common technique used
// by attackers to establish persistence on a compromised web server. Attackers may upload a malicious PHP
// file and call it from a web browser to gain remote access to the server.
// Integration: endpoint
// Language: eql
// UUID: fb76c80b-3eb2-4c56-9ed1-e4c529425d0f
// Type: eql

