// Title: defense_evasion_disabling_windows_logs.toml
// Source: detection-rules::rules/windows/defense_evasion_disabling_windows_logs.toml
// Section: EQL Rule
// Rule Name: Disable Windows Event and Security Logs Using Built-in Tools
// Author: Elastic, Ivan Ninichuck, Austin Songer
// Description:
// Identifies attempts to disable EventLog via the logman Windows utility, PowerShell, or auditpol. This is often done by
// attackers in an attempt to evade detection on a system.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 4de76544-f0e5-486a-8f84-eae0b6063cdc
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
(
  (
    (process.name:"logman.exe" or ?process.pe.original_file_name == "Logman.exe") and
    process.args : "EventLog-*" and process.args : ("stop", "delete")
  ) or
  (
    (
      process.name : ("pwsh.exe", "powershell.exe", "powershell_ise.exe") or
      ?process.pe.original_file_name in ("PowerShell.EXE", "pwsh.dll", "powershell_ise.EXE")
    ) and
	  process.args : "Set-Service" and process.args: "EventLog" and process.args : "Disabled"
  )  or
  (
    (process.name:"auditpol.exe" or ?process.pe.original_file_name == "AUDITPOL.EXE") and process.args : "/success:disable"
  )
)

// Title: defense_evasion_dns_over_https_enabled.toml
// Source: detection-rules::rules/windows/defense_evasion_dns_over_https_enabled.toml
// Section: EQL Rule
// Rule Name: DNS-over-HTTPS Enabled via Registry
// Author: Austin Songer
// Description:
// Identifies when a user enables DNS-over-HTTPS. This can be used to hide internet activity or the process of exfiltrating
// data. With this enabled, an organization will lose visibility into data such as query type, response, and originating
// IP, which are used to determine bad actors.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: a22a09c2-2162-4df0-a356-9aacbeb56a04
// Type: eql

registry where host.os.type == "windows" and event.type == "change" and
  (registry.path : "*\\SOFTWARE\\Policies\\Microsoft\\Edge\\BuiltInDnsClientEnabled" and
  registry.data.strings : ("1", "0x00000001")) or
  (registry.path : "*\\SOFTWARE\\Google\\Chrome\\DnsOverHttpsMode" and
  registry.data.strings : "secure") or
  (registry.path : "*\\SOFTWARE\\Policies\\Mozilla\\Firefox\\DNSOverHTTPS" and
  registry.data.strings : ("1", "0x00000001"))

// Title: defense_evasion_dotnet_compiler_parent_process.toml
// Source: detection-rules::rules/windows/defense_evasion_dotnet_compiler_parent_process.toml
// Section: EQL Rule
// Rule Name: Suspicious .NET Code Compilation
// Author: Elastic
// Description:
// Identifies executions of .NET compilers with suspicious parent processes, which can indicate an attacker's attempt to
// compile code after delivery in order to bypass security mechanisms.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 201200f1-a99b-43fb-88ed-f65a45c4972c
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.name : ("csc.exe", "vbc.exe") and
  process.parent.name : ("wscript.exe", "mshta.exe", "cscript.exe", "wmic.exe", "svchost.exe", "rundll32.exe", "cmstp.exe", "regsvr32.exe")

// Title: defense_evasion_edr_freeze_via_werfaultsecure.toml
// Source: detection-rules::rules/windows/defense_evasion_edr_freeze_via_werfaultsecure.toml
// Section: EQL Rule
// Rule Name: Potential EDR-Freeze via WerFaultSecure Abuse
// Author: Aryu Zaw
// Description:
// Identifies the Windows Error Reporting Protected Process Light (PPL) binary WerFaultSecure.exe being started by a
// process other than the Windows Error Reporting service, with command-line arguments used to take a secure memory dump of
// a target process. Because MiniDumpWriteDump suspends all threads of the target while the dump is produced, an attacker
// can suspend WerFaultSecure.exe mid-dump to leave the targeted EDR or antivirus suspended ("frozen") without ever
// terminating it, a defense-evasion technique publicly known as EDR-Freeze.
// Integration: endpoint, windows, sentinel_one_cloud_funnel, m365_defender
// Language: eql
// UUID: 7b75c162-d439-472d-b39f-2eb0d4d2d318
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.executable : "?:\\Windows\\System32\\WerFaultSecure.exe" and

  /* WerFaultSecure secure dumps are normally initiated by the WER service hosted in svchost.exe */
  process.parent.executable != null and
  not process.parent.executable : ("?:\\Windows\\System32\\svchost.exe", "?:\\Windows\\System32\\wermgr.exe", "?:\\Windows\\System32\\WerFault.exe", "?:\\Windows\\System32\\WerFaultSecure.exe") and

  /* arguments used to take a secure memory dump of a target process (e.g. /pid <target> /encfile <handle> /type 268310) */
  process.args : "/pid" and process.args : "/encfile"

// Title: defense_evasion_enable_inbound_rdp_with_netsh.toml
// Source: detection-rules::rules/windows/defense_evasion_enable_inbound_rdp_with_netsh.toml
// Section: EQL Rule
// Rule Name: Remote Desktop Enabled in Windows Firewall by Netsh
// Author: Elastic
// Description:
// Identifies use of the network shell utility (netsh.exe) to enable inbound Remote Desktop Protocol (RDP) connections in
// the Windows Firewall.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 074464f9-f30d-4029-8c03-0ed237fffec7
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
 (process.name : "netsh.exe" or ?process.pe.original_file_name == "netsh.exe") and
 process.args : ("localport=3389", "RemoteDesktop", "group=\"remote desktop\"") and
 process.args : ("action=allow", "enable=Yes", "enable")

// Title: defense_evasion_enable_network_discovery_with_netsh.toml
// Source: detection-rules::rules/windows/defense_evasion_enable_network_discovery_with_netsh.toml
// Section: EQL Rule
// Rule Name: Enable Host Network Discovery via Netsh
// Author: Elastic
// Description:
// Identifies use of the netsh.exe program to enable host discovery via the network. Attackers can use this command-line
// tool to weaken the host firewall settings.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 8b4f0816-6a65-4630-86a6-c21c179c0d09
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
process.name : "netsh.exe" and
process.args : ("firewall", "advfirewall") and process.args : "group=Network Discovery" and process.args : "enable=Yes"

// Title: defense_evasion_execution_control_panel_suspicious_args.toml
// Source: detection-rules::rules/windows/defense_evasion_execution_control_panel_suspicious_args.toml
// Section: EQL Rule
// Rule Name: Control Panel Process with Unusual Arguments
// Author: Elastic
// Description:
// Identifies unusual instances of Control Panel with suspicious keywords or paths in the process command line value.
// Adversaries may abuse control.exe to proxy execution of malicious code.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 416697ae-e468-4093-a93d-59661fa619ec
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.name : "control.exe" and
  process.command_line : (
    "*.jpg*", "*.png*",
    "*.gif*", "*.bmp*",
    "*.jpeg*", "*.TIFF*",
    "*.inf*", "*.cpl:*/*",
    "*../../..*",
    "*/AppData/Local/*",
    "*:\\Users\\Public\\*",
    "*\\AppData\\Local\\*"
)

// Title: defense_evasion_execution_lolbas_wuauclt.toml
// Source: detection-rules::rules/windows/defense_evasion_execution_lolbas_wuauclt.toml
// Section: EQL Rule
// Rule Name: ImageLoad via Windows Update Auto Update Client
// Author: Elastic
// Description:
// Identifies abuse of the Windows Update Auto Update Client (wuauclt.exe) to load an arbitrary DLL. This behavior is used
// as a defense evasion technique to blend-in malicious activity with legitimate Windows software.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: edf8ee23-5ea7-4123-ba19-56b41e424ae3
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  (?process.pe.original_file_name == "wuauclt.exe" or process.name : "wuauclt.exe") and
   /* necessary windows update client args to load a dll */
   process.args : "/RunHandlerComServer" and process.args : "/UpdateDeploymentProvider" and
   /* common paths writeable by a standard user where the target DLL can be placed */
   process.args : ("C:\\Users\\*.dll", "C:\\ProgramData\\*.dll", "C:\\Windows\\Temp\\*.dll", "C:\\Windows\\Tasks\\*.dll")

// Title: defense_evasion_execution_msbuild_started_by_office_app.toml
// Source: detection-rules::rules/windows/defense_evasion_execution_msbuild_started_by_office_app.toml
// Section: EQL Rule
// Rule Name: Microsoft Build Engine Started by an Office Application
// Author: Elastic
// Description:
// An instance of MSBuild, the Microsoft Build Engine, was started by an Office application. This is unusual behavior for
// the Build Engine and could have been caused by a malicious document executing a script payload.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: c5dc3223-13a2-44a2-946c-e9dc0aa0449c
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.name : "MSBuild.exe" and
  process.parent.name : ("eqnedt32.exe",
                         "excel.exe",
                         "fltldr.exe",
                         "msaccess.exe",
                         "mspub.exe",
                         "outlook.exe",
                         "powerpnt.exe",
                         "winword.exe" )

// Title: defense_evasion_execution_msbuild_started_by_system_process.toml
// Source: detection-rules::rules/windows/defense_evasion_execution_msbuild_started_by_system_process.toml
// Section: EQL Rule
// Rule Name: Microsoft Build Engine Started by a System Process
// Author: Elastic
// Description:
// An instance of MSBuild, the Microsoft Build Engine, was started by Explorer or the WMI (Windows Management
// Instrumentation) subsystem. This behavior is unusual and is sometimes used by malicious payloads.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 9d110cb3-5f4b-4c9a-b9f5-53f0a1707ae3
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.name : "MSBuild.exe" and
  process.parent.name : ("explorer.exe", "wmiprvse.exe")

// Title: defense_evasion_execution_msbuild_started_renamed.toml
// Source: detection-rules::rules/windows/defense_evasion_execution_msbuild_started_renamed.toml
// Section: EQL Rule
// Rule Name: Microsoft Build Engine Using an Alternate Name
// Author: Elastic
// Description:
// An instance of MSBuild, the Microsoft Build Engine, was started after being renamed. This is uncommon behavior and may
// indicate an attempt to run unnoticed or undetected.
// Integration: endpoint, windows, m365_defender, crowdstrike
// Language: eql
// UUID: 9d110cb3-5f4b-4c9a-b9f5-53f0a1707ae4
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.pe.original_file_name == "MSBuild.exe" and
  not process.name : "MSBuild.exe"

// Title: defense_evasion_execution_suspicious_explorer_winword.toml
// Source: detection-rules::rules/windows/defense_evasion_execution_suspicious_explorer_winword.toml
// Section: EQL Rule
// Rule Name: Potential DLL Side-Loading via Trusted Microsoft Programs
// Author: Elastic
// Description:
// Identifies an instance of a Windows trusted program that is known to be vulnerable to DLL Search Order Hijacking
// starting after being renamed or from a non-standard path. This is uncommon behavior and may indicate an attempt to evade
// defenses via side loading a malicious DLL within the memory space of one of those processes.
// Integration: endpoint, windows, m365_defender, crowdstrike, sentinel_one_cloud_funnel
// Language: eql
// UUID: 1160dcdb-0a0a-4a79-91d8-9b84616edebd
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  (
    process.name : ("WinWord.exe", "EXPLORER.EXE", "w3wp.exe", "DISM.EXE") or
    ?process.pe.original_file_name : ("WinWord.exe", "EXPLORER.EXE", "w3wp.exe", "DISM.EXE")
  ) and
  not process.executable : (
          "\\\\?\\Volume{????????-????-????-????-????????????}\\Windows\\System32\\inetsrv\\w3wp.exe",
          "?:\\PROGRA~?\\MICROS~?\\Office??\\winword.exe",
          "?:\\Program Files\\Microsoft Office\\*\\winword.exe",
          "?:\\Program Files\\Microsoft Office ??\\*\\winword.exe",
          "?:\\Program Files\\WindowsApps\\Microsoft.Office.Desktop.*\\Office??\\winword.exe",
          "?:\\Program Files (x86)\\Microsoft Office\\*\\winword.exe",
          "?:\\Program Files (x86)\\Windows Kits\\*Assessment and Deployment Kit\\Deployment Tools\\amd64\\DISM\\dism.exe",
          "?:\\Windows\\explorer.exe",
          "?:\\Windows\\System32\\Dism.exe",
          "?:\\Windows\\System32\\inetsrv\\w3wp.exe",
          "?:\\Windows\\SysWOW64\\Dism.exe",
          "?:\\Windows\\SysWOW64\\explorer.exe",
          "?:\\Windows\\SysWOW64\\inetsrv\\w3wp.exe"
  ) and
  /* Crowdstrike specific exclusion as it uses NT Object paths */
  not
  (
    data_stream.dataset == "crowdstrike.fdr" and
    process.executable : (
        "\\Device\\HarddiskVolume*\\Program Files\\Microsoft Office\\*\\winword.exe",
        "\\Device\\HarddiskVolume*\\Program Files\\Microsoft Office ??\\*\\winword.exe",
        "\\Device\\HarddiskVolume*\\Program Files\\WindowsApps\\Microsoft.Office.Desktop.*\\Office??\\winword.exe",
        "\\Device\\HarddiskVolume*\\Program Files (x86)\\Microsoft Office\\*\\winword.exe",
        "\\Device\\HarddiskVolume*\\Program Files (x86)\\Windows Kits\\10\\Assessment and Deployment Kit\\Deployment Tools\\amd64\\DISM\\dism.exe",
        "\\Device\\HarddiskVolume*\\Windows\\explorer.exe",
        "\\Device\\HarddiskVolume*\\Windows\\System32\\Dism.exe",
        "\\Device\\HarddiskVolume*\\Windows\\System32\\inetsrv\\w3wp.exe",
        "\\Device\\HarddiskVolume*\\Windows\\SysWOW64\\Dism.exe",
        "\\Device\\HarddiskVolume*\\Windows\\SysWOW64\\explorer.exe",
        "\\Device\\HarddiskVolume*\\Windows\\SysWOW64\\inetsrv\\w3wp.exe"
    )
  )

// Title: defense_evasion_execution_windefend_unusual_path.toml
// Source: detection-rules::rules/windows/defense_evasion_execution_windefend_unusual_path.toml
// Section: EQL Rule
// Rule Name: Suspicious Microsoft Antimalware Service Execution
// Author: Elastic, Dennis Perto
// Description:
// Identifies suspicious execution of the Microsoft Antimalware Service Executable (MsMpEng.exe) from non-standard paths or
// renamed instances. This may indicate an attempt to evade defenses through DLL side-loading or by masquerading as the
// antimalware process.
// Integration: endpoint, windows, m365_defender, crowdstrike
// Language: eql
// UUID: 053a0387-f3b5-4ba5-8245-8002cca2bd08
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
(
  (process.pe.original_file_name == "MsMpEng.exe" and not process.name : "MsMpEng.exe") or
  (
    process.name : "MsMpEng.exe" and
    not process.executable : (
            "?:\\ProgramData\\Microsoft\\Windows Defender\\*.exe",
            "?:\\Program Files\\Windows Defender\\*.exe",
            "?:\\Program Files (x86)\\Windows Defender\\*.exe",
            "?:\\Program Files\\Microsoft Security Client\\*.exe",
            "?:\\Program Files (x86)\\Microsoft Security Client\\*.exe",

            /* Crowdstrike specific exclusion as it uses NT Object paths */
            "\\Device\\HarddiskVolume*\\ProgramData\\Microsoft\\Windows Defender\\*.exe",
            "\\Device\\HarddiskVolume*\\Program Files\\Windows Defender\\*.exe",
            "\\Device\\HarddiskVolume*\\Program Files (x86)\\Windows Defender\\*.exe",
            "\\Device\\HarddiskVolume*\\Program Files\\Microsoft Security Client\\*.exe",
            "\\Device\\HarddiskVolume*\\Program Files (x86)\\Microsoft Security Client\\*.exe"
    )
  )
)

// Title: defense_evasion_file_creation_mult_extension.toml
// Source: detection-rules::rules/windows/defense_evasion_file_creation_mult_extension.toml
// Section: EQL Rule
// Rule Name: Executable File Creation with Multiple Extensions
// Author: Elastic
// Description:
// Masquerading can allow an adversary to evade defenses and better blend in with the environment. One way it occurs is
// when the name or location of a file is manipulated as a means of tricking a user into executing what they think is a
// benign file type but is actually executable code.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 8b2b3a62-a598-4293-bc14-3d5fa22bb98f
// Type: eql

file where host.os.type == "windows" and event.type == "creation" and file.extension : "exe" and
  file.name regex~ """.*\.(vbs|vbe|bat|js|cmd|wsh|ps1|pdf|docx?|xlsx?|pptx?|txt|rtf|gif|jpg|png|bmp|hta|txt|img|iso)\.exe""" and
  not (
      process.executable : (
          "?:\\Windows\\System32\\msiexec.exe",
          "\\Device\\HarddiskVolume*\\Windows\\System32\\msiexec.exe",
          "*\\Users\\*\\QGIS_SCCM\\Files\\QGIS-OSGeo4W-*-Setup-x86_64.exe"
      ) and
      file.path : ("?:\\Program Files\\QGIS *\\apps\\grass\\*.exe", "\\Device\\HarddiskVolume*\\Program Files\\QGIS *\\apps\\grass\\*.exe")
  ) and 
  not process.executable : 
                             ("C:\\Program Files\\dotnet\\dotnet.exe", 
                              "C:\\Program Files\\Microsoft Visual Studio\\*.exe",
                              "\\Device\\HarddiskVolume*\\Program Files\\dotnet\\dotnet.exe", 
                              "\\Device\\HarddiskVolume*\\Program Files\\Microsoft Visual Studio\\*.exe")

// Title: defense_evasion_iis_httplogging_disabled.toml
// Source: detection-rules::rules/windows/defense_evasion_iis_httplogging_disabled.toml
// Section: EQL Rule
// Rule Name: IIS HTTP Logging Disabled
// Author: Elastic
// Description:
// Identifies when Internet Information Services (IIS) HTTP Logging is disabled on a server. An attacker with IIS server
// access via a webshell or other mechanism can disable HTTP Logging as an effective anti-forensics measure.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: ebf1adea-ccf2-4943-8b96-7ab11ca173a5
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  (process.name : "appcmd.exe" or ?process.pe.original_file_name == "appcmd.exe") and
  process.args : "/dontLog*:*True" and
  not process.parent.name : "iissetup.exe"

// Title: defense_evasion_indirect_exec_conhost.toml
// Source: detection-rules::rules/windows/defense_evasion_indirect_exec_conhost.toml
// Section: EQL Rule
// Rule Name: Proxy Execution via Console Window Host
// Author: Elastic
// Description:
// Identifies abuse of the Console Window Host (conhost.exe) to execute commands via proxy. This behavior is used as a defense
// evasion technique to blend-in malicious activity with legitimate Windows software.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: fcd16fe8-eb29-42b3-8aee-6c9ad777a2f6
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
 process.name : "conhost.exe" and process.args : "--headless" and
  process.command_line : (
    "*powershell*", "*cmd *", "*cmd.exe *", "*script*", "*mshta*", "*curl *", "*curl.exe *", "*^*^*^*",
    "*.bat*", "*.cmd*", "*schtasks*", "*@SSL*", "*http*", "* \\\\*", "*.vbs*", "*.js*", "*mhsta*"
  ) and
  not (
    /* Winget-AutoUpdate via ServiceUI */
    process.parent.executable : "?:\\Program Files\\winget-autoupdate*\\serviceui.exe" or
    /* Winget-AutoUpdate notification via Task Scheduler */
    (
      process.parent.executable : "?:\\Windows\\System32\\svchost.exe" and process.parent.args : "-s" and
      process.parent.args : "Schedule" and process.command_line : "*WAU-Notify.ps1*"
    ) or
    /* Windows OpenSSH console host — SSH-specific detection handled by 8cd49fbc-a35a-4418-8688-133cc3a1e548 */
    process.parent.executable : (
      "?:\\Windows\\System32\\OpenSSH\\sshd.exe",
      "?:\\Windows\\System32\\OpenSSH\\sshd-session.exe",
      "?:\\Program Files\\OpenSSH*\\sshd.exe",
      "?:\\Program Files\\OpenSSH*\\sshd-session.exe"
    )
  )

// Title: defense_evasion_indirect_exec_forfiles.toml
// Source: detection-rules::rules/windows/defense_evasion_indirect_exec_forfiles.toml
// Section: EQL Rule
// Rule Name: Command Execution via ForFiles
// Author: Elastic
// Description:
// Detects attempts to execute a command via the forfiles Windows utility. Adversaries may use this utility to proxy
// execution via a trusted parent process.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 3f7bd5ac-9711-44b4-82c1-fa246d829f15
// Type: eql

process where host.os.type == "windows" and event.type == "start" and user.id != "S-1-5-18" and
 (process.name : "forfiles.exe" or ?process.pe.original_file_name == "forfiles.exe") and process.args : ("/c", "-c") and
 not process.args : ("-d", "/d", "cmd /c copy @file*", "cmd /c DEL /Q /F @*", "cmd /c del @*", "D:\\*")

// Title: defense_evasion_indirect_exec_openssh.toml
// Source: detection-rules::rules/windows/defense_evasion_indirect_exec_openssh.toml
// Section: EQL Rule
// Rule Name: Proxy Execution via Windows OpenSSH
// Author: Elastic
// Description:
// Identifies attempts to execute commands via proxy using the Windows OpenSSH client. This may indicate an attempt
// to bypass application control via trusted Windows binaries.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 8cd49fbc-a35a-4418-8688-133cc3a1e548
// Type: eql

process where host.os.type == "windows" and event.type == "start" and process.name : ("ssh.exe", "sftp.exe") and
  process.command_line : (
    "*Command=*powershell*", "*schtasks*", "*Command=*@echo off*", "*Command=*http*",
    "*Command=*mshta*", "*Command=*msiexec*", "*Command=*cmd /c*", "*Command=*cmd.exe*",
    "*Command=\"cmd /c*", "*LocalCommand=scp*&&*", "*LocalCommand=?scp*&&*", "*Command=*script*"
  )

// Title: defense_evasion_injection_msbuild.toml
// Source: detection-rules::rules/windows/defense_evasion_injection_msbuild.toml
// Section: EQL Rule
// Rule Name: Process Injection by the Microsoft Build Engine
// Author: Elastic
// Description:
// An instance of MSBuild, the Microsoft Build Engine, created a thread in another process. This technique is sometimes
// used to evade detection or elevate privileges.
// Integration: windows
// Language: eql
// UUID: 9d110cb3-5f4b-4c9a-b9f5-53f0a1707ae9
// Type: eql

process where host.os.type == "windows" and
  event.provider == "Microsoft-Windows-Sysmon" and
  /* CreateRemoteThread */
  event.code == "8" and process.name: "MSBuild.exe"

// Title: defense_evasion_installutil_beacon.toml
// Source: detection-rules::rules/windows/defense_evasion_installutil_beacon.toml
// Section: EQL Rule
// Rule Name: InstallUtil Process Making Network Connections
// Author: Elastic
// Description:
// Identifies InstallUtil.exe making outbound network connections. This may indicate adversarial activity as InstallUtil is
// often leveraged by adversaries to execute code and evade detection.
// Integration: endpoint, windows, sentinel_one_cloud_funnel
// Language: eql
// UUID: a13167f1-eec2-4015-9631-1fee60406dcf
// Type: eql

/* the benefit of doing this as an eql sequence vs kql is this will limit to alerting only on the first network connection */

sequence by process.entity_id
  [process where host.os.type == "windows" and event.type == "start" and process.name : "installutil.exe"]
  [network where host.os.type == "windows" and process.name : "installutil.exe" and network.direction : ("outgoing", "egress")]

// Title: defense_evasion_lolbas_win_cdb_utility.toml
// Source: detection-rules::rules/windows/defense_evasion_lolbas_win_cdb_utility.toml
// Section: EQL Rule
// Rule Name: Execution via Windows Command Debugging Utility
// Author: Elastic
// Description:
// An adversary can use the Windows command line debugging utility cdb.exe to execute commands or shellcode. This rule
// looks for those instances and where the cdb.exe binary is outside of the normal WindowsKit installation paths.
// Integration: endpoint, windows, system, sentinel_one_cloud_funnel, m365_defender, crowdstrike
// Language: eql
// UUID: bdfaddc4-4438-48b4-bc43-9f5cf8151c46
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
 (?process.pe.original_file_name == "CDB.Exe" or process.name : "cdb.exe") and
  process.args : ("-cf", "-c", "-pd") and
  not process.executable : (
        "?:\\Program Files (x86)\\*\\cdb.exe",
        "?:\\Program Files\\*\\cdb.exe",

        /* Crowdstrike specific exclusion as it uses NT Object paths */
        "\\Device\\HarddiskVolume*\\Program Files (x86)\\*\\cdb.exe",
        "\\Device\\HarddiskVolume*\\Program Files\\*\\cdb.exe"
  )

// Title: defense_evasion_lsass_ppl_disabled_registry.toml
// Source: detection-rules::rules/windows/defense_evasion_lsass_ppl_disabled_registry.toml
// Section: EQL Rule
// Rule Name: Disabling Lsa Protection via Registry Modification
// Author: Elastic
// Description:
// LSA protecton is provided to prevent nonprotected processes from reading memory and injecting code. This feature
// provides added security for the credentials that LSA stores and manages. Adversaries may modify the RunAsPPL registry
// and wait or initiate a system restart to enable Lsass credentials access.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 37cb6756-8892-4af3-a6bd-ddc56db0069d
// Type: eql

registry where host.os.type == "windows" and event.type == "change" and
  registry.data.strings != null and process.name != null and
  registry.value : "RunAsPPL" and
  registry.path : "*\\SYSTEM\\*ControlSet*\\Control\\Lsa\\RunAsPPL" and
  not registry.data.strings : ("1", "0x00000001", "2", "0x00000002") and
  not process.executable : "?:\\Windows\\System32\\SecurityHealthService.exe"

// Title: defense_evasion_mark_of_the_web_removal_unusual_process.toml
// Source: detection-rules::rules/windows/defense_evasion_mark_of_the_web_removal_unusual_process.toml
// Section: EQL Rule
// Rule Name: Mark-of-the-Web Removal by an Unusual Process
// Author: Elastic
// Description:
// Identifies an unusual process deleting the Zone.Identifier alternate data stream from an executable or Windows Installer
// package. Attackers can remove this stream to bypass Mark-of-the-Web protections.
// Integration: endpoint
// Language: eql
// UUID: 757371cd-5e9e-4adb-bc4e-d81f0ad0ec4d
// Type: eql

file where host.os.type == "windows" and event.type == "deletion" and
  file.path : (
    "*.exe:Zone.Identifier",
    "*.exe:Zone.Identifier:$DATA",
    "*.msi:Zone.Identifier",
    "*.msi:Zone.Identifier:$DATA"
  ) and

  /* Explorer may remove MOTW after SmartScreen */
  not (
    process.executable : "?:\\Windows\\explorer.exe" and
    process.code_signature.trusted == true and
    process.code_signature.subject_name : "Microsoft Windows"
  )

// Title: defense_evasion_masquerading_as_elastic_endpoint_process.toml
// Source: detection-rules::rules/windows/defense_evasion_masquerading_as_elastic_endpoint_process.toml
// Section: EQL Rule
// Rule Name: Suspicious Endpoint Security Parent Process
// Author: Elastic
// Description:
// A suspicious Endpoint Security parent process was detected. This may indicate a process hollowing or other form of code
// injection.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel
// Language: eql
// UUID: b41a13c6-ba45-4bab-a534-df53d0cfed6a
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.name : ("esensor.exe", "elastic-endpoint.exe") and
  process.parent.executable != null and
  process.args != null and
  /* add FPs here */
  not process.parent.executable : (
        "?:\\Program Files\\Elastic\\*",
        "?:\\Windows\\System32\\services.exe",
        "?:\\Windows\\System32\\WerFault*.exe",
        "?:\\Windows\\System32\\wermgr.exe",
        "?:\\Windows\\explorer.exe"
  ) and
  not (
    process.parent.executable : (
        "?:\\Windows\\System32\\cmd.exe",
        "?:\\Windows\\System32\\SecurityHealthHost.exe",
        "?:\\Windows\\System32\\SecurityHealth\\*\\SecurityHealthHost.exe",
        "?:\\Windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe"
    ) and
    process.args : (
        "test", "version",
        "top", "run",
        "*help", "status",
        "upgrade", "/launch",
        "/enable", "/av"
    )
  )

// Title: defense_evasion_masquerading_as_svchost.toml
// Source: detection-rules::rules/windows/defense_evasion_masquerading_as_svchost.toml
// Section: EQL Rule
// Rule Name: Potential Masquerading as Svchost
// Author: Elastic
// Description:
// Identifies attempts to masquerade as the Service Host process `svchost.exe` to evade detection and blend in with
// normal system activity.
// Integration: endpoint, windows, system
// Language: esql
// UUID: 32f95776-6498-4f3c-a90c-d4f6083e3901
// Type: esql

FROM logs-endpoint.events.process-*, logs-windows.sysmon_operational-*, logs-system.security-*, logs-windows.*, winlogbeat-* metadata _id, _version, _index
| where event.category == "process" and event.type == "start" and
  match(process.name, "svchost.exe", { "fuzziness": 1, "max_expansions": 10 }) and
  not to_lower(process.executable) in ("c:\\windows\\syswow64\\svchost.exe", "c:\\windows\\system32\\svchost.exe") and
  not to_lower(process.executable) like """\\device\\harddiskvolume*\\windows\\system32\\svchost.exe""" and
  not to_lower(process.executable) like """\\device\\harddiskvolume*\\windows\\syswow64\\svchost.exe""" 
| keep *

// Title: defense_evasion_masquerading_business_apps_installer.toml
// Source: detection-rules::rules/windows/defense_evasion_masquerading_business_apps_installer.toml
// Section: EQL Rule
// Rule Name: Potential Masquerading as Business App Installer
// Author: Elastic
// Description:
// Identifies executables with names resembling legitimate business applications but lacking signatures from the original
// developer. Attackers may trick users into downloading malicious executables that masquerade as legitimate applications
// via malicious ads, forum posts, and tutorials, effectively gaining initial access.
// Integration: endpoint
// Language: eql
// UUID: feafdc51-c575-4ed2-89dd-8e20badc2d6c
// Type: eql

process where host.os.type == "windows" and 
  event.type == "start" and process.executable : "?:\\Users\\*\\Downloads\\*" and
  not process.code_signature.status like ("errorCode_endpoint*", "errorUntrustedRoot", "errorChaining") and process.hash.sha256 != null and 
  (
    /* Slack */
    (process.name : "*slack*.exe" and not
      (process.code_signature.subject_name in (
        "Slack Technologies, Inc.",
        "Slack Technologies, LLC"
       ) and process.code_signature.trusted == true)
    ) or

    /* WebEx */
    (process.name : "*webex*.exe" and not
      (process.code_signature.subject_name in ("Cisco WebEx LLC", "Cisco Systems, Inc.") and process.code_signature.trusted == true)
    ) or

    /* Teams */
    (process.name : "teams*.exe" and not
      (process.code_signature.subject_name == "Microsoft Corporation" and process.code_signature.trusted == true)
    ) or

    /* Discord */
    (process.name : "*discord*.exe" and not
      (process.code_signature.subject_name == "Discord Inc." and process.code_signature.trusted == true)
    ) or

    /* WhatsApp */
    (process.name : "*whatsapp*.exe" and not
      (process.code_signature.subject_name in (
        "WhatsApp LLC",
        "WhatsApp, Inc",
        "24803D75-212C-471A-BC57-9EF86AB91435",
        /* WhatsApp Installer - MS Store */
        "Microsoft Corporation"
       ) and process.code_signature.trusted == true)
    ) or

    /* Zoom */
    (process.name : ("*zoom*installer*.exe", "*zoom*setup*.exe", "zoom.exe")  and not
      (process.code_signature.subject_name in (
        "Zoom Video Communications, Inc.", "Zoom Communications, Inc."
       ) and process.code_signature.trusted == true)
    ) or

    /* Outlook */
    (process.name : "*outlook*.exe" and not
      (
        (process.code_signature.subject_name == "Microsoft Corporation" and process.code_signature.trusted == true) or
        (
          process.name: "MSOutlookHelp-PST-Viewer.exe" and process.code_signature.subject_name == "Aryson Technologies Pvt. Ltd" and
          process.code_signature.trusted == true
        )
      )
    ) or

    /* Thunderbird */
    (process.name : "*thunderbird*.exe" and not
      (process.code_signature.subject_name == "Mozilla Corporation" and process.code_signature.trusted == true)
    ) or

    /* Grammarly */
    (process.name : "*grammarly*.exe" and not
      (process.code_signature.subject_name == "Grammarly, Inc." and process.code_signature.trusted == true)
    ) or

    /* Dropbox */
    (process.name : "*dropbox*.exe" and not
      (process.code_signature.subject_name == "Dropbox, Inc" and process.code_signature.trusted == true)
    ) or

    /* Tableau */
    (process.name : "*tableau*.exe" and not
      (process.code_signature.subject_name == "Tableau Software LLC" and process.code_signature.trusted == true)
    ) or

    /* Google Drive */
    (process.name : "*googledrive*.exe" and not
      (process.code_signature.subject_name == "Google LLC" and process.code_signature.trusted == true)
    ) or

    /* MSOffice */
    (process.name : "*office*setup*.exe" and not
      (process.code_signature.subject_name == "Microsoft Corporation" and process.code_signature.trusted == true)
    ) or

    /* Okta */
    (process.name : "*okta*.exe" and not
      (process.code_signature.subject_name == "Okta, Inc." and process.code_signature.trusted == true)
    ) or

    /* OneDrive */
    (process.name : "*onedrive*.exe" and not
      (process.code_signature.subject_name == "Microsoft Corporation" and process.code_signature.trusted == true)
    ) or

    /* Chrome */
    (process.name : "*chrome*.exe" and not
      (process.code_signature.subject_name in ("Google LLC", "Google Inc") and process.code_signature.trusted == true)
    ) or

    /* Firefox */
    (process.name : "*firefox*.exe" and not
      (process.code_signature.subject_name == "Mozilla Corporation" and process.code_signature.trusted == true)
    ) or

    /* Edge */
    (process.name : ("*microsoftedge*.exe", "*msedge*.exe") and not
      (process.code_signature.subject_name == "Microsoft Corporation" and process.code_signature.trusted == true)
    ) or

    /* Brave */
    (process.name : "*brave*.exe" and not
      (process.code_signature.subject_name == "Brave Software, Inc." and process.code_signature.trusted == true)
    ) or

    /* GoogleCloud Related Tools */
    (process.name : "*GoogleCloud*.exe" and not
      (process.code_signature.subject_name == "Google LLC" and process.code_signature.trusted == true)
    ) or

    /* Github Related Tools */
    (process.name : "*github*.exe" and not
      (process.code_signature.subject_name == "GitHub, Inc." and process.code_signature.trusted == true)
    ) or

    /* Notion */
    (process.name : "*notion*.exe" and not
      (process.code_signature.subject_name == "Notion Labs, Inc." and process.code_signature.trusted == true)
    )
  )

// Title: defense_evasion_masquerading_communication_apps.toml
// Source: detection-rules::rules/windows/defense_evasion_masquerading_communication_apps.toml
// Section: EQL Rule
// Rule Name: Potential Masquerading as Communication Apps
// Author: Elastic
// Description:
// Identifies suspicious instances of communications apps, both unsigned and renamed ones, that can indicate an attempt to
// conceal malicious activity, bypass security features such as allowlists, or trick users into executing malware.
// Integration: endpoint, sentinel_one_cloud_funnel
// Language: eql
// UUID: c9482bfa-a553-4226-8ea2-4959bd4f7923
// Type: eql

process where host.os.type == "windows" and
  event.type == "start" and 
  not process.code_signature.status like "errorCode_endpoint*" and process.hash.sha256 != null and 
  (
    /* Slack */
    (process.name : "slack.exe" and not
      (process.code_signature.subject_name : (
        "Slack Technologies, Inc.",
        "Slack Technologies, LLC"
       ) and process.code_signature.trusted == true)
    ) or

    /* WebEx */
    (process.name : "WebexHost.exe" and not
      (process.code_signature.subject_name : ("Cisco WebEx LLC", "Cisco Systems, Inc.") and process.code_signature.trusted == true)
    ) or

    /* Teams */
    (process.name : "Teams.exe" and not
      (process.code_signature.subject_name : "Microsoft Corporation" and process.code_signature.trusted == true) and 
      process.executable != "C:\\Program Files (x86)\\Teams Installer\\Teams.exe"
    ) or

    /* Discord */
    (process.name : "Discord.exe" and not
      (process.code_signature.subject_name : "Discord Inc." and process.code_signature.trusted == true)
    ) or

    /* RocketChat */
    (process.name : "Rocket.Chat.exe" and not
      (process.code_signature.subject_name : "Rocket.Chat Technologies Corp." and process.code_signature.trusted == true) and 
      process.executable != "C:\\Program Files\\rocketchat\\Rocket.Chat.exe"
    ) or

    /* Mattermost */
    (process.name : "Mattermost.exe" and not
      (process.code_signature.subject_name : "Mattermost, Inc." and process.code_signature.trusted == true)
    ) or

    /* WhatsApp */
    (process.name : "WhatsApp.exe" and not
      (process.code_signature.subject_name : (
        "WhatsApp LLC",
        "WhatsApp, Inc",
        "24803D75-212C-471A-BC57-9EF86AB91435"
       ) and process.code_signature.trusted == true)
    ) or

    /* Zoom */
    (process.name : "Zoom.exe" and not
      (process.code_signature.subject_name : (
        "Zoom Video Communications, Inc.",
        "Zoom Communications, Inc."
       ) and process.code_signature.trusted == true)
    ) or

    /* Outlook */
    (process.name : "outlook.exe" and not
      (process.code_signature.subject_name : "Microsoft Corporation" and process.code_signature.trusted == true)
    ) or

    /* Thunderbird */
    (process.name : "thunderbird.exe" and not
      (process.code_signature.subject_name : "Mozilla Corporation" and process.code_signature.trusted == true)
    )
  )

// Title: defense_evasion_masquerading_renamed_autoit.toml
// Source: detection-rules::rules/windows/defense_evasion_masquerading_renamed_autoit.toml
// Section: EQL Rule
// Rule Name: Renamed Automation Script Interpreter
// Author: Elastic
// Description:
// Identifies renamed automation script interpreter processes, including AutoIt, AutoHotkey, and KIX32. Malware operators
// may rename these executables to avoid detection.
// Integration: endpoint, windows, m365_defender, crowdstrike
// Language: eql
// UUID: 2e1e835d-01e5-48ca-b9fc-7a61f7f11902
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  (
   (process.pe.original_file_name : "AutoIt*.exe" and not process.name : "AutoIt*.exe") or
   (process.pe.original_file_name == "AutoHotkey.exe" and not process.name : ("AutoHotkey*.exe", "InternalAHK.exe")) or
   (process.pe.original_file_name == "KIX32.EXE" and not process.name : "KIX*.exe" and process.executable : ("?:\\Users\\*.exe", "?:\\ProgramData\\*.exe", "\\Device\\HarddiskVolume*\\Users\\*.exe", "\\Device\\HarddiskVolume*\\ProgramData\\*.exe"))
   )

// Title: defense_evasion_masquerading_suspicious_werfault_childproc.toml
// Source: detection-rules::rules/windows/defense_evasion_masquerading_suspicious_werfault_childproc.toml
// Section: EQL Rule
// Rule Name: Suspicious WerFault Child Process
// Author: Elastic
// Description:
// A suspicious WerFault child process was detected, which may indicate an attempt to run via the SilentProcessExit
// registry key manipulation. Verify process details such as command line, network connections and file writes.
// Integration: endpoint, windows, sentinel_one_cloud_funnel, m365_defender
// Language: eql
// UUID: ac5012b8-8da8-440b-aaaf-aedafdea2dff
// Type: eql

process where host.os.type == "windows" and event.type == "start" and

  process.parent.name : "WerFault.exe" and

  /* args -s and -t used to execute a process via SilentProcessExit mechanism */
  (process.parent.args : "-s" and process.parent.args : "-t" and process.parent.args : "-c") and

  not process.executable : ("?:\\Windows\\SysWOW64\\Initcrypt.exe", "?:\\Program Files (x86)\\Heimdal\\Heimdal.Guard.exe")

// Title: defense_evasion_masquerading_trusted_directory.toml
// Source: detection-rules::rules/windows/defense_evasion_masquerading_trusted_directory.toml
// Section: EQL Rule
// Rule Name: Program Files Directory Masquerading
// Author: Elastic
// Description:
// Identifies execution from a directory masquerading as the Windows Program Files directories. These paths are trusted and
// usually host trusted third party programs. An adversary may leverage masquerading, along with low privileges to bypass
// detections allowlisting those folders.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 32c5cf9c-2ef8-4e87-819e-5ccb7cd18b14
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.executable : (
    "C:\\*Program Files*\\*.exe",
    "\\Device\\HarddiskVolume*\\*Program Files*\\*.exe"
  ) and
  not process.executable : (
        "?:\\Program Files\\*.exe",
        "?:\\Program Files (x86)\\*.exe",
        "?:\\Users\\*.exe",
        "?:\\ProgramData\\*.exe",
        "?:\\Windows\\Downloaded Program Files\\*.exe",
        "?:\\Windows\\Temp\\.opera\\????????????\\CProgram?FilesOpera*\\*.exe",
        "?:\\Windows\\Temp\\.opera\\????????????\\CProgram?Files?(x86)Opera*\\*.exe",

        /* NT Object Paths */
        "\\Device\\HarddiskVolume*\\Program Files\\*.exe",
        "\\Device\\HarddiskVolume*\\Program Files (x86)\\*.exe",
        "\\Device\\HarddiskVolume*\\Users\\*.exe",
        "\\Device\\HarddiskVolume*\\ProgramData\\*.exe",
        "\\Device\\HarddiskVolume*\\Windows\\Downloaded Program Files\\*.exe"
  )

// Title: defense_evasion_masquerading_werfault.toml
// Source: detection-rules::rules/windows/defense_evasion_masquerading_werfault.toml
// Section: EQL Rule
// Rule Name: Potential Windows Error Manager Masquerading
// Author: Elastic
// Description:
// Identifies suspicious instances of the Windows Error Reporting process (WerFault.exe or Wermgr.exe) with matching
// command-line and process executable values performing outgoing network connections. This may be indicative of a
// masquerading attempt to evade suspicious child process behavior detections.
// Integration: endpoint, windows
// Language: eql
// UUID: 6ea41894-66c3-4df7-ad6b-2c5074eb3df8
// Type: eql

sequence by host.id, process.entity_id with maxspan = 5s
  [process where host.os.type == "windows" and event.type:"start" and process.name : ("wermgr.exe", "WerFault.exe") and
    (process.args_count == 1 and
      /* Excludes bug where a missing closing quote sets args_count to 1 despite extra args */
      not process.command_line regex~ """\".*\.exe[^\"].*""")]
  [network where host.os.type == "windows" and process.name : ("wermgr.exe", "WerFault.exe") and network.protocol != "dns" and
    network.direction : ("outgoing", "egress") and destination.ip !="::1" and destination.ip !="127.0.0.1"
  ]

// Title: defense_evasion_masquerading_windows_dll.toml
// Source: detection-rules::rules/windows/defense_evasion_masquerading_windows_dll.toml
// Section: EQL Rule
// Rule Name: Potential Masquerading as System32 DLL
// Author: Elastic
// Description:
// Identifies suspicious instances of default system32 DLLs either unsigned or signed with non-MS certificates. This can
// potentially indicate the attempt to masquerade as system DLLs, perform DLL Search Order Hijacking or backdoor and resign
// legitimate DLLs.
// Integration: endpoint
// Language: eql
// UUID: fb01d790-9f74-4e76-97dd-b4b0f7bf6435
// Type: eql

library where host.os.type == "windows" and event.action == "load" and 
(dll.Ext.relative_file_creation_time <= 3600 or dll.Ext.relative_file_name_modify_time <= 3600) and
    not (
      dll.path : (
        "?:\\Windows\\System32\\*",
        "?:\\Windows\\SysWOW64\\*",
        "?:\\Windows\\SystemTemp\\*",
        "?:\\$WINDOWS.~BT\\NewOS\\Windows\\WinSxS\\*",
        "?:\\$WINDOWS.~BT\\NewOS\\Windows\\System32\\*",
        "?:\\$WINDOWS.~BT\\Sources\\*",
        "?:\\$WINDOWS.~BT\\Work\\*",
        "?:\\Windows\\WinSxS\\*",
        "?:\\Windows\\SoftwareDistribution\\Download\\*",
        "?:\\Windows\\assembly\\NativeImages_v*"
      )
    ) and
    not (
      dll.code_signature.subject_name in (
        "Microsoft Windows",
        "Microsoft Corporation",
        "Microsoft Windows Hardware Abstraction Layer Publisher",
        "Microsoft Windows Publisher",
        "Microsoft Windows 3rd party Component",
        "Microsoft 3rd Party Application Component"
      ) and dll.code_signature.trusted == true
