      (dll.code_signature.trusted == true and 
       dll.code_signature.subject_name in (
        "ALIBABA CLOUD COMPUTING LTD", 
        "Epic Systems Corporation", 
        "Google LLC",
        "Agilysys, Inc.", 
        "CD PROJEKT S.A.", 
        "Check Point Software Technologies Ltd.", 
        "Dedalus Italia S.P.A.", 
        "AOMEI International Network Limited", 
        "CHENGDU AOMEI TECHNOLOGY CO., LTD.", 
        "GN Hearing A/S", 
        "Paessler GmbH", 
        "Symantec Corporation")) or
      (
        dll.path : (
          "?:\\Windows\\SystemApps\\*\\dxgi.dll",
          "?:\\Windows\\SystemApps\\*\\wincorlib.dll",
          "?:\\Windows\\dxgi.dll",
          "?:\\Users\\*\\AppData\\Local\\LINE\\bin\\current\\dbghelp.dll", 
          "?:\\Program Files (x86)\\SAP\\FrontEnd\\SAPgui\\dbghelp.dll", 
          "?:\\Program Files (x86)\\Common Files\\Crystal Decision\\2.0\\bin\\atl.dll"
        )
      )
    )

// Title: defense_evasion_microsoft_defender_tampering.toml
// Source: detection-rules::rules/windows/defense_evasion_microsoft_defender_tampering.toml
// Section: EQL Rule
// Rule Name: Microsoft Windows Defender Tampering
// Author: Austin Songer
// Description:
// Identifies when one or more features on Microsoft Defender are disabled. Adversaries may disable or tamper with
// Microsoft Defender features to evade detection and conceal malicious behavior.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: fe794edd-487f-4a90-b285-3ee54f2af2d3
// Type: eql

registry where host.os.type == "windows" and event.type == "change" and process.executable != null and
  (
    (
      registry.value : (
        "PUAProtection", "DisallowExploitProtectionOverride", "TamperProtection", "EnableControlledFolderAccess",
        "SpynetReporting", "SubmitSamplesConsent"
      ) and registry.data.strings : ("0", "0x00000000")
    ) or
    (
      registry.value : (
        "DisableAntiSpyware", "DisableRealtimeMonitoring", "DisableIntrusionPreventionSystem", "DisableScriptScanning",
        "DisableIOAVProtection", "DisableEnhancedNotifications", "DisableBlockAtFirstSeen", "DisableBehaviorMonitoring"
      ) and registry.data.strings : ("1", "0x00000001")
    )
  ) and
  not process.executable : (
    "?:\\Windows\\system32\\svchost.exe", 
    "?:\\Windows\\CCM\\CcmExec.exe", 
    "?:\\Windows\\System32\\DeviceEnroller.exe", 
    "?:\\Program Files (x86)\\Trend Micro\\Security Agent\\tmuninst.exe",
    "\\Device\\HarddiskVolume*\\Windows\\system32\\svchost.exe", 
    "\\Device\\HarddiskVolume*\\Windows\\CCM\\CcmExec.exe", 
    "\\Device\\HarddiskVolume*\\Windows\\System32\\DeviceEnroller.exe", 
    "\\Device\\HarddiskVolume*\\Program Files (x86)\\Trend Micro\\Security Agent\\tmuninst.exe"
  )

/*
