// Title: defense_evasion_misc_lolbin_connecting_to_the_internet.toml
// Source: detection-rules::rules/windows/defense_evasion_misc_lolbin_connecting_to_the_internet.toml
// Section: EQL Rule
// Rule Name: Network Connection via Signed Binary
// Author: Elastic
// Description:
// Binaries signed with trusted digital certificates can execute on Windows systems protected by digital signature
// validation. Adversaries may use these binaries to 'live off the land' and execute malicious files that could bypass
// application allowlists and signature validation.
// Integration: endpoint, windows, sentinel_one_cloud_funnel
// Language: eql
// UUID: 63e65ec3-43b1-45b0-8f2d-45b34291dc44
// Type: eql

sequence by process.entity_id
  [process where host.os.type == "windows" and (process.name : "expand.exe" or process.name : "extrac32.exe" or
                 process.name : "ieexec.exe" or process.name : "makecab.exe") and
                 event.type == "start"]
  [network where host.os.type == "windows" and (process.name : "expand.exe" or process.name : "extrac32.exe" or
                 process.name : "ieexec.exe" or process.name : "makecab.exe") and
    not cidrmatch(destination.ip,
      "10.0.0.0/8", "127.0.0.0/8", "169.254.0.0/16", "172.16.0.0/12", "192.0.0.0/24", "192.0.0.0/29", "192.0.0.8/32",
      "192.0.0.9/32", "192.0.0.10/32", "192.0.0.170/32", "192.0.0.171/32", "192.0.2.0/24", "192.31.196.0/24",
      "192.52.193.0/24", "192.168.0.0/16", "192.88.99.0/24", "224.0.0.0/4", "100.64.0.0/10", "192.175.48.0/24",
      "198.18.0.0/15", "198.51.100.0/24", "203.0.113.0/24", "240.0.0.0/4", "::1", "FE80::/10", "FF00::/8")]

// Title: defense_evasion_modify_ownership_os_files.toml
// Source: detection-rules::rules/windows/defense_evasion_modify_ownership_os_files.toml
// Section: EQL Rule
// Rule Name: System File Ownership Change
// Author: Elastic
// Description:
// Adversaries may modify file or directory ownership to evade access control lists (ACLs) and access protected files.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 7eb54028-ca72-4eb7-8185-b6864572347db
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  (
   (process.name : "icacls.exe" and process.args : "/reset") or
   (process.name : "takeown.exe" and process.args : "/f") or
   (process.name : "icacls.exe" and process.args : "/grant" and process.args : "Everyone:F")
   ) and
   process.command_line : "*.exe *C:\\Windows\\*"

// Title: defense_evasion_ms_office_suspicious_regmod.toml
// Source: detection-rules::rules/windows/defense_evasion_ms_office_suspicious_regmod.toml
// Section: EQL Rule
// Rule Name: MS Office Macro Security Registry Modifications
// Author: Elastic
// Description:
// Microsoft Office Products offer options for users and developers to control the security settings for running and using
// Macros. Adversaries may abuse these security settings to modify the default behavior of the Office Application to trust
// future macros and/or disable security warnings, which could increase their chances of establishing persistence.
// Integration: windows, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: feeed87c-5e95-4339-aef1-47fd79bcfbe3
// Type: eql

registry where host.os.type == "windows" and event.type == "change" and
    registry.value : ("AccessVBOM", "VbaWarnings") and
    registry.data.strings : ("0x00000001", "1")

/*
    Full registry key paths omitted due to data source variations:
    "HKCU\\S-1-*\\SOFTWARE\\Microsoft\\Office\\*\\Security\\AccessVBOM"
    "HKCU\\S-1-*\\SOFTWARE\\Microsoft\\Office\\*\\Security\\VbaWarnings"
*/

// Title: defense_evasion_msbuild_making_network_connections.toml
// Source: detection-rules::rules/windows/defense_evasion_msbuild_making_network_connections.toml
// Section: EQL Rule
// Rule Name: MsBuild Making Network Connections
// Author: Elastic
// Description:
// Identifies MsBuild.exe making outbound network connections. This may indicate adversarial activity as MsBuild is often
// leveraged by adversaries to execute code and evade detection.
// Integration: endpoint
// Language: eql
// UUID: 0e79980b-4250-4a50-a509-69294c14e84b
// Type: eql

sequence by process.entity_id with maxspan=30s

  /* Look for MSBuild.exe process execution */
  /* The events for this first sequence may be noisy, consider adding exceptions */
  [process where host.os.type == "windows" and event.type == "start" and
    (
      process.pe.original_file_name: "MSBuild.exe" or
      process.name: "MSBuild.exe"
    ) and
    not user.id == "S-1-5-18"]

  /* Followed by a network connection to an external address */
  /* Exclude domains that are known to be benign */
  [network where host.os.type == "windows" and
    event.action: ("connection_attempted", "lookup_requested") and
    not user.id == "S-1-5-18" and
    not cidrmatch(destination.ip, "127.0.0.1", "::1") and
    not dns.question.name : (
      "localhost",
      "dc.services.visualstudio.com",
      "vortex.data.microsoft.com",
      "api.nuget.org")]

// Title: defense_evasion_mshta_beacon.toml
// Source: detection-rules::rules/windows/defense_evasion_mshta_beacon.toml
// Section: EQL Rule
// Rule Name: Mshta Making Network Connections
// Author: Elastic
// Description:
// Identifies Mshta.exe making outbound network connections. This may indicate adversarial activity, as Mshta is often
// leveraged by adversaries to execute malicious scripts and evade detection.
// Integration: endpoint, windows, sentinel_one_cloud_funnel
// Language: eql
// UUID: c2d90150-0133-451c-a783-533e736c12d7
// Type: eql

sequence by process.entity_id with maxspan=10m
  [process where host.os.type == "windows" and event.type == "start" and process.name : "mshta.exe" and
     not process.parent.name : "Microsoft.ConfigurationManagement.exe" and
     not (process.parent.executable : "C:\\Amazon\\Amazon Assistant\\amazonAssistantService.exe" or
          process.parent.executable : "C:\\TeamViewer\\TeamViewer.exe") and
     not process.args : "ADSelfService_Enroll.hta"]
  [network where host.os.type == "windows" and process.name : "mshta.exe"]

// Title: defense_evasion_mshta_susp_child.toml
// Source: detection-rules::rules/windows/defense_evasion_mshta_susp_child.toml
// Section: EQL Rule
// Rule Name: Suspicious Microsoft HTML Application Child Process
// Author: Elastic
// Description:
// Identifies Mshta.exe spawning a suspicious child process. This may indicate adversarial activity, as Mshta is often
// leveraged by adversaries to execute malicious scripts and evade detection.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 48e60a73-08e8-42aa-8f51-4ed92c64dbea
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.parent.name : "mshta.exe" and process.command_line != null and
  (
   process.name : (
       "cmd.exe", "powershell.exe", "certutil.exe", "bitsadmin.exe", "curl.exe", "msiexec.exe",
       "schtasks.exe", "reg.exe", "wscript.exe", "rundll32.exe"
   ) or
   process.executable : ("C:\\Users\\*\\*.exe", "\\Device\\HarddiskVolume*\\Users\\*\\*.exe")
  ) and
  not (process.name : "cmd.exe" and process.command_line : "*\\HP\\HP*HPUDC*") and
  not ?process.parent.command_line : "*\\HP\\*\\HPSolutionsPortal.hta*"

// Title: defense_evasion_msiexec_child_proc_netcon.toml
// Source: detection-rules::rules/windows/defense_evasion_msiexec_child_proc_netcon.toml
// Section: EQL Rule
// Rule Name: MsiExec Service Child Process With Network Connection
// Author: Elastic
// Description:
// Identifies the execution of an MsiExec service child process followed by network or dns lookup activity. Adversaries may
// abuse Windows Installers for initial access and delivery of malware.
// Integration: endpoint, windows, sentinel_one_cloud_funnel
// Language: eql
// UUID: 65432f4a-e716-4cc1-ab11-931c4966da2d
// Type: eql

sequence by process.entity_id with maxspan=1m
 [process where host.os.type == "windows" and event.type : "start" and
  process.parent.name : "msiexec.exe" and process.parent.args : "/v" and
  not process.executable :
        ("?:\\Windows\\System32\\msiexec.exe",
         "?:\\Windows\\sysWOW64\\msiexec.exe",
         "?:\\Windows\\system32\\srtasks.exe",
         "?:\\Windows\\syswow64\\srtasks.exe",
         "?:\\Windows\\sys*\\taskkill.exe",
         "?:\\Program Files\\*.exe",
         "?:\\Program Files (x86)\\*.exe",
         "?:\\Windows\\Installer\\MSI*.tmp",
         "?:\\Windows\\Microsoft.NET\\Framework*\\RegSvcs.exe",
         "C:\\Windows\\System32\\regsvr32.exe",
         "C:\\Windows\\Sys?????\\certutil.exe",
         "C:\\Windows\\System32\\WerFault.exe",
         "C:\\Windows\\System32\\wevtutil.exe",
         "C:\\Windows\\SysWOW64\\WindowsPowerShell\\v1.0\\powershell.exe") and
 not (process.name : ("rundll32.exe", "regsvr32.exe", "powershell.exe", "regasm.exe", "wscript.exe") and process.args : ("?:\\Program Files\\*", "?:\\Program Files (x86)\\*")) and
 not (?process.code_signature.subject_name : ("Bruno Software Inc", "Proton AG", "Axis Communications AB", "Citrix Systems, Inc.", "NSUS Limited", "Action1 Corporation", "Solarwinds Worldwide, LLC") and
      ?process.code_signature.trusted == true) and
 not (?process.pe.original_file_name in ("dxsetup.exe", "MofCompiler.exe", "ShellApp.exe") and
      ?process.code_signature.subject_name : "Microsoft Corporation" and ?process.code_signature.trusted == true) and
 not ?process.hash.sha256 in ("cfaef8c711db04d6c4a4381c66ac21b9e234e57febedb77fedc9316898b214bc",
                              "2f26f37cce780ca76f0dbac0de233f4c8d84c31b3f37380b9d5faacc3ee2d03e",
                              "7d9c691bfbf3beb78919dfd940fa6d325c3437425d5b0371df39aef6accf858d")
 ]
[network where host.os.type == "windows" and process.name != null and
 not dns.question.name : ("core.bdec.microsoft.com", "go.microsoft.com", "ocsp.digicert.com", "localhost", "www.google-analytics.com",
                          "ocsp.verisign.com", "*.symcb.com")]

// Title: defense_evasion_msiexec_remote_payload.toml
// Source: detection-rules::rules/windows/defense_evasion_msiexec_remote_payload.toml
// Section: EQL Rule
// Rule Name: Potential Remote Install via MsiExec
// Author: Elastic
// Description:
// Identifies attempts to install a file from a remote server using MsiExec. Adversaries may abuse Windows Installers
// for initial access and delivery of malware.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: c9847fe9-3bed-4e6b-b319-f9956d6dd02a
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.name : "msiexec.exe" and process.args : ("-i*", "/i*", "-p*", "/p*") and
  process.command_line : ("*http:*", "*https:*") and
  process.args : ("/qn", "-qn", "-q", "/q", "/quiet") and
  process.parent.name : (
    "sihost.exe", "explorer.exe", "cmd.exe", "wscript.exe", "mshta.exe",
    "powershell.exe", "wmiprvse.exe", "pcalua.exe", "forfiles.exe", "conhost.exe"
  ) and

  not process.command_line : (
        "*--set-server=*", "*UPGRADEADD=*" , "*--url=*", "*USESERVERCONFIG=*", "*RCTENTERPRISESERVER=*",
        "*app.ninjarmm.com*", "*zoom.us/client*", "*SUPPORTSERVERSTSURI=*", "*START_URL=*", "*AUTOCONFIG=*",
        "*awscli.amazonaws.com*", "*/i \"C:*", "*/i C:\\*"
  )

// Title: defense_evasion_msxsl_network.toml
// Source: detection-rules::rules/windows/defense_evasion_msxsl_network.toml
// Section: EQL Rule
// Rule Name: Network Connection via MsXsl
// Author: Elastic
// Description:
// Identifies msxsl.exe making a network connection. This may indicate adversarial activity as msxsl.exe is often leveraged
