       "192.0.0.0/29", "192.0.0.8/32", "192.0.0.9/32", "192.0.0.10/32", "192.0.0.170/32", "192.0.0.171/32",
       "192.0.2.0/24", "192.31.196.0/24", "192.52.193.0/24", "192.168.0.0/16", "192.88.99.0/24", "224.0.0.0/4",
       "100.64.0.0/10", "192.175.48.0/24","198.18.0.0/15", "198.51.100.0/24", "203.0.113.0/24", "240.0.0.0/4", "::1",
       "FE80::/10", "FF00::/8")]

// Title: defense_evasion_ntlm_downgrade.toml
// Source: detection-rules::rules/windows/defense_evasion_ntlm_downgrade.toml
// Section: EQL Rule
// Rule Name: Potential NetNTLMv1 Downgrade Attack
// Author: Elastic
// Description:
// Identifies registry modification to force the system to fall back to NTLMv1 for authentication. This modification is
// possible with local administrator privileges and is commonly referred to as a `NetNTLMv1 downgrade attack`.
// Integration: endpoint, m365_defender, sentinel_one_cloud_funnel, windows, crowdstrike
// Language: eql
// UUID: 4d169db7-0323-4157-9ad3-ea5ece9019c9
// Type: eql

registry where host.os.type == "windows" and event.action != "deletion" and
 registry.value == "LmCompatibilityLevel" and registry.data.strings in ("2", "1", "0", "0x00000002", "0x00000001", "0x00000000")

// Title: defense_evasion_obf_args_unicode_modified_letters.toml
// Source: detection-rules::rules/windows/defense_evasion_obf_args_unicode_modified_letters.toml
// Section: EQL Rule
// Rule Name: Command Obfuscation via Unicode Modifier Letters
// Author: Elastic
// Description:
// Identifies the presence of Unicode modifier letters in the process command_line. Adversaries sometimes replace ASCII
// characters with visually similar Unicode modifier letters to evade simple string-based detections.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 37148ae6-c6ec-4fe4-88b1-02f40aed93a9
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  (
    process.name : (
      "reg.exe", "net.exe", "net1.exe", "certutil.exe", "MSHTA.EXE", "msiexec.exe", "bitsadmin.exe", "CertReq.exe",
      "PrintBrm.exe", "MSBuild.exe", "wuauclt.exe", "curl.exe", "wget.exe", "ssh.exe", "Cmd.Exe", "PowerShell.EXE",
      "CONHOST.EXE", "wscript.exe", "cscript.exe", "REGSVR32.EXE", "RUNDLL32.EXE", "procdump.exe", "ntdsutil.exe",
      "diskshadow.exe", "schtasks.exe", "sc.exe", "wmic.exe", "VSSADMIN.EXE", "WBADMIN.EXE", "iCACLS.EXE",
      "sftp.exe", "scp.exe", "esentutl.exe", "InstallUtil.exe", "wevtutil.exe"
    ) or
    ?process.pe.original_file_name in (
      "reg.exe", "net.exe", "net1.exe", "CertUtil.exe", "MSHTA.EXE", "msiexec.exe", "bitsadmin.exe", "CertReq.exe",
      "PrintBrm.exe", "MSBuild.exe", "wuauclt.exe", "curl.exe", "wget.exe", "ssh.exe", "Cmd.Exe", "PowerShell.EXE",
      "CONHOST.EXE", "wscript.exe", "cscript.exe", "REGSVR32.EXE", "RUNDLL32.EXE", "procdump", "ntdsutil.exe",
      "diskshadow.exe", "schtasks.exe", "sc.exe", "wmic.exe", "VSSADMIN.EXE", "WBADMIN.EXE", "iCACLS.EXE",
      "sftp.exe", "scp.exe", "esentutl.exe", "InstallUtil.exe", "wevtutil.exe"
    )
 ) and
 process.command_line regex """.*[ʰ-˿ᴬ-ᶻ]+.*"""

// Title: defense_evasion_parent_process_pid_spoofing.toml
// Source: detection-rules::rules/windows/defense_evasion_parent_process_pid_spoofing.toml
// Section: EQL Rule
// Rule Name: Parent Process PID Spoofing
// Author: Elastic
// Description:
// Identifies parent process spoofing used to thwart detection. Adversaries may spoof the parent process identifier (PPID)
// of a new process to evade process-monitoring defenses or to elevate privileges.
// Integration: endpoint
// Language: eql
// UUID: c88d4bd0-5649-4c52-87ea-9be59dbfbcf2
// Type: eql

/* This rule is compatible with Elastic Endpoint only */

sequence by host.id, user.id with maxspan=3m

 [process where host.os.type == "windows" and event.type == "start" and
  process.Ext.token.integrity_level_name != "system" and
  (
    process.pe.original_file_name : ("winword.exe", "excel.exe", "outlook.exe", "powerpnt.exe", "eqnedt32.exe",
                                     "fltldr.exe", "mspub.exe", "msaccess.exe", "powershell.exe", "pwsh.exe",
                                     "cscript.exe", "wscript.exe", "rundll32.exe", "regsvr32.exe", "msbuild.exe",
                                     "mshta.exe", "wmic.exe", "cmstp.exe", "msxsl.exe") or

    (process.executable : ("?:\\Users\\*.exe",
                           "?:\\ProgramData\\*.exe",
                           "?:\\Windows\\Temp\\*.exe",
                           "?:\\Windows\\Tasks\\*") and
      (process.code_signature.exists == false or process.code_signature.status : "errorBadDigest")) or

    process.executable : "?:\\Windows\\Microsoft.NET\\*.exe"
  ) and

  not process.executable :
             ("?:\\Windows\\System32\\WerFaultSecure.exe",
              "?:\\WINDOWS\\SysWOW64\\WerFaultSecure.exe",
              "?:\\Windows\\System32\\WerFault.exe",
              "?:\\Windows\\SysWOW64\\WerFault.exe")
  ] by process.pid
 [process where host.os.type == "windows" and event.type == "start" and
  process.parent.Ext.real.pid > 0 and

  /* process.parent.Ext.real.pid is only populated if the parent process pid doesn't match */
  not (process.name : "msedge.exe" and process.parent.name : "sihost.exe") and

   not process.executable :
             ("?:\\Windows\\System32\\WerFaultSecure.exe",
              "?:\\WINDOWS\\SysWOW64\\WerFaultSecure.exe",
              "?:\\Windows\\System32\\WerFault.exe",
              "?:\\Windows\\SysWOW64\\WerFault.exe")
 ] by process.parent.Ext.real.pid

// Title: defense_evasion_persistence_account_tokenfilterpolicy.toml
// Source: detection-rules::rules/windows/defense_evasion_persistence_account_tokenfilterpolicy.toml
// Section: EQL Rule
// Rule Name: Local Account TokenFilter Policy Disabled
// Author: Elastic
// Description:
// Identifies registry modification to the LocalAccountTokenFilterPolicy policy. If this value exists (which doesn't by
// default) and is set to 1, then remote connections from all local members of Administrators are granted full
// high-integrity tokens during negotiation.
// Integration: endpoint, windows, sentinel_one_cloud_funnel, m365_defender, crowdstrike
// Language: eql
// UUID: 07b1ef73-1fde-4a49-a34a-5dd40011b076
// Type: eql

