    "🔥"
)

// count how many patterns were detected by calculating the number of 🔥 characters inserted
| eval Esql.script_block_pattern_count = length(Esql.script_block_tmp) - length(replace(Esql.script_block_tmp, "🔥", ""))

// keep the fields relevant to the query, although this is not needed as the alert is populated using _id
| keep
    Esql.script_block_pattern_count,
    Esql.script_block_length,
    Esql.script_block_tmp,
    powershell.file.*,
    file.path,
    file.directory,
    powershell.sequence,
    powershell.total,
    _id,
    _version,
    _index,
    host.name,
    host.id,
    agent.id,
    user.id

// Filter for scripts that match the pattern at least five times
| where Esql.script_block_pattern_count >= 5

// Exclude Noisy Patterns

// Icinga Framework
| where not file.directory == "C:\\Program Files\\WindowsPowerShell\\Modules\\icinga-powershell-framework\\cache"
  // ESQL requires this condition, otherwise it only returns matches where file.directory exists.
  or file.directory IS NULL

| where not (powershell.file.script_block_text LIKE "*GitBranchStatus*" AND 
    powershell.file.script_block_text LIKE "*$s.BranchBehindStatusSymbol.Text*")
| where not
    // https://wtfbins.wtf/17
    (
        (powershell.file.script_block_text like "*sentinelbreakpoints*" or
         powershell.file.script_block_text like "*:::::\\\\windows\\\\sentinel*")
        and
        (powershell.file.script_block_text like "*$local:Bypassed*" or
         powershell.file.script_block_text like "*origPSExecutionPolicyPreference*")
    )

// Title: defense_evasion_posh_obfuscation_whitespace_special_proportion.toml
// Source: detection-rules::rules/windows/defense_evasion_posh_obfuscation_whitespace_special_proportion.toml
// Section: EQL Rule
// Rule Name: Potential PowerShell Obfuscation via Special Character Overuse
// Author: Elastic
// Description:
// Detects PowerShell scripts dominated by whitespace and special characters with low symbol diversity, a profile often
// produced by formatting or encoding obfuscation. Attackers use symbol-heavy encoding or formatting (for example,
// SecureString-style blobs or character-level transforms) to hide payloads and evade static analysis and AMSI.
// Integration: windows
// Language: esql
// UUID: 6ddb6c33-00ce-4acd-832a-24b251512023
// Type: esql

from logs-windows.powershell_operational* metadata _id, _version, _index
| where event.code == "4104"

// filter for scripts with low unique symbol counts, which can indicate special character obfuscation
| where powershell.file.script_block_unique_symbols < 50

// replace repeated spaces used for formatting after a new line with a single space to reduce FPs
| eval Esql.script_block_tmp = replace(powershell.file.script_block_text, """\n\s+""", "\n ")

// Look for scripts with more than 1000 chars
| eval Esql.script_block_length = length(Esql.script_block_tmp)
| where Esql.script_block_length > 1000

// replace the patterns we are looking for with the 🔥 emoji to enable counting them
// The emoji is used because it's unlikely to appear in scripts and has a consistent character length of 1
| eval Esql.script_block_tmp = replace(
    Esql.script_block_tmp,
    """[\s\$\{\}\+\@\=\(\)\^\\\"~\[\]\?\./%#\`\'\;\-\!\*]""",
    "🔥"
)

// count how many patterns were detected by calculating the number of 🔥 characters inserted
| eval Esql.script_block_count = Esql.script_block_length - length(replace(Esql.script_block_tmp, "🔥", ""))

// Calculate the ratio of special characters to total length
| eval Esql.script_block_ratio = Esql.script_block_count::double / Esql.script_block_length::double

// keep the fields relevant to the query, although this is not needed as the alert is populated using _id
| keep
    Esql.script_block_count,
    Esql.script_block_length,
    Esql.script_block_ratio,
    Esql.script_block_tmp,
    powershell.file.*,
    file.path,
    powershell.sequence,
    powershell.total,
    _id,
    _version,
    _index,
    host.name,
    host.id,
    agent.id,
    user.id

// Filter for scripts with high whitespace and special character ratio
| where Esql.script_block_ratio >= 0.75

// Title: defense_evasion_powershell_windows_firewall_disabled.toml
// Source: detection-rules::rules/windows/defense_evasion_powershell_windows_firewall_disabled.toml
// Section: EQL Rule
// Rule Name: Windows Firewall Disabled via PowerShell
// Author: Austin Songer
// Description:
// Identifies when the Windows Firewall is disabled using PowerShell cmdlets, which can help attackers evade network
// constraints, like internet and network lateral communication restrictions.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: f63c8e3c-d396-404f-b2ea-0379d3942d73
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  (
    process.name : ("powershell.exe", "pwsh.exe", "powershell_ise.exe") or
    ?process.pe.original_file_name in ("PowerShell.EXE", "pwsh.dll", "powershell_ise.EXE")
  ) and
  process.args : "*Set-NetFirewallProfile*" and
  process.args : "*-Enabled*" and process.args : "*False*" and
  process.args : ("*-All*", "*Public*", "*Domain*", "*Private*")

// Title: defense_evasion_proxy_execution_via_msdt.toml
// Source: detection-rules::rules/windows/defense_evasion_proxy_execution_via_msdt.toml
// Section: EQL Rule
// Rule Name: Suspicious Microsoft Diagnostics Wizard Execution
// Author: Elastic
// Description:
// Identifies potential abuse of the Microsoft Diagnostics Troubleshooting Wizard (MSDT) to proxy malicious command or
// binary execution via malicious process arguments.
// Integration: endpoint, windows, m365_defender, crowdstrike, sentinel_one_cloud_funnel
// Language: eql
// UUID: 2c3c29a4-f170-42f8-a3d8-2ceebc18eb6a
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  (?process.pe.original_file_name == "msdt.exe" or process.name : "msdt.exe") and
  (
    process.args : ("IT_RebrowseForFile=*", "*FromBase64*", "*/../../../*", "IT_BrowseForFile=*") or
    (
      process.args : ("-af", "/af") and process.args : "/skip" and
      process.parent.name : ("explorer.exe", "cmd.exe", "powershell.exe", "cscript.exe", "wscript.exe", "mshta.exe", "rundll32.exe", "regsvr32.exe") and
      process.args : ("?:\\WINDOWS\\diagnostics\\index\\PCWDiagnostic.xml", "PCWDiagnostic.xml", "?:\\Users\\Public\\*", "?:\\Windows\\Temp\\*")
    ) or

    (process.pe.original_file_name == "msdt.exe" and not process.name : "msdt.exe" and process.name != null) or

    (
      ?process.pe.original_file_name == "msdt.exe" and
      not process.executable : (
        "?:\\Windows\\system32\\msdt.exe",
        "?:\\Windows\\SysWOW64\\msdt.exe",
        /* Crowdstrike specific exclusion as it uses NT Object paths */
        "\\Device\\HarddiskVolume*\\Windows\\system32\\msdt.exe",
        "\\Device\\HarddiskVolume*\\Windows\\SysWOW64\\msdt.exe"
      )
    )
  )

// Title: defense_evasion_reg_disable_enableglobalqueryblocklist.toml
// Source: detection-rules::rules/windows/defense_evasion_reg_disable_enableglobalqueryblocklist.toml
// Section: EQL Rule
// Rule Name: DNS Global Query Block List Modified or Disabled
// Author: Elastic
// Description:
// Identifies changes to the DNS Global Query Block List (GQBL), a security feature that prevents the resolution of certain
// DNS names often exploited in attacks like WPAD spoofing. Attackers with certain privileges, such as DNSAdmins, can
// modify or disable the GQBL, allowing exploitation of hosts running WPAD with default settings for privilege escalation
// and lateral movement.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 57bfa0a9-37c0-44d6-b724-54bf16787492
// Type: eql

registry where host.os.type == "windows" and event.type == "change" and registry.data.strings != null and
(
  (registry.value : "EnableGlobalQueryBlockList" and registry.data.strings : ("0", "0x00000000")) or
  (registry.value : "GlobalQueryBlockList" and not registry.data.strings : "wpad")
)

// Title: defense_evasion_regmod_remotemonologue.toml
// Source: detection-rules::rules/windows/defense_evasion_regmod_remotemonologue.toml
// Section: EQL Rule
// Rule Name: Potential RemoteMonologue Attack
// Author: Elastic
// Description:
// Identifies attempt to perform session hijack via COM object registry modification by setting the RunAs value to
// Interactive User.
// Integration: endpoint, m365_defender, sentinel_one_cloud_funnel, windows
// Language: eql
// UUID: c18975f5-676c-4091-b626-81e8938aa2ee
// Type: eql

registry where host.os.type == "windows" and event.action != "deletion" and
  registry.value == "RunAs" and registry.data.strings : "Interactive User" and

  not 
  (
    (
      process.executable : (
        "C:\\ProgramData\\Microsoft\\Windows Defender\\Platform\\4.*\\MsMpEng.exe",
        "C:\\Program Files\\Windows Defender\\MsMpEng.exe"
      ) and
      registry.path : "*\\SOFTWARE\\Classes\\AppID\\{1111A26D-EF95-4A45-9F55-21E52ADF9887}\\RunAs"
    ) or
    (
      process.executable : (
        "C:\\Program Files\\TeamViewer\\TeamViewer.exe",
        "C:\\Program Files (x86)\\TeamViewer\\TeamViewer.exe"
      ) and
      registry.path : "*\\SOFTWARE\\Classes\\AppID\\{850A928D-5456-4865-BBE5-42635F1EBCA1}\\RunAs"
    ) or
    (
      process.executable : "C:\\Windows\\System32\\svchost.exe" and
      registry.path : "*\\S-1-*Classes\\AppID\\{D3E34B21-9D75-101A-8C3D-00AA001A1652}\\RunAs"
    ) or
    (
      process.executable : "C:\\Windows\\System32\\SecurityHealthService.exe" and
      registry.path : (
        "*\\SOFTWARE\\Classes\\AppID\\{1D278EEF-5C38-4F2A-8C7D-D5C13B662567}\\RunAs",
        "*\\SOFTWARE\\Classes\\AppID\\{7E55A26D-EF95-4A45-9F55-21E52ADF9878}\\RunAs"
      )
    ) or
    (
      process.executable : "C:\\Windows\\System32\\SecurityHealthService.exe" and
      registry.path : (
        "*\\SOFTWARE\\Classes\\AppID\\{1D278EEF-5C38-4F2A-8C7D-D5C13B662567}\\RunAs",
        "*\\SOFTWARE\\Classes\\AppID\\{7E55A26D-EF95-4A45-9F55-21E52ADF9878}\\RunAs"
      )
    ) or
    registry.path : (
      "HKLM\\SOFTWARE\\Microsoft\\Office\\ClickToRun\\VREGISTRY_*",
      "\\REGISTRY\\MACHINE\\SOFTWARE\\Microsoft\\Office\\ClickToRun\\VREGISTRY_*"
    ) or
    (process.executable : "C:\\windows\\System32\\msiexec.exe" and ?user.id : "S-1-5-18")
  )

// Title: defense_evasion_right_to_left_override.toml
// Source: detection-rules::rules/windows/defense_evasion_right_to_left_override.toml
// Section: EQL Rule
// Rule Name: File with Right-to-Left Override Character (RTLO) Created/Executed
// Author: Elastic
// Description:
// Identifies the creation or execution of files or processes with names containing the Right-to-Left Override (RTLO)
// character, which can be used to disguise the file extension and trick users into executing malicious files.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel
// Language: eql
// UUID: 7e763fd1-228a-4d43-be88-3ffc14cd7de1
// Type: eql

any where host.os.type == "windows" and event.category in ("file", "process") and 
  (
    (event.type == "creation" and file.path : "*\u{202E}*") or 
    (event.type == "start" and process.name : "*\u{202E}*")
  )

// Title: defense_evasion_root_dir_ads_creation.toml
// Source: detection-rules::rules/windows/defense_evasion_root_dir_ads_creation.toml
// Section: EQL Rule
// Rule Name: Alternate Data Stream Creation/Execution at Volume Root Directory
// Author: Elastic
// Description:
// Identifies the creation of an Alternate Data Stream (ADS) at a volume root directory, which can indicate the attempt to
// hide tools and malware, as ADSs created in this directory are not displayed by system utilities.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel
// Language: eql
// UUID: ff6cf8b9-b76c-4cc1-ac1b-4935164d1029
// Type: eql

any where host.os.type == "windows" and event.category in ("file", "process") and
  (
    (event.type == "creation" and file.path regex~ """[A-Z]:\\:.+""") or
    (event.type == "start" and process.executable regex~ """[A-Z]:\\:.+""")
  )

// Title: defense_evasion_run_virt_windowssandbox.toml
// Source: detection-rules::rules/windows/defense_evasion_run_virt_windowssandbox.toml
// Section: EQL Rule
// Rule Name: Windows Sandbox with Sensitive Configuration
// Author: Elastic
// Description:
// Identifies Windows sanfbox processes indicating the start of a new container with sensitive configurations like write
// access to the host file system, network connection and automatic execution via logon command. Malware may abuse the
// sandbox feature to evade detection.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 56d9cf6c-46ea-4019-9c7f-b1fdb855fee3
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.name : ("wsb.exe", "WindowsSandboxClient.exe") and
  process.command_line : ("*<Networking>Enable</Networking>*",
                          "*<HostFolder>C:\\*<ReadOnly>false*",
                          "*<LogonCommand>*",
                          "*<NetworkingEnabled>true*")

// Title: defense_evasion_rundll32_no_arguments.toml
// Source: detection-rules::rules/windows/defense_evasion_rundll32_no_arguments.toml
// Section: EQL Rule
// Rule Name: Unusual Child Processes of RunDLL32
// Author: Elastic
// Description:
// Identifies a no-argument or malformed Rundll32 launch followed by child process execution. This unusual sequence can
// indicate Rundll32 abuse for proxy execution or payload handoff.
// Integration: endpoint, windows, crowdstrike
// Language: eql
// UUID: f036953a-4615-4707-a1ca-dc53bf69dcd5
// Type: eql

sequence with maxspan=1h
  [process where host.os.type == "windows" and event.type == "start" and
     (process.name : "rundll32.exe" or process.pe.original_file_name == "RUNDLL32.EXE") and
      (process.args_count == 1 and
        /* Excludes bug where a missing closing quote sets args_count to 1 despite extra args */
        not process.command_line regex~ """\".*\.exe[^\"].*""")
  ] by process.entity_id
  [process where host.os.type == "windows" and event.type == "start" and process.parent.name : "rundll32.exe"
  ] by process.parent.entity_id

// Title: defense_evasion_sc_sdset.toml
// Source: detection-rules::rules/windows/defense_evasion_sc_sdset.toml
// Section: EQL Rule
// Rule Name: Service DACL Modification via sc.exe
// Author: Elastic
// Description:
// Identifies DACL modifications to deny access to a service, making it unstoppable, or hide it from system and users.
// Integration: endpoint, windows, sentinel_one_cloud_funnel, m365_defender, crowdstrike
// Language: eql
// UUID: 5188c68e-d3de-4e96-994d-9e242269446f
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  (process.name : "sc.exe" or ?process.pe.original_file_name : "sc.exe") and
  process.args : "sdset" and process.args : "*D;*" and
  process.args : ("*;IU*", "*;SU*", "*;BA*", "*;SY*", "*;WD*")

// Title: defense_evasion_sccm_scnotification_dll.toml
// Source: detection-rules::rules/windows/defense_evasion_sccm_scnotification_dll.toml
// Section: EQL Rule
// Rule Name: Potential Windows Session Hijacking via CcmExec
// Author: Elastic
// Description:
// This detection rule identifies when 'SCNotification.exe' loads an untrusted DLL, which is a potential indicator of an
// attacker attempt to hijack/impersonate a Windows user session.
// Integration: endpoint
// Language: eql
// UUID: e7357fec-6e9c-41b9-b93d-6e4fc40c7d47
// Type: eql

library where host.os.type == "windows" and process.name : "SCNotification.exe" and
  (dll.Ext.relative_file_creation_time < 86400 or dll.Ext.relative_file_name_modify_time <= 500) and dll.code_signature.status != "trusted"

// Title: defense_evasion_scheduledjobs_at_protocol_enabled.toml
// Source: detection-rules::rules/windows/defense_evasion_scheduledjobs_at_protocol_enabled.toml
// Section: EQL Rule
// Rule Name: Scheduled Tasks AT Command Enabled
// Author: Elastic
// Description:
// Identifies attempts to enable the Windows scheduled tasks AT command via the registry. Attackers may use this method to
// move laterally or persist locally. The AT command has been deprecated since Windows 8 and Windows Server 2012, but still
// exists for backwards compatibility.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 9aa0e1f6-52ce-42e1-abb3-09657cee2698
// Type: eql

registry where host.os.type == "windows" and event.type == "change" and
  registry.value : "EnableAt" and
  registry.data.strings : ("1", "0x00000001")

// Title: defense_evasion_script_via_html_app.toml
// Source: detection-rules::rules/windows/defense_evasion_script_via_html_app.toml
// Section: EQL Rule
// Rule Name: Script Execution via Microsoft HTML Application
// Author: Elastic
// Description:
// Identifies the execution of scripts via HTML applications using Windows utilities rundll32.exe or mshta.exe. Adversaries
// may bypass process and/or signature-based defenses by proxying execution of malicious content with signed binaries.
// Integration: endpoint, windows, system, sentinel_one_cloud_funnel, m365_defender, crowdstrike
// Language: eql
// UUID: 181f6b23-3799-445e-9589-0018328a9e46
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
 process.name : ("rundll32.exe", "mshta.exe") and
  (
     (process.command_line :
        (
        "*script*eval(*",
         "*script*GetObject*",
         "*.regread(*",
         "*WScript.Shell*",
         "*.run(*",
         "*).Exec()*",
         "*mshta*http*",
         "*mshtml*RunHTMLApplication*",
         "*mshtml*,#135*",
         "*StrReverse*",
         "*.RegWrite*",
         /* Issue #379 */
         "*window.close(*",
         "* Chr(*"
         )
     and not ?process.parent.executable :
                  ("?:\\Program Files (x86)\\Citrix\\System32\\wfshell.exe",
                   "?:\\Program Files (x86)\\Microsoft Office\\Office*\\MSACCESS.EXE",
                   "?:\\Program Files\\Quokka.Works GTInstaller\\GTInstaller.exe")
     ) or

    (process.name : "mshta.exe" and
     not process.command_line : ("*.hta*", "*.htm*", "-Embedding") and ?process.args_count >=2) or

     /* Execution of HTA file downloaded from the internet */
     (process.name : "mshta.exe" and process.command_line : "*\\Users\\*\\Downloads\\*.hta*") or

     /* Execution of HTA file from archive */
     (process.name : "mshta.exe" and
      process.args : ("?:\\Users\\*\\Temp\\7z*", "?:\\Users\\*\\Temp\\Rar$*", "?:\\Users\\*\\Temp\\Temp?_*", "?:\\Users\\*\\Temp\\BNZ.*"))
   )

// Title: defense_evasion_sdelete_like_filename_rename.toml
// Source: detection-rules::rules/windows/defense_evasion_sdelete_like_filename_rename.toml
// Section: EQL Rule
// Rule Name: Potential Secure File Deletion via SDelete Utility
// Author: Elastic
// Description:
// Detects file name patterns generated by the use of Sysinternals SDelete utility to securely delete a file via multiple
// file overwrite and rename operations.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 5aee924b-6ceb-4633-980e-1bde8cdb40c5
// Type: eql

file where host.os.type == "windows" and event.type == "change" and file.name : "*AAA.AAA"

// Title: defense_evasion_sip_provider_mod.toml
// Source: detection-rules::rules/windows/defense_evasion_sip_provider_mod.toml
// Section: EQL Rule
// Rule Name: SIP Provider Modification
// Author: Elastic
// Description:
// Identifies modifications to the registered Subject Interface Package (SIP) providers. SIP providers are used by the
// Windows cryptographic system to validate file signatures on the system. This may be an attempt to bypass signature
// validation checks or inject code into critical processes.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: f2c7b914-eda3-40c2-96ac-d23ef91776ca
// Type: eql

registry where host.os.type == "windows" and event.type == "change" and registry.value : ("Dll", "$Dll") and
  registry.path: (
    "*\\SOFTWARE\\Microsoft\\Cryptography\\OID\\EncodingType 0\\CryptSIPDllPutSignedDataMsg\\{*}\\Dll",
    "*\\SOFTWARE\\WOW6432Node\\Microsoft\\Cryptography\\OID\\EncodingType 0\\CryptSIPDllPutSignedDataMsg\\{*}\\Dll",
    "*\\SOFTWARE\\Microsoft\\Cryptography\\Providers\\Trust\\FinalPolicy\\{*}\\$Dll",
    "*\\SOFTWARE\\WOW6432Node\\Microsoft\\Cryptography\\Providers\\Trust\\FinalPolicy\\{*}\\$Dll"
    ) and
  registry.data.strings:"*.dll" and
  not (process.name : "msiexec.exe" and registry.data.strings : "mso.dll") and
  not (process.name : "regsvr32.exe" and registry.data.strings == "WINTRUST.DLL")

// Title: defense_evasion_solarwinds_backdoor_service_disabled_via_registry.toml
// Source: detection-rules::rules/windows/defense_evasion_solarwinds_backdoor_service_disabled_via_registry.toml
// Section: EQL Rule
// Rule Name: SolarWinds Process Disabling Services via Registry
// Author: Elastic
// Description:
// Identifies a SolarWinds binary modifying the start type of a service to be disabled. An adversary may abuse this
// technique to manipulate relevant security services.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: b9960fef-82c6-4816-befa-44745030e917
// Type: eql

registry where host.os.type == "windows" and event.type == "change" and registry.value : "Start" and
  process.name : (
      "SolarWinds.BusinessLayerHost*.exe",
      "ConfigurationWizard*.exe",
      "NetflowDatabaseMaintenance*.exe",
      "NetFlowService*.exe",
      "SolarWinds.Administration*.exe",
      "SolarWinds.Collector.Service*.exe",
      "SolarwindsDiagnostics*.exe"
  ) and
  registry.path : "*\\SYSTEM\\*ControlSet*\\Services\\*\\Start" and
  registry.data.strings : ("4", "0x00000004")

// Title: defense_evasion_suspicious_certutil_commands.toml
// Source: detection-rules::rules/windows/defense_evasion_suspicious_certutil_commands.toml
// Section: EQL Rule
// Rule Name: Suspicious CertUtil Commands
// Author: Elastic, Austin Songer
// Description:
// Identifies suspicious commands being used with certutil.exe. CertUtil is a native Windows component which is part of
// Certificate Services. CertUtil is often abused by attackers to live off the land for stealthier command and control or
// data exfiltration.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: fd70c98a-c410-42dc-a2e3-761c71848acf
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  (process.name : "certutil.exe" or ?process.pe.original_file_name == "CertUtil.exe") and
  process.args : ("?decode", "?encode", "?urlcache", "?verifyctl", "?encodehex", "?decodehex", "?exportPFX")

// Title: defense_evasion_suspicious_execution_from_mounted_device.toml
// Source: detection-rules::rules/windows/defense_evasion_suspicious_execution_from_mounted_device.toml
// Section: EQL Rule
// Rule Name: Suspicious Execution from a Mounted Device
// Author: Elastic
// Description:
// Identifies when a script interpreter or signed binary is launched via a non-standard working directory. An attacker may
// use this technique to evade defenses.
// Integration: endpoint, windows
// Language: eql
// UUID: 8a1d4831-3ce6-4859-9891-28931fa6101d
// Type: eql

process where host.os.type == "windows" and event.type == "start" and process.executable : "C:\\*" and
  (
    process.working_directory : ("D:\\*", "E:\\*", "F:\\*") or
    ?process.Ext.device.product_id : ("Virtual DVD-ROM", "Virtual Disk")
  ) and
  process.parent.name : "explorer.exe" and
  process.name : (
    "rundll32.exe", "mshta.exe", "powershell.exe", "pwsh.exe", "cmd.exe", "regsvr32.exe", "cscript.exe",
    "wscript.exe", "certutil.exe", "bitsadmin.exe", "msiexec.exe", "wmic.exe", "schtasks.exe", "msbuild.exe"
  )

// Title: defense_evasion_suspicious_managedcode_host_process.toml
// Source: detection-rules::rules/windows/defense_evasion_suspicious_managedcode_host_process.toml
// Section: EQL Rule
// Rule Name: Suspicious Managed Code Hosting Process
// Author: Elastic
// Description:
// Identifies a suspicious managed code hosting process which could indicate code injection or other form of suspicious
// code execution.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: acf738b5-b5b2-4acc-bad9-1e18ee234f40
// Type: eql

file where host.os.type == "windows" and event.type != "deletion" and
  file.name : ("wscript.exe.log",
               "cscript.exe.log",
               "mshta.exe.log",
               "wmic.exe.log",
               "svchost.exe.log",
               "dllhost.exe.log",
               "cmstp.exe.log",
               "regsvr32.exe.log")

// Title: defense_evasion_suspicious_process_access_direct_syscall.toml
// Source: detection-rules::rules/windows/defense_evasion_suspicious_process_access_direct_syscall.toml
// Section: EQL Rule
// Rule Name: Suspicious Process Access via Direct System Call
// Author: Elastic
// Description:
// Identifies suspicious process access events from an unknown memory region. Endpoint security solutions usually hook
// userland Windows APIs in order to decide if the code that is being executed is malicious or not. It's possible to bypass
// hooked functions by writing malicious functions that call syscalls directly.
// Integration: windows
// Language: eql
// UUID: 2dd480be-1263-4d9c-8672-172928f6789a
// Type: eql

process where host.os.type == "windows" and event.code == "10" and
 length(winlog.event_data.CallTrace) > 0 and

 /* Sysmon CallTrace starting with unknown memory module instead of ntdll which host Windows NT Syscalls */
 not winlog.event_data.CallTrace :
            ("?:\\WINDOWS\\SYSTEM32\\ntdll.dll*",
             "?:\\WINDOWS\\SysWOW64\\ntdll.dll*",
             "?:\\Windows\\System32\\sysfer.dll*",
             "?:\\Windows\\System32\\wow64cpu.dll*",
             "?:\\WINDOWS\\System32\\wow64win.dll*",
             "?:\\Windows\\System32\\win32u.dll*",
             "?:\\ProgramData\\Symantec\\Symantec Endpoint Protection\\*\\sysfer.dll*") and

 not winlog.event_data.TargetImage :
            ("?:\\Program Files (x86)\\Malwarebytes Anti-Exploit\\mbae-svc.exe",
             "?:\\Program Files\\Cisco\\AMP\\*\\sfc.exe",
             "?:\\Program Files (x86)\\Microsoft\\EdgeWebView\\Application\\*\\msedgewebview2.exe",
             "?:\\Program Files\\Adobe\\Acrobat DC\\Acrobat\\*\\AcroCEF.exe") and

 not (process.executable : ("?:\\Program Files\\Adobe\\Acrobat DC\\Acrobat\\Acrobat.exe",
                            "?:\\Program Files (x86)\\World of Warcraft\\_classic_\\WowClassic.exe") and
      not winlog.event_data.TargetImage : "?:\\WINDOWS\\system32\\lsass.exe")

// Title: defense_evasion_suspicious_process_creation_calltrace.toml
// Source: detection-rules::rules/windows/defense_evasion_suspicious_process_creation_calltrace.toml
// Section: EQL Rule
// Rule Name: Suspicious Process Creation CallTrace
// Author: Elastic
// Description:
// Identifies when a process is created and immediately accessed from an unknown memory code region and by the same parent
// process. This may indicate a code injection attempt.
// Integration: windows
// Language: eql
// UUID: 3ed032b2-45d8-4406-bc79-7ad1eabb2c72
// Type: eql

sequence by host.id with maxspan=1m
  [process where host.os.type == "windows" and event.code == "1" and
   /* sysmon process creation */
   process.parent.name : ("winword.exe", "excel.exe", "outlook.exe", "powerpnt.exe", "eqnedt32.exe", "fltldr.exe",
                          "mspub.exe", "msaccess.exe","cscript.exe", "wscript.exe", "rundll32.exe", "regsvr32.exe",
                          "mshta.exe", "wmic.exe", "cmstp.exe", "msxsl.exe") and

   /* noisy FP patterns */
   not (process.parent.name : "EXCEL.EXE" and process.executable : "?:\\Program Files\\Microsoft Office\\root\\Office*\\ADDINS\\*.exe") and
   not (process.executable : "?:\\Windows\\splwow64.exe" and process.args in ("8192", "12288") and process.parent.name : ("winword.exe", "excel.exe", "outlook.exe", "powerpnt.exe")) and
   not (process.parent.name : "rundll32.exe" and process.parent.args : ("?:\\WINDOWS\\Installer\\MSI*.tmp,zzzzInvokeManagedCustomActionOutOfProc", "--no-sandbox")) and
   not (process.executable :
            ("?:\\Program Files (x86)\\Microsoft\\EdgeWebView\\Application\\*\\msedgewebview2.exe",
             "?:\\Program Files\\Adobe\\Acrobat DC\\Acrobat\\Acrobat.exe",
             "?:\\Windows\\SysWOW64\\DWWIN.EXE") and
        process.parent.name : ("winword.exe", "excel.exe", "outlook.exe", "powerpnt.exe")) and
   not (process.parent.name : "regsvr32.exe" and process.parent.args : ("?:\\Program Files\\*", "?:\\Program Files (x86)\\*"))
   ] by process.parent.entity_id, process.entity_id
  [process where host.os.type == "windows" and event.code == "10" and
   /* Sysmon process access event from unknown module */
   winlog.event_data.CallTrace : "*UNKNOWN*"] by process.entity_id, winlog.event_data.TargetProcessGUID

// Title: defense_evasion_suspicious_scrobj_load.toml
// Source: detection-rules::rules/windows/defense_evasion_suspicious_scrobj_load.toml
// Section: EQL Rule
// Rule Name: Suspicious Script Object Execution
// Author: Elastic
// Description:
// Identifies scrobj.dll loaded into unusual Microsoft processes. This usually means a malicious scriptlet is being
// executed in the target process.
// Integration: endpoint, windows
// Language: eql
// UUID: 4ed678a9-3a4f-41fb-9fea-f85a6e0a0dff
// Type: eql

any where host.os.type == "windows" and
 (event.category : ("library", "driver") or (event.category == "process" and event.action : "Image loaded*")) and
 (?dll.name : "scrobj.dll" or ?file.name : "scrobj.dll") and
 process.executable : ("?:\\Windows\\System32\\*.exe", "?:\\Windows\\SysWOW64\\*.exe") and
 not process.executable : (
       "?:\\Windows\\System32\\cscript.exe",
       "?:\\Windows\\SysWOW64\\cscript.exe",
       "?:\\Windows\\system32\\msiexec.exe",
       "?:\\Windows\\SysWOW64\\msiexec.exe",
       "?:\\Windows\\System32\\smartscreen.exe",
       "?:\\Windows\\system32\\taskhostw.exe",
       "?:\\windows\\system32\\inetsrv\\w3wp.exe",
       "?:\\windows\\SysWOW64\\inetsrv\\w3wp.exe",
       "?:\\Windows\\system32\\wscript.exe",
       "?:\\Windows\\SysWOW64\\wscript.exe",
       "?:\\Windows\\System32\\mshta.exe",
       "?:\\Windows\\system32\\mobsync.exe",
       "?:\\Windows\\SysWOW64\\mobsync.exe",
       "?:\\Windows\\System32\\cmd.exe",
       "?:\\Windows\\SysWOW64\\cmd.exe",
       "?:\\Windows\\System32\\OpenWith.exe",
       "?:\\Windows\\System32\\wbem\\WMIADAP.exe",
       "?:\\Windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe")

// Title: defense_evasion_suspicious_short_program_name.toml
// Source: detection-rules::rules/windows/defense_evasion_suspicious_short_program_name.toml
// Section: EQL Rule
// Rule Name: Renamed Utility Executed with Short Program Name
// Author: Elastic
// Description:
// Identifies the execution of a process with a single character process name, differing from the original file name. This
// is often done by adversaries while staging, executing temporary utilities, or trying to bypass security detections based
// on the process name.
// Integration: endpoint, windows, m365_defender, crowdstrike
// Language: eql
// UUID: 17c7f6a5-5bc9-4e1f-92bf-13632d24384d
// Type: eql

process where host.os.type == "windows" and event.type == "start" and 
 process.name regex~ """[a-z0-9]\.exe""" and process.pe.original_file_name != null

// Title: defense_evasion_suspicious_wmi_script.toml
// Source: detection-rules::rules/windows/defense_evasion_suspicious_wmi_script.toml
// Section: EQL Rule
// Rule Name: Suspicious WMIC XSL Script Execution
// Author: Elastic
// Description:
// Identifies WMIC allowlist bypass techniques by alerting on suspicious execution of scripts. When WMIC loads scripting
// libraries it may be indicative of an allowlist bypass.
// Integration: endpoint, windows
// Language: eql
// UUID: 7f370d54-c0eb-4270-ac5a-9a6020585dc6
// Type: eql

sequence by process.entity_id with maxspan = 2m
[process where host.os.type == "windows" and event.type == "start" and
   (process.name : "WMIC.exe" or process.pe.original_file_name : "wmic.exe") and
   process.args : ("format*:*", "/format*:*", "*-format*:*") and
   not process.command_line : ("* /format:table *", "* /format:table")]
[any where host.os.type == "windows" and (event.category == "library" or (event.category == "process" and event.action : "Image loaded*")) and
 (?dll.name : ("jscript.dll", "vbscript.dll") or file.name : ("jscript.dll", "vbscript.dll"))]

// Title: defense_evasion_suspicious_zoom_child_process.toml
// Source: detection-rules::rules/windows/defense_evasion_suspicious_zoom_child_process.toml
// Section: EQL Rule
// Rule Name: Suspicious Zoom Child Process
// Author: Elastic
// Description:
// A suspicious Zoom child process was detected, which may indicate an attempt to run unnoticed. Verify process details
// such as command line, network connections, file writes and associated file signature details as well.
// Integration: endpoint, windows, sentinel_one_cloud_funnel, m365_defender, system, crowdstrike
// Language: eql
// UUID: 97aba1ef-6034-4bd3-8c1a-1e0996b27afa
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
 process.parent.name : "Zoom.exe" and process.name : ("cmd.exe", "powershell.exe", "pwsh.exe", "powershell_ise.exe")

// Title: defense_evasion_system_critical_proc_abnormal_file_activity.toml
// Source: detection-rules::rules/windows/defense_evasion_system_critical_proc_abnormal_file_activity.toml
// Section: EQL Rule
// Rule Name: Unusual Executable File Creation by a System Critical Process
// Author: Elastic
// Description:
// Identifies an unexpected executable file being created or modified by a Windows system critical process, which may
// indicate activity related to remote code execution or other forms of exploitation.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: e94262f2-c1e9-4d3f-a907-aeab16712e1a
// Type: eql

file where host.os.type == "windows" and event.type != "deletion" and
  file.extension : ("exe", "dll") and
  process.name : ("smss.exe",
                  "autochk.exe",
                  "csrss.exe",
                  "wininit.exe",
                  "services.exe",
                  "lsass.exe",
                  "winlogon.exe",
                  "userinit.exe",
                  "LogonUI.exe") and
  not (
    process.name : "smss.exe" and
    file.path : (
      "?:\\Windows\\System32\\wpbbin.exe",
      "\\Device\\HarddiskVolume*\\Windows\\System32\\wpbbin.exe"
    )
  ) and
  not (
    process.name : "lsass.exe" and
    file.path : (
      "?:\\Windows\\System32\\eac_usermode_*.dll",
      "\\Device\\HarddiskVolume*\\Windows\\System32\\eac_usermode_*.dll"
    )
  )

// Title: defense_evasion_timestomp_sysmon.toml
// Source: detection-rules::rules/windows/defense_evasion_timestomp_sysmon.toml
// Section: EQL Rule
// Rule Name: Potential Timestomp in Executable Files
// Author: Elastic
// Description:
// Identifies the modification of a file creation time for executable files in sensitive system directories. Adversaries
// may modify file time attributes to blend malicious executables with legitimate system files. Timestomping is a technique
// that modifies the timestamps of a file often to mimic files that are in trusted directories.
// Integration: windows
// Language: eql
// UUID: 166727ab-6768-4e26-b80c-948b228ffc06
// Type: eql

file where host.os.type == "windows" and
  event.provider == "Microsoft-Windows-Sysmon" and event.code == "2" and
  file.extension : (
    "exe", "dll", "sys", "msi", "scr", "pif", "lnk"
  ) and
  file.path : (
    "?:\\Windows\\System32\\*",
    "?:\\Windows\\SysWOW64\\*",
    "?:\\ProgramData\\*",
    "?:\\Users\\Public\\*",
    "?:\\Users\\*\\AppData\\Roaming\\Microsoft\\Windows\\Start Menu\\Programs\\Startup\\*",
    "?:\\ProgramData\\Microsoft\\Windows\\Start Menu\\Programs\\Startup\\*"
  ) and
  not process.executable : (
    "?:\\Program Files\\*",
    "?:\\Program Files (x86)\\*",
    "?:\\ProgramData\\Microsoft\\Windows Defender\\*",
    "?:\\Windows\\system32\\cleanmgr.exe",
    "?:\\Windows\\system32\\msiexec.exe",
    "?:\\Windows\\syswow64\\msiexec.exe",
    "?:\\Windows\\system32\\svchost.exe",
    "?:\\Windows\\System32\\Robocopy.exe",
    "?:\\Windows\\SysWOW64\\Robocopy.exe",
    "?:\\Windows\\explorer.exe",
    "?:\\Windows\\system32\\Dism.exe",
    "?:\\Windows\\system32\\DFSRs.exe",
    "?:\\Windows\\system32\\wbengine.exe",
    "?:\\Windows\\system32\\CompatTelRunner.exe",
    "?:\\Windows\\system32\\SearchIndexer.exe",
    "?:\\Windows\\system32\\wuauclt.exe",
    "?:\\Windows\\servicing\\TrustedInstaller.exe",
    "?:\\Windows\\WinSxS\\*\\TiWorker.exe",
    "?:\\Windows\\Microsoft.NET\\*",
    "?:\\Windows\\SystemApps\\*",
    "?:\\Windows\\uus\\*\\wuaucltcore.exe",
    "?:\\$WINDOWS.~BT\\Sources\\mighost.exe"
  ) and
  not (process.executable : "?:\\Windows\\System32\\spoolsv.exe" and file.path : "?:\\Windows\\System32\\spool\\*") and
  not user.name : ("SYSTEM", "Local Service", "Network Service")

// Title: defense_evasion_untrusted_driver_loaded.toml
// Source: detection-rules::rules/windows/defense_evasion_untrusted_driver_loaded.toml
// Section: EQL Rule
// Rule Name: Untrusted Driver Loaded
// Author: Elastic
// Description:
// Identifies an untrusted driver loaded by the Windows kernel. Adversaries may modify code signing policies to
// enable execution of unsigned or self-signed kernel code.
// Integration: endpoint
// Language: eql
// UUID: d8ab1ec1-feeb-48b9-89e7-c12e189448aa
// Type: eql

driver where host.os.type == "windows" and process.pid == 4 and
  (dll.code_signature.trusted == false or dll.code_signature.exists == false) and
  /* errorExpired and errorRevoked are handled by d12bac54-ab2a-4159-933f-d7bcefa7b61d */
  not dll.code_signature.status : ("errorExpired", "errorRevoked", "errorCode_endpoint:*") and

  not dll.hash.sha256 : (
        /* HP DOT4 printer driver family FPs (Dot4.sys, Dot4Prt.sys, Dot4usb.sys, Dot4Scan.sys) */
        "f21c1d478180bc5e932bb2c2e4618e3ed463ca87acedeb139682d218435f82f1",
        "7e2f2a139e897eae56038b920bda9381094bc0ae9e626f6634e6b444b8b0c91f",
        "12ffdf5f48a79b1b4adbb88ba2cb6c59dd6719554e8ea6beefe99b3e3c66f1ac",
        "dbc6afaf80141e2480e19878f581edfe9c2b018da2ec527c4025ff04d5587afd",
        /* (dc3d.sys, test-signed) */
        "ca8f9564733ded4c3895cf7150bb254995d66889e6be08d6654e4f897e4ff7a4"
  )

// Title: defense_evasion_unusual_ads_file_creation.toml
// Source: detection-rules::rules/windows/defense_evasion_unusual_ads_file_creation.toml
// Section: EQL Rule
// Rule Name: Unusual File Creation - Alternate Data Stream
// Author: Elastic
// Description:
// Identifies suspicious creation of Alternate Data Streams on highly targeted files using a script or command interpreter.
// This is uncommon for legitimate files and sometimes done by adversaries to hide malware.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel
// Language: eql
// UUID: 71bccb61-e19b-452f-b104-79a60e546a95
// Type: eql

file where host.os.type == "windows" and event.type == "creation" and
   process.name : ("cmd.exe", "powershell.exe", "pwsh.exe", "mshta.exe", "wscript.exe", "cscript.exe", "node.exe", "python*.exe") and
   file.extension in~ (
    "pdf", "dll", "exe", "dat", "com", "bat", "cmd", "sys", "vbs", "vbe", "ps1", "hta", "txt", "js", "jse",
    "wsh", "wsf", "sct", "docx", "doc", "xlsx", "xls", "pptx", "ppt", "rtf", "gif", "jpg", "png", "bmp", "img", "iso"
  ) and
  file.path : "C:\\*:*" and
  not file.name :("*:$DATA", "*PG$Secure", "*Zone.Identifier", "*com.apple.lastuseddate#PS", "*com.apple.provenance")

// Title: defense_evasion_unusual_dir_ads.toml
// Source: detection-rules::rules/windows/defense_evasion_unusual_dir_ads.toml
// Section: EQL Rule
// Rule Name: Unusual Process Execution Path - Alternate Data Stream
// Author: Elastic
// Description:
// Identifies processes running from an Alternate Data Stream. This is uncommon for legitimate processes and sometimes done
// by adversaries to hide malware.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 4bd1c1af-79d4-4d37-9efa-6e0240640242
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.args : "?:\\*:*" and
  (
    process.args_count == 1 and

    /* Excludes bug where a missing closing quote sets args_count to 1 despite extra args */
    not process.command_line regex~ """\".*\.exe[^\"].*"""
  )

// Title: defense_evasion_unusual_network_connection_via_dllhost.toml
// Source: detection-rules::rules/windows/defense_evasion_unusual_network_connection_via_dllhost.toml
// Section: EQL Rule
// Rule Name: Unusual Network Connection via DllHost
// Author: Elastic
// Description:
// Identifies unusual instances of dllhost.exe making outbound network connections. This may indicate adversarial Command
// and Control activity.
// Integration: endpoint, windows, sentinel_one_cloud_funnel
// Language: eql
// UUID: c7894234-7814-44c2-92a9-f7d851ea246a
// Type: eql

sequence by host.id, process.entity_id with maxspan=1m
  [process where host.os.type == "windows" and event.type == "start" and process.name : "dllhost.exe" and process.args_count == 1]
  [network where host.os.type == "windows" and process.name : "dllhost.exe" and
   not cidrmatch(destination.ip, "10.0.0.0/8", "127.0.0.0/8", "169.254.0.0/16", "172.16.0.0/12", "192.0.0.0/24",
    "192.0.0.0/29", "192.0.0.8/32", "192.0.0.9/32", "192.0.0.10/32", "192.0.0.170/32", "192.0.0.171/32", "192.0.2.0/24",
    "192.31.196.0/24", "192.52.193.0/24", "192.168.0.0/16", "192.88.99.0/24", "224.0.0.0/4", "100.64.0.0/10",
    "192.175.48.0/24", "198.18.0.0/15", "198.51.100.0/24", "203.0.113.0/24", "240.0.0.0/4", "::1", "FE80::/10",
    "FF00::/8")]

// Title: defense_evasion_unusual_network_connection_via_rundll32.toml
// Source: detection-rules::rules/windows/defense_evasion_unusual_network_connection_via_rundll32.toml
// Section: EQL Rule
// Rule Name: Unusual Network Connection via RunDLL32
// Author: Elastic
// Description:
// Identifies unusual instances of rundll32.exe making outbound network connections. This may indicate adversarial Command
// and Control activity.
// Integration: endpoint, windows, sentinel_one_cloud_funnel
// Language: eql
// UUID: 52aaab7b-b51c-441a-89ce-4387b3aea886
// Type: eql

sequence by host.id, process.entity_id with maxspan=1m
  [process where host.os.type == "windows" and event.type == "start" and process.name : "rundll32.exe" and
  (
    process.args_count == 1 and

    /* Excludes bug where a missing closing quote sets args_count to 1 despite extra args */
    not process.command_line regex~ """\".*\.exe[^\"].*"""
  )]
  [network where host.os.type == "windows" and process.name : "rundll32.exe" and
   not cidrmatch(destination.ip, "10.0.0.0/8", "127.0.0.0/8", "169.254.0.0/16", "172.16.0.0/12", "192.0.0.0/24",
       "192.0.0.0/29", "192.0.0.8/32", "192.0.0.9/32", "192.0.0.10/32", "192.0.0.170/32", "192.0.0.171/32",
       "192.0.2.0/24", "192.31.196.0/24", "192.52.193.0/24", "192.168.0.0/16", "192.88.99.0/24", "224.0.0.0/4",
       "100.64.0.0/10", "192.175.48.0/24","198.18.0.0/15", "198.51.100.0/24", "203.0.113.0/24", "240.0.0.0/4", "::1",
       "FE80::/10", "FF00::/8")]

// Title: defense_evasion_unusual_process_network_connection.toml
// Source: detection-rules::rules/windows/defense_evasion_unusual_process_network_connection.toml
// Section: EQL Rule
// Rule Name: Unusual Process Network Connection
// Author: Elastic
// Description:
// Identifies network activity from unexpected system applications. This may indicate adversarial activity as these
// applications are often leveraged by adversaries to execute code and evade detection.
// Integration: endpoint, windows, sentinel_one_cloud_funnel
// Language: eql
// UUID: 610949a1-312f-4e04-bb55-3a79b8c95267
// Type: eql

sequence by process.entity_id
  [process where host.os.type == "windows" and (process.name : "Microsoft.Workflow.Compiler.exe" or
                  process.name : "bginfo.exe" or
                  process.name : "cdb.exe" or
                  process.name : "cmstp.exe" or
                  process.name : "csi.exe" or
                  process.name : "dnx.exe" or
                  process.name : "fsi.exe" or
                  process.name : "ieexec.exe" or
                  process.name : "iexpress.exe" or
                  process.name : "odbcconf.exe" or
                  process.name : "rcsi.exe" or
                  process.name : "xwizard.exe") and
     event.type == "start"]
  [network where host.os.type == "windows" and (process.name : "Microsoft.Workflow.Compiler.exe" or
                  process.name : "bginfo.exe" or
                  process.name : "cdb.exe" or
                  process.name : "cmstp.exe" or
                  process.name : "csi.exe" or
                  process.name : "dnx.exe" or
                  process.name : "fsi.exe" or
                  process.name : "ieexec.exe" or
                  process.name : "iexpress.exe" or
                  process.name : "odbcconf.exe" or
                  process.name : "rcsi.exe" or
                  process.name : "xwizard.exe")]

// Title: defense_evasion_unusual_system_vp_child_program.toml
// Source: detection-rules::rules/windows/defense_evasion_unusual_system_vp_child_program.toml
// Section: EQL Rule
// Rule Name: Unusual Child Process from a System Virtual Process
// Author: Elastic
// Description:
// Identifies a suspicious child process of the Windows virtual system process, which could indicate code injection.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel
// Language: eql
// UUID: de9bd7e0-49e9-4e92-a64d-53ade2e66af1
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.parent.pid == 4 and process.executable : "?*" and
  not process.executable : ("Registry", "MemCompression", "?:\\Windows\\System32\\smss.exe", "HotPatch")

// Title: defense_evasion_via_filter_manager.toml
// Source: detection-rules::rules/windows/defense_evasion_via_filter_manager.toml
// Section: EQL Rule
// Rule Name: Potential Evasion via Filter Manager
// Author: Elastic
// Description:
// The Filter Manager Control Program (fltMC.exe) binary may be abused by adversaries to unload a filter driver and evade
// defenses.
// Integration: endpoint, windows, m365_defender, system, sentinel_one_cloud_funnel
// Language: eql
// UUID: 06dceabf-adca-48af-ac79-ffdf4c3b1e9a
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.name : "fltMC.exe" and process.args : "unload" and
  not process.parent.executable : 
                   ("?:\\Program Files (x86)\\ManageEngine\\UEMS_Agent\\bin\\DCFAService64.exe", 
                    "?:\\Windows\\SysWOW64\\msiexec.exe", 
                    "?:\\Program Files\\Bitdefender\\Endpoint Security\\installer\\installer.exe", 
                    "?:\\Program Files\\Bitdefender\\Endpoint Security\\EPSecurityService.exe", 
                    "?:\\Program Files\\Bitdefender\\Bitdefender Security\\productcfg.exe", 
                    "?:\\Program Files\\Bitdefender\\Bitdefender Security\\bdservicehost.exe", 
                    "?:\\Program Files\\Bitdefender\\EndpointSetupInformation\\{*}\\Installer.exe")

// Title: defense_evasion_wdac_policy_by_unusual_process.toml
// Source: detection-rules::rules/windows/defense_evasion_wdac_policy_by_unusual_process.toml
// Section: EQL Rule
// Rule Name: WDAC Policy File by an Unusual Process
// Author: Elastic
// Description:
// Identifies the creation of a Windows Defender Application Control (WDAC) policy file by an unusual process. Adversaries
// may use a specially crafted WDAC policy to restrict the execution of security products.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 3aaf37f3-05a1-40a5-bb6e-e380c4f92c52
// Type: eql

file where host.os.type == "windows" and event.action != "deletion" and
  file.extension : ("p7b", "cip") and
  file.path : (
    "?:\\Windows\\System32\\CodeIntegrity\\*.p7b",
    "?:\\Windows\\System32\\CodeIntegrity\\CiPolicies\\Active\\*.cip",
    "\\Device\\HarddiskVolume*\\Windows\\System32\\CodeIntegrity\\*.p7b",
    "\\Device\\HarddiskVolume*\\Windows\\System32\\CodeIntegrity\\CiPolicies\\Active\\*.cip"
  ) and
  not process.executable : (
    "C:\\Windows\\System32\\poqexec.exe",
    "\\Device\\HarddiskVolume*\\Windows\\System32\\poqexec.exe",
    "?:\\Windows\\WinSxS\\*\\TiWorker.exe",
    "?:\\Windows\\System32\\omadmclient.exe"
  ) and
  /* System / ntoskrnl.exe (PID 4) */
  not process.pid == 4

// Title: defense_evasion_workfolders_control_execution.toml
// Source: detection-rules::rules/windows/defense_evasion_workfolders_control_execution.toml
// Section: EQL Rule
// Rule Name: Signed Proxy Execution via MS Work Folders
// Author: Elastic, Austin Songer
// Description:
// Identifies the use of Windows Work Folders to execute a potentially masqueraded control.exe file in the current working
// directory. Misuse of Windows Work Folders could indicate malicious activity.
// Integration: windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: ad0d2742-9a49-11ec-8d6b-acde48001122
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.name : "control.exe" and process.parent.name : "WorkFolders.exe" and
  not process.executable : (
    "?:\\Windows\\System32\\control.exe",
    "?:\\Windows\\SysWOW64\\control.exe",

    /* Crowdstrike specific condition as it uses NT Object paths */
    "\\Device\\HarddiskVolume*\\Windows\\System32\\control.exe",
    "\\Device\\HarddiskVolume*\\Windows\\SysWOW64\\control.exe"
  )

// Title: defense_evasion_wsl_bash_exec.toml
// Source: detection-rules::rules/windows/defense_evasion_wsl_bash_exec.toml
// Section: EQL Rule
// Rule Name: Suspicious Execution via Windows Subsystem for Linux
// Author: Elastic
// Description:
// Detects Linux Bash commands from the Windows Subsystem for Linux. Adversaries may enable and use WSL for Linux to
// avoid detection.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel
// Language: eql
// UUID: 3e0eeb75-16e8-4f2f-9826-62461ca128b7
// Type: eql

process where host.os.type == "windows" and event.type : "start" and
  (
    (
      (process.executable : "?:\\Windows\\System32\\bash.exe" or ?process.pe.original_file_name == "Bash.exe") and
      not process.command_line : ("bash", "bash.exe")
    ) or
    process.executable : "?:\\Users\\*\\AppData\\Local\\Packages\\*\\rootfs\\usr\\bin\\bash" or
    (
      process.parent.name : "wsl.exe" and process.parent.command_line : "bash*" and not process.name : "wslhost.exe"
    ) or
    (
      process.name : "wsl.exe" and
      (
        process.args : "--system" or
        (
          process.args : "--manage" and process.args : "--set-default-user" and process.args : "root"
        ) or
        (
          (process.args : ("curl", "wget") and process.args : ("http://*", "https://*")) or
          process.args : ("*curl*http://*", "*curl*https://*", "*wget*http://*", "*wget*https://*")
        ) or
        (
          (
            process.args like~ ("*/dev/tcp/*", "*/dev/udp/*", "*zsh/net/tcp*") and
            process.args like ("*&>*", "*<>*", "*>&*", "*<&*")
          ) or
          (
            process.args : ("nc", "netcat", "nc.traditional", "ncat", "*/nc", "*/netcat", "*/nc.traditional", "*/ncat") and
            process.args : ("sh", "/bin/sh", "bash", "/bin/bash") and
            process.args : ("-e", "--exec", "-c", "--sh-exec")
          ) or
          (
            process.args like~ "*socat*" and
            process.args like~ ("*exec:*", "*system:*", "*shell:*") and
            process.args like~ ("*tcp*", "*udp*", "*openssl*")
          )
        ) or
        (
          process.args : ("-e", "--exec") and
          process.args : (
            "/mnt/c/*.exe", "/mnt/c/*.ps1", "/mnt/c/*.bat", "/mnt/c/*.cmd", "/mnt/c/*.vbs", "/mnt/c/*.js",
            "/mnt/c/*.hta"
          ) and
          not process.args : "*wslpath*"
        ) or
        process.args : (
          "*/etc/passwd*", "*/etc/shadow*", "*/etc/sudoers*", "*/etc/sudoers.d/*", "*/root/.ssh/*", "*/home/*/.ssh/*",
          "*/root/.aws/credentials*", "*/home/*/.aws/credentials*", "*/root/.kube/config*", "*/home/*/.kube/config*",
          "*/mnt/c/Windows/System32/config/SAM*",
          "*/mnt/c/Windows/System32/config/SECURITY*",
          "*/mnt/c/Windows/System32/config/SYSTEM", "*/mnt/c/Windows/System32/config/SYSTEM.*",
          "*/mnt/c/Windows/NTDS/ntds.dit*",
          "*/mnt/c/Users/*/AppData/Roaming/Microsoft/Credentials/*",
          "*/mnt/c/Users/*/AppData/Local/Microsoft/Credentials/*",
          "*/mnt/c/Users/*/AppData/Roaming/Microsoft/Protect/*",
          "*/mnt/c/Users/*/.ssh/*",
          "*/mnt/c/Users/*/.aws/credentials",
          "*/mnt/c/Users/*/.azure/*",
          "*/mnt/c/Users/*/.config/gcloud/*",
          "*/mnt/c/Users/*/AppData/Local/Google/Chrome/User Data/*/Login Data*",
          "*/mnt/c/Users/*/AppData/Local/Microsoft/Edge/User Data/*/Login Data*"
        )
      )
    )
  ) and
    not process.parent.executable : ("?:\\Program Files\\Docker\\*.exe", "?:\\Program Files (x86)\\Docker\\*.exe")

// Title: defense_evasion_wsl_child_process.toml
// Source: detection-rules::rules/windows/defense_evasion_wsl_child_process.toml
// Section: EQL Rule
// Rule Name: Execution via Windows Subsystem for Linux
// Author: Elastic
// Description:
// Detects attempts to execute a program on the host from the Windows Subsystem for Linux. Adversaries may enable and use
// WSL for Linux to avoid detection.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: db7dbad5-08d2-4d25-b9b1-d3a1e4a15efd
// Type: eql

process where host.os.type == "windows" and event.type : "start" and process.command_line != null and
  process.parent.name : ("wsl.exe", "wslhost.exe") and
  not process.executable : (
        "?:\\Program Files (x86)\\*",
        "?:\\Program Files\\*",
        "?:\\Program Files*\\WindowsApps\\MicrosoftCorporationII.WindowsSubsystemForLinux_*\\wsl*.exe",
        "?:\\Windows\\System32\\conhost.exe",
        "?:\\Windows\\System32\\lxss\\wslhost.exe",
        "?:\\Windows\\System32\\WerFault.exe",
        "?:\\Windows\\System32\\wsl.exe",
        "?:\\Windows\\Sys?????\\wslconfig.exe"
  ) and
  not (
    /* Crowdstrike specific exclusion as it uses NT Object paths */
    (data_stream.dataset == "crowdstrike.fdr" or event.action == "ProcessRollup2") and
      process.executable : (
        "\\Device\\HarddiskVolume*\\Program Files (x86)\\*",
        "\\Device\\HarddiskVolume*\\Program Files\\*",
        "\\Device\\HarddiskVolume*\\Program Files*\\WindowsApps\\MicrosoftCorporationII.WindowsSubsystemForLinux_*\\wsl*.exe",
        "\\Device\\HarddiskVolume*\\Windows\\System32\\conhost.exe",
        "\\Device\\HarddiskVolume*\\Windows\\System32\\lxss\\wslhost.exe",
        "\\Device\\HarddiskVolume*\\Windows\\System32\\WerFault.exe",
        "\\Device\\HarddiskVolume*\\Windows\\System32\\wsl.exe",
        "\\Device\\HarddiskVolume*\\Windows\\Sys?????\\wslconfig.exe"
      )
  ) and
  not (
    (process.name : "cmd.exe" and process.command_line : "*echo*%USERPROFILE%*") or
    (process.name : "git.exe" and process.command_line : "git.exe -c log.*") or
    (process.name : "powershell.exe" and process.command_line : "powershell.exe -Command $env:USERPROFILE") or
    (process.name : "Code.exe" and process.command_line : ("*cli.js --folder-uri=vscode-remote://wsl*", "ms-vscode-remote.remote-wsl"))
  )

// Title: defense_evasion_wsl_enabled_via_dism.toml
// Source: detection-rules::rules/windows/defense_evasion_wsl_enabled_via_dism.toml
// Section: EQL Rule
// Rule Name: Windows Subsystem for Linux Enabled via Dism Utility
// Author: Elastic
// Description:
// Detects attempts to enable the Windows Subsystem for Linux using Microsoft Dism utility. Adversaries may enable and use
// WSL for Linux to avoid detection.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: e2e0537d-7d8f-4910-a11d-559bcf61295a
// Type: eql

process where host.os.type == "windows" and event.type : "start" and
 (process.name : "Dism.exe" or ?process.pe.original_file_name == "DISM.EXE") and 
 process.command_line : "*Microsoft-Windows-Subsystem-Linux*"

// Title: defense_evasion_wsl_filesystem.toml
// Source: detection-rules::rules/windows/defense_evasion_wsl_filesystem.toml
// Section: EQL Rule
// Rule Name: Host File System Changes via Windows Subsystem for Linux
// Author: Elastic
// Description:
// Detects file creation and modification on the host system from the Windows Subsystem for Linux. Adversaries may enable
// and use WSL to avoid detection.
// Integration: endpoint, windows, sentinel_one_cloud_funnel
// Language: eql
// UUID: e88d1fe9-b2f4-48d4-bace-a026dc745d4b
// Type: eql

sequence by process.entity_id with maxspan=5m
[process where host.os.type == "windows" and event.type == "start" and
 process.name : "dllhost.exe" and
  /* Plan9FileSystem CLSID - WSL Host File System Worker */
 process.command_line : "*{DFB65C4C-B34F-435D-AFE9-A86218684AA8}*"]
[file where host.os.type == "windows" and process.name : "dllhost.exe" and
  not file.path : "?:\\Windows\\Prefetch\\DLLHOST.exe-????????.pf"]

// Title: defense_evasion_wsl_kalilinux.toml
// Source: detection-rules::rules/windows/defense_evasion_wsl_kalilinux.toml
// Section: EQL Rule
// Rule Name: Attempt to Install or Run Kali Linux via WSL
// Author: Elastic
// Description:
// Detects attempts to install or use Kali Linux via Windows Subsystem for Linux. Adversaries may enable and use WSL for
// Linux to avoid detection.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: dd34b062-b9e3-4a6b-8c0c-6c8ca6dd450e
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
(
  (process.name : "wsl.exe" and process.args : ("-d", "--distribution", "-i", "--install") and process.args : "kali*") or
  process.executable : (
    "?:\\Users\\*\\AppData\\Local\\packages\\kalilinux*",
    "?:\\Users\\*\\AppData\\Local\\Microsoft\\WindowsApps\\kali.exe",
    "?:\\Program Files*\\WindowsApps\\KaliLinux.*\\kali.exe",

    /* Crowdstrike specific exclusion as it uses NT Object paths */
    "\\Device\\HarddiskVolume*\\Users\\*\\AppData\\Local\\packages\\kalilinux*",
    "\\Device\\HarddiskVolume*\\Users\\*\\AppData\\Local\\Microsoft\\WindowsApps\\kali.exe",
    "\\Device\\HarddiskVolume*\\Program Files*\\WindowsApps\\KaliLinux.*\\kali.exe"
  )
)

// Title: defense_evasion_wsl_registry_modification.toml
// Source: detection-rules::rules/windows/defense_evasion_wsl_registry_modification.toml
// Section: EQL Rule
// Rule Name: Windows Subsystem for Linux Distribution Installed
// Author: Elastic
// Description:
// Detects changes to the registry that indicates the install of a new Windows Subsystem for Linux distribution by name.
// Adversaries may enable and use WSL for Linux to avoid detection.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: a1699af0-8e1e-4ed0-8ec1-89783538a061
// Type: eql

registry where host.os.type == "windows" and event.type == "change" and registry.value : "PackageFamilyName" and
 registry.path : "*\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Lxss\\*\\PackageFamilyName"

// Title: discovery_active_directory_webservice.toml
// Source: detection-rules::rules/windows/discovery_active_directory_webservice.toml
// Section: EQL Rule
// Rule Name: Potential Enumeration via Active Directory Web Service
// Author: Elastic
// Description:
// Identifies processes loading Active Directory related modules followed by a network connection to the ADWS dedicated TCP
// port. Adversaries may abuse the ADWS Windows service that allows Active Directory to be queried via this web service.
// Integration: endpoint
// Language: eql
// UUID: 9c951837-7d13-4b0c-be7a-f346623c8795
// Type: eql

sequence by process.entity_id with maxspan=3m
 [library where host.os.type == "windows" and
  dll.name : ("System.DirectoryServices*.dll", "System.IdentityModel*.dll") and
  not user.id in ("S-1-5-18", "S-1-5-19", "S-1-5-20") and
  not process.executable :
                ("?:\\windows\\system32\\dsac.exe",
                 "?:\\program files\\powershell\\?\\pwsh.exe",
                 "?:\\windows\\system32\\windowspowershell\\*.exe",
                 "?:\\windows\\syswow64\\windowspowershell\\*.exe",
                 "?:\\program files\\microsoft monitoring agent\\*.exe",
                 "?:\\windows\\adws\\microsoft.activedirectory.webservices.exe")]
 [network where host.os.type == "windows" and destination.port == 9389 and source.port >= 49152 and
  network.direction == "egress" and network.transport == "tcp" and not cidrmatch(destination.ip, "127.0.0.0/8", "::1/128")]

// Title: discovery_ad_explorer_execution.toml
// Source: detection-rules::rules/windows/discovery_ad_explorer_execution.toml
// Section: EQL Rule
// Rule Name: Active Directory Discovery using AdExplorer
// Author: Elastic
// Description:
// This rule detects the use of ADExplorer utility. Active Directory Explorer (AD Explorer) is an advanced Active Directory (AD)
// viewer and editor. AD Explorer also includes the ability to save snapshots of an AD database for off-line viewing and comparisons.
// Adversaries may abuse this utility to perform domain reconnaissance.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: ff46eb26-0684-4da3-9dd6-21032c9878e1
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  (process.name : "ADExplorer*.exe" or ?process.pe.original_file_name == "AdExp")

// Title: discovery_adfind_command_activity.toml
// Source: detection-rules::rules/windows/discovery_adfind_command_activity.toml
// Section: EQL Rule
// Rule Name: AdFind Command Activity
// Author: Elastic
// Description:
// This rule detects the Active Directory query tool, AdFind.exe. AdFind has legitimate purposes, but it is frequently
// leveraged by threat actors to perform post-exploitation Active Directory reconnaissance. The AdFind tool has been
// observed in Trickbot, Ryuk, Maze, and FIN6 campaigns. For Winlogbeat, this rule requires Sysmon.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: eda499b8-a073-4e35-9733-22ec71f57f3a
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  (process.name : "AdFind*.exe" or ?process.pe.original_file_name == "AdFind.exe") and
  process.args : ("objectcategory=computer", "(objectcategory=computer)",
                  "objectcategory=person", "(objectcategory=person)",
                  "objectcategory=subnet", "(objectcategory=subnet)",
                  "objectcategory=group", "(objectcategory=group)",
                  "objectcategory=organizationalunit", "(objectcategory=organizationalunit)",
                  "objectcategory=attributeschema", "(objectcategory=attributeschema)",
                  "domainlist", "dcmodes", "adinfo", "dclist", "computers_pwnotreqd", "trustdmp")

// Title: discovery_admin_recon.toml
// Source: detection-rules::rules/windows/discovery_admin_recon.toml
// Section: EQL Rule
// Rule Name: Enumeration of Administrator Accounts
// Author: Elastic
// Description:
// Identifies instances of lower privilege accounts enumerating Administrator accounts or groups using built-in Windows
// tools.
// Integration: endpoint, windows, system, m365_defender, crowdstrike
// Language: eql
// UUID: 871ea072-1b71-4def-b016-6278b505138d
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
(
  (
    (
      (process.name : "net.exe" or ?process.pe.original_file_name == "net.exe") or
      ((process.name : "net1.exe" or ?process.pe.original_file_name == "net1.exe") and not process.parent.name : "net.exe")
    ) and
    process.args : ("group", "user", "localgroup") and
    process.args : ("*admin*", "Domain Admins", "Remote Desktop Users", "Enterprise Admins", "Organization Management")
    and not process.args : ("/add", "/delete")
  ) or
  (
    (process.name : "wmic.exe" or ?process.pe.original_file_name == "wmic.exe") and
    process.args : ("group", "useraccount")
  )
) and not user.id : ("S-1-5-18", "S-1-5-19", "S-1-5-20")

// Title: discovery_command_system_account.toml
// Source: detection-rules::rules/windows/discovery_command_system_account.toml
// Section: EQL Rule
// Rule Name: Account Discovery Command via SYSTEM Account
// Author: Elastic
// Description:
// Identifies when the SYSTEM account uses an account discovery utility. This could be a sign of discovery activity after
// an adversary has achieved privilege escalation.
// Integration: endpoint, windows
// Language: eql
// UUID: 2856446a-34e6-435b-9fb5-f8f040bfa7ed
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  (?process.Ext.token.integrity_level_name : "System" or
  ?winlog.event_data.IntegrityLevel : "System") and
  (
    process.name : "whoami.exe" or
    (
      process.name : "net1.exe" and not process.parent.name : "net.exe" and not process.args : ("start", "stop", "/active:*")
    )
  ) and 
process.parent.executable != null and 
not (process.name : "net1.exe" and process.working_directory : "C:\\ProgramData\\Microsoft\\Windows Defender Advanced Threat Protection\\Downloads\\") and 
not process.parent.executable : 
                ("C:\\Program Files\\Microsoft Monitoring Agent\\Agent\\MonitoringHost.exe", 
                 "C:\\Program Files\\Dell\\SupportAssistAgent\\SRE\\SRE.exe", 
                 "C:\\Program Files\\Obkio Agent\\main.dist\\ObkioAgentSoftware.exe", 
                 "C:\\Windows\\Temp\\WinGet\\defaultState\\PostgreSQL.PostgreSQL*\\postgresql-*-windows-x64.exe", 
                 "C:\\Program Files\\Obkio Agent\\main.dist\\ObkioAgentSoftware.exe", 
                 "C:\\Program Files (x86)\\SolarWinds\\Agent\\Plugins\\JobEngine\\SWJobEngineWorker2.exe") and 
not (process.parent.executable : "C:\\Windows\\Sys?????\\WindowsPowerShell\\v1.0\\powershell.exe" and 
     process.parent.args : ("C:\\Program Files (x86)\\Microsoft Intune Management Extension\\*.ps1", 
                            "Agent\\Modules\\AdHealthConfiguration\\AdHealthConfiguration.psd1'")) and 
not (process.parent.name : "cmd.exe" and process.working_directory : "C:\\Program Files\\Infraon Corp\\SecuraAgent\\")

// Title: discovery_enumerating_domain_trusts_via_dsquery.toml
// Source: detection-rules::rules/windows/discovery_enumerating_domain_trusts_via_dsquery.toml
// Section: EQL Rule
// Rule Name: Enumerating Domain Trusts via DSQUERY.EXE
// Author: Elastic
// Description:
// Identifies the use of dsquery.exe for domain trust discovery purposes. Adversaries may use this command-line utility to
// enumerate trust relationships that may be used for Lateral Movement opportunities in Windows multi-domain forest
// environments.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 06a7a03c-c735-47a6-a313-51c354aef6c3
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
    (process.name : "dsquery.exe" or ?process.pe.original_file_name: "dsquery.exe") and 
    process.args : "*objectClass=trustedDomain*"

// Title: discovery_enumerating_domain_trusts_via_nltest.toml
// Source: detection-rules::rules/windows/discovery_enumerating_domain_trusts_via_nltest.toml
// Section: EQL Rule
// Rule Name: Enumerating Domain Trusts via NLTEST.EXE
// Author: Elastic
// Description:
// Identifies the use of nltest.exe for domain trust discovery purposes. Adversaries may use this command-line utility to
// enumerate domain trusts and gain insight into trust relationships, as well as the state of Domain Controller (DC)
// replication in a Microsoft Windows NT Domain.
// Integration: endpoint, windows, system, m365_defender, crowdstrike
// Language: eql
// UUID: 84da2554-e12a-11ec-b896-f661ea17fbcd
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
    process.name : "nltest.exe" and process.args : (
        "/DCLIST:*", "/DCNAME:*", "/DSGET*",
        "/LSAQUERYFTI:*", "/PARENTDOMAIN",
        "/DOMAIN_TRUSTS", "/BDC_QUERY:*"
        ) and 
not process.parent.name : "PDQInventoryScanner.exe" and
not (
  user.id in ("S-1-5-18", "S-1-5-19", "S-1-5-20") and
  /* Don't apply the user.id exclusion to Sysmon for compatibility */
  not data_stream.dataset : ("windows.sysmon_operational", "windows.sysmon")
)

// Title: discovery_group_policy_object_discovery.toml
// Source: detection-rules::rules/windows/discovery_group_policy_object_discovery.toml
// Section: EQL Rule
// Rule Name: Group Policy Discovery via Microsoft GPResult Utility
// Author: Elastic
// Description:
// Detects the usage of gpresult.exe to query group policy objects. Attackers may query group policy objects during the
// reconnaissance phase after compromising a system to gain a better understanding of the active directory environment and
// possible methods to escalate privileges or move laterally.
// Integration: windows, endpoint, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 94a401ba-4fa2-455c-b7ae-b6e037afc0b7
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
(process.name: "gpresult.exe" or ?process.pe.original_file_name == "gprslt.exe") and process.args: ("/z", "/v", "/r", "/x")

// Title: discovery_high_number_ad_properties.toml
// Source: detection-rules::rules/windows/discovery_high_number_ad_properties.toml
// Section: EQL Rule
// Rule Name: Suspicious Access to LDAP Attributes
// Author: Elastic
// Description:
// Identify read access to a high number of Active Directory object attributes. The knowledge of objects properties can
// help adversaries find vulnerabilities, elevate privileges or collect sensitive information.
// Integration: windows, system
// Language: eql
// UUID: 68ad737b-f90a-4fe5-bda6-a68fa460044e
// Type: eql

any where host.os.type == "windows" and event.code == "4662" and not winlog.event_data.SubjectUserSid : "S-1-5-18" and
 winlog.event_data.AccessMaskDescription == "Read Property" and length(winlog.event_data.Properties) >= 2000

// Title: discovery_peripheral_device.toml
// Source: detection-rules::rules/windows/discovery_peripheral_device.toml
// Section: EQL Rule
// Rule Name: Peripheral Device Discovery
// Author: Elastic
// Description:
// Identifies use of the Windows file system utility (fsutil.exe) to gather information about attached peripheral devices
// and components connected to a computer system.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 0c7ca5c2-728d-4ad9-b1c5-bbba83ecb1f4
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  (process.name : "fsutil.exe" or ?process.pe.original_file_name == "fsutil.exe") and
  process.args : "fsinfo" and process.args : "drives"

// Title: discovery_whoami_command_activity.toml
// Source: detection-rules::rules/windows/discovery_whoami_command_activity.toml
// Section: EQL Rule
// Rule Name: Whoami Process Activity
// Author: Elastic
// Description:
// Identifies suspicious use of whoami.exe which displays user, group, and privileges information for the user who is
// currently logged on to the local system.
// Integration: endpoint, system, windows, m365_defender
// Language: eql
// UUID: ef862985-3f13-4262-a686-5f357bbb9bc2
// Type: eql

process where host.os.type == "windows" and event.type == "start" and process.name : "whoami.exe" and
(
  (
    /* scoped for whoami execution under system privileges */
    (
      (
        user.domain : ("NT *", "* NT", "IIS APPPOOL") and
        user.id : ("S-1-5-18", "S-1-5-19", "S-1-5-20", "S-1-5-82-*") and
        not ?winlog.event_data.SubjectUserName : "*$" and

        /* Sysmon will always populate user.id as S-1-5-18, leading to FPs */
        not data_stream.dataset : ("windows.sysmon_operational", "windows.sysmon")
      ) or
      (?process.Ext.token.integrity_level_name : "System" or ?winlog.event_data.IntegrityLevel : "System")
    ) and
    not (
      process.parent.name : "cmd.exe" and
      process.parent.args : (
          "chcp 437>nul 2>&1 & C:\\WINDOWS\\System32\\whoami.exe  /groups",
          "chcp 437>nul 2>&1 & %systemroot%\\system32\\whoami /user",
          "C:\\WINDOWS\\System32\\whoami.exe /groups",
          "*WINDOWS\\system32\\config\\systemprofile*"
      )
    ) and
    not (process.parent.executable : "C:\\Windows\\system32\\inetsrv\\appcmd.exe" and process.parent.args : "LIST") and
    not process.parent.executable : (
        "C:\\Program Files\\Microsoft Monitoring Agent\\Agent\\MonitoringHost.exe",
        "C:\\Program Files\\Cohesity\\cohesity_windows_agent_service.exe"
    )
  ) or
  process.parent.name : ("wsmprovhost.exe", "w3wp.exe", "wmiprvse.exe", "rundll32.exe", "regsvr32.exe")
)

// Title: execution_apt_solarwinds_backdoor_child_cmd_powershell.toml
