 ) and
 not process.executable : ("?:\\Windows\\SysWOW64\\ARP.EXE", "?:\\Windows\\SysWOW64\\lodctr.exe", "?:\\Windows\\SysWOW64\\unlodctr.exe")

// Title: execution_azure_customscript_extension_suspicious_descendant.toml
// Source: detection-rules::rules/windows/execution_azure_customscript_extension_suspicious_descendant.toml
// Section: EQL Rule
// Rule Name: Suspicious Child Process via Azure VM CustomScript Extension
// Author: Elastic
// Description:
// Identifies a suspicious process executing as a descendant of the Azure VM CustomScript extension handler
// (CustomScriptHandler.exe) on a Windows host. The Azure CustomScript extension runs an attacker-supplied script with high
// privilege (SYSTEM) via the guest agent, and is a common cloud-to-host code-execution and persistence primitive. Because
// the extension's resource name is attacker-controlled and absent from on-host telemetry, this rule anchors on the
// type-bearing handler binary ('Microsoft.Compute.CustomScriptExtension\...\CustomScriptHandler.exe') rather than the
// spoofable extension name, making it resistant to renaming. CustomScript legitimately launches PowerShell and cmd, so the
// rule fires only when the descendant is an execution-proxy, download, or discovery LOLBin, or PowerShell exhibiting
// suspicious tradecraft.
// Integration: endpoint
// Language: eql
// UUID: b4d4f0fb-908e-4cd1-ac8f-795c0433db0a
// Type: eql

sequence by host.id with maxspan=1m
  /* Azure CustomScript extension handler */
  [process where host.os.type == "windows" and event.type == "start" and
     (process.name : "CustomScriptHandler.exe" or
      process.executable : "?:\\Packages\\Plugins\\*CustomScript*\\*\\CustomScriptHandler.exe")] by process.entity_id
  /* Abused LOLBin / suspicious PowerShell anywhere in its tree */
  [process where host.os.type == "windows" and event.type == "start" and
   (
     process.name : ("mshta.exe", "regsvr32.exe", "rundll32.exe", "installutil.exe", "msbuild.exe", "regasm.exe",
                     "regsvcs.exe", "wscript.exe", "cscript.exe", "bitsadmin.exe", "nltest.exe", "whoami.exe",
                     "net.exe", "net1.exe", "wmic.exe", "systeminfo.exe", "quser.exe", "arp.exe", "tasklist.exe") or
     (process.name : "certutil.exe" and process.args : ("*urlcache*", "*-decode*", "*-encode*")) or
     (process.name : ("powershell.exe", "pwsh.exe") and
      process.command_line : ("*-enc*", "*EncodedCommand*", "*FromBase64String*", "*DownloadString*", "*DownloadFile*",
                              "*Invoke-Expression*", "*IEX *", "*IEX(*", "*|IEX*", "*-w hidden*", "*WindowStyle Hidden*",
                              "*Net.WebClient*", "*Invoke-WebRequest*", "*Start-BitsTransfer*"))
   )] by process.Ext.ancestry

// Title: execution_com_object_xwizard.toml
// Source: detection-rules::rules/windows/execution_com_object_xwizard.toml
// Section: EQL Rule
// Rule Name: Execution of COM object via Xwizard
// Author: Elastic
// Description:
// Windows Component Object Model (COM) is an inter-process communication (IPC) component of the native Windows application
// programming interface (API) that enables interaction between software objects or executable code. Xwizard can be used to
// run a COM object created in registry to evade defensive counter measures.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel, system, crowdstrike
// Language: eql
// UUID: 1a6075b0-7479-450e-8fe7-b8b8438ac570
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
 (process.name : "xwizard.exe" or ?process.pe.original_file_name : "xwizard.exe") and
 (
   (process.args : "RunWizard" and process.args : "{*}") or
   (process.executable != null and
     not process.executable : (
        "C:\\Windows\\SysWOW64\\xwizard.exe",
        "C:\\Windows\\System32\\xwizard.exe",

        /* Crowdstrike specific exclusion as it uses NT Object paths */
        "\\Device\\HarddiskVolume*\\Windows\\SysWOW64\\xwizard.exe",
        "\\Device\\HarddiskVolume*\\Windows\\System32\\xwizard.exe"
     )
   )
 )

// Title: execution_command_prompt_connecting_to_the_internet.toml
// Source: detection-rules::rules/windows/execution_command_prompt_connecting_to_the_internet.toml
// Section: EQL Rule
// Rule Name: Suspicious Command Prompt Network Connection
// Author: Elastic
// Description:
// Identifies a network connection by the command prompt (cmd.exe) when it is executed with specific arguments, such as a
// script or a URL, or when it is spawned by Microsoft Office applications. Adversaries often abuse cmd.exe to download
// malicious payloads or establish command and control channels from a remote source.
// Integration: endpoint, windows, sentinel_one_cloud_funnel
// Language: eql
// UUID: 89f9a4b0-9f8f-4ee0-8823-c4751a6d6696
// Type: eql

sequence by process.entity_id with maxspan=15s
  [process where host.os.type == "windows" and event.type == "start" and
    process.name : "cmd.exe" and process.args : ("/c", "/k") and
    (
      process.args : ("*.bat", "*.cmd") or
      process.command_line : ("*http://*", "*https://*", "*ftp://*") or
      process.parent.name : ("excel.exe", "msaccess.exe", "mspub.exe", "powerpnt.exe", "winword.exe", "outlook.exe")
    )
  ]
  [network where host.os.type == "windows" and process.name : "cmd.exe" and
     not cidrmatch(destination.ip, "10.0.0.0/8", "127.0.0.0/8", "169.254.0.0/16", "172.16.0.0/12", "192.0.0.0/24",
                                  "192.0.0.0/29", "192.0.0.8/32", "192.0.0.9/32", "192.0.0.10/32", "192.0.0.170/32",
                                  "192.0.0.171/32", "192.0.2.0/24", "192.31.196.0/24", "192.52.193.0/24",
                                  "192.168.0.0/16", "192.88.99.0/24", "224.0.0.0/4", "100.64.0.0/10", "192.175.48.0/24",
                                  "198.18.0.0/15", "198.51.100.0/24", "203.0.113.0/24", "240.0.0.0/4", "::1",
                                  "FE80::/10", "FF00::/8")]

// Title: execution_command_shell_via_rundll32.toml
// Source: detection-rules::rules/windows/execution_command_shell_via_rundll32.toml
// Section: EQL Rule
// Rule Name: Command Shell Activity Started via RunDLL32
// Author: Elastic
// Description:
// Identifies command shell activity started via RunDLL32, which is commonly abused by attackers to host malicious code.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel
// Language: eql
// UUID: 9ccf3ce0-0057-440a-91f5-870c6ad39093
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
 process.name : ("cmd.exe", "powershell.exe") and
  process.parent.name : "rundll32.exe" and process.parent.command_line != null and
  /* common FPs can be added here */
  not process.parent.args : ("C:\\Windows\\System32\\SHELL32.dll,RunAsNewUser_RunDLL",
                             "C:\\WINDOWS\\*.tmp,zzzzInvokeManagedCustomActionOutOfProc")

// Title: execution_delayed_via_ping_lolbas_unsigned.toml
// Source: detection-rules::rules/windows/execution_delayed_via_ping_lolbas_unsigned.toml
// Section: EQL Rule
// Rule Name: Delayed Execution via Ping
// Author: Elastic
// Description:
// Identifies the execution of commonly abused Windows utilities via a delayed Ping execution. This behavior is often
// observed during malware installation and is consistent with an attacker attempting to evade detection.
// Integration: endpoint
// Language: eql
// UUID: e00b8d49-632f-4dc6-94a5-76153a481915
// Type: eql

sequence by process.parent.entity_id with maxspan=1m
  [process where host.os.type == "windows" and event.action == "start" and process.name : "ping.exe" and
   process.args : "-n" and process.parent.name : "cmd.exe" and not user.id : "S-1-5-18"]
  [process where host.os.type == "windows" and event.action == "start" and
   process.parent.name : "cmd.exe" and
   (
        process.name : (
            "rundll32.exe", "powershell.exe",
            "mshta.exe", "msbuild.exe",
            "certutil.exe", "regsvr32.exe",
            "powershell.exe", "cscript.exe",
            "wscript.exe", "wmic.exe",
            "installutil.exe", "msxsl.exe",
            "Microsoft.Workflow.Compiler.exe",
            "ieexec.exe", "iexpress.exe",
            "RegAsm.exe", "installutil.exe",
            "RegSvcs.exe", "RegAsm.exe"
        ) or
        (process.executable : "?:\\Users\\*\\AppData\\*.exe" and not process.code_signature.trusted == true)
    ) and

    not process.args : ("?:\\Program Files\\*", "?:\\Program Files (x86)\\*") and
    not (process.name : ("openssl.exe", "httpcfg.exe", "certutil.exe") and process.parent.command_line : "*ScreenConnectConfigurator.cmd*") and
    not (process.pe.original_file_name : "DPInst.exe" and process.command_line : "driver\\DPInst_x64  /f ") and
    not (process.name : "powershell.exe" and process.args : "Write-Host ======*") and
    not (process.name : "wscript.exe" and process.args : "launchquiet_args.vbs" and process.parent.args : "?:\\Windows\\TempInst\\7z*") and
    not (process.name : "regsvr32.exe" and process.args : ("?:\\windows\\syswow64\\msxml?.dll", "msxml?.dll", "?:\\Windows\\SysWOW64\\mschrt20.ocx")) and
    not (process.name : "wscript.exe" and
         process.working_directory :
                    ("?:\\Windows\\TempInst\\*",
                     "?:\\Users\\*\\AppData\\Local\\Temp\\BackupBootstrapper\\Logs\\",
                     "?:\\Users\\*\\AppData\\Local\\Temp\\QBTools\\"))
    ]

// Title: execution_downloaded_shortcut_files.toml
// Source: detection-rules::rules/windows/execution_downloaded_shortcut_files.toml
// Section: EQL Rule
// Rule Name: Downloaded Shortcut Files
// Author: Elastic
// Description:
// Identifies .lnk shortcut file downloaded from outside the local network. These shortcut files are commonly used in
// phishing campaigns.
// Integration: endpoint
// Language: eql
// UUID: 39157d52-4035-44a8-9d1a-6f8c5f580a07
// Type: eql

file where host.os.type == "windows" and event.type == "creation" and file.extension == "lnk" and file.Ext.windows.zone_identifier > 1

// Title: execution_downloaded_url_file.toml
// Source: detection-rules::rules/windows/execution_downloaded_url_file.toml
// Section: EQL Rule
// Rule Name: Downloaded URL Files
// Author: Elastic
// Description:
// Identifies .url shortcut files downloaded from outside the local network. These shortcut files are commonly used in
// phishing campaigns.
// Integration: endpoint
// Language: eql
// UUID: cd82e3d6-1346-4afd-8f22-38388bbf34cb
// Type: eql

file where host.os.type == "windows" and event.type == "creation" and file.extension == "url"
   and file.Ext.windows.zone_identifier == 3

// Title: execution_enumeration_via_wmiprvse.toml
// Source: detection-rules::rules/windows/execution_enumeration_via_wmiprvse.toml
// Section: EQL Rule
// Rule Name: Enumeration Command Spawned via WMIPrvSE
// Author: Elastic
// Description:
// Identifies native Windows host and network enumeration commands spawned by the Windows Management Instrumentation
// Provider Service (WMIPrvSE).
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 770e0c4d-b998-41e5-a62e-c7901fd7f470
// Type: eql

process where host.os.type == "windows" and event.type == "start" and process.command_line != null and
  process.name:
  (
    "arp.exe", "dsquery.exe", "dsget.exe", "gpresult.exe", "hostname.exe", "ipconfig.exe", "nbtstat.exe",
    "net.exe", "net1.exe", "netsh.exe", "netstat.exe", "nltest.exe", "ping.exe", "qprocess.exe", "quser.exe",
    "qwinsta.exe", "reg.exe", "sc.exe", "systeminfo.exe", "tasklist.exe", "tracert.exe", "whoami.exe"
  ) and
  process.parent.name:"wmiprvse.exe" and
  not (
    process.name : "sc.exe" and process.args : "RemoteRegistry" and process.args : "start=" and
    process.args : ("demand", "disabled")
  ) and
  not process.args : "tenable_mw_scan"

// Title: execution_html_help_executable_program_connecting_to_the_internet.toml
// Source: detection-rules::rules/windows/execution_html_help_executable_program_connecting_to_the_internet.toml
// Section: EQL Rule
// Rule Name: Network Connection via Compiled HTML File
// Author: Elastic
// Description:
// Compiled HTML files (.chm) are commonly distributed as part of the Microsoft HTML Help system. Adversaries may conceal
// malicious code in a CHM file and deliver it to a victim for execution. CHM content is loaded by the HTML Help executable
// program (hh.exe).
// Integration: endpoint, windows, sentinel_one_cloud_funnel
// Language: eql
// UUID: b29ee2be-bf99-446c-ab1a-2dc0183394b8
// Type: eql

sequence by process.entity_id
  [process where host.os.type == "windows" and process.name : "hh.exe" and event.type == "start"]
  [network where host.os.type == "windows" and process.name : "hh.exe" and
     not cidrmatch(destination.ip, "10.0.0.0/8", "127.0.0.0/8", "169.254.0.0/16", "172.16.0.0/12", "192.0.0.0/24",
       "192.0.0.0/29", "192.0.0.8/32", "192.0.0.9/32", "192.0.0.10/32", "192.0.0.170/32", "192.0.0.171/32",
       "192.0.2.0/24", "192.31.196.0/24", "192.52.193.0/24", "192.168.0.0/16", "192.88.99.0/24", "224.0.0.0/4",
       "100.64.0.0/10", "192.175.48.0/24","198.18.0.0/15", "198.51.100.0/24", "203.0.113.0/24", "240.0.0.0/4", "::1",
       "FE80::/10", "FF00::/8") and
     not dns.question.name : "localhost"]

// Title: execution_initial_access_foxmail_exploit.toml
// Source: detection-rules::rules/windows/execution_initial_access_foxmail_exploit.toml
// Section: EQL Rule
// Rule Name: Potential Foxmail Exploitation
// Author: Elastic
// Description:
// Identifies the Foxmail client spawning a child process with arguments pointing to user-profile AppData paths or remote
// shares. This may indicate exploitation of a Foxmail vulnerability for initial access and execution via a malicious email.
// Integration: endpoint, windows, system, sentinel_one_cloud_funnel, m365_defender, crowdstrike
// Language: eql
// UUID: 2c6a6acf-0dcb-404d-89fb-6b0327294cfa
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
 process.parent.name : "Foxmail.exe" and process.args : ("?:\\Users\\*\\AppData\\*", "\\\\*")

// Title: execution_initial_access_via_msc_file.toml
// Source: detection-rules::rules/windows/execution_initial_access_via_msc_file.toml
// Section: EQL Rule
// Rule Name: Unusual Execution via Microsoft Common Console File
// Author: Elastic
// Description:
// Identifies the execution of a child process from a Microsoft Common Console file. Adversaries may embed a malicious
// command in an MSC file in order to trick victims into executing malicious commands.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel
// Language: eql
// UUID: e760c72b-bb1f-44f0-9f0d-37d51744ee75
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.parent.executable : "?:\\Windows\\System32\\mmc.exe" and endswith~(process.parent.args, ".msc") and
  not (
    process.parent.args : (
      "?:\\Windows\\System32\\*.msc",
      "?:\\Windows\\SysWOW64\\*.msc",
      "?:\\Program files\\*.msc",
      "?:\\Program Files (x86)\\*.msc"
    ) or
    (
      process.executable : "?:\\Windows\\System32\\mmc.exe" and
      process.command_line : "\"C:\\WINDOWS\\system32\\mmc.exe\" \"C:\\Windows\\System32\\gpme.msc\" /s /gpobject:\"LDAP://*"
    ) or
    (
      process.executable : (
        "?:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe",
        "?:\\Program Files\\Mozilla Firefox\\firefox.exe",
        "?:\\Program Files\\Google\\Chrome\\Application\\chrome.exe",
        "?:\\Program Files\\internet explorer\\iexplore.exe"
      ) and
      process.args : "http*://go.microsoft.com/fwlink/*"
    ) or
    process.executable : (
      "?:\\Windows\\System32\\vmconnect.exe",
      "?:\\Windows\\System32\\WerFault.exe",
      "?:\\Windows\\System32\\wermgr.exe"
    )
  )

// Title: execution_initial_access_wps_dll_exploit.toml
// Source: detection-rules::rules/windows/execution_initial_access_wps_dll_exploit.toml
// Section: EQL Rule
// Rule Name: WPS Office Exploitation via DLL Hijack
// Author: Elastic
// Description:
// Identifies the load of a remote library by the WPS Office promecefpluginhost.exe executable. This may indicate the
// successful exploitation of CVE-2024-7262 or CVE-2024-7263 via DLL hijack abusing the ksoqing custom protocol handler.
// Integration: endpoint, windows
// Language: eql
// UUID: ac6bc744-e82b-41ad-b58d-90654fa4ebfb
// Type: eql

any where host.os.type == "windows" and process.name : "promecefpluginhost.exe" and
(
 (event.category == "library" and
  ?dll.path :
     ("?:\\Users\\*\\AppData\\Local\\Temp\\wps\\INetCache\\*",
      "\\Device\\Mup\\**", "\\\\*")) or

  ((event.category == "process" and event.action : "Image loaded*") and
  ?file.path :
     ("?:\\Users\\*\\AppData\\Local\\Temp\\wps\\INetCache\\*",
      "\\Device\\Mup\\**", "\\\\*"))
)

// Title: execution_java_dropped_jar_immediate_dns_lookup.toml
// Source: detection-rules::rules/windows/execution_java_dropped_jar_immediate_dns_lookup.toml
// Section: EQL Rule
// Rule Name: Java Dropped and Executed With DNS Lookup
// Author: Elastic
// Description:
// Identifies a recently dropped or modified javaw.exe process started from a user-writable path to run a JAR or Java
// classpath application, followed by a DNS lookup. Adversaries may drop Java payloads into user directories and execute
// them immediately to establish command and control while evading application control focused on native Windows
// binaries.
// Integration: endpoint
// Language: eql
// UUID: 80d7f4ef-c3b6-4466-80f4-805bdd10507d
// Type: eql

sequence by process.entity_id with maxspan=1m
 [process where host.os.type == "windows" and event.action == "start" and
  (process.Ext.relative_file_creation_time <= 500 or process.Ext.relative_file_name_modify_time <= 500) and
  (process.name : "javaw.exe" or process.pe.original_file_name == "javaw.exe") and process.executable : ("?:\\Users\\*", "?:\\ProgramData\\*", "?:\\Windows\\Temp\\*") and user.id != "S-1-5-18" and
  (
   (process.args_count == 3 and process.args : "-jar") or
   (process.args_count == 4 and process.args : ("-cp", "-classpath") and process.command_line : " *.* ")
  )]
 [network where host.os.type == "windows" and event.action: "lookup_requested"]

// Title: execution_mofcomp.toml
// Source: detection-rules::rules/windows/execution_mofcomp.toml
// Section: EQL Rule
// Rule Name: Mofcomp Activity
// Author: Elastic
// Description:
// Managed Object Format (MOF) files can be compiled locally or remotely through mofcomp.exe. Attackers may leverage MOF
// files to build their own namespaces and classes into the Windows Management Instrumentation (WMI) repository, or
// establish persistence using WMI Event Subscription.
// Integration: endpoint, m365_defender, system, crowdstrike
// Language: eql
// UUID: 210d4430-b371-470e-b879-80b7182aa75e
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.name : "mofcomp.exe" and process.args : "*.mof" and
  not user.id : "S-1-5-18" and
  not process.args : (
    "?:\\Program Files (x86)\\Microsoft Power BI Report Server\\*.mof",
    "?:\\Program Files (x86)\\Microsoft SQL Server Reporting Services\\*.mof",
    "?:\\Program Files (x86)\\Microsoft SQL Server\\*.mof",
    "?:\\Program Files\\Microsoft Policy Platform\\*.mof",
    "?:\\Program Files\\Microsoft Power BI Report Server\\*.mof",
    "?:\\Program Files\\Microsoft SQL Server Reporting Services\\*.mof",
    "?:\\Program Files\\Microsoft SQL Server\\*.mof",
    "?:\\Windows\\System32\\wbem\\com.hp.provider.*.mof",
    "?:\\Windows\\System32\\wbem\\CxAudioSvc_*.mof",
    "?:\\Windows\\System32\\wbem\\Framework\\root\\*.mof",
    "?:\\Windows\\System32\\wbem\\Veeam.Backup.*.mof",
    "?:\\Windows\\System32\\wbem\\ZTITatoo.mof",
    "?:\\Windows\\SysWOW64\\wbem\\Framework\\root\\*.mof"
  )

// Title: execution_ms_office_written_file.toml
// Source: detection-rules::rules/windows/execution_ms_office_written_file.toml
// Section: EQL Rule
// Rule Name: Execution of File Written or Modified by Microsoft Office
// Author: Elastic
// Description:
// Identifies an executable created by a Microsoft Office application and subsequently executed. These processes are often
// launched via scripts inside documents or during exploitation of Microsoft Office applications.
// Integration: endpoint
// Language: eql
// UUID: 0d8ad79f-9025-45d8-80c1-4f0cd3c5e8e5
// Type: eql

sequence with maxspan=2h
  [file where host.os.type == "windows" and event.type != "deletion" and file.extension : "exe" and
    process.name : (
      "WINWORD.EXE", "EXCEL.EXE", "OUTLOOK.EXE", "POWERPNT.EXE",
      "eqnedt32.exe", "fltldr.exe", "MSPUB.EXE", "MSACCESS.EXE"
    )
  ] by host.id, file.path
  [process where host.os.type == "windows" and event.type == "start" and 
   not (process.name : "NewOutlookInstaller.exe" and process.code_signature.subject_name : "Microsoft Corporation" and process.code_signature.trusted == true) and 
   not (process.name : "ShareFileForOutlook-v*.exe" and process.code_signature.subject_name : "Citrix Systems, Inc." and process.code_signature.trusted == true)
  ] by host.id, process.executable

// Title: execution_nodejs_susp_patterns.toml
// Source: detection-rules::rules/windows/execution_nodejs_susp_patterns.toml
// Section: EQL Rule
// Rule Name: Suspicious Execution with NodeJS
// Author: Elastic
// Description:
// Identifies suspicious Node.js execution patterns, including PowerShell-launched module preloads and inline eval,
// decode, or child-process usage.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 55f711c1-6b4d-4787-930d-c9317a885adf
// Type: eql

process where host.os.type == "windows" and event.type == "start" and

(process.name : "node.exe" or ?process.pe.original_file_name == "node.exe" or
 ?process.code_signature.subject_name : ("OpenJS Foundation", "Node.js Foundation")) and

(
  (process.args : ("-r", "--require", "--require=*") and
   process.parent.name : ("powershell.exe", "pwsh.exe")) or

  process.command_line : ("*eval(*", "*atob(*", "*require*child_process*")
)

// Title: execution_notepad_markdown_child_process.toml
// Source: detection-rules::rules/windows/execution_notepad_markdown_child_process.toml
// Section: EQL Rule
// Rule Name: Potential Notepad Markdown RCE Exploitation
// Author: Elastic
// Description:
// Identifies a process started by Notepad after opening a Markdown file. This may indicate successful exploitation of a
// Notepad markdown parsing vulnerability (CVE-2026-20841) that can lead to arbitrary code execution.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel
// Language: eql
// UUID: 7f3521dd-fb80-4548-a7eb-8db37b898dc2
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.parent.name : "notepad.exe" and process.parent.args : "*.md" and
  not process.executable : "C:\\Program Files\\WindowsApps\\Microsoft.WindowsNotepad_*\\Notepad\\Notepad.exe"

// Title: execution_posh_malicious_script_agg.toml
// Source: detection-rules::rules/windows/execution_posh_malicious_script_agg.toml
// Section: EQL Rule
// Rule Name: Potential Malicious PowerShell Based on Alert Correlation
// Author: Elastic
// Description:
// Identifies PowerShell script blocks linked to multiple distinct PowerShell detections via the same ScriptBlock ID,
// indicating compound suspicious behavior. Attackers often chain obfuscation, decoding, and execution within a single
// script block.
// Language: esql
// UUID: f770ce79-05fd-4d74-9866-1c5d66c9b34b
// Type: esql

from .alerts-security.* metadata _id

// Filter for PowerShell related alerts
| where kibana.alert.rule.name like "*PowerShell*"

// as alerts don't have non-ECS fields, parse the script block ID using grok
| grok message "ScriptBlock ID: (?<Esql.script_block_id>.+)"
| where Esql.script_block_id is not null

// keep relevant fields for further processing
| keep kibana.alert.rule.name, Esql.script_block_id, _id, user.id, process.pid, host.id

// count distinct alerts and filter for matches above the threshold
| stats
    Esql.kibana_alert_rule_name_count_distinct = count_distinct(kibana.alert.rule.name),
    Esql.kibana_alert_rule_name_values = values(kibana.alert.rule.name),
    Esql._id_values = values(_id),
    Esql.user_id_values = values(user.id),
    Esql.process_pid_values = values(process.pid),
    Esql.host_id_values = values(host.id)
  by Esql.script_block_id

// Apply detection threshold
| where Esql.kibana_alert_rule_name_count_distinct >= 5
| eval user.id = MV_MIN(Esql.user_id_values),
       process.pid = MV_MIN(Esql.process_pid_values),
       host.id = MV_MIN(Esql.host_id_values)
| keep host.id, user.id, process.pid, Esql.*

// Title: execution_powershell_susp_args_via_winscript.toml
// Source: detection-rules::rules/windows/execution_powershell_susp_args_via_winscript.toml
// Section: EQL Rule
// Rule Name: Command and Scripting Interpreter via Windows Scripts
// Author: Elastic
// Description:
// Identifies PowerShell, PowerShell ISE, or Cmd execution spawned from Windows Script Host or MSHTA.
// Integration: windows, system, sentinel_one_cloud_funnel, m365_defender, crowdstrike
// Language: eql
// UUID: 2d62889e-e758-4c5e-b57e-c735914ee32a
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.command_line != null and
  (
    process.name : ("powershell.exe", "pwsh.exe", "powershell_ise.exe", "cmd.exe") or
    ?process.pe.original_file_name : ("powershell.exe", "pwsh.dll", "powershell_ise.exe", "Cmd.Exe")
  ) and
  process.parent.name : ("wscript.exe", "mshta.exe") and
  not (
    process.args : (
      "C:\\Program Files\\Intel\\SUR\\QUEENCREEK\\x64\\task.bat",
      "\"C:\\Program Files\\Intel\\SUR\\QUEENCREEK\\x64\\task.bat\""
    ) or
    process.command_line : (
      "\"C:\\Windows\\system32\\cmd.exe\" /c auditpol.exe /set /SUBCATEGORY:*",
      "\"C:\\Windows\\system32\\cmd.exe\" /c auditpol.exe /get*",
      "\"C:\\Windows\\system32\\cmd.exe\" /c exit\""
    ) or
    (process.args == "-File" and process.args == "-ExecutionPolicy")
  )
  and 
  not (
    ?user.id == "S-1-5-18" and
    /* Don't apply the user.id exclusion to Sysmon for compatibility */
    not data_stream.dataset : ("windows.sysmon_operational", "windows.sysmon")
  )

// Title: execution_psexec_lateral_movement_command.toml
// Source: detection-rules::rules/windows/execution_psexec_lateral_movement_command.toml
// Section: EQL Rule
// Rule Name: PsExec Network Connection
// Author: Elastic
// Description:
// Identifies use of the SysInternals tool PsExec.exe making a network connection. This could be an indication of lateral
// movement.
// Integration: endpoint, windows, sentinel_one_cloud_funnel
// Language: eql
// UUID: 55d551c6-333b-4665-ab7e-5d14a59715ce
// Type: eql

sequence by process.entity_id
  [process where host.os.type == "windows" and event.type == "start" and
   (process.name : "PsExec.exe" or ?process.pe.original_file_name : "psexec.c") and

   /* This flag suppresses the display of the license dialog and may
      indicate that psexec executed for the first time in the machine */
   process.args : "-accepteula" and

   not process.executable : ("?:\\ProgramData\\Docusnap\\Discovery\\discovery\\plugins\\17\\Bin\\psexec.exe",
                             "?:\\Docusnap 11\\Bin\\psexec.exe",
                             "?:\\Program Files\\Docusnap X\\Bin\\psexec.exe",
                             "?:\\Program Files\\Docusnap X\\Tools\\dsDNS.exe") and
   not process.parent.executable : "?:\\Program Files (x86)\\Cynet\\Cynet Scanner\\CynetScanner.exe"]
  [network where host.os.type == "windows"]

// Title: execution_register_server_program_connecting_to_the_internet.toml
// Source: detection-rules::rules/windows/execution_register_server_program_connecting_to_the_internet.toml
// Section: EQL Rule
// Rule Name: Network Connection via Registration Utility
// Author: Elastic
// Description:
// Identifies the native Windows tools regsvr32.exe, regsvr64.exe, RegSvcs.exe, or RegAsm.exe making a network connection.
// This may be indicative of an attacker bypassing allowlists or running arbitrary scripts via a signed Microsoft binary.
// Integration: endpoint, windows
// Language: eql
// UUID: fb02b8d3-71ee-4af1-bacd-215d23f17efa
// Type: eql

sequence by process.entity_id
  [process where host.os.type == "windows" and event.type == "start" and
   process.name : ("regsvr32.exe", "RegAsm.exe", "RegSvcs.exe") and
   not (
         (?process.Ext.token.integrity_level_name : "System" or ?winlog.event_data.IntegrityLevel : "System") and
         (process.parent.name : "msiexec.exe" or process.parent.executable : ("C:\\Program Files (x86)\\*.exe", "C:\\Program Files\\*.exe"))
       )
   ]
  [network where host.os.type == "windows" and process.name : ("regsvr32.exe", "RegAsm.exe", "RegSvcs.exe")  and
   not cidrmatch(destination.ip, "10.0.0.0/8", "127.0.0.0/8", "169.254.0.0/16", "172.16.0.0/12", "192.0.0.0/24",
       "192.0.0.0/29", "192.0.0.8/32", "192.0.0.9/32", "192.0.0.10/32", "192.0.0.170/32", "192.0.0.171/32",
       "192.0.2.0/24", "192.31.196.0/24", "192.52.193.0/24", "192.168.0.0/16", "192.88.99.0/24", "224.0.0.0/4",
       "100.64.0.0/10", "192.175.48.0/24","198.18.0.0/15", "198.51.100.0/24", "203.0.113.0/24", "240.0.0.0/4", "::1",
       "FE80::/10", "FF00::/8") and network.protocol != "dns"]

// Title: execution_revshell_cmd_via_netcat.toml
// Source: detection-rules::rules/windows/execution_revshell_cmd_via_netcat.toml
// Section: EQL Rule
// Rule Name: Potential Command Shell via NetCat
// Author: Elastic
// Description:
// Identifies potential attempt to execute via a reverse shell using the netcat utility to execute Windows commands using
// the default interpreters like Cmd.exe and Powershell.
// Integration: endpoint
// Language: eql
// UUID: 9c0f61fa-abf4-4b11-8d9d-5978c09182dd
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
process.name : ("cmd.exe", "powershell.exe") and process.parent.args : "-e" and
 (
  (process.parent.args_count == 5 and process.parent.command_line regex~ """.*[0-9]{1,3}(\.[0-9]{1,3}){3}.*""") or
  (process.parent.args : "-*l*" and process.parent.args : "-*p*" and process.parent.args : ("cmd.exe", "powershell.exe"))
  )

// Title: execution_scheduled_task_powershell_source.toml
// Source: detection-rules::rules/windows/execution_scheduled_task_powershell_source.toml
// Section: EQL Rule
// Rule Name: Outbound Scheduled Task Activity via PowerShell
// Author: Elastic
// Description:
// Identifies the PowerShell process loading the Task Scheduler COM DLL followed by an outbound RPC network connection
// within a short time period. This may indicate lateral movement or remote discovery via scheduled tasks.
// Integration: endpoint, windows
// Language: eql
// UUID: 5cd55388-a19c-47c7-8ec4-f41656c2fded
// Type: eql

sequence by host.id, process.entity_id with maxspan = 5s
 [any where host.os.type == "windows" and (event.category == "library" or (event.category == "process" and event.action : "Image loaded*")) and
  (?dll.name : "taskschd.dll" or file.name : "taskschd.dll") and process.name : ("powershell.exe", "pwsh.exe", "powershell_ise.exe")]
 [network where host.os.type == "windows" and process.name : ("powershell.exe", "pwsh.exe", "powershell_ise.exe") and destination.port == 135 and not cidrmatch(destination.ip, "127.0.0.0/8", "::1/128")]

// Title: execution_scripting_remote_webdav.toml
// Source: detection-rules::rules/windows/execution_scripting_remote_webdav.toml
// Section: EQL Rule
// Rule Name: Suspicious Execution from a WebDav Share
// Author: Elastic
// Description:
// Identifies attempts to execute or invoke content from remote WebDAV shares. Adversaries may abuse WebDAV paths,
// public tunnels, or host@port UNC paths to run tools or scripts while reducing local staging on the victim file system.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: ee7726cc-babc-4885-988c-f915173ac0c0
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
 process.name : ("cmd.exe", "powershell.exe", "conhost.exe", "wscript.exe", "mshta.exe", "curl.exe", "msiexec.exe", "bitsadmin.exe", "net.exe") and
 process.command_line : ("*trycloudflare.com*", "*@SSL\\*", "*\\webdav\\*", "*\\DavWWWRoot\\*", "*\\\\*.*@8080\\*", "*\\\\*.*@80\\*", "*\\\\*.*@8443\\*", "*\\\\*.*@443\\*") and
 not (process.name : "cmd.exe" and process.args : "\\\\?\\UNC\\*.sharepoint.com@SSL\\DavWWWRoot\\*")

// Title: execution_scripts_archive_file.toml
// Source: detection-rules::rules/windows/execution_scripts_archive_file.toml
// Section: EQL Rule
// Rule Name: Windows Script Execution from Archive
// Author: Elastic
// Description:
// Identifies attempts to execute Jscript/Vbscript files from an archive file. The use of archives is a common delivery method
// of malicious scripts.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 30f9d940-7d55-4fff-a8b9-4715d20eb204
// Type: eql

process where host.os.type == "windows" and event.type == "start" and process.name : "wscript.exe" and
 process.parent.name : ("explorer.exe", "winrar.exe", "7zFM.exe") and
 process.args :
        ("?:\\Users\\*\\AppData\\Local\\Temp\\7z*\\*",
         "?:\\Users\\*\\AppData\\Local\\Temp\\*.zip.*\\*",
         "?:\\Users\\*\\AppData\\Local\\Temp\\Rar$*\\*",
         "?:\\Users\\*\\AppData\\Local\\Temp\\Temp?_*\\*",
         "?:\\Users\\*\\AppData\\Local\\Temp\\BNZ.*")

// Title: execution_shared_modules_local_sxs_dll.toml
// Source: detection-rules::rules/windows/execution_shared_modules_local_sxs_dll.toml
// Section: EQL Rule
// Rule Name: Execution via local SxS Shared Module
// Author: Elastic
// Description:
// Identifies the creation, change, or deletion of a DLL module within a Windows SxS local folder. Adversaries may abuse
// shared modules to execute malicious payloads by instructing the Windows module loader to load DLLs from arbitrary local
// paths.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: a3ea12f3-0d4e-4667-8b44-4230c63f3c75
// Type: eql

file where host.os.type == "windows" and file.extension : "dll" and
  file.path : (
    "C:\\*\\*.exe.local\\*.dll",
    /* Crowdstrike specific condition as it uses NT Object paths */
    "\\Device\\HarddiskVolume*\\*\\*.exe.local\\*.dll"
  )

// Title: execution_susp_javascript_via_deno.toml
// Source: detection-rules::rules/windows/execution_susp_javascript_via_deno.toml
// Section: EQL Rule
// Rule Name: Suspicious JavaScript Execution via Deno
// Author: Elastic
// Description:
// Detects execution of JavaScript via Deno with suspicious command-line patterns (base64, eval, http, or import in a
// javascript context). Adversaries may abuse Deno to run malicious JavaScript for execution or staging.
// Integration: endpoint, windows, sentinel_one_cloud_funnel, m365_defender, system, crowdstrike
// Language: eql
// UUID: ff18d24b-2ba6-4691-a17f-75c4380d0965
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
 (process.name : "deno.exe" or ?process.pe.original_file_name == "deno.exe" or ?process.code_signature.subject_name == "Deno Land Inc.") and
 process.command_line : ("*javascript*base64*", "*eval(*", "*http*", "*javascript*import*")

// Title: execution_suspicious_cmd_wmi.toml
// Source: detection-rules::rules/windows/execution_suspicious_cmd_wmi.toml
// Section: EQL Rule
// Rule Name: Suspicious Cmd Execution via WMI
// Author: Elastic
// Description:
// Identifies suspicious command execution (cmd) via Windows Management Instrumentation (WMI) on a remote host. This could
// be indicative of adversary lateral movement.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 12f07955-1674-44f7-86b5-c35da0a6f41a
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
 process.parent.name : "WmiPrvSE.exe" and process.name : "cmd.exe" and process.args : "/c" and process.args:"/Q" and 
 process.args : "2>&1" and process.args: "1>"  and 
 process.args : ("C:\\windows\\temp\\*.txt", "\\Windows\\Temp\\*", "-encodehex", "\\\\127.0.0.1\\C$\\Windows\\Temp\\*", "\\\\127.0.0.1\\ADMIN$\\__*.*")

// Title: execution_suspicious_image_load_wmi_ms_office.toml
// Source: detection-rules::rules/windows/execution_suspicious_image_load_wmi_ms_office.toml
// Section: EQL Rule
// Rule Name: Suspicious WMI Image Load from MS Office
// Author: Elastic
// Description:
// Identifies a suspicious image load (wmiutils.dll) from Microsoft Office processes. This behavior may indicate
// adversarial activity where child processes are spawned via Windows Management Instrumentation (WMI). This technique can
// be used to execute code and evade traditional parent/child processes spawned from Microsoft Office products.
// Integration: endpoint, windows
// Language: eql
// UUID: 891cb88e-441a-4c3e-be2d-120d99fe7b0d
// Type: eql

any where host.os.type == "windows" and
 (event.category : ("library", "driver") or (event.category == "process" and event.action : "Image loaded*")) and
  process.name : ("WINWORD.EXE", "EXCEL.EXE", "POWERPNT.EXE", "MSPUB.EXE", "MSACCESS.EXE") and
  (?dll.name : "wmiutils.dll" or file.name : "wmiutils.dll")

// Title: execution_suspicious_pdf_reader.toml
// Source: detection-rules::rules/windows/execution_suspicious_pdf_reader.toml
// Section: EQL Rule
// Rule Name: Suspicious PDF Reader Child Process
// Author: Elastic
// Description:
// Identifies suspicious child processes of PDF reader applications. These child processes are often launched via
// exploitation of PDF applications or social engineering.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 53a26770-9cbd-40c5-8b57-61d01a325e14
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.parent.name : ("AcroRd32.exe",
                         "Acrobat.exe",
                         "FoxitPhantomPDF.exe",
                         "FoxitReader.exe") and
  process.name : ("arp.exe", "dsquery.exe", "dsget.exe", "gpresult.exe", "hostname.exe", "ipconfig.exe", "nbtstat.exe",
                  "net.exe", "net1.exe", "netsh.exe", "netstat.exe", "nltest.exe", "ping.exe", "qprocess.exe",
                  "quser.exe", "qwinsta.exe", "reg.exe", "sc.exe", "systeminfo.exe", "tasklist.exe", "tracert.exe",
                  "whoami.exe", "bginfo.exe", "cdb.exe", "cmstp.exe", "csi.exe", "dnx.exe", "fsi.exe", "ieexec.exe",
                  "iexpress.exe", "installutil.exe", "Microsoft.Workflow.Compiler.exe", "msbuild.exe", "mshta.exe",
                  "msxsl.exe", "odbcconf.exe", "rcsi.exe", "regsvr32.exe", "xwizard.exe", "atbroker.exe",
                  "forfiles.exe", "schtasks.exe", "regasm.exe", "regsvcs.exe", "cmd.exe", "cscript.exe",
                  "powershell.exe", "pwsh.exe", "wmic.exe", "wscript.exe", "bitsadmin.exe", "certutil.exe", "ftp.exe")

// Title: execution_suspicious_psexesvc.toml
// Source: detection-rules::rules/windows/execution_suspicious_psexesvc.toml
// Section: EQL Rule
// Rule Name: Suspicious Process Execution via Renamed PsExec Executable
// Author: Elastic
// Description:
// Identifies suspicious psexec activity which is executing from the psexec service that has been renamed, possibly to
// evade detection.
// Integration: endpoint, windows, m365_defender, crowdstrike
// Language: eql
// UUID: e2f9fdf5-8076-45ad-9427-41e0e03dc9c2
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.pe.original_file_name : "psexesvc.exe" and not process.name : "PSEXESVC.exe"

// Title: execution_via_compiled_html_file.toml
// Source: detection-rules::rules/windows/execution_via_compiled_html_file.toml
// Section: EQL Rule
// Rule Name: Process Activity via Compiled HTML File
// Author: Elastic
// Description:
// Compiled HTML files (.chm) are commonly distributed as part of the Microsoft HTML Help system. Adversaries may conceal
// malicious code in a CHM file and deliver it to a victim for execution. CHM content is loaded by the HTML Help executable
// program (hh.exe).
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: e3343ab9-4245-4715-b344-e11c56b0a47f
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
 process.parent.name : "hh.exe" and
 process.name : ("mshta.exe", "cmd.exe", "powershell.exe", "pwsh.exe", "powershell_ise.exe", "cscript.exe", "wscript.exe")

// Title: execution_via_hidden_shell_conhost.toml
// Source: detection-rules::rules/windows/execution_via_hidden_shell_conhost.toml
// Section: EQL Rule
// Rule Name: Conhost Spawned By Suspicious Parent Process
// Author: Elastic
// Description:
// Detects when the Console Window Host (conhost.exe) process is spawned by a suspicious parent process, which could be
// indicative of code injection.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel
// Language: eql
// UUID: 05b358de-aa6d-4f6c-89e6-78f74018b43b
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.name : "conhost.exe" and
  process.parent.name : ("lsass.exe", "services.exe", "smss.exe", "winlogon.exe", "explorer.exe", "dllhost.exe", "rundll32.exe",
                         "regsvr32.exe", "userinit.exe", "wininit.exe", "spoolsv.exe", "ctfmon.exe") and
  not (process.parent.name : "rundll32.exe" and
       process.parent.args : ("?:\\Windows\\Installer\\MSI*.tmp,zzzzInvokeManagedCustomActionOutOfProc",
                              "?:\\WINDOWS\\system32\\PcaSvc.dll,PcaPatchSdbTask",
                              "?:\\WINDOWS\\system32\\davclnt.dll,DavSetCookie"))

// Title: execution_via_mmc_console_file_unusual_path.toml
// Source: detection-rules::rules/windows/execution_via_mmc_console_file_unusual_path.toml
// Section: EQL Rule
// Rule Name: Microsoft Management Console File from Unusual Path
// Author: Elastic
// Description:
// Identifies attempts to open a Microsoft Management Console File from untrusted paths. Adversaries may use MSC files for
// initial access and execution.
// Integration: endpoint, windows, sentinel_one_cloud_funnel, m365_defender, system, crowdstrike
// Language: eql
// UUID: 7e23dfef-da2c-4d64-b11d-5f285b638853
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.executable : (
    "?:\\Windows\\System32\\mmc.exe",

    /* Crowdstrike specific condition as it uses NT Object paths */
    "\\Device\\HarddiskVolume*\\Windows\\System32\\mmc.exe"
  ) and
  process.args : "*.msc" and
  not process.args : (
        "?:\\Windows\\System32\\*.msc",
        "?:\\Windows\\SysWOW64\\*.msc",
        "?:\\Program files\\*.msc",
        "?:\\Program Files (x86)\\*.msc",
        "?:\\Windows\\ADFS\\Microsoft.IdentityServer.msc"
  ) and
  not process.command_line : (
    "C:\\Windows\\system32\\mmc.exe eventvwr.msc /s",
    "mmc.exe eventvwr.msc /s",
    "\"C:\\Windows\\System32\\mmc.exe\" CompMgmt.msc*"
  )

// Title: execution_windows_fakecaptcha_cmd_ps.toml
// Source: detection-rules::rules/windows/execution_windows_fakecaptcha_cmd_ps.toml
// Section: EQL Rule
// Rule Name: Potential Fake CAPTCHA Phishing Attack
// Author: Elastic
// Description:
// Identifies potential fake CAPTCHA phishing attacks based on PowerShell, Cmd, or Mshta command-line values. Adversaries employ this
// technique via compromised websites with browser injects, posing either as fake CAPTCHAs to access the site or as a page
// loading error requiring a fix to display the page. The victim is instructed to copy and paste a malicious command to
// the Windows Run dialog box.
// Integration: endpoint, windows, system, sentinel_one_cloud_funnel, m365_defender, crowdstrike
// Language: eql
// UUID: fbad57ec-4442-48db-a34f-5ee907b44a22
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
 process.name : ("powershell.exe", "cmd.exe", "mshta.exe") and process.parent.name : "explorer.exe" and
 process.command_line : ("*recaptcha *", "*CAPTCHA Verif*", "*complete verification*", "*Verification ID*", "*Verification Code*", "*Verification UID*",
                         "*hυmаn vаlіdаtiοn*", "*human ID*", "*Action Identificator*", "*not a robot*", "*Click OK to*", "*anti-robot test*",
                         "*Cloudflare ID*")

// Title: execution_windows_phish_clickfix.toml
// Source: detection-rules::rules/windows/execution_windows_phish_clickfix.toml
// Section: EQL Rule
// Rule Name: Potential Execution via FileFix Phishing Attack
// Author: Elastic
// Description:
// Identifies the execution of Windows commands or downloaded files via the browser's dialog box. Adversaries may use
// phishing to instruct the victim to copy and paste malicious commands for execution via crafted phishing web pages.
// Integration: endpoint, windows, sentinel_one_cloud_funnel, m365_defender
// Language: eql
// UUID: 7dc45430-7407-4790-b89e-c857c3f6bf23
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
 process.parent.args == "--message-loop-type-ui" and process.parent.args == "--service-sandbox-type=none" and
 (
  process.name : ("pwsh.exe", "powershell.exe", "curl.exe", "msiexec.exe", "mshta.exe", "wscript.exe", "cscript.exe", "rundll32.exe", "certutil.exe", "certreq.exe") or
  process.executable : "?:\\Users\\*\\Downloads\\*"
  ) and
not (process.name : "rundll32.exe" and process.args : ("ndfapi.dll,NdfRunDllDiagnoseWithAnswerFile", "shwebsvc.dll,AddNetPlaceRunDll"))

// Title: execution_windows_script_from_internet.toml
// Source: detection-rules::rules/windows/execution_windows_script_from_internet.toml
// Section: EQL Rule
// Rule Name: Execution of a Downloaded Windows Script
// Author: Elastic
// Description:
// Identifies the creation of a Windows script downloaded from the internet followed by the execution of a scripting utility.
// Adversaries may use Windows script files for initial access and execution.
// Integration: endpoint
// Language: eql
// UUID: 79543b00-28a5-4461-81ac-644c4dc4012f
// Type: eql

sequence by host.id, user.id with maxspan=3m
[file where host.os.type == "windows" and event.action == "creation" and user.id != "S-1-5-18" and
  process.name : ("chrome.exe", "msedge.exe", "brave.exe", "browser.exe", "dragon.exe", "vivaldi.exe", "explorer.exe", "winrar.exe", "7zFM.exe", "7zG.exe", "Bandizip.exe") and
  file.extension in~ ("js", "jse", "vbs", "vbe", "wsh", "wsf", "sct", "hta", "cmd", "bat", "ps1", "msi") and
  (file.origin_url != null or file.origin_referrer_url != null)]
[process where host.os.type == "windows" and event.type == "start" and
 process.parent.name : ("chrome.exe", "msedge.exe", "brave.exe", "firefox.exe", "browser.exe", "dragon.exe", "vivaldi.exe", "explorer.exe", "winrar.exe", "7zFM.exe", "7zG.exe", "Bandizip.exe") and 
 process.args_count >= 2 and
 (
  process.name in~ ("wscript.exe", "cscript.exe", "mshta.exe") or
  (process.name : "cmd.exe" and process.command_line : ("*.cmd*", "*.bat*", "*.wsf*")) or
  (process.name in~ ("powershell.exe", "pwsh.exe") and process.command_line : "*.ps1*") or 
  (process.name : "msiexec.exe" and process.command_line : "*.msi" and process.args : ("/i*", "-i*"))
  )]

// Title: exfiltration_excessive_dns_queries_by_process.toml
// Source: detection-rules::rules/windows/exfiltration_excessive_dns_queries_by_process.toml
// Section: EQL Rule
// Rule Name: Potential DNS Exfiltration via Excessive Chunked Queries
// Author: Elastic
// Description:
// Identifies potential DNS exfiltration on Windows hosts by detecting a high volume of DNS queries whose subdomain labels
// follow a chunked encoding pattern (index-payload.base_domain). Attackers split stolen data across many DNS queries to
// evade volume-based detection; this rule aggregates queries per process, base domain, and five-minute window and flags
// sessions with many distinct chunk indices and sufficiently long encoded payloads.
// Integration: endpoint, windows, crowdstrike
// Language: esql
// UUID: 882a39ad-a404-45e3-b5d4-bc11d2b09818
// Type: esql

FROM logs-crowdstrike.fdr*, logs-endpoint.events.network-*, logs-windows.sysmon_operational-*
| WHERE host.os.type == "windows"
    AND event.category == "network"
    AND event.action IN ("lookup_requested", "DNSEvent (DNS query)", "DnsRequest")
    AND process.name != "svchost.exe"
    AND dns.question.name RLIKE """[0-9]{1,5}-[A-Za-z0-9+/=]{15,63}\..+"""
| GROK dns.question.name "%{INT:chunk_index}-%{DATA:chunk_payload}\\.%{GREEDYDATA:Esql.base_domain}"
| WHERE chunk_index IS NOT NULL
| EVAL payload_len = LENGTH(chunk_payload)
| STATS
    Esql.occurrences = COUNT(*),
    Esql.unique_chunks = COUNT_DISTINCT(chunk_index),
    Esql.max_index = MAX(TO_INTEGER(chunk_index)),
    Esql.avg_payload_len = AVG(payload_len)
  BY process.name, Esql.base_domain, user.id, user.name, host.id, host.name, data_stream.namespace, DATE_TRUNC(5 minutes, @timestamp)
| WHERE Esql.occurrences >= 30
    AND Esql.unique_chunks >= 30
    AND Esql.avg_payload_len >= 20
| SORT Esql.unique_chunks DESC
| LIMIT 20
| KEEP host.id, host.name, process.name, user.id, user.name, data_stream.namespace, Esql.*

// Title: exfiltration_rclone_cloud_upload.toml
// Source: detection-rules::rules/windows/exfiltration_rclone_cloud_upload.toml
// Section: EQL Rule
// Rule Name: Potential Data Exfiltration via Rclone
// Author: Elastic
// Description:
// Identifies abuse of rclone (or a renamed copy, e.g. disguised as a security or backup utility) to exfiltrate data to
// cloud storage or remote endpoints. Rclone is a legitimate file sync tool; threat actors rename it to blend with
// administrative traffic and use copy/sync with cloud backends (e.g. :s3:) and include filters to exfiltrate specific
// file types.
// Integration: endpoint, windows, sentinel_one_cloud_funnel, m365_defender, system, crowdstrike
// Language: eql
// UUID: 3f4c2b18-9d2e-4b7a-a3c1-8e6d9f2b5c7e
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
 (process.name : "rclone.exe" or ?process.pe.original_file_name == "rclone.exe") and process.args : ("copy", "sync") and
  not process.args : ("--config=?:\\Program Files\\rclone\\config\\rclone\\rclone.conf", "--config=?:\\Program Files (x86)\\rclone\\config\\rclone\\rclone.conf") and 
  not process.executable : ("?:\\Program Files*", "\\Device\\HarddiskVolume*\\Program Files*")

// Title: impact_backup_file_deletion.toml
// Source: detection-rules::rules/windows/impact_backup_file_deletion.toml
// Section: EQL Rule
// Rule Name: Third-party Backup Files Deleted via Unexpected Process
// Author: Elastic
// Description:
// Identifies the deletion of backup files, saved using third-party software, by a process outside of the backup suite.
// Adversaries may delete Backup files to ensure that recovery from a ransomware attack is less likely.
// Integration: endpoint, sentinel_one_cloud_funnel
// Language: eql
// UUID: 11ea6bec-ebde-4d71-a8e9-784948f8e3e9
// Type: eql

file where host.os.type == "windows" and event.type == "deletion" and
  (
    /* Veeam Related Backup Files */
    (
      file.extension : ("VBK", "VIB", "VBM") and
      not (
        process.executable : ("?:\\Windows\\*", "?:\\Program Files\\*", "?:\\Program Files (x86)\\*") and
        (process.code_signature.trusted == true and process.code_signature.subject_name : ("Veeam Software Group GmbH", "Veeam Software AG"))
      )
    ) or
    /* Veritas Backup Exec Related Backup File */
    (
      file.extension : "BKF" and
        not process.executable : (
          "?:\\Program Files\\Veritas\\Backup Exec\\*",
          "?:\\Program Files (x86)\\Veritas\\Backup Exec\\*"
        )
    )
  ) and
  not (
    process.name : ("MSExchangeMailboxAssistants.exe", "Microsoft.PowerBI.EnterpriseGateway.exe") and
      (process.code_signature.subject_name : "Microsoft Corporation" and process.code_signature.trusted == true)
  ) and
  not file.path : (
    "?:\\ProgramData\\Trend Micro\\*",
    "?:\\Program Files (x86)\\Trend Micro\\*",
    "?:\\$RECYCLE.BIN\\*"
  )

// Title: impact_deleting_backup_catalogs_with_wbadmin.toml
// Source: detection-rules::rules/windows/impact_deleting_backup_catalogs_with_wbadmin.toml
// Section: EQL Rule
// Rule Name: Backup Deletion with Wbadmin
// Author: Elastic
// Description:
// Detects use of wbadmin.exe to delete backup catalogs, system state backups, or other backup data. Ransomware and other
// malware may do this to prevent system recovery.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 581add16-df76-42bb-af8e-c979bfb39a59
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  (process.name : "wbadmin.exe" or ?process.pe.original_file_name == "WBADMIN.EXE") and
  process.args : ("catalog", "backup", "systemstatebackup") and process.args : "delete"

// Title: impact_high_freq_file_renames_by_kernel.toml
// Source: detection-rules::rules/windows/impact_high_freq_file_renames_by_kernel.toml
// Section: EQL Rule
// Rule Name: Potential Ransomware Behavior - Note Files by System
// Author: Elastic
// Description:
// This rule identifies the creation of multiple files with same name and over SMB by the same user. This behavior may indicate the 
// successful remote execution of a ransomware dropping file notes to different folders.
// Integration: endpoint
// Language: esql
// UUID: 1397e1b9-0c90-4d24-8d7b-80598eb9bc9a
// Type: esql

from logs-endpoint.events.file-* metadata _id, _version, _index

// filter for file creation event done remotely over SMB with common user readable file types used to place ransomware notes
| where event.category == "file" and host.os.type == "windows" and event.action == "creation" and process.pid == 4 and user.id != "S-1-5-18" and 
  file.extension in ("txt", "htm", "html", "hta", "pdf", "jpg", "bmp", "png") and
  to_lower(file.path) like """c:\\*""" and not to_lower(file.path) like """c:\\temp\\*"""

// truncate the timestamp to a 60-second window
| eval Esql.time_window_date_trunc = date_trunc(60 seconds, @timestamp)

| keep user.id, user.name, file.path, file.name, process.entity_id, Esql.time_window_date_trunc, host.name, host.ip, host.id

// filter for same file name dropped in at least 3 unique paths by the System virtual process
| stats Esql.file_path_count_distinct = COUNT_DISTINCT(file.path),  Esql.file_path_values = VALUES(file.path), Esql.host_ip_values = values(host.ip) by host.id, host.name, user.name, user.id, process.entity_id , file.name, Esql.time_window_date_trunc
| where Esql.file_path_count_distinct >= 3

// Title: impact_mod_critical_os_files.toml
// Source: detection-rules::rules/windows/impact_mod_critical_os_files.toml
// Section: EQL Rule
// Rule Name: Potential System Tampering via File Modification
// Author: Elastic
// Description:
// Identifies attempts to delete or modify critical files used during the boot process to prevent the system from booting.
// This may indicate a destructive attack behavior.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel
// Language: eql
// UUID: 1a3f2a4c-12d0-4b88-961a-2711ee295637
// Type: eql

file where host.os.type == "windows" and event.type in ("change", "deletion") and
  file.name : ("winload.exe", "winload.efi", "ntoskrnl.exe", "bootmgr") and
  file.path : ("?:\\Windows\\*", "\\Device\\HarddiskVolume*\\Windows\\*") and
  not process.executable : (
    "?:\\Windows\\System32\\poqexec.exe",
    "?:\\Windows\\System32\\wbengine.exe",
    "?:\\Windows\\WinSxS\\???64_microsoft-windows-servicingstack_*\\tiworker.exe"
  ) and
  not file.path : (
    "?:\\Windows\\WinSxS\\Temp\\InFlight\\*",
    "?:\\Windows\\SoftwareDistribution\\Download*",
    "?:\\Windows\\WinSxS\\amd64_microsoft-windows*",
    "?:\\Windows\\SystemTemp\\*",
    "?:\\Windows\\Temp\\????????.???\\*",
    "?:\\Windows\\Temp\\*\\amd64_microsoft-windows-*",
    "\\Device\\HarddiskVolume*\\Windows\\SoftwareDistribution\\Download*",
    "?:\\Windows\\Temp\\BootImages\\{*}\\mount\\Windows\\*"
  )

// Title: impact_modification_of_boot_config.toml
// Source: detection-rules::rules/windows/impact_modification_of_boot_config.toml
// Section: EQL Rule
// Rule Name: Modification of Boot Configuration
// Author: Elastic
// Description:
// Identifies use of bcdedit.exe to delete boot configuration data. This tactic is sometimes used as by malware or an
// attacker as a destructive technique.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 69c251fb-a5d6-4035-b5ec-40438bd829ff
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  (process.name : "bcdedit.exe" or ?process.pe.original_file_name == "bcdedit.exe") and
    (
      (process.args : "/set" and process.args : "bootstatuspolicy" and process.args : "ignoreallfailures") or
      (process.args : "no" and process.args : "recoveryenabled")
    )

// Title: impact_ransomware_file_rename_smb.toml
// Source: detection-rules::rules/windows/impact_ransomware_file_rename_smb.toml
// Section: EQL Rule
// Rule Name: Suspicious File Renamed via SMB
// Author: Elastic
// Description:
// Identifies suspicious file rename operation by the virtual System process. This may indicate a remote ransomware attack via the SMB protocol.
// Integration: endpoint
// Language: eql
// UUID: 78e9b5d5-7c07-40a7-a591-3dbbf464c386
// Type: eql

sequence by host.id, file.extension with maxspan=1s
 [file where host.os.type == "windows" and
  event.action == "rename" and process.pid == 4 and user.id : ("S-1-5-21*", "S-1-12-*") and
  file.extension != null and file.Ext.entropy >= 6 and file.path : "C:\\Users\\*" and
  file.Ext.original.name : ("*.jpg", "*.bmp", "*.png", "*.pdf", "*.doc", "*.docx", "*.xls", "*.xlsx", "*.ppt", "*.pptx", "*.lnk") and
  not file.extension : ("jpg", "bmp", "png", "pdf", "doc", "docx", "xls", "xlsx", "ppt", "pptx", "lnk")] with runs=3

// Title: impact_ransomware_note_file_over_smb.toml
// Source: detection-rules::rules/windows/impact_ransomware_note_file_over_smb.toml
// Section: EQL Rule
// Rule Name: Potential Ransomware Note File Dropped via SMB
// Author: Elastic
// Description:
// Identifies the creation of a file with a name similar to ransomware note files by the Windows System process (PID 4). This may indicate a remote ransomware attack via the SMB protocol.
// Integration: endpoint
// Language: eql
// UUID: 02bab13d-fb14-4d7c-b6fe-4a28874d37c5
// Type: eql

sequence by host.id, file.name with maxspan=1m
 [file where host.os.type == "windows" and event.action == "creation" and
  process.pid == 4 and user.id : ("S-1-5-21*", "S-1-12-*") and file.extension : ("hta", "txt", "readme", "htm*") and
   /* ransom file name keywords */
    file.name : ("*read*me*", "*lock*", "*@*", "*RECOVER*", "*decrypt*", "*restore*file*", "*FILES_BACK*", "*how*to*") and 
    (file.path : ("C:\\Users\\*", "C:\\aaAntiRansom*") or (file.path : "C:\\*" and not file.path : "C:\\*\\*"))] with runs=3

// Title: impact_volume_shadow_copy_deletion_or_resized_via_vssadmin.toml
// Source: detection-rules::rules/windows/impact_volume_shadow_copy_deletion_or_resized_via_vssadmin.toml
// Section: EQL Rule
// Rule Name: Volume Shadow Copy Deleted or Resized via VssAdmin
// Author: Elastic
// Description:
// Identifies use of vssadmin.exe for shadow copy deletion or resizing on endpoints. This commonly occurs in tandem with
// ransomware or other destructive attacks.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: b5ea4bfe-a1b2-421f-9d47-22a75a6f2921
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  (process.name : "vssadmin.exe" or ?process.pe.original_file_name == "VSSADMIN.EXE") and
  process.args : ("delete", "resize") and process.args : "shadows*"

// Title: impact_volume_shadow_copy_deletion_via_powershell.toml
// Source: detection-rules::rules/windows/impact_volume_shadow_copy_deletion_via_powershell.toml
// Section: EQL Rule
// Rule Name: Volume Shadow Copy Deletion via PowerShell
// Author: Elastic, Austin Songer
// Description:
// Identifies the use of the Win32_ShadowCopy class and related cmdlets to achieve shadow copy deletion. This commonly
// occurs in tandem with ransomware or other destructive attacks.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: d99a037b-c8e2-47a5-97b9-170d076827c4
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.name : ("powershell.exe", "pwsh.exe", "powershell_ise.exe") and
  process.args : ("*Get-WmiObject*", "*gwmi*", "*Get-CimInstance*", "*gcim*") and
  process.args : ("*Win32_ShadowCopy*") and
  process.args : ("*.Delete()*", "*Remove-WmiObject*", "*rwmi*", "*Remove-CimInstance*", "*rcim*")

// Title: impact_volume_shadow_copy_deletion_via_wmic.toml
// Source: detection-rules::rules/windows/impact_volume_shadow_copy_deletion_via_wmic.toml
// Section: EQL Rule
// Rule Name: Volume Shadow Copy Deletion via WMIC
// Author: Elastic
// Description:
// Identifies use of wmic.exe for shadow copy deletion on endpoints. This commonly occurs in tandem with ransomware or
// other destructive attacks.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: dc9c1f74-dac3-48e3-b47f-eb79db358f57
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  (process.name : "WMIC.exe" or ?process.pe.original_file_name == "wmic.exe") and
  process.args : "delete" and process.args : "shadowcopy"

// Title: initial_access_evasion_suspicious_htm_file_creation.toml
// Source: detection-rules::rules/windows/initial_access_evasion_suspicious_htm_file_creation.toml
// Section: EQL Rule
// Rule Name: Suspicious HTML File Creation
// Author: Elastic
// Description:
// Identifies the execution of a browser process to open an HTML file with high entropy and size. Adversaries may smuggle
// data and files past content filters by hiding malicious payloads inside of seemingly benign HTML files.
// Integration: endpoint
// Language: eql
// UUID: f0493cb4-9b15-43a9-9359-68c23a7f2cf3
// Type: eql

sequence by user.id with maxspan=2m

 [file where host.os.type == "windows" and event.action in ("creation", "rename") and

  /* Check for HTML files with high entropy and size */
  file.extension : ("htm", "html") and ((file.Ext.entropy >= 5 and file.size >= 150000) or file.size >= 1000000) and

  /* Check for file paths in common download and temporary directories */
  file.path : (
    "?:\\Users\\*\\Downloads\\*",
    "?:\\Users\\*\\Content.Outlook\\*",
    "?:\\Users\\*\\AppData\\Local\\Temp\\Temp?_*",
    "?:\\Users\\*\\AppData\\Local\\Temp\\7z*",
    "?:\\Users\\*\\AppData\\Local\\Temp\\Rar$*")]
 [process where host.os.type == "windows" and event.action == "start" and
  (
   /* Check for browser processes opening HTML files with single argument */
   (process.name in ("chrome.exe", "msedge.exe", "brave.exe", "whale.exe", "browser.exe", "dragon.exe", "vivaldi.exe", "opera.exe")
    and process.args == "--single-argument") or

   /* Optionally, check for browser processes opening HTML files with two arguments */
   (process.name == "iexplore.exe" and process.args_count == 2) or

   /* Optionally, check for browser processes opening HTML files with URL argument */
   (process.name in ("firefox.exe", "waterfox.exe") and process.args == "-url")
  )
  /* Check for file paths in common download and temporary directories targeted in the process arguments */
  and process.args : ("?:\\Users\\*\\Downloads\\*.htm*",
                      "?:\\Users\\*\\Content.Outlook\\*.htm*",
                      "?:\\Users\\*\\AppData\\Local\\Temp\\Temp?_*.htm*",
                      "?:\\Users\\*\\AppData\\Local\\Temp\\7z*.htm*",
                      "?:\\Users\\*\\AppData\\Local\\Temp\\Rar$*.htm*")]

// Title: initial_access_execution_from_inetcache.toml
// Source: detection-rules::rules/windows/initial_access_execution_from_inetcache.toml
// Section: EQL Rule
// Rule Name: Suspicious Execution from INET Cache
// Author: Elastic
// Description:
// Identifies the execution of a process with arguments pointing to the INetCache Folder. Adversaries may deliver malicious
// content via WININET during initial access.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: dca6b4b0-ae70-44eb-bb7a-ce6db502ee78
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.parent.name : ("explorer.exe", "winrar.exe", "7zFM.exe", "Bandizip.exe") and
  (
    process.args : "*\\AppData\\Local\\Microsoft\\Windows\\INetCache\\IE\\*" or
    process.executable : (
      "?:\\Users\\*\\AppData\\Local\\Microsoft\\Windows\\INetCache\\IE\\*",

      /* Crowdstrike specific condition as it uses NT Object paths */
      "\\Device\\HarddiskVolume*\\Users\\*\\AppData\\Local\\Microsoft\\Windows\\INetCache\\IE\\*"
    )
  ) and
  not process.executable : (
        "?:\\Program Files\\*.exe",
        "?:\\Program Files (x86)\\*.exe",
        "?:\\Windows\\System32\\mspaint.exe",
        "?:\\Windows\\System32\\notepad.exe",

        /* Crowdstrike specific exclusion as it uses NT Object paths */
        "\\Device\\HarddiskVolume*\\Program Files\\*.exe",
        "\\Device\\HarddiskVolume*\\Program Files (x86)\\*.exe",
        "\\Device\\HarddiskVolume*\\Windows\\System32\\mspaint.exe",
        "\\Device\\HarddiskVolume*\\Windows\\System32\\notepad.exe"
  )

// Title: initial_access_execution_from_removable_media.toml
// Source: detection-rules::rules/windows/initial_access_execution_from_removable_media.toml
// Section: EQL Rule
// Rule Name: Execution from a Removable Media with Network Connection
// Author: Elastic
// Description:
// Identifies process execution from a removable media and by an unusual process. Adversaries may move onto systems,
// possibly those on disconnected or air-gapped networks, by copying malware to removable media and taking advantage of
// Autorun features when the media is inserted into a system and executes.
// Integration: endpoint
// Language: eql
// UUID: 1542fa53-955e-4330-8e4d-b2d812adeb5f
// Type: eql

sequence by process.entity_id with maxspan=5m
 [process where host.os.type == "windows" and event.action == "start" and

  /* Direct Exec from USB */
  (process.Ext.device.bus_type : "usb" or process.Ext.device.product_id : "USB *") and
  (process.code_signature.trusted == false or process.code_signature.exists == false) and

  not process.code_signature.status : ("errorExpired", "errorCode_endpoint*")]
 [network where host.os.type == "windows" and event.action == "connection_attempted"]

// Title: initial_access_execution_remote_via_msiexec.toml
// Source: detection-rules::rules/windows/initial_access_execution_remote_via_msiexec.toml
// Section: EQL Rule
// Rule Name: Potential Remote File Execution via MSIEXEC
// Author: Elastic
// Description:
// Identifies the execution of the built-in Windows Installer, msiexec.exe, to install a remote package. Adversaries may
// abuse msiexec.exe to launch local or network accessible MSI files.
// Integration: endpoint
// Language: eql
// UUID: 3e441bdb-596c-44fd-8628-2cfdf4516ada
// Type: eql

sequence with maxspan=1m
 [process where host.os.type == "windows" and event.action == "start" and
    process.name : "msiexec.exe" and process.args : "/V"] by process.entity_id
 [network where host.os.type == "windows" and process.name : "msiexec.exe" and
    event.action == "connection_attempted"] by process.entity_id
 [process where host.os.type == "windows" and event.action == "start" and
  process.parent.name : "msiexec.exe" and user.id : ("S-1-5-21-*", "S-1-5-12-1-*") and
  not process.executable : ("?:\\Windows\\SysWOW64\\msiexec.exe",
                            "?:\\Windows\\System32\\msiexec.exe",
                            "?:\\Windows\\System32\\srtasks.exe",
                            "?:\\Windows\\SysWOW64\\srtasks.exe",
                            "?:\\Windows\\System32\\taskkill.exe",
                            "?:\\Windows\\Installer\\MSI*.tmp",
                            "?:\\Program Files\\*.exe",
                            "?:\\Program Files (x86)\\*.exe",
                            "?:\\Windows\\System32\\ie4uinit.exe",
                            "?:\\Windows\\SysWOW64\\ie4uinit.exe",
                            "?:\\Windows\\System32\\sc.exe",
                            "?:\\Windows\\system32\\Wbem\\mofcomp.exe",
                            "?:\\Windows\\twain_32\\fjscan32\\SOP\\crtdmprc.exe",
                            "?:\\Windows\\SysWOW64\\taskkill.exe",
                            "?:\\Windows\\SysWOW64\\schtasks.exe",
                            "?:\\Windows\\system32\\schtasks.exe",
                            "?:\\Windows\\System32\\sdbinst.exe") and
  not (process.code_signature.subject_name == "Citrix Systems, Inc." and process.code_signature.trusted == true) and
  not (process.name : ("regsvr32.exe", "powershell.exe", "rundll32.exe", "wscript.exe") and
       process.Ext.token.integrity_level_name == "high" and
       process.args : ("?:\\Program Files\\*", "?:\\Program Files (x86)\\*")) and
  not (process.executable : ("?:\\Program Files\\*.exe", "?:\\Program Files (x86)\\*.exe") and process.code_signature.trusted == true) and
  not (process.name : "rundll32.exe" and process.args : "printui.dll,PrintUIEntry")
  ] by process.parent.entity_id

// Title: initial_access_execution_via_office_addins.toml
// Source: detection-rules::rules/windows/initial_access_execution_via_office_addins.toml
// Section: EQL Rule
// Rule Name: Suspicious Execution via Microsoft Office Add-Ins
// Author: Elastic
// Description:
// Identifies execution of common Microsoft Office applications to launch an Office Add-In from a suspicious path or with
// an unusual parent process. This may indicate an attempt to get initial access via a malicious phishing MS Office Add-In.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel
// Language: eql
// UUID: ae8a142c-6a1d-4918-bea7-0b617e99ecfa
// Type: eql

process where

    host.os.type == "windows" and event.type == "start" and

    process.name : ("WINWORD.EXE", "EXCEL.EXE", "POWERPNT.EXE", "MSACCESS.EXE", "VSTOInstaller.exe") and

    process.args regex~ """.+\.(wll|xll|ppa|ppam|xla|xlam|vsto)""" and

    /* Office Add-In from suspicious paths */
    (process.args :
             ("?:\\Users\\*\\Temp\\7z*",
              "?:\\Users\\*\\Temp\\Rar$*",
              "?:\\Users\\*\\Temp\\Temp?_*",
              "?:\\Users\\*\\Temp\\BNZ.*",
              "?:\\Users\\*\\Downloads\\*",
              "?:\\Users\\*\\AppData\\Roaming\\*",
              "?:\\Users\\Public\\*",
              "?:\\ProgramData\\*",
              "?:\\Windows\\Temp\\*",
              "\\Device\\*",
              "http*") or

    process.parent.name : ("explorer.exe", "OpenWith.exe") or

    /* Office Add-In from suspicious parent */
    process.parent.name : ("cmd.exe", "powershell.exe")) and

    /* False Positives */
    not (process.args : "*.vsto" and
         process.parent.executable :
                   ("?:\\Program Files\\Logitech\\LogiOptions\\PlugInInstallerUtility*.exe",
                    "?:\\ProgramData\\Logishrd\\LogiOptions\\Plugins\\VSTO\\*\\VSTOInstaller.exe",
                    "?:\\Program Files\\Logitech\\LogiOptions\\PlugInInstallerUtility.exe",
                    "?:\\Program Files\\LogiOptionsPlus\\PlugInInstallerUtility*.exe",
                    "?:\\ProgramData\\Logishrd\\LogiOptionsPlus\\Plugins\\VSTO\\*\\VSTOInstaller.exe",
                    "?:\\Program Files\\Common Files\\microsoft shared\\VSTO\\*\\VSTOInstaller.exe")) and
    not (process.args : "/Uninstall" and process.name : "VSTOInstaller.exe") and
    not (process.parent.name : "rundll32.exe" and
         process.parent.args : "?:\\WINDOWS\\Installer\\MSI*.tmp,zzzzInvokeManagedCustomActionOutOfProc") and
    not (process.name : "VSTOInstaller.exe" and process.args : "https://dl.getsidekick.com/outlook/vsto/Sidekick.vsto")

