// Title: initial_access_script_executing_powershell.toml
// Source: detection-rules::rules/windows/initial_access_script_executing_powershell.toml
// Section: EQL Rule
// Rule Name: Windows Script Executing PowerShell
// Author: Elastic
// Description:
// Identifies a PowerShell process launched by either cscript.exe or wscript.exe. Observing Windows scripting processes
// executing a PowerShell script, may be indicative of malicious activity.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel
// Language: eql
// UUID: f545ff26-3c94-4fd0-bd33-3c7f95a3a0fc
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.parent.name : ("cscript.exe", "wscript.exe") and process.name : "powershell.exe" and
  not (
    process.parent.name : "wscript.exe" and
    process.parent.args : "?:\\ProgramData\\intune-drive-mapping-generator\\IntuneDriveMapping-VBSHelper.vbs" and
    process.parent.args : "?:\\ProgramData\\intune-drive-mapping-generator\\DriveMapping.ps1"
  )

// Title: initial_access_scripts_process_started_via_wmi.toml
// Source: detection-rules::rules/windows/initial_access_scripts_process_started_via_wmi.toml
// Section: EQL Rule
// Rule Name: Windows Script Interpreter Executing Process via WMI
// Author: Elastic
// Description:
// Identifies use of the built-in Windows script interpreters (cscript.exe or wscript.exe) being used to execute a process
// via Windows Management Instrumentation (WMI). This may be indicative of malicious activity.
// Integration: endpoint, windows
// Language: eql
// UUID: b64b183e-1a76-422d-9179-7b389513e74d
// Type: eql

sequence by host.id with maxspan = 5s
    [any where host.os.type == "windows" and
     (event.category : ("library", "driver") or (event.category == "process" and event.action : "Image loaded*")) and
     (?dll.name : "wmiutils.dll" or file.name : "wmiutils.dll") and process.name : ("wscript.exe", "cscript.exe")]
    [process where host.os.type == "windows" and event.type == "start" and
     process.parent.name : "wmiprvse.exe" and
     user.domain != "NT AUTHORITY" and
     (process.pe.original_file_name :
        (
          "cscript.exe",
          "wscript.exe",
          "PowerShell.EXE",
          "Cmd.Exe",
          "MSHTA.EXE",
          "RUNDLL32.EXE",
          "REGSVR32.EXE",
          "MSBuild.exe",
          "InstallUtil.exe",
          "RegAsm.exe",
          "RegSvcs.exe",
          "msxsl.exe",
          "CONTROL.EXE",
          "EXPLORER.EXE",
          "Microsoft.Workflow.Compiler.exe",
          "msiexec.exe"
        ) or
      process.executable : ("C:\\Users\\*.exe", "C:\\ProgramData\\*.exe")
     )
    ]

// Title: initial_access_suspicious_execution_from_vscode_extension.toml
// Source: detection-rules::rules/windows/initial_access_suspicious_execution_from_vscode_extension.toml
// Section: EQL Rule
// Rule Name: Suspicious Execution from VS Code Extension
// Author: Elastic
// Description:
// Detects suspicious process execution launched from a VS Code extension context (parent command line contains
// .vscode/extensions). Malicious extensions can run on startup and drop or execute payloads (e.g. RATs like
// ScreenConnect, script interpreters, or download utilities). This covers both script/LOLBin children and
// recently created executables from non-Program Files paths, as seen in campaigns such as the fake Clawdbot
// extension that installed ScreenConnect RAT.
// Integration: endpoint
// Language: eql
// UUID: c3d4e5f6-a7b8-6c9d-0e1f-2a3b4c5d6e7f
// Type: eql

process where host.os.type == "windows" and event.action == "start" and
  process.parent.name : ("node.exe", "Code.exe") and
  process.parent.command_line != null and
  process.parent.command_line : ("*vscode*extensions*", "*extensionHost*") and
  (
    process.name : (
      "cmd.exe", "powershell.exe", "pwsh.exe", "rundll32.exe", "msiexec.exe",
      "curl.exe", "bitsadmin.exe", "wscript.exe", "cscript.exe", "mshta.exe",
      "node.exe"
    ) or

	// recently dropped PE
    process.Ext.relative_file_creation_time <= 500
  ) and 
  not (process.name : "cmd.exe" and process.args : ("npm.cmd config get prefix", "code -v", "chcp")) and 
  not (process.name : "python.exe" and process.parent.command_line : "*ms-python.vscode-*")

// Title: initial_access_suspicious_ms_exchange_files.toml
// Source: detection-rules::rules/windows/initial_access_suspicious_ms_exchange_files.toml
// Section: EQL Rule
// Rule Name: Microsoft Exchange Server UM Writing Suspicious Files
// Author: Elastic, Austin Songer
// Description:
// Identifies suspicious files being written by the Microsoft Exchange Server Unified Messaging (UM) service. This activity
// has been observed exploiting CVE-2021-26858.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel
// Language: eql
// UUID: 6cd1779c-560f-4b68-a8f1-11009b27fe63
// Type: eql

file where host.os.type == "windows" and event.type == "creation" and
  process.name : ("UMWorkerProcess.exe", "umservice.exe") and
  file.extension : ("php", "jsp", "js", "aspx", "asmx", "asax", "cfm", "shtml") and
  (
    file.path : "?:\\inetpub\\wwwroot\\aspnet_client\\*" or

    (file.path : "?:\\*\\Microsoft\\Exchange Server*\\FrontEnd\\HttpProxy\\owa\\auth\\*" and
       not (file.path : "?:\\*\\Microsoft\\Exchange Server*\\FrontEnd\\HttpProxy\\owa\\auth\\version\\*" or
            file.name : ("errorFE.aspx", "expiredpassword.aspx", "frowny.aspx", "GetIdToken.htm", "logoff.aspx",
                        "logon.aspx", "OutlookCN.aspx", "RedirSuiteServiceProxy.aspx", "signout.aspx"))) or

    (file.path : "?:\\*\\Microsoft\\Exchange Server*\\FrontEnd\\HttpProxy\\ecp\\auth\\*" and
       not file.name : "TimeoutLogoff.aspx")
  )

// Title: initial_access_suspicious_ms_exchange_process.toml
// Source: detection-rules::rules/windows/initial_access_suspicious_ms_exchange_process.toml
// Section: EQL Rule
// Rule Name: Microsoft Exchange Server UM Spawning Suspicious Processes
// Author: Elastic, Austin Songer
// Description:
// Identifies suspicious processes being spawned by the Microsoft Exchange Server Unified Messaging (UM) service. This
// activity has been observed exploiting CVE-2021-26857.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 483c4daf-b0c6-49e0-adf3-0bfa93231d6b
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.parent.name : ("UMService.exe", "UMWorkerProcess.exe") and
    not process.executable : (
          "?:\\Windows\\System32\\werfault.exe",
          "?:\\Windows\\System32\\wermgr.exe",
          "?:\\Program Files\\Microsoft\\Exchange Server\\V??\\Bin\\UMWorkerProcess.exe",
          "?:\\Program Files\\Microsoft\\Exchange Server\\Bin\\UMWorkerProcess.exe",
          "D:\\Exchange 2016\\Bin\\UMWorkerProcess.exe",
          "E:\\ExchangeServer\\Bin\\UMWorkerProcess.exe",
          "D:\\Exchange\\Bin\\UMWorkerProcess.exe",
          "D:\\Exchange Server\\Bin\\UMWorkerProcess.exe",
          "E:\\Exchange Server\\V15\\Bin\\UMWorkerProcess.exe",

          /* Crowdstrike specific exclusion as it uses NT Object paths */
          "\\Device\\HarddiskVolume*\\Windows\\System32\\werfault.exe",
          "\\Device\\HarddiskVolume*\\Windows\\System32\\wermgr.exe",
          "\\Device\\HarddiskVolume*\\Program Files\\Microsoft\\Exchange Server\\V??\\Bin\\UMWorkerProcess.exe",
          "\\Device\\HarddiskVolume*\\Program Files\\Microsoft\\Exchange Server\\Bin\\UMWorkerProcess.exe",
          "\\Device\\HarddiskVolume*\\Exchange 2016\\Bin\\UMWorkerProcess.exe",
          "\\Device\\HarddiskVolume*\\ExchangeServer\\Bin\\UMWorkerProcess.exe",
          "\\Device\\HarddiskVolume*\\Exchange\\Bin\\UMWorkerProcess.exe",
          "\\Device\\HarddiskVolume*\\Exchange Server\\Bin\\UMWorkerProcess.exe",
          "\\Device\\HarddiskVolume*\\Exchange Server\\V15\\Bin\\UMWorkerProcess.exe"
    )

// Title: initial_access_suspicious_ms_exchange_worker_child_process.toml
// Source: detection-rules::rules/windows/initial_access_suspicious_ms_exchange_worker_child_process.toml
// Section: EQL Rule
// Rule Name: Microsoft Exchange Worker Spawning Suspicious Processes
// Author: Elastic
// Description:
// Identifies suspicious processes being spawned by the Microsoft Exchange Server worker process (w3wp). This activity may
// indicate exploitation activity or access to an existing web shell backdoor.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel
// Language: eql
// UUID: f81ee52c-297e-46d9-9205-07e66931df26
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.parent.name : "w3wp.exe" and process.parent.args : "MSExchange*AppPool" and
  (
    (process.name : ("cmd.exe", "powershell.exe", "pwsh.exe", "powershell_ise.exe") or
