  )

// Title: initial_access_suspicious_ms_office_child_process.toml
// Source: detection-rules::rules/windows/initial_access_suspicious_ms_office_child_process.toml
// Section: EQL Rule
// Rule Name: Suspicious MS Office Child Process
// Author: Elastic
// Description:
// Identifies suspicious child processes of frequently targeted Microsoft Office applications (Word, PowerPoint, Excel).
// These child processes are often launched during exploitation of Office applications or from documents with malicious
// macros.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: a624863f-a70d-417f-a7d2-7a404638d47f
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.parent.name : (
      "eqnedt32.exe", "excel.exe", "fltldr.exe", "msaccess.exe",
      "mspub.exe", "powerpnt.exe", "winword.exe", "outlook.exe"
  ) and
  process.name : (
      "Microsoft.Workflow.Compiler.exe", "arp.exe", "atbroker.exe", "bginfo.exe", "bitsadmin.exe", "cdb.exe",
      "certutil.exe", "cmd.exe", "cmstp.exe", "control.exe", "cscript.exe", "csi.exe", "dnx.exe", "dsget.exe",
      "dsquery.exe", "forfiles.exe", "fsi.exe", "ftp.exe", "gpresult.exe", "hostname.exe", "ieexec.exe", "iexpress.exe",
      "installutil.exe", "ipconfig.exe", "mshta.exe", "msxsl.exe", "nbtstat.exe", "net.exe", "net1.exe", "netsh.exe",
      "netstat.exe", "nltest.exe", "odbcconf.exe", "ping.exe", "powershell.exe", "pwsh.exe", "qprocess.exe",
      "quser.exe", "qwinsta.exe", "rcsi.exe", "reg.exe", "regasm.exe", "regsvcs.exe", "regsvr32.exe", "sc.exe",
      "schtasks.exe", "systeminfo.exe", "tasklist.exe", "tracert.exe", "whoami.exe", "wmic.exe", "wscript.exe",
      "xwizard.exe", "explorer.exe", "rundll32.exe", "hh.exe", "msdt.exe"
  ) and
  not (
    process.parent.name : "outlook.exe" and
    process.name : "rundll32.exe" and
    process.args : "shell32.dll,Control_RunDLL" and
    process.args : "srchadmin.dll"
  )

// Title: initial_access_suspicious_ms_outlook_child_process.toml
// Source: detection-rules::rules/windows/initial_access_suspicious_ms_outlook_child_process.toml
// Section: EQL Rule
// Rule Name: Suspicious MS Outlook Child Process
// Author: Elastic
// Description:
// Identifies suspicious child processes of Microsoft Outlook. These child processes are often associated with spear
// phishing activity.
// Integration: endpoint, windows, system, sentinel_one_cloud_funnel, m365_defender, crowdstrike
// Language: eql
// UUID: 32f4675e-6c49-4ace-80f9-97c9259dca2e
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.parent.name : "outlook.exe" and
  process.name : ("Microsoft.Workflow.Compiler.exe", "arp.exe", "atbroker.exe", "bginfo.exe", "bitsadmin.exe",
                  "cdb.exe", "certutil.exe", "cmd.exe", "cmstp.exe", "cscript.exe", "csi.exe", "dnx.exe", "dsget.exe",
                  "dsquery.exe", "forfiles.exe", "fsi.exe", "ftp.exe", "gpresult.exe", "hostname.exe", "ieexec.exe",
                  "iexpress.exe", "installutil.exe", "ipconfig.exe", "mshta.exe", "msxsl.exe", "nbtstat.exe", "net.exe",
                  "net1.exe", "netsh.exe", "netstat.exe", "nltest.exe", "odbcconf.exe", "ping.exe", "powershell.exe",
                  "pwsh.exe", "qprocess.exe", "quser.exe", "qwinsta.exe", "rcsi.exe", "reg.exe", "regasm.exe",
                  "regsvcs.exe", "regsvr32.exe", "sc.exe", "schtasks.exe", "systeminfo.exe", "tasklist.exe",
                  "tracert.exe", "whoami.exe", "wmic.exe", "wscript.exe", "xwizard.exe")

// Title: initial_access_suspicious_windows_server_update_svc.toml
// Source: detection-rules::rules/windows/initial_access_suspicious_windows_server_update_svc.toml
// Section: EQL Rule
// Rule Name: Windows Server Update Service Spawning Suspicious Processes
// Author: Elastic
// Description:
// Identifies suspicious processes being spawned by the Windows Server Update Service.
// This activity may indicate exploitation activity or access to an existing web shell backdoor.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel
// Language: eql
// UUID: 1ac027c2-8c60-4715-af73-927b9c219e20
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.name : ("cmd.exe", "powershell.exe", "pwsh.exe", "powershell_ise.exe", "rundll32.exe", "curl.exe") and
  (
   (process.parent.name : "w3wp.exe" and process.parent.args : "WsusPool") or
   process.parent.name : "WsusService.exe"
   )

// Title: initial_access_url_cve_2025_33053.toml
// Source: detection-rules::rules/windows/initial_access_url_cve_2025_33053.toml
// Section: EQL Rule
// Rule Name: Potential CVE-2025-33053 Exploitation
// Author: Elastic
// Description:
// Identifies Internet Explorer Diagnostics launching a helper name from a non-System32 path, which may indicate
// CVE-2025-33053 exploitation.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel
// Language: eql
// UUID: 5e23495f-09e2-4484-8235-bdb150d698c9
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.parent.executable : "C:\\Program Files\\Internet Explorer\\iediagcmd.exe" and
  process.name : ("route.exe", "netsh.exe", "ipconfig.exe", "dxdiag.exe", "conhost.exe", "makecab.exe") and
  process.executable != null and
  not process.executable : ("C:\\Windows\\System32\\route.exe",
                            "C:\\Windows\\System32\\netsh.exe",
                            "C:\\Windows\\System32\\ipconfig.exe",
                            "C:\\Windows\\System32\\dxdiag.exe",
                            "C:\\Windows\\System32\\conhost.exe",
                            "C:\\Windows\\System32\\makecab.exe")

// Title: initial_access_via_explorer_suspicious_child_parent_args.toml
// Source: detection-rules::rules/windows/initial_access_via_explorer_suspicious_child_parent_args.toml
// Section: EQL Rule
// Rule Name: Suspicious Explorer Child Process
// Author: Elastic
// Description:
// Identifies a suspicious Windows explorer child process. Explorer.exe can be abused to launch malicious scripts or
// executables from a trusted parent process.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel
// Language: eql
// UUID: 9a5b4e31-6cde-4295-9ff7-6be1b8567e1b
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  (
   process.name : ("cscript.exe", "wscript.exe", "powershell.exe", "rundll32.exe", "cmd.exe", "mshta.exe", "regsvr32.exe") or
   ?process.pe.original_file_name in ("cscript.exe", "wscript.exe", "PowerShell.EXE", "RUNDLL32.EXE", "Cmd.Exe", "MSHTA.EXE", "REGSVR32.EXE")
  ) and
  /* Explorer started via DCOM */
  process.parent.name : "explorer.exe" and process.parent.args : "-Embedding" and
  not process.parent.args:
          (
            /* Noisy CLSID_SeparateSingleProcessExplorerHost Explorer COM Class IDs   */
            "/factory,{5BD95610-9434-43C2-886C-57852CC8A120}",
            "/factory,{ceff45ee-c862-41de-aee2-a022c81eda92}"
          )

// Title: initial_access_webshell_screenconnect_server.toml
// Source: detection-rules::rules/windows/initial_access_webshell_screenconnect_server.toml
// Section: EQL Rule
// Rule Name: ScreenConnect Server Spawning Suspicious Processes
// Author: Elastic
// Description:
// Identifies suspicious processes being spawned by the ScreenConnect server process (ScreenConnect.Service.exe). This
// activity may indicate exploitation activity or access to an existing web shell backdoor.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 3d00feab-e203-4acc-a463-c3e15b7e9a73
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.parent.name : "ScreenConnect.Service.exe" and
  (process.name : ("cmd.exe", "powershell.exe", "pwsh.exe", "powershell_ise.exe", "csc.exe") or
  ?process.pe.original_file_name in ("Cmd.Exe", "PowerShell.EXE", "pwsh.dll", "powershell_ise.EXE", "csc.exe"))

// Title: initial_access_xsl_script_execution_via_com.toml
// Source: detection-rules::rules/windows/initial_access_xsl_script_execution_via_com.toml
// Section: EQL Rule
// Rule Name: Remote XSL Script Execution via COM
// Author: Elastic
// Description:
// Identifies the execution of a hosted XSL script using the Microsoft.XMLDOM COM interface via Microsoft Office processes.
// This behavior may indicate adversarial activity to execute malicious JScript or VBScript on the system.
// Integration: endpoint
// Language: eql
// UUID: 48f657ee-de4f-477c-aa99-ed88ee7af97a
// Type: eql

sequence with maxspan=1m
 [library where host.os.type == "windows" and dll.name : "msxml3.dll" and
  process.name : ("winword.exe", "excel.exe", "powerpnt.exe", "mspub.exe")] by process.entity_id
 [process where host.os.type == "windows" and event.action == "start" and
  process.parent.name : ("winword.exe", "excel.exe", "powerpnt.exe", "mspub.exe") and
  not process.executable :
        ("?:\\Windows\\System32\\WerFault.exe",
         "?:\\Windows\\SysWoW64\\WerFault.exe",
         "?:\\windows\\splwow64.exe",
         "?:\\Windows\\System32\\conhost.exe",
         "?:\\Program Files\\*.exe",
         "?:\\Program Files (x86)\\*exe")] by process.parent.entity_id

// Title: lateral_movement_cmd_service.toml
// Source: detection-rules::rules/windows/lateral_movement_cmd_service.toml
// Section: EQL Rule
// Rule Name: Service Command Lateral Movement
// Author: Elastic
// Description:
// Identifies use of sc.exe to create, modify, or start services on remote hosts. This could be indicative of adversary
// lateral movement but will be noisy if commonly done by admins.
// Integration: endpoint, windows
// Language: eql
// UUID: d61cbcf8-1bc1-4cff-85ba-e7b21c5beedc
// Type: eql

sequence by process.entity_id with maxspan = 1m
  [process where host.os.type == "windows" and event.type == "start" and
     (process.name : "sc.exe" or process.pe.original_file_name : "sc.exe") and
      process.args : "\\\\*" and process.args : ("binPath=*", "binpath=*") and
      process.args : ("create", "config", "failure", "start")]
  [network where host.os.type == "windows" and process.name : "sc.exe" and destination.ip != "127.0.0.1"]

// Title: lateral_movement_credential_access_kerberos_correlation.toml
// Source: detection-rules::rules/windows/lateral_movement_credential_access_kerberos_correlation.toml
// Section: EQL Rule
// Rule Name: Suspicious Kerberos Authentication Ticket Request
// Author: Elastic
// Description:
// Correlates network connections to the standard Kerberos port by an unusual process from the source machine with a
// Kerberos authentication ticket request from the target domain controller.
// Integration: endpoint, windows, system
// Language: eql
// UUID: c6b40f4c-c6a9-434e-adb8-989b0d06d005
// Type: eql

sequence by source.port, source.ip with maxspan=3s
 [network where host.os.type == "windows" and destination.port == 88 and
  process.executable != null and process.pid != 4 and 
  not process.executable : (
        "?:\\Windows\\system32\\lsass.exe",
        "\\device\\harddiskvolume*\\windows\\system32\\lsass.exe",
        "\\device\\harddiskvolume*\\windows\\system32\\svchost.exe"
  ) and
  not (
    process.executable : (
      "C:\\Windows\\System32\\svchost.exe",
      "C:\\Program Files\\VMware\\VMware View\\Server\\bin\\ws_TomcatService.exe",
      "C:\\Program Files\\Omnissa\\Horizon\\Server\\bin\\ws_TomcatService.exe",
      "C:\\Program Files\\SysAidServer\\root\\WEB-INF\\domains\\NetworkDiscovery.exe",
      "C:\\Program Files (x86)\\IGEL\\RemoteManager\\*\\bin\\tomcat10.exe",
      "F:\\IGEL\\RemoteManager\\*\\bin\\tomcat10.exe"
    ) and
    user.id in ("S-1-5-20", "S-1-5-18")
  ) and
  source.ip != "127.0.0.1" and destination.ip != "::1" and destination.ip != "127.0.0.1"]
 [authentication where host.os.type == "windows" and event.code in ("4768", "4769")]

// Title: lateral_movement_dcom_hta.toml
// Source: detection-rules::rules/windows/lateral_movement_dcom_hta.toml
// Section: EQL Rule
// Rule Name: Incoming DCOM Lateral Movement via MSHTA
// Author: Elastic
// Description:
// Identifies the use of Distributed Component Object Model (DCOM) to execute commands from a remote host, which are
// launched via the HTA Application COM Object. This behavior may indicate an attacker abusing a DCOM application to move
// laterally while attempting to evade detection.
// Integration: endpoint, windows
// Language: eql
// UUID: 622ecb68-fa81-4601-90b5-f8cd661e4520
// Type: eql

sequence with maxspan=1m
  [process where host.os.type == "windows" and event.type == "start" and
     process.name : "mshta.exe" and process.args : "-Embedding"
  ] by host.id, process.entity_id
  [network where host.os.type == "windows" and event.type == "start" and process.name : "mshta.exe" and
     network.direction : ("incoming", "ingress") and network.transport == "tcp" and
     source.port > 49151 and destination.port > 49151 and source.ip != "127.0.0.1" and source.ip != "::1"
  ] by host.id, process.entity_id

// Title: lateral_movement_dcom_mmc20.toml
// Source: detection-rules::rules/windows/lateral_movement_dcom_mmc20.toml
// Section: EQL Rule
// Rule Name: Incoming DCOM Lateral Movement with MMC
// Author: Elastic
// Description:
// Identifies the use of Distributed Component Object Model (DCOM) to run commands from a remote host, which are launched
// via the MMC20 Application COM Object. This behavior may indicate an attacker abusing a DCOM application to move
// laterally.
// Integration: endpoint, windows
// Language: eql
// UUID: 51ce96fb-9e52-4dad-b0ba-99b54440fc9a
// Type: eql

sequence by host.id with maxspan=1m
 [network where host.os.type == "windows" and event.type == "start" and process.name : "mmc.exe" and source.port >= 49152 and
  destination.port >= 49152 and source.ip != "127.0.0.1" and source.ip != "::1" and
  network.direction : ("incoming", "ingress") and network.transport == "tcp"
 ] by process.entity_id
 [process where host.os.type == "windows" and event.type == "start" and process.parent.name : "mmc.exe"
 ] by process.parent.entity_id

// Title: lateral_movement_dcom_shellwindow_shellbrowserwindow.toml
// Source: detection-rules::rules/windows/lateral_movement_dcom_shellwindow_shellbrowserwindow.toml
// Section: EQL Rule
// Rule Name: Incoming DCOM Lateral Movement with ShellBrowserWindow or ShellWindows
// Author: Elastic
// Description:
// Identifies use of Distributed Component Object Model (DCOM) to run commands from a remote host, which are launched via
// the ShellBrowserWindow or ShellWindows Application COM Object. This behavior may indicate an attacker abusing a DCOM
// application to stealthily move laterally.
// Integration: endpoint, windows
// Language: eql
// UUID: 8f919d4b-a5af-47ca-a594-6be59cd924a4
// Type: eql

sequence by host.id with maxspan=5s
 [network where host.os.type == "windows" and event.type == "start" and process.name : "explorer.exe" and
  network.direction : ("incoming", "ingress") and network.transport == "tcp" and
  source.port > 49151 and destination.port > 49151 and source.ip != "127.0.0.1" and source.ip != "::1"
 ] by process.entity_id
 [process where host.os.type == "windows" and event.type == "start" and
  process.parent.name : "explorer.exe"
 ] by process.parent.entity_id

// Title: lateral_movement_defense_evasion_lanman_nullsessionpipe_modification.toml
// Source: detection-rules::rules/windows/lateral_movement_defense_evasion_lanman_nullsessionpipe_modification.toml
// Section: EQL Rule
// Rule Name: NullSessionPipe Registry Modification
// Author: Elastic
// Description:
// Identifies NullSessionPipe registry modifications that specify which pipes can be accessed anonymously. This could be
// indicative of adversary lateral movement preparation by making the added pipe available to everyone.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: ddab1f5f-7089-44f5-9fda-de5b11322e77
// Type: eql

registry where host.os.type == "windows" and event.type == "change" and
  registry.value : "NullSessionPipes" and
  length(registry.data.strings) > 0 and
  not registry.data.strings : "(empty)"

// Title: lateral_movement_direct_outbound_smb_connection.toml
// Source: detection-rules::rules/windows/lateral_movement_direct_outbound_smb_connection.toml
// Section: EQL Rule
// Rule Name: SMB Connections via LOLBin or Untrusted Process
// Author: Elastic
// Description:
// Identifies potentially suspicious processes that are not trusted or living-off-the-land binaries (LOLBin) making Server
// Message Block (SMB) network connections over port 445. Windows File Sharing is typically implemented over SMB, which
// communicates between hosts using port 445. Legitimate connections are generally established by the kernel (PID 4). This
// rule helps to detect processes that might be port scanners, exploits, or user-level processes attempting lateral
// movement within the network by leveraging SMB connections.
// Integration: endpoint
// Language: eql
// UUID: c82c7d8f-fb9e-4874-a4bd-fd9e3f9becf1
// Type: eql

sequence by process.entity_id with maxspan=1m

  /* first sequence to capture the start of Windows processes */
  [process where host.os.type == "windows" and event.type == "start" and process.pid != 4 and

    /* ignore NT Authority and Network Service accounts */
    not user.id in ("S-1-5-19", "S-1-5-20") and

    /* filter out anything trusted but not from Microsoft */
    /* LOLBins will be inherently trusted and signed, so ignore everything else trusted */
    not (process.code_signature.trusted == true and not startsWith(process.code_signature.subject_name, "Microsoft")) and

    /* filter out PowerShell scripts from Windows Defender ATP */
    not (
      process.name : "powershell.exe" and
      process.args :"?:\\ProgramData\\Microsoft\\Windows Defender Advanced Threat Protection\\Downloads\\PSScript_*.ps1")]

  /* second sequence to capture network connections over port 445 related to SMB */
  [network where host.os.type == "windows" and destination.port == 445 and process.pid != 4]

// Title: lateral_movement_evasion_rdp_shadowing.toml
// Source: detection-rules::rules/windows/lateral_movement_evasion_rdp_shadowing.toml
// Section: EQL Rule
// Rule Name: Potential Remote Desktop Shadowing Activity
// Author: Elastic
// Description:
// Identifies the modification of the Remote Desktop Protocol (RDP) Shadow registry or the execution of processes
// indicative of an active RDP shadowing session. An adversary may abuse the RDP Shadowing feature to spy on or control
// other users active RDP sessions.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel
// Language: eql
// UUID: c57f8579-e2a5-4804-847f-f2732edc5156
// Type: eql

/* Identifies the modification of RDP Shadow registry or
  the execution of processes indicative of active shadow RDP session */

any where host.os.type == "windows" and
(
  (event.category == "registry" and event.type == "change" and
    registry.value : "Shadow" and
    registry.path : (
      "*\\Software\\Policies\\Microsoft\\Windows NT\\Terminal Services\\Shadow"
    ) and
    registry.data.strings : ("1", "0x00000001", "2", "0x00000002", "3", "0x00000003", "4", "0x00000004")

  ) or
  (event.category == "process" and event.type == "start" and
    (
      (process.name : ("RdpSaUacHelper.exe", "RdpSaProxy.exe") and process.parent.name : "svchost.exe") or
      (?process.pe.original_file_name : "mstsc.exe" and process.args : "/shadow:*")
    )
  )
)

// Title: lateral_movement_executable_tool_transfer_smb.toml
// Source: detection-rules::rules/windows/lateral_movement_executable_tool_transfer_smb.toml
// Section: EQL Rule
// Rule Name: Potential Lateral Tool Transfer via SMB Share
// Author: Elastic
// Description:
// Identifies the creation or change of a Windows executable file over network shares. Adversaries may transfer tools or
// other files between systems in a compromised environment.
// Integration: endpoint
// Language: eql
// UUID: 58bc134c-e8d2-4291-a552-b4b3e537c60b
// Type: eql

sequence by host.id with maxspan=30s
  [network where host.os.type == "windows" and event.type == "start" and process.pid == 4 and destination.port == 445 and
   network.direction : ("incoming", "ingress") and
   network.transport == "tcp" and source.ip != "127.0.0.1" and source.ip != "::1"
  ] by process.entity_id
  /* add more executable / script extensions here if they are not noisy in your environment */
  [file where host.os.type == "windows" and event.type in ("creation", "change") and process.pid == 4 and user.id like ("S-1-5-21*", "S-1-12-*") and 
   (file.Ext.header_bytes : "4d5a*" or file.extension : ("exe", "scr", "pif", "com", "dll", "bat", "cmd", "ps1", "vbs", "vbe", "js", "jse", "wsh", "wsf", "sct", "hta", "cpl")) and
   not file.path : (
     "?:\\Windows\\VeeamVssSupport\\*",
     "?:\\Windows\\VeeamLogShipper\\*"
   )] by process.entity_id

// Title: lateral_movement_execution_from_tsclient_mup.toml
// Source: detection-rules::rules/windows/lateral_movement_execution_from_tsclient_mup.toml
// Section: EQL Rule
// Rule Name: Execution via TSClient Mountpoint
// Author: Elastic
// Description:
// Identifies execution from the Remote Desktop Protocol (RDP) shared mountpoint tsclient on the target host. This may
// indicate a lateral movement attempt.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 4fe9d835-40e1-452d-8230-17c147cafad8
// Type: eql

process where host.os.type == "windows" and event.type == "start" and process.executable : "\\Device\\Mup\\tsclient\\*.exe"

// Title: lateral_movement_execution_via_file_shares_sequence.toml
// Source: detection-rules::rules/windows/lateral_movement_execution_via_file_shares_sequence.toml
// Section: EQL Rule
// Rule Name: Remote Execution via File Shares
// Author: Elastic
// Description:
// Identifies the execution of a file that was created by the virtual system process. This may indicate lateral movement
// via network file shares.
// Integration: endpoint
// Language: eql
// UUID: ab75c24b-2502-43a0-bf7c-e60e662c811e
// Type: eql

sequence with maxspan=1m
  [file where host.os.type == "windows" and event.type in ("creation", "change") and 
   process.pid == 4 and (file.extension : ("exe", "scr", "pif", "com") or file.Ext.header_bytes : "4d5a*")] by host.id, file.path
  [process where host.os.type == "windows" and event.type == "start" and
    not (
      (
        process.code_signature.trusted == true and
        process.code_signature.subject_name : (
              "Veeam Software Group GmbH",
              "Elasticsearch, Inc.",
              "PDQ.com Corporation",
              "CrowdStrike, Inc.",
              "Microsoft Windows Hardware Compatibility Publisher",
              "ZOHO Corporation Private Limited",
              "BeyondTrust Corporation", 
              "CyberArk Software Ltd.", 
              "Sophos Ltd",
              "AO Kaspersky Lab",
              "Anthropic, PBC",
              "Adobe Inc.",
              "Netwrix Corporation"
        )
      ) or
      (
        process.executable : (
          "?:\\Windows\\ccmsetup\\ccmsetup.exe",
          "?:\\Windows\\SoftwareDistribution\\Download\\Install\\*.exe",
          "?:\\Windows\\CAInvokerService.exe",
          "?:\\Users\\*\\AppData\\Local\\Microsoft\\OneDrive\\*\\OneDriveSetup.exe"
        ) and process.code_signature.trusted == true
      ) or
      (
        process.executable : "?:\\SMS_*\\srvboot.exe" and 
        process.code_signature.trusted == true and process.code_signature.subject_name : "Microsoft Corporation"
      )
    )
  ] by host.id, process.executable

// Title: lateral_movement_incoming_winrm_shell_execution.toml
// Source: detection-rules::rules/windows/lateral_movement_incoming_winrm_shell_execution.toml
// Section: EQL Rule
// Rule Name: Incoming Execution via WinRM Remote Shell
// Author: Elastic
// Description:
// Identifies remote execution via Windows Remote Management (WinRM) remote shell on a target host. This could be an
// indication of lateral movement.
// Integration: endpoint, windows, sentinel_one_cloud_funnel
// Language: eql
// UUID: 1cd01db9-be24-4bef-8e7c-e923f0ff78ab
// Type: eql

sequence by host.id with maxspan=30s
   [network where host.os.type == "windows" and process.pid == 4 and network.direction : ("incoming", "ingress") and
    destination.port in (5985, 5986) and source.ip != "127.0.0.1" and source.ip != "::1"]
   [process where host.os.type == "windows" and
    event.type == "start" and process.parent.name : "winrshost.exe" and not process.executable : "?:\\Windows\\System32\\conhost.exe"]

// Title: lateral_movement_incoming_wmi.toml
// Source: detection-rules::rules/windows/lateral_movement_incoming_wmi.toml
// Section: EQL Rule
// Rule Name: WMI Incoming Lateral Movement
// Author: Elastic
// Description:
// Identifies processes executed via Windows Management Instrumentation (WMI) on a remote host. This could be indicative of
// adversary lateral movement, but could be noisy if administrators use WMI to remotely manage hosts.
// Integration: endpoint, windows
// Language: eql
// UUID: f3475224-b179-4f78-8877-c2bd64c26b88
// Type: eql

sequence by host.id with maxspan = 20s

 /* Accepted Incoming RPC connection by Winmgmt service */

  [network where host.os.type == "windows" and process.name : "svchost.exe" and network.direction : ("incoming", "ingress") and
   source.ip != "127.0.0.1" and source.ip != "::1" and destination.port == 135]

  /* Excluding Common FPs Nessus and SCCM */

  [process where host.os.type == "windows" and event.type == "start" and process.parent.name : "WmiPrvSE.exe" and
   not (?process.Ext.token.integrity_level_name : "System" or ?winlog.event_data.IntegrityLevel : "System") and
   not (
         user.id : ("S-1-5-18", "S-1-5-19", "S-1-5-20") and
         /* Don't apply the user.id exclusion to Sysmon for compatibility */
         not data_stream.dataset : ("windows.sysmon_operational", "windows.sysmon")
   ) and
   not process.executable :
               ("?:\\Program Files\\HPWBEM\\Tools\\hpsum_swdiscovery.exe",
                "?:\\Windows\\CCM\\Ccm32BitLauncher.exe",
                "?:\\Windows\\System32\\wbem\\mofcomp.exe",
                "?:\\Windows\\Microsoft.NET\\Framework*\\csc.exe",
                "?:\\Windows\\System32\\powercfg.exe") and
   not (process.executable : "?:\\Windows\\System32\\msiexec.exe" and process.args : "REBOOT=ReallySuppress") and
   not (process.executable : "?:\\Windows\\System32\\inetsrv\\appcmd.exe" and process.args : "uninstall")
   ]

// Title: lateral_movement_mount_hidden_or_webdav_share_net.toml
// Source: detection-rules::rules/windows/lateral_movement_mount_hidden_or_webdav_share_net.toml
// Section: EQL Rule
// Rule Name: Mounting Hidden or WebDav Remote Shares
// Author: Elastic
// Description:
// Identifies the use of net.exe to mount a WebDav or hidden remote share. This may indicate lateral movement or
// preparation for data exfiltration.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: c4210e1c-64f2-4f48-b67e-b5a8ffe3aa14
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
 ((process.name : "net.exe" or ?process.pe.original_file_name == "net.exe") or ((process.name : "net1.exe" or ?process.pe.original_file_name == "net1.exe") and
 not process.parent.name : "net.exe")) and
 process.args : "use" and
 /* including hidden and webdav based online shares such as onedrive  */
 process.args : ("\\\\*\\*$*", "\\\\*@SSL\\*", "http*") and
 /* excluding shares deletion operation */
 not process.args : "/d*"

// Title: lateral_movement_powershell_remoting_target.toml
// Source: detection-rules::rules/windows/lateral_movement_powershell_remoting_target.toml
// Section: EQL Rule
// Rule Name: Incoming Execution via PowerShell Remoting
// Author: Elastic
// Description:
// Identifies remote execution via Windows PowerShell remoting. Windows PowerShell remoting allows a user to run any
// Windows PowerShell command on one or more remote computers. This could be an indication of lateral movement.
// Integration: endpoint, windows, sentinel_one_cloud_funnel
// Language: eql
// UUID: 2772264c-6fb9-4d9d-9014-b416eed21254
// Type: eql

sequence by host.id with maxspan = 30s
   [network where host.os.type == "windows" and network.direction : ("incoming", "ingress") and destination.port in (5985, 5986) and
    source.ip != "127.0.0.1" and source.ip != "::1"]
   [process where host.os.type == "windows" and
    event.type == "start" and process.parent.name : "wsmprovhost.exe" and not process.executable : "?:\\Windows\\System32\\conhost.exe"]

// Title: lateral_movement_rdp_enabled_registry.toml
// Source: detection-rules::rules/windows/lateral_movement_rdp_enabled_registry.toml
// Section: EQL Rule
// Rule Name: RDP Enabled via Registry
// Author: Elastic
// Description:
// Identifies registry write modifications to enable Remote Desktop Protocol (RDP) access. This could be indicative of
// adversary lateral movement preparation.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 58aa72ca-d968-4f34-b9f7-bea51d75eb50
// Type: eql

registry where host.os.type == "windows" and event.type == "change" and
  registry.value : "fDenyTSConnections" and
  registry.data.strings : ("0", "0x00000000") and
  not process.executable : (
        "?:\\Windows\\System32\\SystemPropertiesRemote.exe",
        "?:\\Windows\\System32\\SystemPropertiesComputerName.exe",
        "?:\\Windows\\System32\\SystemPropertiesAdvanced.exe",
        "?:\\Windows\\System32\\SystemSettingsAdminFlows.exe",
        "?:\\Windows\\WinSxS\\*\\TiWorker.exe",
        "?:\\Windows\\system32\\svchost.exe",
        "\\Device\\HarddiskVolume*\\Windows\\System32\\SystemPropertiesRemote.exe",
        "\\Device\\HarddiskVolume*\\Windows\\System32\\SystemPropertiesComputerName.exe",
        "\\Device\\HarddiskVolume*\\Windows\\System32\\SystemPropertiesAdvanced.exe",
        "\\Device\\HarddiskVolume*\\Windows\\System32\\SystemSettingsAdminFlows.exe",
        "\\Device\\HarddiskVolume*\\Windows\\WinSxS\\*\\TiWorker.exe",
        "\\Device\\HarddiskVolume*\\Windows\\system32\\svchost.exe"
  )

// Title: lateral_movement_rdp_sharprdp_target.toml
// Source: detection-rules::rules/windows/lateral_movement_rdp_sharprdp_target.toml
// Section: EQL Rule
// Rule Name: Potential SharpRDP Behavior
// Author: Elastic
// Description:
// Identifies potential behavior of SharpRDP, which is a tool that can be used to perform authenticated command execution
// against a remote target via Remote Desktop Protocol (RDP) for the purposes of lateral movement.
// Integration: endpoint
// Language: eql
// UUID: 8c81e506-6e82-4884-9b9a-75d3d252f967
// Type: eql

/* Incoming RDP followed by a new RunMRU string value set to cmd, powershell, taskmgr or tsclient, followed by process execution within 1m */

sequence by host.id with maxspan=1m
  [network where host.os.type == "windows" and event.type == "start" and process.name : "svchost.exe" and destination.port == 3389 and
   network.direction : ("incoming", "ingress") and network.transport == "tcp" and
   source.ip != "127.0.0.1" and source.ip != "::1"
  ]

  [registry where host.os.type == "windows" and event.type == "change" and process.name : "explorer.exe" and
   registry.path : ("HKEY_USERS\\*\\Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\RunMRU\\*") and
   registry.data.strings : ("cmd.exe*", "powershell.exe*", "taskmgr*", "\\\\tsclient\\*.exe\\*")
  ]

  [process where host.os.type == "windows" and event.type == "start" and
   (process.parent.name : ("cmd.exe", "powershell.exe", "taskmgr.exe") or process.args : ("\\\\tsclient\\*.exe")) and
   not process.name : "conhost.exe"
   ]

// Title: lateral_movement_remote_file_copy_hidden_share.toml
// Source: detection-rules::rules/windows/lateral_movement_remote_file_copy_hidden_share.toml
// Section: EQL Rule
// Rule Name: Remote File Copy to a Hidden Share
// Author: Elastic
// Description:
// Identifies a remote file copy attempt to a hidden network share. This may indicate lateral movement or data staging
// activity.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: fa01341d-6662-426b-9d0c-6d81e33c8a9d
// Type: eql

process where host.os.type == "windows" and event.type == "start" and user.id != "S-1-5-18" and
  process.name : ("cmd.exe", "powershell.exe") and
  process.command_line : "*\\\\*\\*$*" and process.command_line : ("* copy*", "* move*", "* cp *", "* mv *")

// Title: lateral_movement_remote_task_creation_winlog.toml
// Source: detection-rules::rules/windows/lateral_movement_remote_task_creation_winlog.toml
// Section: EQL Rule
// Rule Name: Remote Scheduled Task Creation via RPC
// Author: Elastic
// Description:
// Identifies scheduled task creation from a remote source. This could be indicative of adversary lateral movement.
// Integration: system, windows
// Language: eql
// UUID: 9c865691-5599-447a-bac9-b3f2df5f9a9d
// Type: eql

iam where host.os.type == "windows" and event.action == "scheduled-task-created" and
 winlog.event_data.RpcCallClientLocality : "0" and winlog.event_data.ClientProcessId : "0"

// Title: lateral_movement_scheduled_task_target.toml
// Source: detection-rules::rules/windows/lateral_movement_scheduled_task_target.toml
// Section: EQL Rule
// Rule Name: Remote Scheduled Task Creation
// Author: Elastic
// Description:
// Identifies remote scheduled task creations on a target host. This could be indicative of adversary lateral movement.
// Integration: endpoint, windows, sentinel_one_cloud_funnel
// Language: eql
// UUID: 954ee7c8-5437-49ae-b2d6-2960883898e9
// Type: eql

/* Task Scheduler service incoming connection followed by TaskCache registry modification  */

sequence by host.id, process.entity_id with maxspan = 1m
   [network where host.os.type == "windows" and process.name : "svchost.exe" and
   network.direction : ("incoming", "ingress") and source.port >= 49152 and destination.port >= 49152 and
   source.ip != "127.0.0.1" and source.ip != "::1" and source.ip != null
   ]
   [registry where host.os.type == "windows" and event.type == "change" and registry.value : "Actions" and
    registry.path : "*\\SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\Schedule\\TaskCache\\Tasks\\*\\Actions"]

// Title: lateral_movement_suspicious_rdp_client_imageload.toml
// Source: detection-rules::rules/windows/lateral_movement_suspicious_rdp_client_imageload.toml
// Section: EQL Rule
// Rule Name: Suspicious RDP ActiveX Client Loaded
// Author: Elastic
// Description:
// Identifies suspicious Image Loading of the Remote Desktop Services ActiveX Client (mstscax), this may indicate the
// presence of RDP lateral movement capability.
// Integration: endpoint, windows
// Language: eql
// UUID: 71c5cb27-eca5-4151-bb47-64bc3f883270
// Type: eql

any where host.os.type == "windows" and
 (event.category : ("library", "driver") or (event.category == "process" and event.action : "Image loaded*")) and
 (?dll.name : "mstscax.dll" or file.name : "mstscax.dll") and
   /* depending on noise in your env add here extra paths  */
  process.executable : (
    "C:\\Windows\\*",
    "C:\\Users\\Public\\*",
    "C:\\Users\\Default\\*",
    "C:\\Intel\\*",
    "C:\\PerfLogs\\*",
    "C:\\ProgramData\\*",
    "\\Device\\Mup\\*",
    "\\\\*"
  ) and
  /* add here FPs */
  not process.executable : (
    "?:\\Windows\\System32\\mstsc.exe",
    "?:\\Windows\\SysWOW64\\mstsc.exe",
    "?:\\Windows\\System32\\vmconnect.exe",
    "?:\\Windows\\System32\\WindowsSandboxClient.exe",
    "?:\\Windows\\System32\\hvsirdpclient.exe"
  )

// Title: lateral_movement_unusual_dns_service_children.toml
// Source: detection-rules::rules/windows/lateral_movement_unusual_dns_service_children.toml
// Section: EQL Rule
// Rule Name: Unusual Child Process of dns.exe
// Author: Elastic
// Description:
// Identifies an unexpected process spawning from dns.exe, the process responsible for Windows DNS server services, which
// may indicate activity related to remote code execution or other forms of exploitation.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 8c37dc0e-e3ac-4c97-8aa0-cf6a9122de45
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.parent.name : "dns.exe" and
  not process.executable : (
    "?:\\Windows\\System32\\conhost.exe",
    "?:\\Windows\\System32\\dns.exe",

    /* Crowdstrike specific exclusion as it uses NT Object paths */
    "\\Device\\HarddiskVolume*\\Windows\\System32\\conhost.exe",
    "\\Device\\HarddiskVolume*\\Windows\\System32\\dns.exe",
    "\\Device\\HarddiskVolume*\\Program Files\\ReasonLabs\\*"
  ) and
  not ?process.parent.executable : "?:\\Program Files\\ReasonLabs\\DNS\\ui\\DNS.exe"

// Title: lateral_movement_via_startup_folder_rdp_smb.toml
// Source: detection-rules::rules/windows/lateral_movement_via_startup_folder_rdp_smb.toml
// Section: EQL Rule
// Rule Name: Lateral Movement via Startup Folder
// Author: Elastic
// Description:
// Identifies suspicious file creations in the startup folder of a remote system. An adversary could abuse this to move
// laterally by dropping a malicious script or executable that will be executed after a reboot or user logon.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel
// Language: eql
// UUID: 25224a80-5a4a-4b8a-991e-6ab390465c4f
// Type: eql

file where host.os.type == "windows" and event.type in ("creation", "change") and

 /* via RDP TSClient mounted share or SMB */
  (process.name : "mstsc.exe" or process.pid == 4) and

   file.path : ("?:\\Users\\*\\AppData\\Roaming\\Microsoft\\Windows\\Start Menu\\Programs\\Startup\\*",
                "?:\\ProgramData\\Microsoft\\Windows\\Start Menu\\Programs\\Startup\\*")

// Title: lateral_movement_via_wsus_update.toml
// Source: detection-rules::rules/windows/lateral_movement_via_wsus_update.toml
// Section: EQL Rule
// Rule Name: Potential WSUS Abuse for Lateral Movement
// Author: Elastic
// Description:
// Identifies a potential Windows Server Update Services (WSUS) abuse to execute psexec to enable for lateral movement.
// WSUS is limited to executing Microsoft signed binaries, which limits the executables that can be used to tools published
// by Microsoft.
// Integration: endpoint, windows, system, sentinel_one_cloud_funnel, m365_defender, crowdstrike
// Language: eql
// UUID: 8e2485b6-a74f-411b-bf7f-38b819f3a846
// Type: eql

process where host.os.type == "windows" and event.type == "start" and process.parent.name : "wuauclt.exe" and
process.executable : (
    "?:\\Windows\\SoftwareDistribution\\Download\\Install\\*",
    "\\Device\\HarddiskVolume?\\Windows\\SoftwareDistribution\\Download\\Install\\*"
) and
(process.name : "psexec64.exe" or ?process.pe.original_file_name : "psexec.c")

// Title: persistence_app_compat_shim.toml
// Source: detection-rules::rules/windows/persistence_app_compat_shim.toml
// Section: EQL Rule
// Rule Name: Installation of Custom Shim Databases
// Author: Elastic
// Description:
// Identifies the installation of custom Application Compatibility Shim databases. This Windows functionality has been
// abused by attackers to stealthily gain persistence and arbitrary code execution in legitimate Windows processes.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: c5ce48a6-7f57-4ee8-9313-3d0024caee10
// Type: eql

registry where host.os.type == "windows" and event.type == "change" and
  registry.path : "*\\SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\AppCompatFlags\\Custom\\*.sdb" and
  not process.executable : (
        "?:\\Program Files (x86)\\DesktopCentral_Agent\\*\\Setup\\NwSapSetup.exe",
        "?:\\$WINDOWS.~BT\\Sources\\SetupPlatform.exe",
        "?:\\Program Files (x86)\\SAP\\SAPsetup\\setup\\NwSapSetup.exe",
        "?:\\Program Files (x86)\\SAP\\SapSetup\\OnRebootSvc\\NWSAPSetupOnRebootInstSvc.exe",
        "?:\\Program Files (x86)\\Kaspersky Lab\\Kaspersky Security for Windows Server\\kavfs.exe",

        /* Crowdstrike specific exclusion as it uses NT Object paths */
        "\\Device\\HarddiskVolume*\\Program Files (x86)\\DesktopCentral_Agent\\*\\Setup\\NwSapSetup.exe",
        "\\Device\\HarddiskVolume*\\$WINDOWS.~BT\\Sources\\SetupPlatform.exe",
        "\\Device\\HarddiskVolume*\\Program Files (x86)\\SAP\\SAPsetup\\setup\\NwSapSetup.exe",
        "\\Device\\HarddiskVolume*\\Program Files (x86)\\SAP\\SapSetup\\OnRebootSvc\\NWSAPSetupOnRebootInstSvc.exe",
        "\\Device\\HarddiskVolume*\\Program Files (x86)\\Kaspersky Lab\\Kaspersky Security for Windows Server\\kavfs.exe"
  )

// Title: persistence_appcertdlls_registry.toml
// Source: detection-rules::rules/windows/persistence_appcertdlls_registry.toml
// Section: EQL Rule
// Rule Name: Registry Persistence via AppCert DLL
// Author: Elastic
// Description:
// Detects attempts to maintain persistence by creating registry keys using AppCert DLLs. AppCert DLLs are loaded by every
// process using the common API functions to create processes.
// Integration: endpoint, windows, sentinel_one_cloud_funnel, m365_defender, crowdstrike
// Language: eql
// UUID: 513f0ffd-b317-4b9c-9494-92ce861f22c7
// Type: eql

registry where host.os.type == "windows" and event.type == "change" and
  registry.path : "*\\SYSTEM\\*ControlSet*\\Control\\Session Manager\\AppCertDLLs\\*"

// Title: persistence_appinitdlls_registry.toml
// Source: detection-rules::rules/windows/persistence_appinitdlls_registry.toml
// Section: EQL Rule
// Rule Name: Registry Persistence via AppInit DLL
// Author: Elastic
// Description:
// AppInit DLLs are dynamic-link libraries (DLLs) that are loaded into every process that creates a user interface (loads
// user32.dll) on Microsoft Windows operating systems. The AppInit DLL mechanism is used to load custom code into user-mode
// processes, allowing for the customization of the user interface and the behavior of Windows-based applications.
// Attackers who add those DLLs to the registry locations can execute code with elevated privileges, similar to process
// injection, and provide a solid and constant persistence on the machine.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: d0e159cf-73e9-40d1-a9ed-077e3158a855
// Type: eql

registry where host.os.type == "windows" and event.type == "change" and
  registry.value : "AppInit_Dlls" and
  not process.executable : (
     "?:\\Windows\\System32\\DriverStore\\FileRepository\\*\\Display.NvContainer\\NVDisplay.Container.exe",
     "?:\\Windows\\System32\\msiexec.exe",
     "?:\\Windows\\SysWOW64\\msiexec.exe",
     "?:\\Program Files\\Commvault\\Base\\cvd.exe",
     "?:\\Program Files\\Commvault\\ContentStore*\\Base\\cvd.exe",
     "?:\\Program Files (x86)\\Commvault\\Base\\cvd.exe",
     "?:\\Program Files (x86)\\Commvault\\ContentStore*\\Base\\cvd.exe",
     "?:\\Program Files\\NVIDIA Corporation\\Display.NvContainer\\NVDisplay.Container.exe",

     /* Crowdstrike specific condition as it uses NT Object paths */
     "\\Device\\HarddiskVolume*\\Windows\\System32\\DriverStore\\FileRepository\\*\\Display.NvContainer\\NVDisplay.Container.exe",
     "\\Device\\HarddiskVolume*\\Windows\\System32\\msiexec.exe",
     "\\Device\\HarddiskVolume*\\Windows\\SysWOW64\\msiexec.exe",
     "\\Device\\HarddiskVolume*\\Program Files\\Commvault\\Base\\cvd.exe",
     "\\Device\\HarddiskVolume*\\Program Files\\Commvault\\ContentStore*\\Base\\cvd.exe",
     "\\Device\\HarddiskVolume*\\Program Files (x86)\\Commvault\\Base\\cvd.exe",
     "\\Device\\HarddiskVolume*\\Program Files (x86)\\Commvault\\ContentStore*\\Base\\cvd.exe",
     "\\Device\\HarddiskVolume*\\Program Files\\NVIDIA Corporation\\Display.NvContainer\\NVDisplay.Container.exe"
  )
  /*
    Full registry key path omitted due to data source variations:
    "HKLM\\SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\Windows\\AppInit_Dlls"
    "HKLM\\SOFTWARE\\Wow6432Node\\Microsoft\\Windows NT\\CurrentVersion\\Windows\\AppInit_Dlls"
  */

// Title: persistence_browser_extension_install.toml
// Source: detection-rules::rules/windows/persistence_browser_extension_install.toml
// Section: EQL Rule
// Rule Name: Browser Extension Install
// Author: Elastic
// Description:
// Identifies the install of browser extensions. Malicious browser extensions can be installed via app store downloads
// masquerading as legitimate extensions, social engineering, or by an adversary that has already compromised a system.
// Integration: endpoint, m365_defender, sentinel_one_cloud_funnel, windows
// Language: eql
// UUID: f97504ac-1053-498f-aeaa-c6d01e76b379
// Type: eql

file where host.os.type == "windows" and event.type : "creation" and
(
  /* Firefox-Based Browsers */
  (
    file.name : "*.xpi" and
    file.path : "?:\\Users\\*\\AppData\\Roaming\\*\\Profiles\\*\\Extensions\\*.xpi" and
    not
    (
      process.name : "firefox.exe" and
      file.name : (
        "langpack-*@firefox.mozilla.org.xpi",
        "*@dictionaries.addons.mozilla.org.xpi",
        "newtab@mozilla.org.xpi",
        "uBlock0@raymondhill.net.xpi",
        /* AdBlockPlus */
        "{d10d0bf8-f5b5-c8b4-a8b2-2b9879e08c5d}.xpi",
        /* Bitwarden */
        "{446900e4-71c2-419f-a6a7-df9c091e268b}.xpi",
        "addon@darkreader.org.xpi",
        /* 1Password */
        "{d634138d-c276-4fc8-924b-40a0ea21d284}.xpi",
        "support@lastpass.com.xpi",
        /* Grammarly */
        "87677a2c52b84ad3a151a4a72f5bd3c4@jetpack.xpi",
        "sentinelone_visibility@sentinelone.com.xpi",
        "keepassxc-browser@keepassxc.org.xpi"
      )
    )
  ) or
  /* Chromium-Based Browsers */
  (
    file.name : "*.crx" and
    file.path : "?:\\Users\\*\\AppData\\Local\\*\\*\\User Data\\Webstore Downloads\\*"
  )
)

// Title: persistence_dontexpirepasswd_account.toml
// Source: detection-rules::rules/windows/persistence_dontexpirepasswd_account.toml
// Section: EQL Rule
// Rule Name: Account Configured with Never-Expiring Password
// Author: Elastic
// Description:
// Detects the creation and modification of an account with the "Don't Expire Password" option Enabled. Attackers can abuse
// this misconfiguration to persist in the domain and maintain long-term access using compromised accounts with this
// property.
// Integration: system, windows
// Language: eql
// UUID: 62a70f6f-3c37-43df-a556-f64fa475fba2
// Type: eql

any where host.os.type == "windows" and
(
  (
    event.code == "4738" and winlog.event_data.NewUACList == "USER_DONT_EXPIRE_PASSWORD" and not user.id == "S-1-5-18"
  ) or
  (
    event.code == "5136" and winlog.event_data.AttributeLDAPDisplayName == "userAccountControl" and
    winlog.event_data.AttributeValue in ("66048", "66080") and winlog.event_data.OperationType == "%%14674" and
    not (
      winlog.event_data.SubjectUserName : "*svc*" or
      winlog.event_data.ObjectDN : "*Service*"
    )
  )
)

// Title: persistence_evasion_hidden_local_account_creation.toml
// Source: detection-rules::rules/windows/persistence_evasion_hidden_local_account_creation.toml
// Section: EQL Rule
// Rule Name: Creation of a Hidden Local User Account
// Author: Elastic
// Description:
// Identifies the creation of a hidden local user account by appending the dollar sign to the account name. This is
// sometimes done by attackers to increase access to a system and avoid appearing in the results of accounts listing using
// the net users command.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 2edc8076-291e-41e9-81e4-e3fcbc97ae5e
// Type: eql

registry where host.os.type == "windows" and event.type in ("change", "creation") and
  registry.path : (
    "HKLM\\SAM\\SAM\\Domains\\Account\\Users\\Names\\*$\\",
    "\\REGISTRY\\MACHINE\\SAM\\SAM\\Domains\\Account\\Users\\Names\\*$\\",
    "MACHINE\\SAM\\SAM\\Domains\\Account\\Users\\Names\\*$\\"
)

// Title: persistence_evasion_registry_ifeo_injection.toml
// Source: detection-rules::rules/windows/persistence_evasion_registry_ifeo_injection.toml
// Section: EQL Rule
// Rule Name: Image File Execution Options Injection
// Author: Elastic
// Description:
// The Debugger and SilentProcessExit registry keys can allow an adversary to intercept the execution of files, causing a
// different process to be executed. This functionality can be abused by an adversary to establish persistence.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 6839c821-011d-43bd-bd5b-acff00257226
// Type: eql

registry where host.os.type == "windows" and event.type == "change" and
  registry.value : ("Debugger", "MonitorProcess") and length(registry.data.strings) > 0 and
  registry.path : (
    "HKLM\\SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\Image File Execution Options\\*.exe\\Debugger",
    "HKLM\\SOFTWARE\\WOW6432Node\\Microsoft\\Windows NT\\CurrentVersion\\Image File Execution Options\\*\\Debugger",
    "HKLM\\SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\SilentProcessExit\\*\\MonitorProcess",
    "HKLM\\SOFTWARE\\WOW6432Node\\Microsoft\\Windows NT\\CurrentVersion\\SilentProcessExit\\*\\MonitorProcess",
    "\\REGISTRY\\MACHINE\\SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\Image File Execution Options\\*.exe\\Debugger",
    "\\REGISTRY\\MACHINE\\SOFTWARE\\WOW6432Node\\Microsoft\\Windows NT\\CurrentVersion\\Image File Execution Options\\*\\Debugger",
    "\\REGISTRY\\MACHINE\\SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\SilentProcessExit\\*\\MonitorProcess",
    "\\REGISTRY\\MACHINE\\SOFTWARE\\WOW6432Node\\Microsoft\\Windows NT\\CurrentVersion\\SilentProcessExit\\*\\MonitorProcess",
    "MACHINE\\SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\Image File Execution Options\\*.exe\\Debugger",
    "MACHINE\\SOFTWARE\\WOW6432Node\\Microsoft\\Windows NT\\CurrentVersion\\Image File Execution Options\\*\\Debugger",
    "MACHINE\\SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\SilentProcessExit\\*\\MonitorProcess",
    "MACHINE\\SOFTWARE\\WOW6432Node\\Microsoft\\Windows NT\\CurrentVersion\\SilentProcessExit\\*\\MonitorProcess"
  ) and
    /* add FPs here */
  not registry.data.strings regex~ ("""C:\\Program Files( \(x86\))?\\ThinKiosk\\thinkiosk\.exe""", """.*\\PSAppDeployToolkit\\.*""")

// Title: persistence_evasion_registry_startup_shell_folder_modified.toml
// Source: detection-rules::rules/windows/persistence_evasion_registry_startup_shell_folder_modified.toml
// Section: EQL Rule
// Rule Name: Suspicious Startup Shell Folder Modification
// Author: Elastic
// Description:
// Identifies suspicious startup shell folder modifications to change the default Startup directory in order to bypass
// detections monitoring file creation in the Windows Startup folder.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: c8b150f0-0164-475b-a75e-74b47800a9ff
// Type: eql

registry where host.os.type == "windows" and event.type == "change" and
 registry.value : ("Common Startup", "Startup") and
 registry.path : (
     "HKLM\\Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\User Shell Folders\\Common Startup",
     "HKLM\\Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\Shell Folders\\Common Startup",
     "HKEY_USERS\\*\\Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\User Shell Folders\\Startup",
     "HKEY_USERS\\*\\Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\Shell Folders\\Startup",
     "HKU\\*\\Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\User Shell Folders\\Startup",
     "HKU\\*\\Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\Shell Folders\\Startup",
     "HKCU\\*\\Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\User Shell Folders\\Startup",
     "HKCU\\*\\Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\Shell Folders\\Startup",
     "\\REGISTRY\\MACHINE\\Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\User Shell Folders\\Common Startup",
     "\\REGISTRY\\MACHINE\\Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\Shell Folders\\Common Startup",
     "\\REGISTRY\\USER\\*\\Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\User Shell Folders\\Startup",
     "\\REGISTRY\\USER\\*\\Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\Shell Folders\\Startup",
     "MACHINE\\Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\User Shell Folders\\Common Startup",
     "MACHINE\\Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\Shell Folders\\Common Startup",
     "USER\\*\\Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\User Shell Folders\\Startup",
     "USER\\*\\Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\Shell Folders\\Startup"
     ) and
  registry.data.strings != null and
  /* Normal Startup Folder Paths */
  not registry.data.strings : (
           "C:\\ProgramData\\Microsoft\\Windows\\Start Menu\\Programs\\Startup",
           "%ProgramData%\\Microsoft\\Windows\\Start Menu\\Programs\\Startup",
           "%USERPROFILE%\\AppData\\Roaming\\Microsoft\\Windows\\Start Menu\\Programs\\Startup",
           "%%USERPROFILE%%\\AppData\\Roaming\\Microsoft\\Windows\\Start Menu\\Programs\\Startup",
           "C:\\Users\\*\\AppData\\Roaming\\Microsoft\\Windows\\Start Menu\\Programs\\Startup",
           "\\\\*"
           )

// Title: persistence_group_modification_by_system.toml
// Source: detection-rules::rules/windows/persistence_group_modification_by_system.toml
// Section: EQL Rule
// Rule Name: Active Directory Group Modification by SYSTEM
// Author: Elastic
// Description:
// Identifies a user being added to an active directory group by the SYSTEM (S-1-5-18) user. This behavior can indicate
// that the attacker has achieved SYSTEM privileges in a domain controller, which attackers can obtain by exploiting
// vulnerabilities or abusing default group privileges (e.g., Server Operators), and is attempting to pivot to a domain
// account.
// Integration: system, windows
// Language: eql
// UUID: 6f024bde-7085-489b-8250-5957efdf1caf
// Type: eql

iam where host.os.type == "windows" and event.code == "4728" and
winlog.event_data.SubjectUserSid : "S-1-5-18" and

/* DOMAIN_USERS and local groups */
not group.id : "S-1-5-21-*-513"

// Title: persistence_local_scheduled_job_creation.toml
// Source: detection-rules::rules/windows/persistence_local_scheduled_job_creation.toml
// Section: EQL Rule
// Rule Name: Persistence via Scheduled Job Creation
// Author: Elastic
// Description:
// A job can be used to schedule programs or scripts to be executed at a specified date and time. Adversaries may abuse
// task scheduling functionality to facilitate initial or recurring execution of malicious code.
// Integration: endpoint, windows, sentinel_one_cloud_funnel, m365_defender
// Language: eql
// UUID: 1327384f-00f3-44d5-9a8c-2373ba071e92
// Type: eql

file where host.os.type == "windows" and event.type != "deletion" and
  file.path : "?:\\Windows\\Tasks\\*" and file.extension : "job" and
  not (
    (
      process.executable : "?:\\Program Files\\CCleaner\\CCleaner64.exe" and
      file.path : "?:\\Windows\\Tasks\\CCleanerCrashReporting.job"
    ) or
    process.executable : (
      "?:\\Program Files (x86)\\DesktopCentral_Agent\\bin\\dcagentregister.exe",
      "?:\\Program Files (x86)\\epson\\Epson Scan 2\\Update\\e_dtsksd.exe",
      "?:\\Program Files (x86)\\ManageEngine\\UEMS_Agent\\bin\\dcagentregister.exe",
      "?:\\Program Files (x86)\\ManageEngine\\UEMS_Agent\\dcconfig.exe",
      "?:\\Program Files (x86)\\ManageEngine\\UEMS_Agent\\Updates\\UemsComponentUpgrader.exe",
      "?:\\Program Files (x86)\\Skillbrains\\Updater\\*\\Updater.exe",
      "?:\\Windows\\System32\\drivers\\RivetNetworks\\Killer\\CustomizeInstallFirstRun.exe"
    )
  )

// Title: persistence_local_scheduled_task_creation.toml
// Source: detection-rules::rules/windows/persistence_local_scheduled_task_creation.toml
// Section: EQL Rule
// Rule Name: Local Scheduled Task Creation
// Author: Elastic
// Description:
// Indicates the creation of a scheduled task. Adversaries can use these to establish persistence, move laterally, and/or
// escalate privileges.
// Integration: endpoint, windows
// Language: eql
// UUID: afcce5ad-65de-4ed2-8516-5e093d3ac99a
// Type: eql

sequence with maxspan=1m
  [process where host.os.type == "windows" and event.type == "start" and
    ((process.name : ("cmd.exe", "wscript.exe", "rundll32.exe", "regsvr32.exe", "wmic.exe", "mshta.exe",
                      "powershell.exe", "pwsh.exe", "powershell_ise.exe", "WmiPrvSe.exe", "wsmprovhost.exe", "winrshost.exe") or
    process.pe.original_file_name : ("cmd.exe", "wscript.exe", "rundll32.exe", "regsvr32.exe", "wmic.exe", "mshta.exe",
                                     "powershell.exe", "pwsh.dll", "powershell_ise.exe", "WmiPrvSe.exe", "wsmprovhost.exe",
                                     "winrshost.exe")) or
    ?process.code_signature.trusted == false) and
    /* exclude legitimate software creating its own scheduled tasks */
    not (
      process.name : "cmd.exe" and
      (
        (
          process.parent.executable : "?:\\Program Files\\Adobe\\Adobe Creative Cloud Experience\\libs\\node.exe" and
          process.command_line : "*?:\\Program Files\\Adobe\\Adobe Creative Cloud Experience\\CCXProcess.exe*"
        ) or
        (
          process.parent.executable : "?:\\Program Files (x86)\\LG Software\\LG App Count\\LGAppCountObserver.exe" and
          process.command_line : "*?:\\Program Files (x86)\\LG Software\\LG App Count\\*"
        ) or
        (
          process.parent.executable : "?:\\Program Files (x86)\\LG Software\\LG Update & Recovery\\URAlarm.exe" and
          process.command_line : "*?:\\Program Files (x86)\\LG Software\\LG Update & Recovery\\Support\\*"
        )
      )
    )
  ] by process.entity_id
  [process where host.os.type == "windows" and event.type == "start" and
    (process.name : "schtasks.exe" or process.pe.original_file_name == "schtasks.exe") and
    process.args : ("/create", "-create") and process.args : ("/RU", "/SC", "/TN", "/TR", "/F", "/XML") and
    /* exclude SYSTEM Integrity Level - look for task creations by non-SYSTEM user */
    not (?process.Ext.token.integrity_level_name : "System" or ?winlog.event_data.IntegrityLevel : "System")
  ] by process.parent.entity_id

// Title: persistence_local_scheduled_task_scripting.toml
// Source: detection-rules::rules/windows/persistence_local_scheduled_task_scripting.toml
// Section: EQL Rule
// Rule Name: Scheduled Task Created by a Windows Script
// Author: Elastic
// Description:
// A scheduled task was created by a Windows script via cscript.exe, wscript.exe or powershell.exe. This can be abused by
// an adversary to establish persistence.
// Integration: endpoint, windows
// Language: eql
// UUID: 689b9d57-e4d5-4357-ad17-9c334609d79a
// Type: eql

sequence by host.id with maxspan = 30s
  [any where host.os.type == "windows" and 
    (event.category : ("library", "driver") or (event.category == "process" and event.action : "Image loaded*")) and
    (?dll.name : "taskschd.dll" or file.name : "taskschd.dll") and
    process.name : ("cscript.exe", "wscript.exe", "powershell.exe", "pwsh.exe", "powershell_ise.exe")]
  [registry where host.os.type == "windows" and event.type == "change" and registry.value : "Actions" and
    registry.path : (
      "HKLM\\SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\Schedule\\TaskCache\\Tasks\\*\\Actions",
      "\\REGISTRY\\MACHINE\\SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\Schedule\\TaskCache\\Tasks\\*\\Actions"
  )]

// Title: persistence_ms_office_addins_file.toml
// Source: detection-rules::rules/windows/persistence_ms_office_addins_file.toml
// Section: EQL Rule
// Rule Name: Persistence via Microsoft Office AddIns
// Author: Elastic
// Description:
// Detects attempts to establish persistence on an endpoint by abusing Microsoft Office add-ins.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: f44fa4b6-524c-4e87-8d9e-a32599e4fb7c
// Type: eql

file where host.os.type == "windows" and event.type != "deletion" and
 file.extension : ("wll","xll","ppa","ppam","xla","xlam") and
 file.path : (
    "C:\\Users\\*\\AppData\\Roaming\\Microsoft\\Word\\Startup\\*",
    "C:\\Users\\*\\AppData\\Roaming\\Microsoft\\AddIns\\*",
    "C:\\Users\\*\\AppData\\Roaming\\Microsoft\\Excel\\XLSTART\\*",

    /* Crowdstrike specific condition as it uses NT Object paths */
    "\\Device\\HarddiskVolume*\\Users\\*\\AppData\\Roaming\\Microsoft\\Word\\Startup\\*",
    "\\Device\\HarddiskVolume*\\Users\\*\\AppData\\Roaming\\Microsoft\\AddIns\\*",
    "\\Device\\HarddiskVolume*\\Users\\*\\AppData\\Roaming\\Microsoft\\Excel\\XLSTART\\*"
 ) and
 not (file.name : "~$*" and process.name : "excel.exe" and ?file.size in (0, 165))

// Title: persistence_ms_outlook_vba_template.toml
// Source: detection-rules::rules/windows/persistence_ms_outlook_vba_template.toml
// Section: EQL Rule
// Rule Name: Persistence via Microsoft Outlook VBA
// Author: Elastic
// Description:
// Detects attempts to establish persistence on an endpoint by installing a rogue Microsoft Outlook VBA Template.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 397945f3-d39a-4e6f-8bcb-9656c2031438
// Type: eql

file where host.os.type == "windows" and event.type != "deletion" and
  file.name : "VbaProject.OTM" and
  file.path : ("?:\\Users\\*\\AppData\\Roaming\\Microsoft\\Outlook\\VbaProject.OTM", "\\Device\\HarddiskVolume*\\Users\\*\\AppData\\Roaming\\Microsoft\\Outlook\\VbaProject.OTM")

// Title: persistence_msds_alloweddelegateto_krbtgt.toml
// Source: detection-rules::rules/windows/persistence_msds_alloweddelegateto_krbtgt.toml
// Section: EQL Rule
// Rule Name: KRBTGT Delegation Backdoor
// Author: Elastic
// Description:
// Identifies the modification of the msDS-AllowedToDelegateTo attribute to KRBTGT. Attackers can use this technique to
// maintain persistence to the domain by having the ability to request tickets for the KRBTGT service.
// Integration: system, windows
// Language: eql
// UUID: e052c845-48d0-4f46-8a13-7d0aba05df82
// Type: eql

iam where host.os.type == "windows" and event.code == "4738" and winlog.event_data.AllowedToDelegateTo : "*krbtgt*"

// Title: persistence_msoffice_startup_registry.toml
// Source: detection-rules::rules/windows/persistence_msoffice_startup_registry.toml
// Section: EQL Rule
// Rule Name: Office Test Registry Persistence
// Author: Elastic
// Description:
// Identifies the modification of the Microsoft Office "Office Test" Registry key, a registry location that can be used to
// specify a DLL which will be executed every time an MS Office application is started. Attackers can abuse this to gain
// persistence on a compromised host.
// Integration: endpoint, m365_defender, sentinel_one_cloud_funnel, crowdstrike, windows
// Language: eql
// UUID: 14dab405-5dd9-450c-8106-72951af2391f
// Type: eql

registry where host.os.type == "windows" and event.action != "deletion" and
    registry.path : "*\\Software\\Microsoft\\Office Test\\Special\\Perf\\*"

// Title: persistence_netsh_helper_dll.toml
// Source: detection-rules::rules/windows/persistence_netsh_helper_dll.toml
// Section: EQL Rule
// Rule Name: Netsh Helper DLL
// Author: Elastic
// Description:
// Identifies the addition of a Netsh Helper DLL, netsh.exe supports the addition of these DLLs to extend its
// functionality. Attackers may abuse this mechanism to execute malicious payloads every time the utility is executed,
// which can be done by administrators or a scheduled task.
// Integration: endpoint, m365_defender, sentinel_one_cloud_funnel, windows, crowdstrike
// Language: eql
// UUID: b0638186-4f12-48ac-83d2-47e686d08e82
// Type: eql

registry where host.os.type == "windows" and event.type == "change" and
  registry.path : (
    "HKLM\\Software\\Microsoft\\netsh\\*",
    "\\REGISTRY\\MACHINE\\Software\\Microsoft\\netsh\\*",
    "MACHINE\\Software\\Microsoft\\netsh\\*"
  )

// Title: persistence_powershell_exch_mailbox_activesync_add_device.toml
// Source: detection-rules::rules/windows/persistence_powershell_exch_mailbox_activesync_add_device.toml
// Section: EQL Rule
// Rule Name: New ActiveSyncAllowedDeviceID Added via PowerShell
// Author: Elastic
// Description:
// Identifies the use of the Exchange PowerShell cmdlet, Set-CASMailbox, to add a new ActiveSync allowed device.
// Adversaries may target user email to collect sensitive information.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: ce64d965-6cb0-466d-b74f-8d2c76f47f05
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.name: ("powershell.exe", "pwsh.exe", "powershell_ise.exe") and process.args : "Set-CASMailbox*ActiveSyncAllowedDeviceIDs*"

// Title: persistence_powershell_profiles.toml
// Source: detection-rules::rules/windows/persistence_powershell_profiles.toml
// Section: EQL Rule
// Rule Name: Persistence via PowerShell profile
// Author: Elastic
// Description:
// Identifies the creation or modification of a PowerShell profile. PowerShell profile is a script that is executed when
// PowerShell starts to customize the user environment, which can be abused by attackers to persist in a environment where
// PowerShell is common.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 5cf6397e-eb91-4f31-8951-9f0eaa755a31
// Type: eql

file where host.os.type == "windows" and event.type != "deletion" and
  file.name : ("profile.ps1", "Microsoft.Powershell_profile.ps1") and
  file.path : ("?:\\Users\\*\\Documents\\WindowsPowerShell\\*.ps1", 
                    "?:\\Users\\*\\Documents\\PowerShell\\*.ps1", 
                    "?:\\Windows\\System32\\WindowsPowerShell\\*.ps1", 
                    "\\Device\\HarddiskVolume*\\Users\\*\\Documents\\WindowsPowerShell\\*.ps1", 
                    "\\Device\\HarddiskVolume*\\Users\\*\\Documents\\PowerShell\\*.ps1", 
                    "\\Device\\HarddiskVolume*\\Windows\\System32\\WindowsPowerShell\\*.ps1")

// Title: persistence_priv_escalation_via_accessibility_features.toml
// Source: detection-rules::rules/windows/persistence_priv_escalation_via_accessibility_features.toml
// Section: EQL Rule
// Rule Name: Potential Modification of Accessibility Binaries
// Author: Elastic
// Description:
// Windows contains accessibility features that may be launched with a key combination before a user has logged in. An
// adversary can modify the way these programs are launched to get a command prompt or backdoor without logging in to the
// system.
// Integration: endpoint, windows, m365_defender
// Language: eql
// UUID: 7405ddf1-6c8e-41ce-818f-48bea6bcaed8
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
 process.parent.name : ("Utilman.exe", "winlogon.exe") and user.name == "SYSTEM" and
 process.pe.original_file_name : "?*" and
 process.args :
    (
    "C:\\Windows\\System32\\osk.exe",
    "C:\\Windows\\System32\\Magnify.exe",
    "C:\\Windows\\System32\\Narrator.exe",
    "C:\\Windows\\System32\\Sethc.exe",
    "utilman.exe",
    "ATBroker.exe",
    "DisplaySwitch.exe",
    "sethc.exe"
    )
 and not process.pe.original_file_name in
    (
    "osk.exe",
    "sethc.exe",
    "utilman2.exe",
    "DisplaySwitch.exe",
    "atbroker.exe",
    "ATBroker.exe",
    "ScreenMagnifier.exe",
    "SR.exe",
    "Narrator.exe",
    "magnify.exe",
    "MAGNIFY.EXE"
    )

// Title: persistence_remote_password_reset.toml
// Source: detection-rules::rules/windows/persistence_remote_password_reset.toml
// Section: EQL Rule
// Rule Name: Account Password Reset Remotely
// Author: Elastic
// Description:
// Identifies an attempt to reset a potentially privileged account password remotely. Adversaries may manipulate account
// passwords to maintain access or evade password duration policies and preserve compromised credentials.
// Integration: system, windows
// Language: eql
// UUID: 2820c9c2-bcd7-4d6e-9eba-faf3891ba450
// Type: eql

sequence by winlog.computer_name with maxspan=1m
  [authentication where host.os.type == "windows" and event.action == "logged-in" and
    /* event 4624 need to be logged */
    winlog.logon.type : "Network" and event.outcome == "success" and source.ip != null and
    source.ip != "127.0.0.1" and source.ip != "::1" and
    not winlog.event_data.TargetUserName : ("svc*", "PIM_*", "_*_", "*-*-*", "*$")] by winlog.event_data.TargetLogonId
   /* event 4724 need to be logged */
  [iam where host.os.type == "windows" and event.action == "reset-password" and
   (
    /*
       This rule is very noisy if not scoped to privileged accounts, duplicate the
       rule and add your own naming convention and accounts of interest here.
     */
    winlog.event_data.TargetUserName: ("*Admin*", "*super*", "*SVC*", "*DC0*", "*service*", "*DMZ*", "*ADM*") or
    winlog.event_data.TargetSid : ("S-1-5-21-*-500", "S-1-12-1-*-500")
    )
  ] by winlog.event_data.SubjectLogonId

// Title: persistence_runtime_run_key_startup_susp_procs.toml
// Source: detection-rules::rules/windows/persistence_runtime_run_key_startup_susp_procs.toml
// Section: EQL Rule
// Rule Name: Execution of Persistent Suspicious Program
// Author: Elastic
// Description:
// Identifies execution of suspicious persistent programs (scripts, rundll32, etc.) by looking at process lineage and
// command line usage.
// Integration: endpoint, windows
// Language: eql
// UUID: e7125cea-9fe1-42a5-9a05-b0792cf86f5a
// Type: eql

/* userinit followed by explorer followed by early child process of explorer (unlikely to be launched interactively) within 1m */
sequence by host.id, user.name with maxspan=1m
  [process where host.os.type == "windows" and event.type == "start" and process.name : "userinit.exe" and process.parent.name : "winlogon.exe"]
  [process where host.os.type == "windows" and event.type == "start" and process.name : "explorer.exe"]
  [process where host.os.type == "windows" and event.type == "start" and process.parent.name : "explorer.exe" and
   /* add suspicious programs here */
   process.pe.original_file_name in ("cscript.exe",
                                     "wscript.exe",
                                     "PowerShell.EXE",
                                     "MSHTA.EXE",
                                     "RUNDLL32.EXE",
                                     "REGSVR32.EXE",
                                     "RegAsm.exe",
                                     "MSBuild.exe",
                                     "InstallUtil.exe") and
    /* add potential suspicious paths here */
    process.args : ("C:\\Users\\*", "C:\\ProgramData\\*", "C:\\Windows\\Temp\\*", "C:\\Windows\\Tasks\\*", "C:\\PerfLogs\\*", "C:\\Intel\\*")
   ]

// Title: persistence_scheduled_task_creation_winlog.toml
// Source: detection-rules::rules/windows/persistence_scheduled_task_creation_winlog.toml
// Section: EQL Rule
// Rule Name: A scheduled task was created
// Author: Elastic
// Description:
// Indicates the creation of a scheduled task using Windows event logs. Adversaries can use these to establish persistence,
// move laterally, and/or escalate privileges.
// Integration: system, windows
// Language: eql
// UUID: 92a6faf5-78ec-4e25-bea1-73bacc9b59d9
// Type: eql

iam where host.os.type == "windows" and event.action == "scheduled-task-created" and

 /* excluding tasks created by the computer account */
 not user.name : "*$" and

 /* TaskContent is not parsed, exclude by full taskname noisy ones */
 not winlog.event_data.TaskName : (
              "\\CreateExplorerShellUnelevatedTask",
              "\\Hewlett-Packard\\HPDeviceCheck",
              "\\Hewlett-Packard\\HP Support Assistant\\WarrantyChecker",
              "\\Hewlett-Packard\\HP Support Assistant\\WarrantyChecker_backup",
              "\\Hewlett-Packard\\HP Web Products Detection",
              "\\Microsoft\\VisualStudio\\Updates\\BackgroundDownload",
              "\\OneDrive Standalone Update Task-S-1-5-21*",
              "\\OneDrive Standalone Update Task-S-1-12-1-*",
              "\\SoftLanding\\S-1-5-21-*\\SoftLanding*",
              "\\SoftLanding\\S-1-12-*\\SoftLanding*",
              "\\OneDrive Reporting Task-S-1-5-21-*",
              "\\OneDrive Reporting Task-S-1-12-1-*",
              "\\GoogleUserPEH\\RunPlatformExperienceHelper*",
              "\\Mozilla\\Firefox Default Browser Agent*",
              "\\Microsoft\\Office\\Office Background Push Maintenance",
              "\\Microsoft\\Windows\\GroupPolicy\\GPUpdate"
 )

// Title: persistence_sdprop_exclusion_dsheuristics.toml
// Source: detection-rules::rules/windows/persistence_sdprop_exclusion_dsheuristics.toml
// Section: EQL Rule
// Rule Name: AdminSDHolder SDProp Exclusion Added
// Author: Elastic
// Description:
// Identifies a modification on the dsHeuristics attribute on the bit that holds the configuration of groups excluded from
// the SDProp process. The SDProp compares the permissions on protected objects with those defined on the AdminSDHolder
// object. If the permissions on any of the protected accounts and groups do not match, the permissions on the protected
// accounts and groups are reset to match those of the domain's AdminSDHolder object, meaning that groups excluded will
// remain unchanged. Attackers can abuse this misconfiguration to maintain long-term access to privileged accounts in these
// groups.
// Integration: system, windows
// Language: eql
// UUID: 61d29caf-6c15-4d1e-9ccb-7ad12ccc0bc7
// Type: eql

any where host.os.type == "windows" and event.code == "5136" and
  winlog.event_data.AttributeLDAPDisplayName : "dSHeuristics" and
  winlog.event_data.OperationType : "%%14674" and
  length(winlog.event_data.AttributeValue) > 15 and
  winlog.event_data.AttributeValue regex~ "[0-9]{15}([1-9a-f]).*"

// Title: persistence_service_windows_service_winlog.toml
// Source: detection-rules::rules/windows/persistence_service_windows_service_winlog.toml
// Section: EQL Rule
// Rule Name: Suspicious Service was Installed in the System
// Author: Elastic
// Description:
// Identifies the creation of a new Windows service with a suspicious service name or command value. Windows services
// typically run as SYSTEM and can be used for privilege escalation and persistence.
// Integration: system, windows
// Language: eql
// UUID: da87eee1-129c-4661-a7aa-57d0b9645fad
// Type: eql

any where host.os.type == "windows" and
(
  (
    event.code : "4697" and
    (
      (
        (
          winlog.event_data.ServiceFileName : (
            "*COMSPEC*", "*\\127.0.0.1*", "*Admin$*", "*powershell*", "*rundll32*", "*cmd.exe*",
            "*echo*", "*RemComSvc*", "*.bat*", "*.cmd*", "*certutil*", "*vssadmin*", "*certmgr*", "*bitsadmin*",
            "*\\Users\\*", "*\\Windows\\Tasks\\*", "*\\PerfLogs\\*", "*\\Windows\\Debug\\*",
            "*regsvr32*", "*msbuild*", "*winexesvc.exe*", "*DumpSvc.exe*", "*pwsh.exe*", "*PAExec*"
          ) or
          winlog.event_data.ServiceFileName regex~ """%systemroot%\\[a-z0-9]+\.exe"""
        ) and
        not winlog.event_data.ServiceFileName: (
              "%SystemRoot%\\PSEXESVC.exe", "%SystemRoot%\\\\RemComSvc.exe",
              "%SystemRoot%\\pbpsdeploy.exe", "%SystemRoot%\\system32\\RemComSvc.exe",
              "\"C:\\Program Files\\Common Files\\Zoom\\Support\\CptService.exe*",
              "\"C:\\Program Files\\Common Files\\ZoomVDIPluginManagement\\Support\\CptService.exe*",
              "\"C:\\Program Files (x86)\\CheckPoint\\Endpoint Security\\EFR\\host\\cpsechost.exe\" service"
        )
      ) or
      winlog.event_data.ServiceName : (
         "mssecsvc2.0", "WCESERVICE*", "WCE SERVICE*", "pwdump*", "gsecdump*", "cachedump*"
      )
    )
  ) or
  (
    event.code : "7045" and
    (
      (
        winlog.event_data.ImagePath : (
          "*COMSPEC*", "*\\127.0.0.1*", "*Admin$*", "*powershell*", "*rundll32*", "*cmd.exe*",
          "*echo*", "*.bat*", "*.cmd*", "*certutil*", "*vssadmin*", "*certmgr*", "*bitsadmin*",
          "*\\Users\\*", "*\\Windows\\Tasks\\*", "*\\PerfLogs\\*", "*\\Windows\\Debug\\*",
          "*regsvr32*", "*msbuild*", "*winexesvc.exe*", "*DumpSvc.exe*", "*pwsh.exe*", "*PAExec*"
        ) and
        not winlog.event_data.ImagePath : (
              "%SystemRoot%\\PSEXESVC.exe", "%SystemRoot%\\\\RemComSvc.exe",
              "%SystemRoot%\\pbpsdeploy.exe", "%SystemRoot%\\system32\\RemComSvc.exe",
              "\"C:\\Program Files\\Common Files\\Zoom\\Support\\CptService.exe*",
              "\"C:\\Program Files\\Common Files\\ZoomVDIPluginManagement\\Support\\CptService.exe*",
              "\"C:\\Program Files (x86)\\CheckPoint\\Endpoint Security\\EFR\\host\\cpsechost.exe\" service"
        )
      ) or
      winlog.event_data.ServiceName : (
         "mssecsvc2.0", "WCESERVICE*", "WCE SERVICE*", "pwdump*", "gsecdump*", "cachedump*"
      )
    )
  )
)

// Title: persistence_services_registry.toml
// Source: detection-rules::rules/windows/persistence_services_registry.toml
// Section: EQL Rule
// Rule Name: Unusual Persistence via Services Registry
// Author: Elastic
// Description:
// Identifies processes modifying the services registry key directly, instead of through the expected Windows APIs. This
// could be an indication of an adversary attempting to stealthily persist through abnormal service creation or
// modification of an existing service.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel
// Language: eql
// UUID: 403ef0d3-8259-40c9-a5b6-d48354712e49
// Type: eql

registry where host.os.type == "windows" and event.type == "change" and
  registry.data.strings != null and registry.value : ("ServiceDLL", "ImagePath") and
  registry.path : (
      "HKLM\\SYSTEM\\ControlSet*\\Services\\*\\ServiceDLL",
      "HKLM\\SYSTEM\\ControlSet*\\Services\\*\\ImagePath",
      "\\REGISTRY\\MACHINE\\SYSTEM\\ControlSet*\\Services\\*\\ServiceDLL",
      "\\REGISTRY\\MACHINE\\SYSTEM\\ControlSet*\\Services\\*\\ImagePath",
      "MACHINE\\SYSTEM\\ControlSet*\\Services\\*\\ServiceDLL",
      "MACHINE\\SYSTEM\\ControlSet*\\Services\\*\\ImagePath"
  ) and not registry.data.strings : (
      "?:\\windows\\system32\\Drivers\\*.sys",
      "\\SystemRoot\\System32\\drivers\\*.sys",
      "\\??\\?:\\Windows\\system32\\Drivers\\*.SYS",
      "\\??\\?:\\Windows\\syswow64\\*.sys",
      "system32\\DRIVERS\\USBSTOR", 
      "system32\\drivers\\*.sys", 
      "C:\\WindowsAzure\\GuestAgent*.exe", 
      "\"C:\\Program Files\\Common Files\\McAfee\\*", 
      "C:\\Program Files (x86)\\VERITAS\\VxPBX\\bin\\pbx_exchange.exe", 
      "\"C:\\Program Files (x86)\\VERITAS\\VxPBX\\bin\\pbx_exchange.exe\"",
      "\"C:\\ProgramData\\McAfee\\Agent\\Current\\*") and
  not (process.name : "procexp??.exe" and registry.data.strings : "?:\\*\\procexp*.sys") and
  not process.executable : (
      "?:\\Program Files\\*.exe",
      "?:\\Program Files (x86)\\*.exe",
      "?:\\Windows\\System32\\svchost.exe",
      "?:\\Windows\\winsxs\\*\\TiWorker.exe",
      "?:\\Windows\\System32\\drvinst.exe",
      "?:\\Windows\\System32\\services.exe",
      "?:\\Windows\\System32\\msiexec.exe",
      "?:\\Windows\\System32\\regsvr32.exe",
      "?:\\Windows\\System32\\WaaSMedicAgent.exe", 
      "?:\\Windows\\UUS\\amd64\\WaaSMedicAgent.exe"
  )

// Title: persistence_startup_folder_file_written_by_suspicious_process.toml
// Source: detection-rules::rules/windows/persistence_startup_folder_file_written_by_suspicious_process.toml
// Section: EQL Rule
// Rule Name: Startup Persistence by a Suspicious Process
// Author: Elastic
// Description:
// Identifies files written to or modified in the startup folder by commonly abused processes. Adversaries may use this
// technique to maintain persistence.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel
// Language: eql
// UUID: 440e2db4-bc7f-4c96-a068-65b78da59bde
// Type: eql

file where host.os.type == "windows" and event.type != "deletion" and
  user.domain != "NT AUTHORITY" and
  file.path : ("C:\\Users\\*\\AppData\\Roaming\\Microsoft\\Windows\\Start Menu\\Programs\\Startup\\*",
               "C:\\ProgramData\\Microsoft\\Windows\\Start Menu\\Programs\\StartUp\\*") and
  process.name : ("cmd.exe",
                  "powershell.exe",
                  "wmic.exe",
                  "mshta.exe",
                  "pwsh.exe",
                  "cscript.exe",
                  "wscript.exe",
                  "regsvr32.exe",
                  "RegAsm.exe",
                  "rundll32.exe",
                  "EQNEDT32.EXE",
                  "WINWORD.EXE",
                  "EXCEL.EXE",
                  "POWERPNT.EXE",
                  "MSPUB.EXE",
                  "MSACCESS.EXE",
                  "iexplore.exe",
                  "InstallUtil.exe")

// Title: persistence_startup_folder_file_written_by_unsigned_process.toml
// Source: detection-rules::rules/windows/persistence_startup_folder_file_written_by_unsigned_process.toml
// Section: EQL Rule
// Rule Name: Startup Folder Persistence via Unsigned Process
// Author: Elastic
// Description:
// Identifies files written or modified in the startup folder by unsigned processes. Adversaries may abuse this technique
// to maintain persistence in an environment.
// Integration: endpoint
// Language: eql
// UUID: 2fba96c0-ade5-4bce-b92f-a5df2509da3f
// Type: eql

sequence by host.id, process.entity_id with maxspan=5s
  [process where host.os.type == "windows" and event.type == "start" and process.code_signature.trusted == false and
  /* suspicious paths can be added here  */
   process.executable : ("C:\\Users\\*.exe",
                         "C:\\ProgramData\\*.exe",
                         "C:\\Windows\\Temp\\*.exe",
                         "C:\\Windows\\Tasks\\*.exe",
                         "C:\\Intel\\*.exe",
                         "C:\\PerfLogs\\*.exe")
   ]
   [file where host.os.type == "windows" and event.type != "deletion" and user.domain != "NT AUTHORITY" and
    file.path : ("C:\\Users\\*\\AppData\\Roaming\\Microsoft\\Windows\\Start Menu\\Programs\\Startup\\*",
                 "C:\\ProgramData\\Microsoft\\Windows\\Start Menu\\Programs\\StartUp\\*")
   ]

// Title: persistence_startup_folder_scripts.toml
// Source: detection-rules::rules/windows/persistence_startup_folder_scripts.toml
// Section: EQL Rule
// Rule Name: Persistent Scripts in the Startup Directory
// Author: Elastic
// Description:
// Identifies script engines creating files in the Startup folder, or the creation of script files in the Startup folder.
// Adversaries may abuse this technique to maintain persistence in an environment.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel
// Language: eql
// UUID: f7c4dc5a-a58d-491d-9f14-9b66507121c0
// Type: eql

file where host.os.type == "windows" and event.type != "deletion" and

  /* Call attention to file extensions that may be used for malicious purposes */
  /* Optionally, Windows scripting engine processes targeting shortcut files */
  (
    file.extension : ("vbs", "vbe", "wsh", "wsf", "js", "jse", "sct", "hta", "ps1", "bat", "cmd") or
    process.name : ("wscript.exe", "cscript.exe")
  ) and not (startsWith(user.domain, "NT") or endsWith(user.domain, "NT"))

  /* Identify files created or changed in the startup folder */
  and file.path : (
        "?:\\Users\\*\\AppData\\Roaming\\Microsoft\\Windows\\Start Menu\\Programs\\Startup\\*",
        "?:\\ProgramData\\Microsoft\\Windows\\Start Menu\\Programs\\StartUp\\*")

// Title: persistence_suspicious_com_hijack_registry.toml
// Source: detection-rules::rules/windows/persistence_suspicious_com_hijack_registry.toml
// Section: EQL Rule
// Rule Name: Component Object Model Hijacking
// Author: Elastic
// Description:
// Identifies Component Object Model (COM) hijacking via registry modification. Adversaries may establish persistence by
// executing malicious content triggered by hijacked references to COM objects.
// Integration: endpoint
// Language: eql
// UUID: 16a52c14-7883-47af-8745-9357803f0d4c
// Type: eql

registry where host.os.type == "windows" and event.type == "change" and
  /* not necessary but good for filtering privileged installations */
  user.domain != "NT AUTHORITY" and process.executable != null and 
  (
    (
      registry.path : "HK*\\InprocServer32\\" and
      registry.data.strings: ("scrobj.dll", "?:\\*\\scrobj.dll") and
      not registry.path : "*\\{06290BD*-48AA-11D2-8432-006008C3FBFC}\\*"
    ) or

    (
      registry.path : "HKLM\\*\\InProcServer32\\*" and
        registry.data.strings : ("*\\Users\\*", "*\\ProgramData\\*")
    ) or

    /* in general COM Registry changes on Users Hive is less noisy and worth alerting */
    (
      registry.path : (
        "HKEY_USERS\\*\\InprocServer32\\",
        "HKEY_USERS\\*\\LocalServer32\\",
        "HKEY_USERS\\*\\DelegateExecute",
        "HKEY_USERS\\*\\TreatAs\\",
        "HKEY_USERS\\*\\ScriptletURL*", 
        "HKEY_USERS\\*\\TypeLib*\\Win*"
      ) and
      not registry.data.strings : (
            /* COM related to Windows Spotlight feature */
            "{4813071a-41ad-44a2-9835-886d2f63ca30}",

            /* AppX/MSIX DelegateExecute handlers: execute, protocol, file */
            "{A56A841F-E974-45C1-8001-7E3F8A085917}",
            "{4ED3A719-CEA8-4BD9-910D-E252F997AFC2}",
            "{BFEC0C93-0B7D-4F2C-B09C-AFFFC4BDAE78}"
      )
    )
  ) and 

  not (
    process.code_signature.trusted == true and
    process.code_signature.subject_name in (
        "Island Technology Inc.", "Google LLC", "Grammarly, Inc.", "Dropbox, Inc", "REFINITIV US LLC", "HP Inc.", "Adobe Inc.",
        "Citrix Systems, Inc.", "Veeam Software Group GmbH", "Zhuhai Kingsoft Office Software Co., Ltd.", "Oracle America, Inc.",
        "Brave Software, Inc.", "DeepL SE", "Opera Norway AS", "Thomas Braun", "Slack Technologies, LLC", "Spotify AB",
        "Vivaldi Technologies AS"
    )
  ) and 

  /* excludes trusted applications registering their own COM components */
  not (
    process.code_signature.trusted == true and
    (
      (
        process.name : "OneDrive.Sync.Service.exe" and
        process.code_signature.subject_name == "Microsoft Corporation" and
        registry.data.strings : (
          "*\\Microsoft\\OneDrive\\*\\OneDrive.Sync.Service.exe*",
          "*\\Microsoft\\OneDrive\\*\\OneDrive.Sync.Service.dll*"
        )
      ) or
      (
        process.executable : "?:\\Users\\*\\AppData\\Local\\Kingsoft\\WPS Office\\*\\office6\\ksomisc.exe" and
        process.code_signature.subject_name == "WPS SOFTWARE PTE. LTD." and
        registry.data.strings : "*\\Kingsoft\\WPS Office\\*"
      ) or
      (
        process.name : "claude.exe" and
        process.code_signature.subject_name == "Anthropic, PBC" and
        registry.data.strings : (
          "*\\Users\\*\\AppData\\Local\\AnthropicClaude\\app-*\\claude.exe*",
          "*\\ProgramData\\*\\AnthropicClaude\\app-*\\claude.exe*"
        )
      )
    )
  ) and

  /* excludes Microsoft signed noisy processes */
  not
  (
    process.name : (
      "OneDrive.exe", "OneDriveSetup.exe", "FileSyncConfig.exe", "Teams.exe", "MicrosoftEdgeUpdate.exe", "msrdcw.exe",
      "MicrosoftEdgeUpdateComRegisterShell64.exe", "setup.exe", "PowerToys.PowerLauncher.exe"
    ) and
    process.code_signature.trusted == true and process.code_signature.subject_name in ("Microsoft Windows", "Microsoft Corporation")
  ) and

  not process.executable : (
        "?:\\$WINDOWS.~BT\\Sources\\SetupHost.exe",
        "?:\\Program Files (x86)\\*.exe",
        "?:\\Program Files\\*.exe",
        "?:\\ProgramData\\4Team\\4Team-Updater\\4Team-Updater-Helper.exe",
        "?:\\ProgramData\\Lenovo\\Udc\\Hosts\\x64\\MessagingPlugin.exe",
        "?:\\ProgramData\\Microsoft\\Windows Defender\\Platform\\*\\MsMpEng.exe",
        "?:\\Users\\*\\AppData\\Local\\Wondershare\\Wondershare NativePush\\WsToastNotification.exe",
        "?:\\Windows\\System32\\DriverStore\\FileRepository\\*.exe",
        "?:\\Windows\\System32\\FMToastNotification.exe",
        "?:\\Windows\\System32\\msiexec.exe",
        "?:\\Windows\\System32\\svchost.exe",
        "?:\\Windows\\SysWOW64\\regsvr32.exe",
        "?:\\Windows\\System32\\regsvr32.exe",
        "\\Device\\Mup\\*\\Kufer\\KuferSQL\\BasysSQL.exe"
  )

// Title: persistence_suspicious_image_load_scheduled_task_ms_office.toml
// Source: detection-rules::rules/windows/persistence_suspicious_image_load_scheduled_task_ms_office.toml
// Section: EQL Rule
// Rule Name: Suspicious Image Load (taskschd.dll) from MS Office
// Author: Elastic
// Description:
// Identifies a suspicious image load (taskschd.dll) from Microsoft Office processes. This behavior may indicate
// adversarial activity where a scheduled task is configured via Windows Component Object Model (COM). This technique can
// be used to configure persistence and evade monitoring by avoiding the usage of the traditional Windows binary
// (schtasks.exe) used to manage scheduled tasks.
// Integration: endpoint, windows
// Language: eql
// UUID: baa5d22c-5e1c-4f33-bfc9-efa73bb53022
// Type: eql

any where host.os.type == "windows" and
 (event.category : ("library", "driver") or (event.category == "process" and event.action : "Image loaded*")) and
  process.name : ("WINWORD.EXE", "EXCEL.EXE", "POWERPNT.EXE", "MSPUB.EXE", "MSACCESS.EXE") and
  (?dll.name : "taskschd.dll" or file.name : "taskschd.dll")

// Title: persistence_suspicious_service_created_registry.toml
// Source: detection-rules::rules/windows/persistence_suspicious_service_created_registry.toml
// Section: EQL Rule
// Rule Name: Suspicious ImagePath Service Creation
// Author: Elastic
// Description:
// Identifies the creation of a suspicious ImagePath value. This could be an indication of an adversary attempting to
// stealthily persist or escalate privileges through abnormal service creation.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 36a8e048-d888-4f61-a8b9-0f9e2e40f317
// Type: eql

registry where host.os.type == "windows" and event.type == "change" and
  registry.value : "ImagePath" and
  registry.path : "*\\SYSTEM\\ControlSet*\\Services\\*\\ImagePath" and
  /* add suspicious registry ImagePath values here */
  registry.data.strings : ("%COMSPEC%*", "*\\.\\pipe\\*")

// Title: persistence_suspicious_user_mandatory_profile_file.toml
// Source: detection-rules::rules/windows/persistence_suspicious_user_mandatory_profile_file.toml
// Section: EQL Rule
// Rule Name: Potential Persistence via Mandatory User Profile
// Author: Elastic
// Description:
// Detects the creation or modification of a mandatory user profile hive (NTUSER.MAN) by an unusual process.
// Adversaries may abuse Windows mandatory profiles by dropping a malicious NTUSER.MAN file containing
// pre-populated persistence-related registry keys. On the next user logon, Windows loads the registry hive
// from NTUSER.MAN, causing embedded persistence mechanisms to activate without directly modifying the live
// registry. This technique can evade traditional registry-based monitoring and indicate a stealthy
// persistence attempt.
// Integration: endpoint
// Language: eql
// UUID: 0e42f920-047d-4568-b961-2a50db6c4713
// Type: eql

file where host.os.type == "windows" and
 event.type in ("creation", "change") and user.id != "S-1-5-18" and
 file.name : "NTUSER.MAN" and file.path : "?:\\Users\\*.MAN"

// Title: persistence_sysmon_wmi_event_subscription.toml
// Source: detection-rules::rules/windows/persistence_sysmon_wmi_event_subscription.toml
// Section: EQL Rule
// Rule Name: Suspicious WMI Event Subscription Created
// Author: Elastic
// Description:
// Detects the creation of a WMI Event Subscription. Attackers can abuse this mechanism for persistence or to elevate to
// SYSTEM privileges.
// Integration: windows, endpoint
// Language: eql
// UUID: e72f87d0-a70e-4f8d-8443-a6407bc34643
// Type: eql

any where host.os.type == "windows" and
 (
   (data_stream.dataset == "windows.sysmon_operational" and event.code == "21" and
    ?winlog.event_data.Operation : "Created" and ?winlog.event_data.Consumer : ("*subscription:CommandLineEventConsumer*", "*subscription:ActiveScriptEventConsumer*")) or

   (data_stream.dataset == "endpoint.events.api" and event.provider == "Microsoft-Windows-WMI-Activity" and ?process.Ext.api.name == "IWbemServices::PutInstance" and
    ?process.Ext.api.parameters.consumer_type in ("ActiveScriptEventConsumer", "CommandLineEventConsumer"))
 )

// Title: persistence_system_shells_via_services.toml
// Source: detection-rules::rules/windows/persistence_system_shells_via_services.toml
// Section: EQL Rule
// Rule Name: System Shells via Services
// Author: Elastic
// Description:
// Windows services typically run as SYSTEM and can be used as a privilege escalation opportunity. Malware or penetration
// testers may run a shell as a service to gain SYSTEM permissions.
// Integration: endpoint, windows, system, sentinel_one_cloud_funnel, m365_defender, crowdstrike
// Language: eql
// UUID: 0022d47d-39c7-4f69-a232-4fe9dc7a3acd
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.parent.name : "services.exe" and
  process.name : ("cmd.exe", "powershell.exe", "pwsh.exe", "powershell_ise.exe") and

  /* Third party FP's */
  not process.args : "NVDisplay.ContainerLocalSystem"

// Title: persistence_temp_scheduled_task.toml
// Source: detection-rules::rules/windows/persistence_temp_scheduled_task.toml
// Section: EQL Rule
// Rule Name: Temporarily Scheduled Task Creation
// Author: Elastic
// Description:
// Indicates the creation and deletion of a scheduled task within a short time interval. Adversaries can use these to proxy
// malicious execution via the schedule service and perform clean up.
// Integration: system, windows
// Language: eql
// UUID: 81ff45f8-f8c2-4e28-992e-5a0e8d98e0fe
// Type: eql

sequence by winlog.computer_name, winlog.event_data.TaskName with maxspan=5m
   [iam where host.os.type == "windows" and event.action == "scheduled-task-created" and not user.name : "*$"]
   [iam where host.os.type == "windows" and event.action == "scheduled-task-deleted" and not user.name : "*$"]

// Title: persistence_time_provider_mod.toml
// Source: detection-rules::rules/windows/persistence_time_provider_mod.toml
// Section: EQL Rule
// Rule Name: Potential Persistence via Time Provider Modification
// Author: Elastic
// Description:
// Identifies modification of the Time Provider. Adversaries may establish persistence by registering and enabling a
// malicious DLL as a time provider. Windows uses the time provider architecture to obtain accurate time stamps from other
// network devices or clients in the network. Time providers are implemented in the form of a DLL file which resides in the
// System32 folder. The service W32Time initiates during the startup of Windows and loads w32time.dll.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 14ed1aa9-ebfd-4cf9-a463-0ac59ec55204
// Type: eql

registry where host.os.type == "windows" and event.type == "change" and
  registry.path: "*\\SYSTEM\\*ControlSet*\\Services\\W32Time\\TimeProviders\\*" and
  registry.data.strings:"*.dll" and
  not
  (
    process.executable : ("?:\\Windows\\System32\\msiexec.exe", "\\Device\\HarddiskVolume*\\Windows\\System32\\msiexec.exe") and
    registry.data.strings : "?:\\Program Files\\VMware\\VMware Tools\\vmwTimeProvider\\vmwTimeProvider.dll"
  ) and
  not registry.data.strings : "C:\\Windows\\SYSTEM32\\w32time.DLL"

// Title: persistence_user_account_added_to_privileged_group_ad.toml
// Source: detection-rules::rules/windows/persistence_user_account_added_to_privileged_group_ad.toml
// Section: EQL Rule
// Rule Name: User Added to Privileged Group in Active Directory
// Author: Elastic, Skoetting
// Description:
// Identifies a user being added to a privileged group in Active Directory. Privileged accounts and groups in Active
// Directory are those to which powerful rights, privileges, and permissions are granted that allow them to perform nearly
// any action in Active Directory and on domain-joined systems.
// Integration: system, windows
// Language: eql
// UUID: 5cd8e1f7-0050-4afc-b2df-904e40b2f5ae
// Type: eql

iam where host.os.type == "windows" and event.action == "added-member-to-group" and
(
    group.id : "S-1-5-21*" and
    (
        group.name : (
            "Admin*",
            "Domain Admins",
            "Enterprise Admins",
            "Backup Admins",
            "Schema Admins",
            "DnsAdmins",
            "Exchange Organization Administrators",
            "Print Operators",
            "Server Operators",
            "Account Operators"
        )
    ) or
    (
        group.id : (
            "S-1-5-21-*-544",
            "S-1-5-21-*-512",
            "S-1-5-21-*-519",
            "S-1-5-21-*-551",
            "S-1-5-21-*-518",
            "S-1-5-21-*-1101",
            "S-1-5-21-*-1102",
            "S-1-5-21-*-550",
            "S-1-5-21-*-549",
            "S-1-5-21-*-548"
        )
    )
)

// Title: persistence_user_account_creation.toml
// Source: detection-rules::rules/windows/persistence_user_account_creation.toml
// Section: EQL Rule
// Rule Name: User Account Creation
// Author: Elastic
// Description:
// Identifies attempts to create new users. This is sometimes done by attackers to increase access or establish persistence
// on a system or domain.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 1aa9181a-492b-4c01-8b16-fa0735786b2b
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  (process.name : ("net.exe", "net1.exe") and not process.parent.name : "net.exe") and
  (process.args : "user" and process.args : ("/ad", "/add"))

// Title: persistence_via_application_shimming.toml
// Source: detection-rules::rules/windows/persistence_via_application_shimming.toml
// Section: EQL Rule
// Rule Name: Potential Application Shimming via Sdbinst
// Author: Elastic
// Description:
// The Application Shim was created to allow for backward compatibility of software as the operating system codebase
// changes over time. This Windows functionality has been abused by attackers to stealthily gain persistence and arbitrary
// code execution in legitimate Windows processes.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: fd4a992d-6130-4802-9ff8-829b89ae801f
// Type: eql

process where host.os.type == "windows" and event.type == "start" and process.name : "sdbinst.exe" and
  process.args : "?*" and
  not (process.args : "-m" and process.args : "-bg") and
  not process.args : (
    "-mm",
    "?:\\Program Files\\WindowsApps\\Microsoft.ApplicationCompatibilityEnhancements_*\\sdb\\sysMergeInboxStoreApp.sdb",
    "\"?:\\Program Files\\WindowsApps\\Microsoft.ApplicationCompatibilityEnhancements_*\\sdb\\sysMergeInboxStoreApp.sdb\"",
    "?:\\Program Files\\WindowsApps\\Microsoft.ApplicationCompatibilityEnhancements_*\\sdb\\msiMergeInboxStoreApp.sdb",
    "\"?:\\Program Files\\WindowsApps\\Microsoft.ApplicationCompatibilityEnhancements_*\\sdb\\msiMergeInboxStoreApp.sdb\"",
    "?:\\Program Files (x86)\\Citrix\\ICA Client\\CitrixWorkspaceLegacySWDA.sdb",
    "Citrix Workspace",
    "C:\\Program Files\\IIS Express\\iisexpressshim.sdb",
    "C:\\Program Files (x86)\\IIS Express\\iisexpressshim.sdb"
  )

// Title: persistence_via_bits_job_notify_command.toml
// Source: detection-rules::rules/windows/persistence_via_bits_job_notify_command.toml
// Section: EQL Rule
// Rule Name: Persistence via BITS Job Notify Cmdline
// Author: Elastic
// Description:
// An adversary can use the Background Intelligent Transfer Service (BITS) SetNotifyCmdLine method to execute a program
// that runs after a job finishes transferring data or after a job enters a specified state in order to persist on a
// system.
// Integration: endpoint, windows, sentinel_one_cloud_funnel, m365_defender
// Language: eql
// UUID: c3b915e0-22f3-4bf7-991d-b643513c722f
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.parent.name : "svchost.exe" and process.parent.args : "BITS" and
  not process.executable :
              ("?:\\Windows\\System32\\WerFaultSecure.exe",
               "?:\\Windows\\System32\\WerFault.exe",
               "?:\\Windows\\System32\\wermgr.exe",
               "?:\\WINDOWS\\system32\\directxdatabaseupdater.exe")

// Title: persistence_via_hidden_run_key_valuename.toml
// Source: detection-rules::rules/windows/persistence_via_hidden_run_key_valuename.toml
// Section: EQL Rule
// Rule Name: Persistence via Hidden Run Key Detected
// Author: Elastic
// Description:
// Identifies a persistence mechanism that utilizes the NtSetValueKey native API to create a hidden (null terminated)
// registry key. An adversary may use this method to hide from system utilities such as the Registry Editor (regedit).
// Integration: endpoint, windows, crowdstrike, sentinel_one_cloud_funnel, m365_defender
// Language: eql
// UUID: a9b05c3b-b304-4bf9-970d-acdfaef2944c
// Type: eql

registry where host.os.type == "windows" and event.type == "change" and length(registry.data.strings) > 0 and

  /* Registry Path ends with backslash */
  registry.path : "*\\Run\\" and
  registry.path : (
    "*\\Software\\Microsoft\\Windows\\CurrentVersion\\Run\\",
    "*\\Software\\WOW6432Node\\Microsoft\\Windows\\CurrentVersion\\Run\\",
    "*\\Software\\Microsoft\\Windows\\CurrentVersion\\Policies\\Explorer\\Run\\"
  )

// Title: persistence_via_lsa_security_support_provider_registry.toml
// Source: detection-rules::rules/windows/persistence_via_lsa_security_support_provider_registry.toml
// Section: EQL Rule
// Rule Name: Installation of Security Support Provider
// Author: Elastic
// Description:
// Identifies registry modifications related to the Windows Security Support Provider (SSP) configuration. Adversaries may
// abuse this to establish persistence in an environment.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: e86da94d-e54b-4fb5-b96c-cecff87e8787
// Type: eql

registry where host.os.type == "windows" and event.type == "change" and
  registry.value : "Security Packages" and
  registry.path : (
      "*\\SYSTEM\\*ControlSet*\\Control\\Lsa\\Security Packages",
      "*\\SYSTEM\\*ControlSet*\\Control\\Lsa\\OSConfig\\Security Packages"
  ) and
  not process.executable : (
        "C:\\Windows\\System32\\msiexec.exe",
        "C:\\Windows\\SysWOW64\\msiexec.exe",
        /* Crowdstrike specific exclusion as it uses NT Object paths */
        "\\Device\\HarddiskVolume*\\Windows\\System32\\msiexec.exe",
        "\\Device\\HarddiskVolume*\\Windows\\SysWOW64\\msiexec.exe"
  )

// Title: persistence_via_telemetrycontroller_scheduledtask_hijack.toml
