                      "DeviceCensus.exe",
                      "CompatTelRunner.exe",
                      "DismHost.exe",
                      "rundll32.exe",
                      "powershell.exe")

// Title: persistence_via_update_orchestrator_service_hijack.toml
// Source: detection-rules::rules/windows/persistence_via_update_orchestrator_service_hijack.toml
// Section: EQL Rule
