// Title: persistence_via_windows_management_instrumentation_event_subscription.toml
// Source: detection-rules::rules/windows/persistence_via_windows_management_instrumentation_event_subscription.toml
// Section: EQL Rule
// Rule Name: Persistence via WMI Event Subscription
// Author: Elastic
// Description:
// An adversary can use Windows Management Instrumentation (WMI) to install event filters, providers, consumers, and
// bindings that execute code when a defined event occurs. Adversaries may use the capabilities of WMI to subscribe to an
// event and execute arbitrary code when that event occurs, providing persistence on a system.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 9b6813a1-daf1-457e-b0e6-0bb4e55b8a4c
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  (process.name : "wmic.exe" or ?process.pe.original_file_name == "wmic.exe") and
  process.args : "create" and
  process.args : ("ActiveScriptEventConsumer", "CommandLineEventConsumer")

// Title: persistence_web_shell_aspx_write.toml
// Source: detection-rules::rules/windows/persistence_web_shell_aspx_write.toml
// Section: EQL Rule
// Rule Name: Potential IIS Web Shell File Creation
// Author: Elastic
// Description:
// Identifies the creation of ASPX/ASHX/ASMX files in specific directories that are commonly targeted by attackers to deploy web shells.
// Integration: endpoint, windows, sentinel_one_cloud_funnel, m365_defender, crowdstrike
// Language: eql
// UUID: 32144184-7bfa-4541-9c3f-b65f16d24df9
// Type: eql

file where host.os.type == "windows" and event.type != "deletion" and file.extension : ("aspx", "ashx", "asmx") and
 process.name : ("w3wp.exe", "MSExchangeMailboxReplication.exe", "EdgeTransport.exe", "Microsoft.Exchange.*.exe", "UMWorkerProcess.exe", "umservice.exe", "cmd.exe", "powershell.exe", "pwsh.exe", "certutil.exe", "xcopy.exe") and 
  (
   (file.path : ("?:\\Program Files\\Common Files\\microsoft shared\\Web Server Extensions\\*\\TEMPLATE\\LAYOUTS\\*",
                 "?:\\inetpub\\wwwroot\\aspnet_client\\system_web\\*", 
                 "?:\\Program Files\\Microsoft\\Exchange Server\\V*\\FrontEnd\\HttpProxy\\owa\\auth\\*", 
                 "?:\\Program Files\\Microsoft\\Exchange Server\\V*\\FrontEnd\\HttpProxy\\ecp\\auth\\*") and 
    /* not sub-dirs */
    not file.path : ("?:\\inetpub\\wwwroot\\aspnet_client\\system_web\\*\\*", 
                     "?:\\Program Files\\Microsoft\\Exchange Server\\V*\\FrontEnd\\HttpProxy\\*\\auth\\*\\*", 
                     "?:\\Program Files\\Common Files\\microsoft shared\\Web Server Extensions\\*\\TEMPLATE\\LAYOUTS\\*\\*")) or 

    /* not sub-dirs */
   (file.path : "?:\\inetpub\\wwwroot\\aspnet_client\\*" and not file.path : "?:\\inetpub\\wwwroot\\aspnet_client\\*\\*")
  )

// Title: persistence_werfault_reflectdebugger.toml
// Source: detection-rules::rules/windows/persistence_werfault_reflectdebugger.toml
// Section: EQL Rule
// Rule Name: Werfault ReflectDebugger Persistence
