  */

// Title: privilege_escalation_account_takeover_mixed_logon_types.toml
// Source: detection-rules::rules/windows/privilege_escalation_account_takeover_mixed_logon_types.toml
// Section: EQL Rule
// Rule Name: Potential Account Takeover - Mixed Logon Types
// Author: Elastic
// Description:
// Identifies a user account (often a service account) that normally logs in with high volume using one logon type
// suddenly showing successful logons using a different logon type with low count. This pattern may indicate account
// takeover or use of stolen credentials from a new context (e.g. interactive or network logon where only batch/service
// was expected).
// Integration: system, windows
// Language: esql
// UUID: b2c3d4e5-f6a7-5b6c-9d0e-1f2a3b4c5d6e
// Type: esql

from logs-system.security*, logs-windows.forwarded*, winlogbeat-* metadata _id, _version, _index
| WHERE event.category == "authentication" and event.action == "logged-in" and winlog.event_id == "4624" and
        event.outcome == "success" and not user.id in ("S-1-5-18", "S-1-5-19", "S-1-5-20") and
        to_lower(user.name) != "administrator"
| STATS logon_count = COUNT(*), host_names = VALUES(host.name) by user.name, user.id, winlog.logon.type
| STATS
    Esql.max_logon = MAX(logon_count),
    Esql.min_logon = MIN(logon_count),
    Esql.unique_host_count = COUNT_DISTINCT(host_names),
    Esql.host_name_values = VALUES(host_names),
    Esql.logon_type_values = VALUES(winlog.logon.type),
    Esql.count_distinct_logon_types = COUNT_DISTINCT(winlog.logon.type) by user.name, user.id

// high count of logons is often associated with service account tied to a specific service, if observed in use with a different logon type it's suspicious
| WHERE Esql.count_distinct_logon_types >= 2 and Esql.max_logon >= 1000 and (Esql.min_logon >= 1 and Esql.min_logon <= 10) and Esql.unique_host_count >= 2
| EVAL winlog.logon.type = MV_FIRST(Esql.logon_type_values), host.name = MV_FIRST(Esql.host_name_values)
| KEEP user.name, user.id, host.name, winlog.logon.type, Esql.*

// Title: privilege_escalation_create_process_as_different_user.toml
// Source: detection-rules::rules/windows/privilege_escalation_create_process_as_different_user.toml
// Section: EQL Rule
// Rule Name: Process Creation via Secondary Logon
// Author: Elastic
// Description:
// Identifies process creation with alternate credentials. Adversaries may create a new process with a different token to
// escalate privileges and bypass access controls.
// Integration: system, windows
// Language: eql
// UUID: 42eeee3d-947f-46d3-a14d-7036b962c266
// Type: eql

sequence by winlog.computer_name with maxspan=1m

[authentication where host.os.type == "windows" and event.action:"logged-in" and
 event.outcome == "success" and user.id : ("S-1-5-21-*", "S-1-12-1-*") and

 /* seclogon service */
 process.name == "svchost.exe" and
 winlog.event_data.LogonProcessName : "seclogo*" and source.ip == "::1" ] by winlog.event_data.TargetLogonId

[process where host.os.type == "windows" and event.type == "start"] by winlog.event_data.TargetLogonId

// Title: privilege_escalation_create_process_with_token_unpriv.toml
// Source: detection-rules::rules/windows/privilege_escalation_create_process_with_token_unpriv.toml
// Section: EQL Rule
// Rule Name: Process Created with a Duplicated Token
// Author: Elastic
// Description:
// Identifies the creation of a process impersonating the token of another user logon session. Adversaries may create a new
// process with a different token to escalate privileges and bypass access controls.
// Integration: endpoint
// Language: eql
// UUID: 1b0b4818-5655-409b-9c73-341cac4bb73f
// Type: eql

/* This rule is only compatible with Elastic Endpoint 8.4+ */

process where host.os.type == "windows" and event.action == "start" and

 user.id : ("S-1-5-21-*", "S-1-12-1-*") and

 (process.Ext.effective_parent.executable regex~ """[C-Z]:\\Windows\\(System32|SysWOW64)\\[a-zA-Z0-9\-\_\.]+\.exe""" or
  process.Ext.effective_parent.executable : "?:\\Windows\\explorer.exe") and

 (
  process.name : ("powershell.exe", "cmd.exe", "rundll32.exe", "notepad.exe", "net.exe", "ntdsutil.exe",
                  "tasklist.exe", "reg.exe", "certutil.exe", "bitsadmin.exe", "msbuild.exe", "esentutl.exe") or

  ((process.Ext.relative_file_creation_time <= 900 or process.Ext.relative_file_name_modify_time <= 900) and
   not process.code_signature.status : ("trusted", "errorExpired", "errorCode_endpoint*") and
   not process.executable : ("?:\\Program Files\\*", "?:\\Program Files (x86)\\*"))
 ) and
 not (process.name : "rundll32.exe" and
      process.command_line : ("*davclnt.dll,DavSetCookie*", "*?:\\Program Files*",
                              "*\\Windows\\System32\\winethc.dll*", "*\\Windows\\SYSTEM32\\EDGEHTML.dll*",
                              "*shell32.dll,SHCreateLocalServerRunDll*")) and
 not startswith~(process.Ext.effective_parent.name, process.parent.name) and
 not (process.name : "powershell.exe" and process.parent.name : "wmiprvse.exe" and process.Ext.effective_parent.executable : "?:\\Windows\\System32\\wsmprovhost.exe") and
 not (process.Ext.effective_parent.executable : "?:\\Windows\\System32\\RuntimeBroker.exe" and process.parent.executable : "?:\\Windows\\System32\\sihost.exe") and
 not (process.Ext.effective_parent.executable : "?:\\Windows\\System32\\sethc.exe" and process.parent.executable : "?:\\Windows\\System32\\svchost.exe") and
 not (process.Ext.effective_parent.executable : "?:\\Windows\\explorer.exe" and
      process.parent.executable : ("?:\\Windows\\System32\\svchost.exe", "?:\\Windows\\System32\\msiexec.exe", "?:\\Windows\\twain_32\\*.exe"))

// Title: privilege_escalation_disable_uac_registry.toml
// Source: detection-rules::rules/windows/privilege_escalation_disable_uac_registry.toml
// Section: EQL Rule
// Rule Name: Disabling User Account Control via Registry Modification
// Author: Elastic
// Description:
// User Account Control (UAC) can help mitigate the impact of malware on Windows hosts. With UAC, apps and tasks always run
// in the security context of a non-administrator account, unless an administrator specifically authorizes
// administrator-level access to the system. This rule identifies registry value changes to bypass User Access Control
// (UAC) protection.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: d31f183a-e5b1-451b-8534-ba62bca0b404
// Type: eql

registry where host.os.type == "windows" and event.type == "change" and
  registry.value : ("EnableLUA", "ConsentPromptBehaviorAdmin", "PromptOnSecureDesktop") and
  registry.data.strings : ("0", "0x00000000")

  /*
    Full registry key path omitted due to data source variations:
    HKLM\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System\\EnableLUA
    HKLM\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System\\ConsentPromptBehaviorAdmin
    HKLM\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System\\PromptOnSecureDesktop
  */

// Title: privilege_escalation_dns_serverlevelplugindll.toml
// Source: detection-rules::rules/windows/privilege_escalation_dns_serverlevelplugindll.toml
// Section: EQL Rule
// Rule Name: Unsigned DLL loaded by DNS Service
// Author: Elastic
// Description:
// Identifies unusual DLLs loaded by the DNS Server process, potentially indicating the abuse of the ServerLevelPluginDll
// functionality. This can lead to privilege escalation and remote code execution with SYSTEM privileges.
// Integration: endpoint, windows
// Language: eql
// UUID: 5d676480-9655-4507-adc6-4eec311efff8
// Type: eql

any where host.os.type == "windows" and event.category : ("library", "process") and
  event.type : ("start", "change") and event.action : ("load", "Image loaded*") and
  process.executable : "?:\\windows\\system32\\dns.exe" and
  not ?dll.code_signature.trusted == true and
  not file.code_signature.status == "Valid"

// Title: privilege_escalation_expired_driver_loaded.toml
// Source: detection-rules::rules/windows/privilege_escalation_expired_driver_loaded.toml
// Section: EQL Rule
// Rule Name: Expired or Revoked Driver Loaded
// Author: Elastic
// Description:
// Identifies an attempt to load a revoked or expired driver. Adversaries may bring outdated drivers with vulnerabilities
// to gain code execution in kernel mode or abuse revoked certificates to sign their drivers.
// Integration: endpoint
// Language: eql
// UUID: d12bac54-ab2a-4159-933f-d7bcefa7b61d
// Type: eql

driver where host.os.type == "windows" and process.pid == 4 and
  dll.code_signature.status : ("errorExpired", "errorRevoked")

// Title: privilege_escalation_exploit_cve_202238028.toml
// Source: detection-rules::rules/windows/privilege_escalation_exploit_cve_202238028.toml
// Section: EQL Rule
// Rule Name: Potential privilege escalation via CVE-2022-38028
// Author: Elastic
// Description:
// Identifies a potential privilege escalation attempt via CVE-2022-38028 through modification of the protected Print to PDF
// MPDW constraints script.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: dffbd37c-d4c5-46f8-9181-5afdd9172b4c
// Type: eql

file where host.os.type == "windows" and event.type != "deletion" and
    file.name : "MPDW-constraints.js" and
    file.path : (
        "?:\\*\\Windows\\system32\\DriverStore\\FileRepository\\*\\MPDW-constraints.js",
        "?:\\*\\Windows\\WinSxS\\amd64_microsoft-windows-printing-printtopdf_*\\MPDW-constraints.js", 
        "\\Device\\HarddiskVolume*\\*\\Windows\\system32\\DriverStore\\FileRepository\\*\\MPDW-constraints.js",
        "\\Device\\HarddiskVolume*\\*\\Windows\\WinSxS\\amd64_microsoft-windows-printing-printtopdf_*\\MPDW-constraints.js"
    ) and
    not process.executable : (
          "?:\\$WINDOWS.~BT\\Sources\\SetupHost.exe",
          "?:\\Windows\\System32\\taskhostw.exe"
    ) and
    not file.path : (
        "?:\\$WINDOWS.~BT\\NewOS\\Windows\\WinSxS\\*\\MPDW-constraints.js",
        "\\Device\\HarddiskVolume*\\$WINDOWS.~BT\\NewOS\\Windows\\WinSxS\\*\\MPDW-constraints.js"
    )

// Title: privilege_escalation_gpo_schtask_service_creation.toml
// Source: detection-rules::rules/windows/privilege_escalation_gpo_schtask_service_creation.toml
// Section: EQL Rule
// Rule Name: Creation or Modification of a new GPO Scheduled Task or Service
// Author: Elastic
// Description:
// Detects the creation or modification of a new Group Policy based scheduled task or service. These methods are used for
// legitimate system administration, but can also be abused by an attacker with domain admin permissions to execute a
// malicious payload remotely on all or a subset of the domain joined machines.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel
// Language: eql
// UUID: c0429aa8-9974-42da-bfb6-53a0a515a145
// Type: eql

file where host.os.type == "windows" and event.type != "deletion" and event.action != "open" and
 file.name : ("ScheduledTasks.xml", "Services.xml") and
  file.path : (
    "?:\\Windows\\SYSVOL\\domain\\Policies\\*\\MACHINE\\Preferences\\ScheduledTasks\\ScheduledTasks.xml",
    "?:\\Windows\\SYSVOL\\domain\\Policies\\*\\MACHINE\\Preferences\\Services\\Services.xml"
  ) and
  not process.executable : "C:\\Windows\\System32\\dfsrs.exe"

// Title: privilege_escalation_group_policy_iniscript.toml
// Source: detection-rules::rules/windows/privilege_escalation_group_policy_iniscript.toml
// Section: EQL Rule
// Rule Name: Startup/Logon Script added to Group Policy Object
// Author: Elastic
// Description:
// Detects the modification of Group Policy Objects (GPO) to add a startup/logon script to users or computer objects.
// Integration: system, windows
// Language: eql
// UUID: 16fac1a1-21ee-4ca6-b720-458e3855d046
// Type: eql

any where host.os.type == "windows" and event.code in ("5136", "5145") and
(
  (
    winlog.event_data.AttributeLDAPDisplayName : (
      "gPCMachineExtensionNames",
      "gPCUserExtensionNames"
    ) and
    winlog.event_data.AttributeValue : "*42B5FAAE-6536-11D2-AE5A-0000F87571E3*" and
    winlog.event_data.AttributeValue : (
      "*40B66650-4972-11D1-A7CA-0000F87571E3*",
      "*40B6664F-4972-11D1-A7CA-0000F87571E3*"
    )
  ) or
  (
    winlog.event_data.ShareName : "\\\\*\\SYSVOL" and
    winlog.event_data.RelativeTargetName : ("*\\scripts.ini", "*\\psscripts.ini") and
    winlog.event_data.AccessList:"*%%4417*"
  )
)

// Title: privilege_escalation_group_policy_privileged_groups.toml
// Source: detection-rules::rules/windows/privilege_escalation_group_policy_privileged_groups.toml
// Section: EQL Rule
// Rule Name: Group Policy Abuse for Privilege Addition
// Author: Elastic
// Description:
// Detects the first occurrence of a modification to Group Policy Object Attributes to add privileges to user accounts or
// use them to add users as local admins.
// Integration: system, windows
// Language: eql
// UUID: b9554892-5e0e-424b-83a0-5aef95aa43bf
// Type: eql

any where host.os.type == "windows" and event.code: "5136" and
  winlog.event_data.AttributeLDAPDisplayName: "gPCMachineExtensionNames" and
  winlog.event_data.AttributeValue: "*827D319E-6EAC-11D2-A4EA-00C04F79F83A*" and
  winlog.event_data.AttributeValue: "*803E14A0-B4FB-11D0-A0D0-00A0C90F574B*"

// Title: privilege_escalation_group_policy_scheduled_task.toml
// Source: detection-rules::rules/windows/privilege_escalation_group_policy_scheduled_task.toml
// Section: EQL Rule
// Rule Name: Scheduled Task Execution at Scale via GPO
// Author: Elastic
// Description:
// Detects the modification of Group Policy Object attributes to execute a scheduled task in the objects controlled by the
// GPO.
// Integration: system, windows
// Language: eql
// UUID: 15a8ba77-1c13-4274-88fe-6bd14133861e
// Type: eql

any where host.os.type == "windows" and event.code in ("5136", "5145") and
(
  (
    winlog.event_data.AttributeLDAPDisplayName : (
      "gPCMachineExtensionNames",
      "gPCUserExtensionNames"
    ) and
    winlog.event_data.AttributeValue : "*CAB54552-DEEA-4691-817E-ED4A4D1AFC72*" and
    winlog.event_data.AttributeValue : "*AADCED64-746C-4633-A97C-D61349046527*"
  ) or
  (
    winlog.event_data.ShareName : "\\\\*\\SYSVOL" and
    winlog.event_data.RelativeTargetName : "*ScheduledTasks.xml" and
    winlog.event_data.AccessList:"*%%4417*"
  )
)

// Title: privilege_escalation_installertakeover.toml
// Source: detection-rules::rules/windows/privilege_escalation_installertakeover.toml
// Section: EQL Rule
// Rule Name: Potential Privilege Escalation via InstallerFileTakeOver
// Author: Elastic
// Description:
// Identifies a potential exploitation of InstallerTakeOver (CVE-2021-41379) default PoC execution. Successful exploitation
// allows an unprivileged user to escalate privileges to SYSTEM.
// Integration: endpoint
// Language: eql
// UUID: 58c6d58b-a0d3-412d-b3b8-0981a9400607
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
    process.Ext.token.integrity_level_name : "System" and
    (
      (process.name : "elevation_service.exe" and
       not process.pe.original_file_name == "elevation_service.exe") or

      (process.name : "elevation_service.exe" and
       not process.code_signature.trusted == true) or

      (process.parent.name : "elevation_service.exe" and
       process.name : ("rundll32.exe", "cmd.exe", "powershell.exe"))
    ) and
    not
    (
      process.name : "elevation_service.exe" and process.code_signature.trusted == true and
      process.pe.original_file_name == null
    )

// Title: privilege_escalation_krbrelayup_service_creation.toml
// Source: detection-rules::rules/windows/privilege_escalation_krbrelayup_service_creation.toml
// Section: EQL Rule
// Rule Name: Service Creation via Local Kerberos Authentication
// Author: Elastic
// Description:
// Identifies a suspicious local successful logon event where the Logon Package is Kerberos, the remote address is set to
// localhost, followed by service creation from the same LogonId. This may indicate an attempt to leverage a Kerberos relay
// attack variant that can elevate privileges locally from a domain-joined user to LocalSystem privileges.
// Integration: system, windows
// Language: eql
// UUID: e4e31051-ee01-4307-a6ee-b21b186958f4
// Type: eql

sequence by winlog.computer_name with maxspan=5m
 [authentication where host.os.type == "windows" and

  /* event 4624 need to be logged */
  event.action == "logged-in" and event.outcome == "success" and winlog.event_data.ElevatedToken == "%%1843" and process.pid == 0 and 

  /* authenticate locally using relayed kerberos Ticket */
  winlog.event_data.AuthenticationPackageName :"Kerberos" and winlog.logon.type == "Network" and cidrmatch(source.ip, "127.0.0.0/8", "::1")] by winlog.event_data.TargetLogonId

  [any where host.os.type == "windows" and
   /* event 4697 need to be logged */
   event.action : "service-installed"] by winlog.event_data.SubjectLogonId

// Title: privilege_escalation_lsa_auth_package.toml
// Source: detection-rules::rules/windows/privilege_escalation_lsa_auth_package.toml
// Section: EQL Rule
// Rule Name: Potential LSA Authentication Package Abuse
// Author: Elastic
// Description:
// Adversaries can use the autostart mechanism provided by the Local Security Authority (LSA) authentication packages for
// privilege escalation or persistence by placing a reference to a binary in the Windows registry. The binary will then be
// executed by SYSTEM when the authentication packages are loaded.
// Integration: endpoint, m365_defender
// Language: eql
// UUID: e9abe69b-1deb-4e19-ac4a-5d5ac00f72eb
// Type: eql

registry where host.os.type == "windows" and event.type == "change" and
  registry.path : (
      "HKLM\\SYSTEM\\*ControlSet*\\Control\\Lsa\\Authentication Packages",
      "\\REGISTRY\\MACHINE\\SYSTEM\\*ControlSet*\\Control\\Lsa\\Authentication Packages"
  ) and
  /* exclude SYSTEM SID - look for changes by non-SYSTEM user */
  not user.id : "S-1-5-18"

// Title: privilege_escalation_make_token_local.toml
// Source: detection-rules::rules/windows/privilege_escalation_make_token_local.toml
// Section: EQL Rule
// Rule Name: Interactive Logon by an Unusual Process
// Author: Elastic
// Description:
// Identifies interactive logon attempt with alternate credentials and by an unusual process. Adversaries may create a new
// token to escalate privileges and bypass access controls.
// Integration: system, windows
// Language: eql
// UUID: 61766ef9-48a5-4247-ad74-3349de7eb2ad
// Type: eql

authentication where
 host.os.type : "windows" and winlog.event_data.LogonProcessName : "Advapi*" and
 winlog.logon.type == "Interactive" and winlog.event_data.SubjectUserSid : ("S-1-5-21*", "S-1-12-*") and
 winlog.event_data.TargetUserSid : ("S-1-5-21*", "S-1-12-*")  and process.executable : "C:\\*" and
 not startswith~(winlog.event_data.SubjectUserSid, winlog.event_data.TargetUserSid) and
 not process.executable :
            ("?:\\Windows\\System32\\winlogon.exe",
             "?:\\Windows\\System32\\wininit.exe",
             "?:\\Program Files\\*.exe",
             "?:\\Program Files (x86)\\*.exe",
             "?:\\Windows\\SysWOW64\\inetsrv\\w3wp.exe",
             "?:\\Windows\\System32\\inetsrv\\w3wp.exe",
             "?:\\Windows\\SysWOW64\\msiexec.exe")

// Title: privilege_escalation_msi_repair_via_mshelp_link.toml
// Source: detection-rules::rules/windows/privilege_escalation_msi_repair_via_mshelp_link.toml
// Section: EQL Rule
// Rule Name: Potential Escalation via Vulnerable MSI Repair
// Author: Elastic
// Description:
// Identifies when a browser process navigates to the Microsoft Help page followed by spawning an elevated process. This
// may indicate a successful exploitation for privilege escalation abusing a vulnerable Windows Installer repair setup.
// Integration: endpoint, sentinel_one_cloud_funnel, m365_defender, windows
// Language: eql
// UUID: 043d80a3-c49e-43ef-9c72-1088f0c7b278
// Type: eql

process where event.type == "start" and host.os.type == "windows" and
 user.domain : ("NT AUTHORITY", "AUTORITE NT", "AUTORIDADE NT") and
 process.parent.name : ("chrome.exe", "msedge.exe", "brave.exe", "whale.exe", "browser.exe", "dragon.exe", "vivaldi.exe",
                        "opera.exe", "iexplore", "firefox.exe", "waterfox.exe", "iexplore.exe", "tor.exe", "safari.exe") and
 process.parent.command_line : "*go.microsoft.com*"

// Title: privilege_escalation_named_pipe_impersonation.toml
// Source: detection-rules::rules/windows/privilege_escalation_named_pipe_impersonation.toml
// Section: EQL Rule
// Rule Name: Privilege Escalation via Named Pipe Impersonation
// Author: Elastic
// Description:
// Identifies a privilege escalation attempt via named pipe impersonation. An adversary may abuse this technique by
// utilizing a framework such as Metasploit's meterpreter getsystem command.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 3ecbdc9e-e4f2-43fa-8cca-63802125e582
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
 (process.name : ("Cmd.Exe", "PowerShell.EXE") or ?process.pe.original_file_name in ("Cmd.Exe", "PowerShell.EXE")) and
 process.args : "echo" and process.args : ">" and process.args : "\\\\.\\pipe\\*"

// Title: privilege_escalation_persistence_phantom_dll.toml
// Source: detection-rules::rules/windows/privilege_escalation_persistence_phantom_dll.toml
// Section: EQL Rule
// Rule Name: Suspicious DLL Loaded for Persistence or Privilege Escalation
// Author: Elastic
// Description:
// Identifies the loading of a non Microsoft signed DLL that is missing on a default Windows install (phantom DLL) or one
// that can be loaded from a different location by a native Windows process. This may be abused to persist or elevate
// privileges via privileged file write vulnerabilities.
// Integration: endpoint, windows
// Language: eql
// UUID: bfeaf89b-a2a7-48a3-817f-e41829dc61ee
// Type: eql

any where host.os.type == "windows" and 
(
  /*  Elastic Defend DLL load events */
  (event.category == "library" and 
    (
     ?dll.name : ("wlbsctrl.dll", "wbemcomn.dll", "WptsExtensions.dll", "Tsmsisrv.dll", "TSVIPSrv.dll", "Msfte.dll", "wow64log.dll", "WindowsCoreDeviceInfo.dll", "Ualapi.dll", "wlanhlp.dll", "phoneinfo.dll", "EdgeGdi.dll", "cdpsgshims.dll", "windowsperformancerecordercontrol.dll", "diagtrack_win.dll", "TPPCOIPW32.dll", "tpgenlic.dll", "thinmon.dll", "fxsst.dll", "msTracer.dll") or 

     (?dll.path : "?:\\Windows\\*\\oci.dll" and process.executable : "?:\\Windows\\*.exe")
     )
    and (?dll.code_signature.trusted == false or ?dll.code_signature.exists == false or (?dll.code_signature.trusted == true and not ?dll.code_signature.subject_name : ("Microsoft Windows", "Microsoft Corporation", "Microsoft Windows Publisher"))
      ))
   or

  /*  Sysmon DLL load events */
  ((event.category == "process" and event.action like "Image loaded*") and file.code_signature.status != "Valid" and 
  file.name : ("wlbsctrl.dll", "wbemcomn.dll", "WptsExtensions.dll", "Tsmsisrv.dll", "TSVIPSrv.dll", "Msfte.dll", "wow64log.dll", "WindowsCoreDeviceInfo.dll", "Ualapi.dll", "wlanhlp.dll", "phoneinfo.dll", "EdgeGdi.dll", "cdpsgshims.dll", "windowsperformancerecordercontrol.dll", "diagtrack_win.dll", "TPPCOIPW32.dll", "tpgenlic.dll", "thinmon.dll", "fxsst.dll", "msTracer.dll") and 
   not file.hash.sha256 in 
            ("6e837794fc282446906c36d681958f2f6212043fc117c716936920be166a700f", 
             "b14e4954e8cca060ffeb57f2458b6a3a39c7d2f27e94391cbcea5387652f21a4", 
             "c258d90acd006fa109dc6b748008edbb196d6168bc75ace0de0de54a4db46662", 
             "254e5053ac04b7623e86234077876388e0b10c3ac5c3f4e4e86292b62571bfb0")) 

) and not
  (
    ?dll.path : (
      "?:\\Windows\\System32\\wbemcomn.dll",
      "?:\\Windows\\SysWOW64\\wbemcomn.dll",
      "?:\\Windows\\System32\\windowsperformancerecordercontrol.dll",
      "?:\\Windows\\System32\\wlanhlp.dll", 
      "\\Device\\HarddiskVolume?\\Windows\\SysWOW64\\wbemcomn.dll", 
      "\\Device\\HarddiskVolume?\\Windows\\System32\\wbemcomn.dll", 
      "\\Device\\HarddiskVolume?\\Windows\\SysWOW64\\wlanhlp.dll", 
      "\\Device\\HarddiskVolume?\\Windows\\System32\\wlanhlp.dll", 
      "\\Device\\HarddiskVolume?\\Windows\\SysWOW64\\windowsperformancerecordercontrol.dll", 
      "\\Device\\HarddiskVolume?\\Windows\\System32\\windowsperformancerecordercontrol.dll", 
      "C:\\ProgramData\\docker\\windowsfilter\\*\\Files\\Windows\\System32\\windowsperformancerecordercontrol.dll", 
      "\\Device\\vmsmb\\VSMB-{*}\\os\\windows\\system32\\*.dll", 
      "C:\\Windows\\WinSxS\\amd64_microsoft-windows-wmi-core-wbemcomn-dll_*\\wbemcomn.dll", 
      "C:\\Windows\\WinSxS\\wow64_microsoft-windows-wmi-core-wbemcomn-dll_*\\wbemcomn.dll", 
      "C:\\Windows\\WinSxS\\amd64_microsoft-windows-coresystem-wpr_*\\windowsperformancerecordercontrol.dll"
    ) or

    file.path : (
      "?:\\Windows\\System32\\wbemcomn.dll",
      "?:\\Windows\\SysWOW64\\wbemcomn.dll",
      "?:\\Windows\\System32\\windowsperformancerecordercontrol.dll",
      "?:\\Windows\\System32\\wlanhlp.dll", 
      "C:\\ProgramData\\docker\\windowsfilter\\*\\Files\\Windows\\System32\\windowsperformancerecordercontrol.dll", 
      "C:\\ProgramData\\docker\\windowsfilter\\*\\Files\\Windows\\System32\\wbemcomn.dll", 
      "\\Device\\vmsmb\\VSMB-{*}\\os\\windows\\system32\\*.dll", 
      "C:\\Windows\\WinSxS\\amd64_microsoft-windows-wmi-core-wbemcomn-dll_*\\wbemcomn.dll", 
      "C:\\Windows\\WinSxS\\wow64_microsoft-windows-wmi-core-wbemcomn-dll_*\\wbemcomn.dll"
    ) or 

 ?dll.code_signature.status like "errorCode_endpoint*"
  )

// Title: privilege_escalation_port_monitor_print_processor_abuse.toml
// Source: detection-rules::rules/windows/privilege_escalation_port_monitor_print_processor_abuse.toml
// Section: EQL Rule
// Rule Name: Potential Port Monitor or Print Processor Registration Abuse
// Author: Elastic
// Description:
// Identifies port monitor and print processor registry modifications. Adversaries may abuse port monitor and print
// processors to run malicious DLLs during system boot that will be executed as SYSTEM for privilege escalation and/or
// persistence, if permissions allow writing a fully-qualified pathname for that DLL.
// Integration: endpoint, m365_defender
// Language: eql
// UUID: 8f3e91c7-d791-4704-80a1-42c160d7aa27
// Type: eql

registry where host.os.type == "windows" and event.type == "change" and
  registry.path : (
      "HKLM\\SYSTEM\\*ControlSet*\\Control\\Print\\Monitors\\*",
      "HKLM\\SYSTEM\\*ControlSet*\\Control\\Print\\Environments\\Windows*\\Print Processors\\*",
      "\\REGISTRY\\MACHINE\\SYSTEM\\*ControlSet*\\Control\\Print\\Monitors\\*",
      "\\REGISTRY\\MACHINE\\SYSTEM\\*ControlSet*\\Control\\Print\\Environments\\Windows*\\Print Processors\\*"
  ) and registry.data.strings : "*.dll" and
  /* exclude SYSTEM SID - look for changes by non-SYSTEM user */
  not user.id : "S-1-5-18"

// Title: privilege_escalation_printspooler_registry_copyfiles.toml
// Source: detection-rules::rules/windows/privilege_escalation_printspooler_registry_copyfiles.toml
// Section: EQL Rule
// Rule Name: Suspicious Print Spooler Point and Print DLL
// Author: Elastic
// Description:
// Detects attempts to exploit a privilege escalation vulnerability (CVE-2020-1030) related to the print spooler service.
// Exploitation involves chaining multiple primitives to load an arbitrary DLL into the print spooler process running as
// SYSTEM.
// Integration: endpoint, windows, sentinel_one_cloud_funnel, m365_defender
// Language: eql
// UUID: bd7eefee-f671-494e-98df-f01daf9e5f17
// Type: eql

sequence by host.id with maxspan=30s
[registry where host.os.type == "windows" and
   registry.value : "SpoolDirectory" and
   registry.path : "*\\SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\Print\\Printers\\*\\SpoolDirectory" and
   registry.data.strings : "C:\\Windows\\System32\\spool\\drivers\\x64\\4"]
[registry where host.os.type == "windows" and
   registry.value : "Module" and
   registry.path : "*\\SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\Print\\Printers\\*\\CopyFiles\\Payload\\Module" and
   registry.data.strings : "C:\\Windows\\System32\\spool\\drivers\\x64\\4\\*"]

// Title: privilege_escalation_printspooler_suspicious_file_deletion.toml
// Source: detection-rules::rules/windows/privilege_escalation_printspooler_suspicious_file_deletion.toml
// Section: EQL Rule
// Rule Name: Suspicious Print Spooler File Deletion
// Author: Elastic
// Description:
// Detects deletion of print driver files by an unusual process. This may indicate a clean up attempt post successful
// privilege escalation via Print Spooler service related vulnerabilities.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel
// Language: eql
// UUID: c4818812-d44f-47be-aaef-4cfb2f9cc799
// Type: eql

file where host.os.type == "windows" and event.type == "deletion" and
  file.extension : "dll" and file.path : "?:\\Windows\\System32\\spool\\drivers\\x64\\3\\*.dll" and
  not process.name : ("spoolsv.exe", "dllhost.exe", "explorer.exe")

// Title: privilege_escalation_printspooler_suspicious_spl_file.toml
// Source: detection-rules::rules/windows/privilege_escalation_printspooler_suspicious_spl_file.toml
// Section: EQL Rule
// Rule Name: Suspicious Print Spooler SPL File Created
// Author: Elastic
// Description:
// Detects attempts to exploit privilege escalation vulnerabilities related to the Print Spooler service including
// CVE-2020-1048 and CVE-2020-1337.
// Integration: endpoint, m365_defender
// Language: eql
// UUID: a7ccae7b-9d2c-44b2-a061-98e5946971fa
// Type: eql

file where host.os.type == "windows" and event.type != "deletion" and
  file.extension : "spl" and
  file.path : "?:\\Windows\\System32\\spool\\PRINTERS\\*" and
  not process.name : ("spoolsv.exe",
                      "printfilterpipelinesvc.exe",
                      "PrintIsolationHost.exe",
                      "splwow64.exe",
                      "msiexec.exe",
                      "poqexec.exe",
                      "System") and
  not user.id : "S-1-5-18" and
  not process.executable :
            ("?:\\Windows\\System32\\mmc.exe",
             "\\Device\\Mup\\*.exe",
             "?:\\Windows\\System32\\svchost.exe",
             "?:\\Windows\\System32\\mmc.exe",
             "?:\\Windows\\System32\\printui.exe",
             "?:\\Windows\\System32\\mstsc.exe",
             "?:\\Windows\\System32\\spool\\*.exe",
             "?:\\Program Files\\*.exe",
             "?:\\Program Files (x86)\\*.exe",
             "?:\\PROGRA~1\\*.exe",
             "?:\\PROGRA~2\\*.exe",
             "?:\\Windows\\System32\\rundll32.exe")

// Title: privilege_escalation_rogue_windir_environment_var.toml
// Source: detection-rules::rules/windows/privilege_escalation_rogue_windir_environment_var.toml
// Section: EQL Rule
// Rule Name: Privilege Escalation via Windir Environment Variable
// Author: Elastic
// Description:
// Identifies a privilege escalation attempt via a rogue Windows directory (Windir) environment variable. This is a known
// primitive that is often combined with other vulnerabilities to elevate privileges.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: d563aaba-2e72-462b-8658-3e5ea22db3a6
// Type: eql

registry where host.os.type == "windows" and event.type == "change" and
registry.value : ("windir", "systemroot") and registry.data.strings != null and
registry.path : (
    "*\\Environment\\windir",
    "*\\Environment\\systemroot"
    ) and
 not registry.data.strings : ("C:\\windows", "%SystemRoot%")

// Title: privilege_escalation_samaccountname_spoofing_attack.toml
// Source: detection-rules::rules/windows/privilege_escalation_samaccountname_spoofing_attack.toml
// Section: EQL Rule
// Rule Name: Potential Privileged Escalation via SamAccountName Spoofing
// Author: Elastic
// Description:
// Identifies a suspicious computer account name rename event, which may indicate an attempt to exploit CVE-2021-42278 to
// elevate privileges from a standard domain user to a user with domain admin privileges. CVE-2021-42278 is a security
// vulnerability that allows potential attackers to impersonate a domain controller via samAccountName attribute spoofing.
// Integration: system, windows
// Language: eql
// UUID: bdcf646b-08d4-492c-870a-6c04e3700034
// Type: eql

iam where host.os.type == "windows" and event.action == "renamed-user-account" and
  /* machine account name renamed to user like account name */
  winlog.event_data.OldTargetUserName : "*$" and not winlog.event_data.NewTargetUserName : "*$"

// Title: privilege_escalation_service_control_spawned_script_int.toml
// Source: detection-rules::rules/windows/privilege_escalation_service_control_spawned_script_int.toml
// Section: EQL Rule
// Rule Name: Service Control Spawned via Script Interpreter
// Author: Elastic
// Description:
// Identifies Service Control (sc.exe) spawning from script interpreter processes to create, modify, or start services.
// This can potentially indicate an attempt to elevate privileges or maintain persistence.
// Integration: endpoint, system, windows, m365_defender, crowdstrike
// Language: eql
// UUID: e8571d5f-bea1-46c2-9f56-998de2d3ed95
// Type: eql

/* This rule is not compatible with Sysmon due to user.id issues */

process where host.os.type == "windows" and event.type == "start" and
  (process.name : "sc.exe" or ?process.pe.original_file_name == "sc.exe") and
  process.parent.name : ("cmd.exe", "wscript.exe", "rundll32.exe", "regsvr32.exe",
                         "wmic.exe", "mshta.exe","powershell.exe", "pwsh.exe") and
  process.args:("config", "create", "start", "delete", "stop", "pause") and
  /* exclude SYSTEM SID - look for service creations by non-SYSTEM user */
  not user.id : "S-1-5-18"

// Title: privilege_escalation_suspicious_dnshostname_update.toml
// Source: detection-rules::rules/windows/privilege_escalation_suspicious_dnshostname_update.toml
// Section: EQL Rule
// Rule Name: Remote Computer Account DnsHostName Update
// Author: Elastic
// Description:
// Identifies the remote update to a computer account's DnsHostName attribute. If the new value set is a valid domain
// controller DNS hostname and the subject computer name is not a domain controller, then it's highly likely a preparation
// step to exploit CVE-2022-26923 in an attempt to elevate privileges from a standard domain user to domain admin
// privileges.
// Integration: system, windows
// Language: eql
// UUID: 6bed021a-0afb-461c-acbe-ffdb9574d3f3
// Type: eql

iam where host.os.type == "windows" and event.action == "changed-computer-account" and
    user.id : ("S-1-5-21-*", "S-1-12-1-*") and

    /* if DnsHostName value equal a DC DNS hostname then it's highly suspicious */
    winlog.event_data.DnsHostName : "??*" and

    /* exclude FPs where DnsHostName starts with the ComputerName that was changed */
    not startswith~(winlog.event_data.DnsHostName, substring(winlog.event_data.TargetUserName, 0, length(winlog.event_data.TargetUserName) - 1))

// Title: privilege_escalation_takeover_new_source_ip.toml
// Source: detection-rules::rules/windows/privilege_escalation_takeover_new_source_ip.toml
// Section: EQL Rule
// Rule Name: Potential Account Takeover - Logon from New Source IP
// Author: Elastic
// Description:
// Identifies a user account that normally logs in with high volume from one source IP suddenly logging in from a different
// source IP. This pattern (one IP with many successful logons, another IP with very few) may indicate account takeover
// or use of stolen credentials from a new location.
// Integration: system, windows
// Language: esql
// UUID: a1b2c3d4-e5f6-4a5b-8c9d-0e1f2a3b4c5d
// Type: esql

from logs-system.security*, logs-windows.forwarded*, winlogbeat-* metadata _id, _version, _index
| where event.category == "authentication" and event.action == "logged-in" and winlog.event_id == "4624" and 
        event.outcome == "success" and winlog.logon.type in ("Network", "RemoteInteractive") and 
		source.ip is not null and source.ip != "127.0.0.1" and not to_string(source.ip) like "*::*" and not user.name like "*$"
| stats logon_count = COUNT(*), host_names = VALUES(host.name) by user.name, user.id, source.ip
| stats 
    Esql.max_logon = MAX(logon_count),
    Esql.min_logon = MIN(logon_count),
    Esql.unique_host_count = COUNT_DISTINCT(host_names),
    Esql.host_name_values = VALUES(host_names),
    Esql.source_ip_values = VALUES(source.ip),
    Esql.count_distinct_source_ip = COUNT_DISTINCT(source.ip) by user.name, user.id

// high count of logons is often associated with service account tied to a specific source.ip, if observed in use from a new source.ip it's suspicious
| where Esql.max_logon >= 1000 and (Esql.min_logon >= 1 and Esql.min_logon <= 5) and Esql.count_distinct_source_ip == 2 and Esql.unique_host_count >= 2
| eval source.ip = MV_FIRST(Esql.source_ip_values), host.name = MV_FIRST(Esql.host_name_values)
| KEEP user.name, user.id, host.name, source.ip, Esql.*

// Title: privilege_escalation_tokenmanip_sedebugpriv_enabled.toml
// Source: detection-rules::rules/windows/privilege_escalation_tokenmanip_sedebugpriv_enabled.toml
// Section: EQL Rule
// Rule Name: SeDebugPrivilege Enabled by a Suspicious Process
// Author: Elastic
// Description:
// Identifies a process running with a non-SYSTEM account that enables the SeDebugPrivilege privilege. Adversaries may
// enable this privilege to debug and modify other processes, typically reserved for system-level tasks, to escalate
// privileges and bypass access controls.
// Integration: windows, system
// Language: eql
// UUID: 97020e61-e591-4191-8a3b-2861a2b887cd
// Type: eql

any where host.os.type == "windows" and event.provider: "Microsoft-Windows-Security-Auditing" and
 event.action : "Token Right Adjusted Events" and

 winlog.event_data.EnabledPrivilegeList : "SeDebugPrivilege" and

 /* exclude processes with System Integrity  */
 not winlog.event_data.SubjectUserSid : ("S-1-5-18", "S-1-5-19", "S-1-5-20") and

 not winlog.event_data.ProcessName : (
        "?:\\Program Files (x86)\\*",
        "?:\\Program Files\\*",
        "?:\\Users\\*\\AppData\\Local\\Temp\\*-*\\DismHost.exe",
        "?:\\Windows\\System32\\auditpol.exe",
        "?:\\Windows\\System32\\cleanmgr.exe",
        "?:\\Windows\\System32\\lsass.exe",
        "?:\\Windows\\System32\\mmc.exe",
        "?:\\Windows\\System32\\MRT.exe",
        "?:\\Windows\\System32\\msiexec.exe",
        "?:\\Windows\\System32\\sdiagnhost.exe",
        "?:\\Windows\\System32\\ServerManager.exe",
        "?:\\Windows\\System32\\taskhostw.exe",
        "?:\\Windows\\System32\\wbem\\WmiPrvSe.exe",
        "?:\\Windows\\System32\\WerFault.exe",
        "?:\\Windows\\SysWOW64\\msiexec.exe",
        "?:\\Windows\\SysWOW64\\wbem\\WmiPrvSe.exe",
        "?:\\Windows\\SysWOW64\\WerFault.exe",
        "?:\\Windows\\WinSxS\\*"
    )

// Title: privilege_escalation_uac_bypass_com_clipup.toml
// Source: detection-rules::rules/windows/privilege_escalation_uac_bypass_com_clipup.toml
// Section: EQL Rule
// Rule Name: UAC Bypass Attempt with IEditionUpgradeManager Elevated COM Interface
// Author: Elastic
// Description:
// Identifies attempts to bypass User Account Control (UAC) by abusing an elevated COM Interface to launch a rogue Windows
// ClipUp program. Attackers may attempt to bypass UAC to stealthily execute code with elevated permissions.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel
// Language: eql
// UUID: b90cdde7-7e0d-4359-8bf0-2c112ce2008a
// Type: eql

process where host.os.type == "windows" and event.type == "start" and process.name : "Clipup.exe" and
  not process.executable : "C:\\Windows\\System32\\ClipUp.exe" and process.parent.name : "dllhost.exe" and
  /* CLSID of the Elevated COM Interface IEditionUpgradeManager */
  process.parent.args : "/Processid:{BD54C901-076B-434E-B6C7-17C531F4AB41}"

// Title: privilege_escalation_uac_bypass_com_ieinstal.toml
// Source: detection-rules::rules/windows/privilege_escalation_uac_bypass_com_ieinstal.toml
// Section: EQL Rule
// Rule Name: UAC Bypass Attempt via Elevated COM Internet Explorer Add-On Installer
// Author: Elastic
// Description:
// Identifies User Account Control (UAC) bypass attempts by abusing an elevated COM Interface to launch a malicious
// program. Attackers may attempt to bypass UAC to stealthily execute code with elevated permissions.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel
// Language: eql
// UUID: fc7c0fa4-8f03-4b3e-8336-c5feab0be022
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
 process.executable : "C:\\*\\AppData\\*\\Temp\\IDC*.tmp\\*.exe" and
 process.parent.name : "ieinstal.exe" and process.parent.args : "-Embedding"

 /* uncomment once in winlogbeat */
 /* and not (process.code_signature.subject_name == "Microsoft Corporation" and process.code_signature.trusted == true) */

// Title: privilege_escalation_uac_bypass_com_interface_icmluautil.toml
// Source: detection-rules::rules/windows/privilege_escalation_uac_bypass_com_interface_icmluautil.toml
// Section: EQL Rule
// Rule Name: UAC Bypass via ICMLuaUtil Elevated COM Interface
// Author: Elastic
// Description:
// Identifies User Account Control (UAC) bypass attempts via the ICMLuaUtil Elevated COM interface. Attackers may attempt
// to bypass UAC to stealthily execute code with elevated permissions.
// Integration: endpoint, windows, m365_defender
// Language: eql
// UUID: 68d56fdc-7ffa-4419-8e95-81641bd6f845
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
 process.parent.name == "dllhost.exe" and
 process.parent.args in ("/Processid:{3E5FC7F9-9A51-4367-9063-A120244FBEC7}", "/Processid:{D2E7041B-2927-42FB-8E9F-7CE93B6DC937}") and
 process.pe.original_file_name != "WerFault.exe" and
 not (process.executable : "?:\\Program Files\\WireGuard\\wireguard.exe" and process.args : "/installmanagerservice")

// Title: privilege_escalation_uac_bypass_diskcleanup_hijack.toml
// Source: detection-rules::rules/windows/privilege_escalation_uac_bypass_diskcleanup_hijack.toml
// Section: EQL Rule
// Rule Name: UAC Bypass via DiskCleanup Scheduled Task Hijack
// Author: Elastic
// Description:
// Identifies User Account Control (UAC) bypass via hijacking DiskCleanup Scheduled Task. Attackers bypass UAC to
// stealthily execute code with elevated permissions.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 1dcc51f6-ba26-49e7-9ef4-2655abb2361e
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
 process.args : "/autoclean" and process.args : "/d" and process.executable != null and
 not process.executable : (
        "C:\\Windows\\System32\\cleanmgr.exe",
        "C:\\Windows\\SysWOW64\\cleanmgr.exe",
        "C:\\Windows\\System32\\taskhostw.exe",

        /* Crowdstrike specific exclusion as it uses NT Object paths */
        "\\Device\\HarddiskVolume*\\Windows\\System32\\cleanmgr.exe",
        "\\Device\\HarddiskVolume*\\Windows\\SysWOW64\\cleanmgr.exe",
        "\\Device\\HarddiskVolume*\\Windows\\System32\\taskhostw.exe"
)

// Title: privilege_escalation_uac_bypass_dll_sideloading.toml
// Source: detection-rules::rules/windows/privilege_escalation_uac_bypass_dll_sideloading.toml
// Section: EQL Rule
// Rule Name: UAC Bypass Attempt via Privileged IFileOperation COM Interface
// Author: Elastic
// Description:
// Identifies attempts to bypass User Account Control (UAC) via DLL side-loading. Attackers may attempt to bypass UAC to
// stealthily execute code with elevated permissions.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel
// Language: eql
// UUID: 5a14d01d-7ac8-4545-914c-b687c2cf66b3
// Type: eql

file where host.os.type == "windows" and event.type : "change" and process.name : "dllhost.exe" and
  /* Known modules names side loaded into process running with high or system integrity level for UAC Bypass, update here for new modules */
  file.name : ("wow64log.dll", "comctl32.dll", "DismCore.dll", "OskSupport.dll", "duser.dll", "Accessibility.ni.dll") and
  /* has no impact on rule logic just to avoid OS install related FPs */
  not file.path : ("C:\\Windows\\SoftwareDistribution\\*", "C:\\Windows\\WinSxS\\*")

// Title: privilege_escalation_uac_bypass_event_viewer.toml
// Source: detection-rules::rules/windows/privilege_escalation_uac_bypass_event_viewer.toml
// Section: EQL Rule
// Rule Name: Bypass UAC via Event Viewer
// Author: Elastic
// Description:
// Identifies User Account Control (UAC) bypass via eventvwr.exe. Attackers bypass UAC to stealthily execute code with
// elevated permissions.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 31b4c719-f2b4-41f6-a9bd-fce93c2eaf62
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.parent.name : "eventvwr.exe" and
  not process.executable : (
        "?:\\Windows\\SysWOW64\\mmc.exe",
        "?:\\Windows\\System32\\mmc.exe",
        "?:\\Windows\\SysWOW64\\WerFault.exe",
        "?:\\Windows\\System32\\WerFault.exe",

        /* Crowdstrike specific exclusion as it uses NT Object paths */
        "\\Device\\HarddiskVolume*\\Windows\\Sys?????\\mmc.exe",
        "\\Device\\HarddiskVolume*\\Windows\\Sys?????\\WerFault.exe"
  )

// Title: privilege_escalation_uac_bypass_mock_windir.toml
// Source: detection-rules::rules/windows/privilege_escalation_uac_bypass_mock_windir.toml
// Section: EQL Rule
// Rule Name: UAC Bypass Attempt via Windows Directory Masquerading
// Author: Elastic
// Description:
// Identifies an attempt to bypass User Account Control (UAC) by masquerading as a Microsoft trusted Windows directory.
// Attackers may bypass UAC to stealthily execute code with elevated permissions.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 290aca65-e94d-403b-ba0f-62f320e63f51
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.args : ("C:\\Windows \\system32\\*.exe", "C:\\Windows \\SysWOW64\\*.exe")

// Title: privilege_escalation_uac_bypass_winfw_mmc_hijack.toml
// Source: detection-rules::rules/windows/privilege_escalation_uac_bypass_winfw_mmc_hijack.toml
// Section: EQL Rule
// Rule Name: UAC Bypass via Windows Firewall Snap-In Hijack
// Author: Elastic
// Description:
// Identifies attempts to bypass User Account Control (UAC) by hijacking the Microsoft Management Console (MMC) Windows
// Firewall snap-in. Attackers bypass UAC to stealthily execute code with elevated permissions.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel
// Language: eql
// UUID: 1178ae09-5aff-460a-9f2f-455cd0ac4d8e
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
 process.parent.name == "mmc.exe" and
 /* process.Ext.token.integrity_level_name == "high" can be added in future for tuning */
 /* args of the Windows Firewall SnapIn */
  process.parent.args == "WF.msc" and process.name != "WerFault.exe"

// Title: privilege_escalation_unquoted_service_path.toml
// Source: detection-rules::rules/windows/privilege_escalation_unquoted_service_path.toml
// Section: EQL Rule
// Rule Name: Potential Exploitation of an Unquoted Service Path Vulnerability
// Author: Elastic
// Description:
// Adversaries may leverage unquoted service path vulnerabilities to escalate privileges. By placing an executable in a
// higher-level directory within the path of an unquoted service executable, Windows will natively launch this executable
// from its defined path variable instead of the benign one in a deeper directory, thus leading to code execution.
// Integration: endpoint, m365_defender, sentinel_one_cloud_funnel, windows, system, crowdstrike
// Language: eql
// UUID: 12de29d4-bbb0-4eef-b687-857e8a163870
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  (
    process.executable : "?:\\Program.exe" or
    process.executable regex """(C:\\Program Files \(x86\)\\|C:\\Program Files\\)\w+.exe"""
  )

// Title: privilege_escalation_unusual_parentchild_relationship.toml
// Source: detection-rules::rules/windows/privilege_escalation_unusual_parentchild_relationship.toml
// Section: EQL Rule
// Rule Name: Unusual Parent-Child Relationship
// Author: Elastic
// Description:
// Identifies Windows programs run from unexpected parent processes. This could indicate masquerading or other strange
// activity on a system.
// Integration: endpoint, windows, system, m365_defender, sentinel_one_cloud_funnel, crowdstrike
// Language: eql
// UUID: 35df0dd8-092d-4a83-88c1-5151a804f31b
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
process.parent.name != null and process.parent.executable like ("?:\\*", "\\Device\\*") and
 (
   /* suspicious parent processes */
   (process.name:"autochk.exe" and not process.parent.name:"smss.exe") or
   (process.name:("fontdrvhost.exe", "dwm.exe") and not process.parent.name:("wininit.exe", "winlogon.exe", "dwm.exe")) or
   (process.name:("consent.exe", "RuntimeBroker.exe", "TiWorker.exe") and not process.parent.name:("svchost.exe", "Workplace Container Helper.exe")) or
   (process.name:"SearchIndexer.exe" and not process.parent.name:"services.exe") or
   (process.name:"SearchProtocolHost.exe" and not process.parent.name:("SearchIndexer.exe", "dllhost.exe")) or
   (process.name:"dllhost.exe" and not process.parent.name:("services.exe", "svchost.exe")) or
   (process.name:"smss.exe" and not process.parent.name:("System", "smss.exe")) or
   (process.name:"csrss.exe" and not process.parent.name:("smss.exe", "svchost.exe")) or
   (process.name:"wininit.exe" and not process.parent.name:"smss.exe") or
   (process.name:"winlogon.exe" and not process.parent.name:"smss.exe") or
   (process.name:("lsass.exe", "LsaIso.exe") and not process.parent.name:"wininit.exe") or
   (process.name:"LogonUI.exe" and not process.parent.name:("wininit.exe", "winlogon.exe")) or
   (process.name:"services.exe" and not process.parent.name:"wininit.exe") or
   (process.name:"svchost.exe" and not process.parent.name:("MsMpEng.exe", "services.exe", "svchost.exe")) or
   (process.name:"spoolsv.exe" and not process.parent.name:("services.exe", "Workplace Starter.exe")) or
   (process.name:"taskhost.exe" and not process.parent.name:("services.exe", "svchost.exe", "ngentask.exe")) or
   (process.name:"taskhostw.exe" and not process.parent.name:("services.exe", "svchost.exe")) or
   (process.name:"userinit.exe" and not process.parent.name:("dwm.exe", "winlogon.exe", "KUsrInit.exe")) or
   (process.name:("wmiprvse.exe", "wsmprovhost.exe", "winrshost.exe") and not process.parent.name:"svchost.exe") or
   /* suspicious child processes */
   (process.parent.name:("SearchProtocolHost.exe", "taskhost.exe", "csrss.exe") and not process.name:("werfault.exe", "wermgr.exe", "WerFaultSecure.exe", "conhost.exe", "ngentask.exe", "SearchProtocolHost.exe")) or
   (process.parent.name:"autochk.exe" and not process.name:("chkdsk.exe", "doskey.exe", "WerFault.exe")) or
   (process.parent.name:"smss.exe" and not process.name:("autochk.exe", "smss.exe", "csrss.exe", "wininit.exe", "winlogon.exe", "setupcl.exe", "WerFault.exe", "wpbbin.exe", "PvsVmBoot.exe", "SophosNA.exe", "omnissa-ic-nga.exe", "icarus_rvrt.exe", "poqexec.exe")) or
   (process.parent.name:"wermgr.exe" and not process.name:("WerFaultSecure.exe", "wermgr.exe", "WerFault.exe") and
     not (process.name:"rundll32.exe" and process.command_line : "*WerConCpl.dll*LaunchErcApp*")) or
   (process.parent.name:"conhost.exe" and not process.name:("mscorsvw.exe", "wermgr.exe", "WerFault.exe", "WerFaultSecure.exe", "conhost.exe"))
  )

// Title: privilege_escalation_unusual_printspooler_childprocess.toml
// Source: detection-rules::rules/windows/privilege_escalation_unusual_printspooler_childprocess.toml
// Section: EQL Rule
// Rule Name: Unusual Print Spooler Child Process
// Author: Elastic
// Description:
// Detects unusual Print Spooler service (spoolsv.exe) child processes. This may indicate an attempt to exploit privilege
// escalation vulnerabilities related to the Printing Service on Windows.
// Integration: endpoint, windows, system, crowdstrike, sentinel_one_cloud_funnel, m365_defender
// Language: eql
// UUID: ee5300a7-7e31-4a72-a258-250abb8b3aa1
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
 process.parent.name : "spoolsv.exe" and process.command_line != null and
 (?process.Ext.token.integrity_level_name : "System" or ?winlog.event_data.IntegrityLevel : "System") and

 /* exclusions for FP control below */
 not process.name : ("splwow64.exe", "PDFCreator.exe", "acrodist.exe", "spoolsv.exe", "msiexec.exe", "route.exe", "WerFault.exe") and
 not process.command_line : "*\\WINDOWS\\system32\\spool\\DRIVERS*" and
 not (process.name : "net.exe" and process.command_line : ("*stop*", "*start*")) and
 not (process.name : ("cmd.exe", "powershell.exe") and process.command_line : ("*.spl*", "*\\program files*", "*route add*")) and
 not (process.name : "netsh.exe" and process.command_line : ("*add portopening*", "*rule name*")) and
 not (process.name : "regsvr32.exe" and process.command_line : "*PrintConfig.dll*") and
 not process.executable : (
    "?:\\Program Files (x86)\\CutePDF Writer\\CPWriter2.exe",
    "?:\\Program Files (x86)\\GPLGS\\gswin32c.exe",
    "?:\\Program Files (x86)\\Acro Software\\CutePDF Writer\\CPWSave.exe",
    "?:\\Program Files (x86)\\Acro Software\\CutePDF Writer\\CPWriter2.exe",
    "?:\\Program Files (x86)\\CutePDF Writer\\CPWSave.exe",
    "?:\\Program Files (x86)\\TSplus\\UniversalPrinter\\CPWriter2.exe",
    "?:\\Program Files\\Seagull\\Printer Drivers\\Packages\\*\\DriverEnvironmentSetup.exe",
    "?:\\Windows\\system32\\CNAB4RPD.EXE",

    /* Crowdstrike specific condition as it uses NT Object paths */
    "\\Device\\HarddiskVolume*\\Program Files (x86)\\CutePDF Writer\\CPWriter2.exe",
    "\\Device\\HarddiskVolume*\\Program Files (x86)\\GPLGS\\gswin32c.exe",
    "\\Device\\HarddiskVolume*\\Program Files (x86)\\Acro Software\\CutePDF Writer\\CPWSave.exe",
    "\\Device\\HarddiskVolume*\\Program Files (x86)\\Acro Software\\CutePDF Writer\\CPWriter2.exe",
    "\\Device\\HarddiskVolume*\\Program Files (x86)\\CutePDF Writer\\CPWSave.exe",
    "\\Device\\HarddiskVolume*\\Program Files (x86)\\TSplus\\UniversalPrinter\\CPWriter2.exe",
    "\\Device\\HarddiskVolume*\\Program Files\\Seagull\\Printer Drivers\\Packages\\*\\DriverEnvironmentSetup.exe",
    "\\Device\\HarddiskVolume*\\Windows\\system32\\CNAB4RPD.EXE"
 )

// Title: privilege_escalation_unusual_svchost_childproc_childless.toml
// Source: detection-rules::rules/windows/privilege_escalation_unusual_svchost_childproc_childless.toml
// Section: EQL Rule
// Rule Name: Unusual Service Host Child Process - Childless Service
// Author: Elastic
// Description:
// Identifies unusual child processes of Service Host (svchost.exe) that traditionally do not spawn any child processes.
// This may indicate a code injection or an equivalent form of exploitation.
// Integration: endpoint, windows, m365_defender, sentinel_one_cloud_funnel
// Language: eql
// UUID: 6a8ab9cc-4023-4d17-b5df-1a3e16882ce7
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.parent.name : "svchost.exe" and

  /* based on svchost service arguments -s svcname where the service is known to be childless */
  process.parent.args : (
    "WdiSystemHost", "LicenseManager", "StorSvc", "CDPSvc", "cdbhsvc", "BthAvctpSvc", "SstpSvc", "WdiServiceHost",
    "imgsvc", "TrkWks", "WpnService", "IKEEXT", "PolicyAgent", "CryptSvc", "netprofm", "ProfSvc", "StateRepository",
    "camsvc", "LanmanWorkstation", "NlaSvc", "EventLog", "hidserv", "DisplayEnhancementService", "ShellHWDetection",
    "AppHostSvc", "fhsvc", "CscService", "PushToInstall"
  ) and

  /* unknown FPs can be added here */
  not process.name : ("WerFault.exe", "WerFaultSecure.exe", "wermgr.exe") and
  not (process.executable : "?:\\Windows\\System32\\RelPost.exe" and process.parent.args : "WdiSystemHost") and
  not (
    process.name : "rundll32.exe" and
    process.args : "?:\\WINDOWS\\System32\\winethc.dll,ForceProxyDetectionOnNextRun" and
    process.parent.args : "WdiServiceHost"
  ) and
  not (
    process.executable : (
      "?:\\Program Files\\*",
      "?:\\Program Files (x86)\\*",
      "?:\\Windows\\System32\\Kodak\\kds_?????\\lib\\lexexe.exe"
    ) and process.parent.args : "imgsvc"
  )

// Title: privilege_escalation_via_ppid_spoofing.toml
// Source: detection-rules::rules/windows/privilege_escalation_via_ppid_spoofing.toml
// Section: EQL Rule
// Rule Name: Privileges Elevation via Parent Process PID Spoofing
// Author: Elastic
// Description:
// Identifies parent process spoofing used to create an elevated child process. Adversaries may spoof the parent process
// identifier (PPID) of a new process to evade process-monitoring defenses or to elevate privileges.
// Integration: endpoint
// Language: eql
// UUID: 26b01043-4f04-4d2f-882a-5a1d2e95751b
// Type: eql

/* This rule is compatible with Elastic Endpoint only */

process where host.os.type == "windows" and event.action == "start" and

 /* process creation via seclogon */
 process.parent.Ext.real.pid > 0 and process.parent.executable != null and

 /* PrivEsc to SYSTEM */
 user.id : "S-1-5-18"  and

 /* Common FPs - evasion via hollowing is possible, should be covered by code injection */
 not process.executable : ("?:\\Windows\\System32\\WerFault.exe",
                           "?:\\Windows\\SysWOW64\\WerFault.exe",
                           "?:\\Windows\\System32\\WerFaultSecure.exe",
                           "?:\\Windows\\SysWOW64\\WerFaultSecure.exe",
                           "?:\\Windows\\System32\\Wermgr.exe",
                           "?:\\Windows\\SysWOW64\\Wermgr.exe",
                           "?:\\Windows\\SoftwareDistribution\\Download\\Install\\securityhealthsetup.exe") and
 /* Logon Utilities */
 not (process.parent.executable : "?:\\Windows\\System32\\Utilman.exe" and
     process.executable : ("?:\\Windows\\System32\\osk.exe",
                           "?:\\Windows\\System32\\Narrator.exe",
                           "?:\\Windows\\System32\\Magnify.exe",
                           "?:\\Windows\\System32\\VoiceAccess.exe")) and

 not process.parent.executable : "?:\\Windows\\System32\\AtBroker.exe" and

 not (process.code_signature.subject_name in
           ("philandro Software GmbH", "Freedom Scientific Inc.", "TeamViewer Germany GmbH", "Projector.is, Inc.",
            "TeamViewer GmbH", "Cisco WebEx LLC", "Dell Inc") and process.code_signature.trusted == true) and

 /* AM_Delta_Patch Windows Update */
 not (process.executable : ("?:\\Windows\\System32\\MpSigStub.exe", "?:\\Windows\\SysWOW64\\MpSigStub.exe") and
      process.parent.executable : ("?:\\Windows\\System32\\wuauclt.exe",
                                   "?:\\Windows\\SysWOW64\\wuauclt.exe",
                                   "?:\\Windows\\UUS\\Packages\\Preview\\*\\wuaucltcore.exe",
                                   "?:\\Windows\\UUS\\amd64\\wuauclt.exe",
                                   "?:\\Windows\\UUS\\amd64\\wuaucltcore.exe",
                                   "?:\\ProgramData\\Microsoft\\Windows\\UUS\\*\\wuaucltcore.exe")) and

 /* Other third party SW */
 not process.parent.executable :
                   ("?:\\Program Files (x86)\\HEAT Software\\HEAT Remote\\HEATRemoteServer.exe",
                    "?:\\Program Files (x86)\\VisualCron\\VisualCronService.exe",
                    "?:\\Program Files\\BinaryDefense\\Vision\\Agent\\bds-vision-agent-app.exe",
                    "?:\\Program Files\\Tablet\\Wacom\\WacomHost.exe",
                    "?:\\Program Files (x86)\\LogMeIn\\x64\\LogMeIn.exe",
                    "?:\\Program Files (x86)\\EMC Captiva\\Captiva Cloud Runtime\\Emc.Captiva.WebCaptureRunner.exe",
                    "?:\\Program Files\\Freedom Scientific\\*.exe",
                    "?:\\Program Files (x86)\\Google\\Chrome Remote Desktop\\*\\remoting_host.exe",
                    "?:\\Program Files (x86)\\GoToAssist Remote Support Customer\\*\\g2ax_comm_customer.exe") and
 not (
    process.code_signature.trusted == true and process.code_signature.subject_name == "Netwrix Corporation" and
    process.name : ("adcrcpy.exe", "addumpcaller.exe") and process.parent.name : (
      "Netwrix.ADA.EventCollector.exe",
      "Netwrix.ADA.Analyzer.exe"
    )
 )

// Title: privilege_escalation_via_rogue_named_pipe.toml
// Source: detection-rules::rules/windows/privilege_escalation_via_rogue_named_pipe.toml
// Section: EQL Rule
// Rule Name: Privilege Escalation via Rogue Named Pipe Impersonation
// Author: Elastic
// Description:
// Identifies a privilege escalation attempt via rogue named pipe impersonation. An adversary may abuse this technique by
// masquerading as a known named pipe and manipulating a privileged process to connect to it.
// Integration: windows
// Language: eql
// UUID: 76ddb638-abf7-42d5-be22-4a70b0bf7241
// Type: eql

file where host.os.type == "windows" and
  event.provider == "Microsoft-Windows-Sysmon" and

  /* Named Pipe Creation */
  event.code == "17" and

  /* Sysmon truncates the "Pipe" keyword in normal named pipe creation events */
  file.name : "\\*\\Pipe\\*"

// Title: privilege_escalation_windows_service_via_unusual_client.toml
// Source: detection-rules::rules/windows/privilege_escalation_windows_service_via_unusual_client.toml
// Section: EQL Rule
// Rule Name: Windows Service Installed via an Unusual Client
// Author: Elastic
// Description:
// Identifies the creation of a Windows service by an unusual client process. Services may be created with administrator
// privileges but are executed under SYSTEM privileges, so an adversary may also use a service to escalate privileges from
// administrator to SYSTEM.
// Integration: system, windows
// Language: eql
// UUID: 55c2bf58-2a39-4c58-a384-c8b1978153c2
// Type: eql

configuration where host.os.type == "windows" and
  event.action == "service-installed" and
  (winlog.event_data.ClientProcessId == "0" or winlog.event_data.ParentProcessId == "0") and
  startswith~(user.domain, winlog.computer_name) and winlog.event_data.ServiceAccount == "LocalSystem" and 
  not winlog.event_data.ServiceFileName : (
    "?:\\Windows\\VeeamVssSupport\\VeeamGuestHelper.exe*",
    "?:\\Windows\\VeeamLogShipper\\VeeamLogShipper.exe",
    "%SystemRoot%\\system32\\Drivers\\Crowdstrike\\*-CsInstallerService.exe",
    "\"%windir%\\AdminArsenal\\PDQInventory-Scanner\\service-1\\PDQInventory-Scanner-1.exe\" ",
    "\"%windir%\\AdminArsenal\\PDQDeployRunner\\service-1\\PDQDeployRunner-1.exe\" ",
    "\"%windir%\\AdminArsenal\\PDQInventoryWakeCommand\\service-1\\PDQInventoryWakeCommand-1.exe\" ",
    "\"%SystemRoot%\\nsnetpush.exe\"",
    "\"C:\\WINDOWS\\ccmsetup\\ccmsetup.exe\" /runservice /ignoreskipupgrade /config:MobileClient.tcf",
    "\"?:\\SMS\\bin\\x64\\srvboot.exe\"",
    "%SystemRoot%\\pbpsdeploy.exe"
  )

// Title: collection_archive_data_zip_imageload.toml
// Source: detection-rules::rules_building_block/collection_archive_data_zip_imageload.toml
// Section: EQL Building Block
// Rule Name: Compression DLL Loaded by Unusual Process
// Author: Elastic
// Description:
// Identifies the image load of a compression DLL. Adversaries will often compress and encrypt data in preparation for
// exfiltration.
// Integration: endpoint
// Language: eql
// UUID: d197478e-39f0-4347-a22f-ba654718b148
// Type: eql

library where host.os.type == "windows" and event.action == "load" and
  dll.name : ("System.IO.Compression.FileSystem.ni.dll", "System.IO.Compression.ni.dll") and
  not 
  (
    (
      process.executable : (
        "?:\\Program Files\\*",
        "?:\\Program Files (x86)\\*",
        "?:\\Windows\\Microsoft.NET\\Framework*\\mscorsvw.exe",
        "?:\\Windows\\System32\\sdiagnhost.exe",
        "?:\\Windows\\System32\\inetsrv\\w3wp.exe",
        "?:\\Windows\\SysWOW64\\inetsrv\\w3wp.exe",
        "?:\\ProgramData\\Microsoft\\Windows Defender Advanced Threat Protection\\DataCollection\\*\\OpenHandleCollector.exe"
      ) and process.code_signature.trusted == true
    ) or
    (
      process.name : "NuGet.exe" and process.code_signature.trusted == true and user.id : ("S-1-5-18", "S-1-5-20")
    )
  )

// Title: collection_common_compressed_archived_file.toml
// Source: detection-rules::rules_building_block/collection_common_compressed_archived_file.toml
// Section: EQL Building Block
// Rule Name: File Compressed or Archived into Common Format by Unsigned Process
// Author: Elastic
// Description:
// Detects files being compressed or archived into common formats by unsigned processes. This is a common technique used to
// obfuscate files to evade detection or to staging data for exfiltration.
// Integration: endpoint
// Language: eql
// UUID: 79124edf-30a8-4d48-95c4-11522cad94b1
// Type: eql

file where host.os.type == "windows" and event.type in ("creation", "change") and
 process.executable != null and process.code_signature.trusted != true and
 file.Ext.header_bytes : (
                          /* compression formats */
                          "1F9D*",             /* tar zip, tar.z (Lempel-Ziv-Welch algorithm) */
                          "1FA0*",             /* tar zip, tar.z (LZH algorithm) */
                          "425A68*",           /* Bzip2 */
                          "524E4301*",         /* Rob Northen Compression */
                          "524E4302*",         /* Rob Northen Compression */
                          "4C5A4950*",         /* LZIP */
                          "504B0*",            /* ZIP */
                          "526172211A07*",     /* RAR compressed */
                          "44434D0150413330*", /* Windows Update Binary Delta Compression file */
                          "50413330*",         /* Windows Update Binary Delta Compression file */
                          "377ABCAF271C*",     /* 7-Zip */
                          "1F8B*",             /* GZIP */
                          "FD377A585A00*",     /* XZ, tar.xz */
                          "7801*",	           /* zlib: No Compression (no preset dictionary) */
                          "785E*",	           /* zlib: Best speed (no preset dictionary) */
                          "789C*",	           /* zlib: Default Compression (no preset dictionary) */
                          "78DA*", 	           /* zlib: Best Compression (no preset dictionary) */
                          "7820*",	           /* zlib: No Compression (with preset dictionary) */
                          "787D*",	           /* zlib: Best speed (with preset dictionary) */
                          "78BB*",	           /* zlib: Default Compression (with preset dictionary) */
                          "78F9*",	           /* zlib: Best Compression (with preset dictionary) */
                          "62767832*",         /* LZFSE */
                          "28B52FFD*",         /* Zstandard, zst */
                          "5253564B44415441*", /* QuickZip rs compressed archive */
                          "2A2A4143452A2A*",   /* ACE */

                          /* archive formats */
                          "2D686C302D*",       /* lzh */
                          "2D686C352D*",       /* lzh */
                          "303730373037*",     /* cpio */
                          "78617221*",         /* xar */
                          "4F4152*",           /* oar */
                          "49536328*"          /* cab archive */
 )

// Title: collection_files_staged_in_recycle_bin_root.toml
// Source: detection-rules::rules_building_block/collection_files_staged_in_recycle_bin_root.toml
// Section: EQL Building Block
// Rule Name: File Staged in Root Folder of Recycle Bin
// Author: Elastic
// Description:
// Identifies files written to the root of the Recycle Bin folder instead of subdirectories. Adversaries may place files in
// the root of the Recycle Bin in preparation for exfiltration or to evade defenses.
// Integration: endpoint, windows
// Language: eql
// UUID: 57bccf1d-daf5-4e1a-9049-ff79b5254704
// Type: eql

file where host.os.type == "windows" and event.type == "creation" and
  file.path : "?:\\$RECYCLE.BIN\\*" and
  not file.path : "?:\\$RECYCLE.BIN\\*\\*" and
  not file.name : "desktop.ini"

// Title: collection_outlook_email_archive.toml
// Source: detection-rules::rules_building_block/collection_outlook_email_archive.toml
// Section: EQL Building Block
// Rule Name: Accessing Outlook Data Files
// Author: Elastic
// Description:
// Identifies commands containing references to Outlook data files extensions, which can potentially indicate the search,
// access, or modification of these files.
// Integration: endpoint, windows, system
// Language: eql
// UUID: 2e311539-cd88-4a85-a301-04f38795007c
// Type: eql

process where host.os.type == "windows" and event.type == "start" and process.args : ("*.ost", "*.pst") and
  not process.name : "outlook.exe" and
  not (
        process.name : "rundll32.exe" and
        process.args : "*davclnt.dll,DavSetCookie*"
  )

// Title: command_and_control_bitsadmin_activity.toml
// Source: detection-rules::rules_building_block/command_and_control_bitsadmin_activity.toml
// Section: EQL Building Block
// Rule Name: Bitsadmin Activity
// Author: Elastic
// Description:
// Windows Background Intelligent Transfer Service (BITS) is a low-bandwidth, asynchronous file transfer mechanism.
// Adversaries may abuse BITS to persist, download, execute, and even clean up after running malicious code.
// Integration: endpoint, windows, system
// Language: eql
// UUID: 8eec4df1-4b4b-4502-b6c3-c788714604c9
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  (
   (process.name : "bitsadmin.exe" and process.args : (
        "*Transfer*", "*Create*", "AddFile", "*SetNotifyFlags*", "*SetNotifyCmdLine*",
        "*SetMinRetryDelay*", "*SetCustomHeaders*", "*Resume*")
   ) or
   (process.name : "powershell.exe" and process.args : (
        "*Start-BitsTransfer*", "*Add-BitsFile*",
        "*Resume-BitsTransfer*", "*Set-BitsTransfer*", "*BITS.Manager*")
   )
  )

// Title: command_and_control_certutil_network_connection.toml
// Source: detection-rules::rules_building_block/command_and_control_certutil_network_connection.toml
// Section: EQL Building Block
// Rule Name: Network Connection via Certutil
// Author: Elastic
// Description:
// Identifies certutil.exe making a network connection. Adversaries could abuse certutil.exe to download a certificate, or
// malware, from a remote URL.
// Integration: endpoint, windows
// Language: eql
// UUID: 3838e0e3-1850-4850-a411-2e8c5ba40ba8
// Type: eql

network where host.os.type == "windows" and process.name : "certutil.exe" and
  not cidrmatch(destination.ip, "10.0.0.0/8", "127.0.0.0/8", "169.254.0.0/16", "172.16.0.0/12", "192.0.0.0/24",
                                "192.0.0.0/29", "192.0.0.8/32", "192.0.0.9/32", "192.0.0.10/32", "192.0.0.170/32",
                                "192.0.0.171/32", "192.0.2.0/24", "192.31.196.0/24", "192.52.193.0/24",
                                "192.168.0.0/16", "192.88.99.0/24", "224.0.0.0/4", "100.64.0.0/10", "192.175.48.0/24",
                                "198.18.0.0/15", "198.51.100.0/24", "203.0.113.0/24", "240.0.0.0/4", "::1",
                                "FE80::/10", "FF00::/8") and
  not dns.question.name in ("localhost", "*.digicert.com", "ctldl.windowsupdate.com")

// Title: command_and_control_dns_to_commonly_abused_webservices.toml
// Source: detection-rules::rules_building_block/command_and_control_dns_to_commonly_abused_webservices.toml
// Section: EQL Building Block
// Rule Name: DNS to Commonly Abused Web Services
// Author: Elastic
// Description:
// Adversaries may implement command and control (C2) communications that use common web services to hide their activity.
// This attack technique is typically targeted at an organization and uses web services common to the victim network, which
// allows the adversary to blend into legitimate traffic activity. These popular services are typically targeted since they
// have most likely been used before compromise, which helps malicious traffic blend in.
// Integration: endpoint
// Language: eql
// UUID: 8248323e-f888-4134-a26f-37a6362f7231
// Type: eql

network where host.os.type == "linux" and dns.question.name != null and process.name != null and
dns.question.name like~ (
  /* Google services */
  "drive.google.com", "docs.google.com", "script.google.com", "script.googleusercontent.com",
  "*googleapis.com", "calendar.app.google*",

  /* Dropbox */
  "api.dropboxapi.com", "content.dropboxapi.com", "*dl.dropboxusercontent.com",

  /* Microsoft / OneDrive / SharePoint */
  "api.onedrive.com", "*.onedrive.org", "onedrive.live.com", "*files.1drv.com", "graph.microsoft.com",
  "*.sharepoint.com", "login.live.com", "g.live.com",

  /* Slack */
  "*slack.com", "slack-redir.net", "slack-files.com",

  /* Discord */
  "discord.com", "cdn.discordapp.com", "discordapp.com",

  /* Telegram */
  "api.telegram.org", "t.me",

  /* Azure / Cloud storage */
  "apis.azureedge.net", "*.blob.core.windows.net", "*.blob.storage.azure.net", "*azurewebsites.net",

  /* GitHub / Dev hosting */
  "api.github.com", "raw.githubusercontent.*", "gist.githubusercontent.com", "rawcdn.githack.*",
  "*.notabug.org",

  /* Developer tunnels / reverse proxies */
  "*.devtunnels.ms", "*global.rel.tunnels.api.visualstudio.com", "*.ngrok.io", "*.ngrok-free.app",
  "*.portmap.*", "serveo.net", "*localtunnel.me", "*pagekite.me", "*.trycloudflare.com",

  /* AWS */
  "*s3.amazonaws.com",

  /* Paste services */
  "pastebin.*", "paste4btc.com", "paste.ee", "ghostbin.com", "paste.nrecom.net", "zerobin.net",
  "controlc.com", "pastecode.dev", "paste.rs", "hastebin.com", "dpaste.org", "dpaste.com", "0bin.net",
  "paste.ofcode.org", "paste.wakas.org", "nopaste.net",

  /* File sharing / exfiltration */
  "filebin.net", "file.io", "transfer.sh", "*.gofile.io", "workupload.com", "*upload.ee", "*anonfiles.com",
  "api.anonfile.com", "*bayfiles.com", "*bublup.com", "*dropfiles.org", "*dropmefiles.com", "*easyupload.io",
  "*filetransfer.io", "*sendspace.com", "*share.riseup.net", "*temp.sh", "*tempsend.com", "*ufile.io",
  "*send.now", "*send.cm", "*sendit.sh", "*pixeldrain.com", "*megaupload.com", "*mediafire.com",
  "*bashupload.com", "*bujang.online", "mediafire.zip", "*.4shared.com", "filecloud.me", "*.pcloud.com",
  "*catbox.moe",

  /* CDN / hosting / generic file infra */
  "*cdnmegafiles.com", "www.uplooder.net", "?.top4top.io", "top4top.io", "*.b-cdn.net", "cdn*.space",
  "i.ibb.co", "i.imgur.com",

  /* Webhooks / testing / bins */
  "webhook.site", "run.mocky.io", "mockbin.org", "requestbin.net",

  /* Public hosting / misc infra */
  "*.publicvm.com", "*.blogspot.com", "*infinityfreeapp.com", "free.keep.sh", "*.aternos.me",
  "*hosting-profi.de",

  /* IP / network utilities */
  "api.mylnikov.org", "ipbase.com", "*.getmyip.com", "myexternalip.com", "*.geojs.io",
  "*api.2ip.ua", "*api.db-ip.com", "*api.ip.sb", "*api.ipify.org", "*api.myip.com",
  "*api.npoint.io", "*api64.ipify.org", "*bot.whatismyipaddress.com", "*checkip.amazonaws.com",
  "*checkip.dyndns.org", "*curlmyip.com", "*eth0.me", "*freegeoip.app", "*freegeoip.net",
  "*freeipapi.com", "*geoiptool.com", "*geolocation-db.com", "*httpbin.org",
  "*icanhazip.com", "*ident.me", "*ifcfg.me", "*ifconfig.me", "*inet-ip.info", "*ip-api.com",
  "*ip.appspot.com", "*ip.tyk.nu", "*ip4.seeip.org", "*ipecho.net", "*ipinfo.io", "*iplogger.*",
  "*ipof.in", "*ipwho.is", "*ipwhois.app", "*ipv4.icanhazip.com", "*ipv6.icanhazip.com",
  "*myip.dnsomatic.com", "*myip.ipip.net", "*myip.opendns.com", "*portmap.io", "*wgetip.com",
  "*whatismyip.akamai.com", "*wtfismyip.com",

  /* Social / platforms */
  "mbasic.facebook.com", "*.zulipchat.com", "stackoverflow.com",

  /* Package hosting */
  "files.pythonhosted.org",

  /* Databases / backend platforms */
