// Title: command_and_control_ollama_model_download_untrusted_source.toml
// Source: detection-rules::rules_building_block/command_and_control_ollama_model_download_untrusted_source.toml
// Section: EQL Building Block
// Rule Name: Ollama DNS Query to Untrusted Domain
// Author: Elastic
// Description:
// Detects Ollama DNS queries to domains outside official infrastructure. Adversaries can redirect Ollama to pull models
// from attacker-controlled servers via OLLAMA_HOST or custom manifests. Malicious models may contain backdoors, exploit
// parsing vulnerabilities like CVE-2025-1975, or poison inference outputs.
// Integration: endpoint
// Language: eql
// UUID: e9a3b2c1-d4f5-6789-0abc-def123456789
// Type: eql

network where event.action == "lookup_requested" and
  process.name in ("ollama", "ollama.exe") and
  dns.question.name != null and
  not dns.question.name : (
    "ollama.ai", "*.ollama.ai", "ollama.com", "*.ollama.com",
    "github.com", "*.github.com", "*.githubusercontent.com",
    "*.r2.cloudflarestorage.com", "*.cloudflare.com", "*.cloudflarestorage.com",
    "localhost", "*.local", "*.internal", "*.localdomain"
  )

// Title: credential_access_mdmp_file_creation.toml
// Source: detection-rules::rules_building_block/credential_access_mdmp_file_creation.toml
// Section: EQL Building Block
// Rule Name: Potential Credential Access via Memory Dump File Creation
// Author: Elastic
// Description:
// Identifies the creation or modification of a medium size memory dump file which can indicate an attempt to access
// credentials from a process memory.
// Integration: endpoint
// Language: eql
// UUID: e707a7be-cc52-41ac-8ab3-d34b38c20005
// Type: eql

file where host.os.type == "windows" and event.type == "creation" and

  /* MDMP header */
  file.Ext.header_bytes : "4d444d50*" and file.size >= 30000 and
  not

  (
    (
      process.name : "System" or
      process.executable : (
        "?:\\Windows\\System32\\WerFault.exe",
        "?:\\Windows\\SysWOW64\\WerFault.exe",
        "?:\\Windows\\System32\\Wermgr.exe",
        "?:\\Windows\\SysWOW64\\Wermgr.exe",
        "?:\\Windows\\System32\\WerFaultSecure.exe",
        "?:\\Windows\\SysWOW64\\WerFaultSecure.exe",
        "?:\\Windows\\System32\\WUDFHost.exe",
        "C:\\Windows\\System32\\rdrleakdiag.exe",
        "?:\\Windows\\System32\\Taskmgr.exe",
        "?:\\Windows\\SysWOW64\\Taskmgr.exe",
        "?:\\Program Files\\*.exe",
        "?:\\Program Files (x86)\\*.exe",
        "?:\\Windows\\SystemApps\\*.exe",
        "?:\\Users\\*\\AppData\\Roaming\\Zoom\\bin\\zCrashReport64.exe",
        "?:\\Windows\\CCM\\ccmdump.exe",
        "?:\\$WINDOWS.~BT\\Sources\\SetupHost.exe"
      ) and process.code_signature.trusted == true
    ) or
    (
      file.path : (
        "?:\\ProgramData\\Microsoft\\Windows\\WER\\*",
        "?:\\ProgramData\\Microsoft\\WDF\\*",
        "?:\\ProgramData\\Alteryx\\ErrorLogs\\*",
        "?:\\ProgramData\\Goodix\\*",
        "?:\\Windows\\system32\\config\\systemprofile\\AppData\\Local\\CrashDumps\\*",
        "?:\\Users\\*\\AppData\\Roaming\\Zoom\\logs\\zoomcrash*",
        "?:\\Users\\*\\AppData\\*\\Crashpad\\*",
        "?:\\Users\\*\\AppData\\*\\crashpaddb\\*",
        "?:\\Users\\*\\AppData\\*\\HungReports\\*",
        "?:\\Users\\*\\AppData\\*\\CrashDumps\\*",
        "?:\\Users\\*\\AppData\\*\\NativeCrashReporting\\*",
        "?:\\Program Files (x86)\\*\\Crashpad\\*",
        "?:\\Program Files\\*\\Crashpad\\*"
      ) and (process.code_signature.trusted == true or process.executable == null)
    )
  )

// Title: credential_access_mdmp_file_unusual_extension.toml
// Source: detection-rules::rules_building_block/credential_access_mdmp_file_unusual_extension.toml
// Section: EQL Building Block
// Rule Name: Memory Dump File with Unusual Extension
// Author: Elastic
// Description:
// Identifies the creation of a memory dump file with an unusual extension, which can indicate an attempt to disguise a
// memory dump as another file type to bypass security defenses.
// Integration: endpoint
// Language: eql
// UUID: c0b9dc99-c696-4779-b086-0d37dc2b3778
// Type: eql

file where host.os.type == "windows" and event.type == "creation" and

  /* MDMP header */
  file.Ext.header_bytes : "4d444d50*" and
  not file.extension : ("dmp", "mdmp", "hdmp", "edmp", "full", "tdref", "cg", "tmp", "dat") and
  not 
  (
    process.executable : "?:\\Program Files\\Endgame\\esensor.exe" and
    process.code_signature.trusted == true and length(file.extension) == 0
  ) and
  not
  (
    process.name : "System" and file.extension : "tmpscan"
  )

// Title: credential_access_win_private_key_access.toml
// Source: detection-rules::rules_building_block/credential_access_win_private_key_access.toml
// Section: EQL Building Block
// Rule Name: Attempted Private Key Access
// Author: Elastic
// Description:
// Attackers may try to access private keys, e.g. ssh, in order to gain further authenticated access to the environment.
// Integration: endpoint, windows, system
// Language: eql
// UUID: c55badd3-3e61-4292-836f-56209dc8a601
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.command_line : ("*.pem *", "*.pem", "*.id_rsa*") and
  not process.args : (
        "--rootcert",
        "--cert",
        "--crlfile"
  ) and
  not process.command_line : (
        "*--cacert*",
        "*--ssl-cert*",
        "*--tls-cert*",
        "*--tls_server_certs*"
  ) and
  not process.executable : (
    "?:\\ProgramData\\Logishrd\\LogiOptions\\Software\\*\\LogiLuUpdater.exe",
    "?:\\Program Files\\Elastic\\Agent\\data\\*\\osqueryd.exe",
    "?:\\Program Files\\Git\\cmd\\git.exe",
    "?:\\Program Files\\Git\\mingw64\\bin\\git.exe",
    "?:\\Program Files\\Guardicore\\gc-controller.exe",
    "?:\\Program Files\\Guardicore\\gc-deception-agent.exe",
    "?:\\Program Files\\Guardicore\\gc-detection-agent.exe",
    "?:\\Program Files\\Guardicore\\gc-enforcement-agent.exe",
    "?:\\Program Files\\Guardicore\\gc-guest-agent.exe",
    "?:\\Program Files\\Logi\\LogiBolt\\LogiBoltUpdater.exe",
    "?:\\Program Files (x86)\\Schneider Electric EcoStruxure\\Building Operation 5.0\\Device Administrator\\Python\\python.exe",
    "?:\\Program Files\\Splunk\\bin\\openssl.exe",
    "?:\\Program Files\\SplunkUniversalForwarder\\bin\\openssl.exe",
    "?:\\Users\\*\\AppData\\Local\\Logi\\LogiBolt\\LogiBoltUpdater.exe",
    "?:\\Windows\\system32\\icacls.exe",
    "?:\\Windows\\System32\\OpenSSH\\*"
  )

// Title: defense_evasion_cmd_copy_binary_contents.toml
// Source: detection-rules::rules_building_block/defense_evasion_cmd_copy_binary_contents.toml
// Section: EQL Building Block
// Rule Name: Binary Content Copy via Cmd.exe
// Author: Elastic
// Description:
// Attackers may abuse cmd.exe commands to reassemble binary fragments into a malicious payload.
// Integration: endpoint, windows, system
// Language: eql
// UUID: 53dedd83-1be7-430f-8026-363256395c8b
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.name : "cmd.exe" and (
    (process.args : "type" and process.args : (">", ">>")) or
    (process.args : "copy" and process.args : "/b"))

// Title: defense_evasion_cmstp_execution.toml
// Source: detection-rules::rules_building_block/defense_evasion_cmstp_execution.toml
// Section: EQL Building Block
// Rule Name: Potential Defense Evasion via CMSTP.exe
// Author: Elastic
// Description:
// The Microsoft Connection Manager Profile Installer (CMSTP.exe) is a command-line program to install Connection Manager
// service profiles, which accept installation information file (INF) files. Adversaries may abuse CMSTP to proxy the
// execution of malicious code by supplying INF files that contain malicious commands.
// Integration: endpoint, windows, system
// Language: eql
// UUID: bd3d058d-5405-4cee-b890-337f09366ba2
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.name : "cmstp.exe" and process.args == "/s"

// Title: defense_evasion_collection_masquerading_unusual_archive_file_extension.toml
// Source: detection-rules::rules_building_block/defense_evasion_collection_masquerading_unusual_archive_file_extension.toml
// Section: EQL Building Block
// Rule Name: Archive File with Unusual Extension
// Author: Elastic
// Description:
// Identifies the creation of an archive file with an unusual extension. Attackers may attempt to evade detection by
// masquerading files using the file extension values used by image, audio, or document file types.
// Integration: endpoint
// Language: eql
// UUID: cffbaf47-9391-4e09-a83c-1f27d7474826
// Type: eql

file where host.os.type == "windows" and event.action != "deletion" and

  /* common archive file headers - Rar, 7z, GZIP, MSCF, XZ, ZIP */
  file.Ext.header_bytes : ("52617221*", "377ABCAF271C*", "1F8B*", "4d534346*", "FD377A585A00*", "504B0304*", "504B0708*") and

  (
    /* common image file extensions */
    file.extension : ("jpg", "jpeg", "emf", "tiff", "gif", "png", "bmp", "ico", "fpx", "eps", "inf") or

    /* common audio and video file extensions */
    file.extension : ("mp3", "wav", "avi", "mpeg", "flv", "wma", "wmv", "mov", "mp4", "3gp") or

    /* common document file extensions */
    (file.extension : ("doc", "docx", "rtf", "ppt", "pptx", "xls", "xlsx") and

    /* exclude ZIP file header values for OPENXML documents */
    not file.Ext.header_bytes : ("504B0304*", "504B0708*"))
  ) and

  not (process.executable : "?:\\Windows\\System32\\inetsrv\\w3wp.exe" and file.path : "?:\\inetpub\\temp\\IIS Temporary Compressed Files\\*")

// Title: defense_evasion_dotnet_clickonce_dfsvc_netcon.toml
// Source: detection-rules::rules_building_block/defense_evasion_dotnet_clickonce_dfsvc_netcon.toml
// Section: EQL Building Block
// Rule Name: Execution via Microsoft DotNet ClickOnce Host
// Author: Elastic
// Description:
// Identifies the execution of DotNet ClickOnce installer via Dfsvc.exe trampoline. Adversaries may take advantage of
// ClickOnce to proxy execution of malicious payloads via trusted Microsoft processes.
// Integration: endpoint
// Language: eql
// UUID: 5297b7f1-bccd-4611-93fa-ea342a01ff84
// Type: eql

sequence by user.id with maxspan=5s
 [process where host.os.type == "windows" and event.action == "start" and
  process.name : "rundll32.exe" and process.command_line : ("*dfshim*ShOpenVerbApplication*", "*dfshim*#*")]
 [network where host.os.type == "windows" and process.name : "dfsvc.exe"]

// Title: defense_evasion_download_susp_extension.toml
// Source: detection-rules::rules_building_block/defense_evasion_download_susp_extension.toml
// Section: EQL Building Block
// Rule Name: File with Suspicious Extension Downloaded
// Author: Elastic
// Description:
// Identifies unusual files downloaded from outside the local network that have the potential to be abused for code
// execution.
// Integration: endpoint
// Language: eql
// UUID: 8d366588-cbd6-43ba-95b4-0971c3f906e5
// Type: eql

file where host.os.type == "windows" and event.type == "creation" and
  file.extension : (
    "appinstaller", "application", "appx", "appxbundle", "cpl", "diagcab", "diagpkg", "diagcfg", "manifest",
    "msix", "pif", "search-ms", "searchConnector-ms", "settingcontent-ms", "symlink", "theme", "themepack" 
  ) and file.Ext.windows.zone_identifier > 1 and
  not
  (
    (
      file.extension : "msix" and 
      file.path : (
        "?:\\Users\\*\\AppData\\Local\\Temp\\WinGet\\Microsoft.Winget.Source*",
        "?:\\Windows\\system32\\config\\systemprofile\\AppData\\Local\\Microsoft\\WinGet\\State\\defaultState\\Microsoft.PreIndexed.Package\\Microsoft.Winget.Source*"
      )
    ) or
    (
      process.name : "Teams.exe" and process.code_signature.trusted == true and
      file.extension : "msix" and 
      file.path : "?:\\Users\\*\\AppData\\Roaming\\Microsoft\\Teams\\tmp\\*"
    )
  )

// Title: defense_evasion_execution_via_visualstudio_prebuildevent.toml
// Source: detection-rules::rules_building_block/defense_evasion_execution_via_visualstudio_prebuildevent.toml
// Section: EQL Building Block
// Rule Name: Execution via MS VisualStudio Pre/Post Build Events
// Author: Elastic
// Description:
// Identifies the execution of a command via Microsoft Visual Studio Pre or Post build events. Adversaries may backdoor a
// trusted visual studio project to execute a malicious command during the project build process.
// Integration: endpoint
// Language: eql
// UUID: fec7ccb7-6ed9-4f98-93ab-d6b366b063a0
// Type: eql

sequence with maxspan=1m
  [process where host.os.type == "windows" and event.action == "start" and
   process.name : "cmd.exe" and process.parent.name : "MSBuild.exe" and
   process.args : "?:\\Users\\*\\AppData\\Local\\Temp\\tmp*.exec.cmd"] by process.entity_id
  [process where host.os.type == "windows" and event.action == "start" and
    process.name : (
      "cmd.exe", "powershell.exe",
      "MSHTA.EXE", "CertUtil.exe",
      "CertReq.exe", "rundll32.exe",
      "regsvr32.exe", "MSbuild.exe",
      "cscript.exe", "wscript.exe",
      "installutil.exe"
    ) and
    not 
    (
      process.name : ("cmd.exe", "powershell.exe") and
      process.args : (
        "*\\vcpkg\\scripts\\buildsystems\\msbuild\\applocal.ps1",
        "HKLM\\SOFTWARE\\Microsoft\\VisualStudio\\SxS\\VS?",
        "process.versions.node*",
        "?:\\Program Files\\nodejs\\node.exe",
        "HKEY_LOCAL_MACHINE\\SOFTWARE\\Microsoft\\MSBuild\\ToolsVersions\\*",
        "*Get-ChildItem*Tipasplus.css*",
        "Build\\GenerateResourceScripts.ps1",
        "Shared\\Common\\..\\..\\BuildTools\\ConfigBuilder.ps1\"",
        "?:\\Projets\\*\\PostBuild\\MediaCache.ps1"
      )
    ) and
    not process.executable : "?:\\Program Files*\\Microsoft Visual Studio\\*\\MSBuild.exe" and
    not (process.name : "cmd.exe" and
         process.command_line :
                  ("*vswhere.exe -property catalog_productSemanticVersion*",
                   "*git log --pretty=format*", "*\\.nuget\\packages\\vswhere\\*",
                   "*Common\\..\\..\\BuildTools\\*"))
  ] by process.parent.entity_id

// Title: defense_evasion_file_permission_modification.toml
// Source: detection-rules::rules_building_block/defense_evasion_file_permission_modification.toml
// Section: EQL Building Block
// Rule Name: File and Directory Permissions Modification
// Author: Elastic
// Description:
// Identifies the change of permissions/ownership of files/folders through built-in Windows utilities. Threat actors may
// require permission modification of files/folders to change, modify or delete them.
// Integration: endpoint
// Language: eql
// UUID: bc9e4f5a-e263-4213-a2ac-1edf9b417ada
// Type: eql

process where event.type == "start" and host.os.type == "windows" and
(
  ((process.name: "icacls.exe" or process.pe.original_file_name == "iCACLS.EXE") and process.args: ("*:F", "/reset", "/setowner", "*grant*")) or
  ((process.name: "cacls.exe" or process.pe.original_file_name == "CACLS.EXE") and process.args: ("/g", "*:f")) or
  ((process.name: "takeown.exe" or process.pe.original_file_name == "takeown.exe") and process.args: ("/F")) or
  ((process.name: "attrib.exe" or process.pe.original_file_name== "ATTRIB.EXE") and process.args: "-r")
) and not user.id : "S-1-5-18" and
not (
  process.args : ("C:\\ProgramData\\Lenovo\\*", "C:\\ProgramData\\Adobe\\*", "C:\\ProgramData\\ASUS\\ASUS*")
)

// Title: defense_evasion_generic_deletion.toml
// Source: detection-rules::rules_building_block/defense_evasion_generic_deletion.toml
// Section: EQL Building Block
// Rule Name: File or Directory Deletion Command
// Author: Elastic
// Description:
// This rule identifies the execution of commands that can be used to delete files and directories. Adversaries may delete
// files and directories on a host system, such as logs, browser history, or malware.
// Integration: endpoint
// Language: eql
// UUID: 5919988c-29e1-4908-83aa-1f087a838f63
// Type: eql

process where host.os.type == "windows" and event.type == "start" and 
(
  ((process.name : "rundll32.exe" or ?process.pe.original_file_name : "RUNDLL32.EXE") and process.args : "*InetCpl.cpl,Clear*") or 
  ((process.name : "reg.exe" or ?process.pe.original_file_name : "reg.exe") and process.args : "delete") or 
  (
    (process.name : "cmd.exe" or ?process.pe.original_file_name : "Cmd.Exe") and
    process.args : ("*rmdir*", "*rm *", "rm", "*del *", "del", "*erase *", "erase") and
    not process.args : (
          "*\\AppData\\Local\\Microsoft\\OneDrive\\*",
          "*\\AppData\\Local\\Temp\\DockerDesktop\\*",
          "*\\AppData\\Local\\Temp\\Report.*",
          "*\\AppData\\Local\\Temp\\*.PackageExtraction"
    )
  ) or
  ((process.name : "powershell.exe" or ?process.pe.original_file_name : "PowerShell.EXE") and
    process.args : ("*rmdir", "rm", "rd", "*Remove-Item*", "del", "*]::Delete(*"))
) and not user.id : "S-1-5-18"

// Title: defense_evasion_indirect_command_exec_pcalua_forfiles.toml
// Source: detection-rules::rules_building_block/defense_evasion_indirect_command_exec_pcalua_forfiles.toml
// Section: EQL Building Block
// Rule Name: Indirect Command Execution via Forfiles/Pcalua
// Author: Elastic
// Description:
// Identifies indirect command execution via Program Compatibility Assistant (pcalua.exe) or forfiles.exe.
// Integration: endpoint, windows, system
// Language: eql
// UUID: 98843d35-645e-4e66-9d6a-5049acd96ce1
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.parent.name : ("pcalua.exe", "forfiles.exe")

// Title: defense_evasion_injection_from_msoffice.toml
// Source: detection-rules::rules_building_block/defense_evasion_injection_from_msoffice.toml
// Section: EQL Building Block
// Rule Name: Potential Process Injection from Malicious Document
// Author: Elastic
// Description:
// Identifies child processes of frequently targeted Microsoft Office applications (Word, PowerPoint, Excel) with unusual
// process arguments and path. This behavior is often observed during exploitation of Office applications or from documents
// with malicious macros.
// Integration: endpoint
// Language: eql
// UUID: 1c5a04ae-d034-41bf-b0d8-96439b5cc774
// Type: eql

process where host.os.type == "windows" and event.action == "start" and
  process.parent.name : ("excel.exe", "powerpnt.exe", "winword.exe") and
  process.args_count == 1 and
  process.executable : (
    "?:\\Windows\\SysWOW64\\*.exe", "?:\\Windows\\system32\\*.exe"
  ) and
  not (process.executable : "?:\\Windows\\System32\\spool\\drivers\\x64\\*" and
       process.code_signature.trusted == true and not process.code_signature.subject_name : "Microsoft *") and
  not process.executable : (
    "?:\\Windows\\Sys*\\Taskmgr.exe",
    "?:\\Windows\\Sys*\\ctfmon.exe",
    "?:\\Windows\\System32\\notepad.exe")

// Title: defense_evasion_installutil_command_activity.toml
// Source: detection-rules::rules_building_block/defense_evasion_installutil_command_activity.toml
// Section: EQL Building Block
// Rule Name: InstallUtil Activity
// Author: Elastic
// Description:
// InstallUtil is a command-line utility that allows for installation and uninstallation of resources by executing specific
// installer components specified in .NET binaries. Adversaries may use InstallUtil to proxy the execution of code through
// a trusted Windows utility.
// Integration: endpoint, windows, system
// Language: eql
// UUID: 90babaa8-5216-4568-992d-d4a01a105d98
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.name : "installutil.exe" and not user.id : "S-1-5-18"

// Title: defense_evasion_invalid_codesign_imageload.toml
// Source: detection-rules::rules_building_block/defense_evasion_invalid_codesign_imageload.toml
// Section: EQL Building Block
// Rule Name: Image Loaded with Invalid Signature
// Author: Elastic
// Description:
// Identifies binaries that are loaded and with an invalid code signature. This may indicate an attempt to masquerade as a
// signed binary.
// Integration: endpoint
// Language: eql
// UUID: fd9484f2-1c56-44ae-8b28-dc1354e3a0e8
// Type: eql

library where host.os.type == "windows" and event.action == "load" and
  dll.code_signature.status : ("errorUntrustedRoot", "errorBadDigest", "errorUntrustedRoot") and
  (dll.Ext.relative_file_creation_time <= 500 or dll.Ext.relative_file_name_modify_time <= 500) and
  not startswith~(dll.name, process.name) and
  not dll.path : (
    "?:\\Windows\\System32\\DriverStore\\FileRepository\\*"
  )

// Title: defense_evasion_masquerading_browsers.toml
// Source: detection-rules::rules_building_block/defense_evasion_masquerading_browsers.toml
// Section: EQL Building Block
// Rule Name: Potential Masquerading as Browser Process
// Author: Elastic
// Description:
// Identifies suspicious instances of browser processes, such as unsigned or signed with unusual certificates, that can
// indicate an attempt to conceal malicious activity, bypass security features such as allowlists, or trick users into
// executing malware.
// Integration: endpoint
// Language: eql
// UUID: 5b9eb30f-87d6-45f4-9289-2bf2024f0376
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  (
    /* Chrome Related Processes */
    (
      process.name : (
        "chrome.exe", "GoogleUpdate.exe", "GoogleCrashHandler64.exe", "GoogleCrashHandler.exe",
        "GoogleUpdateComRegisterShell64.exe", "GoogleUpdateSetup.exe", "GoogleUpdateOnDemand.exe",
        "chrome_proxy.exe", "remote_assistance_host.exe", "remoting_native_messaging_host.exe",
        "GoogleUpdateBroker.exe"
      ) and
      not (process.code_signature.subject_name in ("Google LLC", "Google Inc") and process.code_signature.trusted == true) and
      not (
        process.executable : (
          "?:\\Program Files\\HP\\Sure Click\\servers\\chrome.exe",
          "?:\\Program Files\\HP\\Sure Click\\*\\servers\\chrome.exe"
        ) and
        process.code_signature.subject_name == "Bromium, Inc." and process.code_signature.trusted == true
      ) and
      not (
        process.executable : "?:\\Program Files\\dynatrace\\synthetic\\Chrome-bin\\chrome.exe" and
        process.code_signature.subject_name == "Dynatrace LLC" and process.code_signature.trusted == true
      ) and
      not (
        process.executable : "?:\\Users\\*\\Desktop\\CentBrowser\\chrome.exe" and
        process.code_signature.subject_name == "MV INFORMATICA NORDESTE LTDA" and process.code_signature.trusted == true
      ) and
      not (
        process.executable : (
          "?:\\Users\\*\\AppData\\Local\\ms-playwright\\chromium-*\\chrome-win\\chrome.exe",
          "?:\\Users\\*\\AppData\\Local\\Programs\\synthetics-recorder\\resources\\local-browsers\\chromium-*\\chrome-win\\chrome.exe",
          "*\\node_modules\\puppeteer\\*\\win64-*\\chrome-win\\chrome.exe",
          "?:\\Program Files (x86)\\Invicti Professional Edition\\chromium\\chrome.exe",
          "?:\\Program Files\\End2End, Inc\\ARMS Html Engine\\chrome.exe",
          "?:\\Users\\*\\AppData\\Local\\*BurpSuitePro\\burpbrowser\\*\\chrome.exe",
          "?:\\Users\\*\\AppData\\Roaming\\*BurpSuite\\burpbrowser\\*\\chrome.exe",
          "?:\\Gradient\\Connector.Service\\runtimes\\win-x64\\native\\chrome.exe",
          "?:\\Program Files (x86)\\Netsparker Enterprise Agent-?\\chromium\\chrome.exe"
        ) and process.args: (
                "--enable-features=NetworkService,NetworkServiceInProcess",
                "--type=crashpad-handler", "--enable-automation", "--disable-xss-auditor"
              )
      )
    ) or

    /* MS Edge Related Processes */
    (
      process.name : (
        "msedge.exe", "MicrosoftEdgeUpdate.exe", "identity_helper.exe", "msedgewebview2.exe",
        "MicrosoftEdgeWebview2Setup.exe", "MicrosoftEdge_X*.exe", "msedge_proxy.exe",
        "MicrosoftEdgeUpdateCore.exe", "MicrosoftEdgeUpdateBroker.exe", "MicrosoftEdgeUpdateSetup_X*.exe",
        "MicrosoftEdgeUpdateComRegisterShell64.exe", "msedgerecovery.exe", "MicrosoftEdgeUpdateSetup.exe"
      ) and
      not (process.code_signature.subject_name == "Microsoft Corporation" and process.code_signature.trusted == true) and
      not (
        process.name : "msedgewebview2.exe" and
        process.code_signature.subject_name in ("Bromium, Inc.", "Amazon.com Services LLC", "Code Systems Corporation") and
        process.code_signature.trusted == true
      ) and
      not process.executable : "?:\\Program Files (x86)\\Microsoft\\EdgeUpdate\\MicrosoftEdgeUpdate.exe"
    ) or

    /* Brave Related Processes */
    (
      process.name : (
        "brave.exe", "BraveUpdate.exe", "BraveCrashHandler64.exe", "BraveCrashHandler.exe",
        "BraveUpdateOnDemand.exe", "brave_vpn_helper.exe", "BraveUpdateSetup*.exe",
        "BraveUpdateComRegisterShell64.exe"
      ) and
      not (process.code_signature.subject_name in ("Brave Software, Inc.", "Google Inc") and process.code_signature.trusted == true)
    ) or

    /* Firefox Related Processes */
    (
      process.name : (
        "firefox.exe", "pingsender.exe", "default-browser-agent.exe", "maintenanceservice.exe",
        "plugin-container.exe", "maintenanceservice_tmp.exe", "maintenanceservice_installer.exe",
        "minidump-analyzer.exe"
      ) and
      not (process.code_signature.subject_name == "Mozilla Corporation" and process.code_signature.trusted == true) and
      not (
        process.name : "default-browser-agent.exe" and
        process.code_signature.subject_name in ("WATERFOX LIMITED") and process.code_signature.trusted == true
      ) and
      not process.hash.sha256 == "ddc7a6c3a4b50d23daffe8e364c575fd7df9af9711b14d153b09553ddd3670a0" and
      not process.executable : "?:\\Users\\*\\AppData\\Local\\ms-playwright\\firefox-*\\firefox\\firefox.exe"
    ) or

    /* Island Related Processes */
    (
      process.name : (
        "Island.exe", "IslandUpdate.exe", "IslandCrashHandler.exe", "IslandCrashHandler64.exe",
        "IslandUpdateBroker.exe", "IslandUpdateOnDemand.exe", "IslandUpdateComRegisterShell64.exe",
        "IslandUpdateSetup.exe"
      ) and
      not (process.code_signature.subject_name == "Island Technology Inc." and process.code_signature.trusted == true)
    ) or

    /* Opera Related Processes */
    (
      process.name : ("opera.exe", "opera_*.exe", "browser_assistant.exe") and
      not (process.code_signature.subject_name in ("Opera Norway AS", "Opera Software AS") and process.code_signature.trusted == true)
    ) or

    /* Whale Related Processes */
    (
      process.name : ("whale.exe", "whale_update.exe", "wusvc.exe") and
      not (process.code_signature.subject_name == "NAVER Corp." and process.code_signature.trusted == true)
    ) or

    /* Chromium-based Browsers processes */
    (
      process.name : ("chrmstp.exe", "notification_helper.exe", "elevation_service.exe") and
      not (
        process.code_signature.subject_name in (
          "Island Technology Inc.",
          "Citrix Systems, Inc.",
          "Brave Software, Inc.",
          "Google LLC",
          "Google Inc",
          "Microsoft Corporation",
          "NAVER Corp.",
          "AVG Technologies USA, LLC",
          "Avast Software s.r.o.",
          "PIRIFORM SOFTWARE LIMITED",
          "NortonLifeLock Inc.",
          "Opera Norway AS"
        ) and process.code_signature.trusted == true
      )
    )
  )

// Title: defense_evasion_masquerading_unusual_exe_file_extension.toml
// Source: detection-rules::rules_building_block/defense_evasion_masquerading_unusual_exe_file_extension.toml
// Section: EQL Building Block
// Rule Name: Executable File with Unusual Extension
// Author: Elastic
// Description:
// Identifies the creation or modification of an executable file with an unexpected file extension. Attackers may attempt
// to evade detection by masquerading files using the file extension values used by image, audio, or document file types.
// Integration: endpoint
// Language: eql
// UUID: ecd4857b-5bac-455e-a7c9-a88b66e56a9e
// Type: eql

file where host.os.type == "windows" and event.action != "deletion" and

 /* MZ header or its common base64 equivalent TVqQ */
 file.Ext.header_bytes : ("4d5a*", "54567151*") and

 (
   /* common image file extensions */
   file.extension : ("jpg", "jpeg", "emf", "tiff", "gif", "png", "bmp", "fpx", "eps", "svg", "inf") or

   /* common audio and video file extensions */
   file.extension : ("mp3", "wav", "avi", "mpeg", "flv", "wma", "wmv", "mov", "mp4", "3gp") or

   /* common document file extensions */
   file.extension : ("txt", "pdf", "doc", "docx", "rtf", "ppt", "pptx", "xls", "xlsx", "hwp", "html")
  ) and
  not process.pid == 4 and
  not process.executable : "?:\\Program Files (x86)\\Trend Micro\\Client Server Security Agent\\Ntrtscan.exe"

// Title: defense_evasion_masquerading_vlc_dll.toml
// Source: detection-rules::rules_building_block/defense_evasion_masquerading_vlc_dll.toml
// Section: EQL Building Block
// Rule Name: Potential Masquerading as VLC DLL
// Author: Elastic
// Description:
// Identifies instances of VLC-related DLLs which are not signed by the original developer. Attackers may name their
// payload as legitimate applications to blend into the environment, or embedding its malicious code within legitimate
// applications to deceive machine learning algorithms by incorporating authentic and benign code.
// Integration: endpoint
// Language: eql
// UUID: 4494c14f-5ff8-4ed2-8e99-bf816a1642fc
// Type: eql

library where host.os.type == "windows" and event.action == "load" and
  dll.name : ("libvlc.dll", "libvlccore.dll", "axvlc.dll") and
  not (
    dll.code_signature.subject_name : ("VideoLAN", "716F2E5E-A03A-486B-BC67-9B18474B9D51")
    and dll.code_signature.trusted == true
  )

// Title: defense_evasion_masquerading_windows_system32_exe.toml
// Source: detection-rules::rules_building_block/defense_evasion_masquerading_windows_system32_exe.toml
// Section: EQL Building Block
// Rule Name: Potential Masquerading as System32 Executable
// Author: Elastic
// Description:
// Identifies suspicious instances of default system32 executables, either unsigned or signed with non-MS certificates.
// This could indicate the attempt to masquerade as system executables or backdoored and resigned legitimate executables.
// Integration: endpoint
// Language: eql
// UUID: 79ce2c96-72f7-44f9-88ef-60fa1ac2ce47
// Type: eql

process where host.os.type == "windows" and event.type == "start" and 
