// Title: defense_evasion_msdt_suspicious_diagcab.toml
// Source: detection-rules::rules_building_block/defense_evasion_msdt_suspicious_diagcab.toml
// Section: EQL Building Block
// Rule Name: Suspicious Troubleshooting Pack Cabinet Execution
// Author: Elastic
// Description:
// Identifies the execution of the Microsoft Diagnostic Wizard to open a diagcab file from a suspicious path and with an
// unusual parent process. This may indicate an attempt to execute malicious Troubleshooting Pack Cabinet files.
// Integration: endpoint, windows, system
// Language: eql
// UUID: 808291d3-e918-4a3a-86cd-73052a0c9bdc
// Type: eql

process where host.os.type == "windows" and event.action == "start" and
  (process.name : "msdt.exe" or ?process.pe.original_file_name == "msdt.exe") and process.args : "/cab" and
  process.parent.name : (
    "firefox.exe", "chrome.exe", "msedge.exe", "explorer.exe", "brave.exe", "whale.exe", "browser.exe",
    "dragon.exe", "vivaldi.exe", "opera.exe", "iexplore", "firefox.exe", "waterfox.exe", "iexplore.exe",
    "winrar.exe", "winrar.exe", "7zFM.exe", "outlook.exe", "winword.exe", "excel.exe"
  ) and
  process.args : (
    "?:\\Users\\*",
    "\\\\*",
    "http*",
    "ftp://*"
  )

// Title: defense_evasion_msiexec_installsource_archive_file.toml
// Source: detection-rules::rules_building_block/defense_evasion_msiexec_installsource_archive_file.toml
// Section: EQL Building Block
// Rule Name: Windows Installer with Suspicious Properties
// Author: Elastic
// Description:
// Identifies the execution of an installer from an archive or with suspicious properties. Adversaries may abuse
// msiexec.exe to launch local or network accessible MSI files in an attempt to bypass application whitelisting.
// Integration: endpoint
// Language: eql
// UUID: 55f07d1b-25bc-4a0f-aa0c-05323c1319d0
// Type: eql

sequence by host.id with maxspan=1m
  [registry where host.os.type == "windows" and event.type == "change" and process.name : "msiexec.exe" and
   (
    (registry.value : "InstallSource" and
     registry.data.strings : ("?:\\Users\\*\\Temp\\Temp?_*.zip\\*",
                             "?:\\Users\\*\\*.7z\\*",
                             "?:\\Users\\*\\*.rar\\*")) or

    (registry.value : ("DisplayName", "ProductName") and registry.data.strings : "SetupTest")
    )]
  [process where host.os.type == "windows" and event.action == "start" and
    process.parent.name : "msiexec.exe" and
    not process.name : "msiexec.exe" and
    not (process.executable : ("?:\\Program Files (x86)\\*.exe", "?:\\Program Files\\*.exe") and process.code_signature.trusted == true)]

// Title: defense_evasion_outlook_suspicious_child.toml
// Source: detection-rules::rules_building_block/defense_evasion_outlook_suspicious_child.toml
// Section: EQL Building Block
// Rule Name: Suspicious Outlook Child Process
// Author: Elastic
// Description:
// Identifies suspicious child processes spawned by MS Outlook, which can indicate a potential masquerading or the
// exploitation of a vulnerability on the application causing it to execute code.
// Integration: endpoint
// Language: eql
// UUID: 6cf17149-a8e3-44ec-9ec9-fdc8535547a1
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.parent.name : "outlook.exe" and
  not (
    (
      process.executable : (
        "?:\\Program Files\\*",
        "?:\\Program Files (x86)\\*",
        "?:\\Windows\\System32\\WerFault.exe",
        "?:\\Windows\\SysWOW64\\WerFault.exe",
        "?:\\Windows\\system32\\wermgr.exe",
        "?:\\Users\\*\\AppData\\Local\\Microsoft\\Teams\\current\\Teams.exe",
        "?:\\Users\\*\\AppData\\Local\\Temp\\NewOutlookInstall\\NewOutlookInstaller.exe",
        "?:\\Users\\*\\AppData\\Local\\Google\\Chrome\\Application\\chrome.exe",
        "?:\\Users\\*\\AppData\\Local\\Island\\Island\\Application\\Island.exe",
        "?:\\Users\\*\\AppData\\Local\\Mozilla Firefox\\firefox.exe",
        "?:\\Users\\*\\AppData\\Roaming\\Zoom\\bin\\Zoom.exe",
        "?:\\Windows\\System32\\IME\\SHARED\\IMEWDBLD.EXE",
        "?:\\Windows\\System32\\spool\\drivers\\x64\\*",
        "?:\\Windows\\System32\\prevhost.exe",
        "?:\\Windows\\System32\\dwwin.exe",
        "?:\\Windows\\System32\\mspaint.exe",
        "?:\\Windows\\SysWOW64\\mspaint.exe",
        "?:\\Windows\\System32\\notepad.exe",
        "?:\\Windows\\SysWOW64\\notepad.exe",
        "?:\\Windows\\System32\\smartscreen.exe",
        "?:\\Windows\\explorer.exe",
        "?:\\Windows\\splwow64.exe"
      ) and process.code_signature.trusted == true  
    ) or
    (
      process.name : "rundll32.exe" and
      process.args : "*hpmsn???.dll,MonitorPrintJobStatus*"
    )
  )

// Title: defense_evasion_posh_obfuscation_proportion_special_chars.toml
// Source: detection-rules::rules_building_block/defense_evasion_posh_obfuscation_proportion_special_chars.toml
// Section: EQL Building Block
// Rule Name: Potential PowerShell Obfuscation via High Special Character Proportion
// Author: Elastic
// Description:
// Identifies PowerShell script block content with an unusually high proportion of non-alphanumeric characters, often
// produced by encoding, string mangling, or dynamic code generation. Attackers use special-character heavy obfuscation to
// conceal payloads and hinder static analysis and AMSI.
// Integration: windows
// Language: esql
// UUID: f9753455-8d55-4ad8-b70a-e07b6f18deea
// Type: esql

from logs-windows.powershell_operational* metadata _id, _version, _index
| where event.code == "4104"

// Filter out smaller scripts that are unlikely to implement obfuscation using the patterns we are looking for
| eval Esql.script_block_length = length(powershell.file.script_block_text)
| where Esql.script_block_length > 1000

// replace the patterns we are looking for with the 🔥 emoji to enable counting them
// The emoji is used because it's unlikely to appear in scripts and has a consistent character length of 1
// Excludes spaces, #, = and - as they are heavily used in scripts for formatting
| eval Esql.script_block_tmp = replace(powershell.file.script_block_text, """[^0-9A-Za-z\s#=-]""", "🔥")

// count how many patterns were detected by calculating the number of 🔥 characters inserted
| eval Esql.script_block_pattern_count = Esql.script_block_length - length(replace(Esql.script_block_tmp, "🔥", ""))

// Calculate the ratio of special characters to total length
| eval Esql.script_block_ratio = Esql.script_block_pattern_count::double / Esql.script_block_length::double

// keep the fields relevant to the query, although this is not needed as the alert is populated using _id
| keep
    Esql.script_block_pattern_count,
    Esql.script_block_length,
    Esql.script_block_ratio,
    Esql.script_block_tmp,
    powershell.file.*,
    file.path,
    file.directory,
    powershell.sequence,
    powershell.total,
    _id,
    _version,
    _index,
    host.name,
    host.id,
    agent.id,
    user.id

// Filter for scripts with high special character ratio
| where Esql.script_block_ratio > 0.35

// Exclude Noisy Patterns
| where not file.directory like "C:\\\\ProgramData\\\\Microsoft\\\\Windows Defender Advanced Threat Protection\\\\DataCollection\\\\*"
  // ESQL requires this condition, otherwise it only returns matches where file.directory exists.
  or file.directory IS NULL

// Title: defense_evasion_service_disabled_registry.toml
// Source: detection-rules::rules_building_block/defense_evasion_service_disabled_registry.toml
// Section: EQL Building Block
// Rule Name: Service Disabled via Registry Modification
// Author: Elastic
// Description:
// Identifies attempts to modify services start settings using processes other than services.exe. Attackers may attempt to
// modify security and monitoring services to avoid detection or delay response.
// Integration: endpoint
// Language: eql
// UUID: 75dcb176-a575-4e33-a020-4a52aaa1b593
// Type: eql

registry where host.os.type == "windows" and event.type == "change" and
  registry.path : (
    "HKLM\\SYSTEM\\*ControlSet*\\Services\\*\\Start",
    "\\REGISTRY\\MACHINE\\SYSTEM\\*ControlSet*\\Services\\*\\Start"
  ) and registry.data.strings : ("3", "4") and
  not 
    (
      process.name : "services.exe" and user.id : "S-1-5-18"
    )
  and not registry.path : "HKLM\\SYSTEM\\ControlSet001\\Services\\MrxSmb10\\Start"

// Title: defense_evasion_service_path_registry.toml
// Source: detection-rules::rules_building_block/defense_evasion_service_path_registry.toml
// Section: EQL Building Block
// Rule Name: Service Path Modification
// Author: Elastic
// Description:
// Identifies attempts to modify a service path by an unusual process. Attackers may attempt to modify existing services
// for persistence or privilege escalation.
// Integration: endpoint, windows
// Language: eql
// UUID: f243fe39-83a4-46f3-a3b6-707557a102df
// Type: eql

registry where host.os.type == "windows" and event.type == "change" and
  registry.path : (
    "HKLM\\SYSTEM\\*ControlSet*\\Services\\*\\ImagePath",
    "\\REGISTRY\\MACHINE\\SYSTEM\\*ControlSet*\\Services\\*\\ImagePath"
  ) and not (
    process.executable : (
      "?:\\Program Files\\*.exe",
      "?:\\Program Files (x86)\\*.exe",
      "?:\\Windows\\System32\\services.exe",
      "?:\\Windows\\WinSxS\\*"
    )
  )

// Title: defense_evasion_services_exe_path.toml
// Source: detection-rules::rules_building_block/defense_evasion_services_exe_path.toml
// Section: EQL Building Block
// Rule Name: Service Path Modification via sc.exe
