// Title: discovery_ec2_multi_region_describe_instances.toml
// Source: detection-rules::rules_building_block/discovery_ec2_multi_region_describe_instances.toml
// Section: EQL Building Block
// Rule Name: AWS EC2 Multi-Region DescribeInstances API Calls
// Author: Elastic
// Description:
// Identifies when a single AWS resource is making `DescribeInstances` API calls in more than 10 regions within a 30-second
// window. This could indicate a potential threat actor attempting to discover the AWS infrastructure across multiple
// regions using compromised credentials or a compromised instance. Adversaries may use this information to identify
// potential targets for further exploitation or to gain a better understanding of the target's infrastructure.
// Integration: aws
// Language: esql
// UUID: 393ef120-63d1-11ef-8e38-f661ea17fbce
// Type: esql

from logs-aws.cloudtrail-* metadata _id, _version, _index

// filter for DescribeInstances API calls
| where event.dataset == "aws.cloudtrail"
  and event.provider == "ec2.amazonaws.com"
  and event.action == "DescribeInstances"

// truncate the timestamp to a 30-second window
| eval Esql.time_window_date_trunc = date_trunc(30 seconds, @timestamp)

// keep only the relevant raw fields
| keep 
    Esql.time_window_date_trunc, 
    aws.cloudtrail.user_identity.arn, 
    cloud.region, 
    cloud.account.id,
    aws.cloudtrail.user_identity.access_key_id,
    aws.cloudtrail.user_identity.type,
    user_agent.original,
    source.as.organization.name,
    source.ip,
    @timestamp,
    data_stream.namespace    

// count the number of unique regions and total API calls within the 30-second window
| stats
    Esql.cloud_region_count_distinct = count_distinct(cloud.region),
    Esql.event_count = count(*),
    Esql.event_timestamp_values = VALUES(@timestamp),
    Esql.aws_cloudtrail_user_identity_type_values = VALUES(aws.cloudtrail.user_identity.type),
    Esql.aws_cloudtrail_user_identity_access_key_id_values = VALUES(aws.cloudtrail.user_identity.access_key_id),
    Esql.source_ip_values = VALUES(source.ip),
    Esql.user_agent_original_values = VALUES(user_agent.original),
    Esql.source_as_organization_name_values = VALUES(source.as.organization.name),
    Esql.cloud_account_id_values = VALUES(cloud.account.id),
    Esql.cloud_region_values = VALUES(cloud.region),
    Esql.data_stream_namespace_values = VALUES(data_stream.namespace)
  by Esql.time_window_date_trunc, aws.cloudtrail.user_identity.arn

// filter for resources making DescribeInstances API calls in more than 10 regions within the 30-second window
| where Esql.cloud_region_count_distinct >= 10 and Esql.event_count >= 10

// Title: discovery_files_dir_systeminfo_via_cmd.toml
// Source: detection-rules::rules_building_block/discovery_files_dir_systeminfo_via_cmd.toml
// Section: EQL Building Block
// Rule Name: System Information Discovery via Windows Command Shell
// Author: Elastic
// Description:
// Identifies the execution of discovery commands to enumerate system information, files, and folders using the Windows
// Command Shell.
// Integration: endpoint, windows, system
// Language: eql
// UUID: d68e95ad-1c82-4074-a12a-125fe10ac8ba
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.name : "cmd.exe" and process.args : "/c" and process.args : ("set", "dir") and
  not process.parent.executable : (
    "?:\\Program Files\\*",
    "?:\\Program Files (x86)\\*",
    "?:\\PROGRA~1\\*",
    "?:\\TeamCity\\jre\\bin\\java.exe"
  ) and
  not process.args : (
    "*\\db\\rabbit@*", "*/db/rabbit@*",
    "*rabbitmq/db/*", "*RabbitMQ\\db*"
  ) and
  not process.parent.args : "*C:\\Program Files (x86)\\Tanium\\Tanium Client\\TPython\\TPython.bat*"

// Title: discovery_generic_account_groups.toml
// Source: detection-rules::rules_building_block/discovery_generic_account_groups.toml
// Section: EQL Building Block
// Rule Name: Windows Account or Group Discovery
// Author: Elastic
// Description:
// This rule identifies the execution of commands that enumerates account or group information. Adversaries may use
// built-in applications to get a listing of local system or domain accounts and groups.
// Integration: endpoint
// Language: eql
// UUID: 089db1af-740d-4d84-9a5b-babd6de143b0
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
(
  (
   (
    (process.name : "net.exe" or process.pe.original_file_name == "net.exe") or
    (
     (process.name : "net1.exe" or process.pe.original_file_name == "net1.exe") and
     not process.parent.name : "net.exe"
    )
   ) and process.args : ("accounts", "group", "user", "localgroup") and not process.args : "/add"
  ) or
  (process.name:("dsquery.exe", "dsget.exe") and process.args:("*members*", "user")) or
  (process.name:"dsquery.exe" and process.args:"*filter*") or
  process.name:("quser.exe", "qwinsta.exe", "PsGetSID.exe", "PsLoggedOn.exe", "LogonSessions.exe", "whoami.exe") or
  (
    process.name: "cmd.exe" and
    (
      process.args : "echo" and process.args : (
        "%username%", "%userdomain%", "%userdnsdomain%",
        "%userdomain_roamingprofile%", "%userprofile%",
        "%homepath%", "%localappdata%", "%appdata%"
      ) or
      process.args : "set"
    )
  )
) and not process.parent.args: "C:\\Program Files (x86)\\Microsoft Intune Management Extension\\Content\\DetectionScripts\\*.ps1"
and not process.parent.name : "LTSVC.exe" and not user.id : "S-1-5-18"

// Title: discovery_generic_process_discovery.toml
// Source: detection-rules::rules_building_block/discovery_generic_process_discovery.toml
// Section: EQL Building Block
// Rule Name: Process Discovery Using Built-in Tools
// Author: Elastic
// Description:
// This rule identifies the execution of commands that can be used to enumerate running processes. Adversaries may
// enumerate processes to identify installed applications and security solutions.
// Integration: endpoint, windows, system
// Language: eql
// UUID: 4982ac3e-d0ee-4818-b95d-d9522d689259
// Type: eql

process where host.os.type == "windows" and event.type == "start" and process.args != null and 
  not user.id in ("S-1-5-18", "S-1-5-19", "S-1-5-20") and process.parent.executable != null and
  (
   process.name :("PsList.exe", "qprocess.exe") or

   (process.name : "powershell.exe" and process.args : ("*get-process*", "*Win32_Process*") and not process.parent.name in ("openaev-agent.exe", "cmd.exe", "Miro.exe", "Granola.exe", "Wispr Flow.exe")) or

   (process.name : "wmic.exe" and process.args : ("process", "*Win32_Process*") and not process.parent.name in ("Code.exe", "node.exe", "javaw.exe", "java.exe", "asus_framework.exe", "Evernote.exe", "RingCentral.exe", "Avaya Cloud.exe", "Arduino IDE.exe")) or

   (process.name : "tasklist.exe" and process.args_count == 1 and process.parent.args != "tasklist | findstr consent.exe") or

   (process.name : "query.exe" and process.args : ("process", "imagename*", "csv", "/fi"))
  ) and
  not process.working_directory like ("?:\\Program Files*", "D:\\*", "E:\\*") and
  not process.parent.executable like ("?:\\Program Files (x86)\\*.exe", "?:\\Program Files\\*.exe")

// Title: discovery_hosts_file_access.toml
// Source: detection-rules::rules_building_block/discovery_hosts_file_access.toml
// Section: EQL Building Block
// Rule Name: System Hosts File Access
// Author: Elastic
// Description:
// Identifies the use of built-in tools to read the contents of "/etc/hosts" on a local machine. Attackers may use this data
// to discover remote machines in an environment that may be used for Lateral Movement from the current system.
// Integration: endpoint, auditd_manager
// Language: eql
// UUID: f75f65cf-ed04-48df-a7ff-b02a8bfe636e
// Type: eql

process where event.type == "start" and event.action in ("exec", "exec_event", "executed", "process_started") and
process.name in ("vi", "nano", "cat", "more", "less", "vim", "vim.basic", "emacs") and process.args == "/etc/hosts" and
not ?process.working_directory in ("/opt/SolarWinds/Agent/bin/Plugins/SCM", "/opt/cohesityagent/software/crux/bin")

// Title: discovery_kubectl_configuration_discovery.toml
// Source: detection-rules::rules_building_block/discovery_kubectl_configuration_discovery.toml
// Section: EQL Building Block
// Rule Name: Kubectl Configuration Discovery
// Author: Elastic
// Description:
// This rule detects the execution of kubectl commands that are commonly used for configuration discovery in Kubernetes
// environments. It looks for process events where kubectl is executed with arguments that query configuration information,
// such as configmaps. In environments where kubectl is not expected to be used, this could indicate potential reconnaissance
// activity by an adversary.
// Integration: endpoint, auditd_manager, crowdstrike, cloud_defend
// Language: eql
// UUID: 98ac2919-f8b3-4d2d-b85b-e1c13ac0c68b
// Type: eql

process where host.os.type == "linux" and event.type == "start" and
event.action in ("exec", "exec_event", "executed", "process_started", "ProcessRollup2") and
process.name == "kubectl" and process.args in ("get", "describe") and process.args in ("configmap", "configmaps") and
not ?process.parent.args in (
  "/hooks/schedule_sync_configmap.sh", "/service-fabric/generate-support-bundle.sh", "/hooks/onstartup_sync_configmap.sh"
)

// Title: discovery_kubectl_workload_and_cluster_discovery.toml
// Source: detection-rules::rules_building_block/discovery_kubectl_workload_and_cluster_discovery.toml
// Section: EQL Building Block
// Rule Name: Kubectl Workload and Cluster Discovery
// Author: Elastic
// Description:
// This rule detects the execution of kubectl commands that are commonly used for workload and cluster
// discovery in Kubernetes environments. It looks for process events where kubectl is executed with
// arguments that query cluster information, such as namespaces, nodes, pods, deployments, and other
// resources. In environments where kubectl is not expected to be used, this could indicate potential
// reconnaissance activity by an adversary.
// Integration: endpoint, auditd_manager, crowdstrike, cloud_defend
// Language: eql
// UUID: 74e5241e-c1a1-4e70-844e-84ee3d73eb7d
// Type: eql

process where host.os.type == "linux" and event.type == "start" and
event.action in ("exec", "exec_event", "executed", "process_started", "ProcessRollup2") and
process.name == "kubectl" and (
  (process.args in ("cluster-info", "api-resources", "api-versions", "version")) or
  (process.args in ("get", "describe") and process.args in (
    "namespaces", "nodes", "pods", "pod", "deployments", "deployment",
    "replicasets", "statefulsets", "daemonsets", "services", "service",
    "ingress", "ingresses", "endpoints", "configmaps", "events", "svc",
    "roles", "rolebindings", "clusterroles", "clusterrolebindings"
    )
  )
)

// Title: discovery_net_share_discovery_winlog.toml
// Source: detection-rules::rules_building_block/discovery_net_share_discovery_winlog.toml
// Section: EQL Building Block
// Rule Name: Potential Network Share Discovery
// Author: Elastic
// Description:
// Adversaries may look for folders and drives shared on remote systems to identify sources of information to gather as a
// precursor for collection and identify potential systems of interest for Lateral Movement.
// Integration: windows, system
// Language: eql
// UUID: b2318c71-5959-469a-a3ce-3a0768e63b9c
// Type: eql

sequence by user.name, source.port, source.ip with maxspan=15s 
 [file where event.action == "network-share-object-access-checked" and 
  winlog.event_data.ShareName in ("\\\\*\\ADMIN$", "\\\\*\\C$") and 
  source.ip != null and source.ip != "0.0.0.0" and source.ip != "::1" and source.ip != "::" and source.ip != "127.0.0.1"]
 [file where event.action == "network-share-object-access-checked" and 
  winlog.event_data.ShareName in ("\\\\*\\ADMIN$", "\\\\*\\C$") and 
  source.ip != null and source.ip != "0.0.0.0" and source.ip != "::1" and source.ip != "::" and source.ip != "127.0.0.1"]

// Title: discovery_net_view.toml
// Source: detection-rules::rules_building_block/discovery_net_view.toml
// Section: EQL Building Block
// Rule Name: Windows Network Enumeration
// Author: Elastic
// Description:
// Identifies attempts to enumerate hosts in a network using the built-in Windows net.exe tool.
// Integration: endpoint, windows
// Language: eql
// UUID: 7b8bfc26-81d2-435e-965c-d722ee397ef1
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  ((process.name : "net.exe" or process.pe.original_file_name == "net.exe") or
   ((process.name : "net1.exe" or process.pe.original_file_name == "net1.exe") and
       not process.parent.name : "net.exe")) and
  (process.args : "view" or (process.args : "time" and process.args : "\\\\*")) and
  not process.command_line : "net  view \\\\localhost "


  /* expand when ancestry is available
  and not descendant of [process where event.type == "start" and process.name : "cmd.exe" and
                           ((process.parent.name : "userinit.exe") or
                            (process.parent.name : "gpscript.exe") or
                            (process.parent.name : "explorer.exe" and
                               process.args : "C:\\*\\Start Menu\\Programs\\Startup\\*.bat*"))]
  */

// Title: discovery_of_domain_groups.toml
// Source: detection-rules::rules_building_block/discovery_of_domain_groups.toml
// Section: EQL Building Block
// Rule Name: Discovery of Domain Groups
// Author: Elastic
// Description:
// Identifies the execution of Linux built-in commands related to account or group enumeration. Adversaries may use account
// and group information to orient themselves before deciding how to act.
// Integration: endpoint, auditd_manager, crowdstrike
// Language: eql
// UUID: b92d5eae-70bb-4b66-be27-f98ba9d0ccdc
// Type: eql

process where host.os.type == "linux" and event.type == "start" and event.action in ("exec", "exec_event", "executed", "process_started", "ProcessRollup2")
 and (
  process.name in ("ldapsearch", "dscacheutil") or (process.name == "dscl" and process.args : "*-list*")
)

// Title: discovery_post_exploitation_external_ip_lookup.toml
// Source: detection-rules::rules_building_block/discovery_post_exploitation_external_ip_lookup.toml
// Section: EQL Building Block
// Rule Name: External IP Lookup from Non-Browser Process
// Author: Elastic
// Description:
// Identifies domains commonly used by adversaries for post-exploitation IP lookups. It is common for adversaries to test
// for Internet access and acquire their external IP address after they have gained access to a system. Among others, this
// has been observed in campaigns leveraging the information stealer, Trickbot.
// Integration: endpoint
// Language: eql
// UUID: 1d72d014-e2ab-4707-b056-9b96abe7b511
// Type: eql

network where host.os.type == "windows" and network.protocol == "dns" and
    process.name != null and user.id not in ("S-1-5-19", "S-1-5-20") and
    event.action == "lookup_requested" and
    /* Add new external IP lookup services here */
    dns.question.name :
    (
        "*api.ipify.org",
        "*freegeoip.app",
        "*checkip.amazonaws.com",
        "*checkip.dyndns.org",
        "*freegeoip.app",
        "*icanhazip.com",
        "*ifconfig.*",
        "*ipecho.net",
        "*ipgeoapi.com",
        "*ipinfo.io",
        "*ip.anysrc.net",
        "*myexternalip.com",
        "*myipaddress.com",
        "*showipaddress.com",
        "*whatismyipaddress.com",
        "*wtfismyip.com",
        "*ipapi.co",
        "*ip-lookup.net",
        "*ipstack.com"
    ) and
    /* Insert noisy false positives here */
    not
    (
      (
        process.executable : (
            "?:\\Program Files\\*.exe",
            "?:\\Program Files (x86)\\*.exe",
            "?:\\Windows\\Prey\\versions\\*\\bin\\node.exe",
            "?:\\Windows\\System32\\WWAHost.exe",
            "?:\\Windows\\System32\\smartscreen.exe",
            "?:\\Windows\\System32\\MicrosoftEdgeCP.exe",
            "?:\\ProgramData\\Microsoft\\Windows Defender\\Platform\\*\\MsMpEng.exe",
            "?:\\Users\\*\\AppData\\Local\\Google\\Chrome\\Application\\chrome.exe",
            "?:\\Users\\*\\AppData\\Local\\Programs\\Fiddler\\Fiddler.exe",
            "?:\\Users\\*\\AppData\\Local\\Programs\\Microsoft VS Code\\Code.exe",
            "?:\\Users\\*\\AppData\\Local\\Microsoft\\OneDrive\\OneDrive.exe"
        ) and process.code_signature.trusted == true
      ) or
      (
        (process.name : "Evernote.exe" and process.code_signature.subject_name : "Evernote Corporation" and process.code_signature.trusted == true) or
        (process.name : "firefox.exe" and process.code_signature.subject_name : "Mozilla Corporation" and process.code_signature.trusted == true) or
        (process.name : "Loom.exe" and process.code_signature.subject_name : "Loom, Inc." and process.code_signature.trusted == true) or
        (process.name : "opera.exe" and process.code_signature.subject_name : "Opera Norway AS" and process.code_signature.trusted == true) or
        (process.name : "brave.exe" and process.code_signature.subject_name : "Brave Software, Inc." and process.code_signature.trusted == true) or
        (process.name : "vivaldi.exe" and process.code_signature.subject_name : "Vivaldi Technologies AS" and process.code_signature.trusted == true)
      )
    )

// Title: discovery_potential_memory_seeking_activity.toml
// Source: detection-rules::rules_building_block/discovery_potential_memory_seeking_activity.toml
// Section: EQL Building Block
// Rule Name: Potential Memory Seeking Activity
// Author: Elastic
// Description:
// Monitors for the execution of Unix utilities that may be leveraged as memory address seekers. Attackers may leverage
// built-in utilities to seek specific memory addresses, allowing for potential future manipulation/exploitation.
// Integration: endpoint
// Language: eql
// UUID: 035a6f21-4092-471d-9cda-9e379f459b1e
// Type: eql

process where host.os.type == "linux" and event.type == "start" and event.action in ("exec", "exec_event") and (
  (process.name == "tail" and process.args in ("-c", "--bytes")) or
  (process.name == "cmp" and process.args == "-i") or
  (process.name in ("hexdump", "xxd") and process.args == "-s") or
  (process.name == "dd" and process.args : ("skip*", "seek*"))
) and not (
  process.parent.args like ("/opt/error_monitor/error_monitor.sh", "printf*", "/sbin/dracut") or
  process.parent.name in ("acme.sh", "dracut", "leapp") or
  process.parent.executable like (
    "/bin/cagefs_enter", "/opt/nessus_agent/sbin/nessus-service", "/usr/libexec/platform-python*",
    "/usr/libexec/vdsm/vdsmd", "/usr/local/bin/docker-entrypoint.sh", "/usr/lib/module-init-tools/lsinitrd-quick",
    "/usr/bin/unmkinitramfs", "/usr/bin/lsinitramfs", "/opt/msp-agent/msp-agent-core.run",
    "/usr/local/cloudamize/bin/register.sh", "/usr/local/hestia/bin/v-log-action", "/usr/local/emps/bin/php"
  ) or
  process.parent.command_line like "sh*acme.sh*" or
  process.args like ("/var/tmp/dracut*", "/opt/bitdefender-security-tools/var/log/script_update.log") or
  ?process.working_directory like (
    "/usr/local/nutanix/ngt/python/bin", "/var/lib/waagent/*", "/opt/Tychon/Endpoint/bin",
    "/usr/local/cloudamize/bin", "/opt/sentinelone/bin"
  ) or
  process.command_line in ("tail -c 1", "tail -c 2") or
  (process.command_line == "dd ibs=18850 skip=1 count=1" and process.parent.args == "/opt/msp-agent/msp-agent-core.run")
)

// Title: discovery_remote_system_discovery_commands_windows.toml
