// Type: eql

process where host.os.type == "windows" and event.type == "start" and process.name : "at.exe" and process.args : "\\\\*"

// Title: lateral_movement_rdp_conn_unusual_process.toml
// Source: detection-rules::rules_building_block/lateral_movement_rdp_conn_unusual_process.toml
// Section: EQL Building Block
// Rule Name: Potential Outgoing RDP Connection by Unusual Process
// Author: Elastic
// Description:
// Adversaries may attempt to connect to a remote system over Windows Remote Desktop Protocol (RDP) to achieve lateral
// movement. Adversaries may avoid using the Microsoft Terminal Services Client (mstsc.exe) binary to establish an RDP
// connection to evade detection.
// Integration: endpoint
// Language: eql
// UUID: 8e39f54e-910b-4adb-a87e-494fbba5fb65
// Type: eql

network where host.os.type == "windows" and
  event.action == "connection_attempted" and destination.port == 3389 and
  destination.ip != "::1" and destination.ip != "127.0.0.1" and
  not (
    process.executable : (
      "?:\\Windows\\System32\\mstsc.exe",
      "?:\\Program Files (x86)\\mRemoteNG\\mRemoteNG.exe",
      "?:\\Program Files (x86)\\PRTG Network Monitor\\PRTG Probe.exe",
      "?:\\Program Files\\Azure Advanced Threat Protection Sensor\\*\\Microsoft.Tri.Sensor.exe",
      "?:\\Program Files (x86)\\Microsoft\\Remote Desktop Connection Manager\\RDCMan.exe",
      "?:\\Program Files\\SentinelOne\\Sentinel Agent*\\Ranger\\SentinelRanger.exe",
      "?:\\Program Files\\Devolutions\\Remote Desktop Manager\\RemoteDesktopManager.exe",
      "?:\\Program Files (x86)\\Devolutions\\Remote Desktop Manager\\RemoteDesktopManager.exe"
    ) and process.code_signature.trusted == true
  )

// Title: lateral_movement_unusual_process_sql_accounts.toml
// Source: detection-rules::rules_building_block/lateral_movement_unusual_process_sql_accounts.toml
// Section: EQL Building Block
// Rule Name: Unusual Process For MSSQL Service Accounts
// Author: Elastic
// Description:
// Identifies unusual process executions using MSSQL Service accounts, which can indicate the exploitation/compromise of
// SQL instances. Attackers may exploit exposed MSSQL instances for initial access or lateral movement.
// Integration: endpoint
// Language: eql
// UUID: e74d645b-fec6-431e-bf93-ca64a538e0de
// Type: eql

process where event.type == "start" and host.os.type == "windows" and
  user.name : (
    "SQLSERVERAGENT", "SQLAGENT$*",
    "MSSQLSERVER", "MSSQL$*",
    "MSSQLServerOLAPService",
    "ReportServer*", "MsDtsServer150",
    "MSSQLFDLauncher*",
    "SQLServer2005SQLBrowserUser$*",
    "SQLWriter", "winmgmt"
  ) and user.domain : "NT SERVICE" and
  not (
    (
      process.name : (
        "sqlceip.exe", "sqlservr.exe", "sqlagent.exe",
        "msmdsrv.exe", "ReportingServicesService.exe",
        "MsDtsSrvr.exe", "sqlbrowser.exe", "DTExec.exe",
        "SQLPS.exe", "fdhost.exe", "fdlauncher.exe",
        "SqlDumper.exe", "sqlsqm.exe", "DatabaseMail.exe",
        "ISServerExec.exe", "Microsoft.ReportingServices.Portal.WebHost.exe",
        "bcp.exe", "SQLCMD.exe", "DatabaseMail.exe"
      ) or
      process.executable : (
        "?:\\Windows\\System32\\wermgr.exe",
        "?:\\Windows\\System32\\conhost.exe",
        "?:\\Windows\\System32\\WerFault.exe"
      )
    ) and
    (
      process.code_signature.subject_name : ("Microsoft Corporation", "Microsoft Windows") and
      process.code_signature.trusted == true
    )
  ) and
  not (
    (process.name : "cmd.exe" and process.parent.name : "sqlservr.exe") or
    (process.name : "cmd.exe" and process.parent.name : "forfiles.exe" and process.command_line : "/c echo *")
  )

// Title: lateral_movement_wmic_remote.toml
// Source: detection-rules::rules_building_block/lateral_movement_wmic_remote.toml
// Section: EQL Building Block
// Rule Name: WMIC Remote Command
// Author: Elastic
// Description:
// Identifies the use of wmic.exe to run commands on remote hosts. While this can be used by administrators legitimately,
// attackers can abuse this built-in utility to achieve lateral movement.
// Integration: endpoint, windows, system
// Language: eql
// UUID: f59668de-caa0-4b84-94c1-3a1549e1e798
// Type: eql

process where host.os.type == "windows" and event.type == "start" and
  process.name : "WMIC.exe" and
  process.args : "*node:*" and
  process.args : ("call", "set", "get") and
  not process.args : ("*/node:localhost*", "*/node:\"127.0.0.1\"*", "/node:127.0.0.1")

