// Title: persistence_iam_instance_request_to_iam_service.toml
// Source: detection-rules::rules_building_block/persistence_iam_instance_request_to_iam_service.toml
// Section: EQL Building Block
// Rule Name: AWS EC2 Instance Interaction with IAM Service
// Author: Elastic
// Description:
// Identifies when an EC2 instance interacts with the AWS IAM service via an assumed role. This is uncommon behavior and
// could indicate an attacker using compromised credentials to further exploit an environment. For example, an assumed role
// could be used to create new users for persistence or add permissions for privilege escalation. An EC2 instance assumes a
// role using their EC2 ID as the session name. This rule looks for the pattern "i-" which is the beginning pattern for
// assumed role sessions started by an EC2 instance. This is a [building
// block](https://www.elastic.co/guide/en/security/current/building-block-rule.html) rule and does not generate alerts on
// its own. It is meant to be used for correlation with other rules to detect suspicious activity.
// Integration: aws
// Language: eql
// UUID: a44bcb58-5109-4870-a7c6-11f5fe7dd4b1
// Type: eql

any where event.dataset == "aws.cloudtrail"
    and event.provider == "iam.amazonaws.com"
    and aws.cloudtrail.user_identity.type == "AssumedRole"
    and stringContains(user.id, ":i-")
    and (
            startsWith(event.action, "Update")
            or startsWith(event.action, "Attach")
            or startsWith(event.action, "Detach")
            or startsWith(event.action, "Create")
            or startsWith(event.action, "Delete")
            or startsWith(event.action, "Add")
            or startsWith(event.action, "Remove")
            or startsWith(event.action, "Put")
            or startsWith(event.action, "Tag")
    )
    and not user_agent.original like~ ("*Terraform*", "*Pulumi*", "*Ansible*")

// Title: persistence_startup_folder_lnk.toml
// Source: detection-rules::rules_building_block/persistence_startup_folder_lnk.toml
// Section: EQL Building Block
// Rule Name: Shortcut File Written or Modified on Startup Folder
// Author: Elastic
// Description:
// Identifies shortcut files written to or modified in the startup folder. Adversaries may use this technique to maintain
// persistence.
// Integration: endpoint
// Language: eql
// UUID: ee53d67a-5f0c-423c-a53c-8084ae562b5c
// Type: eql

file where host.os.type == "windows" and event.type != "deletion" and file.extension == "lnk" and
  file.path : (
    "C:\\Users\\*\\AppData\\Roaming\\Microsoft\\Windows\\Start Menu\\Programs\\Startup\\*",
    "C:\\ProgramData\\Microsoft\\Windows\\Start Menu\\Programs\\StartUp\\*"
  ) and
  not (
    (process.name : "ONENOTE.EXE" and process.code_signature.status: "trusted" and file.name : "*OneNote.lnk") or
    (process.name : "OktaVerifySetup.exe" and process.code_signature.status: "trusted" and file.name : "Okta Verify.lnk") or
    (process.name : "OneLaunch.exe" and process.code_signature.status: "trusted" and file.name : "OneLaunch*.lnk") or
    (process.name : "APPServerClient.exe" and process.code_signature.status: "trusted" and file.name : "Parallels Client.lnk")
  )

// Title: persistence_web_server_sus_file_creation.toml
// Source: detection-rules::rules_building_block/persistence_web_server_sus_file_creation.toml
// Section: EQL Building Block
// Rule Name: Unusual File Creation by Web Server
// Author: Elastic
// Description:
// This rule detects unusual file creations from a web server parent process. Adversaries may attempt to create files from
// a web server parent process to establish persistence, execute malicious scripts, or exfiltrate data. ES|QL rules have
// limited fields available in its alert documents. Make sure to review the original documents to aid in the investigation
// of this alert.
// Integration: endpoint
// Language: esql
// UUID: 894b7cc9-040b-427c-aca5-36b40d3667bf
// Type: esql

from logs-endpoint.events.file-* metadata _id, _index, _version

// Ensure event.action values in a list are expanded
| mv_expand event.action 

| where
    host.os.type == "linux" and
    event.action == "creation" and (
        process.name in (
            "apache", "nginx", "apache2", "httpd", "lighttpd", "caddy", "mongrel_rails", "gunicorn",
            "uwsgi", "openresty", "cherokee", "h2o", "resin", "puma", "unicorn", "traefik", "tornado", "hypercorn",
            "daphne", "twistd", "yaws", "webfsd", "httpd.worker", "flask", "rails", "mongrel", "php-cgi",
            "php-fcgi", "php-cgi.cagefs", "catalina.sh", "hiawatha", "lswsctrl"
        ) or
        process.name like "php-fpm*" or
        user.name in ("apache", "www-data", "httpd", "nginx", "lighttpd", "tomcat", "tomcat8", "tomcat9") or
        user.id in ("33", "498", "48")
      )

| keep
    @timestamp,
    _id,
    _index,
    _version,
    host.os.type,
    event.action,
    user.name,
    user.id,
    process.name,
    process.executable,
    file.path,
    agent.id,
    host.name,
    event.dataset,
    data_stream.namespace

| stats
    Esql.event_count = count(),
    Esql.agent_id_count_distinct = count_distinct(agent.id),
    Esql.host_name_values = values(host.name),
    Esql.agent_id_values = values(agent.id),
    Esql.event_dataset_values = values(event.dataset),
    Esql.data_stream_namespace_values = values(data_stream.namespace)

  by process.executable, file.path

| where
    Esql.agent_id_count_distinct == 1 and
    Esql.event_count < 5
